/**
 * Debug Utility Tests - اختبارات أداة Debug
 * 
 * @version 1.0.0
 * @date 2026-03-17
 */

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { debug } from '@/app/utils/debug';
import { SecureFetchError } from '@/app/services/SecureAPIClient';

describe('Debug Utility', () => {
  let consoleSpy: {
    log: any;
    warn: any;
    error: any;
    info: any;
  };

  beforeEach(() => {
    // ✅ إنشاء Spies لمراقبة console
    consoleSpy = {
      log: vi.spyOn(console, 'log').mockImplementation(() => {}),
      warn: vi.spyOn(console, 'warn').mockImplementation(() => {}),
      error: vi.spyOn(console, 'error').mockImplementation(() => {}),
      info: vi.spyOn(console, 'info').mockImplementation(() => {}),
    };
  });

  afterEach(() => {
    // ✅ استعادة console الأصلي
    vi.restoreAllMocks();
  });

  describe('Debug Methods', () => {
    it('should have log method', () => {
      expect(debug.log).toBeDefined();
      expect(typeof debug.log).toBe('function');
    });

    it('should have warn method', () => {
      expect(debug.warn).toBeDefined();
      expect(typeof debug.warn).toBe('function');
    });

    it('should have error method', () => {
      expect(debug.error).toBeDefined();
      expect(typeof debug.error).toBe('function');
    });

    it('should have info method', () => {
      expect(debug.info).toBeDefined();
      expect(typeof debug.info).toBe('function');
    });

    it('should have time and timeEnd methods', () => {
      expect(debug.time).toBeDefined();
      expect(debug.timeEnd).toBeDefined();
      expect(typeof debug.time).toBe('function');
      expect(typeof debug.timeEnd).toBe('function');
    });
  });

  describe('Error Logging', () => {
    it('should always log errors (even in production)', () => {
      const testError = new Error('Test Error');
      debug.error('Error:', testError);

      // ✅ console.error يُستدعى دائماً
      expect(consoleSpy.error).toHaveBeenCalled();
    });

    it('should suppress benign secure fetch errors unless verbose console is enabled', () => {
      debug.error('[timelineEventsSupabase] جلب — استثناء:', new SecureFetchError('api_unavailable', 503, '', 'http://localhost/api'));
      expect(consoleSpy.error).not.toHaveBeenCalled();
    });
  });

  describe('Development Logging', () => {
    it('should call debug.log without throwing', () => {
      expect(() => {
        debug.log('Test message');
      }).not.toThrow();
    });

    it('should call debug.warn without throwing', () => {
      expect(() => {
        debug.warn('Test warning');
      }).not.toThrow();
    });

    it('should call debug.info without throwing', () => {
      expect(() => {
        debug.info('Test info');
      }).not.toThrow();
    });
  });

  describe('Performance Timing', () => {
    it('should handle time() without throwing', () => {
      expect(() => {
        debug.time('test-timer');
      }).not.toThrow();
    });

    it('should handle timeEnd() without throwing', () => {
      expect(() => {
        debug.time('test-timer');
        debug.timeEnd('test-timer');
      }).not.toThrow();
    });
  });
});

/**
 * Execution Workflow Integration Tests
 * Complete end-to-end tests for execution file management
 */

import { describe, it, expect, beforeEach, vi } from 'vitest';
import SecureStoreService from '@/app/services/SecureStoreService';

describe('Execution Workflow Integration', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    SecureStoreService.listKeysSync().forEach((k) => SecureStoreService.deleteItemSync(k));
  });

  describe('Complete Execution File Lifecycle', () => {
    it('should create, save, and retrieve execution file', async () => {
      // Step 1: Create execution file
      const newExecutionFile = {
        id: 'exec-2026-001',
        caseNo: '2026/123',
        executionType: 'مدني',
        court: 'تنفيذ الكرخ',
        creditor: {
          name: 'أحمد محمد علي',
          phone: '07901234567',
          isClient: true,
        },
        debtor: {
          name: 'خالد حسن جاسم',
          phone: '07907654321',
          isClient: false,
        },
        totalAmount: 5000000,
        debtType: 'قرض شخصي',
        createdAt: new Date().toISOString(),
      };

      // Step 2: Save to localStorage (simulating local save)
      const files = [newExecutionFile];
      SecureStoreService.setItemSync('lawyer-execution-files', JSON.stringify(files));

      // Step 3: Retrieve and verify
      const savedFiles = JSON.parse(
        SecureStoreService.getItemSync('lawyer-execution-files') || '[]'
      );

      expect(savedFiles).toHaveLength(1);
      expect(savedFiles[0].id).toBe('exec-2026-001');
      expect(savedFiles[0].caseNo).toBe('2026/123');
      expect(savedFiles[0].creditor.name).toBe('أحمد محمد علي');
    });

    it('should update execution file', async () => {
      // Setup: Create initial file
      const initialFile = {
        id: 'exec-001',
        caseNo: '2026/100',
        totalAmount: 5000000,
        status: 'active',
        createdAt: new Date().toISOString(),
      };

      SecureStoreService.setItemSync(
        'lawyer-execution-files',
        JSON.stringify([initialFile])
      );

      // Update: Modify file
      const files = JSON.parse(
        SecureStoreService.getItemSync('lawyer-execution-files') || '[]'
      );
      const updatedFiles = files.map((f: any) =>
        f.id === 'exec-001' ? { ...f, totalAmount: 7000000, status: 'updated' } : f
      );

      SecureStoreService.setItemSync(
        'lawyer-execution-files',
        JSON.stringify(updatedFiles)
      );

      // Verify
      const result = JSON.parse(
        SecureStoreService.getItemSync('lawyer-execution-files') || '[]'
      );

      expect(result[0].totalAmount).toBe(7000000);
      expect(result[0].status).toBe('updated');
    });

    it('should delete execution file (soft delete)', async () => {
      const file = {
        id: 'exec-delete',
        caseNo: '2026/999',
        status: 'active',
        deletedAt: null,
      };

      SecureStoreService.setItemSync('lawyer-execution-files', JSON.stringify([file]));

      // Soft delete
      const files = JSON.parse(
        SecureStoreService.getItemSync('lawyer-execution-files') || '[]'
      );
      const updatedFiles = files.map((f: any) =>
        f.id === 'exec-delete'
          ? { ...f, status: 'deleted', deletedAt: Date.now() }
          : f
      );

      SecureStoreService.setItemSync(
        'lawyer-execution-files',
        JSON.stringify(updatedFiles)
      );

      // Verify
      const result = JSON.parse(
        SecureStoreService.getItemSync('lawyer-execution-files') || '[]'
      );

      expect(result[0].status).toBe('deleted');
      expect(result[0].deletedAt).toBeGreaterThan(0);
    });
  });

  describe('Auction Process Flow', () => {
    it('should calculate auction details correctly', () => {
      const propertyValue = 50000000; // 50M IQD
      const auctionFeePercentage = 0.02; // 2%
      const courtFeePercentage = 0.01; // 1%

      const auctionFees = propertyValue * auctionFeePercentage;
      const courtFees = propertyValue * courtFeePercentage;
      const publishingFees = 200000; // Fixed 200K IQD
      const totalCosts = auctionFees + courtFees + publishingFees;
      const minimumBid = propertyValue * 0.75; // 75% of value

      expect(auctionFees).toBe(1000000);
      expect(courtFees).toBe(500000);
      expect(totalCosts).toBe(1700000);
      expect(minimumBid).toBe(37500000);
    });

    it('should track auction stages', () => {
      const auctionStages = [
        { stage: 'تقييم الملكية', completed: true, date: '2026-01-01' },
        { stage: 'نشر الإعلان', completed: true, date: '2026-01-15' },
        { stage: 'المزاد الأول', completed: true, date: '2026-02-01', result: 'فاشل' },
        { stage: 'المزاد الثاني', completed: true, date: '2026-02-15', result: 'ناجح' },
        { stage: 'تسجيل البيع', completed: false, date: null },
      ];

      const completedStages = auctionStages.filter(s => s.completed);
      const pendingStages = auctionStages.filter(s => !s.completed);

      expect(completedStages).toHaveLength(4);
      expect(pendingStages).toHaveLength(1);
    });
  });

  describe('Payment Tracking', () => {
    it('should track payment installments', () => {
      const totalDebt = 10000000; // 10M IQD
      const payments = [
        { date: '2026-01-01', amount: 2000000, method: 'نقدي' },
        { date: '2026-02-01', amount: 3000000, method: 'شيك' },
        { date: '2026-03-01', amount: 2500000, method: 'تحويل' },
      ];

      const totalPaid = payments.reduce((sum, p) => sum + p.amount, 0);
      const remaining = totalDebt - totalPaid;
      const paymentPercentage = (totalPaid / totalDebt) * 100;

      expect(totalPaid).toBe(7500000);
      expect(remaining).toBe(2500000);
      expect(paymentPercentage).toBe(75);
    });

    it('should calculate payment deadline status', () => {
      const now = new Date('2026-03-01').getTime();
      const paymentDeadline = new Date('2026-02-28').getTime();
      const daysOverdue = Math.floor((now - paymentDeadline) / (1000 * 60 * 60 * 24));

      expect(daysOverdue).toBe(1);
      expect(daysOverdue).toBeGreaterThan(0); // Overdue
    });
  });

  describe('Seizure Process', () => {
    it('should track seized assets', () => {
      const seizedAssets = [
        { id: '1', type: 'عقار', value: 50000000, status: 'محجوز' },
        { id: '2', type: 'سيارة', value: 15000000, status: 'محجوز' },
        { id: '3', type: 'حساب_بنكي', value: 5000000, status: 'محجوز' },
      ];

      const totalValue = seizedAssets.reduce((sum, a) => sum + a.value, 0);
      const activeSeizures = seizedAssets.filter(a => a.status === 'محجوز');

      expect(totalValue).toBe(70000000);
      expect(activeSeizures).toHaveLength(3);
    });

    it('should validate seizure coverage', () => {
      const totalDebt = 40000000; // 40M IQD
      const seizedValue = 70000000; // 70M IQD
      const coveragePercentage = (seizedValue / totalDebt) * 100;
      const isCovered = seizedValue >= totalDebt;

      expect(coveragePercentage).toBe(175);
      expect(isCovered).toBe(true);
    });
  });

  describe('Document Management', () => {
    it('should attach documents to execution file', () => {
      const executionFile = {
        id: 'exec-001',
        caseNo: '2026/100',
        documents: [
          { id: 'doc-1', name: 'حكم_محكمة.pdf', type: 'حكم', uploadDate: '2026-01-01' },
          { id: 'doc-2', name: 'صورة_الهوية.jpg', type: 'هوية', uploadDate: '2026-01-02' },
          { id: 'doc-3', name: 'سند_ملكية.pdf', type: 'سند', uploadDate: '2026-01-03' },
        ],
      };

      expect(executionFile.documents).toHaveLength(3);

      const judgmentDocs = executionFile.documents.filter(d => d.type === 'حكم');
      expect(judgmentDocs).toHaveLength(1);
    });
  });

  describe('Notes and History', () => {
    it('should track execution history', () => {
      const history = [
        { date: '2026-01-01', action: 'إنشاء الملف', user: 'المحامي أحمد' },
        { date: '2026-01-15', action: 'إضافة حجز', user: 'المحامي أحمد' },
        { date: '2026-02-01', action: 'مزاد أول', user: 'المحامي أحمد' },
        { date: '2026-02-15', action: 'مزاد ثاني', user: 'المحامي أحمد' },
      ];

      expect(history).toHaveLength(4);
      expect(history[0].action).toBe('إنشاء الملف');
      expect(history[history.length - 1].action).toBe('مزاد ثاني');
    });

    it('should add and retrieve notes', () => {
      const notes = [
        { id: '1', text: 'المدين متعاون', timestamp: '2026-01-01', pinned: false },
        { id: '2', text: 'موعد المزاد القادم', timestamp: '2026-01-15', pinned: true },
        { id: '3', text: 'تحديث العنوان', timestamp: '2026-02-01', pinned: false },
      ];

      const pinnedNotes = notes.filter(n => n.pinned);
      expect(pinnedNotes).toHaveLength(1);
      expect(pinnedNotes[0].text).toBe('موعد المزاد القادم');
    });
  });

  describe('Search and Filter', () => {
    it('should filter execution files by type', () => {
      const files = [
        { id: '1', executionType: 'مدني', court: 'الكرخ' },
        { id: '2', executionType: 'شرعي', court: 'الرصافة' },
        { id: '3', executionType: 'مدني', court: 'الكرخ' },
      ];

      const civilFiles = files.filter(f => f.executionType === 'مدني');
      const shariaFiles = files.filter(f => f.executionType === 'شرعي');

      expect(civilFiles).toHaveLength(2);
      expect(shariaFiles).toHaveLength(1);
    });

    it('should filter by court', () => {
      const files = [
        { id: '1', court: 'تنفيذ الكرخ' },
        { id: '2', court: 'تنفيذ الرصافة' },
        { id: '3', court: 'تنفيذ الكرخ' },
      ];

      const karkhFiles = files.filter(f => f.court === 'تنفيذ الكرخ');
      expect(karkhFiles).toHaveLength(2);
    });

    it('should search by case number', () => {
      const files = [
        { id: '1', caseNo: '2026/123' },
        { id: '2', caseNo: '2026/456' },
        { id: '3', caseNo: '2025/789' },
      ];

      const searchQuery = '2026';
      const results = files.filter(f => f.caseNo.includes(searchQuery));

      expect(results).toHaveLength(2);
    });
  });

  describe('Status Transitions', () => {
    it('should transition through execution stages', () => {
      const stages = [
        { name: 'تسجيل', status: 'completed', date: '2026-01-01' },
        { name: 'تبليغ', status: 'completed', date: '2026-01-15' },
        { name: 'حجز', status: 'in-progress', date: '2026-02-01' },
        { name: 'مزاد', status: 'pending', date: null },
        { name: 'توزيع', status: 'pending', date: null },
      ];

      const completedStages = stages.filter(s => s.status === 'completed');
      const currentStage = stages.find(s => s.status === 'in-progress');
      const pendingStages = stages.filter(s => s.status === 'pending');

      expect(completedStages).toHaveLength(2);
      expect(currentStage?.name).toBe('حجز');
      expect(pendingStages).toHaveLength(2);
    });
  });

  describe('Performance Metrics', () => {
    it('should calculate execution success rate', () => {
      const completedExecutions = 75;
      const totalExecutions = 100;
      const successRate = (completedExecutions / totalExecutions) * 100;

      expect(successRate).toBe(75);
    });

    it('should calculate average execution duration', () => {
      const durations = [30, 45, 60, 90, 120]; // days
      const averageDuration = durations.reduce((sum, d) => sum + d, 0) / durations.length;

      expect(averageDuration).toBe(69);
    });

    it('should track collection efficiency', () => {
      const totalDebt = 100000000;
      const totalCollected = 75000000;
      const collectionRate = (totalCollected / totalDebt) * 100;

      expect(collectionRate).toBe(75);
    });
  });
});

import { isAllowedIraqiLawName } from '@/app/constants/iraqiLawCatalog';
import { sanitizePayload } from '../../security/sanitizer.ts';
import { getSupabaseAdminClient } from '../../security/supabaseAdminClient.ts';
import { wifeJsonResponse } from '../../security/wifeSecurityHeaders.ts';
import { buildIraqiLawInsertRow } from '../lawsAdminUtils.ts';
import { requirePlatformAdmin } from '../lawsAdminAuth.ts';
import { unwrapWifeUser } from '../../security/bffAuth.ts';
import { devLocalInsertLaw, shouldUseDevLocalLawsStore } from '../devLawsLocalStore.ts';

export const runtime = 'nodejs';

function isRecord(value: unknown): value is Record<string, unknown> {
  return Boolean(value) && typeof value === 'object';
}

/**
 * WIFE + platform-admin — insert one law article (replaces Edge add-law).
 */
export async function POST(request: Request): Promise<Response> {
  try {
    const authGate = unwrapWifeUser(await requirePlatformAdmin(request));
    if ('response' in authGate) return authGate.response;
    const { userId } = authGate;

    let payload: unknown = null;
    try {
      payload = sanitizePayload(await request.json());
    } catch {
      payload = null;
    }
    if (!isRecord(payload)) {
      return wifeJsonResponse(400, { ok: false, error: 'Invalid payload' });
    }

    const law_name = typeof payload.law_name === 'string' ? payload.law_name.trim() : '';
    const article_number =
      payload.article_number === null || payload.article_number === undefined
        ? ''
        : String(payload.article_number).trim();
    const content = typeof payload.content === 'string' ? payload.content.trim() : '';

    if (!law_name) {
      return wifeJsonResponse(400, { ok: false, error: 'الحقل law_name مطلوب وغير فارغ.' });
    }
    if (!isAllowedIraqiLawName(law_name)) {
      return wifeJsonResponse(400, {
        ok: false,
        error: 'اسم القانون غير مسموح. استخدم أحد القوانين المعتمدة في النظام فقط.',
      });
    }
    if (!article_number) {
      return wifeJsonResponse(400, { ok: false, error: 'الحقل article_number مطلوب وغير فارغ.' });
    }
    if (!content) {
      return wifeJsonResponse(400, { ok: false, error: 'الحقل content مطلوب وغير فارغ.' });
    }

    const admin = getSupabaseAdminClient();
    if (!admin) {
      if (shouldUseDevLocalLawsStore()) {
        const record = await devLocalInsertLaw({ law_name, article_number, content });
        return wifeJsonResponse(200, {
          ok: true,
          message: 'تم حفظ المادة في ملف الحزمة المحلية داخل المشروع.',
          record: {
            id: record.id,
            law_name: record.law_name,
            article_number: record.article_number,
          },
        });
      }
      return wifeJsonResponse(503, {
        ok: false,
        error: 'قاعدة البيانات غير مهيأة على الخادم.',
        details: 'أضف مفتاح إدارة Supabase في ملف .env ثم أعد تشغيل npm run dev.',
      });
    }

    const { data, error } = await admin
      .from('iraqi_laws')
      .insert(buildIraqiLawInsertRow(law_name, article_number, content))
      .select('id, law_name, article_number')
      .single();

    if (error) {
      return wifeJsonResponse(500, {
        ok: false,
        error: 'فشل حفظ السجل في قاعدة البيانات.',
        details: error.message,
      });
    }

    return wifeJsonResponse(200, {
      ok: true,
      message: 'تم حفظ المادة بنجاح.',
      record: data,
    });
  } catch {
    return wifeJsonResponse(500, { ok: false, error: 'Internal laws add error' });
  }
}

import { isAllowedIraqiLawName } from '@/app/constants/iraqiLawCatalog';
import { sanitizePayload } from '../../security/sanitizer.ts';
import { getSupabaseAdminClient } from '../../security/supabaseAdminClient.ts';
import { wifeJsonResponse } from '../../security/wifeSecurityHeaders.ts';
import { requirePlatformAdmin } from '../lawsAdminAuth.ts';
import { unwrapWifeUser } from '../../security/bffAuth.ts';
import { clearIraqiLaws, parseOptionalArticleBound } from '../lawsAdminUtils.ts';
import {
  devLocalClearLaws,
  shouldUseDevLocalLawsStore,
} from '../devLawsLocalStore.ts';

export const runtime = 'nodejs';

function isRecord(value: unknown): value is Record<string, unknown> {
  return Boolean(value) && typeof value === 'object';
}

/**
 * WIFE + platform-admin — clear law articles (replaces Edge clear-laws).
 */
export async function POST(request: Request): Promise<Response> {
  try {
    const authGate = unwrapWifeUser(await requirePlatformAdmin(request));
    if ('response' in authGate) return authGate.response;
    const { userId } = authGate;

    let payload: unknown = null;
    try {
      payload = sanitizePayload(await request.json());
    } catch {
      payload = null;
    }
    if (!isRecord(payload)) {
      return wifeJsonResponse(400, { ok: false, error: 'Invalid payload' });
    }

    const lawName = typeof payload.law_name === 'string' ? payload.law_name.trim() : '';
    if (!lawName) {
      return wifeJsonResponse(400, {
        ok: false,
        error: 'law_name مطلوب لتحديد التبويب المستهدف للحذف.',
      });
    }
    if (!isAllowedIraqiLawName(lawName)) {
      return wifeJsonResponse(400, { ok: false, error: 'Law name is not in the allowed catalog.' });
    }

    const admin = getSupabaseAdminClient();
    if (!admin) {
      if (shouldUseDevLocalLawsStore()) {
        const result = await devLocalClearLaws({
          lawName,
          articleFrom: parseOptionalArticleBound(payload.article_from),
          articleTo: parseOptionalArticleBound(payload.article_to),
        });
        if (result.ok === false) {
          return wifeJsonResponse(400, { ok: false, error: result.error });
        }
        return wifeJsonResponse(200, {
          ok: true,
          message: result.message,
          deletedCount: result.deletedCount,
          article_from: result.article_from,
          article_to: result.article_to,
        });
      }
      return wifeJsonResponse(503, { ok: false, error: 'Database client not configured' });
    }

    const result = await clearIraqiLaws({
      admin,
      lawName,
      articleFrom: parseOptionalArticleBound(payload.article_from),
      articleTo: parseOptionalArticleBound(payload.article_to),
    });

    if (result.ok === false) {
      return wifeJsonResponse(400, { ok: false, error: result.error });
    }

    return wifeJsonResponse(200, {
      ok: true,
      message: result.message,
      deletedCount: result.deletedCount,
      article_from: result.article_from,
      article_to: result.article_to,
    });
  } catch {
    return wifeJsonResponse(500, { ok: false, error: 'Internal laws clear error' });
  }
}

import { isAllowedIraqiLawName } from '@/app/constants/iraqiLawCatalog';
import { sanitizePayload } from '../../security/sanitizer.ts';
import { getSupabaseAdminClient } from '../../security/supabaseAdminClient.ts';
import { wifeJsonResponse } from '../../security/wifeSecurityHeaders.ts';
import { buildIraqiLawInsertRow } from '../lawsAdminUtils.ts';
import { requirePlatformAdmin } from '../lawsAdminAuth.ts';
import { unwrapWifeUser } from '../../security/bffAuth.ts';
import { devLocalImportLawArticles, shouldUseDevLocalLawsStore } from '../devLawsLocalStore.ts';

export const runtime = 'nodejs';

const INSERT_CHUNK_SIZE = 50;

function isRecord(value: unknown): value is Record<string, unknown> {
  return Boolean(value) && typeof value === 'object';
}

function normalizeImportArticle(raw: unknown): { article_number: string; content: string } | null {
  if (!isRecord(raw)) return null;
  const article_number =
    raw.article_number === null || raw.article_number === undefined
      ? ''
      : String(raw.article_number).trim();
  const content = typeof raw.content === 'string' ? raw.content.trim() : '';
  if (!article_number || !content) return null;
  return { article_number, content };
}

/**
 * WIFE + platform-admin — bulk import law articles in one request.
 */
export async function POST(request: Request): Promise<Response> {
  try {
    const authGate = unwrapWifeUser(await requirePlatformAdmin(request));
    if ('response' in authGate) return authGate.response;
    const { userId } = authGate;

    let payload: unknown = null;
    try {
      payload = sanitizePayload(await request.json());
    } catch {
      payload = null;
    }
    if (!isRecord(payload)) {
      return wifeJsonResponse(400, { ok: false, error: 'Invalid payload' });
    }

    const law_name = typeof payload.law_name === 'string' ? payload.law_name.trim() : '';
    if (!law_name) {
      return wifeJsonResponse(400, { ok: false, error: 'الحقل law_name مطلوب وغير فارغ.' });
    }
    if (!isAllowedIraqiLawName(law_name)) {
      return wifeJsonResponse(400, {
        ok: false,
        error: 'اسم القانون غير مسموح. استخدم أحد القوانين المعتمدة في النظام فقط.',
      });
    }

    if (!Array.isArray(payload.articles) || payload.articles.length === 0) {
      return wifeJsonResponse(400, {
        ok: false,
        error: 'الحقل articles مطلوب ويجب أن يكون مصفوفة غير فارغة.',
      });
    }

    const rawCount = payload.articles.length;
    const articles: Array<{ article_number: string; content: string }> = [];
    const skipped: Array<{ index: number; reason: string }> = [];

    for (let i = 0; i < payload.articles.length; i++) {
      const normalized = normalizeImportArticle(payload.articles[i]);
      if (!normalized) {
        skipped.push({ index: i + 1, reason: 'article_number أو content غير صالح' });
        continue;
      }
      articles.push(normalized);
    }

    if (articles.length === 0) {
      return wifeJsonResponse(400, {
        ok: false,
        error: `لم يُقبل أي عنصر (${rawCount} في الطلب).`,
        rawCount,
        skipped,
      });
    }

    const admin = getSupabaseAdminClient();
    if (!admin) {
      if (shouldUseDevLocalLawsStore()) {
        const result = await devLocalImportLawArticles({ law_name, articles });
        return wifeJsonResponse(200, {
          ok: true,
          message: `تم حفظ ${result.imported} مادة في ملف الحزمة المحلية.`,
          imported: result.imported,
          rawCount,
          skipped: skipped.length,
          skippedDetails: skipped.slice(0, 5),
        });
      }
      return wifeJsonResponse(503, {
        ok: false,
        error: 'قاعدة البيانات غير مهيأة على الخادم.',
        details: 'أضف مفتاح إدارة Supabase في ملف .env ثم أعد تشغيل npm run dev.',
      });
    }

    let imported = 0;
    for (let i = 0; i < articles.length; i += INSERT_CHUNK_SIZE) {
      const chunk = articles.slice(i, i + INSERT_CHUNK_SIZE).map((row) =>
        buildIraqiLawInsertRow(law_name, row.article_number, row.content),
      );
      const { error } = await admin.from('iraqi_laws').insert(chunk);
      if (error) {
        return wifeJsonResponse(500, {
          ok: false,
          error: 'فشل حفظ دفعة المواد في قاعدة البيانات.',
          details: error.message,
          imported,
          rawCount,
        });
      }
      imported += chunk.length;
    }

    return wifeJsonResponse(200, {
      ok: true,
      message: `تم حفظ ${imported} مادة بنجاح.`,
      imported,
      rawCount,
      skipped: skipped.length,
      skippedDetails: skipped.slice(0, 5),
    });
  } catch {
    return wifeJsonResponse(500, { ok: false, error: 'Internal laws import-bundle error' });
  }
}

