                                        setActiveCivilLawTab(tab);
                                        setSuccess(null);
                                        setError(null);
                                    }}
                                    disabled={singleLoading || bulkLoading}
                                    className={cn(
                                        "rounded-lg px-3 py-2 text-xs font-bold transition",
                                        activeCivilLawTab === tab
                                            ? "bg-[#E6C673] text-[#05060D]"
                                            : "text-[#E6C673] hover:bg-[#E6C673]/10",
