                    </div>
                </div>

                <div className="grid grid-cols-1 gap-2 rounded-xl border border-[#E6C673]/20 bg-[#05060D]/70 p-1.5 sm:grid-cols-3">
                    <button
                        type="button"
                        onClick={() => {
                            setActiveTab("single");
                            setError(null);
                            setSuccess(null);
                        }}
                        disabled={singleLoading || bulkLoading || browseLoading}
                        className={cn(
                            "rounded-lg px-3 py-2 text-sm font-semibold transition",
                            activeTab === "single"
                                ? "bg-[#E6C673] text-[#05060D]"
                                : "text-[#E6C673] hover:bg-[#E6C673]/10",
                        )}
                    >
                        إدخال مادة مفردة
                    </button>
                    <button
                        type="button"
                        onClick={() => {
                            setActiveTab("bulk");
                            setError(null);
                            setSuccess(null);
                        }}
                        disabled={singleLoading || bulkLoading || browseLoading}
                        className={cn(
                            "rounded-lg px-3 py-2 text-sm font-semibold transition",
                            activeTab === "bulk"
                                ? "bg-[#E6C673] text-[#05060D]"
                                : "text-[#E6C673] hover:bg-[#E6C673]/10",
                        )}
                    >
                        إدخال جماعي (JSON)
                    </button>
                    <button
                        type="button"
                        onClick={() => {
                            setActiveTab("browse");
                            setError(null);
                            setSuccess(null);
                        }}
                        disabled={singleLoading || bulkLoading}
                        className={cn(
                            "rounded-lg px-3 py-2 text-sm font-semibold transition",
                            activeTab === "browse"
                                ? "bg-[#E6C673] text-[#05060D]"
                                : "text-[#E6C673] hover:bg-[#E6C673]/10",
                        )}
                    >
                        استعراض وتصفية
                    </button>
                </div>

                {activeTab === "single" && (
                    <>
                        <div>
                            <label
                                htmlFor="admin-law-name"
                                className="mb-1.5 block text-sm font-medium text-[#E6C673]/90"
                            >
                                اسم القانون
                            </label>
                            <input
                                id="admin-law-name"
                                type="text"
                                autoComplete="off"
                                placeholder="يُحدد تلقائياً حسب القسم المختار"
                                value={resolvedLawName}
                                onChange={() => void 0}
                                disabled
                                className="w-full rounded-xl border border-white/10 bg-[#05060D]/80 px-4 py-3 text-sm text-white outline-none ring-[#E6C673]/30 transition-[border-color,box-shadow] placeholder:text-gray-500 focus:border-[#E6C673]/45 focus:ring-2 disabled:opacity-60"
                            />
                        </div>

                        <div>
                            <label
                                htmlFor="admin-law-article"
                                className="mb-1.5 block text-sm font-medium text-[#E6C673]/90"
                            >
                                رقم المادة
                            </label>
                            <input
                                id="admin-law-article"
                                type="text"
                                autoComplete="off"
                                placeholder="مثال: المادة 9"
                                value={articleNumber}
                                onChange={(e) => {
                                    setArticleNumber(e.target.value);
                                    setSuccess(null);
                                    setError(null);
                                }}
                                disabled={singleLoading || bulkLoading}
                                className="w-full rounded-xl border border-white/10 bg-[#05060D]/80 px-4 py-3 text-sm text-white outline-none ring-[#E6C673]/30 transition-[border-color,box-shadow] placeholder:text-gray-500 focus:border-[#E6C673]/45 focus:ring-2 disabled:opacity-60"
                            />
                        </div>

                        <div>
                            <label
                                htmlFor="admin-law-content"
                                className="mb-1.5 block text-sm font-medium text-[#E6C673]/90"
                            >
                                النص الحرفي للمادة
                            </label>
                            <textarea
                                id="admin-law-content"
                                rows={12}
                                placeholder="الصق أو اكتب نص المادة كما ورد في المصدر الرسمي…"
                                value={content}
                                onChange={(e) => {
                                    setContent(e.target.value);
                                    setSuccess(null);
                                    setError(null);
                                }}
                                disabled={singleLoading || bulkLoading}
                                className="min-h-[220px] w-full resize-y rounded-xl border border-white/10 bg-[#05060D]/80 px-4 py-3 text-sm leading-relaxed text-white outline-none ring-[#E6C673]/30 transition-[border-color,box-shadow] placeholder:text-gray-500 focus:border-[#E6C673]/45 focus:ring-2 disabled:opacity-60"
                            />
                        </div>
                    </>
                )}

                {activeTab === "browse" && (
                    <div className="space-y-4 rounded-2xl border border-[#E6C673]/20 bg-[#05060D]/70 p-3">
                        <div className="flex flex-wrap items-center justify-between gap-2">
                            <p className="text-sm font-bold text-[#E6C673]">
                                التصفية الهرمية للمواد المحقونة
                            </p>
                            <button
                                type="button"
                                onClick={() => {
                                    hasLoadedBrowseRef.current = false;
                                    void loadBrowseArticles();
                                }}
                                disabled={browseLoading}
                                className="rounded-lg border border-white/15 px-3 py-1.5 text-xs font-bold text-white/80 hover:bg-white/5 disabled:opacity-60"
                            >
                                {browseLoading ? "جاري التحديث…" : "تحديث الجدول"}
                            </button>
                        </div>

                        {/* Primary Filter Bar — الأقسام العامة */}
                        <div className="grid grid-cols-1 gap-2 sm:grid-cols-2">
                            {LAW_STRUCTURE_SECTION_IDS.map((sectionId) => {
                                const section = LAW_STRUCTURE[sectionId];
                                return (
                                    <button
                                        key={sectionId}
                                        type="button"
                                        onClick={() => {
                                            setHierarchySectionId(sectionId);
                                            setHierarchyFilterId(null);
                                        }}
                                        className={cn(
                                            "rounded-lg border px-3 py-2 text-xs font-bold transition",
                                            hierarchySectionId === sectionId
                                                ? "border-[#E6C673] bg-[#E6C673] text-[#05060D]"
                                                : "border-white/10 text-[#E6C673] hover:bg-[#E6C673]/10",
                                        )}
                                    >
                                        {section.label}
                                    </button>
                                );
                            })}
                        </div>

                        {/* Secondary Filter Bar — أزرار النطاق */}
                        <div className="space-y-2 rounded-xl border border-white/10 bg-[#0A0F1C]/80 p-2">
                            <p className="text-xs font-semibold text-gray-400">
                                تصنيفات {activeHierarchySection.label}
                            </p>
                            <div className="flex flex-wrap gap-2">
                                {activeHierarchySection.filters.map((filter) => {
                                    const isActive = hierarchyFilterId === filter.id;
                                    const isPinned =
                                        pinnedFilterPath?.sectionId === hierarchySectionId &&
                                        pinnedFilterPath?.filterId === filter.id;
                                    return (
                                        <div
                                            key={filter.id}
                                            className={cn(
                                                "inline-flex items-center gap-1 rounded-lg border",
                                                isActive
                                                    ? "border-[#E6C673] bg-[#E6C673]/15"
                                                    : "border-white/10 bg-white/[0.03]",
                                            )}
                                        >
                                            <button
                                                type="button"
                                                onClick={() => setHierarchyFilterId(filter.id)}
                                                className={cn(
                                                    "px-3 py-2 text-xs font-bold transition",
                                                    isActive
                                                        ? "text-[#E6C673]"
                                                        : "text-white/80 hover:text-[#E6C673]",
                                                )}
                                            >
                                                {filter.label}
                                                <span className="mr-1 text-[10px] font-medium text-gray-400">
                                                    ({filter.from}–{filter.to === 9999 ? "∞" : filter.to})
                                                </span>
                                            </button>
                                            <button
                                                type="button"
                                                title={
                                                    isPinned
                                                        ? "إلغاء التثبيت"
                                                        : "تثبيت هذا النطاق"
                                                }
                                                onClick={(e) => {
                                                    e.stopPropagation();
                                                    if (isPinned) {
                                                        handleUnpinHierarchyFilter();
                                                    } else {
                                                        handlePinHierarchyFilter(
                                                            hierarchySectionId,
                                                            filter.id,
                                                        );
                                                    }
                                                }}
                                                className={cn(
                                                    "rounded-lg p-2 transition",
                                                    isPinned
                                                        ? "text-[#E6C673]"
                                                        : "text-white/40 hover:text-[#E6C673]",
                                                )}
                                            >
                                                <Pin
                                                    className={cn(
                                                        "h-3.5 w-3.5",
                                                        isPinned && "fill-current",
                                                    )}
                                                />
                                            </button>
                                        </div>
                                    );
                                })}
                            </div>
                            {pinnedFilterPath ? (
                                <p className="text-[11px] text-emerald-300/90">
                                    مثبت: {LAW_STRUCTURE[pinnedFilterPath.sectionId].label} —{" "}
                                    {LAW_STRUCTURE[pinnedFilterPath.sectionId].filters.find(
                                        (f) => f.id === pinnedFilterPath.filterId,
                                    )?.label ?? pinnedFilterPath.filterId}
                                </p>
                            ) : null}
                        </div>

                        {browseLoadError ? (
                            <p className="rounded-xl border border-red-500/40 bg-red-500/10 px-3 py-2 text-sm text-red-300">
                                {browseLoadError}
                            </p>
                        ) : null}

                        <div className="overflow-hidden rounded-xl border border-white/10">
                            <div className="flex items-center justify-between border-b border-white/10 bg-[#0A0F1C]/90 px-3 py-2">
                                <span className="text-xs font-bold text-white/80">
                                    {activeHierarchyFilter
                                        ? `المواد ${activeHierarchyFilter.from}–${
                                              activeHierarchyFilter.to === 9999
                                                  ? "∞"
                                                  : activeHierarchyFilter.to
                                          }`
                                        : "اختر نطاقاً لعرض المواد"}
                                </span>
                                <span className="text-xs text-gray-400">
                                    {hierarchyFilteredRows.length} مادة
                                </span>
                            </div>
                            {browseLoading ? (
                                <p className="px-4 py-6 text-center text-sm text-gray-400">
                                    جاري تحميل المواد…
                                </p>
                            ) : !activeHierarchyFilter ? (
                                <p className="px-4 py-6 text-center text-sm text-gray-400">
                                    اختر زر تصنيف خاص لعرض المواد ضمن النطاق العددي.
                                </p>
                            ) : visibleHierarchyRows.length === 0 ? (
                                <p className="px-4 py-6 text-center text-sm text-gray-400">
                                    لا توجد مواد في هذا النطاق للقسم المحدد.
                                </p>
                            ) : (
                                <div className="max-h-[420px] overflow-y-auto">
                                    <table className="w-full text-right text-sm">
                                        <thead className="sticky top-0 bg-[#0A0F1C] text-xs text-[#E6C673]/90">
                                            <tr>
                                                <th className="px-3 py-2 font-bold">رقم المادة</th>
                                                <th className="px-3 py-2 font-bold">النص</th>
                                            </tr>
                                        </thead>
                                        <tbody>
                                            {visibleHierarchyRows.map((row) => (
                                                <tr
                                                    key={row.id}
                                                    className="border-t border-white/5 hover:bg-white/[0.03]"
                                                >
                                                    <td className="whitespace-nowrap px-3 py-2 align-top font-bold text-[#E6C673]">
                                                        {row.articleNumber}
                                                    </td>
                                                    <td className="px-3 py-2 align-top text-xs leading-relaxed text-white/85">
                                                        {row.content.length > 220
                                                            ? `${row.content.slice(0, 220)}…`
                                                            : row.content}
                                                    </td>
                                                </tr>
                                            ))}
                                        </tbody>
                                    </table>
                                </div>
                            )}
                        </div>

                        {hierarchyFilteredRows.length > visibleHierarchyRows.length ? (
                            <div className="flex justify-center">
                                <button
                                    type="button"
                                    onClick={() =>
                                        setBrowseVisibleCount(
                                            (v) => v + BROWSE_TABLE_PAGE_SIZE,
                                        )
                                    }
                                    className="rounded-lg border border-[#E6C673]/30 px-4 py-2 text-xs font-bold text-[#E6C673] hover:bg-[#E6C673]/10"
                                >
                                    تحميل المزيد
                                </button>
                            </div>
                        ) : null}
                    </div>
                )}

                {activeTab === "bulk" && (
                    <>
                        <div>
                            <div className="mb-1.5 flex flex-wrap items-center justify-between gap-2">
                                <label
                                    htmlFor="admin-law-bulk-json"
                                    className="block text-sm font-medium text-[#E6C673]/90"
                                >
                                    إدخال جماعي بصيغة JSON
                                </label>
                                <div className="flex items-center gap-2">
                                    <input
                                        ref={bulkJsonFileInputRef}
                                        type="file"
                                        accept=".json,application/json"
                                        className="hidden"
                                        onChange={handleBulkJsonFileChange}
                                        disabled={singleLoading || bulkLoading}
                                    />
                                    <button
                                        type="button"
                                        onClick={() => bulkJsonFileInputRef.current?.click()}
                                        disabled={singleLoading || bulkLoading}
                                        className="rounded-lg border border-[#E6C673]/30 px-3 py-1.5 text-xs font-bold text-[#E6C673] hover:bg-[#E6C673]/10 disabled:opacity-60"
                                    >
                                        رفع ملف JSON
                                    </button>
                                    {bulkJsonFileName ? (
                                        <span className="text-xs text-white/60">{bulkJsonFileName}</span>
                                    ) : null}
                                </div>
                            </div>
                            <textarea
                                id="admin-law-bulk-json"
                                rows={14}
                                placeholder={`[\n  { \"المادة\": 1, \"النص\": \"...\" },\n  { \"article_number\": \"2\", \"content\": \"...\" },\n  { \"المادة\": 3, \"نص المادة\": \"...\" }\n]\n\nأو حزمة: { \"articles\": [ ... ] } أو { \"articles\": { \"1\": \"نص...\" } }\n\nlaw_name من القسم المختار — يُفضّل رفع الملف كاملاً بدل اللصق.`}
                                value={bulkJson}
                                onChange={(e) => {
                                    setBulkJson(e.target.value);
                                    setBulkJsonFileName(null);
                                    setSuccess(null);
                                    setError(null);
                                    setBulkErrorHint(null);
                                }}
                                disabled={singleLoading || bulkLoading}
                                className="min-h-[260px] w-full resize-y rounded-xl border border-white/10 bg-[#05060D]/80 px-4 py-3 font-mono text-sm leading-relaxed text-white outline-none ring-[#E6C673]/30 transition-[border-color,box-shadow] placeholder:text-gray-500 focus:border-[#E6C673]/45 focus:ring-2 disabled:opacity-60"
                            />
                            {bulkParseSummary && !bulkLoading ? (
                                <p
                                    className={cn(
                                        "mt-2 text-xs leading-relaxed",
                                        bulkParsePreview?.ok ? "text-emerald-300" : "text-amber-300",
                                    )}
                                    role="status"
                                >
                                    {bulkParseSummary}
                                </p>
                            ) : null}
                        </div>

                        {(bulkLoading || bulkProgress.processed > 0) && (
                            <div className="rounded-xl border border-[#E6C673]/25 bg-[#0B1120] p-3">
                                <p className="mb-2 text-sm text-[#E6C673]">
                                    تم رفع {bulkProgress.success} من {bulkProgress.total} صالح
                                    {bulkProgress.rawTotal > bulkProgress.total
                                        ? ` (الملف: ${bulkProgress.rawTotal}، تخطّي: ${bulkProgress.skipped})`
                                        : ""}
                                    {" "}— {bulkProgress.processed} معالجة، {bulkProgress.failed} فشل
                                </p>
                                <div className="h-2 w-full overflow-hidden rounded-full bg-white/10">
                                    <div
                                        className="h-full bg-gradient-to-l from-[#c4a85a] to-[#E6C673] transition-all"
                                        style={{
                                            width: `${
                                                bulkProgress.total > 0
                                                    ? (bulkProgress.processed /
                                                        bulkProgress.total) *
                                                        100
                                                    : 0
                                            }%`,
                                        }}
                                    />
                                </div>
                                {bulkErrorHint ? (
                                    <p className="mt-2 text-xs leading-relaxed text-red-300" role="alert">
                                        {bulkErrorHint}
                                    </p>
                                ) : null}
                            </div>
                        )}
                    </>
                )}

                {success && (
                    <div className="space-y-2">
                        <p
                            className="rounded-xl border border-emerald-500/35 bg-emerald-500/10 px-4 py-3 text-sm font-medium text-emerald-300"
                            role="status"
                        >
                            {success}
                        </p>
                    </div>
                )}

                {error && (
                    <p
                        className="rounded-xl border border-red-500/40 bg-red-500/10 px-4 py-3 text-sm font-medium text-red-300"
                        role="alert"
                    >
                        {error}
                    </p>
                )}

                {activeTab !== "browse" ? (
                <button
                    type="button"
                    onClick={activeTab === "single" ? handleSubmit : handleBulkSubmit}
                    disabled={singleLoading || bulkLoading || clearLoading}
                    className={cn(
                        "w-full rounded-xl py-3.5 text-sm font-bold transition-[opacity,transform,box-shadow] active:scale-[0.99]",
                        "bg-gradient-to-l from-[#c4a85a] to-[#E6C673] text-[#05060D]",
                        "shadow-[0_4px_24px_rgba(230,198,115,0.25)]",
                        "hover:opacity-95 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[#E6C673]",
                        (singleLoading || bulkLoading) && "cursor-not-allowed opacity-70",
                    )}
                >
                    {singleLoading || bulkLoading
                        ? activeTab === "single"
                            ? "جاري الحفظ…"
                            : "جاري الرفع الجماعي…"
                        : activeTab === "single"
                        ? "حفظ المادة"
                        : "بدء الرفع الجماعي"}
                </button>
                ) : null}

                {activeTab !== "browse" ? (
                <div className="grid grid-cols-2 gap-2">
                    <label className="flex flex-col gap-1 text-xs text-gray-400">
                        من مادة (اختياري)
                        <input
                            type="number"
                            min={1}
                            value={clearArticleFrom}
                            onChange={(e) => setClearArticleFrom(e.target.value)}
                            disabled={singleLoading || bulkLoading || clearLoading}
                            className="rounded-lg border border-white/10 bg-[#05060D]/80 px-3 py-2 text-sm text-white"
                            placeholder="1"
                        />
                    </label>
                    <label className="flex flex-col gap-1 text-xs text-gray-400">
                        إلى مادة (اختياري)
                        <input
                            type="number"
                            min={1}
                            value={clearArticleTo}
                            onChange={(e) => setClearArticleTo(e.target.value)}
                            disabled={singleLoading || bulkLoading || clearLoading}
                            className="rounded-lg border border-white/10 bg-[#05060D]/80 px-3 py-2 text-sm text-white"
                            placeholder="300"
                        />
                    </label>
                </div>
                ) : null}

                {activeTab !== "browse" ? (
                <button
                    type="button"
                    onClick={handleClearDatabase}
                    disabled={singleLoading || bulkLoading || clearLoading}
                    className={cn(
                        "w-full rounded-xl py-3 text-sm font-bold transition-[opacity,transform] active:scale-[0.99]",
                        "border border-red-500/50 bg-red-900/25 text-red-200 hover:bg-red-900/35",
                        "focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-red-400",
                        (singleLoading || bulkLoading || clearLoading) &&
                            "cursor-not-allowed opacity-70",
                    )}
                >
                    {clearLoading
                        ? "جاري تنظيف قاعدة البيانات…"
                        : clearArticleFrom.trim() && clearArticleTo.trim()
                        ? "حذف نطاق المواد المحدد"
                        : "حذف جميع المواد القانونية"}
                </button>
                ) : null}
            </div>
        </section>
    );
}

// @ts-nocheck
export type BulkLawInvokeRow = {
    law_name: string;
    article_number: string;
    content: string;
};

export type BulkLawParseResult =
    | {
          ok: true;
          rawCount: number;
          items: BulkLawInvokeRow[];
          skipped: Array<{ index: number; reason: string }>;
      }
    | { ok: false; error: string };

const ARTICLE_FIELD_KEYS = [
    'article_number',
    'articleNumber',
    'ArticleNumber',
    'article',
    'Article',
    'المادة',
    'الماده',
    'مادة',
    'رقم_المادة',
    'رقم المادة',
    'نص_المادة',
    'number',
    'num',
    'no',
    'رقم',
    'id',
    'key',
] as const;

const CONTENT_FIELD_KEYS = [
    'content',
    'text',
    'body',
    'النص',
    'النص الكامل',
    'نص',
    'نص المادة',
    'نص_المادة',
    'المحتوى',
    'محتوى',
    'description',
    'content_text',
    'full_text',
    'value',
    'paragraph',
] as const;

const BUNDLE_META_KEYS = new Set([
    'schemaVersion',
    'schema_version',
    'law_name',
    'lawName',
    'articles',
    'data',
    'law',
    'metadata',
    'meta',
]);

const NESTED_ARTICLE_CONTAINERS: readonly (readonly string[])[] = [
    ['articles'],
    ['data', 'articles'],
    ['law', 'articles'],
    ['payload', 'articles'],
    ['items'],
    ['rows'],
    ['records'],
    ['مواد'],
    ['قانون', 'مواد'],
];

/** يقبل article_number كنص أو رقم (مثل 1 أو "المادة 1"). */
export function normalizeBulkArticleNumber(raw: unknown): string {
    if (typeof raw === 'string') {
        const trimmed = raw.trim();
        if (!trimmed) return '';
        const match = trimmed.match(/(?:المادة|مادة|article)\s*[:#-]?\s*([0-9\u0660-\u0669]+)/i);
        if (match?.[1]) return match[1];
        return trimmed;
    }
    if (typeof raw === 'number' && Number.isFinite(raw)) {
        return String(Math.trunc(raw));
    }
    return '';
}

export function normalizeBulkContent(raw: unknown): string {
    if (typeof raw === 'string') return raw.trim();
    if (Array.isArray(raw)) {
        return raw
            .map((part) => normalizeBulkContent(part))
            .filter(Boolean)
            .join('\n');
    }
    if (raw && typeof raw === 'object') {
        const record = raw as Record<string, unknown>;
        for (const key of CONTENT_FIELD_KEYS) {
            const nested = normalizeBulkContent(record[key]);
            if (nested) return nested;
        }
    }
    return '';
}

function normalizeFieldKey(key: string): string {
    return key
        .trim()
        .toLowerCase()
        .replace(/[\s_\-]/g, '')
        .replace(/[أإآ]/g, 'ا')
        .replace(/ة/g, 'ه')
        .replace(/ى/g, 'ي');
}

function pickFirstRowField(row: Record<string, unknown>, keys: readonly string[]): unknown {
    for (const key of keys) {
        if (!Object.prototype.hasOwnProperty.call(row, key)) continue;
        const value = row[key];
        if (value !== undefined && value !== null) return value;
    }

    const normalizedTargets = new Set(keys.map((key) => normalizeFieldKey(key)));
    for (const [key, value] of Object.entries(row)) {
        if (value === undefined || value === null) continue;
        const normalizedKey = normalizeFieldKey(key);
        if (normalizedTargets.has(normalizedKey)) return value;
        if (
            normalizedKey.includes('ماده')
            || normalizedKey.includes('article')
            || normalizedKey.includes('رقمالماده')
        ) {
            if (typeof value === 'string' || typeof value === 'number') return value;
        }
        if (
            normalizedKey.includes('نص')
            || normalizedKey.includes('content')
            || normalizedKey.includes('text')
            || normalizedKey.includes('محتو')
        ) {
            return value;
        }
    }
    return undefined;
}

export function extractBulkArticleNumber(row: Record<string, unknown>): string {
    const direct = normalizeBulkArticleNumber(pickFirstRowField(row, ARTICLE_FIELD_KEYS));
    if (direct) return direct;

    const keys = Object.keys(row);
    if (keys.length === 1) {
        return normalizeBulkArticleNumber(keys[0]);
    }
    return '';
}

export function extractBulkContent(row: Record<string, unknown>): string {
    return normalizeBulkContent(pickFirstRowField(row, CONTENT_FIELD_KEYS));
}

function rowFromArticleMapEntry(key: string, value: unknown): Record<string, unknown> | null {
    if (typeof value === 'string') {
        return { article_number: key, content: value };
    }
    if (value && typeof value === 'object' && !Array.isArray(value)) {
        const row = value as Record<string, unknown>;
        if (!extractBulkArticleNumber(row)) {
            return { article_number: key, ...row };
        }
        return row;
    }
    return null;
}

function articlesObjectToRows(articlesObj: Record<string, unknown>): unknown[] {
    const rows: unknown[] = [];
    for (const [key, value] of Object.entries(articlesObj)) {
        const row = rowFromArticleMapEntry(key, value);
        if (row) rows.push(row);
    }
    return rows;
}

function digNestedArticles(node: unknown, pathIndex = 0): unknown[] | null {
    if (pathIndex >= NESTED_ARTICLE_CONTAINERS.length) return null;
    if (!node || typeof node !== 'object') return null;

    for (let i = pathIndex; i < NESTED_ARTICLE_CONTAINERS.length; i++) {
        const path = NESTED_ARTICLE_CONTAINERS[i];
        let current: unknown = node;
        let found = true;
        for (const segment of path) {
            if (!current || typeof current !== 'object' || Array.isArray(current)) {
                found = false;
                break;
            }
            current = (current as Record<string, unknown>)[segment];
        }
        if (!found || current === undefined || current === null) continue;
        if (Array.isArray(current)) return current;
        if (typeof current === 'object') {
            return articlesObjectToRows(current as Record<string, unknown>);
        }
    }
    return null;
}

/** يفكّ Array مباشر أو حزمة { articles: [...] } أو خريطة { "1": "نص" }. */
export function unwrapBulkLawJsonRows(parsed: unknown): unknown[] {
    if (Array.isArray(parsed)) return parsed;

    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
        return [];
    }

    const root = parsed as Record<string, unknown>;
    const nested = digNestedArticles(root);
    if (nested && nested.length > 0) return nested;

    if (root.articles && typeof root.articles === 'object' && !Array.isArray(root.articles)) {
        const fromArticlesObject = articlesObjectToRows(root.articles as Record<string, unknown>);
        if (fromArticlesObject.length > 0) return fromArticlesObject;
    }

    const mapKeys = Object.keys(root).filter((key) => !BUNDLE_META_KEYS.has(key));
    if (mapKeys.length === 0) return [];

    const rows: Record<string, unknown>[] = [];
    for (const key of mapKeys) {
        const row = rowFromArticleMapEntry(key, root[key]);
        if (row) rows.push(row);
    }
    return rows;
}

function describeBulkRowValidationFailure(
    index: number,
    lawName: string,
    articleNumber: string,
    bodyContent: string,
): string {
    const missing: string[] = [];
    if (!lawName) missing.push('اختيار القسم القانوني');
    if (!articleNumber) missing.push('article_number أو «المادة»');
    if (!bodyContent) missing.push('content أو «النص»');
    return `العنصر ${index + 1}: ${missing.join(' · ')}`;
}

export function parseBulkLawJsonInput(
    parsed: unknown,
    lawName: string,
): BulkLawParseResult {
    const trimmedLawName = String(lawName ?? '').trim();
    if (!trimmedLawName) {
        return { ok: false, error: 'اختر القسم القانوني قبل الرفع الجماعي.' };
    }

    const rawRows = unwrapBulkLawJsonRows(parsed);
    if (rawRows.length === 0) {
        return {
            ok: false,
            error:
                'أدخل مصفوفة JSON أو حزمة { "articles": [...] } تحتوي مادة واحدة على الأقل.',
        };
    }

    const items: BulkLawInvokeRow[] = [];
    const skipped: Array<{ index: number; reason: string }> = [];

    for (let i = 0; i < rawRows.length; i++) {
        const row = rawRows[i];
        if (!row || typeof row !== 'object' || Array.isArray(row)) {
            skipped.push({ index: i + 1, reason: 'ليس كائناً صالحاً' });
            continue;
        }

        const record = row as Record<string, unknown>;
        const article_number = extractBulkArticleNumber(record);
        const content = extractBulkContent(record);

        if (!article_number || !content) {
            skipped.push({
                index: i + 1,
                reason: describeBulkRowValidationFailure(
                    i,
                    trimmedLawName,
                    article_number,
                    content,
                ),
            });
            continue;
        }

        items.push({
            law_name: trimmedLawName,
            article_number,
            content,
        });
    }

    if (items.length === 0) {
        const firstSkip = skipped[0]?.reason ?? 'لا توجد مواد صالحة.';
        return {
            ok: false,
            error: `لم يُقبل أي عنصر (${rawRows.length} في الملف). ${firstSkip}`,
        };
    }

    return {
        ok: true,
        rawCount: rawRows.length,
        items,
        skipped,
    };
}

export function parseBulkLawJsonText(jsonText: string, lawName: string): BulkLawParseResult {
    const trimmed = String(jsonText ?? '').trim();
    if (!trimmed) {
        return { ok: false, error: 'الصق JSON أو ارفع ملف .json.' };
    }

    let parsed: unknown;
    try {
        parsed = JSON.parse(trimmed);
    } catch {
        return { ok: false, error: 'صيغة JSON غير صحيحة. تأكد من أن النص JSON صالح.' };
    }
    return parseBulkLawJsonInput(parsed, lawName);
}

export function summarizeBulkLawParse(result: BulkLawParseResult): string | null {
    if (!result.ok) return result.error;
    if (result.skipped.length === 0) {
        return `جاهز للرفع: ${result.items.length} مادة (${result.rawCount} في الملف).`;
    }
    return `جاهز للرفع: ${result.items.length} صالح من ${result.rawCount} في الملف — تخطّي ${result.skipped.length}.`;
}

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { createPortal } from 'react-dom';
import { motion, AnimatePresence } from 'motion/react';
import { X, Mic, Square, Sparkles, Play, Trash2 } from 'lucide-react';
import { SmartToast } from '@/app/components/ui/SmartToast';
import type { VoiceNoteSavePayload } from '@/app/components/lawyer/commandCenterTypes';
import {
    VAULT_SHEET,
    VAULT_SHEET_OVERLAY_VIEWPORT,
} from '@/app/components/lawyer/SmartVaultModal/vaultDustyRoseTheme';
import { HUB_TOPMOST_OVERLAY_Z_CLASS } from '@/app/components/lawyer/dashboard/hubOverlayStack';
import {
    createArabicTranscriptSession,
    isSpeechRecognitionSupported,
} from '@/app/services/voice/speechTranscription';
import {
    MAX_VOICE_DURATION_SEC,
    MIN_VOICE_DURATION_SEC,
    formatVoiceDuration,
} from '@/app/services/voice/voiceRecordingLimits';

interface VoiceRecorderModalProps {
    onClose: () => void;
    onSaveVoice?: (payload: VoiceNoteSavePayload) => void | Promise<void>;
}

/** فوق نوافذ الإضبارة (ملاحظات z-250 / محضر z-260) — مع الإبقاء على أنماط الـ vault */
const VOICE_RECORDER_OVERLAY =
    VAULT_SHEET_OVERLAY_VIEWPORT.replace(/z-\[\d+]/, HUB_TOPMOST_OVERLAY_Z_CLASS);

const GOLD = '#E6C673';
const VAULT_RECORDER_SHELL =
    `${VAULT_SHEET} relative w-full max-w-md overflow-hidden rounded-[22px] sm:rounded-[22px] ` +
    'border-[#B87333]/18 shadow-[0_24px_80px_rgba(0,0,0,0.52)]';
const VAULT_RECORDER_HEADER =
    'relative flex items-center justify-between border-b border-[#B87333]/14 px-5 py-4 ' +
    'bg-gradient-to-l from-[#132238] via-[#0E1B2E] to-[#0a1524]';
const VAULT_RECORDER_INNER =
    'rounded-2xl border border-[#D9CFC0]/16 bg-gradient-to-br from-[#15253a] via-[#132238] to-[#0E1B2E] ' +
    'shadow-[inset_0_1px_0_rgba(230,222,208,0.06)]';
const PEARL_BTN_GOLD =
    'flex h-14 w-full items-center justify-center gap-2.5 rounded-2xl font-bold text-sm transition-all ' +
    'bg-[#B87333]/18 border border-[#B87333]/35 text-[#E8E4DC] hover:bg-[#B87333]/26 active:scale-[0.985] disabled:opacity-60';
const PEARL_BTN_STOP =
    'flex h-14 w-full items-center justify-center gap-2.5 rounded-2xl font-bold text-sm transition-all ' +
    'border border-rose-400/38 bg-rose-500/12 text-rose-100 active:scale-[0.985] disabled:opacity-60 animate-pulse';

function pickRecorderMimeType(): string | undefined {
    if (typeof MediaRecorder === 'undefined' || typeof MediaRecorder.isTypeSupported !== 'function') {
        return undefined;
    }
    const candidates = ['audio/webm;codecs=opus', 'audio/webm', 'audio/ogg;codecs=opus', 'audio/mp4'];
    for (const candidate of candidates) {
        if (MediaRecorder.isTypeSupported(candidate)) return candidate;
    }
    return undefined;
}

function createMediaRecorder(stream: MediaStream): MediaRecorder {
    const mimeType = pickRecorderMimeType();
    if (mimeType) {
        try {
            return new MediaRecorder(stream, { mimeType });
        } catch {
            /* fallback below */
        }
    }
    return new MediaRecorder(stream);
}

export const VoiceRecorderModal = ({ onClose, onSaveVoice }: VoiceRecorderModalProps) => {
    const [isRecording, setIsRecording] = useState(false);
    const [isSaving, setIsSaving] = useState(false);
    const [result, setResult] = useState<string | null>(null);
    const [liveTranscript, setLiveTranscript] = useState('');
    const [recordingTime, setRecordingTime] = useState(0);
    const [audioUrl, setAudioUrl] = useState<string | null>(null);
    const [savedToNotepad, setSavedToNotepad] = useState(false);

    const mediaRecorderRef = useRef<MediaRecorder | null>(null);
    const chunksRef = useRef<Blob[]>([]);
    const streamRef = useRef<MediaStream | null>(null);
    const durationRef = useRef(0);
    const transcriptRef = useRef('');
    const transcriptSessionRef = useRef<ReturnType<typeof createArabicTranscriptSession>>(null);
    const mimeTypeRef = useRef('audio/webm');
    const stopRecordingRef = useRef<(() => void) | null>(null);

    const sttSupported = isSpeechRecognitionSupported();

    const resetRecording = useCallback(() => {
        transcriptSessionRef.current?.stop();
        transcriptSessionRef.current = null;
        setResult(null);
        setLiveTranscript('');
        transcriptRef.current = '';
        setAudioUrl((prev) => {
            if (prev) URL.revokeObjectURL(prev);
            return null;
        });
        setRecordingTime(0);
        durationRef.current = 0;
        setSavedToNotepad(false);
        if (mediaRecorderRef.current && mediaRecorderRef.current.state !== 'inactive') {
            try {
                mediaRecorderRef.current.stop();
            } catch {
                /* ignore */
            }
        }
        mediaRecorderRef.current = null;
        if (streamRef.current) {
            streamRef.current.getTracks().forEach((t) => t.stop());
            streamRef.current = null;
        }
        setIsRecording(false);
    }, []);

    const finalizeBlob = useCallback(
        async (blob: Blob) => {
            const durationSeconds = durationRef.current;
            if (durationSeconds < MIN_VOICE_DURATION_SEC) {
                SmartToast.info('التسجيل قصير جداً — حاول مجدداً');
                resetRecording();
                return;
            }

            if (blob.size === 0) {
                SmartToast.error('لم يُسجَّل صوت — تحقق من المايكروفون');
                resetRecording();
                return;
            }

            const url = URL.createObjectURL(blob);
            setAudioUrl(url);

            const transcript = (transcriptRef.current || transcriptSessionRef.current?.getTranscript() || '').trim();
            if (!onSaveVoice) {
                setSavedToNotepad(false);
                setResult(
                    transcript
                        ? transcript
                        : 'تم حفظ التسجيل محلياً — افتح المفكرة للاستماع.',
                );
                SmartToast.success('تم حفظ التسجيل الصوتي');
                return;
            }

            setIsSaving(true);
            try {
                await onSaveVoice({ blob, durationSeconds, transcript: transcript || undefined });
                setSavedToNotepad(true);
                setResult(
                    transcript
                        ? transcript
                        : 'تم حفظ التسجيل في المفكرة — يمكنك تشغيله من قائمة الملاحظات.',
                );
            } catch {
                SmartToast.error('تعذّر حفظ التسجيل في المفكرة');
                setSavedToNotepad(false);
            } finally {
                setIsSaving(false);
            }
        },
        [onSaveVoice, resetRecording],
    );

    const stopRecording = useCallback(() => {
        transcriptSessionRef.current?.stop();
        transcriptSessionRef.current = null;
        if (mediaRecorderRef.current && mediaRecorderRef.current.state !== 'inactive') {
            try {
                mediaRecorderRef.current.stop();
            } catch {
                /* ignore */
            }
        } else {
            setIsRecording(false);
        }
    }, []);

    stopRecordingRef.current = stopRecording;

    const startRecording = useCallback(async () => {
        if (typeof navigator === 'undefined' || !navigator.mediaDevices?.getUserMedia) {
            SmartToast.warning('التسجيل الصوتي غير مدعوم في هذا المتصفح');
            return;
        }
        if (typeof MediaRecorder === 'undefined') {
            SmartToast.warning('مسجّل الصوت غير مدعوم — جرّب Chrome أو Edge');
            return;
        }

        try {
            resetRecording();

            const stream = await navigator.mediaDevices.getUserMedia({
                audio: { echoCancellation: true, noiseSuppression: true },
            });
            streamRef.current = stream;
            chunksRef.current = [];
            transcriptRef.current = '';
            setLiveTranscript('');

            const recorder = createMediaRecorder(stream);
            mediaRecorderRef.current = recorder;
            mimeTypeRef.current = recorder.mimeType || pickRecorderMimeType() || 'audio/webm';

            recorder.ondataavailable = (e) => {
                if (e.data.size > 0) chunksRef.current.push(e.data);
            };

            recorder.onerror = () => {
                SmartToast.error('تعذّر إكمال التسجيل');
                resetRecording();
            };

            recorder.onstop = () => {
                stream.getTracks().forEach((t) => t.stop());
                streamRef.current = null;
                mediaRecorderRef.current = null;
                setIsRecording(false);
                const blob = new Blob(chunksRef.current, { type: mimeTypeRef.current });
                void finalizeBlob(blob);
            };

            recorder.start(500);
            setIsRecording(true);
            setRecordingTime(0);
            durationRef.current = 0;
            setResult(null);
            setSavedToNotepad(false);

            if (sttSupported) {
                window.setTimeout(() => {
                    if (!mediaRecorderRef.current || mediaRecorderRef.current.state !== 'recording') return;
                    transcriptSessionRef.current = createArabicTranscriptSession((text) => {
                        transcriptRef.current = text;
                        setLiveTranscript(text);
                    });
                    transcriptSessionRef.current?.start();
                }, 400);
            }
        } catch (err) {
            const name = err instanceof DOMException ? err.name : '';
            if (name === 'NotAllowedError' || name === 'PermissionDeniedError') {
                SmartToast.warning('يُرجى السماح بالمايكروفون من إعدادات المتصفح');
            } else if (name === 'NotFoundError') {
                SmartToast.warning('لم يُعثر على مايكروفون');
            } else {
                SmartToast.warning('تعذّر بدء التسجيل — تحقق من المايكروفون');
            }
            resetRecording();
        }
    }, [finalizeBlob, resetRecording, sttSupported]);

    useEffect(() => {
        let timer: ReturnType<typeof setInterval> | undefined;
        if (isRecording) {
            timer = setInterval(() => {
                setRecordingTime((t) => {
                    const next = t + 1;
                    durationRef.current = next;
                    if (next >= MAX_VOICE_DURATION_SEC) {
                        stopRecordingRef.current?.();
                    }
                    return next;
                });
            }, 1000);
        }
        return () => {
            if (timer) clearInterval(timer);
        };
    }, [isRecording]);

    useEffect(() => {
        document.body.style.overflow = 'hidden';
        return () => {
            document.body.style.overflow = '';
            transcriptSessionRef.current?.stop();
            if (streamRef.current) {
                streamRef.current.getTracks().forEach((t) => t.stop());
            }
            if (audioUrl) URL.revokeObjectURL(audioUrl);
        };
    }, [audioUrl]);

    const handlePrimaryAction = () => {
        if (isSaving) return;
        if (isRecording) {
            stopRecording();
            return;
        }
        if (savedToNotepad) {
            onClose();
            return;
        }
        if (result) {
            resetRecording();
            return;
        }
        void startRecording();
    };

    const requestClose = useCallback(() => {
        if (isSaving) return;
        if (isRecording) {
            stopRecording();
            return;
        }
        onClose();
    }, [isSaving, isRecording, stopRecording, onClose]);

    useEffect(() => {
        const onKeyDown = (e: KeyboardEvent) => {
            if (e.key === 'Escape') requestClose();
        };
        window.addEventListener('keydown', onKeyDown);
        return () => window.removeEventListener('keydown', onKeyDown);
    }, [requestClose]);

    const primaryBtnClass = isRecording ? PEARL_BTN_STOP : PEARL_BTN_GOLD;

    return createPortal(
        <div
            className={`${VOICE_RECORDER_OVERLAY} p-4`}
            dir="rtl"
            onClick={requestClose}
            role="presentation"
            data-testid="voice-recorder-overlay"
        >
            <motion.div
                initial={{ y: 20, opacity: 0 }}
                animate={{ y: 0, opacity: 1 }}
                exit={{ y: 20, opacity: 0 }}
                transition={{ duration: 0.2 }}
                className={`${VAULT_RECORDER_SHELL} font-['Tajawal','Cairo',sans-serif]`}
                onClick={(e) => e.stopPropagation()}
                role="dialog"
                aria-modal="true"
                aria-label="المسجل الذكي"
                data-testid="voice-recorder-modal"
            >
                <div className={VAULT_RECORDER_HEADER}>
                    <div className="flex items-center gap-3 min-w-0">
                        <div
                            className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl border border-[#B87333]/26 bg-[#132238] text-[#C4926A]"
                            style={{
                                boxShadow: 'inset 0 1px 0 rgba(230,222,208,0.05)',
                            }}
                        >
                            <Mic size={20} strokeWidth={1.75} />
                        </div>
                        <div className="min-w-0 text-right">
                            <h3 className="text-base font-bold tracking-tight text-[#F4F0E8]">المسجل الذكي</h3>
                            <p className="mt-0.5 text-[11px] font-medium text-[#C9BCA8]/55">
                                {sttSupported ? 'تسجيل + تحويل نصي (عربي)' : 'تسجيل صوتي — حتى 3 دقائق'}
                            </p>
                        </div>
                    </div>
                    <button
                        type="button"
                        onClick={requestClose}
                        data-testid="voice-recorder-close"
                        aria-label="إغلاق"
                        className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full border border-[#D9CFC0]/12 bg-[#132238]/85 text-[#C9BCA8]/70 hover:border-[#B87333]/24 hover:bg-[#132238] hover:text-[#F4F0E8] transition-colors"
                    >
                        <X size={18} />
                    </button>
                </div>

                <div className="space-y-4 bg-[#0E1B2E] p-5">
                    <AnimatePresence mode="wait">
                        {!isRecording && !result && (
                            <motion.p
                                key="idle"
                                initial={{ opacity: 0 }}
                                animate={{ opacity: 1 }}
                                exit={{ opacity: 0 }}
                                className="rounded-2xl border border-[#D9CFC0]/12 bg-[#132238]/72 px-4 py-3 text-center text-sm font-medium text-[#C9BCA8]/70"
                                data-testid="voice-recorder-idle-hint"
                            >
                                اضغط للتسجيل — الحد الأقصى {formatVoiceDuration(MAX_VOICE_DURATION_SEC)}
                            </motion.p>
                        )}

                        {isRecording && (
                            <motion.div
                                key="recording"
                                initial={{ opacity: 0 }}
                                animate={{ opacity: 1 }}
                                exit={{ opacity: 0 }}
                                className="py-2 text-center space-y-3"
                            >
                                <p
                                    className="text-3xl font-bold tabular-nums tracking-widest text-[#F4F0E8]"
                                    data-testid="voice-recorder-timer"
                                >
                                    {formatVoiceDuration(recordingTime)}
                                </p>
                                {liveTranscript ? (
                                    <div className={`${VAULT_RECORDER_INNER} max-h-28 overflow-y-auto p-3 text-right`}>
                                        <p className="mb-1 text-xs text-[#C4926A]">النص المباشر</p>
                                        <p className="text-sm leading-relaxed text-[#E8E4DC]">{liveTranscript}</p>
                                    </div>
                                ) : sttSupported ? (
                                    <p className="text-xs text-[#C9BCA8]/46">جاري الاستماع…</p>
                                ) : null}
                            </motion.div>
                        )}

                        {result && (
                            <motion.div
                                key="result"
                                initial={{ opacity: 0 }}
                                animate={{ opacity: 1 }}
                                exit={{ opacity: 0 }}
                                className="space-y-3"
                                data-testid="voice-recorder-result"
                            >
                                <div className={`${VAULT_RECORDER_INNER} border-[#B87333]/18 p-4 text-center`}>
                                    <Sparkles className="mx-auto mb-2 h-5 w-5 text-[#C4926A]" />
                                    <p className="text-xs font-bold text-[#C4926A]">
                                        {savedToNotepad ? 'تم الحفظ في المفكرة' : 'التسجيل الصوتي'}
                                    </p>
                                </div>
                                <div className={`${VAULT_RECORDER_INNER} max-h-36 overflow-y-auto p-4`}>
                                    <p className="whitespace-pre-wrap text-right text-sm font-medium leading-relaxed text-[#E8E4DC]">
                                        {result}
                                    </p>
                                </div>
                                {audioUrl ? (
                                    <div className={`${VAULT_RECORDER_INNER} flex items-center gap-3 p-3`}>
                                        <Play className="h-5 w-5 shrink-0 text-[#C4926A]" />
                                        <audio src={audioUrl} controls className="h-10 min-w-0 flex-1" />
                                    </div>
                                ) : null}
                                {!savedToNotepad ? (
                                    <button
                                        type="button"
                                        onClick={resetRecording}
                                        data-testid="voice-recorder-reset"
                                        className="flex w-full items-center justify-center gap-2 rounded-2xl border border-[#D9CFC0]/12 bg-[#132238]/55 py-2.5 text-xs font-bold text-[#C9BCA8] transition hover:border-[#B87333]/20 hover:bg-[#132238]/85"
                                    >
                                        <Trash2 size={15} />
                                        تسجيل جديد
                                    </button>
                                ) : null}
                            </motion.div>
                        )}
                    </AnimatePresence>

                    <button
                        type="button"
                        disabled={isSaving}
                        onClick={handlePrimaryAction}
                        data-testid={
                            isRecording
                                ? 'voice-recorder-stop'
                                : savedToNotepad
                                  ? 'voice-recorder-done'
                                  : result
                                    ? 'voice-recorder-new'
                                    : 'voice-recorder-start'
                        }
                        className={primaryBtnClass}
                    >
                        {isSaving ? (
                            'جاري الحفظ…'
                        ) : isRecording ? (
                            <>
                                <Square size={18} />
                                إيقاف التسجيل
                            </>
                        ) : savedToNotepad ? (
                            <>
                                <Sparkles size={18} />
                                تم — إغلاق
                            </>
                        ) : result ? (
                            <>
                                <Mic size={18} />
                                تسجيل جديد
                            </>
                        ) : (
                            <>
                                <Mic size={18} />
                                ابدأ التسجيل
                            </>
                        )}
                    </button>
                </div>
            </motion.div>
        </div>,
        document.body,
    );
};

import React, { Suspense, lazy, useEffect, useRef } from 'react';
import { createPortal, flushSync } from 'react-dom';
import { useBodyScrollLock } from '@/app/utils/bodyScrollLock';
import { X, Plus } from 'lucide-react';
import type { ArchivePortalProps } from '@/app/types/common';
import { warmExecutionWorkspace, warmLawsuitWorkspace } from '@/app/utils/lazyComponentsIntent';
import { ArchiveDossierToolbar } from './components/ArchiveDossierToolbar';
import { ArchivePortalTrashDialogs } from './components/ArchivePortalTrashDialogs';
import { ArchivePortalLifecycleBars } from './components/ArchivePortalLifecycleBars';
import { ArchivePortalTrashBulkBar } from './components/ArchivePortalTrashBulkBar';
import { ExecutionArchiveFileGrid } from './components/ExecutionArchiveFileGrid';
import { ExecutionArchiveToolbar } from './components/ExecutionArchiveToolbar';
import { ARCHIVE_ROYAL_GLASS_FAB } from './archiveToolbarStyles';
import type { LooseArchiveFile } from './types';

const LazyArchivePortalFileGrid = lazy(() =>
    import('./components/ArchivePortalFileGrid').then((m) => ({
        default: m.ArchivePortalFileGrid,
    })),
);

const LazyArchivePortalExecutionPreviewModal = lazy(() =>
    import('./components/ArchivePortalExecutionPreviewModal').then((m) => ({
        default: m.ArchivePortalExecutionPreviewModal,
    })),
);

export function ArchivePortalChrome({
    type,
    files,
    theme: _theme,
    shapeClass: _shapeClass,
    onClose,
    onFileClick,
    onAddAction,
    embedded,
    hideHeader,
    hideTopActionBar,
    escapeEnabled = true,
    onMoveExecutionToTrash,
    onRestoreExecutionFromTrash,
    onArchiveExecution,
    onRestoreArchivedExecution,
    onPermanentlyDeleteExecutions,
    onMoveLawsuitToTrash,
    onRestoreLawsuitFromTrash,
    onArchiveLawsuit,
    onRestoreArchivedLawsuit,
    onPermanentlyDeleteLawsuits,
    lawsuitFilesForCluster = [],
    criminalCases = [],
    onOpenCriminalCase,
    onDeleteCriminalCase,
    initialLawsuitJurisdictionTab: _initialLawsuitJurisdictionTab,
    executionFilesHydrating = false,
    executionTrashDaysRemaining,
    gridOnly = false,
    archiveScrollParent = null,
    portal,
}: ArchivePortalProps & {
    portal: any;
    executionTrashDaysRemaining?: (file: LooseArchiveFile) => number | undefined;
}) {
    /** مكافئ محتوى LawsuitsCivilArchiveInstantShell داخل منطقة الشبكة فقط (بلا تكرار شريط/أدوات). */
    const LawsuitArchiveGridFallback = (
        <div
            className="flex flex-col items-center justify-center h-full text-center py-20"
            aria-busy="true"
            data-testid="lawsuit-archive-grid-fallback"
        >
            <h3 className="text-white/40 text-2xl font-bold mb-2">لا توجد ملفات</h3>
        </div>
    );

    const {
        dossierSearchOpen,
        setDossierSearchOpen,
        dossierSearchQuery,
        setDossierSearchQuery,
        lawsuitJurisdictionTab,
        setLawsuitJurisdictionTab,
        viewingCriminal,
        dossierViewMode,
        setDossierViewMode,
        criminalDeleteTarget,
        setCriminalDeleteTarget,
        searchQuery,
        setSearchQuery,
        filterType,
        setFilterType,
        perspectiveFilter,
        setPerspectiveFilter,
        dossierStatusFilter,
        setDossierStatusFilter,
        executionPreviewFile,
        setExecutionPreviewFile,
        executionViewMode,
        setExecutionViewMode,
        executionArchivedCount,
        lawsuitViewMode,
        setLawsuitViewMode,
        trashConfirmTarget,
        setTrashConfirmTarget,
        archiveConfirmTarget,
        setArchiveConfirmTarget,
        lawsuitTrashConfirmTarget,
        setLawsuitTrashConfirmTarget,
        selectedTrashIds,
        setSelectedTrashIds,
        permanentDeleteOpen,
        setPermanentDeleteOpen,
        confirmPermanentDelete,
        beginPermanentDeleteForIds,
        permanentIdsRef,
        previewTimelineEvents,
        executionTrashedCountTotal,
        executionJurisdictionCountsForView,
        lawsuitTrashedCount,
        unifiedArchivedCount,
        toggleTrashSelect,
        getTitle,
        filteredCriminalCases,
        showLawsuitCardsInGrid,
        showCriminalCardsInGrid,
        showDossierToolbar,
        enrichedFiles,
        selectAllTrashedInView,
        beginPermanentDeleteFlow,
        hasLawsuitLifecycle,
        hasExecutionLifecycle,
        executionFilterSummary,
    } = portal;

    useBodyScrollLock(!embedded && !gridOnly);

    useEffect(() => {
        if (embedded || gridOnly) return;
        if (type === 'lawsuits') {
            const warmArchiveIntent = () => {
                warmLawsuitWorkspace({ includeSecondary: false });
            };
            if (typeof requestIdleCallback !== 'undefined') {
                const idleId = requestIdleCallback(warmArchiveIntent, { timeout: 1_400 });
                return () => cancelIdleCallback(idleId);
            }
            const timeoutId = window.setTimeout(warmArchiveIntent, 320);
            return () => window.clearTimeout(timeoutId);
        }
        if (type === 'executions') {
            // فوري — لا تؤجّل تسخين الإضبارة إلى idle وإلا أول نقرة تظل باردة
            warmExecutionWorkspace({ includeSecondary: true, secondaryDelayMs: 0 });
        }
        return undefined;
    }, [embedded, gridOnly, type]);

    useEffect(() => {
        if (embedded || gridOnly || !escapeEnabled) return;
        const onKeyDown = (event: KeyboardEvent) => {
            if (event.key === 'Escape') {
                event.preventDefault();
                onClose();
            }
        };
        window.addEventListener('keydown', onKeyDown);
        return () => window.removeEventListener('keydown', onKeyDown);
    }, [embedded, gridOnly, escapeEnabled, onClose]);

    const lawsuitTrashBulkBar =
        type === 'lawsuits' && lawsuitViewMode === 'trash' && enrichedFiles.length > 0 && onPermanentlyDeleteLawsuits ? (
            <ArchivePortalTrashBulkBar
                animated
                selectedCount={selectedTrashIds.size}
                onSelectAll={selectAllTrashedInView}
                onClearSelection={() => setSelectedTrashIds(new Set())}
                onBeginPermanentDelete={beginPermanentDeleteFlow}
            />
        ) : null;

    const getArchiveScrollElement = React.useCallback(
        () => archiveScrollParent,
        [archiveScrollParent],
    );

    const chromeScrollRef = React.useRef<HTMLDivElement | null>(null);
    const getChromeScrollElement = React.useCallback(
        () => archiveScrollParent ?? chromeScrollRef.current,
        [archiveScrollParent],
    );

    const lawsuitFileGrid = (
        <Suspense fallback={LawsuitArchiveGridFallback}>
            <LazyArchivePortalFileGrid
                type={type}
                enrichedFiles={enrichedFiles}
                searchQuery={searchQuery}
                filterType={filterType}
                perspectiveFilter={perspectiveFilter}
                executionViewMode={executionViewMode}
                setExecutionViewMode={setExecutionViewMode}
                lawsuitFilesForCluster={lawsuitFilesForCluster}
                onFileClick={(file) => onFileClick(file as Parameters<typeof onFileClick>[0])}
                setExecutionPreviewFile={setExecutionPreviewFile}
                onMoveExecutionToTrash={onMoveExecutionToTrash}
                onArchiveExecution={onArchiveExecution}
                onRestoreExecutionFromTrash={onRestoreExecutionFromTrash}
                onRestoreArchivedExecution={onRestoreArchivedExecution}
                onPermanentlyDeleteExecutions={onPermanentlyDeleteExecutions}
                executionTrashDaysRemaining={executionTrashDaysRemaining ?? (() => undefined)}
                selectedTrashIds={selectedTrashIds}
                toggleTrashSelect={toggleTrashSelect}
                setTrashConfirmTarget={setTrashConfirmTarget}
                setArchiveConfirmTarget={setArchiveConfirmTarget}
                hasLawsuitLifecycle={hasLawsuitLifecycle}
                dossierViewMode={dossierViewMode}
                showCriminalCardsInGrid={showCriminalCardsInGrid}
                filteredCriminalCases={filteredCriminalCases}
                showLawsuitCardsInGrid={showLawsuitCardsInGrid}
                onOpenCriminalCase={onOpenCriminalCase}
                lawsuitViewMode={lawsuitViewMode}
                onMoveLawsuitToTrash={onMoveLawsuitToTrash}
                onArchiveLawsuit={onArchiveLawsuit}
                onRestoreLawsuitFromTrash={onRestoreLawsuitFromTrash}
                onRestoreArchivedLawsuit={onRestoreArchivedLawsuit}
                onPermanentlyDeleteLawsuits={onPermanentlyDeleteLawsuits}
                setLawsuitTrashConfirmTarget={setLawsuitTrashConfirmTarget}
                setCriminalDeleteTarget={setCriminalDeleteTarget}
                onDeleteCriminalCase={onDeleteCriminalCase}
                dossierSearchQuery={dossierSearchQuery}
                lawsuitJurisdictionTab={lawsuitJurisdictionTab}
                executionFilesHydrating={executionFilesHydrating}
                beginPermanentDeleteForIds={beginPermanentDeleteForIds}
                getArchiveScrollElement={gridOnly ? getArchiveScrollElement : getChromeScrollElement}
                onAddAction={onAddAction}
            />
        </Suspense>
    );

    const trashDialogs = (
        <ArchivePortalTrashDialogs
            type={type}
            trashConfirmTarget={trashConfirmTarget}
            setTrashConfirmTarget={setTrashConfirmTarget}
            archiveConfirmTarget={archiveConfirmTarget}
            setArchiveConfirmTarget={setArchiveConfirmTarget}
            onArchiveExecution={onArchiveExecution}
            lawsuitTrashConfirmTarget={lawsuitTrashConfirmTarget}
            setLawsuitTrashConfirmTarget={setLawsuitTrashConfirmTarget}
            criminalDeleteTarget={criminalDeleteTarget}
            setCriminalDeleteTarget={setCriminalDeleteTarget}
            permanentDeleteOpen={permanentDeleteOpen}
            setPermanentDeleteOpen={setPermanentDeleteOpen}
            confirmPermanentDelete={confirmPermanentDelete}
            permanentIdsRef={permanentIdsRef}
            onMoveExecutionToTrash={onMoveExecutionToTrash}
            onMoveLawsuitToTrash={onMoveLawsuitToTrash}
            onDeleteCriminalCase={onDeleteCriminalCase}
        />
    );

    if (gridOnly) {
        return (
            <div className="relative flex min-h-0 flex-1 flex-col">
                {lawsuitTrashBulkBar}
                {lawsuitFileGrid}
                {trashDialogs}
            </div>
        );
    }

    // لون القشرة يطابق InstantChrome — bg-black/90 كان يظهر وميضاً أسود عند اعتماد المحتوى
    const shellClass = embedded
        ? "relative flex h-full min-h-0 flex-col bg-[#0B1021] font-['Tajawal']"
        : "fixed inset-0 z-[220] bg-[#0B1021] flex flex-col font-['Tajawal']";

    const layer = (
        <div className={shellClass}>
            {!hideHeader && (
                <div className="px-5 sm:px-6 pt-[max(1rem,env(safe-area-inset-top))] pb-4 border-b border-white/[0.06] flex justify-between items-center gap-4 bg-[#0A0F1C]/80 backdrop-blur-xl shrink-0">
                    <div className="min-w-0 flex-1">
                        <h2 className="text-xl sm:text-2xl font-bold text-white truncate">{getTitle()}</h2>
                        <p className="text-white/40 text-sm mt-0.5 leading-relaxed">
                                {type === 'executions' ? (
                                    <>
                                        {executionViewMode === 'trash' ? (
                                            <>
                                                {enrichedFiles.length}{' '}
                                                {enrichedFiles.length === 1 ? 'إضبارة' : 'إضبارات'} في
                                                سلة المهملات
                                            </>
                                        ) : executionViewMode === 'archived' ? (
                                            <>
                                                {enrichedFiles.length}{' '}
                                                {enrichedFiles.length === 1 ? 'إضبارة' : 'إضبارات'} في
                                                مخزن الأرشيف
                                            </>
                                        ) : (
                                            <>
                                                {enrichedFiles.length}{' '}
                                                {enrichedFiles.length === 1 ? 'إضبارة' : 'إضبارات'}
                                                {executionFilterSummary ? (
                                                    <span className="text-[#E6C673]/80">
                                                        {' '}
                                                        · {executionFilterSummary}
                                                    </span>
                                                ) : null}
                                            </>
                                        )}
                                        {executionViewMode === 'trash' ? (
                                            <span className="block mt-1 text-amber-200/80 text-[11px]">
                                                تبقى الإضابير هنا 30 يوماً ثم تُحذف تلقائياً نهائياً ما لم
                                                تُسترجع.
                                            </span>
                                        ) : null}
                                    </>
                                ) : (
                                    <>
                                        {enrichedFiles.length}{' '}
                                        {(searchQuery || filterType !== 'all') &&
                                        files.length !== enrichedFiles.length ? (
                                            <span>من أصل {files.length} </span>
                                        ) : null}
                                        ملف
                                    </>
                                )}
                        </p>
                    </div>
                    <button
                        type="button"
                        onClick={onClose}
                        aria-label="إغلاق مخزن الإضابير"
                        className="shrink-0 inline-flex items-center justify-center min-h-[44px] min-w-[44px] rounded-full border border-white/10 bg-white/5 hover:bg-white/10 text-white/50 hover:text-white transition-all touch-manipulation"
                    >
                        <X size={20} />
                    </button>
                </div>
            )}

            <ArchivePortalLifecycleBars
                hasExecutionLifecycle={hasExecutionLifecycle}
                executionViewMode={executionViewMode}
                setExecutionViewMode={setExecutionViewMode}
                executionTrashedCountTotal={executionTrashedCountTotal}
                executionArchivedCount={executionArchivedCount}
                executionTrashActionVisible={
                    executionViewMode === 'trash' ||
                    selectedTrashIds.size > 0 ||
                    executionTrashedCountTotal > 0
                }
                hideExecutionPrimarySegments
                hasLawsuitLifecycle={hasLawsuitLifecycle}
                lawsuitViewMode={lawsuitViewMode}
                setLawsuitViewMode={setLawsuitViewMode}
                unifiedArchivedCount={unifiedArchivedCount}
                lawsuitTrashedCount={lawsuitTrashedCount}
                lawsuitTrashActionVisible={
                    lawsuitViewMode === 'trash' ||
                    selectedTrashIds.size > 0 ||
                    lawsuitTrashedCount > 0
                }
            />

            {showDossierToolbar ? (
                <ArchiveDossierToolbar
                    showJurisdictionTabs={type === 'lawsuits'}
                    showUrgentChip={false}
                    jurisdictionTab={lawsuitJurisdictionTab}
                    onJurisdictionTabChange={setLawsuitJurisdictionTab}
                    searchOpen={dossierSearchOpen}
                    onToggleSearch={() => setDossierSearchOpen((v) => !v)}
                    searchQuery={dossierSearchQuery}
                    onSearchQueryChange={setDossierSearchQuery}
                    searchPlaceholder={
                        viewingCriminal
                            ? 'ابحث برقم الإضبارة، المشتكي، المتهم، أو المادة…'
                            : 'ابحث برقم الإضبارة أو اسم الدعوى...'
                    }
                    viewMode={dossierViewMode}
                    onViewModeChange={setDossierViewMode}
                />
            ) : null}

            {/* ⓘ زر "إضافة ملف قضائي جديد" تم نقله إلى FAB ثابت أسفل-يسار المنفذ — يظهر في كل التبويبات (مدني/شخصي/جزائي) ولا يأخذ مساحة من قائمة الإضابير. */}

            {type === 'executions' ? (
                <ExecutionArchiveToolbar
                    lifecycleMode={executionViewMode}
                    searchQuery={searchQuery}
                    onSearchQueryChange={setSearchQuery}
                    filterType={filterType}
                    onFilterTypeChange={setFilterType}
                    perspectiveFilter={perspectiveFilter}
                    onPerspectiveFilterChange={setPerspectiveFilter}
                    dossierStatusFilter={dossierStatusFilter}
                    onDossierStatusFilterChange={setDossierStatusFilter}
                    jurisdictionCounts={executionJurisdictionCountsForView}
                />
            ) : null}

            {type === 'lawsuits' && lawsuitViewMode === 'trash' && enrichedFiles.length > 0 && onPermanentlyDeleteLawsuits
                ? lawsuitTrashBulkBar
                : null}

            {type === 'executions' && executionViewMode === 'trash' && enrichedFiles.length > 0 && onPermanentlyDeleteExecutions && (
                <ArchivePortalTrashBulkBar
                    selectedCount={selectedTrashIds.size}
                    onSelectAll={selectAllTrashedInView}
                    onClearSelection={() => setSelectedTrashIds(new Set())}
                    onBeginPermanentDelete={beginPermanentDeleteFlow}
                />
            )}

            {/* Grid */}
            <div
                ref={chromeScrollRef}
                className={`flex-1 overflow-y-auto px-4 sm:px-5 lg:px-6 py-5 ${
                    embedded
                        ? 'pb-[max(5.5rem,calc(4.5rem+env(safe-area-inset-bottom)))]'
                        : 'pb-[max(2rem,calc(5.25rem+env(safe-area-inset-bottom)))]'
                }`}
            >
            {type === 'executions' ? (
                <ExecutionArchiveFileGrid
                    enrichedFiles={enrichedFiles}
                    searchQuery={searchQuery}
                    filterType={filterType}
                    perspectiveFilter={perspectiveFilter}
                    dossierStatusFilter={dossierStatusFilter}
                    executionViewMode={executionViewMode}
                    setExecutionViewMode={setExecutionViewMode}
                    lawsuitFilesForCluster={lawsuitFilesForCluster}
                    onFileClick={(file) => onFileClick(file as Parameters<typeof onFileClick>[0])}
                    setExecutionPreviewFile={setExecutionPreviewFile}
                    onMoveExecutionToTrash={onMoveExecutionToTrash}
                    onArchiveExecution={onArchiveExecution}
                    onRestoreExecutionFromTrash={onRestoreExecutionFromTrash}
                    onRestoreArchivedExecution={onRestoreArchivedExecution}
                    onPermanentlyDeleteExecutions={onPermanentlyDeleteExecutions}
                    executionTrashDaysRemaining={executionTrashDaysRemaining ?? (() => undefined)}
                    selectedTrashIds={selectedTrashIds}
                    toggleTrashSelect={toggleTrashSelect}
                    setTrashConfirmTarget={setTrashConfirmTarget}
                    setArchiveConfirmTarget={setArchiveConfirmTarget}
                    executionFilesHydrating={executionFilesHydrating}
                    beginPermanentDeleteForIds={beginPermanentDeleteForIds}
                    getArchiveScrollElement={getChromeScrollElement}
                />
            ) : (
                lawsuitFileGrid
            )}
            </div>

            {type === 'executions' && executionPreviewFile && (
                <Suspense fallback={null}>
                    <LazyArchivePortalExecutionPreviewModal
                        file={executionPreviewFile}
                        previewTimelineEvents={previewTimelineEvents}
                        onClose={() => setExecutionPreviewFile(null)}
                        onOpenFull={(file) => {
                            flushSync(() => {
                                setExecutionPreviewFile(null);
                            });
                            onFileClick(file);
                        }}
                    />
                </Suspense>
            )}

            {trashDialogs}

            {/* ⭐ Floating Action Button — يظهر في كل تبويبات الإضابير (مدني/شخصي/جزائي/تنفيذ) ولا يأخذ مساحة من القائمة. */}
            {!hideTopActionBar &&
                lawsuitViewMode === 'active' &&
                !(type === 'executions' && executionViewMode !== 'active') &&
                (type === 'lawsuits' || type === 'executions') && (
                    <div className="pointer-events-none absolute inset-x-0 bottom-0 z-40 px-[max(1rem,env(safe-area-inset-left))] pb-[max(1rem,calc(env(safe-area-inset-bottom)+0.75rem))]">
                        <div className="pointer-events-auto flex justify-start px-1">
                            <button
                                type="button"
                                data-testid={type === 'lawsuits' ? 'lawsuits-add-new' : 'executions-add-new'}
                                onClick={onAddAction}
                                onPointerEnter={() => {
                                    if (type === 'executions') {
                                        void import('@/app/runtime/executionCreationLoader')
                                            .then((m) => m.prefetchExecutionCreationViewModule())
                                            .catch(() => undefined);
                                    }
                                }}
                                title={
                                    type === 'executions'
                                        ? 'فتح إضبارة تنفيذ جديدة'
                                        : lawsuitJurisdictionTab === 'criminal'
                                          ? 'إنشاء إضبارة جزائية جديدة'
                                          : 'إضافة ملف قضائي جديد'
                                }
                                aria-label={
                                    type === 'executions'
                                        ? 'فتح إضبارة تنفيذ جديدة'
                                        : lawsuitJurisdictionTab === 'criminal'
                                          ? 'إنشاء إضبارة جزائية جديدة'
                                          : 'إضافة ملف قضائي جديد'
                                }
                                className={
                                    lawsuitJurisdictionTab === 'criminal' && type === 'lawsuits'
                                        ? 'group flex min-h-[3.5rem] items-center gap-2.5 rounded-full border-2 pl-5 pr-4 font-bold shadow-2xl ring-1 ring-white/10 backdrop-blur-xl transition-all duration-200 hover:scale-[1.02] hover:-translate-y-0.5 active:scale-95 touch-manipulation bg-gradient-to-r from-rose-700 to-red-600 hover:from-red-600 hover:to-rose-600 text-white border-rose-400/40 shadow-rose-900/50'
                                        : ARCHIVE_ROYAL_GLASS_FAB
                                }
                            >
                                <Plus size={22} strokeWidth={3} className="drop-shadow" />
                                <span className="text-sm tracking-wide whitespace-nowrap">
                                    {type === 'executions'
                                        ? 'إضبارة تنفيذ جديدة'
                                        : lawsuitJurisdictionTab === 'criminal'
                                          ? 'إضبارة جزائية جديدة'
                                          : 'ملف قضائي جديد'}
                                </span>
                            </button>
                        </div>
                    </div>
                )}
        </div>
    );

    if (embedded) return layer;
    return typeof document !== 'undefined' ? createPortal(layer, document.body) : layer;
}

import React, { useLayoutEffect } from 'react';
import type { ArchivePortalProps } from '@/app/types/common';
