type LawsuitVirtualItem =
    | { kind: 'criminal'; id: string; record: Record<string, unknown> & { id?: string | number } }
    | { kind: 'lawsuit'; id: string; file: ArchiveEnrichedRow };

function resolveLawsuitColumns(width: number): number {
    if (width >= 1280) return 4;
    if (width >= 1024) return 3;
    if (width >= 768) return 2;
    return 1;
}

export function ArchivePortalFileGrid(props: ArchivePortalFileGridProps) {
    const {
        type,
        enrichedFiles,
        searchQuery,
        filterType,
        perspectiveFilter: _perspectiveFilter,
        executionViewMode: _executionViewMode,
        setExecutionViewMode: _setExecutionViewMode,
        lawsuitFilesForCluster: _lawsuitFilesForCluster,
        onFileClick,
        setExecutionPreviewFile: _setExecutionPreviewFile,
        onMoveExecutionToTrash: _onMoveExecutionToTrash,
        onArchiveExecution: _onArchiveExecution,
        onRestoreExecutionFromTrash: _onRestoreExecutionFromTrash,
        onRestoreArchivedExecution: _onRestoreArchivedExecution,
        onPermanentlyDeleteExecutions: _onPermanentlyDeleteExecutions,
        executionTrashDaysRemaining: _executionTrashDaysRemaining,
        selectedTrashIds,
        toggleTrashSelect,
        setTrashConfirmTarget: _setTrashConfirmTarget,
        setArchiveConfirmTarget: _setArchiveConfirmTarget,
        hasLawsuitLifecycle,
        dossierViewMode,
        showCriminalCardsInGrid,
        filteredCriminalCases,
        showLawsuitCardsInGrid,
        onOpenCriminalCase,
        lawsuitViewMode,
        onMoveLawsuitToTrash,
        onArchiveLawsuit,
        onRestoreLawsuitFromTrash,
        onRestoreArchivedLawsuit,
        onPermanentlyDeleteLawsuits,
        setLawsuitTrashConfirmTarget,
        setCriminalDeleteTarget,
        onDeleteCriminalCase,
        dossierSearchQuery,
        lawsuitJurisdictionTab: _lawsuitJurisdictionTab,
        executionFilesHydrating: _executionFilesHydrating = false,
        beginPermanentDeleteForIds: _beginPermanentDeleteForIds,
        getArchiveScrollElement,
        onAddAction: _onAddAction,
    } = props;

    const lawsuitItems = useMemo((): LawsuitVirtualItem[] => {
        if (!(type === 'lawsuits' && hasLawsuitLifecycle)) return [];
        const out: LawsuitVirtualItem[] = [];
        if (showCriminalCardsInGrid) {
            for (const c of filteredCriminalCases) {
                out.push({ kind: 'criminal', id: `criminal:${String(c.id)}`, record: c });
            }
        }
        if (showLawsuitCardsInGrid) {
            for (const file of enrichedFiles) {
                out.push({ kind: 'lawsuit', id: String(file.id), file });
            }
        }
        return out;
    }, [
        type,
        hasLawsuitLifecycle,
        showCriminalCardsInGrid,
        filteredCriminalCases,
        showLawsuitCardsInGrid,
        enrichedFiles,
    ]);

    const renderLawsuitGridItem = useCallback(
        (item: LawsuitVirtualItem) => {
            if (item.kind === 'criminal') {
                const c = item.record;
                return (
                    <CriminalArchiveCard
                        record={c}
                        variant="grid"
                        onOpen={() => onOpenCriminalCase?.(String(c.id))}
                        onDelete={
                            lawsuitViewMode === 'active' && onDeleteCriminalCase
                                ? () => {
                                      const ref = criminalCaseReference(c);
                                      setCriminalDeleteTarget({
                                          id: String(c.id),
                                          title: `${ref.primary} • ${ref.secondary}`,
                                      });
                                  }
                                : undefined
                        }
                    />
                );
            }
            const file = item.file;
            const variant =
                lawsuitViewMode === 'trash'
                    ? 'trash'
                    : lawsuitViewMode === 'archived'
                      ? 'archived'
                      : 'active';
            return (
                <LawsuitArchiveCard
                    file={file}
                    variant={variant}
                    testIdPrefix="lawsuit-card"
                    onOpen={() => onFileClick(file)}
                    onMoveToTrash={
                        variant === 'active' && onMoveLawsuitToTrash
                            ? () => setLawsuitTrashConfirmTarget(file as LooseArchiveFile)
                            : undefined
                    }
                    onArchive={
                        variant === 'active' && onArchiveLawsuit
                            ? () => onArchiveLawsuit((file as LooseArchiveFile).id)
                            : undefined
                    }
                    onRestoreFromTrash={
                        variant === 'trash' && onRestoreLawsuitFromTrash
                            ? () => onRestoreLawsuitFromTrash((file as LooseArchiveFile).id)
                            : undefined
                    }
                    onRestoreFromArchive={
                        variant === 'archived' && onRestoreArchivedLawsuit
                            ? () => onRestoreArchivedLawsuit((file as LooseArchiveFile).id)
                            : undefined
                    }
                    selected={selectedTrashIds.has(String((file as LooseArchiveFile).id))}
                    onToggleSelect={
                        variant === 'trash' && onPermanentlyDeleteLawsuits
                            ? () => toggleTrashSelect((file as LooseArchiveFile).id)
                            : undefined
                    }
                />
            );
        },
        [
            lawsuitViewMode,
            onDeleteCriminalCase,
            onOpenCriminalCase,
            setCriminalDeleteTarget,
            onFileClick,
            onMoveLawsuitToTrash,
            setLawsuitTrashConfirmTarget,
            onArchiveLawsuit,
            onRestoreLawsuitFromTrash,
            onRestoreArchivedLawsuit,
            selectedTrashIds,
            onPermanentlyDeleteLawsuits,
            toggleTrashSelect,
        ],
    );

    const renderLawsuitCompactItem = useCallback(
        (item: LawsuitVirtualItem) => {
            if (item.kind === 'criminal') {
                const c = item.record;
                return (
                    <CriminalArchiveCard
                        record={c}
                        variant="compact"
                        onOpen={() => onOpenCriminalCase?.(String(c.id))}
                    />
                );
            }
            const file = item.file;
            const row = file as ArchiveEnrichedRow;
            const isTx = row.type === 'transaction';
            return (
                <button
                    type="button"
                    onPointerEnter={() => warmLawsuitWorkspace({ includeSecondary: false })}
                    onFocus={() => warmLawsuitWorkspace({ includeSecondary: false })}
                    onClick={() => onFileClick(file)}
                    className="w-full text-right rounded-xl border border-white/10 bg-[#151825] p-3 hover:border-[#E6C673]/40 flex items-start gap-3"
                >
                    <span
                        className={`shrink-0 text-[9px] font-bold px-2 py-0.5 rounded-full border ${
                            isTx
                                ? 'border-purple-500/35 bg-purple-500/10 text-purple-200'
                                : 'border-[#E6C673]/35 bg-[#E6C673]/10 text-[#E6C673]'
                        }`}
                    >
                        {isTx ? 'معاملة' : 'مدني'}
                    </span>
                    <span className="min-w-0 flex-1">
                        <span className="block text-[12px] font-bold text-white truncate">
                            {row.docType ?? row.title ?? 'دعوى'}
                        </span>
                        <span className="block text-[10px] text-white/45 font-mono mt-0.5">
                            {row.caseNo || row.caseNumber || '—'}
                            {'court' in row && row.court
                                ? ` · ${typeof row.court === 'string' ? row.court : row.court.name}`
                                : ''}
                        </span>
                    </span>
                    <span className="text-[10px] text-white/40 shrink-0">
                        {file.smartStatus.label}
                    </span>
                </button>
            );
        },
        [onOpenCriminalCase, onFileClick],
    );

    const hasLawsuitBody =
        (showCriminalCardsInGrid && filteredCriminalCases.length > 0) ||
        (showLawsuitCardsInGrid && enrichedFiles.length > 0);

    return (
        <>
            {type === 'lawsuits' && hasLawsuitLifecycle && dossierViewMode === 'compact' ? (
                lawsuitItems.length > 0 ? (
                    <ArchiveVirtualGrid
                        items={lawsuitItems}
                        estimateRowSize={72}
                        getItemKey={(item) => item.id}
                        testId="lawsuit-archive-grid"
                        className="space-y-2 max-w-4xl mx-auto"
                        resolveColumns={() => 1}
                        getScrollElement={getArchiveScrollElement}
                        renderItem={renderLawsuitCompactItem}
                    />
                ) : null
            ) : type === 'lawsuits' && hasLawsuitLifecycle ? (
                lawsuitItems.length > 0 ? (
                    <ArchiveVirtualGrid
                        items={lawsuitItems}
                        estimateRowSize={260}
                        getItemKey={(item) => item.id}
                        testId="lawsuit-archive-grid"
                        className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-3.5"
                        resolveColumns={resolveLawsuitColumns}
                        getScrollElement={getArchiveScrollElement}
                        renderItem={renderLawsuitGridItem}
                    />
                ) : null
            ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-3.5">
                    {enrichedFiles.map((file) => {
                        const status = file.smartStatus;
                        const row = file as ArchiveEnrichedRow;

                        const isTransactionFile =
                            (file as LooseArchiveFile).type === 'transaction';
                        const kind: DossierKind = isTransactionFile ? 'transaction' : 'civil';

                        const pinPayload =
                            type === 'lawsuits'
                                ? buildLawsuitWorkspacePin(file)
                                : type === 'execution'
                                  ? null
                                  : buildTransactionWorkspacePin(file);

                        const courtName =
                            'court' in file && file.court
                                ? typeof file.court === 'string'
                                    ? file.court
                                    : file.court.name
                                : '';
                        const directorate =
                            'directorate' in file ? String(file.directorate ?? '') : '';
                        const docType =
                            (file as { docType?: string }).docType ??
                            file.title ??
                            String(file.type ?? 'دعوى');
                        const caseNumber = row.caseNo || row.caseNumber || '';

                        const title = courtName || directorate || docType || 'دعوى';
                        const subtitle = caseNumber || (courtName ? docType : '');

                        const parties = Array.isArray(row.parties) ? row.parties : [];

                        return (
                            <UnifiedDossierCard
                                key={String(file.id)}
                                kind={kind}
                                testId={type === 'lawsuits' ? `lawsuit-file-${file.id}` : undefined}
                                statusBadge={{
                                    label: status.label,
                                    className: `${status.bgColor} ${status.borderColor} ${status.color}`,
                                }}
                                pinNode={
                                    pinPayload ? (
                                        <div
                                            onClick={(event) => event.stopPropagation()}
                                            onKeyDown={(event) => event.stopPropagation()}
                                            role="presentation"
                                        >
                                            <WorkspacePinButton item={pinPayload} />
                                        </div>
                                    ) : undefined
                                }
                                title={title}
                                subtitle={subtitle}
                                bodyExtra={
                                    <>
                                        {status.timers ? (
                                            <div className="flex flex-col gap-1 text-xs">
                                                {status.timers.appeal !== undefined ? (
                                                    <div className="flex items-center gap-2">
                                                        <Clock size={12} className="text-blue-400" />
                                                        <span
                                                            className={`font-bold ${status.timers.appeal <= 5 ? 'text-red-400 animate-pulse' : 'text-blue-300'}`}
                                                        >
                                                            استئناف: باقي {status.timers.appeal} يوم
                                                        </span>
                                                    </div>
                                                ) : null}
                                                {status.timers.cassation !== undefined ? (
                                                    <div className="flex items-center gap-2">
                                                        <Clock size={12} className="text-purple-400" />
                                                        <span
                                                            className={`font-bold ${status.timers.cassation <= 5 ? 'text-red-400 animate-pulse' : 'text-purple-300'}`}
                                                        >
                                                            تمييز: باقي {status.timers.cassation} يوم
                                                        </span>
                                                    </div>
                                                ) : null}
                                                {status.timers.review !== undefined ? (
                                                    <div className="flex items-center gap-2">
                                                        <AlertCircle
                                                            size={12}
                                                            className="text-orange-400"
                                                        />
                                                        <span
                                                            className={`font-bold ${status.timers.review <= 3 ? 'text-red-400 animate-pulse' : 'text-orange-300'}`}
                                                        >
                                                            ⏳ مراجعة: باقي {status.timers.review} أيام
                                                        </span>
                                                    </div>
                                                ) : null}
                                                {status.timers.finalAppeal !== undefined ? (
                                                    <div className="flex items-center gap-2">
                                                        <AlertCircle
                                                            size={12}
                                                            className="text-red-400"
                                                        />
                                                        <span
                                                            className={`font-bold ${status.timers.finalAppeal <= 5 ? 'text-red-400 animate-pulse' : 'text-red-300'}`}
                                                        >
                                                            🛑 طعن: باقي {status.timers.finalAppeal} يوم
                                                        </span>
                                                    </div>
                                                ) : null}
                                            </div>
                                        ) : null}
                                        {parties.length > 0 ? (
                                            <div className="flex -space-x-2 space-x-reverse mt-1">
                                                {parties.slice(0, 3).map((p, i: number) => (
                                                    <div
                                                        key={i}
                                                        className="w-7 h-7 rounded-full bg-white/[0.06] border border-white/15 flex items-center justify-center text-[10px] text-white/80 font-bold"
                                                        title={p.name}
                                                    >
                                                        {p.name ? p.name[0] : '؟'}
                                                    </div>
                                                ))}
                                                {parties.length > 3 ? (
                                                    <div className="w-7 h-7 rounded-full bg-[#d4af37]/15 border border-[#d4af37]/30 text-[#d4af37] flex items-center justify-center text-[10px] font-bold">
                                                        +{parties.length - 3}
                                                    </div>
                                                ) : null}
                                            </div>
                                        ) : null}
                                    </>
                                }
                                onOpen={() => onFileClick(file)}
                                openLabel="فتح الإضبارة"
                                footerIcons={
                                    type === 'deleted'
                                        ? [
                                              {
                                                  id: 'restore-hint',
                                                  label: 'استرجاع',
                                                  icon: <RotateCcw size={16} />,
                                                  tone: 'success',
                                                  onClick: () => onFileClick(file),
                                              },
                                          ]
                                        : []
                                }
                            />
                        );
                    })}
                </div>
            )}

            {!hasLawsuitBody && type === 'lawsuits' && hasLawsuitLifecycle ? (
                <div
                    className="flex flex-col items-center justify-center h-full text-center py-20 px-6"
                    data-testid="lawsuit-archive-empty"
                >
                    <h3 className="text-white/55 text-2xl font-bold mb-2">
                        {searchQuery || filterType !== 'all' || dossierSearchQuery
                            ? 'لا توجد نتائج'
                            : 'لا توجد ملفات'}
                    </h3>
                    {searchQuery || filterType !== 'all' || dossierSearchQuery ? (
                        <p className="text-white/40 text-sm">جرب تغيير معايير البحث أو الفلترة</p>
                    ) : lawsuitViewMode === 'trash' ? (
                        <p className="text-white/40 text-sm">لا توجد إضابير في السلة.</p>
                    ) : lawsuitViewMode === 'archived' ? (
                        <p className="text-white/40 text-sm">لا توجد إضابير في مخزن الأرشيف.</p>
                    ) : null}
                </div>
            ) : !(
                  (showCriminalCardsInGrid && filteredCriminalCases.length > 0) ||
                  (showLawsuitCardsInGrid && enrichedFiles.length > 0)
              ) && !(type === 'lawsuits' && hasLawsuitLifecycle) ? (
                <div className="flex flex-col items-center justify-center h-full text-center py-20 px-6">
                    <h3 className="text-white/55 text-2xl font-bold mb-2">
                        {searchQuery || filterType !== 'all' || dossierSearchQuery
                            ? 'لا توجد نتائج'
                            : 'لا توجد ملفات'}
                    </h3>
                    {searchQuery || filterType !== 'all' || dossierSearchQuery ? (
                        <p className="text-white/40 text-sm">جرب تغيير معايير البحث أو الفلترة</p>
                    ) : null}
                </div>
            ) : null}
        </>
    );
}

import React from 'react';
import { motion } from 'motion/react';
import { Archive, Trash2, Link2, Eye, RotateCcw } from 'lucide-react';
import { useReduceMotion } from '@/app/hooks/useReduceMotion';
import { dossierLifecycleBadgeClass } from '@/app/components/lawyer/ExecutionDashboard/helpers/dossierLifecycleUtils';
import { isEvictionClaim } from '@/app/utils/executionModuleStrategies';
import { executionTrashDaysRemaining } from '@/app/utils/executionTrash';
import type { LooseArchiveFile } from '../types';
import { WorkspacePinButton } from '@/app/workspace/WorkspacePinButton';
import { buildExecutionWorkspacePin } from '@/app/workspace/workspacePinBuilders';
import { resolveExecutionArchiveCardView } from '../utils';
import { ExecutionArchivePartyBlock } from './ExecutionArchivePartyBlock';
import { warmExecutionDossier } from '@/app/utils/lazyComponentsIntent';
import { dispatchExecutionDossierPrimeHost } from '@/app/runtime/executionDossierPrimeHost';
import { resolveDossierHeaderFields } from '@/app/utils/executionDossierHeaderFields';

interface ExecutionSmartCardProps {
    file: LooseArchiveFile & {
        unifiedCount?: unknown;
        unifiedTotalDemand?: unknown;
    };
    liveRevision?: number;
    lawsuitFilesForCluster?: unknown[];
    onOpen: () => void;
    onPreview: () => void;
    variant: 'active' | 'archived' | 'trash';
    onRequestMoveToTrash?: () => void;
    onRequestArchive?: () => void;
    onRestoreFromTrash?: () => void;
    onRestoreFromArchive?: () => void;
    onRequestPermanentDelete?: () => void;
    trashDaysRemaining?: number;
    selected?: boolean;
    onToggleSelect?: () => void;
}

function BiDiText({
    children,
    className = '',
}: {
    children: React.ReactNode;
    className?: string;
}) {
    return (
        <bdi dir="auto" className={`[unicode-bidi:plaintext] ${className}`.trim()}>
            {children}
        </bdi>
    );
}

function outlineIconActionClassName(tone: 'neutral' | 'accent' | 'danger') {
    const tones = {
        neutral:
            'border-white/12 bg-white/[0.03] text-white/62 hover:border-white/22 hover:bg-white/[0.06] hover:text-white',
        accent:
            'border-[#E6C673]/28 bg-[#E6C673]/[0.045] text-[#E6C673] hover:border-[#E6C673]/45 hover:bg-[#E6C673]/[0.09]',
        danger:
            'border-rose-500/28 bg-rose-500/[0.045] text-rose-200 hover:border-rose-400/45 hover:bg-rose-500/[0.09]',
    } as const;
    return `flex min-h-[44px] min-w-[44px] items-center justify-center rounded-xl border transition-all duration-200 touch-manipulation ${tones[tone]}`;
}

function outlineTextActionClassName(tone: 'accent' | 'success') {
    const tones = {
        accent:
            'border-[#E6C673]/28 bg-[#E6C673]/[0.06] text-[#E6C673] hover:border-[#E6C673]/45 hover:bg-[#E6C673]/[0.1]',
        success:
            'border-emerald-500/28 bg-emerald-500/[0.06] text-emerald-300 hover:border-emerald-400/45 hover:bg-emerald-500/[0.1]',
    } as const;
    return `inline-flex items-center gap-1.5 rounded-xl border px-2.5 py-1.5 text-[10px] font-bold transition-all duration-200 ${tones[tone]}`;
}

function ExecutionSmartCard({
    file,
    liveRevision = 0,
    lawsuitFilesForCluster = [],
    onOpen,
    onPreview,
    variant,
    onRequestMoveToTrash,
    onRequestArchive,
    onRestoreFromTrash,
    onRestoreFromArchive,
    onRequestPermanentDelete,
    trashDaysRemaining,
    selected,
    onToggleSelect,
}: ExecutionSmartCardProps) {
    const reduceMotion = useReduceMotion();
    const prefetchFiredRef = React.useRef(false);

    const handleToolbarAction = React.useCallback(
        (event: React.SyntheticEvent, action?: () => void) => {
            event.preventDefault();
            event.stopPropagation();
            action?.();
        },
        [],
    );

    const loose = file;
    const unifiedCount = Number(file.unifiedCount || 0);
    const unifiedTotalDemandRaw = Number(file.unifiedTotalDemand);
    const cardView = React.useMemo(
        () =>
            resolveExecutionArchiveCardView(loose, {
                unifiedCount,
                unifiedTotalDemand: unifiedTotalDemandRaw,
            }),
        [loose, unifiedCount, unifiedTotalDemandRaw, liveRevision],
    );

    // قراءة blob الإضبارة (فك تشفير + JSON.parse) عند النية بدل لحظة النقر —
    // buildExecutionViewData يقرأها متزامناً أثناء أول mount، وهذا يجعلها cache hit.
    const warmDossierBlobRef = React.useRef(false);
    const warmDossierBlob = React.useCallback(() => {
        if (warmDossierBlobRef.current) return;
        warmDossierBlobRef.current = true;
        const fileId = String(loose.id ?? '').trim();
        if (!fileId) return;
        void import('@/app/infrastructure/execution/ExecutionDossierRepository')
            .then((m) => {
                m.readExecutionDossierByIdFromCache(fileId);
            })
            .catch(() => undefined);
    }, [loose.id]);

    const primeExecutionDossier = React.useCallback(() => {
        if (prefetchFiredRef.current) return;
        prefetchFiredRef.current = true;
        warmExecutionDossier();
        warmDossierBlob();
        dispatchExecutionDossierPrimeHost({
            ...(loose as Record<string, unknown>),
            type: 'execution',
        });
    }, [warmDossierBlob, loose]);

    const handleOpen = React.useCallback(() => {
        warmExecutionDossier('urgent');
        warmDossierBlob();
        // تسليح Host قبل commit — إن كان مركّباً يُظهر فوراً؛ وإلا يُركّب بنفس الملف
        dispatchExecutionDossierPrimeHost({
            ...(loose as Record<string, unknown>),
            type: 'execution',
        });
        onOpen();
    }, [warmDossierBlob, onOpen, loose]);

    const handleCardClick = React.useCallback(
        (e: React.MouseEvent) => {
            const target = e.target;
            if (!(target instanceof Element)) return;
            if (target.closest('button,a,[role="checkbox"],input,textarea,select,label')) return;
            handleOpen();
        },
        [handleOpen],
    );

    // click يُطلق عند pointerup — البدء من pointerdown يكسب ~100ms من تحميل الـ chunks
    const handleCardPointerDown = React.useCallback(
        (e: React.PointerEvent) => {
            const target = e.target;
            if (!(target instanceof Element)) return;
            if (target.closest('button,a,[role="checkbox"],input,textarea,select,label')) return;
            warmExecutionDossier('urgent');
            warmDossierBlob();
        },
        [warmDossierBlob],
    );

    const headerMeta = React.useMemo(
        () => resolveDossierHeaderFields(cardView.snap),
        [cardView.snap],
    );
    const claimTypeLine = headerMeta.claimTypeDisplay || cardView.claimLabelAr;
    const executionTypeLine =
        headerMeta.docType ||
        cardView.docTypeLabel ||
        headerMeta.classificationDisplay ||
        '';

    const snapLoose = cardView.snap as unknown as LooseArchiveFile;
    const lifecycleBadgeClass = dossierLifecycleBadgeClass(cardView.dossierLifecycleStatus);
    const venueLabel = cardView.directorateLabel
        ? { prefix: 'مديرية التنفيذ', name: cardView.directorateLabel }
        : cardView.court && cardView.court !== 'غير محدد'
          ? { prefix: 'المحكمة', name: cardView.court }
          : null;

    const pinPayload =
        variant === 'active' ? buildExecutionWorkspacePin(cardView.snap, lawsuitFilesForCluster) : null;

    const showTrashSelect = variant === 'trash' && Boolean(onToggleSelect);
    const showPin = variant === 'active' && Boolean(pinPayload);
    const showArchive = variant === 'active' && Boolean(onRequestArchive);
    const showTrash = variant === 'active' && Boolean(onRequestMoveToTrash);
    const showPermanentDelete = variant === 'trash' && Boolean(onRequestPermanentDelete);
    const hasIconToolbar =
        showTrashSelect || showPin || showArchive || showTrash || showPermanentDelete;

    const cardClassName = `
                group relative cursor-pointer overflow-hidden rounded-3xl
                border border-white/10 bg-gradient-to-br from-[#0B1120]/95 to-[#05060D]/90
                p-4 sm:p-[1.125rem] shadow-[0_16px_42px_rgba(0,0,0,0.42)] backdrop-blur-xl
                transition-all duration-300 hover:border-[#E6C673]/35 hover:shadow-[0_20px_52px_rgba(230,198,115,0.08)]
                ${variant === 'trash' ? 'opacity-95 ring-1 ring-rose-500/25' : ''}
                ${variant === 'archived' ? 'opacity-90 ring-1 ring-amber-500/20' : ''}
            `;

    const cardBody = (
        <>
            <div className="pointer-events-none absolute inset-x-0 top-0 h-14 bg-gradient-to-b from-white/[0.04] to-transparent" />

            {variant === 'trash' && (
                <div className="mb-3 flex flex-wrap items-center justify-end gap-2">
                    <span className="inline-flex items-center gap-1.5 rounded-lg border border-amber-500/35 bg-amber-950/40 px-2.5 py-1 text-[10px] font-bold text-amber-100">
                        <Trash2 size={12} className="shrink-0" />
                        في سلة المهملات
                    </span>
                    <span className="inline-flex rounded-lg border border-white/15 bg-white/5 px-2.5 py-1 text-[10px] font-semibold tabular-nums text-slate-300">
                        حذف تلقائي خلال {trashDaysRemaining ?? executionTrashDaysRemaining(loose)} يوماً
                    </span>
                </div>
            )}

            <div className="relative mb-3" dir="rtl">
                <div className="flex items-start justify-between gap-2.5">
                    <div className="min-w-0 flex-1">
                        <div className="mb-1 flex flex-wrap items-center gap-2">
                            <span className="text-[11px] font-semibold text-slate-400">رقم الإضبارة</span>
                            <span
                                className={`inline-flex shrink-0 items-center rounded-full border px-2 py-0.5 text-[10px] font-bold leading-tight ${lifecycleBadgeClass}`}
                            >
                                {cardView.dossierLifecycleBadge}
                            </span>
                            {unifiedCount > 0 ? (
                                <span className="inline-flex shrink-0 items-center rounded-lg border border-[#E6C673]/25 bg-[#0B1120]/55 px-2 py-0.5 text-[10px] font-bold text-[#E6C673]">
                                    موحّدة · {unifiedCount}
                                </span>
                            ) : null}
                        </div>
                        <p className="text-[1.375rem] font-black leading-none tracking-tight text-white sm:text-2xl">
                            <BiDiText className="tabular-nums">
                                {`${cardView.fileNumber} / ${cardView.year}`}
                            </BiDiText>
                        </p>
                        {venueLabel ? (
                            <p className="mt-2 leading-snug">
                                <span className="block text-[11px] font-semibold text-slate-400">
                                    {venueLabel.prefix}
                                </span>
                                <BiDiText className="mt-0.5 block text-[14px] font-bold text-slate-50 sm:text-[15px]">
                                    {venueLabel.name}
                                </BiDiText>
                            </p>
                        ) : null}
                        {claimTypeLine || executionTypeLine ? (
                            <div className="mt-2.5 space-y-1">
                                {claimTypeLine ? (
                                    <p className="truncate text-[12px] text-white/55">
                                        <span className="text-white/35">نوع المطالبة · </span>
                                        <BiDiText className="font-semibold text-white/80">
                                            {claimTypeLine}
                                        </BiDiText>
                                    </p>
                                ) : null}
                                {executionTypeLine ? (
                                    <p className="truncate text-[12px] text-white/55">
                                        <span className="text-white/35">نوع التنفيذ · </span>
                                        <BiDiText className="font-semibold text-white/75">
                                            {executionTypeLine}
                                        </BiDiText>
                                    </p>
                                ) : null}
                            </div>
                        ) : null}
                    </div>

                    <div
                        className="relative z-20 inline-flex shrink-0 flex-col items-stretch gap-1.5"
                        onClick={(e) => e.stopPropagation()}
                        onPointerDown={(e) => e.stopPropagation()}
                        onKeyDown={(e) => e.stopPropagation()}
                        role="presentation"
                    >
                        {hasIconToolbar ? (
                            <div className="inline-flex items-center justify-end gap-1.5 rounded-2xl border border-white/10 bg-black/20 p-1 shadow-[inset_0_1px_0_rgba(255,255,255,0.03)]">
                                {showTrashSelect ? (
                                    <button
                                        type="button"
                                        aria-checked={selected}
                                        role="checkbox"
                                        onClick={onToggleSelect}
                                        className={`flex min-h-[44px] min-w-[44px] items-center justify-center rounded-xl border transition-all duration-200 touch-manipulation ${
                                            selected
                                                ? 'border-[#E6C673]/45 bg-[#E6C673]/14 text-[#E6C673]'
                                                : 'border-white/12 bg-white/[0.03] text-white/62 hover:border-white/22 hover:bg-white/[0.06] hover:text-white'
                                        }`}
                                    >
                                        {selected ? '✓' : ''}
                                    </button>
                                ) : null}
                                {showPin ? (
                                    <WorkspacePinButton
                                        item={pinPayload!}
                                        size={15}
                                        className="min-h-[44px] min-w-[44px] rounded-xl border-white/12 bg-white/[0.03] text-white/62 hover:border-white/22 hover:bg-white/[0.06] hover:text-white touch-manipulation"
                                    />
                                ) : null}
                                {showArchive ? (
                                    <button
                                        type="button"
                                        title="أرشفة الإضبارة"
                                        aria-label="أرشفة الإضبارة"
                                        data-testid="execution-smart-card-archive"
                                        onClick={(event) => handleToolbarAction(event, onRequestArchive)}
                                        onPointerDown={(event) => handleToolbarAction(event, undefined)}
                                        className={outlineIconActionClassName('accent')}
                                    >
                                        <Archive size={16} />
                                    </button>
                                ) : null}
                                {showTrash ? (
                                    <button
                                        type="button"
                                        title="نقل إلى سلة المهملات"
                                        aria-label="نقل إلى سلة المهملات"
                                        data-testid="execution-smart-card-trash"
                                        onClick={(event) => handleToolbarAction(event, onRequestMoveToTrash)}
                                        onPointerDown={(event) => handleToolbarAction(event, undefined)}
                                        className={outlineIconActionClassName('danger')}
                                    >
                                        <Trash2 size={16} />
                                    </button>
                                ) : null}
                                {showPermanentDelete ? (
                                    <button
                                        type="button"
                                        title="حذف نهائي"
                                        aria-label="حذف نهائي"
                                        data-testid="execution-smart-card-permanent-delete"
                                        onClick={(event) => handleToolbarAction(event, onRequestPermanentDelete)}
                                        className={outlineIconActionClassName('danger')}
                                    >
                                        <Trash2 size={16} />
                                    </button>
                                ) : null}
                            </div>
                        ) : null}
                        <div className="flex flex-col gap-1.5">
                            {variant === 'trash' && onRestoreFromTrash ? (
                                <button
                                    type="button"
                                    onClick={onRestoreFromTrash}
                                    className={`${outlineTextActionClassName('success')} w-full justify-center`}
                                >
                                    <RotateCcw size={12} />
                                    استرجاع
                                </button>
                            ) : null}
                            {variant === 'archived' && onRestoreFromArchive ? (
                                <button
                                    type="button"
                                    onClick={onRestoreFromArchive}
                                    className={`${outlineTextActionClassName('success')} w-full justify-center`}
                                >
                                    <RotateCcw size={12} />
                                    إعادة للنشطة
                                </button>
                            ) : null}
                            <button
                                type="button"
                                onClick={(event) => {
                                    event.stopPropagation();
                                    warmExecutionDossier('urgent');
                                    onPreview();
                                }}
                                className={`${outlineTextActionClassName('accent')} min-h-[36px] w-full justify-center`}
                            >
                                <Eye size={13} />
                                التفاصيل
                            </button>
                        </div>
                    </div>
                </div>
            </div>

            {isEvictionClaim(String(cardView.snap.claimType || cardView.snap.docType || '')) && (
                <div className="mb-3 space-y-1 rounded-2xl border border-blue-500/20 bg-blue-950/20 px-3 py-2 text-right">
                    <p className="text-[10px] font-semibold text-blue-300/90">العقار (من بيانات الإضبارة)</p>
                    <p className="text-[11px] text-slate-300">
                        رقم: {snapLoose.property_number || '—'} · المقاطعة: {snapLoose.district || '—'}
                    </p>
                    <p className="line-clamp-2 text-[11px] text-slate-400">
                        الصنف: {snapLoose.property_type || '—'} — {snapLoose.full_address || '—'}
                    </p>
                </div>
            )}

            <ExecutionArchivePartyBlock view={cardView} className="border-t border-slate-800/50 pt-3" />
            {cardView.relationship ? (
                <div className="mt-2.5 flex items-center justify-end gap-2 border-t border-purple-500/20 pt-2.5">
                    <span className="text-[11px] text-purple-200">
                        الصلة: <span className="font-bold">({cardView.relationship})</span> للمدين{' '}
                        <BiDiText className="font-bold">{cardView.linkedDebtorLabel}</BiDiText>
                    </span>
                    <Link2 size={12} className="shrink-0 text-purple-400" />
                </div>
            ) : null}
        </>
    );

    if (reduceMotion) {
        return (
            <div
                onPointerEnter={primeExecutionDossier}
                onPointerDown={handleCardPointerDown}
                onFocus={primeExecutionDossier}
                onClick={handleCardClick}
                className={cardClassName}
            >
                {cardBody}
            </div>
        );
    }

    return (
        <motion.div
            initial={false}
            animate={{ opacity: 1, y: 0 }}
            whileHover={reduceMotion ? undefined : { y: -6 }}
            onPointerEnter={primeExecutionDossier}
            onPointerDown={handleCardPointerDown}
            onFocus={primeExecutionDossier}
            onClick={handleCardClick}
            className={cardClassName}
        >
            {cardBody}
        </motion.div>
    );
}

export default ExecutionSmartCard;

