import React, { useState, useEffect, useCallback, useRef } from 'react';
import { ArrowRight, Search, Bell, ChevronDown, Users } from 'lucide-react';
import { AnimatePresence } from 'motion/react';
import { ForumCategoryPanel } from './ForumCategoryPanel';
import { RepositoryFilterPanel } from './RepositoryFilterPanel';
import { ForumSectionSwitch, type ForumSectionId } from './ForumSectionSwitch';
import { prefetchCommunitySearchOverlay } from '../communityOverlayPrefetch';
import { ForumNotificationsPanel } from './ForumNotificationsPanel';
import { useForumAppBarNotifications } from '../hooks/useForumAppBarNotifications';
import { FORUM_FILTER_LABELS } from '../forumFilters';
import {
    FORUM_APP_BAR,
    FORUM_APP_BAR_ICON,
    FORUM_REPO_SEARCH_BAR,
    FORUM_TEXT_APRICOT,
    FORUM_TEXT_PRIMARY,
} from '../forumPlumTheme';
import {
    repositoryFilterSummary,
    repositoryHasActiveListFilters,
    type RepositorySortKey,
} from '../repositoryListFilters';

interface ForumAppBarProps {
    onBack?: () => void;
    forumSurfaceOpen?: boolean;
    activeSection: ForumSectionId;
    onSectionChange: (section: ForumSectionId) => void;
    onSearchOpen: () => void;
    onNavigateToPost?: (postId: string) => void;
    userId?: string | null;
    selectedFilterIndex: number;
    onFilterSelect: (index: number) => void;
    repositorySearchTerm: string;
    onRepositorySearchTermChange: (value: string) => void;
    repositorySortBy: RepositorySortKey;
    onRepositorySortChange: (value: RepositorySortKey) => void;
    repositorySelectedType: string;
    onRepositoryTypeChange: (value: string) => void;
    repositorySelectedTag: string | null;
    onRepositoryTagChange: (tag: string | null) => void;
    groupsSearchQuery?: string;
    onGroupsSearchQueryChange?: (value: string) => void;
    followingCount?: number;
    onOpenFollowing?: () => void;
    forumFeedScope?: 'all' | 'following';
    onForumFeedScopeChange?: (scope: 'all' | 'following') => void;
    notificationStreamActive?: boolean;
    onAppBarDropdownChange?: (open: boolean) => void;
    closeAppBarDropdownsRef?: React.MutableRefObject<(() => void) | null>;
}

export const ForumAppBar = ({
    onBack,
    forumSurfaceOpen = true,
    activeSection,
    onSectionChange,
    onSearchOpen,
    onNavigateToPost,
    userId,
    selectedFilterIndex,
    onFilterSelect,
    repositorySearchTerm,
    onRepositorySearchTermChange,
    repositorySortBy,
    onRepositorySortChange,
    repositorySelectedType,
    onRepositoryTypeChange,
    repositorySelectedTag,
    onRepositoryTagChange,
    groupsSearchQuery = '',
    onGroupsSearchQueryChange,
    followingCount = 0,
    onOpenFollowing,
    forumFeedScope = 'all',
    onForumFeedScopeChange,
    notificationStreamActive = false,
    onAppBarDropdownChange,
    closeAppBarDropdownsRef,
}: ForumAppBarProps) => {
    const [showForumFilterPanel, setShowForumFilterPanel] = useState(false);
    const [showRepositoryFilterPanel, setShowRepositoryFilterPanel] = useState(false);
    const forumFilterTriggerRef = useRef<HTMLButtonElement>(null);
    const notif = useForumAppBarNotifications(
        userId,
        notificationStreamActive,
        onNavigateToPost,
        onSectionChange,
        forumSurfaceOpen,
    );
    const activeFilterLabel = FORUM_FILTER_LABELS[selectedFilterIndex] ?? FORUM_FILTER_LABELS[0];
    const hasForumFilter = selectedFilterIndex !== 0;
    const hasRepositoryFilter = repositoryHasActiveListFilters(
        repositorySelectedType,
        repositorySortBy,
        repositorySelectedTag,
    );
    const repositoryFilterHint = repositoryFilterSummary(
        repositorySelectedType,
        repositorySortBy,
        repositorySelectedTag,
    );

    useEffect(() => {
        setShowForumFilterPanel(false);
        setShowRepositoryFilterPanel(false);
    }, [activeSection]);

    useEffect(() => {
        if (forumSurfaceOpen) return;
        setShowForumFilterPanel(false);
        setShowRepositoryFilterPanel(false);
        notif.setShowNotifPanel(false);
        onAppBarDropdownChange?.(false);
        // eslint-disable-next-line react-hooks/exhaustive-deps -- إغلاق محلي عند hide السطح فقط
    }, [forumSurfaceOpen]);

    const handleBellClick = () => {
        setShowForumFilterPanel(false);
        setShowRepositoryFilterPanel(false);
        notif.handleBellClick(onAppBarDropdownChange);
    };

    const handleForumSearchOpen = () => {
        setShowForumFilterPanel(false);
        setShowRepositoryFilterPanel(false);
        notif.setShowNotifPanel(false);
        onAppBarDropdownChange?.(false);
        onSearchOpen();
    };

    const handleOpenFollowing = () => {
        setShowForumFilterPanel(false);
        setShowRepositoryFilterPanel(false);
        notif.setShowNotifPanel(false);
        onAppBarDropdownChange?.(false);
        onOpenFollowing?.();
    };

    const handleForumFilterToggle = () => {
        notif.setShowNotifPanel(false);
        setShowRepositoryFilterPanel(false);
        setShowForumFilterPanel((v) => {
            const next = !v;
            onAppBarDropdownChange?.(next);
            return next;
        });
    };

    const handleRepositoryFilterToggle = () => {
        notif.setShowNotifPanel(false);
        setShowForumFilterPanel(false);
        setShowRepositoryFilterPanel((v) => {
            const next = !v;
            onAppBarDropdownChange?.(next);
            return next;
        });
    };

    const closeAppBarDropdowns = useCallback(() => {
        notif.setShowNotifPanel(false);
        setShowForumFilterPanel(false);
        setShowRepositoryFilterPanel(false);
        onAppBarDropdownChange?.(false);
    }, [notif.setShowNotifPanel, onAppBarDropdownChange]);

    useEffect(() => {
        if (!closeAppBarDropdownsRef) return;
        closeAppBarDropdownsRef.current = closeAppBarDropdowns;
        return () => {
            closeAppBarDropdownsRef.current = null;
        };
    }, [closeAppBarDropdownsRef, closeAppBarDropdowns]);

    const searchPlaceholder =
        activeSection === 'forum'
            ? 'ابحث في المنتدى والمستودع...'
            : activeSection === 'groups'
              ? 'ابحث عن مجموعة...'
              : 'ابحث في المستندات، الوسوم، المؤلف...';

    return (
        <div className={FORUM_APP_BAR} data-testid="forum-app-bar">
            <div className="px-4 pt-3 pb-2 flex items-center justify-between gap-3">
                <div className="flex items-center gap-2 min-w-0 flex-1">
                    {onBack ? (
                        <button
                            type="button"
                            data-testid="forum-back"
                            onClick={onBack}
                            className={`${FORUM_APP_BAR_ICON} text-[#9AA3B2] hover:text-[#C9A86C] shrink-0`}
                            aria-label="رجوع"
                        >
                            <ArrowRight size={20} />
                        </button>
                    ) : null}
                    <h1 className={`${FORUM_TEXT_PRIMARY} font-bold text-base sm:text-lg truncate leading-tight`}>
                        منتدى الزملاء المغلق
                    </h1>
                </div>

                <div className="flex items-center gap-2 shrink-0">
                    {activeSection === 'forum' && onOpenFollowing ? (
                        <button
                            type="button"
                            data-testid="forum-following-trigger"
                            onClick={handleOpenFollowing}
                            aria-label="المتابَعون"
                            className={`${FORUM_APP_BAR_ICON} relative ${
                                forumFeedScope === 'following'
                                    ? 'bg-[#C9A86C]/14 text-[#C9A86C] border border-[#C9A86C]/30'
                                    : 'text-[#9AA3B2] hover:text-[#C9A86C]'
                            }`}
                        >
                            <Users size={18} />
                            {followingCount > 0 ? (
                                <span className="absolute -bottom-0.5 -left-0.5 min-w-[16px] h-4 px-0.5 flex items-center justify-center bg-[#C9A86C] text-[#0A0F1C] text-[9px] font-bold rounded-full">
                                    {followingCount > 9 ? '9+' : followingCount}
                                </span>
                            ) : null}
                        </button>
                    ) : null}
                    <div className="relative">
                        <button
                            type="button"
                            data-testid="forum-notifications-trigger"
                            onClick={handleBellClick}
                            aria-label="التنبيهات"
                            aria-expanded={notif.showNotifPanel}
                            className={`${FORUM_APP_BAR_ICON} text-[#9AA3B2] hover:text-[#C9A86C] relative`}
                        >
                            <Bell size={20} />
                            {notif.unreadCount > 0 ? (
                                <span className="absolute -top-0.5 -right-0.5 min-w-[18px] h-[18px] flex items-center justify-center bg-red-500 text-white text-[10px] font-bold rounded-full px-1 shadow-lg">
                                    {notif.unreadCount > 99 ? '99+' : notif.unreadCount}
                                </span>
                            ) : null}
                        </button>

                        <ForumNotificationsPanel
                            open={notif.showNotifPanel}
                            unreadCount={notif.unreadCount}
                            refreshing={notif.refreshingNotifs}
                            notifications={notif.notifications}
                            onClose={() => {
                                notif.setShowNotifPanel(false);
                                onAppBarDropdownChange?.(false);
                            }}
                            onMarkAllRead={() => void notif.handleMarkAllRead()}
                            onNotificationClick={(n) => void notif.handleNotificationClick(n)}
                            onNotificationDismiss={(n) => void notif.handleNotificationDismiss(n)}
                        />
                    </div>
                </div>
            </div>

            <div className="px-4 pb-2">
                <ForumSectionSwitch activeSection={activeSection} onSectionChange={onSectionChange} />
            </div>

            <div className="px-4 pb-3 relative">
                <div className="flex items-center gap-2">
                    <div className={`${FORUM_REPO_SEARCH_BAR} flex-1 min-w-0`}>
                        <div className="flex flex-1 items-center gap-2 px-3 min-w-0">
                            <Search size={17} className="text-[#9AA3B2] shrink-0" aria-hidden />
                            {activeSection === 'forum' ? (
                                <button
                                    type="button"
                                    data-testid="forum-search-trigger"
                                    onClick={handleForumSearchOpen}
                                    onPointerEnter={prefetchCommunitySearchOverlay}
                                    onFocus={prefetchCommunitySearchOverlay}
                                    className="w-full text-right text-sm text-[#9AA3B2] truncate py-2"
                                    aria-label="بحث في المنتدى والمستودع"
                                >
                                    {searchPlaceholder}
                                </button>
                            ) : activeSection === 'groups' ? (
                                <input
                                    type="search"
                                    value={groupsSearchQuery}
                                    onChange={(e) => onGroupsSearchQueryChange?.(e.target.value)}
                                    placeholder={searchPlaceholder}
                                    aria-label="بحث في المجموعات"
                                    data-testid="forum-groups-search"
                                    className="w-full bg-transparent text-[#F3F0EA] text-sm placeholder-[#9AA3B2]/55 outline-none"
                                />
                            ) : (
                                <input
                                    type="search"
                                    value={repositorySearchTerm}
                                    onChange={(e) => onRepositorySearchTermChange(e.target.value)}
                                    placeholder={searchPlaceholder}
                                    aria-label="بحث في المستودع"
                                    data-testid="forum-repository-search"
                                    className="w-full bg-transparent text-[#F3F0EA] text-sm placeholder-[#9AA3B2]/55 outline-none"
                                />
                            )}
                        </div>

                        {activeSection === 'forum' ? (
                            <>
                                <div className="w-px h-6 bg-slate-800/80 shrink-0" aria-hidden />
                                <button
                                    ref={forumFilterTriggerRef}
                                    type="button"
                                    onClick={handleForumFilterToggle}
                                    aria-label="تصنيفات المنتدى"
                                    aria-expanded={showForumFilterPanel}
                                    className={`relative h-11 px-3 flex items-center gap-1.5 shrink-0 transition-colors ${
                                        showForumFilterPanel || hasForumFilter
                                            ? `${FORUM_TEXT_APRICOT} bg-[#C9A86C]/10`
                                            : 'text-[#9AA3B2] hover:text-[#C9A86C] hover:bg-[#C9A86C]/08'
                                    }`}
                                >
                                    <span className="truncate text-xs font-bold">التصنيف</span>
                                    {hasForumFilter ? (
                                        <span className="max-w-[64px] truncate rounded-full bg-[#C9A86C]/12 px-2 py-0.5 text-[10px] leading-none">
                                            {activeFilterLabel}
                                        </span>
                                    ) : null}
                                    <ChevronDown
                                        size={14}
                                        className={`transition-transform duration-200 ${showForumFilterPanel ? 'rotate-180' : ''}`}
                                    />
                                </button>
                            </>
                        ) : null}

                        {activeSection === 'repository' ? (
                            <>
                                <div className="w-px h-6 bg-slate-800/80 shrink-0" aria-hidden />
                                <button
                                    type="button"
                                    onClick={handleRepositoryFilterToggle}
                                    aria-label="ترتيب وتصفية المستودع"
                                    aria-expanded={showRepositoryFilterPanel}
                                    className={`relative h-11 px-3 flex items-center gap-1.5 shrink-0 transition-colors ${
                                        showRepositoryFilterPanel || hasRepositoryFilter
                                            ? `${FORUM_TEXT_APRICOT} bg-[#C9A86C]/10`
                                            : 'text-[#9AA3B2] hover:text-[#C9A86C] hover:bg-[#C9A86C]/08'
                                    }`}
                                >
                                    <ChevronDown
                                        size={16}
                                        className={`transition-transform duration-200 ${showRepositoryFilterPanel ? 'rotate-180' : ''}`}
                                    />
                                    {hasRepositoryFilter ? (
                                        <span className="max-w-[88px] truncate text-[10px] font-bold leading-none">
                                            {repositoryFilterHint}
                                        </span>
                                    ) : null}
                                </button>
                            </>
                        ) : null}
                    </div>
                </div>

                <AnimatePresence>
                    {showForumFilterPanel ? (
                        <>
                            <div
                                className="fixed inset-0 z-40"
                                onClick={() => setShowForumFilterPanel(false)}
                                aria-hidden
                            />
                            <ForumCategoryPanel
                                key="forum-category-panel"
                                selectedFilterIndex={selectedFilterIndex}
                                onFilterSelect={onFilterSelect}
                                onClose={() => setShowForumFilterPanel(false)}
                                anchorRef={forumFilterTriggerRef}
                            />
                        </>
                    ) : null}
                </AnimatePresence>

                <AnimatePresence>
                    {showRepositoryFilterPanel ? (
                        <>
                            <div
                                className="fixed inset-0 z-40"
                                onClick={() => setShowRepositoryFilterPanel(false)}
                                aria-hidden
                            />
                            <RepositoryFilterPanel
                                key="repository-filter-panel"
                                sortBy={repositorySortBy}
                                selectedType={repositorySelectedType}
                                selectedTag={repositorySelectedTag}
                                onSortChange={onRepositorySortChange}
                                onTypeChange={onRepositoryTypeChange}
                                onTagChange={onRepositoryTagChange}
                                onClose={() => setShowRepositoryFilterPanel(false)}
                            />
                        </>
                    ) : null}
                </AnimatePresence>
            </div>
        </div>
    );
};

import React, { useCallback, useState } from 'react';
import { createPortal } from 'react-dom';
import { motion } from 'motion/react';
import { useReduceMotion } from '@/app/hooks/useReduceMotion';
import { UserCheck, UserMinus, Bell, MessageCircle, Reply, X } from 'lucide-react';
import type { ForumFollowRecord } from '@/app/services/forum/forumFollowTypes';
import {
    FORUM_ICON_BTN,
    FORUM_PANEL,
    FORUM_TEXT_APRICOT,
    FORUM_TEXT_MUTED,
    FORUM_TEXT_PRIMARY,
} from '../forumPlumTheme';

type ForumFollowingPanelProps = {
    open: boolean;
    onClose: () => void;
    following: ForumFollowRecord[];
    followers: Array<{ followerId: string; createdAt: string }>;
    authorNames: Record<string, string>;
    onUnfollow: (userId: string) => void;
    onFollowBack?: (userId: string) => void;
    onUpdatePrefs: (
        userId: string,
        prefs: Partial<Pick<ForumFollowRecord, 'notifyPosts' | 'notifyComments' | 'notifyReplies'>>,
    ) => void;
    onOpenFollowingFeed: () => void;
    onOpenProfile?: (userId: string, displayName?: string) => void;
};

function PrefToggle({
    label,
    icon: Icon,
    checked,
    onChange,
}: {
    label: string;
    icon: React.ElementType;
    checked: boolean;
    onChange: (v: boolean) => void;
}) {
    return (
        <label className="flex items-center justify-between gap-2 py-1.5 cursor-pointer">
            <span className="flex items-center gap-1.5 text-[11px] text-white/55">
                <Icon size={12} className="text-[#C9A86C]/70" aria-hidden />
                {label}
            </span>
            <input
                type="checkbox"
                checked={checked}
                onChange={(e) => onChange(e.target.checked)}
                className="w-4 h-4 accent-[#C9A86C]"
            />
        </label>
    );
}

export const ForumFollowingPanel = function ForumFollowingPanel({
    open,
    onClose,
    following,
    followers,
    authorNames,
    onUnfollow,
    onFollowBack,
    onUpdatePrefs,
    onOpenFollowingFeed,
    onOpenProfile,
}: ForumFollowingPanelProps) {
    const [expandedId, setExpandedId] = useState<string | null>(null);
    const [tab, setTab] = useState<'following' | 'followers'>('following');
    const reduceMotion = useReduceMotion();

    const requestClose = useCallback(() => {
        onClose();
    }, [onClose]);

    const sheetTransition = reduceMotion
        ? { duration: 0 }
        : { type: 'tween' as const, duration: 0.18, ease: [0.32, 0, 0.67, 0] as const };

    const panelLayer = (
        <>
            <motion.div
                key="following-backdrop"
                initial={reduceMotion ? false : { opacity: 0 }}
                animate={{ opacity: 1 }}
                transition={sheetTransition}
                className="fixed inset-0 z-[96] bg-black/50"
                onClick={requestClose}
                aria-hidden
            />
            <motion.div
                key="following-sheet"
                data-testid="forum-following-panel"
                initial={reduceMotion ? false : { y: '100%' }}
                animate={{ y: 0 }}
                transition={sheetTransition}
                        className={`fixed inset-x-0 bottom-0 z-[97] max-h-[78dvh] rounded-t-[24px] ${FORUM_PANEL} shadow-2xl flex flex-col pb-[env(safe-area-inset-bottom)]`}
                        role="dialog"
                        aria-modal="true"
                        aria-label="قائمة المتابعة"
                        dir="rtl"
            >
                        <div className="w-10 h-1 rounded-full bg-white/20 mx-auto mt-3 mb-2" aria-hidden />
                        <div className="px-4 pb-3 flex items-center justify-between gap-3 border-b border-[#2A3344]/40">
                            <div>
                                <h3 className={`${FORUM_TEXT_PRIMARY} font-bold text-sm`}>المتابعة</h3>
                                <p className={`${FORUM_TEXT_MUTED} text-[11px] mt-0.5`}>
                                    {tab === 'following'
                                        ? `${following.length} محامٍ تتابعهم`
                                        : `${followers.length} يتابعونك`}
                                </p>
                            </div>
                            <div className="flex items-center gap-2">
                                {tab === 'following' && following.length > 0 ? (
                                    <button
                                        type="button"
                                        onClick={() => {
                                            onOpenFollowingFeed();
                                            requestClose();
                                        }}
                                        className={`${FORUM_TEXT_APRICOT} text-[11px] font-bold px-3 py-1.5 rounded-lg bg-[#C9A86C]/10 border border-[#C9A86C]/25`}
                                    >
                                        عرض منشوراتهم
                                    </button>
                                ) : null}
                                <button
                                    type="button"
                                    onClick={requestClose}
                                    aria-label="إغلاق"
                                    className={FORUM_ICON_BTN}
                                >
                                    <X size={16} />
                                </button>
                            </div>
                        </div>

                        <div className="px-4 pt-2 flex gap-1">
                            {(['following', 'followers'] as const).map((key) => (
                                <button
                                    key={key}
                                    type="button"
                                    onClick={() => setTab(key)}
                                    className={`flex-1 py-2 rounded-lg text-[11px] font-bold transition-colors ${
                                        tab === key
                                            ? 'bg-[#C9A86C]/14 text-[#C9A86C] border border-[#C9A86C]/25'
                                            : 'text-white/45 border border-transparent'
                                    }`}
                                >
                                    {key === 'following' ? 'أتابعهم' : 'متابِعوني'}
                                </button>
                            ))}
                        </div>

                        <div className="flex-1 overflow-y-auto px-4 py-3 space-y-2">
                            {tab === 'following' ? (
                            following.length === 0 ? (
                                <div className="py-10 text-center">
                                    <UserCheck size={32} className="text-[#C9A86C]/30 mx-auto mb-3" />
                                    <p className={`${FORUM_TEXT_PRIMARY} text-sm font-bold mb-1`}>لا تتابع أحداً بعد</p>
                                    <p className={`${FORUM_TEXT_MUTED} text-xs`}>
                                        اضغط «متابعة» على بطاقة أي محامٍ لتصلك تنبيهات نشاطه
                                    </p>
                                </div>
                            ) : (
                                following.map((row) => {
                                    const name = authorNames[row.followingId] ?? 'محامٍ';
                                    const expanded = expandedId === row.followingId;
                                    return (
                                        <div
                                            key={row.followingId}
                                            className="rounded-xl hami-forum-panel overflow-hidden"
                                        >
                                            <div className="flex items-center gap-2 px-3 py-2.5">
                                                <div className="w-9 h-9 rounded-full bg-[#C9A86C]/12 border border-[#C9A86C]/25 flex items-center justify-center text-[#C9A86C] text-xs font-bold shrink-0">
                                                    {name.slice(0, 1)}
                                                </div>
                                                <button
                                                    type="button"
                                                    onClick={() => {
                                                        if (onOpenProfile) {
                                                            onOpenProfile(row.followingId, name);
                                                            requestClose();
                                                            return;
                                                        }
                                                        setExpandedId(expanded ? null : row.followingId);
                                                    }}
                                                    className="flex-1 min-w-0 text-right"
                                                >
                                                    <p className={`${FORUM_TEXT_PRIMARY} text-xs font-bold truncate`}>
                                                        {name}
                                                    </p>
                                                    <p className={`${FORUM_TEXT_MUTED} text-[10px]`}>
                                                        {onOpenProfile
                                                            ? 'عرض الملف الشخصي'
                                                            : expanded
                                                              ? 'إخفاء التفضيلات'
                                                              : 'تخصيص التنبيهات'}
                                                    </p>
                                                </button>
                                                {onOpenProfile ? (
                                                    <button
                                                        type="button"
                                                        onClick={() =>
                                                            setExpandedId(expanded ? null : row.followingId)
                                                        }
                                                        className="w-8 h-8 rounded-lg bg-white/[0.04] border border-white/10 flex items-center justify-center text-white/45"
                                                        title="تخصيص التنبيهات"
                                                        aria-label="تخصيص التنبيهات"
                                                    >
                                                        <Bell size={14} />
                                                    </button>
                                                ) : null}
                                                <button
                                                    type="button"
                                                    onClick={() => onUnfollow(row.followingId)}
                                                    className="w-8 h-8 rounded-lg bg-red-950/30 border border-red-500/20 flex items-center justify-center text-red-300"
                                                    title="إلغاء المتابعة"
                                                >
                                                    <UserMinus size={14} />
                                                </button>
                                            </div>
                                            {expanded ? (
                                                <div className="px-3 pb-3 pt-1 border-t border-[#2A3344]/30">
                                                    <PrefToggle
                                                        label="منشورات جديدة"
                                                        icon={Bell}
                                                        checked={row.notifyPosts}
                                                        onChange={(v) =>
                                                            onUpdatePrefs(row.followingId, { notifyPosts: v })
                                                        }
                                                    />
                                                    <PrefToggle
                                                        label="تعليقات على منشوراته"
                                                        icon={MessageCircle}
                                                        checked={row.notifyComments}
                                                        onChange={(v) =>
                                                            onUpdatePrefs(row.followingId, { notifyComments: v })
                                                        }
                                                    />
                                                    <PrefToggle
                                                        label="ردود في نقاشاته"
                                                        icon={Reply}
                                                        checked={row.notifyReplies}
                                                        onChange={(v) =>
                                                            onUpdatePrefs(row.followingId, { notifyReplies: v })
                                                        }
                                                    />
                                                </div>
                                            ) : null}
                                        </div>
                                    );
                                })
                            )
                            ) : followers.length === 0 ? (
                                <div className="py-10 text-center">
                                    <UserCheck size={32} className="text-[#C9A86C]/30 mx-auto mb-3" />
                                    <p className={`${FORUM_TEXT_PRIMARY} text-sm font-bold mb-1`}>لا متابعين بعد</p>
                                    <p className={`${FORUM_TEXT_MUTED} text-xs`}>عندما يتابعك محامٍ سيظهر هنا</p>
                                </div>
                            ) : (
                                followers.map((row) => {
                                    const name = authorNames[row.followerId] ?? 'محامٍ';
                                    return (
                                        <div
                                            key={row.followerId}
                                            className="rounded-xl hami-forum-panel px-3 py-2.5 flex items-center gap-2"
                                        >
                                            <div className="w-9 h-9 rounded-full bg-[#C9A86C]/12 border border-[#C9A86C]/25 flex items-center justify-center text-[#C9A86C] text-xs font-bold shrink-0">
                                                {name.slice(0, 1)}
                                            </div>
                                            <div className="flex-1 min-w-0">
                                                {onOpenProfile ? (
                                                    <button
                                                        type="button"
                                                        onClick={() => {
                                                            onOpenProfile(row.followerId, name);
                                                            requestClose();
                                                        }}
                                                        className="text-right w-full"
                                                    >
                                                        <p className={`${FORUM_TEXT_PRIMARY} text-xs font-bold truncate`}>{name}</p>
                                                        <p className={`${FORUM_TEXT_MUTED} text-[10px]`}>عرض الملف الشخصي</p>
                                                    </button>
                                                ) : (
                                                    <>
                                                        <p className={`${FORUM_TEXT_PRIMARY} text-xs font-bold truncate`}>{name}</p>
                                                        <p className={`${FORUM_TEXT_MUTED} text-[10px]`}>متابِع لك</p>
                                                    </>
                                                )}
                                            </div>
                                            {onFollowBack ? (
                                                <button
                                                    type="button"
                                                    onClick={() => onFollowBack(row.followerId)}
                                                    className={`${FORUM_TEXT_APRICOT} text-[10px] font-bold px-2.5 py-1.5 rounded-lg bg-[#C9A86C]/10 border border-[#C9A86C]/25`}
                                                >
                                                    متابعة
                                                </button>
                                            ) : null}
                                        </div>
                                    );
                                })
                            )}
                        </div>
            </motion.div>
        </>
    );

    return typeof document !== 'undefined' ? createPortal(panelLayer, document.body) : panelLayer;
}

import { useCallback, useEffect, useMemo, useState } from 'react';

import { SmartToast } from '@/app/components/ui/SmartToast';
import type { CommunityPost } from '@/app/services/lawyer-cloud';
import { ForumApiService } from '@/app/services/forumApiService';
import type { ForumGroup } from '@/app/services/forum/forumGroupTypes';
import { sortCommunityPosts } from '@/app/services/cloud/lawyerCommunityCloud';
import { COMMUNITY_POSTS_PAGE_SIZE, COMMUNITY_GROUP_POSTS_MAX_RETAINED } from '../communityScreenConstants';
import type { CommunitySection } from '../communitySectionState';
import type { CommunityDualPostLists } from './useCommunityDualPostLists';
import {
    computeGroupVisiblePosts,
    mergeSortedCommunityPosts,
    normalizeCommunityPostsPage,
    trimCommunityPostsRetention,
} from './communityPostFeedUtils';
import { withForumAsyncTimeout } from '../forumAsync';
import { createForumGroupResilient } from '../forumGroupCreate';

export type UseCommunityGroupsFeedParams = {
    lists: Pick<CommunityDualPostLists, 'groupPosts' | 'setGroupPosts' | 'groupPostsRef'>;
    mutedIds: Set<string>;
    currentUserId: string | null;
    authIsLoading: boolean;
    activeSection: CommunitySection;
};

export function useCommunityGroupsFeed({
    lists,
    mutedIds,
    currentUserId,
    authIsLoading,
    activeSection,
}: UseCommunityGroupsFeedParams) {
    const { groupPosts, setGroupPosts, groupPostsRef } = lists;
    const [groups, setGroups] = useState<ForumGroup[]>([]);
    const [groupsLoading, setGroupsLoading] = useState(false);
    const [groupsSearchQuery, setGroupsSearchQuery] = useState('');
    const [activeGroupId, setActiveGroupId] = useState<string | null>(null);
    const [groupPostsLoading, setGroupPostsLoading] = useState(false);
    const [groupPostsHasMore, setGroupPostsHasMore] = useState(true);
    const [groupPostsLoadingMore, setGroupPostsLoadingMore] = useState(false);
    const [isCreateGroupOpen, setIsCreateGroupOpen] = useState(false);
    const [newGroupName, setNewGroupName] = useState('');
    const [newGroupDesc, setNewGroupDesc] = useState('');
    const [submittingGroup, setSubmittingGroup] = useState(false);
    const [joiningGroupId, setJoiningGroupId] = useState<string | null>(null);
    const [leavingGroup, setLeavingGroup] = useState(false);
    const pageSize = COMMUNITY_POSTS_PAGE_SIZE;

    const applyGroupPostsUpdate = useCallback(
        (updater: (prev: CommunityPost[]) => CommunityPost[]) => {
            setGroupPosts((prev) =>
                trimCommunityPostsRetention(updater(prev), COMMUNITY_GROUP_POSTS_MAX_RETAINED),
            );
        },
        [setGroupPosts],
    );

    useEffect(() => {
        if (authIsLoading || activeGroupId) return;
        let cancelled = false;
        setGroupsLoading(true);
        void withForumAsyncTimeout(ForumApiService.listGroups(groupsSearchQuery), 8_000, [])
            .then((rows) => {
                if (!cancelled) setGroups(rows);
            })
            .catch(() => {
                if (!cancelled) SmartToast.error('تعذّر تحميل المجموعات');
            })
            .finally(() => {
                if (!cancelled) setGroupsLoading(false);
            });
        return () => {
            cancelled = true;
        };
    }, [authIsLoading, activeGroupId, groupsSearchQuery]);

    useEffect(() => {
        if (!activeGroupId) {
            setGroupPosts([]);
            setGroupPostsHasMore(true);
            return;
        }
        let cancelled = false;
        setGroupPostsLoading(true);
        void ForumApiService.listPostsPaginated(pageSize, 0, { groupId: activeGroupId })
            .then(({ posts: page }) => {
                if (cancelled) return;
                setGroupPosts(
                    trimCommunityPostsRetention(
                        sortCommunityPosts(normalizeCommunityPostsPage(page)),
                        COMMUNITY_GROUP_POSTS_MAX_RETAINED,
                    ),
                );
                setGroupPostsHasMore(page.length === pageSize);
            })
            .catch(() => {
                if (!cancelled) SmartToast.error('تعذّر تحميل منشورات المجموعة');
            })
            .finally(() => {
                if (!cancelled) setGroupPostsLoading(false);
            });
        return () => {
            cancelled = true;
        };
    }, [activeGroupId, pageSize, setGroupPosts]);

    const activeGroup = useMemo(
        () => (activeGroupId ? groups.find((g) => g.id === activeGroupId) ?? null : null),
        [activeGroupId, groups],
    );

    const groupVisiblePosts = useMemo(
        () => computeGroupVisiblePosts(groupPosts, mutedIds, currentUserId),
        [groupPosts, mutedIds, currentUserId],
    );

    const clearActiveGroup = useCallback(() => setActiveGroupId(null), []);

    const handleJoinGroup = useCallback(
        async (groupId: string) => {
            if (!currentUserId) {
                SmartToast.warning('سجّل الدخول للانضمام');
                return;
            }
            setJoiningGroupId(groupId);
            try {
                const updated = await ForumApiService.joinGroup(groupId, currentUserId);
                setGroups((prev) => prev.map((g) => (g.id === groupId ? updated : g)));
                SmartToast.success('انضممت للمجموعة');
            } catch (err) {
                const message =
                    err instanceof Error && err.message.trim()
                        ? err.message
                        : 'تعذّر الانضمام للمجموعة';
                SmartToast.error(message);
            } finally {
                setJoiningGroupId(null);
            }
        },
        [currentUserId],
    );

    const handleOpenGroup = useCallback(
        (groupId: string) => {
            const group = groups.find((g) => g.id === groupId);
            if (!group?.isMember) return;
            setActiveGroupId(groupId);
        },
        [groups],
    );

    const handleLeaveGroup = useCallback(async () => {
        if (!activeGroupId) return;
        setLeavingGroup(true);
        try {
            await ForumApiService.leaveGroup(activeGroupId, currentUserId);
            setActiveGroupId(null);
            const rows = await ForumApiService.listGroups(groupsSearchQuery);
            setGroups(rows);
            SmartToast.success('غادرت المجموعة');
        } catch (err) {
            const message =
                err instanceof Error && err.message.trim()
                    ? err.message
                    : 'تعذّر مغادرة المجموعة';
            SmartToast.error(message);
        } finally {
            setLeavingGroup(false);
        }
    }, [activeGroupId, currentUserId, groupsSearchQuery]);

    const handleCreateGroup = useCallback(async () => {
        const name = newGroupName.trim();
        const description = newGroupDesc.trim();
        if (!currentUserId) {
            SmartToast.warning('سجّل الدخول لإنشاء مجموعة');
            return;
        }
        if (name.length < 3) {
            SmartToast.warning('اسم المجموعة قصير جداً (3 أحرف على الأقل)');
            return;
        }
        if (description.length < 10) {
            SmartToast.warning('اكتب وصفاً أوضح للمجموعة (10 أحرف على الأقل)');
            return;
        }
        setSubmittingGroup(true);
        try {
            const group = await createForumGroupResilient({ name, description }, currentUserId);
            setGroups((prev) => [group, ...prev.filter((g) => g.id !== group.id)]);
            setIsCreateGroupOpen(false);
            setNewGroupName('');
            setNewGroupDesc('');
            SmartToast.success('تم إنشاء المجموعة');
        } catch (err) {
            const message =
                err instanceof Error && err.message.trim()
                    ? err.message
                    : 'تعذّر إنشاء المجموعة';
            SmartToast.error(message);
        } finally {
            setSubmittingGroup(false);
        }
    }, [currentUserId, newGroupDesc, newGroupName]);

    const handleLoadMoreGroupPosts = useCallback(async () => {
        if (!activeGroupId || groupPostsLoadingMore || !groupPostsHasMore) return;
        setGroupPostsLoadingMore(true);
        try {
            const { posts: nextPage } = await ForumApiService.listPostsPaginated(
                pageSize,
                groupPostsRef.current.length,
                { groupId: activeGroupId },
            );
            applyGroupPostsUpdate((prev) => mergeSortedCommunityPosts(prev, nextPage));
            setGroupPostsHasMore(nextPage.length === pageSize);
        } catch {
            SmartToast.error('تعذّر تحميل المزيد');
        } finally {
            setGroupPostsLoadingMore(false);
        }
    }, [
        activeGroupId,
        applyGroupPostsUpdate,
        groupPostsHasMore,
        groupPostsLoadingMore,
        groupPostsRef,
        pageSize,
    ]);

    const appendPublishedGroupPost = useCallback(
        (saved: CommunityPost) => {
            applyGroupPostsUpdate((prev) => mergeSortedCommunityPosts(prev, [saved]));
        },
        [applyGroupPostsUpdate],
    );

    return {
        groups,
        groupsLoading,
        groupsSearchQuery,
        setGroupsSearchQuery,
        activeGroupId,
        setActiveGroupId,
        clearActiveGroup,
        activeGroup,
        groupPostsLoading,
        groupPostsHasMore,
        groupPostsLoadingMore,
        groupVisiblePosts,
        isCreateGroupOpen,
        setIsCreateGroupOpen,
        newGroupName,
        setNewGroupName,
        newGroupDesc,
        setNewGroupDesc,
        submittingGroup,
        joiningGroupId,
        leavingGroup,
        handleJoinGroup,
        handleOpenGroup,
        handleLeaveGroup,
        handleCreateGroup,
        handleLoadMoreGroupPosts,
        appendPublishedGroupPost,
    };
}

