            followingIds,
            bookmarkedIds,
            handleToggleBookmark,
            handleCopyPostText,
            handleSavePostToVault,
            handleSavePostToDevice,
            handleToggleLock,
            handleMuteUser,
            userStats,
            threadFollowingIds,
            handleToggleThreadFollow,
            activeGroupId,
            activeGroup,
            handleLeaveGroup,
            leavingGroup,
            groupPostsLoading,
            groupPostsHasMore,
            groupPostsLoadingMore,
            groupVisiblePosts,
            handleLoadMoreGroupPosts,
            setActiveGroupId,
            groups,
            groupsLoading,
            groupsSearchQuery,
            setGroupsSearchQuery,
            handleJoinGroup,
            handleOpenGroup,
            setIsCreateGroupOpen,
            joiningGroupId,
            openAddQuestion,
            activePostForComments,
            mutedIds,
            forumMentionCandidates,
            setCommentingPostId,
            handleAddComment,
            handleToggleBestAnswer,
            handleDeleteComment,
            handleEditComment,
            handleToggleCommentUpvote,
            handleReportComment,
            isSearchOpen,
            searchQuery,
            setSearchQuery,
            filterHasPdf,
