            filterHasImage,
            setFilterHasImage,
            selectedTag,
            setSelectedTag,
            allSearchTags,
            filteredPosts,
            filteredRepositoryDocs,
            handleSearchOpenPost,
            handleSearchOpenDocument,
            isAddQuestionOpen,
            newPostText,
            setNewPostText,
            newTagText,
            setNewTagText,
