            newIsUrgent,
            setNewIsUrgent,
            newAttachment,
            removeAttachment,
            submittingPost,
            isRecordingVoice,
            voiceRecordingSec,
            imageInputRef,
            docInputRef,
            toggleVoiceRecording,
            handleUploadAttachment,
            handleAddPost,
            closeAddQuestion,
            fullscreenImage,
            setFullscreenImage,
            isCreateGroupOpen,
            newGroupName,
            newGroupDesc,
            submittingGroup,
            setNewGroupName,
            setNewGroupDesc,
            handleCreateGroup,
            editingPostId,
            editingText,
            setEditingText,
            handleSaveEdit,
            setEditingPostId,
            savingEdit,
