import { useMemo } from 'react';
import { formatDateText } from '../../utils/formatters';
import { maxYmd } from '../../utils/ymd';
import type { UseOrderFileLifecycleDerivedArgs } from './types';

export type GrievancePhase = { effectiveJudgeDecision: string | null; effectiveJudgeDecisionDate: string; effectiveRejectionNotificationDate: string; judgePhaseComplete: boolean; showGrievanceLifecycle: boolean };

export function useGrievanceWizardDerived(args: UseOrderFileLifecycleDerivedArgs, phase: GrievancePhase) {
    const {
        caseData,
        judgeDecision,
        grievanceData,
        grievanceDecision,
        cassationData,
        cassationDecision,
        hearings,
        hearingDraft,
        expertModule,
        phase2FirstHearingDate,
        grievanceLegalEndDate,
        setGrievanceLegalEndDate,
        grievanceTimingConfirmed,
        grievanceDetailsConfirmed,
        grievanceExpiredConfirmed,
        cassationExpiredConfirmed,
        editGrievance,
        requestDateYmd,
        todayYmdValue,
        hasIntervention,
        isFinalized,
        isFinalityNoGrievance,
        defenderPhase2ReadOnly,
        showGrievanceStep,
        isIqrarContext,
        partyLabel,
        computedGrievanceFiledBy,
        computedCassationFiledBy,
        showPreDecisionHearings,
    } = args;
    const { effectiveJudgeDecision, effectiveJudgeDecisionDate, effectiveRejectionNotificationDate, judgePhaseComplete, showGrievanceLifecycle } = phase;

    const grievanceLegalEndMinYmd = useMemo(() => {
    const jd = String(effectiveJudgeDecisionDate || '').trim();
    const jdY = /^\d{4}-\d{2}-\d{2}$/.test(jd) ? jd : '';
    if (!hasIntervention) {
        const n = String(effectiveRejectionNotificationDate || '').trim();
        const nY = /^\d{4}-\d{2}-\d{2}$/.test(n) ? n : '';
        return maxYmd(maxYmd(requestDateYmd, jdY), nY);
    }
    return maxYmd(requestDateYmd, jdY);
}, [
    effectiveJudgeDecisionDate,
    effectiveRejectionNotificationDate,
    hasIntervention,
    requestDateYmd,
]);
const grievanceLegalEndDateChronologyError = useMemo(() => {
    const end = String(grievanceLegalEndDate || '').trim();
    const minD = grievanceLegalEndMinYmd;
    if (!end || !minD) return null;
    if (end < minD) return '⚠️ تاريخ انتهاء المدة يجب ألا يسبق التبليغ أو تاريخ القرار أو تقديم الطلب';
    return null;
}, [grievanceLegalEndDate, grievanceLegalEndMinYmd]);
const grievanceTimingGateReady = useMemo(() => {
    if (!judgeDecision.decision) return false;
    const end = String(grievanceLegalEndDate || '').trim();
    if (!end) return false;
    if (grievanceLegalEndDateChronologyError) return false;
    if (hasIntervention) return true;
    return !!effectiveRejectionNotificationDate;
}, [
    effectiveRejectionNotificationDate,
    grievanceLegalEndDate,
    grievanceLegalEndDateChronologyError,
    hasIntervention,
    judgeDecision.decision,
]);
/** قفل نهائي — لا يُقفل مسار الجلسات لمجرد تسجيل outcome=filed قبل قرار قاضي التظلم */
const grievanceWizardLocked = useMemo(() => {
    if (isFinalized) return true;
    if (!editGrievance && !!caseData?.grievanceDecision) return true;
    if (!editGrievance && caseData?.grievanceOutcome === 'expired') return true;
    return false;
}, [caseData?.grievanceDecision, caseData?.grievanceOutcome, editGrievance, isFinalized]);
const grievanceAllowDecisionEntry = useMemo(() => {
    return caseData?.grievanceOutcome === 'filed' && !caseData?.grievanceDecision;
}, [caseData?.grievanceDecision, caseData?.grievanceOutcome]);
const grievanceWizardInputsLocked = useMemo(() => {
    return grievanceWizardLocked && !grievanceAllowDecisionEntry;
}, [grievanceAllowDecisionEntry, grievanceWizardLocked]);
const grievanceDecisionLocked = useMemo(() => {
    if (!grievanceTimingConfirmed) return false;
    if (grievanceData.outcome === 'expired') return true;
    if (grievanceData.outcome === 'filed' && grievanceDetailsConfirmed) return true;
    return false;
}, [grievanceData.outcome, grievanceDetailsConfirmed, grievanceTimingConfirmed]);
const grievanceInHearings = useMemo(() => {
    return grievanceTimingConfirmed && grievanceData.outcome === 'filed' && grievanceDetailsConfirmed;
}, [grievanceData.outcome, grievanceDetailsConfirmed, grievanceTimingConfirmed]);
const grievanceLockedSummaryText = useMemo(() => {
    if (!grievanceDecisionLocked) return '';
    const tokens: string[] = [];
    if (!hasIntervention) {
        tokens.push(`📌 التبليغ: ${formatDateText(grievanceData.rejectionNotificationDate) || '—'}`);
    }
    tokens.push(`الانتهاء: ${formatDateText(grievanceLegalEndDate) || '—'}`);
    if (grievanceData.outcome === 'expired') {
        tokens.push('التظلم: لا');
    } else if (grievanceData.outcome === 'filed') {
        const who = partyLabel(computedGrievanceFiledBy);
        const when = formatDateText(grievanceData.filingDate) || '—';
        tokens.push(`التظلم: نعم (${who} في ${when})`);
    }
    return tokens.join(' | ');
}, [
    computedGrievanceFiledBy,
    grievanceData.filingDate,
    grievanceData.outcome,
    grievanceData.rejectionNotificationDate,
    grievanceDecisionLocked,
    grievanceLegalEndDate,
    hasIntervention,
    partyLabel,
]);
const grievanceExpiredCanClose = useMemo(() => {
    const end = String(grievanceLegalEndDate || '').trim();
    if (!/^\d{4}-\d{2}-\d{2}$/.test(end)) return false;
    return todayYmdValue > end;
}, [grievanceLegalEndDate, todayYmdValue]);

    const grievanceProceedingsClosed = useMemo(() => {
    const tokens = ['ختام المرافعة', 'ختام وتعيين يوم للقرار', 'ختام المرافعة وتحديد موعد القرار'];
    const latest = hearings
        .filter((h) => h.stage === 'grievance')
        .sort((a, b) => String(b.createdAt || '').localeCompare(String(a.createdAt || '')))[0];
    if (!latest) return false;
    const notes = String(latest.notes || '');
    return tokens.some((t) => notes.includes(t));
}, [hearings]);
const grievanceOutcomeSelected =
    grievanceData.outcome === 'filed' || grievanceData.outcome === 'expired';
const showGrievanceTimingForm = !grievanceTimingConfirmed;
const showGrievanceTimingSummary = grievanceTimingConfirmed;
const showGrievanceOutcomeForm = grievanceTimingConfirmed && !grievanceOutcomeSelected;
const showGrievanceOutcomeSummary = grievanceTimingConfirmed && grievanceOutcomeSelected;
const showGrievanceDetailsForm =
    grievanceTimingConfirmed && grievanceData.outcome === 'filed' && !grievanceDetailsConfirmed;
const showGrievanceDetailsSummary =
    grievanceTimingConfirmed && grievanceData.outcome === 'filed' && grievanceDetailsConfirmed;
const showGrievanceDecisionForm = grievanceInHearings && grievanceProceedingsClosed;
const showGrievanceFinalizeButton = useMemo(() => {
    if (isFinalized || defenderPhase2ReadOnly) return false;
    if (!!caseData?.grievanceDecision) return false;
    if (caseData?.grievanceOutcome === 'expired' && (caseData?.status === 'completed' || caseData?.phase === 'completed')) {
        return false;
    }
    return true;
}, [
    caseData?.grievanceDecision,
    caseData?.grievanceOutcome,
    caseData?.phase,
    caseData?.status,
    defenderPhase2ReadOnly,
    isFinalized,
]);

    return {
        grievanceLegalEndMinYmd,
        grievanceLegalEndDateChronologyError,
        grievanceTimingGateReady,
        grievanceWizardInputsLocked,
        grievanceInHearings,
        grievanceLockedSummaryText,
        grievanceExpiredCanClose,
        grievanceProceedingsClosed,
        showGrievanceTimingForm,
        showGrievanceTimingSummary,
        showGrievanceOutcomeForm,
        showGrievanceOutcomeSummary,
        showGrievanceDetailsForm,
        showGrievanceDetailsSummary,
        showGrievanceDecisionForm,
        showGrievanceFinalizeButton,
    };
}

import { useMemo } from 'react';
import { getActiveDate } from '@/app/utils/hearingDates';
import {
    isAdjournReasonValid,
    isGrievancePleadingClosedSession,
    isPreDecisionCloseNotes,
    isPreDecisionNullifyNotes,
} from '../../utils/hearingRules';
import { maxYmd } from '../../utils/ymd';
import type { UseOrderFileLifecycleDerivedArgs } from './types';

export type ChronologyPhase = { effectiveJudgeDecisionDate: string };

export function useHearingChronologyDerived(args: UseOrderFileLifecycleDerivedArgs, phase: ChronologyPhase) {
    const {
        caseData,
        judgeDecision,
        grievanceData,
        grievanceDecision,
        cassationData,
        cassationDecision,
        hearings,
        hearingDraft,
        expertModule,
        phase2FirstHearingDate,
        grievanceLegalEndDate,
        setGrievanceLegalEndDate,
        grievanceTimingConfirmed,
        grievanceDetailsConfirmed,
        grievanceExpiredConfirmed,
        cassationExpiredConfirmed,
        editGrievance,
        requestDateYmd,
        todayYmdValue,
        hasIntervention,
        isFinalized,
        isFinalityNoGrievance,
        defenderPhase2ReadOnly,
        showGrievanceStep,
        isIqrarContext,
        partyLabel,
        computedGrievanceFiledBy,
        computedCassationFiledBy,
        showPreDecisionHearings,
    } = args;
    const { effectiveJudgeDecisionDate } = phase;

    const intakeFirstHearingDate = useMemo(() => {
    return String((caseData as any)?.firstHearingDate ?? '')
        .trim()
        .match(/^(\d{4}-\d{2}-\d{2})/)?.[1] ?? '';
}, [(caseData as any)?.firstHearingDate]);

const phase1Sessions = useMemo(() => hearings.filter((h) => h.stage === 'pre_decision'), [hearings]);
const phase2Sessions = useMemo(() => hearings.filter((h) => h.stage === 'grievance'), [hearings]);
const phase1ActiveDate = useMemo(
    () => getActiveDate(phase1Sessions, intakeFirstHearingDate),
    [phase1Sessions, intakeFirstHearingDate],
);
const phase2ActiveDate = useMemo(
    () => getActiveDate(phase2Sessions, phase2FirstHearingDate),
    [phase2Sessions, phase2FirstHearingDate],
);
const grievanceFirstHearingAnchorYmd = useMemo(() => {
    return String((caseData as any)?.grievanceFirstHearingDate ?? phase2FirstHearingDate ?? '')
        .trim()
        .match(/^(\d{4}-\d{2}-\d{2})/)?.[1] ?? '';
}, [(caseData as any)?.grievanceFirstHearingDate, phase2FirstHearingDate]);
const showGrievancePhase2AdjournBanner = useMemo(() => {
    return (
        phase2Sessions.length > 0 &&
        !!String(phase2ActiveDate || '').trim() &&
        !!grievanceFirstHearingAnchorYmd &&
        String(phase2ActiveDate) !== grievanceFirstHearingAnchorYmd
    );
}, [grievanceFirstHearingAnchorYmd, phase2ActiveDate, phase2Sessions.length]);
const grievanceHearingsSorted = useMemo(() => {
    return [...phase2Sessions].sort((a, b) => String(a.sessionDate || '').localeCompare(String(b.sessionDate || '')));
}, [phase2Sessions]);

const phase1PleadingClosedLatestSessionYmd = useMemo(() => {
    let best = '';
    for (const h of phase1Sessions) {
        const notes = String(h.notes || '');
        if (isPreDecisionNullifyNotes(notes)) continue;
        if (!isPreDecisionCloseNotes(notes)) continue;
        const d = String(h.sessionDate || '').trim();
        if (!/^\d{4}-\d{2}-\d{2}$/.test(d)) continue;
        if (!best || d > best) best = d;
    }
    return best;
}, [phase1Sessions]);

const phase1ChronologicalSessionMaxYmd = useMemo(() => {
    let best = '';
    for (const h of phase1Sessions) {
        const d = String(h.sessionDate || '').trim();
        if (!/^\d{4}-\d{2}-\d{2}$/.test(d)) continue;
        if (!best || d > best) best = d;
    }
    return best;
}, [phase1Sessions]);

const phase1NewSessionMinYmd = useMemo(
    () => maxYmd(maxYmd(requestDateYmd, intakeFirstHearingDate), phase1ChronologicalSessionMaxYmd),
    [requestDateYmd, intakeFirstHearingDate, phase1ChronologicalSessionMaxYmd],
);

const phase1JudgeDecisionMinYmd = useMemo(
    () => phase1PleadingClosedLatestSessionYmd || requestDateYmd || '',
    [phase1PleadingClosedLatestSessionYmd, requestDateYmd],
);

const phase2PleadingClosedLatestSessionYmd = useMemo(() => {
    let best = '';
    for (const h of phase2Sessions) {
        if (!isGrievancePleadingClosedSession(h)) continue;
        const d = String(h.sessionDate || '').trim();
        if (!/^\d{4}-\d{2}-\d{2}$/.test(d)) continue;
        if (!best || d > best) best = d;
    }
    return best;
}, [phase2Sessions]);

const phase2ChronologicalSessionMaxYmd = useMemo(() => {
    let best = '';
    for (const h of phase2Sessions) {
        const d = String(h.sessionDate || '').trim();
        if (!/^\d{4}-\d{2}-\d{2}$/.test(d)) continue;
        if (!best || d > best) best = d;
    }
    return best;
}, [phase2Sessions]);

const grievanceFilingYmd = useMemo(() => {
    const d = String(grievanceData.filingDate || '').trim();
    return /^\d{4}-\d{2}-\d{2}$/.test(d) ? d : '';
}, [grievanceData.filingDate]);

const phase2NewSessionMinYmd = useMemo(
    () => maxYmd(maxYmd(grievanceFilingYmd, grievanceFirstHearingAnchorYmd), phase2ChronologicalSessionMaxYmd),
    [grievanceFilingYmd, grievanceFirstHearingAnchorYmd, phase2ChronologicalSessionMaxYmd],
);

const grievanceFilingMinYmd = useMemo(() => {
    const jd = String(effectiveJudgeDecisionDate || '').trim();
    const jdY = /^\d{4}-\d{2}-\d{2}$/.test(jd) ? jd : '';
    return jdY || requestDateYmd;
}, [effectiveJudgeDecisionDate, requestDateYmd]);

const grievanceFirstHearingMinYmd = useMemo(
    () => maxYmd(grievanceFilingYmd, grievanceFilingMinYmd),
    [grievanceFilingMinYmd, grievanceFilingYmd],
);

const grievanceDecisionMinYmd = useMemo(
    () => maxYmd(maxYmd(phase2PleadingClosedLatestSessionYmd, grievanceFilingYmd), grievanceFilingMinYmd),
    [grievanceFilingMinYmd, grievanceFilingYmd, phase2PleadingClosedLatestSessionYmd],
);

const judgeDecisionDateChronologyError = useMemo(() => {
    const d = String(judgeDecision.decisionDate || '').trim();
    const minD = phase1JudgeDecisionMinYmd;
    if (!d || !minD) return null;
    if (d < minD) return '⚠️ تاريخ القرار يجب ألا يسبق ختام المرافعة أو تاريخ تقديم الطلب';
    return null;
}, [judgeDecision.decisionDate, phase1JudgeDecisionMinYmd]);

const grievanceFilingDateChronologyError = useMemo(() => {
    const f = grievanceFilingYmd;
    const minD = grievanceFilingMinYmd;
    if (!f || !minD) return null;
    if (f < minD) return '⚠️ تاريخ التظلم يجب ألا يسبق تاريخ قرار المرحلة الأولى';
    return null;
}, [grievanceFilingMinYmd, grievanceFilingYmd]);

const grievanceFirstHearingDateChronologyError = useMemo(() => {
    const p2 = grievanceFirstHearingAnchorYmd;
    const minD = grievanceFirstHearingMinYmd;
    if (!p2 || !minD) return null;
    if (p2 < minD) return '⚠️ تاريخ جلسة التظلم الأولى يجب ألا يسبق تاريخ التظلم أو القرار';
    return null;
}, [grievanceFirstHearingAnchorYmd, grievanceFirstHearingMinYmd]);

const grievanceDecisionDateChronologyError = useMemo(() => {
    const d = String(grievanceDecision.decisionDate || '').trim();
    const minD = grievanceDecisionMinYmd;
    if (!d || !minD) return null;
    if (d < minD) return '⚠️ تاريخ قرار التظلم يجب ألا يسبق ختام المرافعة أو تاريخ التظلم';
    return null;
}, [grievanceDecision.decisionDate, grievanceDecisionMinYmd]);

const decisionNotificationQuickLogMinYmd = useMemo(() => {
    const jd = String(effectiveJudgeDecisionDate || '').trim();
    const jdY = /^\d{4}-\d{2}-\d{2}$/.test(jd) ? jd : '';
    return maxYmd(requestDateYmd, jdY);
}, [effectiveJudgeDecisionDate, requestDateYmd]);

const grievanceClosingHearingExists = useMemo(() => {
    const tokens = ['ختام المرافعة', 'ختام وتعيين يوم للقرار', 'ختام المرافعة وتحديد موعد القرار'];
    return hearings.some((h) => {
        if (h.stage !== 'grievance') return false;
        const notes = String(h.notes || '');
        if (isPreDecisionNullifyNotes(notes)) return false;
        if (tokens.some((t) => notes.includes(t))) return true;
        return !String(h.nextSessionDate || '').trim();
    });
}, [hearings]);
const hearingDraftSessionDateError = useMemo(() => {
    const stage = hearingDraft.stage;
    const session = String(hearingDraft.sessionDate || '').trim();
    if (!session) return null;
    if (stage === 'pre_decision') {
        const minS = phase1NewSessionMinYmd;
        if (minS && session < minS) return '⚠️ تاريخ الجلسة يجب أن يكون بعد/مساوٍ لآخر تاريخ في المسار (تقديم الطلب / جلسات سابقة)';
    }
    if (stage === 'grievance') {
        const minS = phase2NewSessionMinYmd;
        if (minS && session < minS) return '⚠️ تاريخ الجلسة يجب أن يكون بعد/مساوٍ لتاريخ التظلم وجلسة التظلم الأولى والجلسات السابقة';
        const filing = String(grievanceData.filingDate || '').trim();
        if (filing && session < filing) return '⚠️ تاريخ الجلسة يجب أن يكون بعد/مساوٍ لتاريخ تقديم التظلم';
    }
    return null;
}, [
    grievanceData.filingDate,
    hearingDraft.sessionDate,
    hearingDraft.stage,
    phase1NewSessionMinYmd,
    phase2NewSessionMinYmd,
]);
const hearingDraftNextSessionDateError = useMemo(() => {
    if (hearingDraft.outcome !== 'adjourn') return null;
    const session = String(hearingDraft.sessionDate || '').trim();
    const next = String(hearingDraft.nextSessionDate || '').trim();
    if (!session || !next) return null;
    if (next < session) return '⚠️ موعد الجلسة القادمة يجب أن يكون بعد/مساوٍ لتاريخ الجلسة';
    return null;
}, [hearingDraft.nextSessionDate, hearingDraft.outcome, hearingDraft.sessionDate]);
const hearingDraftAdjournReasonError = useMemo(() => {
    if (hearingDraft.outcome !== 'adjourn') return null;
    const notes = String(hearingDraft.notes || '').trim();
    if (!notes) return null;
    if (!isAdjournReasonValid(notes)) return 'سبب التأجيل يجب أن يحتوي على نص وليس أرقاماً فقط';
    return null;
}, [hearingDraft.notes, hearingDraft.outcome]);

    return {
        intakeFirstHearingDate,
        phase1Sessions,
        phase1ActiveDate,
        phase2ActiveDate,
        grievanceFirstHearingAnchorYmd,
        showGrievancePhase2AdjournBanner,
        grievanceHearingsSorted,
        phase1NewSessionMinYmd,
        phase1JudgeDecisionMinYmd,
        phase2NewSessionMinYmd,
        grievanceFilingMinYmd,
        grievanceFirstHearingMinYmd,
        grievanceDecisionMinYmd,
        judgeDecisionDateChronologyError,
        grievanceFilingDateChronologyError,
        grievanceFirstHearingDateChronologyError,
        grievanceDecisionDateChronologyError,
        decisionNotificationQuickLogMinYmd,
        grievanceClosingHearingExists,
        hearingDraftSessionDateError,
        hearingDraftNextSessionDateError,
        hearingDraftAdjournReasonError,
    };
}

import { useMemo } from 'react';

import type { UseOrderFileLifecycleDerivedArgs } from './types';

export function useLifecyclePhaseDerived(args: UseOrderFileLifecycleDerivedArgs) {
    const {
        caseData,
        judgeDecision,
        fileStatus,
        grievanceData,
        isFinalized,
        isFinalityNoGrievance,
        showGrievanceStep,
        isIqrarContext,
    } = args;

    const effectiveJudgeDecision = judgeDecision.decision ?? (caseData as any)?.judgeDecision ?? null;
    const effectiveJudgeDecisionDate = String(
        judgeDecision.decisionDate || (caseData as any)?.judgeDecisionDate || '',
    ).trim();
    const persistedJudgeDecision = String((caseData as any)?.judgeDecision ?? '').trim();
    const persistedJudgeDate = String((caseData as any)?.judgeDecisionDate ?? '').trim();
    const judgePhaseSaved =
        (persistedJudgeDecision && persistedJudgeDate) || fileStatus !== 'pending' || isFinalized;

    const defenderStateOrderSummaryDate = useMemo(() => {
        const s = String((caseData as any)?.stateOrderIssuedDate || '').trim();
        return s.match(/^(\d{4}-\d{2}-\d{2})/)?.[1] ?? '';
    }, [(caseData as any)?.stateOrderIssuedDate]);

    const grievancePhaseStarted =
        !!caseData?.grievanceOutcome || !!caseData?.grievanceDecision || isFinalityNoGrievance;

    const grievanceEligible =
        persistedJudgeDecision === 'rejected' ||
        persistedJudgeDecision === 'accepted' ||
        persistedJudgeDecision === 'partially_accepted' ||
        grievancePhaseStarted;

    const showGrievanceLifecycle =
        showGrievanceStep && judgePhaseSaved && grievanceEligible;

    const grievancePhaseClosed =
        !!caseData?.grievanceDecision ||
        caseData?.grievanceOutcome === 'expired' ||
        isFinalityNoGrievance ||
        (isFinalized && persistedJudgeDecision === 'rejected') ||
        !!caseData?.cassationOutcome ||
        !!caseData?.cassationDecision;

    const showCassationLifecycle = useMemo(() => {
        if (isIqrarContext) return false;
        if (!showGrievanceStep) {
            return judgePhaseSaved || !!caseData?.cassationOutcome || !!caseData?.cassationDecision || isFinalized;
        }
        if (!grievancePhaseClosed) return false;
        const cassationReached =
            !!caseData?.cassationOutcome ||
            !!caseData?.cassationDecision ||
            (caseData as any)?.legalState === 'Awaiting_Cassation' ||
            isFinalized;
        return cassationReached;
    }, [caseData, grievancePhaseClosed, isFinalized, isIqrarContext, judgePhaseSaved, showGrievanceStep]);

    const effectiveRejectionNotificationDate = useMemo(() => {
        return String(grievanceData.rejectionNotificationDate || (caseData as any)?.notificationDate || '').trim();
    }, [caseData, grievanceData.rejectionNotificationDate]);

    const judgePhaseComplete = !!effectiveJudgeDecision && !!effectiveJudgeDecisionDate;

    return {
        effectiveJudgeDecision,
        effectiveJudgeDecisionDate,
        defenderStateOrderSummaryDate,
        judgePhaseComplete,
        showGrievanceLifecycle,
        showCassationLifecycle,
        effectiveRejectionNotificationDate,
    };
}

import { useMemo } from 'react';
import { getPreDecisionHearingOutcome, getPreDecisionSessionOutcome } from '../../utils/hearingRules';
import {
    PRE_DECISION_OUTCOME_ADJOURN,
    PRE_DECISION_OUTCOME_CLOSE,
    PRE_DECISION_OUTCOME_NULLIFY,
} from '../../constants/hearingOutcomes';
import type { PreDecisionHearingOutcomeKind } from '../../types';
import type { UseOrderFileLifecycleDerivedArgs } from './types';



export function usePreDecisionDerived(args: UseOrderFileLifecycleDerivedArgs) {
    const {
        caseData,
        judgeDecision,
        grievanceData,
        grievanceDecision,
        cassationData,
        cassationDecision,
        hearings,
        hearingDraft,
        expertModule,
        phase2FirstHearingDate,
        grievanceLegalEndDate,
        setGrievanceLegalEndDate,
        grievanceTimingConfirmed,
        grievanceDetailsConfirmed,
        grievanceExpiredConfirmed,
        cassationExpiredConfirmed,
        editGrievance,
        requestDateYmd,
        todayYmdValue,
        hasIntervention,
        isFinalized,
        isFinalityNoGrievance,
        defenderPhase2ReadOnly,
        showGrievanceStep,
        isIqrarContext,
        partyLabel,
        computedGrievanceFiledBy,
        computedCassationFiledBy,
        showPreDecisionHearings,
    } = args;
    

    const preDecisionHearingsSorted = useMemo(() => {
    return [...hearings]
        .filter((h) => h.stage === 'pre_decision')
        .sort((a, b) => String(a.sessionDate || '').localeCompare(String(b.sessionDate || '')));
}, [hearings]);
/** جلسات ما قبل القرار — index 0 = الأحدث (createdAt) */
const sessions = useMemo(
    () =>
        [...preDecisionHearingsSorted]
            .sort((a, b) => String(b.createdAt || '').localeCompare(String(a.createdAt || '')))
            .map((session) => ({
                ...session,
                outcome: getPreDecisionSessionOutcome(String(session.notes || ''), session.nextSessionDate),
            })),
    [preDecisionHearingsSorted],
);
const hasSessions = sessions.length > 0;
const latestOutcome = hasSessions ? sessions[0].outcome : null;
const isAdjourned = latestOutcome === PRE_DECISION_OUTCOME_ADJOURN;
const isConcluded = latestOutcome === PRE_DECISION_OUTCOME_CLOSE;
const isNullified = latestOutcome === PRE_DECISION_OUTCOME_NULLIFY;
const isCaseTerminated = isConcluded || isNullified;
const preDecisionTerminalKind = useMemo((): 'close' | 'nullify' | null => {
    if (!isCaseTerminated) return null;
    if (isNullified) return 'nullify';
    if (isConcluded) return 'close';
    return null;
}, [isCaseTerminated, isConcluded, isNullified]);
const preDecisionSessionCount = sessions.length;
const latestPreDecisionHearing = useMemo(() => {
    return [...hearings]
        .filter((h) => h.stage === 'pre_decision')
        .sort((a, b) => String(b.createdAt || '').localeCompare(String(a.createdAt || '')))[0] ?? null;
}, [hearings]);
const latestPreDecisionOutcome = useMemo((): PreDecisionHearingOutcomeKind | 'none' => {
    if (!latestPreDecisionHearing) return 'none';
    return getPreDecisionHearingOutcome(latestPreDecisionHearing);
}, [latestPreDecisionHearing]);
const isPreDecisionSessionModalOpen =
    hearingDraft.open && hearingDraft.stage === 'pre_decision' && !isCaseTerminated;
/** بلا سجل جلسات (مسار غيابي خالص): قرار مباشر. مع سجل الجلسات: القرار فقط بعد ختام المرافعة أو إبطال — لا يُعرض مع الجلسات */
const showDecisionAtTop =
    !showPreDecisionHearings && !hasSessions && !isPreDecisionSessionModalOpen;
const showDecisionAtBottom =
    showPreDecisionHearings &&
    hasSessions &&
    (isConcluded || isNullified) &&
    !isPreDecisionSessionModalOpen;
/** مسار الجلسات: القرار أسفل السجل فقط بعد ختام/إبطال. مسار بلا جلسات: قرار مباشر */
const showJudgeDecisionBlock = showPreDecisionHearings ? showDecisionAtBottom : showDecisionAtTop;
const showJudgeDecisionTerminateOnly = isNullified;
const showJudgeDecisionFullForm = showJudgeDecisionBlock && (showDecisionAtTop || isConcluded);

    return {
        preDecisionHearingsSorted,
        hasSessions,
        latestOutcome,
        isAdjourned,
        isCaseTerminated,
        preDecisionTerminalKind,
        showJudgeDecisionBlock,
        showJudgeDecisionTerminateOnly,
        showJudgeDecisionFullForm,
    };
}

import { useMemo } from 'react';
import type { UseOrderFileLifecycleDerivedArgs } from './types';

export function useWorkspaceInsightsDerived(args: UseOrderFileLifecycleDerivedArgs) {
    const { caseData, hearings, expertModule, todayYmdValue, isFinalized } = args;

    const dayStart = (d: Date) => new Date(d.getFullYear(), d.getMonth(), d.getDate());
    const daysDiff = (from: Date, to: Date) => {
        const msPerDay = 24 * 60 * 60 * 1000;
        return Math.round((dayStart(to).getTime() - dayStart(from).getTime()) / msPerDay);
    };

    const nextHearingDate = useMemo(() => {
        const candidates = hearings
            .map((h) => String(h.nextSessionDate || '').trim())
            .filter((d) => /^\d{4}-\d{2}-\d{2}$/.test(d) && d >= todayYmdValue)
            .sort((a, b) => a.localeCompare(b));
        return candidates[0] ?? '';
    }, [hearings, todayYmdValue]);

    const reportDueSoon = useMemo(() => {
        if (!expertModule.enabled) return false;
        if (!expertModule.reportDueDate) return false;
        if (expertModule.reportReceivedDate) return false;
        const due = new Date(expertModule.reportDueDate);
        if (Number.isNaN(due.getTime())) return false;
        const days = daysDiff(new Date(), due);
        return days >= 0 && days <= 3;
    }, [expertModule.enabled, expertModule.reportDueDate, expertModule.reportReceivedDate]);

    const archiveSummaryText = useMemo(() => {
        if (!isFinalized) return '';
        const reason = String((caseData as any)?.finalityReason || (caseData as any)?.archivedReason || '').trim();
        if (reason === 'terminated_request') return 'إبطال الطلب وإغلاق الإضبارة';
        if (reason === 'iqrar_authenticated') return 'إقرار مؤرشف — تم إصدار حجة الإقرار والمصادقة';
        if (reason === 'cassation_decision') return 'انتهاء مرحلة التمييز وصدور القرار';
        if (reason === 'expired') return 'انقضاء المدة القانونية دون إجراء';
        if (reason === 'no_grievance') return 'اكتساب الدرجة القطعية دون تظلم';
        return 'إنهاء الإضبارة وأرشفتها';
    }, [caseData, isFinalized]);

    return { nextHearingDate, reportDueSoon, archiveSummaryText };
}

import { useMemo } from 'react';
import { isIqrarRequest } from '@/app/domain/urgent/formPathwayConstants';
import { resolveProcedureCategory } from '@/app/domain/urgent/procedureCategory';
import { isPreDecisionNullifyNotes } from '../utils/hearingRules';

export type UseOrderFileCasePathwayArgs = {
    caseData: any;
    fd: Record<string, unknown>;
    fileStatus: import('../types').FileStatus;
    activeLifecycleStep: 'judge' | 'execution' | 'grievance' | 'cassation' | null;
    judgeDecision: import('../types').JudgeDecision;
    grievanceDecision: import('../types').GrievanceDecision;
    hearings: import('../types').CaseHearing[];
    preDecisionClosed: boolean;
};

export function useOrderFileCasePathway({
    caseData,
    fd,
    fileStatus,
    activeLifecycleStep,
    judgeDecision,
    grievanceDecision,
    hearings,
    preDecisionClosed,
}: UseOrderFileCasePathwayArgs) {
    const shouldSkipExecutionStep = useMemo(() => {
        const procedureType = String(caseData?.type ?? fd?.type ?? '').trim();
        const t = String(caseData?.specificActionType ?? '').trim();
        if (procedureType === 'state_order') return true;
        return ['وضع إشارة', 'منع سفر', 'إيقاف', 'حجز'].some((k) => t.includes(k));
    }, [caseData?.specificActionType, caseData?.type, fd?.type]);

    // 🔥 STATUS BADGE CONFIGURATION
    const getStatusConfig = () => {
        const finalized =
            !!caseData?.archived || (caseData as any)?.status === 'completed' || (caseData as any)?.phase === 'completed';
        if (finalized) {
            return {
                icon: '✅',
                text: 'اكتسب الدرجة القطعية / منتهي',
                color: 'green',
                gradient: 'from-emerald-500/20 to-green-500/20',
                borderColor: 'border-emerald-500/35',
                pulse: false,
            };
        }

        const cassationActive =
            caseData?.cassationOutcome === 'filed' ||
            !!caseData?.cassationDecision ||
            fileStatus === 'cassation' ||
            activeLifecycleStep === 'cassation';
        if (cassationActive) {
            return {
                icon: '⚖️',
                text: 'في مرحلة الطعن التمييزي',
                color: 'purple',
                gradient: 'from-violet-500/20 to-purple-500/20',
                borderColor: 'border-violet-500/35',
                pulse: true,
            };
        }

        const localShowGrievanceStep = String(caseData?.type ?? fd?.type ?? '').trim() !== 'urgent_action';
        const grievanceActive =
            localShowGrievanceStep &&
            (caseData?.grievanceOutcome === 'filed' ||
                !!caseData?.grievanceDecision ||
                fileStatus === 'grievance' ||
                activeLifecycleStep === 'grievance');
        if (grievanceActive) {
            return {
                icon: '⚖️',
                text: 'في مرحلة التظلم',
                color: 'purple',
                gradient: 'from-purple-500/20 to-fuchsia-500/20',
                borderColor: 'border-purple-500/35',
                pulse: true,
            };
        }

        const executionActive =
            !shouldSkipExecutionStep &&
            (judgeDecision.decision === 'accepted' || judgeDecision.decision === 'partially_accepted') &&
            fileStatus === 'accepted';
        if (executionActive) {
            return {
                icon: '⚡',
                text: 'قيد المفاتحة والتبليغ',
                color: 'blue',
                gradient: 'from-blue-500/20 to-cyan-500/20',
                borderColor: 'border-blue-500/35',
                pulse: true,
            };
        }

        if (preDecisionClosed && !judgeDecision.decision) {
            return {
                icon: '⏳',
                text: 'بانتظار النطق بالقرار',
                color: 'amber',
                gradient: 'from-amber-500/20 to-orange-500/20',
                borderColor: 'border-amber-500/40',
                pulse: true,
            };
        }

        const hasHearings = hearings.some((h) => h.stage === 'pre_decision');
        if (hasHearings && !preDecisionClosed) {
            return {
                icon: '🔄',
                text: 'قيد المرافعة',
                color: 'slate',
                gradient: 'from-slate-500/20 to-blue-500/10',
                borderColor: 'border-slate-400/30',
                pulse: true,
            };
        }

        return {
            icon: '🟡',
            text: 'قيد انتظار قرار القاضي',
            color: 'amber',
            gradient: 'from-amber-500/20 to-yellow-500/20',
            borderColor: 'border-amber-500/50',
            pulse: true,
        };
    };

    const statusConfig = getStatusConfig();

    const requestTypeText = useMemo(() => {
        return String(caseData?.actionPath ?? caseData?.pathwayTitle ?? '').trim();
    }, [caseData?.actionPath, caseData?.pathwayTitle]);
    const resolvedWorkspaceRequestType = useMemo(() => {
        return String(caseData?.specificActionType ?? caseData?.actionPath ?? '').trim();
    }, [caseData?.specificActionType, caseData?.actionPath]);
    const isIqrar = useMemo(() => isIqrarRequest(resolvedWorkspaceRequestType), [resolvedWorkspaceRequestType]);
    const isIqrarContext = isIqrar;
    const procedureDetailsForPopover = useMemo(() => {
        const details = String((caseData as any)?.procedureDetails ?? '').trim();
        const subject = String((caseData as any)?.requestSubject ?? '').trim();
        if (isIqrarContext) return subject || details;
        return details || subject;
    }, [caseData, isIqrarContext]);

    const partyLabel = (role: 'client' | 'opponent' | null) => {
        if (isIqrarContext) {
            if (role === 'client') return 'المُقَر له (المستفيد طالب الإقرار)';
            if (role === 'opponent') return 'المُقِر (المعترف بالحق)';
        }
        if (role === 'client') return 'المستدعي';
        if (role === 'opponent') return 'المطلوب ضده';
        return '—';
    };
    const oppositeRole = (role: 'client' | 'opponent') => (role === 'client' ? 'opponent' : 'client');
    const isUrgentLawsuit = useMemo(() => {
        const t = requestTypeText;
        if (t.includes('قضاء مستعجل') || t.includes('القضاء المستعجل') || t.includes('دعوى مستعجلة') || t.includes('مستعجلة')) return true;
        return String(caseData?.type ?? '') === 'urgent_action';
    }, [caseData?.type, requestTypeText]);
    const isOrderOnPetition = useMemo(() => {
        if (isUrgentLawsuit) return false;
        const t = requestTypeText;
        if (t.includes('أمر ولائي') || t.includes('أمر على') || t.includes('عريضة') || t.includes('عرائض') || t.includes('أمر')) return true;
        return String(caseData?.type ?? '') === 'state_order';
    }, [caseData?.type, isUrgentLawsuit, requestTypeText]);
    const isStateOrder = useMemo(() => {
        return String(caseData?.type ?? fd?.type ?? '').trim() === 'state_order';
    }, [caseData?.type, fd?.type]);
    const isUrgentJustice = useMemo(() => {
        return isUrgentLawsuit || String(caseData?.type ?? '').trim() === 'urgent_justice';
    }, [caseData?.type, isUrgentLawsuit]);
    const procedureCategory = useMemo(
        () =>
            resolveProcedureCategory(
                (caseData as { procedureCategory?: string })?.procedureCategory,
                resolvedWorkspaceRequestType,
            ),
        [(caseData as { procedureCategory?: string })?.procedureCategory, resolvedWorkspaceRequestType],
    );
    const showGrievanceStep = procedureCategory === 'petition_orders' && !isIqrarContext;
    const grievanceStepNumber = 2;
    const cassationStepNumber = showGrievanceStep ? 3 : 2;
    const showInitialNotification = isUrgentLawsuit;
    /** Phase 42 — جلسات ما قبل القرار خاصة بالدعاوى المدنية فقط؛ الأوامر/الحجج تنتقل مباشرة لقرار القاضي */
    const showPreDecisionHearings = false;
    const preDecisionTerminateExists = useMemo(() => {
        return hearings.some((h) => h.stage === 'pre_decision' && isPreDecisionNullifyNotes(String(h.notes || '')));
    }, [hearings]);

    const computedGrievanceFiledBy = useMemo((): 'client' | 'opponent' | null => {
        if (judgeDecision.decision === 'rejected') return 'client';
        if (judgeDecision.decision === 'accepted' || judgeDecision.decision === 'partially_accepted') return 'opponent';
        return null;
    }, [judgeDecision.decision]);

    const computedCassationFiledBy = useMemo((): 'client' | 'opponent' | null => {
        if (!computedGrievanceFiledBy) return null;
        if (!showGrievanceStep) return computedGrievanceFiledBy;
        if (!grievanceDecision.decision) return null;
        if (grievanceDecision.decision === 'confirmed') return computedGrievanceFiledBy;
        return oppositeRole(computedGrievanceFiledBy);
    }, [computedGrievanceFiledBy, grievanceDecision.decision, showGrievanceStep, oppositeRole]);

    return {
        shouldSkipExecutionStep,
        statusConfig,
        requestTypeText,
        resolvedWorkspaceRequestType,
        isIqrar,
        isIqrarContext,
        procedureDetailsForPopover,
        partyLabel,
        oppositeRole,
        isUrgentLawsuit,
        isOrderOnPetition,
        isStateOrder,
        isUrgentJustice,
        procedureCategory,
        showGrievanceStep,
        grievanceStepNumber,
        cassationStepNumber,
        showInitialNotification,
        showPreDecisionHearings,
        preDecisionTerminateExists,
        computedGrievanceFiledBy,
        computedCassationFiledBy,
    };
}

import { useEffect, useRef, useState } from 'react';
import type {
    CaseAttachment,
    CaseEvent,
    CaseFollowup,
    CaseHearing,
    CaseNote,
    CassationData,
    CassationDecision,
    ExecutionData,
    ExpertModule,
    FileStatus,
    GrievanceData,
    GrievanceDecision,
    HearingStage,
    JudgeDecision,
} from '../types';

export type HearingDraftState = {
    open: boolean;
    stage: HearingStage;
    outcome: 'adjourn' | 'close' | 'terminate';
    sessionDate: string;
    notes: string;
    nextSessionDate: string;
    decisionDate: string;
};

export type UseOrderFileLifecycleStateArgs = {
    fileData: unknown;
    defaultDeadlineDays: number;
};

export function useOrderFileLifecycleState({ fileData, defaultDeadlineDays }: UseOrderFileLifecycleStateArgs) {
    const fd = fileData as Record<string, unknown>;
    const [caseData, setCaseData] = useState<any>(fd);

    const [fileStatus, setFileStatus] = useState<FileStatus>('pending');
    const [isSecretMode, setIsSecretMode] = useState(true);
    const [hasIntervention, setHasIntervention] = useState(false);
    const [activeLifecycleStep, setActiveLifecycleStep] = useState<'judge' | 'execution' | 'grievance' | 'cassation' | null>(
        'judge',
    );

    const [judgeDecision, setJudgeDecision] = useState<JudgeDecision>({
        decision: null,
        decisionDate: '',
        requiresGuarantee: false,
    });
    const [executionData, setExecutionData] = useState<ExecutionData>({
        executionDate: '',
        notificationDate: '',
        deadlineDays: defaultDeadlineDays,
        authority: '',
        notes: '',
    });
    const [grievanceData, setGrievanceData] = useState<GrievanceData>({
        rejectionNotificationDate: '',
        outcome: '',
        filingDate: '',
    });
    const [phase2FirstHearingDate, setPhase2FirstHearingDate] = useState<string>(() => {
        const raw = String((fileData as any)?.grievanceFirstHearingDate ?? (fileData as any)?.phase2FirstHearingDate ?? '').trim();
        return raw.match(/^(\d{4}-\d{2}-\d{2})/)?.[1] ?? '';
    });
    const [grievanceLegalEndDate, setGrievanceLegalEndDate] = useState<string>(
        String((fileData as any)?.grievanceLegalEndDate ?? ''),
    );
    const [grievanceDecisionNotificationConfirmed, setGrievanceDecisionNotificationConfirmed] = useState<boolean>(false);
    const [grievancePetitionNotificationDate, setGrievancePetitionNotificationDate] = useState<string>(
        String((fileData as any)?.grievancePetitionNotificationDate ?? ''),
    );
    const [grievancePetitionNotificationConfirmed, setGrievancePetitionNotificationConfirmed] = useState<boolean>(false);
    const [decisionNotificationModalOpen, setDecisionNotificationModalOpen] = useState<boolean>(false);
    const [petitionNotificationModalOpen, setPetitionNotificationModalOpen] = useState<boolean>(false);
    const [grievanceTimingConfirmed, setGrievanceTimingConfirmed] = useState<boolean>(false);
    const [grievanceDetailsConfirmed, setGrievanceDetailsConfirmed] = useState<boolean>(false);
    const [grievanceExpiredConfirmed, setGrievanceExpiredConfirmed] = useState<boolean>(false);
    const [grievanceDecision, setGrievanceDecision] = useState<GrievanceDecision>({
        decision: null,
        decisionDate: '',
    });
    const [cassationData, setCassationData] = useState<CassationData>({
        filedBy: null,
        outcome: '',
        filingDate: '',
        fileNumber: '',
    });
    const [cassationDecision, setCassationDecision] = useState<CassationDecision>({
        decision: null,
        decisionDate: '',
    });
    const [cassationExpiredConfirmed, setCassationExpiredConfirmed] = useState<boolean>(false);

    const [guaranteeSubmitted, setGuaranteeSubmitted] = useState<boolean>(false);
    const [guaranteeDetails, setGuaranteeDetails] = useState<{ amount: string; receiptNumber: string }>({
        amount: String((fileData as any)?.guaranteeAmount ?? ''),
        receiptNumber: String((fileData as any)?.guaranteeReceiptNumber ?? ''),
    });
    const [hearings, setHearings] = useState<CaseHearing[]>([]);
    const [hearingDraft, setHearingDraft] = useState<HearingDraftState>({
        open: false,
        stage: 'pre_decision',
        outcome: 'adjourn',
        sessionDate: '',
        notes: '',
        nextSessionDate: '',
        decisionDate: '',
    });

    useEffect(() => {
        if (!hearingDraft.open) return;
        if (hearingDraft.outcome === 'adjourn') return;
        setHearingDraft((s) => {
            if (!s.open) return s;
            if (s.outcome === 'adjourn') return s;
            const next = { ...s };
            let changed = false;
            if (String(next.nextSessionDate || '').trim()) {
                next.nextSessionDate = '';
                changed = true;
            }
            if (s.outcome === 'terminate') {
                if (String(next.notes || '').trim()) {
                    next.notes = '';
                    changed = true;
                }
                if (String(next.decisionDate || '').trim()) {
                    next.decisionDate = '';
                    changed = true;
                }
            } else if (s.outcome === 'close') {
                if (String(next.notes || '').trim()) {
                    next.notes = '';
                    changed = true;
                }
            }
            return changed ? next : s;
        });
    }, [hearingDraft.open, hearingDraft.outcome]);

    const [expertModule, setExpertModule] = useState<ExpertModule>({
        enabled: false,
        expertName: '',
        depositAmount: '',
        inspectionDate: '',
        reportDueDate: '',
        reportReceivedDate: '',
    });
    const [preDecisionClosed, setPreDecisionClosed] = useState<boolean>(false);
    const [expectedDecisionDate, setExpectedDecisionDate] = useState<string>('');
    const [registrationData, setRegistrationData] = useState<{
        receiptNumber: string;
        receiptDate: string;
        notificationMethod: string;
        notificationDate: string;
    }>({ receiptNumber: '', receiptDate: '', notificationMethod: '', notificationDate: '' });
    const [caseEvents, setCaseEvents] = useState<CaseEvent[]>([]);
    const [caseNotes, setCaseNotes] = useState<CaseNote[]>([]);
    const [caseAttachments, setCaseAttachments] = useState<CaseAttachment[]>([]);
    const [caseFollowups, setCaseFollowups] = useState<CaseFollowup[]>([]);

    const [editJudge, setEditJudge] = useState(false);
    const [editExecution, setEditExecution] = useState(false);
    const [editRejectionNotice, setEditRejectionNotice] = useState(false);
    const [editGrievance, setEditGrievance] = useState(false);
    const [editCassation, setEditCassation] = useState(false);

    const [judgeError, setJudgeError] = useState<string | null>(null);
    const [executionError, setExecutionError] = useState<string | null>(null);
    const [rejectionNoticeError, setRejectionNoticeError] = useState<string | null>(null);
    const [grievanceError, setGrievanceError] = useState<string | null>(null);
    const [grievanceDecisionError, setGrievanceDecisionError] = useState<string | null>(null);
    const [cassationError, setCassationError] = useState<string | null>(null);
    const [cassationDecisionError, setCassationDecisionError] = useState<string | null>(null);
    const [hearingsError, setHearingsError] = useState<string | null>(null);

    const grievanceRef = useRef<HTMLDivElement | null>(null);
    const cassationRef = useRef<HTMLDivElement | null>(null);
    const grievanceTimingGateRef = useRef<HTMLDivElement | null>(null);
    const grievanceOutcomeGateRef = useRef<HTMLDivElement | null>(null);
    const grievanceHearingsGateRef = useRef<HTMLDivElement | null>(null);
    const grievanceFinalGateRef = useRef<HTMLDivElement | null>(null);
    const cassationFilingGateRef = useRef<HTMLDivElement | null>(null);
    const cassationDecisionGateRef = useRef<HTMLDivElement | null>(null);
    const pendingRegistrationSyncRef = useRef(false);

    return {
        caseData,
        setCaseData,
        fileStatus,
        setFileStatus,
        isSecretMode,
        setIsSecretMode,
        hasIntervention,
        setHasIntervention,
        activeLifecycleStep,
        setActiveLifecycleStep,
        judgeDecision,
        setJudgeDecision,
        executionData,
        setExecutionData,
        grievanceData,
        setGrievanceData,
        phase2FirstHearingDate,
        setPhase2FirstHearingDate,
        grievanceLegalEndDate,
        setGrievanceLegalEndDate,
        grievanceDecisionNotificationConfirmed,
        setGrievanceDecisionNotificationConfirmed,
        grievancePetitionNotificationDate,
        setGrievancePetitionNotificationDate,
        grievancePetitionNotificationConfirmed,
        setGrievancePetitionNotificationConfirmed,
        decisionNotificationModalOpen,
        setDecisionNotificationModalOpen,
        petitionNotificationModalOpen,
        setPetitionNotificationModalOpen,
        grievanceTimingConfirmed,
        setGrievanceTimingConfirmed,
        grievanceDetailsConfirmed,
        setGrievanceDetailsConfirmed,
        grievanceExpiredConfirmed,
        setGrievanceExpiredConfirmed,
        grievanceDecision,
        setGrievanceDecision,
        cassationData,
        setCassationData,
        cassationDecision,
        setCassationDecision,
        cassationExpiredConfirmed,
        setCassationExpiredConfirmed,
        guaranteeSubmitted,
        setGuaranteeSubmitted,
        guaranteeDetails,
        setGuaranteeDetails,
        hearings,
        setHearings,
        hearingDraft,
        setHearingDraft,
        expertModule,
        setExpertModule,
        preDecisionClosed,
        setPreDecisionClosed,
        expectedDecisionDate,
        setExpectedDecisionDate,
        registrationData,
        setRegistrationData,
        caseEvents,
        setCaseEvents,
        caseNotes,
        setCaseNotes,
        caseAttachments,
        setCaseAttachments,
        caseFollowups,
        setCaseFollowups,
        editJudge,
        setEditJudge,
        editExecution,
        setEditExecution,
        editRejectionNotice,
        setEditRejectionNotice,
        editGrievance,
        setEditGrievance,
        editCassation,
        setEditCassation,
        judgeError,
        setJudgeError,
        executionError,
        setExecutionError,
        rejectionNoticeError,
        setRejectionNoticeError,
        grievanceError,
        setGrievanceError,
        grievanceDecisionError,
        setGrievanceDecisionError,
        cassationError,
        setCassationError,
        cassationDecisionError,
        setCassationDecisionError,
        hearingsError,
        setHearingsError,
        grievanceRef,
        cassationRef,
        grievanceTimingGateRef,
        grievanceOutcomeGateRef,
        grievanceHearingsGateRef,
        grievanceFinalGateRef,
        cassationFilingGateRef,
        cassationDecisionGateRef,
        pendingRegistrationSyncRef,
    };
}

import { useState } from 'react';
import type { DossierEditForm, PartyEditRow } from '../modals/DossierEditModal';

type UseOrderFileMetaPartyEditArgs = {
    caseData: any;
    party1Entries: any[];
    party2Entries: any[];
    persistAndMerge: (patch: Record<string, unknown>) => void;
    appendCaseEvent: (message: string, kind?: 'system' | 'action' | 'edit') => void;
};

function mapPartyToForm(party: Record<string, unknown>): PartyEditRow {
    return {
        name: String(party?.name ?? ''),
        address: String(party?.address ?? ''),
    };
}

function mergePartyRow(original: Record<string, unknown>, form: PartyEditRow) {
    return {
        ...original,
        name: String(form.name ?? '').trim(),
        address: String(form.address ?? '').trim(),
    };
}

const emptyDossierForm = (): DossierEditForm => ({
    meta: {
        requestNumber: '',
        requestDate: '',
        courtName: '',
        judgeName: '',
        specificActionType: '',
    },
    party1: [],
    party2: [],
});

export function useOrderFileMetaPartyEdit({
    caseData,
    party1Entries,
    party2Entries,
    persistAndMerge,
    appendCaseEvent,
}: UseOrderFileMetaPartyEditArgs) {
    const [isDossierEditOpen, setIsDossierEditOpen] = useState(false);
    const [dossierEditForm, setDossierEditForm] = useState<DossierEditForm>(emptyDossierForm);

    const openDossierEdit = () => {
        setDossierEditForm({
            meta: {
                requestNumber: String(caseData?.requestNumber ?? ''),
                requestDate: String(caseData?.requestDate ?? ''),
                courtName: String(caseData?.courtName ?? ''),
                judgeName: String(caseData?.judgeName ?? ''),
                specificActionType: String(caseData?.specificActionType ?? ''),
            },
            party1: party1Entries.map((p) => mapPartyToForm(p as Record<string, unknown>)),
            party2: party2Entries.map((p) => mapPartyToForm(p as Record<string, unknown>)),
        });
        setIsDossierEditOpen(true);
    };

    const closeDossierEdit = () => {
        setIsDossierEditOpen(false);
    };

    const saveDossierEdit = (e?: React.SyntheticEvent) => {
        if (e) {
            e.preventDefault();
            e.stopPropagation();
        }

        const nextParty1 = party1Entries.map((p, i) =>
            mergePartyRow(p as Record<string, unknown>, dossierEditForm.party1[i] ?? mapPartyToForm(p)),
        );
        const nextParty2 = party2Entries.map((p, i) =>
            mergePartyRow(p as Record<string, unknown>, dossierEditForm.party2[i] ?? mapPartyToForm(p)),
        );

        const meta = dossierEditForm.meta;
        const patch: Record<string, unknown> = {
            requestNumber: String(meta.requestNumber ?? '').trim(),
            requestDate: String(meta.requestDate ?? '').trim(),
            courtName: String(meta.courtName ?? '').trim(),
            judgeName: String(meta.judgeName ?? '').trim(),
            allParty1: nextParty1,
            allParty2: nextParty2,
        };

        if (nextParty1[0]) {
            patch.party1Name = String((nextParty1[0] as any)?.name ?? '');
            patch.party1Address = String((nextParty1[0] as any)?.address ?? '');
        }
        if (nextParty2[0]) {
            patch.party2Name = String((nextParty2[0] as any)?.name ?? '');
            patch.party2Address = String((nextParty2[0] as any)?.address ?? '');
        }

        persistAndMerge(patch);
        appendCaseEvent('تم تعديل بيانات الإضبارة والأطراف', 'edit');
        closeDossierEdit();
    };

    return {
        isDossierEditOpen,
        dossierEditForm,
        setDossierEditForm,
        openDossierEdit,
        closeDossierEdit,
        saveDossierEdit,
    };
}

import { useMemo } from 'react';
import {
    actionTypeOptions,
    isIqrarRequest,
    JUDICIAL_ACKNOWLEDGMENT_PRIMARY,
    URGENT_PETITION_PRIMARY,
} from '@/app/domain/urgent/formPathwayConstants';
import { getDynamicPartyLabels } from '../utils/partyLabels';
import type { JudgeDecision } from '../types';

export type OrderFilePartyEntry = Record<string, unknown> & {
    name: string;
    isRepresented?: boolean;
};

export type UseOrderFilePartyWorkspaceArgs = {
    caseData: any;
    judgeDecision: JudgeDecision;
    guaranteeSubmitted: boolean;
    resolvedWorkspaceRequestType: string;
    isIqrarContext: boolean;
    isStateOrder: boolean;
    isOrderOnPetition: boolean;
    isUrgentLawsuit: boolean;
    isUrgentJustice: boolean;
};

export function useOrderFilePartyWorkspace({
    caseData,
    judgeDecision,
    guaranteeSubmitted,
    resolvedWorkspaceRequestType,
    isIqrarContext,
    isStateOrder,
    isOrderOnPetition,
    isUrgentLawsuit,
    isUrgentJustice,
}: UseOrderFilePartyWorkspaceArgs) {
    const rawParty1Entries = Array.isArray(caseData?.allParty1) ? (caseData.allParty1 as any[]) : [];
    const rawParty2Entries = Array.isArray(caseData?.allParty2) ? (caseData.allParty2 as any[]) : [];
    const legacyRepresentedSide =
        caseData?.representedParty === 'client' || caseData?.representedParty === 'opponent'
            ? caseData.representedParty
            : null;
    const party1HasRepresentedFlag = rawParty1Entries.some((p) => typeof p?.isRepresented === 'boolean');
    const party2HasRepresentedFlag = rawParty2Entries.some((p) => typeof p?.isRepresented === 'boolean');

    const party1Entries: OrderFilePartyEntry[] = (
        rawParty1Entries.length
            ? rawParty1Entries
            : [{ name: caseData?.party1Name ?? '', phone: caseData?.party1Phone ?? '' }]
    ).map((p, index) => ({
        ...p,
        name: String(p?.name ?? '').trim(),
        isRepresented:
            typeof p?.isRepresented === 'boolean'
                ? p.isRepresented
                : !party1HasRepresentedFlag && legacyRepresentedSide === 'client' && index === 0,
    }));

    const party2Entries: OrderFilePartyEntry[] = (
        rawParty2Entries.length
            ? rawParty2Entries
            : [{ name: caseData?.party2Name ?? '', address: caseData?.party2Address ?? '' }]
    ).map((p, index) => ({
        ...p,
        name: String(p?.name ?? '').trim(),
        isRepresented:
            typeof p?.isRepresented === 'boolean'
                ? p.isRepresented
                : !party2HasRepresentedFlag && legacyRepresentedSide === 'opponent' && index === 0,
    }));

    const isDefendantClient = party2Entries.some((p) => !!(p as any)?.isClient || !!(p as any)?.isRepresented);
    const representedSide =
        party1Entries.some((p) => !!p?.isRepresented) && !party2Entries.some((p) => !!p?.isRepresented)
            ? 'client'
            : party2Entries.some((p) => !!p?.isRepresented) && !party1Entries.some((p) => !!p?.isRepresented)
              ? 'opponent'
              : null;

    const defenderEntryPhase = useMemo(() => {
        if (!isDefendantClient || !isStateOrder) return 1;
        const v = Number((caseData as any)?.defenderEntryPhase);
        return v === 2 || v === 3 ? v : 1;
    }, [caseData, isDefendantClient, isStateOrder]);

    const defenderPhase1ReadOnly = defenderEntryPhase >= 2 && isDefendantClient && isStateOrder;
    const defenderPhase2ReadOnly = defenderEntryPhase >= 3 && isDefendantClient && isStateOrder;

    const procedureTypeTitle = useMemo(() => {
        const raw = String(caseData?.specificActionType || '').trim();
        if (isIqrarRequest(raw)) return 'إقرار قضائي / حجة إقرار';
        if (!raw) return 'أمر ولائي';
        const primary = raw.split('/')[0]?.trim();
        return primary || raw;
    }, [caseData?.specificActionType]);

    const khulasaText = useMemo(() => {
        return String((caseData as any)?.khulasatAlTalab ?? (caseData as any)?.khulasa ?? '').trim();
    }, [caseData]);

    const partyLabels = useMemo(
        () => getDynamicPartyLabels(String(caseData?.specificActionType ?? '').trim()),
        [caseData?.specificActionType],
    );

    const guaranteeGateActive =
        (judgeDecision.decision === 'accepted' || judgeDecision.decision === 'partially_accepted') &&
        judgeDecision.requiresGuarantee &&
        !guaranteeSubmitted;

    const finalityReason = String((caseData as any)?.finalityReason || '').trim();
    const isFinalityNoGrievance = finalityReason === 'no_grievance';
    const isFinalityTerminatedRequest = finalityReason === 'terminated_request';
    const isFinalized =
        !!caseData?.archived ||
        (caseData as any)?.status === 'completed' ||
        (caseData as any)?.status === 'closed' ||
        (caseData as any)?.phase === 'completed';

    const workspaceTypeDetail = useMemo(() => {
        const raw = String(caseData?.specificActionType ?? resolvedWorkspaceRequestType ?? '').trim();
        const leafOptions = [
            ...actionTypeOptions.state_order,
            ...actionTypeOptions.urgent_discovery,
            ...actionTypeOptions.acknowledgment,
        ];
        if (leafOptions.includes(raw)) return raw;
        if (!raw || raw === URGENT_PETITION_PRIMARY || raw === JUDICIAL_ACKNOWLEDGMENT_PRIMARY) {
            const fallback = String((caseData as any)?.requestSubject ?? '').trim();
            return fallback || '—';
        }
        if (raw.includes('/')) {
            const parts = raw.split('/').map((p) => p.trim()).filter(Boolean);
            return parts[0] || raw;
        }
        return raw;
    }, [caseData, resolvedWorkspaceRequestType]);

    const workspaceHeaderTitle = useMemo(() => {
        const detail = workspaceTypeDetail;
        if (isIqrarContext) {
            if (isFinalized && !!caseData?.archived) return `إقرار مؤرشف: ${detail}`;
            return `إقرار: ${detail}`;
        }
        if (isStateOrder || isOrderOnPetition) return `أمر ولائي: ${detail}`;
        if (isUrgentLawsuit || isUrgentJustice) return `طلب مستعجل: ${detail}`;
        return `مسار قضائي: ${detail}`;
    }, [
        workspaceTypeDetail,
        isIqrarContext,
        isFinalized,
        caseData?.archived,
        isStateOrder,
        isOrderOnPetition,
        isUrgentLawsuit,
        isUrgentJustice,
    ]);

    return {
        party1Entries,
        party2Entries,
        isDefendantClient,
        representedSide,
        defenderEntryPhase,
        defenderPhase1ReadOnly,
        defenderPhase2ReadOnly,
        procedureTypeTitle,
        khulasaText,
        partyLabels,
        guaranteeGateActive,
        isFinalityNoGrievance,
        isFinalityTerminatedRequest,
        isFinalized,
        workspaceTypeDetail,
        workspaceHeaderTitle,
    };
}

import { useCallback, useEffect, useRef } from 'react';
import { UrgentActionsDB, uuidv4 } from '@/app/services/urgent-actions-db';
import type { CaseEvent } from '../types';

type UseOrderFilePersistArgs = {
    caseId: string | null;
    userId: string | null;
    caseEvents: CaseEvent[];
    setCaseEvents: React.Dispatch<React.SetStateAction<CaseEvent[]>>;
    setCaseData: React.Dispatch<React.SetStateAction<any>>;
    onCaseUpdated?: (caseId: string, patch: Record<string, unknown>) => void;
};

export function useOrderFilePersist({
    caseId,
    userId,
    caseEvents,
    setCaseEvents,
    setCaseData,
    onCaseUpdated,
}: UseOrderFilePersistArgs) {
    const pendingEventsSyncRef = useRef(false);
    const persistPatchTimerRef = useRef<number | null>(null);
    const persistPatchQueueRef = useRef<Record<string, unknown>>({});

    const flushPersistPatch = useCallback(
        async (patch: Record<string, unknown>) => {
            if (!caseId || !userId || !Object.keys(patch).length) return;
            await UrgentActionsDB.patchCase(userId, caseId, patch);
        },
        [caseId, userId],
    );

    const persistPatch = useCallback(
        (patch: Record<string, unknown>) => {
            if (!caseId) return;
            persistPatchQueueRef.current = { ...persistPatchQueueRef.current, ...patch };
            if (persistPatchTimerRef.current) window.clearTimeout(persistPatchTimerRef.current);
            persistPatchTimerRef.current = window.setTimeout(() => {
                persistPatchTimerRef.current = null;
                const queued = persistPatchQueueRef.current;
                persistPatchQueueRef.current = {};
                void flushPersistPatch(queued);
            }, 900);
        },
        [caseId, flushPersistPatch],
    );

    const persistAndMerge = useCallback(
        (patch: Record<string, unknown>) => {
            void persistPatch(patch);
            if (caseId) onCaseUpdated?.(caseId, patch);
            setCaseData((prev: any) => ({ ...(prev || {}), ...patch }));
        },
        [caseId, onCaseUpdated, persistPatch, setCaseData],
    );

    const appendCaseEvent = useCallback(
        (message: string, kind: CaseEvent['kind'] = 'action') => {
            const clean = String(message || '').trim();
            if (!clean) return;
            const entry: CaseEvent = {
                id: uuidv4(),
                kind,
                message: clean,
                createdAt: new Date().toISOString(),
            };
            pendingEventsSyncRef.current = true;
            setCaseEvents((prev) => [entry, ...prev].slice(0, 400));
        },
        [setCaseEvents],
    );

    useEffect(() => {
        const stopSubmit = (ev: Event) => {
            ev.preventDefault();
        };
        document.addEventListener('submit', stopSubmit, true);
        return () => {
            document.removeEventListener('submit', stopSubmit, true);
        };
    }, []);

    useEffect(() => {
        if (!pendingEventsSyncRef.current) return;
        pendingEventsSyncRef.current = false;
        persistPatchQueueRef.current = { ...persistPatchQueueRef.current, events: caseEvents };
        if (persistPatchTimerRef.current) window.clearTimeout(persistPatchTimerRef.current);
        persistPatchTimerRef.current = window.setTimeout(() => {
            persistPatchTimerRef.current = null;
            const queued = persistPatchQueueRef.current;
            persistPatchQueueRef.current = {};
            void flushPersistPatch(queued);
        }, 900);
    }, [caseEvents, flushPersistPatch]);

    useEffect(() => {
        return () => {
            if (persistPatchTimerRef.current) window.clearTimeout(persistPatchTimerRef.current);
        };
    }, []);

    return { persistPatch, flushPersistPatch, persistAndMerge, appendCaseEvent };
}

