export function useAppealAwaitingCassationRenderer(args: UseDecisionsAppealsAppealRenderersArgs) {
    const {
        appealPerspective,
        decisions,
        transitionAppealWorkflow,
        applyWaiveCassationAfterDebtorGrievance,
