    return { renderAppealAwaitingCassationButtons };
}

import React from 'react';
import { AppealDeadlineLapsePanel } from '../../components/AppealDeadlineLapsePanel';
import type { Decision } from '../../types';
import type { UseDecisionsAppealsAppealRenderersArgs } from './appealRenderersTypes';
import {
    appealDeadlineLapsePanelMessage,
    buildAppealPerpetualEnforcementPatch,
    buildGrievanceDeadlineLapsePatch,
    resolveAppealDeadlineExpiryKind,
} from '../../utils';
import { DECISION_BTN_PRIMARY_WFULL } from './appealRendererButtonClasses';

export function useAppealDeadlineLapseRenderer(args: UseDecisionsAppealsAppealRenderersArgs) {
    const { decisions, patchDecisionRow, logAppealTimeline, setDecisionsHubTab } = args;

    const handleEndAppealDeadline = React.useCallback(
        (decisionId: string) => {
            const row = decisions.find((d) => d.id === decisionId);
            if (!row) return;
            const kind = resolveAppealDeadlineExpiryKind(row);
            if (!kind) return;
            if (kind === 'grievance') {
                patchDecisionRow(decisionId, buildGrievanceDeadlineLapsePatch(row, decisions));
                logAppealTimeline('إنهاء مهلة التظلم', 'أُغلق مسار التظلم — يبقى مسار التمييز إن كانت مهلته سارية');
                return;
            }
            patchDecisionRow(decisionId, buildAppealPerpetualEnforcementPatch(row));
            logAppealTimeline(
                'إنهاء مهلة التمييز',
                'انتهت مهلة التمييز — القرار نافذٌ نهائياً وأُرشف'
            );
            queueMicrotask(() => setDecisionsHubTab('archive'));
        },
        [decisions, patchDecisionRow, logAppealTimeline]
    );

    const renderAppealDeadlineLapseActions = (decision: Decision) => {
        const kind = resolveAppealDeadlineExpiryKind(decision);
        if (!kind) return null;
        return (
            <AppealDeadlineLapsePanel
                message={appealDeadlineLapsePanelMessage(kind)}
                onEndDeadline={() => handleEndAppealDeadline(decision.id)}
                btnPrimaryClass={DECISION_BTN_PRIMARY_WFULL}
            />
        );
    };

    return { renderAppealDeadlineLapseActions };
}

import React from 'react';
import type { Decision } from '../../types';
import type { UseDecisionsAppealsAppealRenderersArgs } from './appealRenderersTypes';
import {
    appealPipelineRowForCard,
    isExecutorDecisionAppealFinal,
    resolveCreditorDecisionEnforcementState,
    renderBinaryEnforcementStatusPill,
} from '../../utils';

export function useAppealDecisionCardStatus(args: UseDecisionsAppealsAppealRenderersArgs) {
    const {
        appealPerspective,
        decisionsHubTab,
        setAppealDetailDecision,
        setDecisionsHubTab,
        goToAppealsWithScroll,
        requestNeedsExecutorOutcome,
        getAppealStatus,
    } = args;

    const buildDecisionCardStatus = React.useCallback((
        decision: Decision,
        appealWindowClosed: boolean,
        allDecisions: Decision[]
    ) => {
        const pipeline = appealPipelineRowForCard(decision, allDecisions);
        const deadlineMeta = getAppealStatus(decision);
        const ap = pipeline.appealPhase ?? null;
        const awaitingTamyeezAfterGrievance =
            Boolean(pipeline.awaitingCassationEntryBy) ||
            pipeline.grievanceRejectedAwaitingTamyeez === true ||
            pipeline.grievanceAcceptedAwaitingDebtorTamyeez === true;
        const appealTrackVisual =
            ap === 'grievance' ||
            ap === 'cassation' ||
            pipeline.appealStatus === 'tadhallum_filed' ||
            pipeline.appealStatus === 'tamyeez_filed' ||
            Boolean(pipeline.awaitingCassationEntryBy) ||
            pipeline.grievanceAcceptedAwaitingDebtorTamyeez === true;

        const appealLegallyFinal = isExecutorDecisionAppealFinal(decision, pipeline, {
            appealWindowClosed,
            appealTrackActive: appealTrackVisual && !appealWindowClosed,
            isPastTamyeezDeadline: deadlineMeta.isPastTamyeezDeadline,
        });

        const openAppealContext = (final: boolean) => {
            if (final) {
                setAppealDetailDecision(decision);
                setDecisionsHubTab('appeals');
                return;
            }
            goToAppealsWithScroll(decision.id);
        };

        const statusPillEl = (() => {
            if (decision.manualExecutorLedgerEntry === true) {
                return null;
            }
            const enforcement = resolveCreditorDecisionEnforcementState(decision, pipeline, {
                hubTab: decisionsHubTab,
                appealLegallyFinal,
                needsExecutor: requestNeedsExecutorOutcome(decision),
                appealPerspective,
                allDecisions,
            });
            const isFinalEnforcedLabel =
                enforcement.pillLabel === 'القرار نافذ' ||
                enforcement.pillLabel.endsWith('— نافذ');
            return renderBinaryEnforcementStatusPill(
                enforcement.enforced,
                enforcement.enforced && isFinalEnforcedLabel
                    ? () => openAppealContext(true)
                    : undefined
            );
        })();

        return { statusPillEl, appealTrackVisual, awaitingTamyeezAfterGrievance, ap };
    }, [appealPerspective, decisionsHubTab, getAppealStatus, goToAppealsWithScroll, requestNeedsExecutorOutcome]);

    return { buildDecisionCardStatus };
}

import React, { useEffect } from 'react';
import { SmartToast } from '@/app/components/ui/SmartToast';
import { applyLawyerCassationEntryForExecution } from '@/app/utils/lawyerCassationEntry';
import type { Decision } from '../types';
import type { ManualAppealAppellantActor } from '../utils';
import {
    newEventId,
    buildExecutorSideAppealCommitPatch,
    executorSideAppealTimelineMessage,
    EXECUTOR_QUEUE_REQUEST_KINDS,
    resolveHarmedPartyAppealActor,
    resolveUnderlyingDecisionHub,
} from '../utils';
import {
    appealInitialCassationTimeline,
    appealInitialGrievanceTimeline,
} from '../appealUiLabels';
import type { DecisionsAppealsMutationsCoreParams } from './decisionsAppealsMutationsTypes';


export type AppealEntryMutationsParams = DecisionsAppealsMutationsCoreParams & {
    transitionAppealWorkflow: (
        decision: Decision,
        patch: Partial<Decision>,
        timelineTitle: string,
        timelineDescription: string,
        tone: 'emerald' | 'rose' | 'amber' | 'slate',
    ) => void;
};

export function useDecisionsAppealsAppealEntryMutations(params: AppealEntryMutationsParams) {
    const {
        executionId,
        decisions,
        setDecisions,
        persistDecisionsToStorage,
        appealPerspective,
        reloadFromStorage,
        onTimelineUpdate,
        getMilestoneTimelineSnapshot,
        setDecisionsHubTab,
        goToAppealsWithScroll,
        transitionAppealWorkflow,
    } = params;

    const commitQueueRequestAppealEntry = React.useCallback(
        (decision: Decision, stage: 'grievance' | 'cassation') => {
            const appealHub = resolveUnderlyingDecisionHub(decision, decisions);
            if (
                !appealHub.requestKind ||
                !EXECUTOR_QUEUE_REQUEST_KINDS.includes(appealHub.requestKind)
            ) {
                return;
            }
            const actor = resolveHarmedPartyAppealActor(decision, appealPerspective);
            if (!actor) return;
            const cassationOnly = decision.cassationOnlyAppeal === true;
            if (stage === 'grievance' && cassationOnly) return;

            const patch =
                stage === 'grievance'
                    ? {
                          noAppealChosen: false,
                          appealActor: actor,
                          appealMethod: 'tadhallum' as const,
                          appealWorkflowState:
                              actor === 'debtor'
                                  ? ('PENDING_APPEAL_DEBTOR' as const)
                                  : ('PENDING_APPEAL_LAWYER' as const),
                          appealStatus: 'tadhallum_filed' as const,
                          appealPhase: 'grievance' as const,
                      }
                    : {
                          noAppealChosen: false,
                          appealActor: actor,
                          appealMethod: 'tamyeez' as const,
                          appealWorkflowState:
                              actor === 'debtor'
                                  ? ('PENDING_APPEAL_DEBTOR' as const)
                                  : ('PENDING_APPEAL_LAWYER' as const),
                          appealStatus: 'tamyeez_filed' as const,
                          appealPhase: 'cassation' as const,
                      };

            const timelineTitle = stage === 'grievance' ? 'تسجيل تظلم' : 'تسجيل تمييز';
            const timelineDescription =
                stage === 'grievance'
                    ? appealInitialGrievanceTimeline(appealPerspective, actor)
                    : appealInitialCassationTimeline(appealPerspective, actor);
            transitionAppealWorkflow(
                decision,
                patch,
                timelineTitle,
                timelineDescription,
                'amber',
            );
        },
        [appealPerspective, decisions, transitionAppealWorkflow],
    );

    const commitExecutorSideAppealEntry = React.useCallback(
        (
            decision: Decision,
            stage: 'grievance' | 'cassation',
            appellants: ManualAppealAppellantActor[],
        ) => {
            if (appellants.length === 0) {
                SmartToast.error('اختر طرفاً واحداً على الأقل');
                return;
            }
            const appealHub = resolveUnderlyingDecisionHub(decision, decisions);
            if (
                decision.manualExecutorLedgerEntry === true ||
                appealHub.manualExecutorLedgerEntry === true
            ) {
                return;
            }
            if (
                appealHub.requestKind &&
                EXECUTOR_QUEUE_REQUEST_KINDS.includes(appealHub.requestKind)
            ) {
                commitQueueRequestAppealEntry(decision, stage);
                return;
            }
            const patch = buildExecutorSideAppealCommitPatch(stage, appellants);
            const timelineTitle = stage === 'grievance' ? 'تسجيل تظلم' : 'تسجيل تمييز';
            const timelineDescription = executorSideAppealTimelineMessage(
                stage,
                appellants,
                appealPerspective,
            );
            transitionAppealWorkflow(decision, patch, timelineTitle, timelineDescription, 'amber');
        },
        [appealPerspective, commitQueueRequestAppealEntry, decisions, transitionAppealWorkflow],
    );

    const applyLawyerCassationEntry = React.useCallback(
        (decision: Decision) => {
            const result = applyLawyerCassationEntryForExecution({
                executionId,
                decisionId: decision.id,
                appealPerspective,
                appendTimeline: false,
            });
            if (!result.ok) return;
            reloadFromStorage();
            const nowIso = new Date().toISOString();
            const appealOpenSnap = getMilestoneTimelineSnapshot?.();
            onTimelineUpdate({
                id: newEventId(),
                date: nowIso.slice(0, 10),
                timestamp: nowIso,
                title: result.timelineTitle ?? 'تمييز القرار',
                description: result.timelineDescription ?? '',
                type: 'appeal',
                source: 'القرارات والطعون',
                ...(appealOpenSnap !== undefined ? { snapshot: appealOpenSnap } : {}),
            });
            queueMicrotask(() =>
                goToAppealsWithScroll(result.scrollDecisionId ?? decision.id),
            );
        },
        [
            appealPerspective,
            executionId,
            getMilestoneTimelineSnapshot,
            goToAppealsWithScroll,
            onTimelineUpdate,
            reloadFromStorage,
        ],
    );

    useEffect(() => {
        const handler = (e: Event) => {
            const detail = (e as CustomEvent<{ executionId?: string; decisionId?: string }>).detail;
            if (executionId && detail?.executionId && detail.executionId !== executionId) return;
            const decisionId = String(detail?.decisionId || '').trim();
            if (!decisionId) return;
            const row = decisions.find((d) => d.id === decisionId);
            if (!row) return;
            applyLawyerCassationEntry(row);
        };
        window.addEventListener('hami-start-cassation-for-decision', handler as EventListener);
        return () => window.removeEventListener('hami-start-cassation-for-decision', handler as EventListener);
    }, [applyLawyerCassationEntry, decisions, executionId]);

    return { commitExecutorSideAppealEntry, commitQueueRequestAppealEntry, applyLawyerCassationEntry };
}

import React from 'react';
import { dispatchDecisionsReload } from '@/app/utils/executorSeizureDecisionQueue';
import type { Decision } from '../types';
import { dispatchHeirSubstitutionOutcomeIfAny } from '../engine/decisionsEngineTypes';
import { applyPersonalCoerciveAppealClosure } from '@/app/utils/personalCoerciveAppealSync';
import { applyEvictionAppealClosure } from '@/app/utils/evictionAppealSync';
import { buildCassationCourtDecisionNext } from '../utils/cassationCourtDecisionCommit';
import { newEventId } from '../utils';
import type { DecisionsAppealsMutationsCoreParams } from './decisionsAppealsMutationsTypes';

export function useDecisionsAppealsCassationMutations(params: DecisionsAppealsMutationsCoreParams) {
    const {
        executionId,
        decisions,
        setDecisions,
        persistDecisionsToStorage,
        appealPerspective,
        onTimelineUpdate,
        getMilestoneTimelineSnapshot,
    } = params;

    const applyCassationCourtDecision = React.useCallback(
        (decision: Decision, choice: 'rad_laheeza' | 'naqd') => {
            const { next, mergedRowId, labelAr, outcomeLine } = buildCassationCourtDecisionNext(
                decisions,
                decision,
                choice,
                appealPerspective
            );
            const now = new Date().toISOString();
            const when = new Date(now).toLocaleString('ar-IQ', {
                dateStyle: 'medium',
                timeStyle: 'short',
            });

            setDecisions(next);
            const removedIds = decisions
                .filter((d) => !next.some((n) => n.id === d.id))
                .map((d) => d.id);
            persistDecisionsToStorage(
                next,
                removedIds.length > 0 ? { removedIds } : undefined
            );
            queueMicrotask(() => dispatchDecisionsReload());

            const mergedRow = next.find((x) => x.id === mergedRowId);
            if (mergedRow) {
                dispatchHeirSubstitutionOutcomeIfAny(executionId, mergedRow);
                applyPersonalCoerciveAppealClosure({
                    executionId,
                    row: mergedRow as unknown as Record<string, unknown>,
                    allDecisions: next as unknown as Record<string, unknown>[],
                });
                applyEvictionAppealClosure({
                    executionId,
                    row: mergedRow as unknown as Record<string, unknown>,
                    allDecisions: next as unknown as Record<string, unknown>[],
                });
            }
            onTimelineUpdate({
                id: newEventId(),
                date: now.slice(0, 10),
                timestamp: now,
                title: `قرار محكمة التمييز: ${labelAr}`,
                description: [`القرار: ${decision.title}`, outcomeLine, `التوقيت: ${when}`].join('\n'),
                type: 'appeal',
                source: 'القرارات والطعون',
            });
        },
        [appealPerspective, decisions, executionId, onTimelineUpdate, persistDecisionsToStorage, setDecisions]
    );

    return { applyCassationCourtDecision };
}

// @ts-nocheck
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { writeExecutorDecisionsUnionForExecution, mergeExecutorDecisionsUnionForPersist, pruneRedundantDecisionsStorageAliases, type ExecutorDecisionsPersistOptions } from '@/app/utils/executionDecisionsNamespace';
import { isSeizureDecisionFollowupComplete } from '@/app/components/lawyer/DecisionsAndAppealsEngine/seizureFollowupComplete';
import {
    buildDomainReconcileSignature,
    filterDecisionsForDomainContext,
    readExecutionDataForDomainGate,
    resolveExecutionDomainContext,
} from '@/app/utils/executionDomainIsolation';
import { normalizeLoadedDecisionRow } from '@/app/components/lawyer/DecisionsAndAppealsEngine/engine/normalizeLoadedDecisionRow';
import {
    readDecisionsSessionCache,
    readDecisionsSessionCacheBest,
    writeDecisionsSessionCache,
} from '@/app/components/lawyer/DecisionsAndAppealsEngine/engine/decisionsSessionCache';
import {
    collectDecisionsStorageCandidateIds,
    normalizeDecisionsExecutionIdProp,
    resolveDecisionsStorageExecutionId,
} from '@/app/components/lawyer/DecisionsAndAppealsEngine/engine/resolveDecisionsStorageExecutionId';
import { readDecisionsUnionAcrossCandidates } from '@/app/components/lawyer/DecisionsAndAppealsEngine/engine/readDecisionsUnionAcrossCandidates';
import {
    purgeManualExecutorAppealArtifacts,
    reconcileTerminatedDecisionArchives,
    reconcileAppealFinalDecisionArchives,
    reconcileAppealDeadlineEnforcement,
} from '@/app/components/lawyer/DecisionsAndAppealsEngine/utils';
import { resolveAppealUiPerspective } from '@/app/components/lawyer/DecisionsAndAppealsEngine/appealUiLabels';
import type { Decision } from '@/app/components/lawyer/DecisionsAndAppealsEngine/types';

export type UseDecisionsAppealsEngineStorageParams = {
    executionId: string | undefined;
    executionDataForSync: Record<string, unknown> | null;
};

function resolveLiveExecutionData(
    executionDataForSync: Record<string, unknown> | null,
    resolvedExecutionId: string
): Record<string, unknown> | null {
    if (executionDataForSync && Object.keys(executionDataForSync).length > 0) {
        return executionDataForSync;
    }
    if (!resolvedExecutionId || resolvedExecutionId === 'default') return null;
    return readExecutionDataForDomainGate(resolvedExecutionId);
}

function collectRemovedDecisionIds(before: Decision[], after: Decision[]): string[] {
    const afterIds = new Set(after.map((d) => String(d.id ?? '').trim()).filter(Boolean));
    return before
        .map((d) => String(d.id ?? '').trim())
        .filter((id) => id && !afterIds.has(id));
}

function normalizeDecisionsFromRaw(raw: Decision[], syncData: Record<string, unknown> | null): Decision[] {
    let normalized = raw.map((d) => normalizeLoadedDecisionRow(d as Decision));
    const purgedManual = purgeManualExecutorAppealArtifacts(normalized);
    normalized = purgedManual.rows;
    const reconciledArchive = reconcileTerminatedDecisionArchives(normalized);
    normalized = reconciledArchive.rows;
    const reconciledAppealFinal = reconcileAppealFinalDecisionArchives(normalized);
    normalized = reconciledAppealFinal.rows;
    const reconciledDeadlines = reconcileAppealDeadlineEnforcement(normalized);
    normalized = reconciledDeadlines.rows;
    if (syncData) {
        normalized = normalized.map((row) => {
            if (String(row.seizureRequestSavedAt || '').trim()) return row;
            if (!isSeizureDecisionFollowupComplete(row, syncData)) return row;
            const ts = String(row.resolvedAt || row.date || new Date().toISOString()).trim();
            return { ...row, seizureRequestSavedAt: ts || new Date().toISOString() };
        });
    }
    return normalized;
}

export function useDecisionsAppealsEngineStorage({
    executionId: executionIdProp,
    executionDataForSync,
}: UseDecisionsAppealsEngineStorageParams) {
    const executionId = useMemo(
        () => normalizeDecisionsExecutionIdProp(executionIdProp),
        [executionIdProp]
    );

    const resolvedExecutionId = useMemo(
        () => resolveDecisionsStorageExecutionId(executionId, executionDataForSync),
        [
            executionId,
            executionDataForSync?.id,
            executionDataForSync?.parentDossierId,
            executionDataForSync?.parentFileId,
        ]
    );

    const storageCandidateIds = useMemo(
        () => collectDecisionsStorageCandidateIds(executionId, executionDataForSync),
        [
            executionId,
            executionDataForSync?.id,
            executionDataForSync?.parentDossierId,
            executionDataForSync?.parentFileId,
        ]
    );

    const lastValidExecutionIdRef = useRef<string | null>(null);
    const reloadGenerationRef = useRef(0);
    const reloadDebounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);
    const reconciledStorageRef = useRef<Set<string>>(new Set());
    const executionDataRef = useRef<Record<string, unknown> | null>(executionDataForSync);
    executionDataRef.current = executionDataForSync;

    const resolveWritableExecutionId = useCallback((): string | null => {
        const data = resolveLiveExecutionData(executionDataRef.current, resolvedExecutionId);
        const id = resolveDecisionsStorageExecutionId(executionId, data);
        if (id && id !== 'default') return id;
        const cached = lastValidExecutionIdRef.current;
        if (cached && cached !== 'default') return cached;
        return null;
    }, [executionId, resolvedExecutionId]);

    const getEffectiveExecutionData = useCallback((): Record<string, unknown> | null => {
        return resolveLiveExecutionData(executionDataRef.current, resolvedExecutionId);
    }, [resolvedExecutionId]);

    const resolvePersistId = useCallback((): string | null => {
        const data = getEffectiveExecutionData();
        const fromWritable = resolveWritableExecutionId();
        if (fromWritable) return fromWritable;

        if (resolvedExecutionId && resolvedExecutionId !== 'default') {
            return resolvedExecutionId;
        }

        const fromProps = resolveDecisionsStorageExecutionId(executionId, data);
        if (fromProps && fromProps !== 'default') return fromProps;

        for (const cid of storageCandidateIds) {
            if (cid && cid !== 'default') return cid;
        }

        const cached = readDecisionsSessionCacheBest(storageCandidateIds);
        if (cached?.length) {
            for (const cid of storageCandidateIds) {
                const hit = readDecisionsSessionCache(cid);
                if (hit?.length) return cid;
            }
        }

        const cachedRef = lastValidExecutionIdRef.current;
        if (cachedRef && cachedRef !== 'default') return cachedRef;

        return null;
    }, [
        executionId,
        getEffectiveExecutionData,
        resolveWritableExecutionId,
        resolvedExecutionId,
        storageCandidateIds,
    ]);

    const writeSessionCacheForCandidates = useCallback(
        (rows: Decision[], persistId: string) => {
            const data = getEffectiveExecutionData();
            const extra = lastValidExecutionIdRef.current
                ? [lastValidExecutionIdRef.current]
                : undefined;
            const aliases = collectDecisionsStorageCandidateIds(executionId, data, extra);
            writeDecisionsSessionCache(persistId, rows, aliases);
        },
        [executionId, getEffectiveExecutionData]
    );

    const readUnionFromStorage = useCallback((): Decision[] => {
        const syncData = getEffectiveExecutionData();
        const extra = lastValidExecutionIdRef.current
            ? [lastValidExecutionIdRef.current]
            : undefined;
        const { rows } = readDecisionsUnionAcrossCandidates(executionId, syncData, extra);
        return normalizeDecisionsFromRaw(rows, syncData);
    }, [executionId, getEffectiveExecutionData]);

    const [decisions, setDecisionsState] = useState<Decision[]>(() => {
        return (
            readDecisionsSessionCacheBest(
                collectDecisionsStorageCandidateIds(executionId, executionDataForSync)
            ) ?? []
        );
    });
    const [decisionsHydrated, setDecisionsHydrated] = useState(() => {
        const cached = readDecisionsSessionCacheBest(
            collectDecisionsStorageCandidateIds(executionId, executionDataForSync)
        );
        return (cached?.length ?? 0) > 0;
    });

    const setDecisions = useCallback((action: React.SetStateAction<Decision[]>) => {
        setDecisionsState(action);
    }, []);

    const domainContextSignature = useMemo(() => {
        const data = resolveLiveExecutionData(executionDataForSync, resolvedExecutionId);
        if (!data) return `${resolvedExecutionId}:none`;
        return buildDomainReconcileSignature(
            resolveExecutionDomainContext(data, resolvedExecutionId)
        );
    }, [
        executionDataForSync?.claimType,
        executionDataForSync?.classification,
        executionDataForSync?.representedParty,
        executionDataForSync?.id,
        executionDataForSync?.parentDossierId,
        resolvedExecutionId,
    ]);

    const persistDecisionsToStorage = useCallback(
        (next: Decision[], opts?: ExecutorDecisionsPersistOptions): Decision[] | null => {
            const data = getEffectiveExecutionData();
            let persistId = resolvePersistId();
            if (!persistId) {
                return null;
            }

            const attemptWrite = (targetId: string): Decision[] | null => {
                lastValidExecutionIdRef.current = targetId;
                const extra = lastValidExecutionIdRef.current
                    ? [lastValidExecutionIdRef.current]
                    : undefined;
                const rows = mergeExecutorDecisionsUnionForPersist(
                    targetId,
                    next as unknown as Record<string, unknown>[],
                    data,
                    { ...opts, extraIds: extra }
                );
                writeExecutorDecisionsUnionForExecution(targetId, rows, data);
                try {
                    pruneRedundantDecisionsStorageAliases(targetId, data);
                } catch {
                    /* prune اختياري — لا يُلغي الحفظ الأساسي */
                }
                const normalized = normalizeDecisionsFromRaw(rows as Decision[], data);
                writeSessionCacheForCandidates(normalized, targetId);
                return normalized;
            };

            try {
                return attemptWrite(persistId);
            } catch {
                for (const altId of storageCandidateIds) {
                    if (!altId || altId === 'default' || altId === persistId) continue;
                    try {
                        persistId = altId;
                        return attemptWrite(altId);
                    } catch {
                        /* جرّب المرشح التالي */
                    }
                }
                return null;
            }
        },
        [
            getEffectiveExecutionData,
            resolvePersistId,
            storageCandidateIds,
            writeSessionCacheForCandidates,
        ]
    );

    const effectiveExecutionData = useMemo(
        () => getEffectiveExecutionData(),
        [domainContextSignature, getEffectiveExecutionData]
    );

    const appealPerspective = useMemo(
        () => resolveAppealUiPerspective(effectiveExecutionData),
        [effectiveExecutionData]
    );

    const executionDomainContext = useMemo(
        () => resolveExecutionDomainContext(effectiveExecutionData, resolvedExecutionId),
        [domainContextSignature, effectiveExecutionData, resolvedExecutionId]
    );

    const domainVisibleDecisions = useMemo(
        () => filterDecisionsForDomainContext(executionDomainContext, decisions),
        [executionDomainContext, decisions]
    );

    const reloadFromStorage = useCallback(() => {
        const generation = ++reloadGenerationRef.current;
        const syncData = getEffectiveExecutionData();
        const extra = lastValidExecutionIdRef.current
            ? [lastValidExecutionIdRef.current]
            : undefined;
        const { canonicalId, rows: rawUnion } = readDecisionsUnionAcrossCandidates(
            executionId,
            syncData,
            extra
        );

        const persistId =
            resolveWritableExecutionId() ??
            (canonicalId !== 'default' ? canonicalId : null);

        if (!persistId) {
            return;
        }

        lastValidExecutionIdRef.current = persistId;
        if (generation !== reloadGenerationRef.current) return;

        const normalized = normalizeDecisionsFromRaw(rawUnion, syncData);
        if (generation !== reloadGenerationRef.current) return;

        let finalRows = normalized;
        setDecisionsState((prev) => {
            if (normalized.length === 0 && prev.length > 0) {
                const retry = readUnionFromStorage();
                finalRows = retry.length > 0 ? retry : prev;
                return finalRows;
            }
            if (normalized.length >= prev.length) {
                finalRows = normalized;
                return normalized;
            }
            const mergedById = new Map<string, Decision>();
            for (const row of [...prev, ...normalized]) {
                const rid = String(row.id ?? '').trim();
                if (rid) mergedById.set(rid, row);
            }
            finalRows = [...mergedById.values()].sort((a, b) => {
                const ad = String(a.resolvedAt ?? a.date ?? '');
                const bd = String(b.resolvedAt ?? b.date ?? '');
                return bd.localeCompare(ad, undefined, { numeric: true });
            });
            return finalRows;
        });
        if (finalRows.length > 0) {
            writeSessionCacheForCandidates(finalRows, persistId);
        }
        setDecisionsHydrated(true);
    }, [
        executionId,
        getEffectiveExecutionData,
        readUnionFromStorage,
        resolveWritableExecutionId,
    ]);

    /** تسوية تخزين لمرة واحدة لكل إضبارة في الجلسة — منفصلة عن كل إعادة تحميل */
    const reconcileStorageOnce = useCallback(() => {
        const syncData = getEffectiveExecutionData();
        const persistId =
            resolvePersistId() ??
            resolveDecisionsStorageExecutionId(executionId, syncData);
        if (!persistId || persistId === 'default') return;
        if (reconciledStorageRef.current.has(persistId)) return;
        reconciledStorageRef.current.add(persistId);

        const { rows: raw } = readDecisionsUnionAcrossCandidates(executionId, syncData);
        if (raw.length === 0) return;

        const normalizedFromRaw = raw.map((d) => normalizeLoadedDecisionRow(d as Decision));
        const purgedManual = purgeManualExecutorAppealArtifacts(normalizedFromRaw);
        let normalized = purgedManual.rows;
        const reconciledArchive = reconcileTerminatedDecisionArchives(normalized);
        normalized = reconciledArchive.rows;
        const reconciledAppealFinal = reconcileAppealFinalDecisionArchives(normalized);
        normalized = reconciledAppealFinal.rows;
        const reconciledDeadlines = reconcileAppealDeadlineEnforcement(normalized);
        normalized = reconciledDeadlines.rows;

        const needsPersist =
            purgedManual.rows.length !== normalizedFromRaw.length ||
            purgedManual.mutated ||
            reconciledArchive.mutated ||
            reconciledAppealFinal.mutated ||
            reconciledDeadlines.mutated;

        if (!needsPersist) return;

        try {
            const removedIds = collectRemovedDecisionIds(normalizedFromRaw, purgedManual.rows);
            const merged = persistDecisionsToStorage(
                normalizeDecisionsFromRaw(normalized, syncData),
                removedIds.length > 0 ? { removedIds } : undefined
            );
            if (merged) {
                setDecisionsState(merged);
            }
        } catch {
            /* ignore */
        }
    }, [executionId, getEffectiveExecutionData, persistDecisionsToStorage, resolvePersistId]);

    useEffect(() => {
        if (resolvedExecutionId && resolvedExecutionId !== 'default') {
            lastValidExecutionIdRef.current = resolvedExecutionId;
        }
    }, [resolvedExecutionId]);

    useEffect(() => {
        const cached = readDecisionsSessionCacheBest(storageCandidateIds);
        if (cached && cached.length > 0) {
            setDecisionsState(cached);
            setDecisionsHydrated(true);
        }
        reloadFromStorage();
        queueMicrotask(() => reconcileStorageOnce());
    }, [resolvedExecutionId, reloadFromStorage, reconcileStorageOnce, storageCandidateIds]);

    useEffect(() => {
        const scheduleReload = () => {
            if (reloadDebounceRef.current) {
                clearTimeout(reloadDebounceRef.current);
            }
            reloadDebounceRef.current = setTimeout(() => {
                reloadDebounceRef.current = null;
                reloadFromStorage();
            }, 120);
        };
        window.addEventListener('hami-decisions-reload', scheduleReload);
        window.addEventListener('hami-execution-decision-outcome', scheduleReload);
        window.addEventListener('hami-seizure-decision-step-saved', scheduleReload);
        window.addEventListener('hami-guarantor-followup-committed', scheduleReload);
        return () => {
            if (reloadDebounceRef.current) {
                clearTimeout(reloadDebounceRef.current);
                reloadDebounceRef.current = null;
            }
            window.removeEventListener('hami-decisions-reload', scheduleReload);
            window.removeEventListener('hami-execution-decision-outcome', scheduleReload);
            window.removeEventListener('hami-seizure-decision-step-saved', scheduleReload);
            window.removeEventListener('hami-guarantor-followup-committed', scheduleReload);
        };
    }, [reloadFromStorage]);

    return {
        decisions,
        decisionsHydrated,
        setDecisions,
        persistDecisionsToStorage,
        appealPerspective,
        executionDomainContext,
        domainVisibleDecisions,
        reloadFromStorage,
        resolvedExecutionId,
        resolveWritableExecutionId,
        getEffectiveExecutionData,
    };
}

// @ts-nocheck
import React from 'react';
import { applyDossierSpecialFollowupOutcome } from '@/app/components/lawyer/ExecutionDashboard/utils/applyDossierSpecialFollowupOutcome';
import {
    normalizeBaseDossierIdFromDecisionsKey,
} from '../engine/decisionsEngineTypes';
import type { DecisionsAppealsMutationsCoreParams } from './decisionsAppealsMutationsTypes';

export type ExecutorResolveOptions = {
    executorNote?: string;
    requireReasoning?: boolean;
};

function dispatchExecutorToast(message: string, type: 'success' | 'warning' | 'info' = 'warning'): void {
    try {
        window.dispatchEvent(new CustomEvent('hami-toast', { detail: { message, type } }));
    } catch {
        /* ignore */
    }
}

export function useDecisionsAppealsExecutorResolve(params: DecisionsAppealsMutationsCoreParams) {
    const {
        executionId,
        decisions,
        setDecisions,
        resolveDecision,
        hubNoteById,
        setHubNoteById,
        setDecisionsHubTab,
        reloadFromStorage,
    } = params;

    const hubNoteByIdRef = React.useRef(hubNoteById);
    hubNoteByIdRef.current = hubNoteById;

    const decisionsRef = React.useRef(decisions);
    decisionsRef.current = decisions;

    const handleExecutorResolveById = React.useCallback(
        (id: string, resolution: 'approved' | 'rejected', options?: ExecutorResolveOptions) => {
            const row = decisionsRef.current.find((d) => d.id === id);
            if (!row) return;

            const note = String(options?.executorNote ?? hubNoteByIdRef.current[id] ?? '').trim();
            if (options?.requireReasoning && !note) {
                dispatchExecutorToast('اكتب تسبيب المنفذ قبل الإرسال');
                return;
            }

            const resolvedAt = new Date().toISOString();
            setDecisions((prev) =>
                prev.map((d) =>
                    String(d.id) === id
                        ? {
                              ...d,
                              executorOutcome: resolution,
                              executorNote: note || undefined,
                              status: resolution === 'approved' ? 'accepted' : 'rejected',
                              resolvedAt,
                          }
                        : d
                )
            );

            resolveDecision({
                row,
                resolution,
                executorNote: note,
            });

            queueMicrotask(() => reloadFromStorage());
            setHubNoteById((p) => {
                const n = { ...p };
                delete n[id];
                return n;
            });
            if (resolution === 'approved') {
                queueMicrotask(() => setDecisionsHubTab('previous'));
            }
            if (resolution === 'approved' && row.requestKind === 'seizure') {
                const dossierId =
                    normalizeBaseDossierIdFromDecisionsKey(executionId) || String(executionId || '').trim();
                const subtype = String((row as any).seizureSubtype || '').trim();
                const resolvedSubtype = subtype
                    ? subtype
                    : /عقار/i.test(`${String(row.title || '')}\n${String(row.body || '')}`)
                      ? 'property'
                      : '';
                if (resolvedSubtype === 'property') {
                    const decisionId = String(row.id || '').trim();
                    if (!decisionId) return;
                    if (String((row as any).seizureRequestSavedAt || '').trim()) return;
                    try {
                        window.dispatchEvent(
                            new CustomEvent('hami-open-seized-property-init', {
                                detail: {
                                    executionId: dossierId,
                                    decisionId,
                                    subject: String(row.title || '').trim() || 'طلب حجز عقار',
                                },
                            })
                        );
                    } catch {}
                    dispatchExecutorToast('موافقة المنفذ على وضع إشارة الحجز — أكمل بيانات العقار.', 'success');
                }
                if (
                    resolvedSubtype === 'property_expert' ||
                    resolvedSubtype === 'property_auction' ||
                    resolvedSubtype === 'property_final_award' ||
                    resolvedSubtype === 'property_reauction_default'
                ) {
                    const rawJson = String((row as any).seizurePayloadJson || '').trim();
                    let seizedPropertyId = '';
                    let step: 'experts' | 'auction' | 'award' | 'reauction_default' | '' = '';
                    if (rawJson) {
                        try {
                            const v = JSON.parse(rawJson) as any;
                            seizedPropertyId = String(v?.seizedPropertyId ?? '').trim();
                        } catch {}
                    }
                    const rowId = String(row.id || '').trim();
                    if (!rowId) return;
                    if (String((row as any).seizureRequestSavedAt || '').trim()) return;
                    if (!seizedPropertyId) {
                        dispatchExecutorToast('طلب عقاري بدون ربط seizedPropertyId داخل القرار.');
                        return;
                    }
                    step =
                        resolvedSubtype === 'property_expert'
                            ? 'experts'
                            : resolvedSubtype === 'property_auction'
                              ? 'auction'
                              : resolvedSubtype === 'property_final_award'
                                ? 'award'
                                : 'reauction_default';
                    try {
                        window.dispatchEvent(
                            new CustomEvent('hami-open-seized-property-step', {
                                detail: {
                                    executionId: dossierId,
                                    decisionId: rowId,
                                    seizedPropertyId,
                                    step,
                                },
                            })
                        );
                    } catch {}
                    dispatchExecutorToast('موافقة المنفذ على خطوة عقارية — أكمل بيانات النتيجة.', 'success');
                }
            }

            /** التوجيه الذكي: طلبات تبويب «التحكم في الإضبارة» */
            if (row.requestKind === 'special_followup') {
                applyDossierSpecialFollowupOutcome({
                    executionId,
                    row: row as Record<string, unknown>,
                    resolution,
                });
            }
        },
        [executionId, resolveDecision, reloadFromStorage, setDecisions, setHubNoteById, setDecisionsHubTab]
    );

    return { handleExecutorResolveById };
}

import React from 'react';
import { dispatchDecisionsReload } from '@/app/utils/executorSeizureDecisionQueue';
import type { Decision } from '../types';
import {
    buildGrievanceResolutionPatch,
    grievancePetitionGranted,
    hubWithInferredAppealOrigin,
    isCreditorInitiatedExecutorRequest,
    newEventId,
} from '../utils';
import { dispatchHeirSubstitutionOutcomeIfAny } from '../engine/decisionsEngineTypes';
import { applyPersonalCoerciveAppealClosure } from '@/app/utils/personalCoerciveAppealSync';
import { applyEvictionAppealClosure } from '@/app/utils/evictionAppealSync';
import type { DecisionsAppealsMutationsCoreParams } from './decisionsAppealsMutationsTypes';

export function useDecisionsAppealsGrievanceMutations(params: DecisionsAppealsMutationsCoreParams) {
    const {
        executionId,
        decisions,
        setDecisions,
        persistDecisionsToStorage,
        appealPerspective,
        reloadFromStorage,
        onTimelineUpdate,
        getMilestoneTimelineSnapshot,
        setDecisionsHubTab,
        goToAppealsWithScroll,
    } = params;

    const applyGrievanceCourtOutcome = React.useCallback(
        (decision: Decision, grievanceAccepted: boolean) => {
            const resolvedAppealPatch = buildGrievanceResolutionPatch(
                decision,
                grievanceAccepted,
                decisions
            );
            const granted = grievancePetitionGranted(decision, grievanceAccepted);
            const now = new Date().toISOString();
            const when = new Date(now).toLocaleString('ar-IQ', {
                dateStyle: 'medium',
                timeStyle: 'short',
            });
            const title = grievanceAccepted ? 'قبول التظلم' : 'رد التظلم';
            const hubGrievance = hubWithInferredAppealOrigin(decision);
            const creditorPartyGrievance = isCreditorInitiatedExecutorRequest(hubGrievance);
            const outcomeLine = (() => {
                if (appealPerspective === 'debtor_agent') {
                    if (grievanceAccepted && granted) {
                        return resolvedAppealPatch.awaitingCassationEntryBy
                            ? creditorPartyGrievance
                                ? 'النتيجة: قُبل تظلم موكّلنا — الطلب مغلق مؤقتاً بانتظار تمييز الدائن.'
                                : 'النتيجة: قُبل تظلم موكّلنا — يتاح للدائن التمييز قبل البت النهائي.'
                            : 'النتيجة: قُبل تظلم موكّلنا — القرار أصبح نافذاً وفق مسار الطعن.';
                    }
                    if (!grievanceAccepted) {
                        return resolvedAppealPatch.appealStatus === 'final'
                            ? creditorPartyGrievance
                                ? 'النتيجة: رُد تظلم موكّلنا — الطلب لصالح الدائن.'
                                : 'النتيجة: رُد التظلم — بقي القرار الأصلي نافذاً.'
                            : creditorPartyGrievance
                              ? 'النتيجة: رُد تظلم موكّلنا — يمكن للدائن التمييز ضمن المهلة.'
                              : 'النتيجة: رُد التظلم — يبقى القرار مرفوضاً ويمكن التمييز ضمن المهلة.';
                    }
                }
                if (granted) {
                    return resolvedAppealPatch.awaitingCassationEntryBy
                        ? 'النتيجة: قُبل التظلم — يتاح للطرف الآخر التمييز قبل نفاذ القرار نهائياً.'
                        : 'النتيجة: قُبل التظلم — القرار أصبح نافذاً وفق مسار الطعن.';
                }
                return resolvedAppealPatch.appealStatus === 'final'
                    ? 'النتيجة: رُد التظلم — بقي القرار الأصلي نافذاً.'
                    : 'النتيجة: رُد التظلم — يبقى القرار مرفوضاً ويمكن التمييز ضمن المهلة.';
            })();
            const srcId = decision.appealSourceDecisionId;
            const logEntry = {
                id: newEventId(),
                at: now,
                message: outcomeLine,
                tone: (granted ? 'emerald' : 'rose') as 'emerald' | 'rose',
            };

            let next: Decision[];
            if (typeof srcId === 'string' && srcId.trim()) {
                const orig = decisions.find((d) => d.id === srcId);
                const mergedOriginal: Decision = {
                    ...(orig ?? decision),
                    ...resolvedAppealPatch,
                    id: srcId,
                    activeAppealCopyId:
                        resolvedAppealPatch.appealStatus === 'final' ? null : orig?.activeAppealCopyId ?? null,
                    appealTimelineLogs: [
                        ...(Array.isArray(orig?.appealTimelineLogs) ? orig.appealTimelineLogs : []),
                        ...(Array.isArray(decision.appealTimelineLogs) ? decision.appealTimelineLogs : []),
                        logEntry,
                    ],
                };
                if (resolvedAppealPatch.appealStatus === 'final') {
                    next = decisions
                        .filter((d) => d.id !== decision.id)
                        .map((d) => (d.id === srcId ? mergedOriginal : d));
                } else {
                    const mergedCopy: Decision = {
                        ...decision,
                        ...resolvedAppealPatch,
                        appealTimelineLogs: [
                            ...(Array.isArray(decision.appealTimelineLogs) ? decision.appealTimelineLogs : []),
                            logEntry,
                        ],
                    };
                    next = decisions.map((d) => {
                        if (d.id === srcId) {
                            return {
                                ...mergedOriginal,
                                activeAppealCopyId: decision.id,
                            };
                        }
                        if (d.id === decision.id) return mergedCopy;
                        return d;
                    });
                }
            } else {
                next = decisions.map((d): Decision => {
                    if (d.id !== decision.id) return d;
                    return {
                        ...d,
                        ...resolvedAppealPatch,
                        appealTimelineLogs: [
                            ...(Array.isArray(d.appealTimelineLogs) ? d.appealTimelineLogs : []),
                            logEntry,
                        ],
                    };
                });
            }

            setDecisions(next);
            persistDecisionsToStorage(next);
            queueMicrotask(() => dispatchDecisionsReload());
            const mergedRowId =
                typeof srcId === 'string' && srcId.trim() ? srcId : decision.id;
            const mergedRow = next.find((x) => x.id === mergedRowId);
            if (mergedRow) {
                dispatchHeirSubstitutionOutcomeIfAny(executionId, mergedRow);
                if (resolvedAppealPatch.appealStatus === 'final') {
                    applyPersonalCoerciveAppealClosure({
                        executionId,
                        row: mergedRow as unknown as Record<string, unknown>,
                        allDecisions: next as unknown as Record<string, unknown>[],
                    });
                    applyEvictionAppealClosure({
                        executionId,
                        row: mergedRow as unknown as Record<string, unknown>,
                        allDecisions: next as unknown as Record<string, unknown>[],
                    });
                }
            }
            onTimelineUpdate({
                id: newEventId(),
                date: now.slice(0, 10),
                timestamp: now,
                title,
                description: [`القرار: ${decision.title}`, outcomeLine, `التوقيت: ${when}`].join('\n'),
                type: 'appeal',
                source: 'القرارات والطعون',
            });
            if (resolvedAppealPatch.appealStatus === 'final') {
                queueMicrotask(() => setDecisionsHubTab('previous'));
            } else if (!granted) {
                queueMicrotask(() => {
                    setDecisionsHubTab('appeals');
                    goToAppealsWithScroll(
                        typeof srcId === 'string' && srcId.trim() ? decision.id : mergedRowId
                    );
                });
            }
        },
        [appealPerspective, decisions, executionId, onTimelineUpdate, persistDecisionsToStorage]
    );

    return { applyGrievanceCourtOutcome };
}

import React, { useEffect, useMemo } from 'react';
import type { Decision } from '../types';
import type { AppealUiPerspective } from '../appealUiLabels';
import {
    sortDecisionsNewestFirst,
    sortDecisionsNewestFirstTerminatedManualLast,
    sortDecisionsAppealActivityNewestFirst,
    resolveAppealsHubFilterOptions,
    resolveAppealHubProponentCategory,
    decisionAppealPipelineActive,
    hubHasActiveAppealLedgerEntry,
    manualExecutorAppealPipelineActive,
    type AppealsHubProponentFilter,
} from '../utils';

export type UseDecisionsAppealsHubListsParams = {
    domainVisibleDecisions: Decision[];
    appealPerspective: AppealUiPerspective;
    requestNeedsExecutorOutcome: (d: Decision) => boolean;
    previousFilter: 'all' | 'approved' | 'rejected';
    previousProponentFilter: AppealsHubProponentFilter;
    appealsProponentFilter: AppealsHubProponentFilter;
    setPreviousProponentFilter: React.Dispatch<React.SetStateAction<AppealsHubProponentFilter>>;
    setAppealsProponentFilter: React.Dispatch<React.SetStateAction<AppealsHubProponentFilter>>;
};

export function useDecisionsAppealsHubLists(params: UseDecisionsAppealsHubListsParams) {
    const {
        domainVisibleDecisions,
        appealPerspective,
        requestNeedsExecutorOutcome,
        previousFilter,
        previousProponentFilter,
        appealsProponentFilter,
        setPreviousProponentFilter,
        setAppealsProponentFilter,
    } = params;

    /** قرارات أصلية فقط (ليس نسخ طعن) — طابور المنفذ ثم الباقي زمنياً */
    const archiveHubDecisions = useMemo(() => {
        const originals = domainVisibleDecisions.filter(
            (d) =>
                !d.appealSourceDecisionId &&
                !d.isArchived &&
                !hubHasActiveAppealLedgerEntry(d)
        );
        const pending = originals.filter((d) => requestNeedsExecutorOutcome(d));
        const rest = originals.filter((d) => !requestNeedsExecutorOutcome(d));
        
        const sortedPending = sortDecisionsNewestFirst(pending);
        const sortedRest = sortDecisionsNewestFirstTerminatedManualLast(rest);

        return [...sortedPending, ...sortedRest];
    }, [domainVisibleDecisions, requestNeedsExecutorOutcome]);

    const archivePendingDecisions = useMemo(
        () => archiveHubDecisions.filter((d) => requestNeedsExecutorOutcome(d)),
        [archiveHubDecisions]
    );
    const archiveSettledDecisions = useMemo(
        () => archiveHubDecisions.filter((d) => !requestNeedsExecutorOutcome(d)),
        [archiveHubDecisions]
    );

    /** القرارات المؤرشفة */
    const archivedDecisions = useMemo(
        () =>
            sortDecisionsNewestFirst(
                domainVisibleDecisions.filter((d) => !d.appealSourceDecisionId && d.isArchived)
            ),
        [domainVisibleDecisions]
    );

    /** سجل الطعون: نسخ مسار الطعن + (للبيانات القديمة) صف واحد يضم مساراً مفتوحاً */
    const appealsHubDecisions = useMemo(
        () =>
            sortDecisionsAppealActivityNewestFirst(
                domainVisibleDecisions.filter((d) => {
                    if (manualExecutorAppealPipelineActive(d)) return true;
                    if (d.manualExecutorLedgerEntry === true) return false;
                    if (d.appealSourceDecisionId) {
                        const src = domainVisibleDecisions.find(
                            (x) => String(x.id) === String(d.appealSourceDecisionId)
                        );
                        if (src?.manualExecutorLedgerEntry === true) return false;
                        return true;
                    }
                    return decisionAppealPipelineActive(d, null);
                })
            ),
        [domainVisibleDecisions]
    );

    const previousHubFilterOptions = useMemo(
        () =>
            resolveAppealsHubFilterOptions(
                archiveSettledDecisions,
                domainVisibleDecisions,
                appealPerspective
            ),
        [appealPerspective, archiveSettledDecisions, domainVisibleDecisions]
    );

    const appealsHubFilterOptions = useMemo(
        () =>
            resolveAppealsHubFilterOptions(
                appealsHubDecisions,
                domainVisibleDecisions,
                appealPerspective
            ),
        [appealPerspective, appealsHubDecisions, domainVisibleDecisions]
    );

    const filteredPreviousSettledDecisions = useMemo(() => {
        return archiveSettledDecisions.filter((d) => {
            if (previousFilter === 'approved') {
                if (
                    d.executorOutcome !== 'approved' &&
                    d.executorOutcome !== 'alternative'
                ) {
                    return false;
                }
            } else if (previousFilter === 'rejected') {
                if (d.executorOutcome !== 'rejected') return false;
            }
            if (previousProponentFilter !== 'all') {
                if (
                    resolveAppealHubProponentCategory(
                        d,
                        domainVisibleDecisions,
                        appealPerspective
                    ) !== previousProponentFilter
                ) {
                    return false;
                }
            }
            return true;
        });
    }, [
        appealPerspective,
        archiveSettledDecisions,
        domainVisibleDecisions,
        previousFilter,
        previousProponentFilter,
    ]);

    const filteredAppealsHubDecisions = useMemo(() => {
        if (appealsProponentFilter === 'all') return appealsHubDecisions;
        return appealsHubDecisions.filter(
            (d) =>
                resolveAppealHubProponentCategory(
                    d,
                    domainVisibleDecisions,
                    appealPerspective
                ) === appealsProponentFilter
        );
    }, [
        appealPerspective,
        appealsHubDecisions,
        appealsProponentFilter,
        domainVisibleDecisions,
    ]);

    useEffect(() => {
        if (
            previousProponentFilter !== 'all' &&
            previousHubFilterOptions.length > 0 &&
            !previousHubFilterOptions.includes(previousProponentFilter)
        ) {
            setPreviousProponentFilter('all');
        }
    }, [previousHubFilterOptions, previousProponentFilter]);

    useEffect(() => {
        if (
            appealsProponentFilter !== 'all' &&
            appealsHubFilterOptions.length > 0 &&
            !appealsHubFilterOptions.includes(appealsProponentFilter)
        ) {
            setAppealsProponentFilter('all');
        }
    }, [appealsHubFilterOptions, appealsProponentFilter]);

    return {
        archiveHubDecisions,
        archivePendingDecisions,
        archiveSettledDecisions,
        archivedDecisions,
        appealsHubDecisions,
        previousHubFilterOptions,
        appealsHubFilterOptions,
        filteredPreviousSettledDecisions,
        filteredAppealsHubDecisions,
    };
}

import React from 'react';
import { SmartToast } from '@/app/components/ui/SmartToast';
import { resolveActiveDecisionsNamespaceSlug } from '@/app/utils/executionDecisionsNamespace';
import { resolveDecisionsStorageExecutionId } from '@/app/components/lawyer/DecisionsAndAppealsEngine/engine/resolveDecisionsStorageExecutionId';
import { applyEvictionAppealClosure } from '@/app/utils/evictionAppealSync';
import { applyPersonalCoerciveAppealClosure } from '@/app/utils/personalCoerciveAppealSync';
import type { Decision } from '../types';
import { newEventId } from '../utils';
import type { DecisionsAppealsMutationsCoreParams } from './decisionsAppealsMutationsTypes';

export function useDecisionsAppealsRowMutations(params: DecisionsAppealsMutationsCoreParams) {
    const {
        decisions,
        setDecisions,
        persistDecisionsToStorage,
        onTimelineUpdate,
        getMilestoneTimelineSnapshot,
        setDecisionsHubTab,
        executionId,
        getEffectiveExecutionData,
        resolveWritableExecutionId,
        newTitle,
        newBody,
        newDate,
        resetAddDecisionForm,
        setShowAddModal,
    } = params;

    const patchDecisionRow = React.useCallback(
        (decisionId: string, patch: Partial<Decision>) => {
            setDecisions((prev) => {
                const next = prev.map((d) => (d.id === decisionId ? { ...d, ...patch } : d));
                return persistDecisionsToStorage(next) ?? next;
            });
        },
        [persistDecisionsToStorage, setDecisions]
    );

    const logAppealTimeline = React.useCallback(
        (title: string, description?: string) => {
            const now = new Date().toISOString();
            const when = new Date(now).toLocaleString('ar-IQ', {
                dateStyle: 'medium',
                timeStyle: 'short',
            });
            onTimelineUpdate({
                id: newEventId(),
                date: now.slice(0, 10),
                timestamp: now,
                title,
                description: [description, `التوقيت: ${when}`].filter(Boolean).join('\n'),
                type: 'appeal',
                source: 'القرارات والطعون',
            });
        },
        [onTimelineUpdate]
    );

    const handleDeleteDecision = React.useCallback((id: string) => {
        setDecisions((prev) => {
            const next = prev.filter((d) => d.id !== id);
            return persistDecisionsToStorage(next, { removedIds: [id] }) ?? next;
        });
    }, [persistDecisionsToStorage, setDecisions]);

    const handleArchiveDecision = React.useCallback((id: string) => {
        setDecisions((prev) => {
            const now = new Date().toISOString();
            const next = prev.map((d) =>
                d.id === id
                    ? {
                          ...d,
                          isArchived: true,
                          requestCycleSuperseded: true,
                          requestCycleSupersededAt: now,
                      }
                    : d
            );
            const synced = persistDecisionsToStorage(next) ?? next;
            const archived = synced.find((d) => d.id === id);
            if (archived) {
                applyPersonalCoerciveAppealClosure({
                    executionId,
                    row: archived as unknown as Record<string, unknown>,
                    allDecisions: synced as unknown as Record<string, unknown>[],
                    forceClose: true,
                });
                applyEvictionAppealClosure({
                    executionId,
                    row: archived as unknown as Record<string, unknown>,
                    allDecisions: synced as unknown as Record<string, unknown>[],
                    forceClose: true,
                });
            }
            queueMicrotask(() => setDecisionsHubTab('archive'));
            return synced;
        });
    }, [executionId, persistDecisionsToStorage, setDecisions, setDecisionsHubTab]);

    const handleAddDecision = () => {
        if (!newTitle.trim() || !newDate) {
            SmartToast.error('يرجى تعبئة العنوان والتاريخ على الأقل');
            return;
        }
        const executionData = getEffectiveExecutionData();
        const persistId =
            resolveWritableExecutionId() ??
            resolveDecisionsStorageExecutionId(executionId, executionData);
        if (!persistId || persistId === 'default') {
            SmartToast.error('تعذّر حفظ القرار — لم يُحدَّد ملف التنفيذ بعد');
            return;
        }
        const domainNamespace = resolveActiveDecisionsNamespaceSlug(persistId, executionData);
        const newDecision: Decision = {
            id: (globalThis as any).crypto?.randomUUID?.() ? (globalThis as any).crypto.randomUUID() : `${Date.now()}_${Math.random().toString(16).slice(2)}`,
            title: newTitle,
            body: newBody,
            date: newDate,
            manualExecutorLedgerEntry: true,
            executorDecisionStatusFlag: 1,
            appealStatus: 'pending',
            appealPhase: null,
            appealWorkflowState: 'NONE',
            domainNamespace,
        };

        const updated = [newDecision, ...decisions];
        let merged = persistDecisionsToStorage(updated);
        if (!merged) {
            merged = persistDecisionsToStorage(updated);
        }
        if (!merged) {
            SmartToast.error('تعذّر حفظ القرار — أعد فتح الإضبارة وحاول مجدداً');
            return;
        }
        setDecisions(merged);

        const now = new Date().toISOString();
        const milestoneSnap = getMilestoneTimelineSnapshot?.();
        onTimelineUpdate({
            id: newEventId(),
            date: newDate,
            timestamp: now,
            title: `إضافة قرار منفذ العدل: ${newTitle}`,
            description: `تاريخ القرار: ${new Date(newDate).toLocaleDateString('ar-EG')}${newBody.trim() ? `\n${newBody.trim()}` : ''}`,
            type: 'decision',
            source: 'القرارات والطعون',
            ...(milestoneSnap !== undefined ? { snapshot: milestoneSnap } : {}),
        });
        
        resetAddDecisionForm();
        setShowAddModal(false);
        setDecisionsHubTab('previous');
    };

    return {
        patchDecisionRow,
        logAppealTimeline,
        handleDeleteDecision,
        handleArchiveDecision,
        handleAddDecision,
    };
}

import React from 'react';
import { dispatchDecisionsReload } from '@/app/utils/executorSeizureDecisionQueue';
import { isExecutionAppealTerminal } from '@/app/utils/executionDecisionAppealActive';
import type { Decision } from '../types';
import { newEventId, appealGrievanceFilingClockPatch, resolveUnderlyingDecisionHub } from '../utils';
import type { DecisionsAppealsMutationsCoreParams } from './decisionsAppealsMutationsTypes';

export function useDecisionsAppealsTransitionWorkflow(params: DecisionsAppealsMutationsCoreParams) {
    const {
        executionId,
        decisions,
        setDecisions,
        persistDecisionsToStorage,
        appealPerspective,
        reloadFromStorage,
        onTimelineUpdate,
        getMilestoneTimelineSnapshot,
        setDecisionsHubTab,
        goToAppealsWithScroll,
    } = params;

    const transitionAppealWorkflow = React.useCallback(
        (
            decision: Decision,
            patch: Partial<Decision>,
            timelineTitle: string,
            timelineDescription: string,
            tone: 'emerald' | 'rose' | 'amber' | 'slate'
        ) => {
            const nowIso = new Date().toISOString();
            const logEntry = {
                id: newEventId(),
                at: nowIso,
                message: timelineDescription,
                tone,
            };
            const target = decisions.find((d) => d.id === decision.id);
            if (!target) return;
            const appealHub = resolveUnderlyingDecisionHub(target, decisions);
            if (
                target.manualExecutorLedgerEntry === true ||
                appealHub.manualExecutorLedgerEntry === true
            ) {
                return;
            }
            const hasMeaningfulChange = Object.entries(patch).some(([k, v]) => {
                const prevVal = (target as any)[k];
                if (Array.isArray(prevVal) || Array.isArray(v)) {
                    return JSON.stringify(prevVal) !== JSON.stringify(v);
                }
                return prevVal !== v;
            });
            if (!hasMeaningfulChange) return;

            const opensAppealCopy =
                !target.appealSourceDecisionId &&
                (patch.appealStatus === 'tadhallum_filed' || patch.appealStatus === 'tamyeez_filed');
            const grievanceClockPatch =
                patch.appealStatus === 'tadhallum_filed' || patch.appealMethod === 'tadhallum'
                    ? appealGrievanceFilingClockPatch()
                    : {};
            const mergedPatch = { ...patch, ...grievanceClockPatch };

            if (opensAppealCopy) {
                /** إن وُجدت بالفعل نسخة طعن للأصل (مثلاً بعد تظلم) لا نُنشئ نسخة ثانية — ندمج التمييز فيها */
                const linkedId = target.activeAppealCopyId;
                if (linkedId) {
                    const linked = decisions.find((d) => d.id === linkedId);
                    if (
                        linked &&
                        !isExecutionAppealTerminal(linked) &&
                        String(linked.appealSourceDecisionId ?? '') === String(target.id)
                    ) {
                        const nextLinked = decisions.map((d) =>
                            d.id === linked.id
                                ? {
                                      ...d,
                                      ...mergedPatch,
                                      appealTimelineLogs: [
                                          logEntry,
                                          ...(Array.isArray(d.appealTimelineLogs) ? d.appealTimelineLogs : []),
                                      ],
                                  }
                                : d
                        );
                        setDecisions(nextLinked);
                        persistDecisionsToStorage(nextLinked);
                        queueMicrotask(() => dispatchDecisionsReload());
                        const appealOpenSnap = getMilestoneTimelineSnapshot?.();
                        onTimelineUpdate({
                            id: newEventId(),
                            date: nowIso.slice(0, 10),
                            timestamp: nowIso,
                            title: timelineTitle,
                            description: timelineDescription,
                            type: 'appeal',
                            source: 'القرارات والطعون',
                            ...(appealOpenSnap !== undefined ? { snapshot: appealOpenSnap } : {}),
                        });
                        goToAppealsWithScroll(linked.id);
                        return;
                    }
                }
                const copyId = `appeal_copy_${Date.now()}_${Math.random().toString(36).slice(2, 9)}`;
                const baseLogs = Array.isArray(target.appealTimelineLogs) ? target.appealTimelineLogs : [];
                const {
                    appealSourceDecisionId: _dropSrc,
                    activeAppealCopyId: _dropAct,
                    ...restTarget
                } = target;
                const copy: Decision = {
                    ...restTarget,
                    id: copyId,
                    appealSourceDecisionId: target.id,
                    ...mergedPatch,
                    appealTimelineLogs: [logEntry, ...baseLogs],
                };
                const cleanedOriginal: Decision = {
                    ...target,
                    appealActor: null,
                    appealMethod: null,
                    appealPhase: null,
                    appealWorkflowState: 'NONE',
                    appealStatus: 'pending',
                    appealResult: undefined,
                    awaitingCassationEntryBy: null,
                    grievanceRejectedAwaitingTamyeez: false,
                    grievanceAcceptedAwaitingDebtorTamyeez: false,
                    manualGrievanceAppellants: undefined,
                    manualCassationAppellants: undefined,
                    activeAppealCopyId: copyId,
                    appealTimelineLogs: baseLogs,
                };
                const next = decisions.map((d) => (d.id === target.id ? cleanedOriginal : d)).concat([copy]);
                setDecisions(next);
                persistDecisionsToStorage(next);
                queueMicrotask(() => dispatchDecisionsReload());
                const appealOpenSnap = getMilestoneTimelineSnapshot?.();
                onTimelineUpdate({
                    id: newEventId(),
                    date: nowIso.slice(0, 10),
                    timestamp: nowIso,
                    title: timelineTitle,
                    description: timelineDescription,
                    type: 'appeal',
                    source: 'القرارات والطعون',
                    ...(appealOpenSnap !== undefined ? { snapshot: appealOpenSnap } : {}),
                });
                goToAppealsWithScroll(copyId);
                return;
            }

            let next = decisions.map((d) =>
                d.id === decision.id
                    ? {
                          ...d,
                          ...mergedPatch,
                          appealTimelineLogs: [
                              logEntry,
                              ...(Array.isArray(d.appealTimelineLogs) ? d.appealTimelineLogs : []),
                          ],
                      }
                    : d
            );
            const merged = next.find((x) => x.id === decision.id);
            if (merged?.appealSourceDecisionId && isExecutionAppealTerminal(merged)) {
                const src = merged.appealSourceDecisionId;
                next = next.map((d) =>
                    d.id === src ? { ...d, activeAppealCopyId: null } : d
                );
            }
            setDecisions(next);
            persistDecisionsToStorage(next);
            queueMicrotask(() => dispatchDecisionsReload());
            onTimelineUpdate({
                id: newEventId(),
                date: nowIso.slice(0, 10),
                timestamp: nowIso,
                title: timelineTitle,
                description: timelineDescription,
                type: 'appeal',
                source: 'القرارات والطعون',
            });
        },
        [decisions, goToAppealsWithScroll, getMilestoneTimelineSnapshot, onTimelineUpdate, persistDecisionsToStorage]
    );

    /** تسجيل طعن على قرار منفذ من البطاقة — مرحلة + طاعن (أو أكثر) */
    return { transitionAppealWorkflow };
}

import React, { useEffect } from 'react';
import { SmartToast } from '@/app/components/ui/SmartToast';
import { applyWaiveCassationAfterDebtorGrievanceForExecution } from '@/app/utils/waiveCassationAfterDebtorGrievance';
import {
    buildWaiveInitialAppealPatch,
    canWaiveFavorableExecutorOutcome,
    canWaiveInitialAppeal,
} from '@/app/utils/waiveInitialAppeal';
import { applyEvictionAppealClosure } from '@/app/utils/evictionAppealSync';
import { applyPersonalCoerciveAppealClosure } from '@/app/utils/personalCoerciveAppealSync';
import { dispatchDecisionsReload } from '@/app/utils/executorSeizureDecisionQueue';
import type { Decision } from '../types';
import { newEventId, canWaiveLawyerAwaitingCassation } from '../utils';
import type { DecisionsAppealsMutationsCoreParams } from './decisionsAppealsMutationsTypes';

export function useDecisionsAppealsWaiveAppealMutations(params: DecisionsAppealsMutationsCoreParams) {
    const {
        executionId,
        decisions,
        setDecisions,
        persistDecisionsToStorage,
        appealPerspective,
        reloadFromStorage,
        onTimelineUpdate,
        getMilestoneTimelineSnapshot: _getMilestoneTimelineSnapshot,
        setDecisionsHubTab,
        goToAppealsWithScroll: _goToAppealsWithScroll,
    } = params;

    const applyWaiveCassationAfterDebtorGrievance = React.useCallback(
        (decision: Decision) => {
            if (!canWaiveLawyerAwaitingCassation(decision, decisions)) {
                SmartToast.error('لا يمكن إتمام الاستغناء عن التمييز في هذه الحالة.');
                return;
            }
            const result = applyWaiveCassationAfterDebtorGrievanceForExecution({
                executionId,
                decisionId: decision.id,
            });
            if (!result.ok) {
                SmartToast.error(result.message ?? 'تعذّر تسجيل الاستغناء عن التمييز.');
                return;
            }
            const now = new Date().toISOString();
            const when = new Date(now).toLocaleString('ar-IQ', {
                dateStyle: 'medium',
                timeStyle: 'short',
            });
            reloadFromStorage();
            onTimelineUpdate({
                id: newEventId(),
                date: now.slice(0, 10),
                timestamp: now,
                title: 'لا حاجة للتمييز',
                description: [
                    `القرار: ${decision.title}`,
                    result.message ?? 'قُبل التظلم دون تمييز — انتهت دورة الطلب.',
                    `التوقيت: ${when}`,
                ].join('\n'),
                type: 'appeal',
                source: 'القرارات والطعون',
            });
            queueMicrotask(() => setDecisionsHubTab('archive'));
        },
        [decisions, executionId, onTimelineUpdate, reloadFromStorage, setDecisionsHubTab]
    );

    const applyWaiveInitialAppeal = React.useCallback(
        (decision: Decision) => {
            if (!canWaiveInitialAppeal(decision, decisions, appealPerspective)) {
                SmartToast.error('لا يمكن إتمام الاستغناء عن الطعن في هذه الحالة.');
                return;
            }

            const favorable = canWaiveFavorableExecutorOutcome(decision, appealPerspective);
            const patch = buildWaiveInitialAppealPatch(decision, { favorable });
            const outcomeLine = favorable
                ? 'لا حاجة للطعن — القرار لمصلحتنا وأُغلقت دورة الطلب دون انتظار مهلة الطرف الآخر.'
                : appealPerspective === 'debtor_agent'
                  ? 'لا حاجة للطعن — قُبل قرار المنفذ دون تظلم أو تمييز من موكّلنا وأُغلقت المهلة.'
                  : 'لا حاجة للطعن — قُبل قرار المنفذ دون تقديم تظلم أو تمييز وأُغلقت دورة الطلب.';
            const now = new Date().toISOString();
            const logEntry = {
                id: newEventId(),
                at: now,
                message: outcomeLine,
                tone: 'slate' as const,
            };

            const next = decisions.map((d): Decision => {
                if (d.id !== decision.id) return d;
                return {
                    ...d,
                    ...patch,
                    appealTimelineLogs: [
                        ...(Array.isArray(d.appealTimelineLogs) ? d.appealTimelineLogs : []),
                        logEntry,
                    ],
                };
            });

            // نفس مسار التظلم — يحلّ معرّف التخزين الصحيح (لا يكتب على executionId الخاطئ بصمت)
            setDecisions(next);
            const persisted = persistDecisionsToStorage(next);
            if (!persisted) {
                SmartToast.error('تعذّر حفظ الاستغناء عن الطعن. أعد المحاولة.');
                return;
            }
            queueMicrotask(() => dispatchDecisionsReload());

            const mergedRow = persisted.find((x) => x.id === decision.id) ?? next.find((x) => x.id === decision.id);
            if (mergedRow) {
                applyPersonalCoerciveAppealClosure({
                    executionId,
                    row: mergedRow as unknown as Record<string, unknown>,
                    allDecisions: persisted as unknown as Record<string, unknown>[],
                });
                applyEvictionAppealClosure({
                    executionId,
                    row: mergedRow as unknown as Record<string, unknown>,
                    allDecisions: persisted as unknown as Record<string, unknown>[],
                });
            }

            const when = new Date(now).toLocaleString('ar-IQ', {
                dateStyle: 'medium',
                timeStyle: 'short',
            });
            onTimelineUpdate({
                id: newEventId(),
                date: now.slice(0, 10),
                timestamp: now,
                title: 'لا حاجة للطعن',
                description: [
                    `القرار: ${decision.title}`,
                    outcomeLine,
                    `التوقيت: ${when}`,
                ].join('\n'),
                type: 'appeal',
                source: 'القرارات والطعون',
            });
            SmartToast.success(outcomeLine);
            queueMicrotask(() => setDecisionsHubTab('archive'));
        },
        [
            appealPerspective,
            decisions,
            executionId,
            onTimelineUpdate,
            persistDecisionsToStorage,
            setDecisions,
            setDecisionsHubTab,
        ]
    );

    useEffect(() => {
        const handler = (e: Event) => {
            const detail = (e as CustomEvent<{ executionId?: string; decisionId?: string }>).detail;
            if (executionId && detail?.executionId && detail.executionId !== executionId) return;
            const decisionId = String(detail?.decisionId || '').trim();
            if (!decisionId) return;
            const row = decisions.find((d) => d.id === decisionId);
            if (!row) return;
            applyWaiveCassationAfterDebtorGrievance(row);
        };
        window.addEventListener('hami-waive-cassation-for-decision', handler as EventListener);
        return () => window.removeEventListener('hami-waive-cassation-for-decision', handler as EventListener);
    }, [applyWaiveCassationAfterDebtorGrievance, decisions, executionId]);

    return { applyWaiveCassationAfterDebtorGrievance, applyWaiveInitialAppeal };
}

import type { Decision } from '../../types';


import {
    type AppealUiPerspective,
} from '../../appealUiLabels';
import { resolveUnderlyingDecisionHub } from '../decisionGraphUtils';
import {
    hubWithInferredAppealOrigin,
    isCreditorInitiatedExecutorRequest,
    isCreditorExecutorAppealSubject,
    resolveRequestProponent,
} from '../appealRequestOrigin';
import { isManualExecutorLedgerDecision } from './manualExecutorIdentity';
import {
    buildManualExecutorGrievanceOutcomePatch,
    manualExecutorAwaitingCassationParty,
    manualExecutorCassationPartyAfterGrievance,
    resolveManualExecutorGrievanceFiler,
} from './manualExecutorLedger';
import { appealGrievanceOutcomeClockPatch } from './appealDates';
import {
    appellantLabelFromLogMessage,
    resolveAppealActorLabel,
} from './appealProceedingsActors';

export type DecisionsAppealsAppealSlot = 'appealsTab' | 'previousCard';

export function appealEntryShowsDebtorFirst(
    d: Decision,
    perspective: AppealUiPerspective = 'creditor_agent'
): boolean {
    return resolveHarmedPartyAppealActor(d, perspective) === 'debtor';
}

/** وكيل الدائن — إحضار جبري بقرار المنفذ أو طلب دائن مُوافق عليه: الطعن للمدين فقط */
export function creditorAgentDebtorIsSoleAppellant(
    d: Decision,
    perspective: AppealUiPerspective = 'creditor_agent'
): boolean {
    if (perspective !== 'creditor_agent') return false;
    if (d.activatedByExecutorOrder === true) return true;
    if (
        d.appealRequestOrigin === 'executor_side' &&
        d.requestKind === 'personal_coercive'
    ) {
        return true;
    }
    if (d.appealRequestOrigin === 'executor_side') return false;
    return resolveHarmedPartyAppealActor(d, perspective) === 'debtor';
}

/** موافقة منفذ يحق بعدها للمدين التظلم — كل أنواع الطلبات */
export function isDebtorAppealEligibleApprovedHub(
    hub: Decision,
    perspective: AppealUiPerspective = 'creditor_agent'
): boolean {
    const phys = hub.executorOutcome;
    if (phys !== 'approved' && phys !== 'alternative') return false;
    if (isCreditorExecutorAppealSubject(hub, perspective)) return true;
    if (creditorAgentDebtorIsSoleAppellant(hub, perspective)) return true;
    if (perspective === 'creditor_agent' && resolveHarmedPartyAppealActor(hub, perspective) === 'debtor') {
        return true;
    }
    return false;
}

/** الطرف المتضرر الذي يحق له تقديم التظلم أو التمييز المباشر */
export function resolveHarmedPartyAppealActor(
    d: Decision,
    perspective: AppealUiPerspective = 'creditor_agent'
): 'lawyer' | 'debtor' | null {
    if (d.appealRequestOrigin === 'executor_side') {
        const ex = d.executorOutcome;
        if (d.activatedByExecutorOrder === true || d.requestKind === 'personal_coercive') {
            if (ex === 'approved' || ex === 'alternative') return 'debtor';
            if (ex === 'rejected') return 'lawyer';
        }
        return null;
    }
    const proponent = resolveRequestProponent(d, perspective);
    const ex = d.executorOutcome;
    if (ex === 'approved' || ex === 'alternative') {
        return proponent === 'creditor' ? 'debtor' : 'lawyer';
    }
    if (ex === 'rejected') {
        return proponent === 'creditor' ? 'lawyer' : 'debtor';
    }
    return null;
}

export function resolveAppealBaseBranch(d: Decision): 'after_approval' | 'after_rejection' {
    if (d.appealBaseBranch === 'after_rejection' || d.appealBaseBranch === 'after_approval') {
        return d.appealBaseBranch;
    }
    return d.executorOutcome === 'rejected' ? 'after_rejection' : 'after_approval';
}

/** مُقدّم التظلم — يُستنتج من نتيجة الطعن وفرع القرار (لا يعتمد على appealActor القديم وحده) */
export function resolveGrievanceFilerActor(
    d: Decision,
    perspective: AppealUiPerspective = 'creditor_agent'
): 'lawyer' | 'debtor' | null {
    if (isManualExecutorLedgerDecision(d)) {
        return resolveManualExecutorGrievanceFiler(d);
    }
    const hub = hubWithInferredAppealOrigin(d);
    const creditorRow = isCreditorInitiatedExecutorRequest(hub);
    const branch = resolveAppealBaseBranch(hub);
    const result = String(d.appealResult ?? '').trim();

    if (result === 'قبول التظلم' || result === 'رد التظلم') {
        if (branch === 'after_approval' && creditorRow) return 'debtor';
        if (branch === 'after_rejection' && creditorRow) return 'lawyer';
        if (branch === 'after_approval' && !creditorRow) return 'lawyer';
        if (branch === 'after_rejection' && !creditorRow) return 'debtor';
    }

    if (d.appealStatus === 'tadhallum_filed' || d.appealPhase === 'grievance') {
        if (d.appealActor === 'lawyer' || d.appealActor === 'debtor') return d.appealActor;
        if (branch === 'after_approval' && creditorRow) return 'debtor';
        if (branch === 'after_rejection' && creditorRow) return 'lawyer';
    }

    if (d.appealActor === 'lawyer' || d.appealActor === 'debtor') return d.appealActor;
    return null;
}

/** true = المُطعّن فاز بالتظلم (قبول التظلم) */
export function grievancePetitionGranted(d: Decision, grievanceAccepted: boolean): boolean {
    if (!grievanceAccepted) return false;
    if (isManualExecutorLedgerDecision(d)) return true;

    const hub = hubWithInferredAppealOrigin(d);
    const filer = resolveGrievanceFilerActor(d);
    const filerIsDebtor = filer === 'debtor';
    const branch = resolveAppealBaseBranch(hub);
    const creditorRow = isCreditorInitiatedExecutorRequest(hub);

    if (!creditorRow) {
        return filerIsDebtor;
    }

    if (branch === 'after_rejection') {
        return filer === 'lawyer';
    }
    return filerIsDebtor;
}

/** الطرف المخالف الذي يحق له التمييز بعد قبول تظلم الطرف الآخر */
export function cassationEntryPartyAfterGrievanceGrant(d: Decision): 'lawyer' | 'debtor' | null {
    if (isManualExecutorLedgerDecision(d)) {
        return manualExecutorCassationPartyAfterGrievance(d, true);
    }
    const branch = resolveAppealBaseBranch(d);
    const filer = resolveGrievanceFilerActor(d);
    const filerIsDebtor = filer === 'debtor';
    const hub = hubWithInferredAppealOrigin(d);
    const creditorRow = isCreditorInitiatedExecutorRequest(hub);
    if (branch === 'after_rejection' && creditorRow && filer === 'lawyer') return 'debtor';
    if (branch === 'after_approval' && creditorRow && filerIsDebtor) return 'lawyer';
    if (branch === 'after_rejection' && !creditorRow && filerIsDebtor) return 'lawyer';
    if (branch === 'after_approval' && !creditorRow && filer === 'lawyer') return 'debtor';
    return null;
}

function attachGrievanceOutcomeCassationClock(
    patch: Partial<Decision>,
    outcomeIssuedYmd?: string
): Partial<Decision> {
    const needsClock =
        Boolean(patch.awaitingCassationEntryBy) ||
        patch.grievanceRejectedAwaitingTamyeez === true ||
        patch.grievanceAcceptedAwaitingDebtorTamyeez === true;
    if (!needsClock) return patch;
    return { ...patch, ...appealGrievanceOutcomeClockPatch(outcomeIssuedYmd) };
}

export function buildGrievanceResolutionPatch(
    d: Decision,
    grievanceAccepted: boolean,
    all?: Decision[],
    outcomeIssuedYmd?: string
): Partial<Decision> {
    const underlying =
        all && all.length > 0 ? resolveUnderlyingDecisionHub(d, all) : d;
    if (isManualExecutorLedgerDecision(d) || isManualExecutorLedgerDecision(underlying)) {
        return buildManualExecutorGrievanceOutcomePatch(d, grievanceAccepted, outcomeIssuedYmd);
    }
    const hub = hubWithInferredAppealOrigin(d);
    const granted = grievancePetitionGranted(d, grievanceAccepted);
    const branch = resolveAppealBaseBranch(hub);
    const appealResult: NonNullable<Decision['appealResult']> = grievanceAccepted
        ? 'قبول التظلم'
        : 'رد التظلم';
    const phys = hub.executorOutcome;
    const creditorRow = isCreditorInitiatedExecutorRequest(hub);

    /** تظلم المدين على طلب دائن موافق عليه (حجز/تخلية/جبري…) — إيقاف مؤقت لا إعادة دورة */
    if (
        grievanceAccepted &&
        creditorRow &&
        (phys === 'approved' || phys === 'alternative') &&
        branch === 'after_approval' &&
        resolveGrievanceFilerActor(d) === 'debtor'
    ) {
        return attachGrievanceOutcomeCassationClock(
            {
                appealPhase: null,
                appealStatus: 'pending',
                appealResult,
                appealWorkflowState: 'PENDING_APPEAL_LAWYER',
                executorOutcome: phys,
                status: 'accepted',
                awaitingCassationEntryBy: 'lawyer',
                grievanceRejectedAwaitingTamyeez: false,
                grievanceAcceptedAwaitingDebtorTamyeez: false,
                appealMethod: 'tadhallum',
                noAppealChosen: false,
            },
            outcomeIssuedYmd
        );
    }

    if (granted) {
        const outcome =
            branch === 'after_rejection'
                ? { executorOutcome: 'approved' as const, status: 'accepted' as const }
                : { executorOutcome: 'approved' as const, status: 'accepted' as const };
        const cassationParty = cassationEntryPartyAfterGrievanceGrant(d);
        if (cassationParty) {
            return attachGrievanceOutcomeCassationClock(
                {
                    appealPhase: null,
                    appealStatus: 'pending',
                    appealResult,
                    appealWorkflowState:
                        cassationParty === 'debtor'
                            ? ('PENDING_APPEAL_DEBTOR' as const)
                            : ('PENDING_APPEAL_LAWYER' as const),
                    ...outcome,
                    awaitingCassationEntryBy: cassationParty,
                    grievanceRejectedAwaitingTamyeez: false,
                    grievanceAcceptedAwaitingDebtorTamyeez: cassationParty === 'debtor',
                    appealMethod: 'tadhallum',
                    noAppealChosen: false,
                },
                outcomeIssuedYmd
            );
        }
        return {
            appealPhase: null,
            appealStatus: 'final',
            appealResult,
            appealWorkflowState:
                branch === 'after_rejection' ? ('FINAL_ACCEPTED' as const) : ('FINAL_REJECTED' as const),
            ...outcome,
            awaitingCassationEntryBy: null,
            grievanceRejectedAwaitingTamyeez: false,
            grievanceAcceptedAwaitingDebtorTamyeez: false,
            appealMethod: 'tadhallum',
            noAppealChosen: false,
        };
    }

    const standing =
        branch === 'after_rejection'
            ? { executorOutcome: 'rejected' as const, status: 'rejected' as const }
            : { executorOutcome: 'approved' as const, status: 'accepted' as const };

    if (branch === 'after_approval') {
        return attachGrievanceOutcomeCassationClock(
            {
                appealPhase: null,
                appealStatus: 'pending',
                appealResult,
                appealWorkflowState: 'PENDING_APPEAL_DEBTOR',
                ...standing,
                awaitingCassationEntryBy: 'debtor',
                grievanceRejectedAwaitingTamyeez: true,
                grievanceAcceptedAwaitingDebtorTamyeez: false,
                appealMethod: null,
                noAppealChosen: false,
            },
            outcomeIssuedYmd
        );
    }

    return attachGrievanceOutcomeCassationClock(
        {
            appealPhase: null,
            appealStatus: 'pending',
            appealResult,
            appealWorkflowState: 'NONE',
            ...standing,
            grievanceRejectedAwaitingTamyeez: true,
            grievanceAcceptedAwaitingDebtorTamyeez: false,
            awaitingCassationEntryBy: d.appealActor ?? null,
            appealMethod: null,
            noAppealChosen: false,
        },
        outcomeIssuedYmd
    );
}

export function petitionGrantedAfterCassation(d: Decision, choice: 'rad_laheeza' | 'naqd'): boolean {
    const filerIsDebtor = resolveCassationFilerActor(d) === 'debtor';
    const rad = choice === 'rad_laheeza';
    const hub = hubWithInferredAppealOrigin(d);
    const creditorRow = isCreditorInitiatedExecutorRequest(hub);

    if (creditorRow) {
        return filerIsDebtor ? rad : !rad;
    }

    const branch = resolveAppealBaseBranch(hub);
    if (branch === 'after_approval') {
        if (filerIsDebtor) return !rad;
        return rad;
    }
    if (filerIsDebtor) return !rad;
    return rad;
}

export function cassationButtonTitles(
    decision: Decision,
    perspective: import('../../appealUiLabels').AppealUiPerspective = 'creditor_agent'
): { rad: string; naqd: string } {
    const hub = hubWithInferredAppealOrigin(decision);
    const creditorPartyRequest = isCreditorInitiatedExecutorRequest(hub);
    const trueDebtorRequest = !creditorPartyRequest;
    if (perspective === 'debtor_agent') {
        if (trueDebtorRequest) {
            return {
                rad: 'تصديق القرار يعني تثبيت ما قرره المنفذ لصالح موكّلنا في هذا الطلب.',
                naqd: 'نقض القرار يعني تغيير نتيجة المنفذ لصالح موكّلنا — وفق مسار التمييز.',
            };
        }
        return {
            rad: 'تصديق القرار يعني تثبيت قرار المنفذ بشأن طلب الدائن.',
            naqd: 'نقض القرار يعني نقض قرار المنفذ في شأن طلب الدائن — لصالح موكّلنا عند الاقتضاء.',
        };
    }
    if (creditorPartyRequest) {
        return {
            rad: 'تصديق القرار يعني تثبيت طلبنا وما سجّله المنفذ لصالح طلب التنفيذ الذي قدّمناه.',
            naqd: 'نقض هذا القرار يعني رفض طلب المدين وإيقاف الإجراء — بحسب ما ينطبق على هذه الإضبارة.',
        };
    }
    return {
        rad: 'تصديق القرار يعني تثبيت ما قرره المنفذ بشأن طلب الطرف الآخر (المدين).',
        naqd: 'نقض القرار يعني تغيير نتيجة المنفذ في شأن طلب المدين — قبولاً أو رفضاً نهائياً وفق مسار التمييز.',
    };
}

const CASSATION_APPEAL_RESULTS = new Set(['رد اللائحة', 'نقض القرار', 'تصديق القرار']);

/** من قدّم التمييز فعلياً — الطرف المخالف بعد قبول تظلم الطرف الآخر */
export function resolveCassationFilerActor(d: Decision): 'lawyer' | 'debtor' | null {
    if (isManualExecutorLedgerDecision(d)) {
        const manual = d.manualCassationAppellants ?? [];
        if (manual.length === 1) return manual[0]!;
        if (d.appealStatus === 'tamyeez_filed' || d.appealPhase === 'cassation') {
            if (d.appealActor === 'lawyer' || d.appealActor === 'debtor') return d.appealActor;
        }
        return manualExecutorAwaitingCassationParty(d);
    }
    const logs = Array.isArray(d.appealTimelineLogs) ? [...d.appealTimelineLogs] : [];
    logs.sort((a, b) => new Date(a.at).getTime() - new Date(b.at).getTime());

    for (let i = logs.length - 1; i >= 0; i--) {
        const m = String(logs[i]?.message || '');
        if (/تم تسجيل تمييز|تسجيل تمييز|سُجِّل تمييز|تمييز المدين|تمييز وكيل/.test(m)) {
            if (/تمييز المدين|المدين.*تمييز/.test(m)) return 'debtor';
            if (/تمييز وكيل|وكيل الدائن/.test(m)) return 'lawyer';
            const fromLog = appellantLabelFromLogMessage(m);
            if (fromLog === 'المدين') return 'debtor';
            if (fromLog === 'الدائن') return 'lawyer';
        }
    }

    const methods = inferAppealMethodsUsed(d);
    const grievanceAccepted =
        d.appealResult === 'قبول التظلم' ||
        logs.some((l) => /قبول التظلم|قُبل التظلم/.test(String(l.message || '')));

    if (methods.tadhallum && methods.tamyeez && grievanceAccepted) {
        const party = cassationEntryPartyAfterGrievanceGrant(d);
        if (party) return party;
    }

    if (
        d.appealMethod === 'tamyeez' ||
        d.appealPhase === 'cassation' ||
        d.appealStatus === 'tamyeez_filed' ||
        CASSATION_APPEAL_RESULTS.has(String(d.appealResult || '').trim())
    ) {
        if (d.awaitingCassationEntryBy === 'lawyer' || d.awaitingCassationEntryBy === 'debtor') {
            return d.awaitingCassationEntryBy;
        }
        if (d.appealActor === 'lawyer' || d.appealActor === 'debtor') {
            const grievanceOnly =
                methods.tadhallum &&
                grievanceAccepted &&
                d.appealMethod !== 'tamyeez' &&
                d.appealPhase !== 'cassation' &&
                d.appealStatus !== 'tamyeez_filed';
            if (!grievanceOnly) return d.appealActor;
            const entitled = cassationEntryPartyAfterGrievanceGrant(d);
            if (entitled) return entitled;
        }
    }

    if (d.grievanceRejectedAwaitingTamyeez) {
        return d.awaitingCassationEntryBy ?? d.appealActor ?? null;
    }

    return d.awaitingCassationEntryBy ?? d.appealActor ?? null;
}

export function resolveCassationAppellantLabel(
    d: Decision,
    perspective: AppealUiPerspective = 'creditor_agent'
): string {
    const actor = resolveCassationFilerActor(d);
    if (actor === 'lawyer') return 'الدائن';
    if (actor === 'debtor') return perspective === 'debtor_agent' ? 'موكّلنا' : 'المدين';
    return resolveAppealActorLabel(d, perspective);
}

export function inferAppealMethodsUsed(d: Decision): { tadhallum: boolean; tamyeez: boolean } {
    const logs = Array.isArray(d.appealTimelineLogs) ? d.appealTimelineLogs : [];
    const logText = logs.map((l) => l.message).join('\n');
    const appealResult = String(d.appealResult || '').trim();
    const grievanceOutcomeOnly =
        (appealResult === 'قبول التظلم' || appealResult === 'رد التظلم') &&
        d.appealStatus !== 'tamyeez_filed' &&
        d.appealPhase !== 'cassation';
    const tamyeez =
        d.appealStatus === 'tamyeez_filed' ||
        d.appealPhase === 'cassation' ||
        Boolean(String(d.tamyeezDecisionNumber || '').trim()) ||
        CASSATION_APPEAL_RESULTS.has(appealResult) ||
        appealResult === 'نقض القرار' ||
        (!grievanceOutcomeOnly &&
            (d.appealMethod === 'tamyeez' ||
                /تم تسجيل تمييز|تسجيل تمييز|سُجِّل تمييز|تمييز المدين|تمييز وكيل/.test(logText) ||
                (/رد اللائحة|نقض القرار|تصديق القرار/.test(logText) && !/تظلم/.test(logText))));
    const tadhallum =
        d.appealMethod === 'tadhallum' ||
        d.appealPhase === 'grievance' ||
        d.appealStatus === 'tadhallum_filed' ||
        appealResult === 'قبول التظلم' ||
        appealResult === 'رد التظلم' ||
        /تظلم/.test(logText) ||
        /قبول التظلم|رد التظلم/.test(logText);
    return { tadhallum, tamyeez };
}

