                    persistExecutionMerge={vi.fn()}
                    pushTimelineEvent={vi.fn()}
                    nextTimelineId={() => 'tl-1'}
                />
            );
        };

        render(<CounterParent />);
        await act(async () => {
            await new Promise((r) => setTimeout(r, 250));
        });

        expect(renders).toBeLessThan(40);
        void hubRenderCount;
    });
});

