                }
            }
            const normalizedItems = normalizeSpecificDeliveryItemsForSave(specificDeliveryItems);
            if (normalizedItems.length === 0) {
                SmartToast.error(
                    '⚠️ أضف شيئاً واحداً على الأقل وحدّد نوعه (منقول أو غير منقول)',
