                                                <label className={`${ecg.radioRow} ${dowryReason === 'طلاق' ? ecg.radioRowActive : ecg.radioRowIdle} flex-1`}>
                                                    <input
                                                        type="radio"
                                                        name="dowryReason"
                                                        value="طلاق"
                                                        checked={dowryReason === 'طلاق'}
                                                        onChange={(e) => setDowryReason(e.target.value as 'طلاق' | 'وفاة')}
                                                        className="accent-[#E6C673]"
                                                    />
                                                    <span className="text-white text-sm">الطلاق</span>
                                                </label>
                                                <label className={`${ecg.radioRow} ${dowryReason === 'وفاة' ? ecg.radioRowActive : ecg.radioRowIdle} flex-1`}>
                                                    <input
                                                        type="radio"
                                                        name="dowryReason"
                                                        value="وفاة"
                                                        checked={dowryReason === 'وفاة'}
                                                        onChange={(e) => setDowryReason(e.target.value as 'طلاق' | 'وفاة')}
                                                        className="accent-[#E6C673]"
                                                    />
                                                    <span className="text-white text-sm">الوفاة</span>
                                                </label>
                                            </div>
                                        </div>
                                    </div>
                                )}

                                {/* VARIANT C: WILL & TAKHARUJ DEEDS - PHASE 42 */}
                                {docType === 'الحجج الشرعية' && (claimType === 'حجة وصية' || claimType === 'حجة تخارج') && (
                                    <div className={ecg.subCard}>
                                        <label className={ecg.labelGold}>
                                            تفاصيل الحجة (مثال: اسم الموصى له، أو تفاصيل حصص التخارج)
                                        </label>
                                        <textarea
                                            value={guardianshipDetails}
                                            onChange={(e) => setGuardianshipDetails(e.target.value)}
                                            className={ecg.textarea}
                                            rows={4}
                                            placeholder={claimType === 'حجة وصية' 
                                                ? "مثال: الموصى له: محمد علي، الحصة الموصى بها: ربع التركة..."
                                                : "مثال: تفاصيل حصص الورثة المتخارجين والمبالغ المتفق عليها..."
                                            }
                                        />
                                    </div>
                                )}

                                {docType === 'تنفيذ الأحكام الأجنبية' && (
                                    <ForeignJudgmentSection
                                        foreignData={foreignData}
                                        onForeignDataChange={setForeignData}
                                    />
                                )}
                            </div>
                        </ExecutionCreationSection>
                        ) : null}

                        {showLawyerFeesBetweenSections ? (
                            <LawyerFeesToggleCard
                                includeLawyerFees={includeLawyerFees}
                                onIncludeLawyerFeesChange={setIncludeLawyerFees}
                                lawyerFeesAmount={lawyerFeesAmount}
                                formatCurrency={formatCurrency}
                                handleAmountChange={handleAmountChange}
                                onLawyerFeesAmountChange={setLawyerFeesAmount}
                            />
                        ) : null}

                        {showPartiesSection ? (
                        <PartiesSection
                            creditors={creditors}
                            additionalCreditors={additionalCreditors}
                            debtors={debtors}
                            additionalDebtorsForm={additionalDebtorsForm}
                            allowMultipleDebtors={allowMultipleDebtors}
                            showDebtorSolidarySplit={showDebtorSolidarySplit}
                            classification={classification}
                            claimType={claimType}
                            effectiveClaimTypes={effectiveClaimTypes}
                            globalClaimTotal={globalClaimTotalForSplit}
                            includeLawyerFees={includeLawyerFees}
                            lockedEntityKind={lockedDebtorEntityKind}
                            debtorManualDebtClaims={debtorManualDebtClaims}
                            debtorLawyerFeesClaims={debtorLawyerFeesClaims}
                            formatCurrency={formatCurrency}
                            onDebtorManualDebtChange={handleDebtorManualDebtChange}
                            onDebtorLawyerFeesChange={handleDebtorLawyerFeesChange}
                            onAddCreditor={addCreditor}
                            onRemoveAdditionalCreditor={removeAdditionalCreditor}
                            onUpdateAdditionalCreditor={updateAdditionalCreditor}
                            onUpdateCreditor={updateCreditor}
                            onAddIndependentDebtor={addIndependentDebtor}
                            onAddSolidaryDebtor={addSolidaryDebtor}
                            onAddAnotherDebtor={addAnotherDebtor}
                            onRemoveAdditionalDebtor={removeAdditionalDebtor}
                            onUpdateAdditionalDebtor={updateAdditionalDebtor}
                            onUpdateDebtor={updateDebtor}
                        />
                        ) : null}

                        {/* ✅ DELETED: دليل التنفيذ القانوني - All tracking, calculations, and legal warnings belong exclusively to the Active Dashboard, NOT the creation form */}

                        {/* ✅ DELETED: متتبع المواعيد القانونية - Statute of Limitations & Notification Tracker belong to Dashboard */}

                        {claimType && ['مشاهدة', 'تسليم ولد'].includes(claimType) && (
                            <ExecutionCreationSection title="تفاصيل إضافية للمطالبة الشرعية">
                                {claimType === 'مشاهدة' && (
                                    <div className={`${ecg.subCard} space-y-4`}>
                                        <p className={`${ecg.subCardTitle} text-[#E6C673]`}>
                                            أسماء الأولاد (مشاهدة واستصحاب)
                                        </p>
                                        {visitationChildrenNames.map((childName, idx) => (
                                            <div key={idx} className="flex gap-2 items-center flex-row-reverse">
                                                <input
                                                    type="text"
                                                    value={childName}
                                                    onChange={(e) => {
                                                        const v = e.target.value;
                                                        setVisitationChildrenNames((prev) =>
                                                            prev.map((n, i) => (i === idx ? v : n))
                                                        );
                                                    }}
                                                    className={`${ecg.field} flex-1 text-sm`}
                                                />
                                                {visitationChildrenNames.length > 1 && (
                                                    <button
                                                        type="button"
                                                        onClick={() =>
                                                            setVisitationChildrenNames((prev) =>
                                                                prev.filter((_, i) => i !== idx)
                                                            )
                                                        }
                                                        className="p-2 text-rose-400 hover:bg-rose-500/10 rounded-lg transition-colors shrink-0"
                                                        title="حذف السطر"
                                                    >
                                                        <Trash2 size={16} />
                                                    </button>
                                                )}
                                            </div>
                                        ))}
                                        <button
                                            type="button"
                                            onClick={() => setVisitationChildrenNames((prev) => [...prev, ''])}
                                            className={`${ecg.addBtn} !mt-0`}
                                        >
                                            <Plus size={14} />
                                            إضافة اسم
                                        </button>
                                    </div>
                                )}

                                {claimType === 'مشاهدة' && (
                                    <VisitationScheduleSetupSection
                                        draft={visitationScheduleDraft}
                                        onChange={setVisitationScheduleDraft}
                                    />
                                )}

                                {claimType === 'تسليم ولد' && (
                                    <div className={`${ecg.subCard} space-y-3`}>
                                        <p className={ecg.subCardTitle}>أسماء المحضونين (نزع حضانة)</p>
                                        {custodyWardNames.map((wardName, idx) => (
                                            <div key={idx} className="flex gap-2 items-center flex-row-reverse">
                                                <input
                                                    type="text"
                                                    value={wardName}
                                                    onChange={(e) => {
                                                        const v = e.target.value;
                                                        setCustodyWardNames((prev) =>
                                                            prev.map((n, i) => (i === idx ? v : n))
                                                        );
                                                    }}
                                                    placeholder={`اسم المحضون ${idx + 1}`}
                                                    className={`${ecg.field} flex-1 text-sm`}
                                                />
                                                {custodyWardNames.length > 1 && (
                                                    <button
                                                        type="button"
                                                        onClick={() =>
                                                            setCustodyWardNames((prev) =>
                                                                prev.filter((_, i) => i !== idx)
                                                            )
                                                        }
                                                        className="p-2 text-rose-400 hover:bg-rose-500/10 rounded-lg transition-colors shrink-0"
                                                        title="حذف السطر"
                                                    >
                                                        <Trash2 size={16} />
                                                    </button>
                                                )}
                                            </div>
                                        ))}
                                        <button
                                            type="button"
                                            onClick={() => setCustodyWardNames((prev) => [...prev, ''])}
                                            className={`${ecg.addBtn} !mt-0`}
                                        >
                                            <Plus size={14} />
                                            إضافة محضون
                                        </button>
                                    </div>
                                )}
                            </ExecutionCreationSection>
                        )}

                        {/* ✅ DELETED: الملخص المالي الذكي - Auto-calculated financial summary belongs to Dashboard */}

                        <div className="h-6"></div> {/* Spacer */}
                    </div>
                </div>

                <ExecutionSaveButton onSubmit={handleSubmit} />

                <ExecutionOptionSheet
                    open={docTypeSheetOpen}
                    onClose={() => setDocTypeSheetOpen(false)}
                    title="نوع السند المنفذ"
                    options={EXECUTION_DOC_TYPE_OPTIONS}
                    comingSoonOptions={EXECUTION_DOC_TYPE_COMING_SOON}
                    selectedValue={docType}
                    onSelect={(v) => handleDocTypeChange(v)}
                />
                <ExecutionOptionSheet
                    open={claimTypeSheetOpen}
                    onClose={() => setClaimTypeSheetOpen(false)}
                    title="نوع المطالبة والتنفيذ"
                    options={shariaExclusiveClaimOptions}
                    selectedValue={claimType}
                    exclusiveSectionTitle={
                        showShariaLinkedClaimPanel ? 'مطالبات منفردة' : undefined
                    }
                    onSelect={(v) => {
                        setActiveClaimTypes([v]);
                        setClaimAmountsByType({});
                        setLinkedClaimDraft([]);
                        setClaimTypeSheetOpen(false);
                    }}
                    multiSelectPanel={
                        showShariaLinkedClaimPanel
                            ? {
                                  sectionTitle: 'مطالبات مالية',
                                  options: shariaLinkedClaimOptions,
                                  draftValues: linkedClaimDraft,
                                  onToggleDraft: toggleLinkedClaimDraft,
                                  onConfirm: saveLinkedClaimDraft,
                                  confirmLabel: 'حفظ الاختيار',
                              }
                            : undefined
                    }
                />

                {/* ✅ PRACTICAL CHEQUE VALIDATOR - DATA CAPTURE MODAL */}
                {showChequeValidatorModal && (
                    <div className={ecg.modalBackdrop} onClick={() => {
                        if (!chequeBankName && !chequeIssueDate && !chequeNumber) {
                            setShowChequeValidatorModal(false);
                        }
                    }}
                    >
                        <div className={ecg.modalPanel} onClick={(e) => e.stopPropagation()}>
                            <h3 className={ecg.modalTitle}>
                                <AlertTriangle size={24} />
                                بيانات الورقة التجارية (صك/كمبيالة)
                            </h3>
                            <p className="text-slate-400 text-sm mb-4">
                                📋 هذه البيانات ستُستخدم في طلب التنفيذ ومخاطبة المصرف
                            </p>

                            <div className="space-y-4 mb-6">
                                {/* Bank Name */}
                                <div>
                                    <label className={ecg.labelGold}>اسم المصرف المسحوب عليه *</label>
                                    <input
                                        type="text"
                                        value={chequeBankName}
                                        onChange={(e) => setChequeBankName(e.target.value)}
                                        placeholder="مثال: مصرف الرافدين، المصرف الأهلي العراقي..."
                                        className={ecg.field}
                                    />
                                </div>
                                <div>
                                    <label className={ecg.labelGold}>رقم الصك / الكمبيالة *</label>
                                    <input
                                        type="text"
                                        value={chequeNumber}
                                        onChange={(e) => setChequeNumber(e.target.value)}
                                        placeholder="مثال: 12345678"
                                        className={ecg.field}
                                    />
                                </div>
                                <div>
                                    <label className={`${ecg.labelGold} flex items-center gap-2 flex-wrap`}>
                                        <Calendar size={16} />
                                        تاريخ إنشاء الصك
                                        <span className="text-slate-500 text-xs font-normal">(اختياري لكن مهم قانونياً)</span>
                                    </label>
                                    <input
                                        type="date"
                                        value={chequeIssueDate}
                                        onChange={(e) => setChequeIssueDate(e.target.value)}
                                        className={ecg.field}
                                    />
                                    {!chequeIssueDate && (
                                        <p className="text-rose-400 text-xs mt-2 flex items-center gap-1">
                                            <AlertTriangle size={12} />
                                            ⚠️ تحذير: الصك بدون تاريخ قد يفقد قوته التنفيذية ويتحول لسند عادي
                                        </p>
                                    )}
                                </div>
                            </div>

                            <div className="flex gap-3">
                                <button type="button"
                                    onClick={() => {
                                        // Validation Rule: If no issue date, downgrade document power
                                        if (!chequeIssueDate) {
                                            setDocType('السندات المتضمنة إقراراً بدين');
                                            setClaimType('استحصال دين مالي');
                                            SmartToast.warning('⚠️ تنبيه قانوني: لعدم وجود تاريخ إنشاء، تحول الصك إلى سند عادي. يجب إثبات الدين وفق شروط مشددة.');
                                        }
                                        setShowChequeValidatorModal(false);
                                    }}
                                    disabled={!chequeBankName || !chequeNumber}
                                    className={ecg.modalBtnPrimary}
                                >
                                    {chequeIssueDate ? 'تأكيد البيانات' : 'متابعة كسند عادي'}
                                </button>
                                <button type="button"
                                    onClick={() => {
                                        setShowChequeValidatorModal(false);
                                        setDocType('');
                                        setClaimType('');
                                    }}
                                    className={ecg.modalBtnGhost}
                                >
                                    إلغاء
                                </button>
                            </div>
                        </div>
                    </div>
                )}

                {/* 🛑 ABSENTEE CHECKLIST MODAL */}
                {showAbsenteeModal && (
                    <div className={ecg.modalBackdrop} onClick={() => setShowAbsenteeModal(false)}>
                        <div className={ecg.modalPanelDanger} onClick={(e) => e.stopPropagation()}>
                            <h3 className={`${ecg.calloutDangerTitle} mb-4`}>
                                <AlertTriangle size={24} />
                                فحص الغياب الإلزامي
                            </h3>
                            <p className="text-slate-400 text-sm mb-4">
                                يرجى الإجابة على الأسئلة التالية:
                            </p>
                            <div className="space-y-3 mb-6">
                                {[
                                    { key: 'isOutsideIraq', label: 'هل المدين متواجد خارج العراق؟' },
                                    { key: 'isAddressUnknown', label: 'هل محل إقامة المدين مجهول؟' },
                                    { key: 'isDiedDuringNotice', label: 'هل توفي المدين خلال فترة الإخبار؟' }
                                ].map(item => (
                                    <label key={item.key} className={ecg.optionRow}>
                                        <span className="text-white text-sm flex-1">{item.label}</span>
                                        <div className="flex gap-2">
                                            <label className="flex items-center gap-1 cursor-pointer">
                                                <input 
                                                    type="radio"
                                                    name={item.key}
                                                    checked={absenteeChecks[item.key as keyof typeof absenteeChecks] === true}
                                                    onChange={() => setAbsenteeChecks({...absenteeChecks, [item.key]: true})}
                                                    className="accent-rose-500"
                                                />
                                                <span className="text-xs text-gray-400">نعم</span>
                                            </label>
                                            <label className="flex items-center gap-1 cursor-pointer">
                                                <input 
                                                    type="radio"
                                                    name={item.key}
                                                    checked={absenteeChecks[item.key as keyof typeof absenteeChecks] === false}
                                                    onChange={() => setAbsenteeChecks({...absenteeChecks, [item.key]: false})}
                                                    className="accent-emerald-500"
                                                />
                                                <span className="text-xs text-gray-400">لا</span>
                                            </label>
                                        </div>
                                    </label>
                                ))}
                            </div>
                            <button type="button"
                                onClick={() => {
                                    const hasAnyYes = Object.values(absenteeChecks).some(v => v === true);
                                    if (hasAnyYes) {
                                        setIsDocumentBlocked(true);
                                        SmartToast.error('🛑 توقف: استناداً للفقرة رابعاً من المادة 14، فقدَ هذا السند قوته التنفيذية المباشرة.');
                                    } else {
                                        setIsDocumentBlocked(false);
                                    }
                                    setShowAbsenteeModal(false);
                                }}
                                className="w-full bg-rose-500 hover:bg-rose-600 text-white font-bold py-3 rounded-lg transition-all"
                            >
                                تأكيد
                            </button>
                        </div>
                    </div>
                )}
        </>
    );

    if (reduceMotion) {
        return (
            <div dir="rtl" className={ecg.modalShell}>
                {shellContent}
            </div>
        );
    }

    return (
        <motion.div initial={false} animate={{ opacity: 1 }} dir="rtl" className={ecg.modalShell}>
            {shellContent}
        </motion.div>
    );
};

import React from 'react';
import { Plus, UserPlus, Users } from 'lucide-react';
import PartyCard, { type PartyCardProps } from './PartyCard';
import { ecg } from './executionCreationGlassUi';
import { ExecutionCreationSection } from './ExecutionCreationSection';
import {
    shouldShowIndependentDebtorSharePanels,
    isPersonalStatusClassification,
} from '../hooks/executionFormUtils';
import { IndependentDebtorSharePanel } from './IndependentDebtorSharePanel';
import { handleMoneyInputChange } from '@/app/utils/moneyInput';

interface CreditorData {
    id: number;
    name: string;
    phone: string;
    address: string;
    occupation: 'موظف' | 'كاسب';
    isClient: boolean;
}

interface DebtorData {
    id: number;
    name: string;
    phone: string;
    address: string;
    occupation: 'موظف' | 'كاسب';
    isClient: boolean;
    isSolidaryLiability?: boolean;
}

interface AdditionalCreditor {
    id: string;
    name: string;
    phone: string;
    address: string;
    occupation: 'موظف' | 'كاسب';
    isClient: boolean;
}

interface AdditionalDebtor {
    id: string;
    name: string;
    phone: string;
    address: string;
    occupation: 'موظف' | 'كاسب';
    isClient: boolean;
    isSolidaryLiability?: boolean;
}

interface PartiesSectionProps {
    creditors: CreditorData[];
    additionalCreditors: AdditionalCreditor[];
    debtors: DebtorData[];
    additionalDebtorsForm: AdditionalDebtor[];
    allowMultipleDebtors: boolean;
    showDebtorSolidarySplit: boolean;
    classification: string;
    claimType: string;
    effectiveClaimTypes: string[];
    globalClaimTotal: number;
    includeLawyerFees: boolean;
    lockedEntityKind: 'natural_person' | 'legal_entity' | null;
    debtorManualDebtClaims: Record<string, string>;
    debtorLawyerFeesClaims: Record<string, string>;
    formatCurrency: (value: string) => string;
    onDebtorManualDebtChange: (debtorKey: string, raw: string) => void;
    onDebtorLawyerFeesChange: (debtorKey: string, raw: string) => void;
    onAddCreditor: () => void;
    onRemoveAdditionalCreditor: (id: string) => void;
    onUpdateAdditionalCreditor: (id: string, field: string, value: string | boolean | number) => void;
    onUpdateCreditor: (id: number, field: string, value: string | boolean | number) => void;
    onAddIndependentDebtor: () => void;
    onAddSolidaryDebtor: () => void;
    onAddAnotherDebtor: () => void;
    onRemoveAdditionalDebtor: (id: string) => void;
    onUpdateAdditionalDebtor: (id: string, field: string, value: string | boolean | number) => void;
    onUpdateDebtor: (id: number, field: string, value: string | boolean | number) => void;
}

export const PartiesSection: React.FC<PartiesSectionProps> = React.memo(({
    creditors,
    additionalCreditors,
    debtors,
    additionalDebtorsForm,
    allowMultipleDebtors,
    showDebtorSolidarySplit,
    classification,
    claimType,
    effectiveClaimTypes,
    globalClaimTotal,
    includeLawyerFees,
    lockedEntityKind,
    debtorManualDebtClaims,
    debtorLawyerFeesClaims,
    formatCurrency,
    onDebtorManualDebtChange,
    onDebtorLawyerFeesChange,
    onAddCreditor,
    onRemoveAdditionalCreditor,
    onUpdateAdditionalCreditor,
    onUpdateCreditor,
    onAddIndependentDebtor,
    onAddSolidaryDebtor,
    onAddAnotherDebtor,
    onRemoveAdditionalDebtor,
    onUpdateAdditionalDebtor,
    onUpdateDebtor,
}) => {
    const totalCreditorCount = creditors.length + additionalCreditors.length;
    const totalDebtorCount = debtors.length + additionalDebtorsForm.length;
    const showIndependentDebtorSharePanels = shouldShowIndependentDebtorSharePanels(
        classification,
        effectiveClaimTypes,
        claimType,
        totalDebtorCount,
        totalCreditorCount,
    );
    const hideDebtorEntityKind = isPersonalStatusClassification(classification);

    /** تسميات ضامن/مستقل فقط عند تعدد المدينين */
    const showDebtorLiabilityLabels = showDebtorSolidarySplit && totalDebtorCount > 1;

    const renderIndependentDebtPanel = (debtorKey: string, isSolidary: boolean) => {
        if (!showIndependentDebtorSharePanels || isSolidary) return null;
        return (
            <div className="px-3 pb-3">
                <IndependentDebtorSharePanel
                    debtDraft={formatCurrency(debtorManualDebtClaims[debtorKey] ?? '')}
                    onDebtInput={(e) => {
                        handleMoneyInputChange(e.target.value, (raw) => {
                            onDebtorManualDebtChange(debtorKey, raw);
                        });
                    }}
                    showLawyerFeesShare={includeLawyerFees}
                    lawyerFeesDraft={formatCurrency(debtorLawyerFeesClaims[debtorKey] ?? '')}
                    onLawyerFeesInput={(e) => {
                        handleMoneyInputChange(e.target.value, (raw) => {
                            onDebtorLawyerFeesChange(debtorKey, raw);
                        });
                    }}
                />
            </div>
        );
    };

    const liabilityLabelFor = (isSolidary: boolean): 'مستقل' | 'ضامن' | null => {
        if (!showDebtorLiabilityLabels) return null;
        return isSolidary ? 'ضامن' : 'مستقل';
    };

    return (
        <ExecutionCreationSection title="أطراف الإضبارة">
            <div className={ecg.partyGroup}>
                <div className="flex flex-col gap-1 p-1">
                    {creditors.map((creditor, index) => (
                        <PartyCard
                            key={creditor.id}
                            party={creditor}
                            index={index}
                            totalCount={totalCreditorCount}
                            type="creditor"
                            onUpdate={onUpdateCreditor as PartyCardProps['onUpdate']}
                            onRemove={() => {}}
                        />
                    ))}
                    {additionalCreditors.map((c, idx) => (
                        <PartyCard
                            key={c.id}
                            party={c}
                            index={creditors.length + idx}
                            totalCount={totalCreditorCount}
                            type="creditor"
                            onUpdate={(id, field, value) =>
                                onUpdateAdditionalCreditor(String(id), field, value)
                            }
                            onRemove={(id) => onRemoveAdditionalCreditor(String(id))}
                        />
                    ))}
                </div>
            </div>

            <button type="button" onClick={onAddCreditor} className={ecg.addBtn}>
                <Plus size={16} /> إضافة دائن آخر
            </button>

            <div className={ecg.partyDivider}>
                <div className={ecg.partyDividerLine} />
            </div>

            <div className={ecg.partyGroup}>
                <div className="flex flex-col gap-1 p-1">
                    {debtors.map((debtor, index) => {
                        const debtorKey = String(debtor.id);
                        const isSolidary = Boolean(debtor.isSolidaryLiability);
                        return (
                            <div key={debtor.id} className="border-b border-white/5 last:border-b-0">
                                <PartyCard
                                    party={debtor}
                                    index={index}
                                    totalCount={totalDebtorCount}
                                    type="debtor"
                                    debtorLiabilityLabel={liabilityLabelFor(isSolidary)}
                                    lockedEntityKind={lockedEntityKind}
                                    hideDebtorEntityKind={hideDebtorEntityKind}
                                    onUpdate={onUpdateDebtor as PartyCardProps['onUpdate']}
                                    onRemove={() => {}}
                                />
                                {renderIndependentDebtPanel(debtorKey, isSolidary)}
                            </div>
                        );
                    })}
                    {additionalDebtorsForm.map((d, idx) => {
                        const isSolidary = Boolean(d.isSolidaryLiability);
                        return (
                            <div key={d.id} className="border-b border-white/5 last:border-b-0">
                                <PartyCard
                                    party={d}
                                    index={debtors.length + idx}
                                    totalCount={totalDebtorCount}
                                    type="debtor"
