            </div>
            <input
                type="text"
                placeholder={isCreditor ? 'العنوان (اختياري)' : 'العنوان الدقيق (مطلوب للتبليغ)'}
                value={draft.address}
                onChange={(e) => setDraft((d) => ({ ...d, address: e.target.value }))}
                onBlur={() => onUpdate(party.id, 'address', draft.address)}
                className={ecg.field}
            />
        </div>
    );
});

