                saveBreakInventoryLedger={saveBreakInventoryLedger}
                finalizeBreakInventoryRequest={finalizeBreakInventoryRequest}
                isMaritalFurnitureClaim={isMaritalFurnitureClaim}
                maritalFurnitureItems={maritalFurnitureItems}
                saveMaritalFurnitureDeliveryInventory={saveMaritalFurnitureDeliveryInventory}
                persistExecutionMerge={persistExecutionMerge}
                pushTimelineEvent={pushTimelineEvent}
                nextTimelineId={nextTimelineId}
                onOpenDecisionsModal={onOpenDecisionsModal}
                expandProcedureKey={expandProcedureKey}
                onExpandProcedureConsumed={onExpandProcedureConsumed}
            />
            ) : null}
            </div>
        )}

        {typeof saveCoerciveAction === 'function' &&
        typeof pushTimelineEvent === 'function' &&
        typeof nextTimelineId === 'function' ? (
            <CoerciveSeizureToolsSection
                isEvictionExecutionModule={isEvictionExecutionModule}
                activeDebtorIsEmployee={activeDebtorIsEmployee}
                activeDebtorIsDeceased={activeDebtorIsDeceased}
                executionCoerciveButtonDisabled={executionCoerciveButtonDisabled}
                coerciveUiLocked={coerciveUiLocked}
                isHistoricalMode={isHistoricalMode}
                executionId={decisionsStorageExecutionId}
                executionData={(executionData as ExecutionFile | null | undefined) ?? null}
                followupSalarySeizureLabel={followupSalarySeizureLabel}
                followupEmployeeFinancialSalaryOnlyCoercive={followupEmployeeFinancialSalaryOnlyCoercive}
                followupMonetaryCoerciveLimitedOnly={followupMonetaryCoerciveLimitedOnly}
                hideCoerciveSeizureSalaryAndProperty={
                    hideCoerciveSeizureSalaryAndProperty || hideFollowupCoerciveTab
                }
                inlineActionGateKey={inlineActionGateKey}
                setInlineActionGateKey={setInlineActionGateKey}
                saveCoerciveAction={saveCoerciveAction}
                pushTimelineEvent={pushTimelineEvent}
                nextTimelineId={nextTimelineId}
                showToast={showToast as CoerciveSeizureToolsSectionProps['showToast']}
            />
        ) : null}
    </>
);

import React from 'react';
import { CheckCircle, Wallet } from 'lucide-react';
import { InlineActionGate } from './InlineActionGate';
import type { InlineActionGateKey } from '../types';

export interface CoerciveToolsGridProps {
    isEvictionExecutionModule: boolean;
    activeDebtorIsEmployee: boolean;
    executionCoerciveButtonDisabled: boolean;
    activeCoerciveActions: string[];
    inlineActionGateKey: InlineActionGateKey | null;
    followupSalarySeizureLabel: string;
    followupGarnishmentAmountPreview: string | number | null | undefined;
    followupEmployeeFinancialSalaryOnlyCoercive: boolean;
    followupMonetaryCoerciveLimitedOnly: boolean;
    hideCoerciveSeizureSalaryAndProperty?: boolean;
    setInlineActionGateKey: (key: InlineActionGateKey | null) => void;
    handleCoerciveAction: (type: string) => void;
}

export const CoerciveToolsGrid: React.FC<CoerciveToolsGridProps> = ({
    isEvictionExecutionModule,
    activeDebtorIsEmployee,
    executionCoerciveButtonDisabled,
    activeCoerciveActions,
    inlineActionGateKey,
    followupSalarySeizureLabel,
    followupGarnishmentAmountPreview,
    followupEmployeeFinancialSalaryOnlyCoercive,
    followupMonetaryCoerciveLimitedOnly,
    hideCoerciveSeizureSalaryAndProperty = false,
    setInlineActionGateKey,
    handleCoerciveAction,
}) => {
    if (isEvictionExecutionModule) return null;

    const showSalaryButton = activeDebtorIsEmployee && !hideCoerciveSeizureSalaryAndProperty;

    if (!showSalaryButton) return null;

    return (
        <>
            <div className="grid grid-cols-2 gap-3">
                {showSalaryButton && (
                    <div className="relative">
                        <button
                            type="button"
                            onClick={() => {
                                if (executionCoerciveButtonDisabled) return;
                                setInlineActionGateKey('seizure_salary');
                            }}
                            disabled={executionCoerciveButtonDisabled}
                            className={`w-full backdrop-blur-xl rounded-2xl p-4 transition-all ${
                                executionCoerciveButtonDisabled
                                    ? 'bg-slate-900/40 opacity-50 cursor-not-allowed'
                                    : 'bg-slate-800/60 hover:bg-slate-700/60'
                            }`}
                        >
                            {activeCoerciveActions.includes('salary') && (
                                <CheckCircle size={14} className="absolute top-2 right-2 text-emerald-400" />
                            )}
                            <div className="w-12 h-12 flex items-center justify-center rounded-2xl bg-white/5 mx-auto mb-2">
                                <Wallet className="w-6 h-6 text-white/70" />
                            </div>
                            <p className={`font-semibold text-xs text-center ${executionCoerciveButtonDisabled ? 'text-gray-600' : 'text-white'}`}>
                                {followupSalarySeizureLabel}
                            </p>
                            {(() => {
                                if (executionCoerciveButtonDisabled) return null;
                                const n = Number(followupGarnishmentAmountPreview);
                                if (!Number.isFinite(n) || n <= 0) return null;
                                return (
                                    <p className="text-amber-400 text-[10px] font-bold text-center mt-1" dir="ltr">
                                        {Math.trunc(n).toLocaleString('ar-IQ')} د.ع/شهرياً
                                    </p>
                                );
                            })()}
                        </button>
                        <InlineActionGate
                            gateKey="seizure_salary"
                            activeKey={inlineActionGateKey}
                            onConfirm={() => handleCoerciveAction('salary')}
                            onCancel={() => setInlineActionGateKey(null)}
                        />
                    </div>
                )}
            </div>
        </>
    );
};

import React from 'react';
import { getLocalTodayYmd } from '@/app/utils/executionStateMachine';
import { patchExecutorDecisionRow } from '@/app/utils/executorSeizureDecisionQueue';
import {
    buildCommunicationDisplayContext,
    buildNoResponseConfirmationDetails,
} from './communicationDecisionModel';
import { CommunicationContextPanel } from './CommunicationContextPanel';

export function CommunicationAwaitingResultCard({
    decision,
    decisionRows,
    exId,
    saving,
    setSaving,
    awaitingUiById,
    setAwaitingUiById,
    resultDraftById,
    setResultDraftById,
    showToast,
    pushTimelineEvent,
    nextTimelineId,
    saveCommunicationResult,
}: {
    decision: any;
    decisionRows: Record<string, unknown>[];
    exId: string;
    saving: boolean;
    setSaving: (v: boolean) => void;
    awaitingUiById: Record<
        string,
        { confirmingNoResponse?: boolean; responseFormOpen?: boolean; confirmLetterDate?: string }
    >;
    setAwaitingUiById: React.Dispatch<
        React.SetStateAction<
            Record<
                string,
                {
                    confirmingNoResponse?: boolean;
                    responseFormOpen?: boolean;
                    confirmLetterDate?: string;
                }
            >
        >
    >;
    resultDraftById: Record<string, { purpose: string; letterNum: string; letterDate: string; result: string }>;
    setResultDraftById: React.Dispatch<
        React.SetStateAction<
            Record<string, { purpose: string; letterNum: string; letterDate: string; result: string }>
        >
    >;
    showToast: (message: string, type: 'success' | 'error' | 'warning' | 'info') => void;
    pushTimelineEvent: (event: any) => void;
    nextTimelineId: () => string;
    saveCommunicationResult: (
        decisionId: string,
        directorate: string,
        draft: { purpose: string; letterNum: string; letterDate: string; result: string },
    ) => void;
}) {
    const decisionId = String(decision?.id || '').trim();
    const ctx = buildCommunicationDisplayContext(decision, decisionRows);
    const ui = awaitingUiById[decisionId] || {};
    const draft =
        resultDraftById[decisionId] || {
            purpose: ctx.directorate,
            letterNum: '',
            letterDate: '',
            result: '',
        };
    const showActionButtons = !ui.confirmingNoResponse;
    const confirmLetterDate = String(ui.confirmLetterDate || getLocalTodayYmd()).trim();

    const dismissFollowup = () => {
        if (!exId || !decisionId || saving) return;
        setSaving(true);
        try {
            patchExecutorDecisionRow(exId, decisionId, {
                deputationFollowupDismissed: true,
                deputationClosed: true,
                deputationResultDetails: 'تم تجاهل متابعة نتيجة المخاطبة.',
            } as any);
            setAwaitingUiById((prev) => {
                const next = { ...prev };
                delete next[decisionId];
                return next;
            });
            showToast('تم تجاهل متابعة النتيجة', 'info');
        } catch {
            showToast('تعذّر التجاهل', 'error');
        }
        setSaving(false);
    };

    const confirmNoResponse = () => {
        if (!exId || !decisionId || saving) return;
        if (!confirmLetterDate || !/^\d{4}-\d{2}-\d{2}$/.test(confirmLetterDate)) {
            showToast('يرجى إدخال تاريخ كتاب التأكيد', 'warning');
            return;
        }
        setSaving(true);
        try {
            const details = buildNoResponseConfirmationDetails({
                previousLetterDate: ctx.requestDate,
                confirmationDate: confirmLetterDate,
            });
            patchExecutorDecisionRow(exId, decisionId, {
                deputationNoResponseConfirmed: true,
                deputationClosed: true,
                deputationResultDetails: details,
                deputationReferralDate: confirmLetterDate,
            } as any);
            const now = new Date().toISOString();
            pushTimelineEvent({
                id: nextTimelineId(),
                type: 'communication',
                title: `تأكيد — عدم ورود إجابة — ${ctx.directorate}`,
                description: details,
                date: confirmLetterDate,
                timestamp: now,
                source: 'محضر المتابعة',
                metadata: { timelineThreadKey: `executor_decision:${decisionId}` },
            });
            setAwaitingUiById((prev) => {
                const next = { ...prev };
                delete next[decisionId];
                return next;
            });
            showToast('تم تسجيل عدم ورود الإجابة', 'success');
        } catch {
            showToast('تعذّر التسجيل', 'error');
        }
        setSaving(false);
    };

    return (
        <div
            key={decisionId}
            className="rounded-2xl border border-white/10 bg-black/15 px-3 py-3 text-right space-y-3"
        >
            <div className="space-y-1">
                <p className="text-[12px] font-black text-slate-50">{ctx.directorate}</p>
                <p className="text-[10px] text-slate-500">مخاطبة بانتظار النتيجة</p>
            </div>

            {<CommunicationContextPanel ctx={ctx} compact />}

            {ui.confirmingNoResponse ? (
                <div className="rounded-xl border border-amber-500/25 bg-amber-950/20 px-3 py-2.5 space-y-2">
                    <p className="text-[11px] font-bold text-amber-100">
                        تأكيد عدم ورود إجابة من «{ctx.directorate}»؟
                    </p>
                    <p className="text-[10px] leading-relaxed text-amber-100/80">
                        {ctx.requestDate
                            ? `سيُسجَّل تأكيد على الكتاب السابق المؤرّخ في ${ctx.requestDate} كمخاطبة مستقلة.`
                            : 'سيُسجَّل تأكيد على الكتاب السابق كمخاطبة مستقلة.'}
                    </p>
                    <div>
                        <label className="mb-1 block text-[9px] text-amber-200/70">
                            تاريخ كتاب التأكيد *
                        </label>
                        <input
                            type="date"
                            value={confirmLetterDate}
                            max={getLocalTodayYmd()}
                            onChange={(e) =>
                                setAwaitingUiById((prev) => ({
                                    ...prev,
                                    [decisionId]: {
                                        ...prev[decisionId],
                                        confirmingNoResponse: true,
                                        confirmLetterDate: e.target.value,
                                    },
                                }))
                            }
                            dir="rtl"
                            className="w-full rounded-xl border border-amber-500/25 bg-black/30 px-3 py-2 text-[11px] text-amber-50 focus:outline-none focus:border-amber-500/50 [&::-webkit-calendar-picker-indicator]:invert"
                        />
                    </div>
                    <div className="flex flex-row-reverse flex-wrap gap-2">
                        <button
                            type="button"
                            disabled={saving}
                            onClick={confirmNoResponse}
                            className="rounded-xl border border-amber-500/40 bg-amber-600/20 px-3 py-2 text-[11px] font-black text-amber-100 disabled:opacity-40"
                        >
                            تأكيد
                        </button>
                        <button
                            type="button"
                            disabled={saving}
                            onClick={() =>
                                setAwaitingUiById((prev) => ({
                                    ...prev,
                                    [decisionId]: {
                                        ...prev[decisionId],
                                        confirmingNoResponse: false,
                                    },
                                }))
                            }
                            className="rounded-xl bg-slate-800 px-3 py-2 text-[11px] font-bold text-slate-100 disabled:opacity-40"
                        >
                            إلغاء
                        </button>
                    </div>
                </div>
            ) : showActionButtons ? (
                <div className="flex flex-row-reverse flex-wrap gap-2">
                    <button
                        type="button"
                        disabled={saving}
                        onClick={() =>
                            setAwaitingUiById((prev) => ({
                                ...prev,
                                [decisionId]: {
                                    ...prev[decisionId],
                                    confirmingNoResponse: true,
                                    responseFormOpen: false,
                                    confirmLetterDate:
                                        prev[decisionId]?.confirmLetterDate || getLocalTodayYmd(),
                                },
                            }))
                        }
                        className="rounded-xl border border-amber-500/35 bg-amber-500/10 px-3 py-2 text-[10px] font-bold text-amber-100 hover:bg-amber-500/15 disabled:opacity-40"
                    >
                        عدم ورود الإجابة
                    </button>
                    <button
                        type="button"
                        disabled={saving}
                        onClick={() =>
                            setAwaitingUiById((prev) => ({
                                ...prev,
                                [decisionId]: {
                                    ...prev[decisionId],
                                    responseFormOpen: !prev[decisionId]?.responseFormOpen,
                                    confirmingNoResponse: false,
                                },
                            }))
                        }
                        className="rounded-xl border border-emerald-500/35 bg-emerald-500/10 px-3 py-2 text-[10px] font-bold text-emerald-100 hover:bg-emerald-500/15 disabled:opacity-40"
                    >
                        تم ورود الإجابة
                    </button>
                    <button
                        type="button"
                        disabled={saving}
                        onClick={dismissFollowup}
                        className="rounded-xl border border-slate-500/35 bg-slate-800/60 px-3 py-2 text-[10px] font-bold text-slate-300 hover:bg-slate-800 disabled:opacity-40"
                    >
                        التجاهل
                    </button>
                </div>
            ) : null}

            {ui.responseFormOpen && showActionButtons ? (
                <div className="space-y-2 border-t border-white/10 pt-2">
                    <div className="grid grid-cols-2 gap-2">
                        <div>
                            <label className="mb-1 block text-[9px] text-slate-500">تاريخ الإجابة</label>
                            <input
                                type="date"
                                value={draft.letterDate}
                                onChange={(e) =>
                                    setResultDraftById((prev) => ({
                                        ...prev,
                                        [decisionId]: { ...draft, letterDate: e.target.value },
                                    }))
                                }
                                className="w-full rounded-xl border border-white/10 bg-white/5 px-3 py-2 text-[11px] text-slate-100"
                            />
                        </div>
                        <div>
                            <label className="mb-1 block text-[9px] text-slate-500">رقم الكتاب</label>
                            <input
                                type="text"
                                value={draft.letterNum}
                                onChange={(e) =>
                                    setResultDraftById((prev) => ({
                                        ...prev,
                                        [decisionId]: { ...draft, letterNum: e.target.value },
                                    }))
                                }
                                className="w-full rounded-xl border border-white/10 bg-white/5 px-3 py-2 text-[11px] text-slate-100 text-right"
                                placeholder="رقم الكتاب"
                            />
                        </div>
                    </div>
                    <div>
                        <label className="mb-1 block text-[9px] text-slate-500">مضمون الإجابة</label>
                        <textarea
                            value={draft.result}
                            onChange={(e) =>
                                setResultDraftById((prev) => ({
                                    ...prev,
                                    [decisionId]: { ...draft, result: e.target.value },
                                }))
                            }
                            rows={3}
                            className="w-full resize-none rounded-xl border border-white/10 bg-white/5 px-3 py-2 text-[11px] text-slate-100 text-right"
                            placeholder="مضمون الإجابة الواردة"
                        />
                    </div>
                    <button
                        type="button"
                        disabled={saving || !String(draft.result || '').trim()}
                        onClick={() => saveCommunicationResult(decisionId, ctx.directorate, draft)}
                        className="w-full rounded-xl bg-emerald-700/70 py-2.5 text-[11px] font-black text-white disabled:opacity-40"
                    >
                        حفظ
                    </button>
                </div>
            ) : null}
        </div>
    );
}

import React from 'react';
import {
    isExecutorRowRejectedAndFinal,
    patchExecutorDecisionRow,
} from '@/app/utils/executorSeizureDecisionQueue';
import { isExecutorRowApprovedWorkflowActive } from '@/app/utils/executorRequestAppealSync';
import {
    ExecutionInlineAccordion,
    ExecutionInlineExecutorDecisionActions,
    type ExecutionInlineStep,
} from '@/app/components/lawyer/ExecutionDashboard/components/ExecutionInlineAccordion';
import {
    COMMUNICATION_KEYWORD,
    buildCommunicationDisplayContext,
    extractDirectorate,
    hasResult,
} from './communicationDecisionModel';
import { CommunicationContextPanel } from './CommunicationContextPanel';

    export function CommunicationExecutorInlineCard({
    decision,
    decisionRows,
    exId,
    saving,
    setSaving,
    resultDraftById,
    setResultDraftById,
    showToast,
    pushTimelineEvent,
    nextTimelineId,
    openAppeals,
}: {
    decision: any;
    decisionRows: Record<string, unknown>[];
    exId: string;
    saving: boolean;
    setSaving: (v: boolean) => void;
    resultDraftById: Record<string, { purpose: string; letterNum: string; letterDate: string; result: string }>;
    setResultDraftById: React.Dispatch<React.SetStateAction<Record<string, { purpose: string; letterNum: string; letterDate: string; result: string }>>>;
    showToast: (message: string, type: 'success' | 'error' | 'warning' | 'info') => void;
    pushTimelineEvent: (event: any) => void;
    nextTimelineId: () => string;
    openAppeals: (decisionId: string) => void;
}) {

        const decisionId = String(decision?.id || '').trim();
        const title = String(decision?.title || '').trim() || COMMUNICATION_KEYWORD;
        const directorate = extractDirectorate(title);
        const rejected = isExecutorRowRejectedAndFinal(decision);
        const approved = isExecutorRowApprovedWorkflowActive(decision, decisionRows);
        const pending = String(decision?.executorOutcome ?? 'pending') === 'pending' || String(decision?.executorOutcome ?? '') === '';
        const hasRes = hasResult(decision);
        const draft =
            resultDraftById[decisionId] || { purpose: directorate, letterNum: '', letterDate: '', result: '' };
        const delivered = decision?.deputationSent === true;
        const canSaveResult =
            approved && !rejected && !hasRes && delivered && Boolean(String(draft.result || '').trim());

        const markDelivered = () => {
            if (!exId || !decisionId || saving) return;
            setSaving(true);
            try {
                patchExecutorDecisionRow(exId, decisionId, { deputationSent: true } as any);
                showToast('تم تسجيل التسليم', 'success');
            } catch {
                showToast('تعذّر تسجيل التسليم', 'error');
            }
            setSaving(false);
        };

        const steps: ExecutionInlineStep[] = [
            {
                id: `${decisionId}:sent`,
                title: 'طلب مخاطبة جهة',
                subtitle: `الجهة: ${directorate}`,
                status: 'done',
                tone: 'success',
            },
            {
                id: `${decisionId}:executor`,
                title: 'قرار المنفذ',
                subtitle: rejected ? 'تم رفض الطلب' : approved ? 'تمت الموافقة' : pending ? 'قيد البت' : '—',
                status: rejected || pending ? 'active' : 'done',
                tone: rejected ? 'danger' : approved ? 'success' : 'neutral',
                content: rejected ? (
                    <ExecutionInlineExecutorDecisionActions
                        executionId={exId}
                        decisionId={decisionId}
                        requestKind={String(decision?.requestKind || 'special_followup')}
                        disabled
                        onOpenAppealCenter={() => openAppeals(decisionId)}
                    />
                ) : pending ? (
                    <ExecutionInlineExecutorDecisionActions
                        executionId={exId}
                        decisionId={decisionId}
                        requestKind={String(decision?.requestKind || 'special_followup')}
                    />
                ) : null,
            },
            {
                id: `${decisionId}:result`,
                title: 'تسجيل نتيجة المخاطبة',
                subtitle: hasRes
                    ? 'تم تسجيل النتيجة'
                    : approved && !rejected && delivered
                      ? 'بانتظار إدخال النتيجة'
                      : approved && !rejected
                        ? 'بانتظار تأكيد التسليم'
                        : 'مقفلة حتى موافقة المنفذ',
                status: hasRes
                    ? 'done'
                    : approved && !rejected && delivered
                      ? 'active'
                      : 'locked',
                tone: hasRes ? 'success' : 'neutral',
                content:
                    approved && !rejected && !hasRes && delivered ? (
                        <div className="space-y-2">
                            <input
                                type="text"
                                value={draft.purpose}
                                onChange={(e) =>
                                    setResultDraftById((prev) => ({
                                        ...prev,
                                        [decisionId]: { ...draft, purpose: e.target.value },
                                    }))
                                }
                                className="w-full rounded-xl border border-white/10 bg-white/5 px-3 py-2 text-[11px] text-slate-100 text-right"
                                placeholder="الجهة المخاطبة"
                            />
                            <div className="grid grid-cols-2 gap-2">
                                <input
                                    type="date"
                                    value={draft.letterDate}
                                    onChange={(e) =>
                                        setResultDraftById((prev) => ({
                                            ...prev,
                                            [decisionId]: { ...draft, letterDate: e.target.value },
                                        }))
                                    }
                                    className="w-full rounded-xl border border-white/10 bg-white/5 px-3 py-2 text-[11px] text-slate-100"
                                />
                                <input
                                    type="text"
                                    value={draft.letterNum}
                                    onChange={(e) =>
                                        setResultDraftById((prev) => ({
                                            ...prev,
                                            [decisionId]: { ...draft, letterNum: e.target.value },
                                        }))
                                    }
                                    className="w-full rounded-xl border border-white/10 bg-white/5 px-3 py-2 text-[11px] text-slate-100 text-right"
                                    placeholder="رقم الكتاب"
                                />
                            </div>
                            <textarea
                                value={draft.result}
                                onChange={(e) =>
                                    setResultDraftById((prev) => ({
                                        ...prev,
                                        [decisionId]: { ...draft, result: e.target.value },
                                    }))
                                }
                                rows={3}
                                className="w-full resize-none rounded-xl border border-white/10 bg-white/5 px-3 py-2 text-[11px] text-slate-100 text-right"
                                placeholder="تفاصيل النتيجة الواردة"
                            />
                            <button
                                type="button"
                                disabled={!canSaveResult || saving}
                                onClick={() => {
                                    if (!canSaveResult || saving) return;
                                    setSaving(true);
                                    const now = new Date().toISOString();
                                    const ref = [
                                        String(draft.letterDate || '').trim(),
                                        String(draft.letterNum || '').trim(),
                                    ]
                                        .filter(Boolean)
                                        .join(' ');
                                    patchExecutorDecisionRow(exId, decisionId, {
                                        deputationTargetDirectorate: String(draft.purpose || '').trim(),
                                        deputationReferralDate: ref || undefined,
                                        deputationResultDetails: String(draft.result || '').trim(),
                                        deputationClosed: true,
                                    } as any);
                                    try {
                                        const ref = [
                                            String(draft.letterDate || '').trim(),
                                            String(draft.letterNum || '').trim(),
                                        ]
                                            .filter(Boolean)
                                            .join(' · ');
                                        pushTimelineEvent({
                                            id: nextTimelineId(),
                                            type: 'communication',
                                            title: `نتيجة مخاطبة — ${directorate}`,
                                            description: [
                                                ref ? `مرجع: ${ref}` : '',
                                                String(draft.result || '').trim(),
                                            ]
                                                .filter(Boolean)
                                                .join('\n'),
                                            date: now.slice(0, 10),
                                            timestamp: now,
                                            source: 'محضر المتابعة',
                                        });
                                    } catch {
                                        /* ignore */
                                    }
                                    setSaving(false);
                                    showToast('✅ تم حفظ النتيجة الواردة', 'success');
                                }}
                                className="w-full rounded-xl bg-emerald-700/70 py-2.5 text-[11px] font-black text-white disabled:opacity-40"
                            >
                                حفظ النتيجة
                            </button>
                        </div>
                    ) : hasRes ? (
                        <CommunicationContextPanel ctx={buildCommunicationDisplayContext(decision, decisionRows)} compact />
                    ) : null,
            } satisfies ExecutionInlineStep,
        ];

        return (
            <div key={decisionId} className="rounded-2xl border border-white/10 bg-black/15 p-3">
                {approved && !rejected && !hasRes ? (
                    <div className="mb-3 flex justify-end">
                        {!delivered ? (
                            <button
                                type="button"
                                disabled={saving}
                                onClick={markDelivered}
                                className="rounded-xl border border-cyan-500/35 bg-cyan-500/10 px-3 py-2 text-[11px] font-extrabold text-cyan-200 hover:bg-cyan-500/15 disabled:opacity-40"
                            >
                                تم التسليم
                            </button>
                        ) : (
                            <span className="rounded-xl border border-emerald-500/30 bg-emerald-500/10 px-3 py-2 text-[11px] font-extrabold text-emerald-200">
                                تمت الإجابة
                            </span>
                        )}
                    </div>
                ) : null}
                <ExecutionInlineAccordion steps={steps} />
            </div>
        );
}

import React, { useMemo, useState } from 'react';
import { Send, CheckCircle, Clock, Plus } from 'lucide-react';
import { getLocalTodayYmd } from '@/app/utils/executionStateMachine';
import {
    isExecutorRowRejectedAndFinal,
    patchExecutorDecisionRow,
} from '@/app/utils/executorSeizureDecisionQueue';
import { isExecutorRowApprovedWorkflowActive } from '@/app/utils/executorRequestAppealSync';
import {
    ExecutionInlineAccordion,
    ExecutionInlineExecutorDecisionActions,
    type ExecutionInlineStep,
} from '@/app/components/lawyer/ExecutionDashboard/components/ExecutionInlineAccordion';
import { LegalEntitySoftProceduresSection } from '@/app/components/lawyer/ExecutionDashboard/components/LegalEntitySoftProceduresSection';
import type { InlineActionGateKey } from '@/app/components/lawyer/ExecutionDashboard/types';
import { useExecutorDecisions } from '@/app/components/lawyer/ExecutionDashboard/hooks/useExecutorDecisions';

export interface CommunicationsTabProps {
    decisionsStorageExecutionId: string;
    showToast: (message: string, type: 'success' | 'error' | 'warning' | 'info') => void;
    pushTimelineEvent: (event: {
        id: string;
        type: string;
        title: string;
        description: string;
        date: string;
        timestamp?: string;
        source?: string;
        metadata?: Record<string, unknown>;
    }) => void;
    nextTimelineId: () => string;
    showSoftFieldProcedures?: boolean;
    showEncroachmentSurveyor?: boolean;
    showSpecificDeliverySurveyor?: boolean;
    inlineActionGateKey?: InlineActionGateKey | null;
    setInlineActionGateKey?: (key: InlineActionGateKey | null) => void;
    onEncroachmentExpenseRecorded?: (
        row: import('@/app/utils/encroachmentRemovalRequests').EncroachmentCaseExpenseRow
    ) => void;
}

const COMMUNICATION_KEYWORD = 'إرسال كتاب / مخاطبة جهة';

function isCommunicationDecision(decision: any): boolean {
    const t = String(decision?.title || '');
    return t.includes(COMMUNICATION_KEYWORD) || /مخاطبة جهة/i.test(t);
}

function hasResult(decision: any): boolean {
    return Boolean(decision?.deputationResultDetails) || decision?.deputationClosed === true;
}

function isCommunicationFollowupComplete(decision: any): boolean {
    return hasResult(decision) || isFollowupDismissed(decision) || isNoResponseConfirmed(decision);
}

function isFollowupDismissed(decision: any): boolean {
    return decision?.deputationFollowupDismissed === true;
}

function isNoResponseConfirmed(decision: any): boolean {
    return decision?.deputationNoResponseConfirmed === true;
}

function isAwaitingCommunicationResult(decision: any, decisionRows: Record<string, unknown>[]): boolean {
    const rejected = isExecutorRowRejectedAndFinal(decision);
    const approved = isExecutorRowApprovedWorkflowActive(decision, decisionRows);
    return approved && !rejected && !isCommunicationFollowupComplete(decision);
}

type CommunicationDisplayContext = {
    directorate: string;
    statusLabel: string;
    statusTone: 'success' | 'warning' | 'danger' | 'neutral' | 'muted';
    requestDate: string;
    referenceLabel: string;
    outcomeTitle: string;
    outcomeBody: string;
};

function buildCommunicationDisplayContext(
    decision: any,
    decisionRows: Record<string, unknown>[],
): CommunicationDisplayContext {
    const title = String(decision?.title || '').trim() || COMMUNICATION_KEYWORD;
    const directorateFromTitle = title.includes('— ')
        ? title.split('— ').slice(1).join('— ').trim()
        : title;
    const directorate =
        String(decision?.deputationTargetDirectorate || '').trim() || directorateFromTitle;
    const rejected = isExecutorRowRejectedAndFinal(decision);
    const approved = isExecutorRowApprovedWorkflowActive(decision, decisionRows);
    const pending =
        String(decision?.executorOutcome ?? 'pending') === 'pending' ||
        String(decision?.executorOutcome ?? '') === '';
    const dismissed = isFollowupDismissed(decision);
    const noResponse = isNoResponseConfirmed(decision);
    const hasRes = hasResult(decision);
    const requestDate = String(decision?.date || decision?.resolvedAt || '').trim().slice(0, 10);
    const referenceLabel = String(decision?.deputationReferralDate || '').trim();

    let statusLabel = '—';
    let statusTone: CommunicationDisplayContext['statusTone'] = 'neutral';
    if (rejected) {
        statusLabel = 'مرفوض';
        statusTone = 'danger';
    } else if (pending) {
        statusLabel = 'قيد البت';
        statusTone = 'warning';
    } else if (approved) {
        if (hasRes && String(decision?.deputationResultDetails || '').trim()) {
            statusLabel = 'مكتمل';
            statusTone = 'success';
        } else if (dismissed) {
            statusLabel = 'موافق — مُتجاهَل';
            statusTone = 'muted';
        } else if (noResponse) {
            statusLabel = 'موافق — عدم ورود إجابة';
            statusTone = 'warning';
        } else {
            statusLabel = 'موافق — بانتظار النتيجة';
            statusTone = 'warning';
        }
    }

    let outcomeTitle = 'مضمون الإجابة';
    let outcomeBody = String(decision?.deputationResultDetails || '').trim();
    if (noResponse) {
        outcomeTitle = 'النتيجة';
        outcomeBody =
            outcomeBody ||
            'تم التأكيد — عدم ورود إجابة من الجهة المخاطبة.';
    } else if (dismissed) {
        outcomeTitle = 'المتابعة';
        outcomeBody = outcomeBody || 'تم تجاهل متابعة نتيجة المخاطبة.';
    } else if (rejected) {
        outcomeTitle = 'ملاحظة';
        outcomeBody =
            String(decision?.executorNote || decision?.body || '').trim() ||
            'تم رفض الطلب من قبل المنفذ.';
    } else if (!outcomeBody) {
        outcomeTitle = 'تفاصيل الطلب';
        outcomeBody = String(decision?.body || '').trim() || '—';
    }

    return {
        directorate,
        statusLabel,
        statusTone,
        requestDate,
        referenceLabel,
        outcomeTitle,
        outcomeBody,
    };
}

const STATUS_TONE_CLASS: Record<CommunicationDisplayContext['statusTone'], string> = {
    success: 'border-emerald-500/35 bg-emerald-500/10 text-emerald-100',
    warning: 'border-amber-500/35 bg-amber-500/10 text-amber-100',
    danger: 'border-rose-500/35 bg-rose-500/10 text-rose-100',
    neutral: 'border-slate-500/35 bg-slate-500/10 text-slate-200',
    muted: 'border-slate-600/35 bg-slate-800/50 text-slate-400',
};

export const CommunicationsTab: React.FC<CommunicationsTabProps> = ({
    decisionsStorageExecutionId,
    showToast,
    pushTimelineEvent,
    nextTimelineId,
    showSoftFieldProcedures = false,
    showEncroachmentSurveyor = false,
    showSpecificDeliverySurveyor = false,
    inlineActionGateKey = null,
    setInlineActionGateKey,
    onEncroachmentExpenseRecorded,
}) => {
    const [targetDirectorate, setTargetDirectorate] = useState('');
    const [requestDate, setRequestDate] = useState(getLocalTodayYmd());
    const [creating, setCreating] = useState(false);
    const [saving, setSaving] = useState(false);
    const [resultDraftById, setResultDraftById] = useState<
        Record<string, { purpose: string; letterNum: string; letterDate: string; result: string }>
    >({});
    const [awaitingUiById, setAwaitingUiById] = useState<
        Record<string, { confirmingNoResponse?: boolean; responseFormOpen?: boolean }>
    >({});

    const { executionId: exId, decisions } = useExecutorDecisions(decisionsStorageExecutionId);
    const decisionRows = useMemo(
        () => (Array.isArray(decisions) ? (decisions as Record<string, unknown>[]) : []),
        [decisions]
    );

    const commDecisions = useMemo(() => {
        const list = Array.isArray(decisions) ? decisions : [];
        return list
            .filter((d: any) => isCommunicationDecision(d))
            .sort((a: any, b: any) => {
                const da = String(a?.resolvedAt ?? a?.date ?? '');
                const db = String(b?.resolvedAt ?? b?.date ?? '');
                return db.localeCompare(da, undefined, { numeric: true });
            });
    }, [decisions]);

    const awaitingExecutor = useMemo(() => {
        return commDecisions.filter((d: any) => {
            const out = String(d?.executorOutcome ?? 'pending');
            return out === 'pending' || out === '';
        });
    }, [commDecisions]);

    const awaitingResultDecisions = useMemo(() => {
        return commDecisions.filter((d: any) => isAwaitingCommunicationResult(d, decisionRows));
    }, [commDecisions, decisionRows]);

    const logDecisions = useMemo(() => {
        return commDecisions.filter((d: any) => {
            const out = String(d?.executorOutcome ?? 'pending');
            if (out === 'pending' || out === '') return false;
            return !isAwaitingCommunicationResult(d, decisionRows);
        });
    }, [commDecisions, decisionRows]);

    /** إنشاء طلب مخاطبة جديد */
    const handleCreate = async () => {
        if (!targetDirectorate.trim()) {
            showToast('يرجى إدخال اسم الجهة المُخاطبة', 'warning');
            return;
        }
        if (!requestDate.trim()) {
            showToast('يرجى إدخال تاريخ الطلب', 'warning');
            return;
        }
        setCreating(true);

        try {
            const { appendSpecialFollowupRequest } = await import('@/app/utils/executorSeizureDecisionQueue');
            const title = `${COMMUNICATION_KEYWORD} — ${targetDirectorate.trim()}`;
            const decisionId = appendSpecialFollowupRequest({
                executionId: exId,
                requestDate: requestDate.trim(),
                content: `مخاطبة جهة: ${targetDirectorate.trim()}`,
                decisionTitle: title,
            });

            if (!decisionId) {
                showToast('يوجد طلب مماثل قيد البت لدى المنفذ.', 'warning');
                setCreating(false);
                return;
            }

            const now = new Date().toISOString();
            pushTimelineEvent({
                id: nextTimelineId(),
                type: 'communication',
                title: `مخاطبة: ${targetDirectorate.trim()}`,
                description: `طلب مخاطبة جهة — ${requestDate.trim()} — قيد البت لدى المنفذ`,
                date: requestDate.trim(),
                timestamp: now,
                source: 'محضر المتابعة',
                metadata: { timelineThreadKey: `executor_decision:${decisionId}`, decisionRowId: decisionId },
            });

            setTargetDirectorate('');
            setRequestDate(getLocalTodayYmd());
            showToast('تم إنشاء الطلب — قرار المنفذ يظهر هنا مباشرة.', 'success');
        } catch {
            showToast('فشل إنشاء الطلب', 'error');
        }
        setCreating(false);
    };

    const extractDirectorate = (title: string): string => {
        const parts = title.split('— ');
        return parts.length > 1 ? parts[1].trim() : title;
    };

    const renderCommunicationContextPanel = (
        ctx: CommunicationDisplayContext,
        opts?: { compact?: boolean },
    ) => {
        const compact = opts?.compact === true;
        return (
            <div className={`space-y-2.5 ${compact ? '' : 'pt-0.5'}`}>
                <div className="flex flex-wrap items-center justify-end gap-2">
                    <span
                        className={`rounded-lg border px-2 py-0.5 text-[10px] font-bold ${STATUS_TONE_CLASS[ctx.statusTone]}`}
                    >
                        {ctx.statusLabel}
                    </span>
                    {ctx.requestDate ? (
                        <span className="text-[10px] text-slate-500">تاريخ الطلب: {ctx.requestDate}</span>
                    ) : null}
                </div>
                {ctx.referenceLabel ? (
                    <div className="rounded-xl border border-white/10 bg-white/[0.03] px-3 py-2 text-right">
                        <p className="text-[9px] font-bold text-slate-500">مرجع الإجابة</p>
                        <p className="mt-0.5 text-[11px] font-semibold text-slate-200">{ctx.referenceLabel}</p>
                    </div>
                ) : null}
                <div className="rounded-xl border border-white/10 bg-black/25 px-3 py-2.5 text-right">
                    <p className="text-[9px] font-bold text-slate-500">{ctx.outcomeTitle}</p>
                    <p
                        className={`mt-1 whitespace-pre-wrap leading-relaxed text-slate-100 ${
                            compact ? 'text-[11px]' : 'text-[12px]'
                        }`}
                    >
                        {ctx.outcomeBody}
                    </p>
                </div>
            </div>
        );
    };

    const openAppeals = (decisionId: string) => {
        if (!exId || !decisionId) return;
        try {
            window.dispatchEvent(
                new CustomEvent('hami-open-decisions-modal', {
                    detail: { executionId: exId, tab: 'previous', decisionId },
                })
            );
        } catch {
            /* ignore */
        }
    };

    const renderCommunicationLogEntry = (decision: any) => {
        const decisionId = String(decision?.id || '').trim();
        const ctx = buildCommunicationDisplayContext(decision, decisionRows);

        return (
            <div
                key={decisionId}
                className="rounded-2xl border border-white/10 bg-black/20 px-3 py-3 text-right space-y-2"
            >
                <div className="space-y-1">
                    <p className="text-[12px] font-black text-slate-50">{ctx.directorate}</p>
                    <p className="text-[10px] text-slate-500">إرسال كتاب / مخاطبة جهة</p>
                </div>
                {renderCommunicationContextPanel(ctx)}
            </div>
        );
    };

    const saveCommunicationResult = (
        decisionId: string,
        directorate: string,
        draft: { purpose: string; letterNum: string; letterDate: string; result: string },
    ) => {
        if (!exId || !decisionId || saving) return;
        if (!String(draft.result || '').trim()) {
            showToast('أدخل مضمون الإجابة', 'warning');
            return;
        }
        setSaving(true);
        const now = new Date().toISOString();
        const ref = [String(draft.letterDate || '').trim(), String(draft.letterNum || '').trim()]
            .filter(Boolean)
            .join(' ');
        patchExecutorDecisionRow(exId, decisionId, {
            deputationTargetDirectorate: String(draft.purpose || '').trim(),
            deputationReferralDate: ref || undefined,
            deputationResultDetails: String(draft.result || '').trim(),
            deputationClosed: true,
            deputationSent: true,
        } as any);
        try {
            pushTimelineEvent({
                id: nextTimelineId(),
                type: 'communication',
                title: `نتيجة مخاطبة — ${directorate}`,
                description: [
                    ref ? `مرجع: ${ref}` : '',
                    String(draft.result || '').trim(),
                ]
                    .filter(Boolean)
                    .join('\n'),
                date: now.slice(0, 10),
                timestamp: now,
                source: 'محضر المتابعة',
            });
        } catch {
            /* ignore */
        }
        setAwaitingUiById((prev) => {
            const next = { ...prev };
            delete next[decisionId];
            return next;
        });
        setSaving(false);
        showToast('✅ تم حفظ النتيجة الواردة', 'success');
    };

    const renderAwaitingResultCard = (decision: any) => {
        const decisionId = String(decision?.id || '').trim();
        const ctx = buildCommunicationDisplayContext(decision, decisionRows);
        const ui = awaitingUiById[decisionId] || {};
        const draft =
            resultDraftById[decisionId] || {
                purpose: ctx.directorate,
                letterNum: '',
                letterDate: '',
                result: '',
            };
        const showActionButtons = !ui.confirmingNoResponse;

        const dismissFollowup = () => {
            if (!exId || !decisionId || saving) return;
            setSaving(true);
            try {
                patchExecutorDecisionRow(exId, decisionId, {
                    deputationFollowupDismissed: true,
                    deputationClosed: true,
                    deputationResultDetails: 'تم تجاهل متابعة نتيجة المخاطبة.',
                } as any);
                setAwaitingUiById((prev) => {
                    const next = { ...prev };
                    delete next[decisionId];
                    return next;
                });
                showToast('تم تجاهل متابعة النتيجة', 'info');
            } catch {
                showToast('تعذّر التجاهل', 'error');
            }
            setSaving(false);
        };

        const confirmNoResponse = () => {
            if (!exId || !decisionId || saving) return;
            setSaving(true);
            try {
                patchExecutorDecisionRow(exId, decisionId, {
                    deputationNoResponseConfirmed: true,
                    deputationClosed: true,
                    deputationResultDetails:
                        'تم التأكيد — عدم ورود إجابة من الجهة المخاطبة.',
                } as any);
                const now = new Date().toISOString();
                pushTimelineEvent({
                    id: nextTimelineId(),
                    type: 'communication',
                    title: `تأكيد — عدم ورود إجابة — ${ctx.directorate}`,
                    description: 'تم التأكيد — عدم ورود إجابة من الجهة المخاطبة.',
                    date: now.slice(0, 10),
                    timestamp: now,
                    source: 'محضر المتابعة',
                    metadata: { timelineThreadKey: `executor_decision:${decisionId}` },
                });
                setAwaitingUiById((prev) => {
                    const next = { ...prev };
                    delete next[decisionId];
                    return next;
                });
                showToast('تم تسجيل عدم ورود الإجابة', 'success');
            } catch {
                showToast('تعذّر التسجيل', 'error');
            }
            setSaving(false);
        };

        return (
            <div
                key={decisionId}
                className="rounded-2xl border border-white/10 bg-black/15 px-3 py-3 text-right space-y-3"
            >
                <div className="space-y-1">
                    <p className="text-[12px] font-black text-slate-50">{ctx.directorate}</p>
                    <p className="text-[10px] text-slate-500">مخاطبة بانتظار النتيجة</p>
                </div>

                {renderCommunicationContextPanel(ctx, { compact: true })}

                {ui.confirmingNoResponse ? (
                    <div className="rounded-xl border border-amber-500/25 bg-amber-950/20 px-3 py-2.5 space-y-2">
                        <p className="text-[11px] font-bold text-amber-100">
                            تأكيد عدم ورود إجابة من «{ctx.directorate}»؟
                        </p>
                        <p className="text-[10px] leading-relaxed text-amber-100/80">
                            سيُسجَّل في سجل المخاطبات بنفس سياق البطاقة العادية.
                        </p>
                        <div className="flex flex-row-reverse flex-wrap gap-2">
                            <button
                                type="button"
                                disabled={saving}
                                onClick={confirmNoResponse}
                                className="rounded-xl border border-amber-500/40 bg-amber-600/20 px-3 py-2 text-[11px] font-black text-amber-100 disabled:opacity-40"
                            >
                                تأكيد
                            </button>
                            <button
                                type="button"
                                disabled={saving}
                                onClick={() =>
                                    setAwaitingUiById((prev) => ({
                                        ...prev,
                                        [decisionId]: {
                                            ...prev[decisionId],
                                            confirmingNoResponse: false,
                                        },
                                    }))
                                }
                                className="rounded-xl bg-slate-800 px-3 py-2 text-[11px] font-bold text-slate-100 disabled:opacity-40"
                            >
                                إلغاء
                            </button>
                        </div>
                    </div>
                ) : showActionButtons ? (
                    <div className="flex flex-row-reverse flex-wrap gap-2">
                        <button
                            type="button"
                            disabled={saving}
                            onClick={() =>
                                setAwaitingUiById((prev) => ({
                                    ...prev,
                                    [decisionId]: {
                                        ...prev[decisionId],
                                        confirmingNoResponse: true,
                                        responseFormOpen: false,
                                    },
                                }))
                            }
                            className="rounded-xl border border-amber-500/35 bg-amber-500/10 px-3 py-2 text-[10px] font-bold text-amber-100 hover:bg-amber-500/15 disabled:opacity-40"
                        >
                            عدم ورود الإجابة
                        </button>
                        <button
                            type="button"
                            disabled={saving}
                            onClick={() =>
                                setAwaitingUiById((prev) => ({
                                    ...prev,
                                    [decisionId]: {
                                        ...prev[decisionId],
                                        responseFormOpen: !prev[decisionId]?.responseFormOpen,
                                        confirmingNoResponse: false,
                                    },
                                }))
                            }
                            className="rounded-xl border border-emerald-500/35 bg-emerald-500/10 px-3 py-2 text-[10px] font-bold text-emerald-100 hover:bg-emerald-500/15 disabled:opacity-40"
                        >
                            تم ورود الإجابة
                        </button>
                        <button
                            type="button"
                            disabled={saving}
                            onClick={dismissFollowup}
                            className="rounded-xl border border-slate-500/35 bg-slate-800/60 px-3 py-2 text-[10px] font-bold text-slate-300 hover:bg-slate-800 disabled:opacity-40"
                        >
                            التجاهل
                        </button>
                    </div>
                ) : null}

                {ui.responseFormOpen && showActionButtons ? (
                    <div className="space-y-2 border-t border-white/10 pt-2">
                        <div className="grid grid-cols-2 gap-2">
                            <div>
                                <label className="mb-1 block text-[9px] text-slate-500">تاريخ الإجابة</label>
                                <input
                                    type="date"
                                    value={draft.letterDate}
                                    onChange={(e) =>
                                        setResultDraftById((prev) => ({
                                            ...prev,
                                            [decisionId]: { ...draft, letterDate: e.target.value },
                                        }))
                                    }
                                    className="w-full rounded-xl border border-white/10 bg-white/5 px-3 py-2 text-[11px] text-slate-100"
                                />
                            </div>
                            <div>
                                <label className="mb-1 block text-[9px] text-slate-500">رقم الكتاب</label>
                                <input
                                    type="text"
                                    value={draft.letterNum}
                                    onChange={(e) =>
                                        setResultDraftById((prev) => ({
                                            ...prev,
                                            [decisionId]: { ...draft, letterNum: e.target.value },
                                        }))
                                    }
                                    className="w-full rounded-xl border border-white/10 bg-white/5 px-3 py-2 text-[11px] text-slate-100 text-right"
                                    placeholder="رقم الكتاب"
                                />
                            </div>
                        </div>
                        <div>
                            <label className="mb-1 block text-[9px] text-slate-500">مضمون الإجابة</label>
                            <textarea
                                value={draft.result}
                                onChange={(e) =>
                                    setResultDraftById((prev) => ({
                                        ...prev,
                                        [decisionId]: { ...draft, result: e.target.value },
                                    }))
                                }
                                rows={3}
                                className="w-full resize-none rounded-xl border border-white/10 bg-white/5 px-3 py-2 text-[11px] text-slate-100 text-right"
                                placeholder="مضمون الإجابة الواردة"
                            />
                        </div>
                        <button
                            type="button"
                            disabled={saving || !String(draft.result || '').trim()}
                            onClick={() => saveCommunicationResult(decisionId, ctx.directorate, draft)}
                            className="w-full rounded-xl bg-emerald-700/70 py-2.5 text-[11px] font-black text-white disabled:opacity-40"
                        >
                            حفظ
                        </button>
                    </div>
                ) : null}
            </div>
        );
    };

    const renderCommunicationCard = (decision: any) => {
        const decisionId = String(decision?.id || '').trim();
        const title = String(decision?.title || '').trim() || COMMUNICATION_KEYWORD;
        const directorate = extractDirectorate(title);
        const rejected = isExecutorRowRejectedAndFinal(decision);
        const approved = isExecutorRowApprovedWorkflowActive(decision, decisionRows);
        const pending = String(decision?.executorOutcome ?? 'pending') === 'pending' || String(decision?.executorOutcome ?? '') === '';
        const hasRes = hasResult(decision);
        const draft =
            resultDraftById[decisionId] || { purpose: directorate, letterNum: '', letterDate: '', result: '' };
        const delivered = decision?.deputationSent === true;
        const canSaveResult =
            approved && !rejected && !hasRes && delivered && Boolean(String(draft.result || '').trim());

        const markDelivered = () => {
            if (!exId || !decisionId || saving) return;
            setSaving(true);
            try {
                patchExecutorDecisionRow(exId, decisionId, { deputationSent: true } as any);
                showToast('تم تسجيل التسليم', 'success');
            } catch {
                showToast('تعذّر تسجيل التسليم', 'error');
            }
            setSaving(false);
        };

        const steps: ExecutionInlineStep[] = [
            {
                id: `${decisionId}:sent`,
                title: 'طلب مخاطبة جهة',
                subtitle: `الجهة: ${directorate}`,
                status: 'done',
                tone: 'success',
            },
            {
                id: `${decisionId}:executor`,
                title: 'قرار المنفذ',
                subtitle: rejected ? 'تم رفض الطلب' : approved ? 'تمت الموافقة' : pending ? 'قيد البت' : '—',
                status: rejected || pending ? 'active' : 'done',
                tone: rejected ? 'danger' : approved ? 'success' : 'neutral',
                content: rejected ? (
                    <ExecutionInlineExecutorDecisionActions
                        executionId={exId}
                        decisionId={decisionId}
                        requestKind={String(decision?.requestKind || 'special_followup')}
                        disabled
                        onOpenAppealCenter={() => openAppeals(decisionId)}
                    />
                ) : pending ? (
                    <ExecutionInlineExecutorDecisionActions
                        executionId={exId}
                        decisionId={decisionId}
                        requestKind={String(decision?.requestKind || 'special_followup')}
                    />
                ) : null,
            },
            {
                id: `${decisionId}:result`,
                title: 'تسجيل نتيجة المخاطبة',
                subtitle: hasRes
                    ? 'تم تسجيل النتيجة'
                    : approved && !rejected && delivered
                      ? 'بانتظار إدخال النتيجة'
                      : approved && !rejected
                        ? 'بانتظار تأكيد التسليم'
                        : 'مقفلة حتى موافقة المنفذ',
                status: hasRes
                    ? 'done'
                    : approved && !rejected && delivered
                      ? 'active'
                      : 'locked',
                tone: hasRes ? 'success' : 'neutral',
                content:
                    approved && !rejected && !hasRes && delivered ? (
                        <div className="space-y-2">
                            <input
                                type="text"
                                value={draft.purpose}
                                onChange={(e) =>
                                    setResultDraftById((prev) => ({
                                        ...prev,
                                        [decisionId]: { ...draft, purpose: e.target.value },
                                    }))
                                }
                                className="w-full rounded-xl border border-white/10 bg-white/5 px-3 py-2 text-[11px] text-slate-100 text-right"
                                placeholder="الجهة المخاطبة"
                            />
                            <div className="grid grid-cols-2 gap-2">
                                <input
                                    type="date"
                                    value={draft.letterDate}
                                    onChange={(e) =>
                                        setResultDraftById((prev) => ({
                                            ...prev,
                                            [decisionId]: { ...draft, letterDate: e.target.value },
                                        }))
                                    }
                                    className="w-full rounded-xl border border-white/10 bg-white/5 px-3 py-2 text-[11px] text-slate-100"
                                />
                                <input
                                    type="text"
                                    value={draft.letterNum}
                                    onChange={(e) =>
                                        setResultDraftById((prev) => ({
                                            ...prev,
                                            [decisionId]: { ...draft, letterNum: e.target.value },
                                        }))
                                    }
                                    className="w-full rounded-xl border border-white/10 bg-white/5 px-3 py-2 text-[11px] text-slate-100 text-right"
                                    placeholder="رقم الكتاب"
                                />
                            </div>
                            <textarea
                                value={draft.result}
                                onChange={(e) =>
                                    setResultDraftById((prev) => ({
                                        ...prev,
                                        [decisionId]: { ...draft, result: e.target.value },
                                    }))
                                }
                                rows={3}
                                className="w-full resize-none rounded-xl border border-white/10 bg-white/5 px-3 py-2 text-[11px] text-slate-100 text-right"
                                placeholder="تفاصيل النتيجة الواردة"
                            />
                            <button
                                type="button"
                                disabled={!canSaveResult || saving}
                                onClick={() => {
                                    if (!canSaveResult || saving) return;
                                    setSaving(true);
                                    const now = new Date().toISOString();
                                    const ref = [
                                        String(draft.letterDate || '').trim(),
                                        String(draft.letterNum || '').trim(),
                                    ]
                                        .filter(Boolean)
                                        .join(' ');
                                    patchExecutorDecisionRow(exId, decisionId, {
                                        deputationTargetDirectorate: String(draft.purpose || '').trim(),
                                        deputationReferralDate: ref || undefined,
                                        deputationResultDetails: String(draft.result || '').trim(),
                                        deputationClosed: true,
                                    } as any);
                                    try {
                                        const ref = [
                                            String(draft.letterDate || '').trim(),
                                            String(draft.letterNum || '').trim(),
                                        ]
                                            .filter(Boolean)
                                            .join(' · ');
                                        pushTimelineEvent({
                                            id: nextTimelineId(),
                                            type: 'communication',
                                            title: `نتيجة مخاطبة — ${directorate}`,
                                            description: [
                                                ref ? `مرجع: ${ref}` : '',
                                                String(draft.result || '').trim(),
                                            ]
                                                .filter(Boolean)
                                                .join('\n'),
                                            date: now.slice(0, 10),
                                            timestamp: now,
                                            source: 'محضر المتابعة',
                                        });
                                    } catch {
                                        /* ignore */
                                    }
                                    setSaving(false);
                                    showToast('✅ تم حفظ النتيجة الواردة', 'success');
                                }}
                                className="w-full rounded-xl bg-emerald-700/70 py-2.5 text-[11px] font-black text-white disabled:opacity-40"
                            >
                                حفظ النتيجة
                            </button>
                        </div>
                    ) : hasRes ? (
                        renderCommunicationContextPanel(
                            buildCommunicationDisplayContext(decision, decisionRows),
                            { compact: true },
                        )
                    ) : null,
            } satisfies ExecutionInlineStep,
        ];

        return (
            <div key={decisionId} className="rounded-2xl border border-white/10 bg-black/15 p-3">
                {approved && !rejected && !hasRes ? (
                    <div className="mb-3 flex justify-end">
                        {!delivered ? (
                            <button
                                type="button"
                                disabled={saving}
                                onClick={markDelivered}
                                className="rounded-xl border border-cyan-500/35 bg-cyan-500/10 px-3 py-2 text-[11px] font-extrabold text-cyan-200 hover:bg-cyan-500/15 disabled:opacity-40"
                            >
                                تم التسليم
                            </button>
                        ) : (
                            <span className="rounded-xl border border-emerald-500/30 bg-emerald-500/10 px-3 py-2 text-[11px] font-extrabold text-emerald-200">
                                تمت الإجابة
                            </span>
                        )}
                    </div>
                ) : null}
                <ExecutionInlineAccordion steps={steps} />
            </div>
        );
    };

    return (
        <div className="space-y-5 p-3 text-right" dir="rtl">
            {showSoftFieldProcedures && setInlineActionGateKey ? (
                <LegalEntitySoftProceduresSection
                    decisionsStorageExecutionId={decisionsStorageExecutionId}
                    inlineActionGateKey={inlineActionGateKey}
                    setInlineActionGateKey={setInlineActionGateKey}
                    showToast={showToast}
                    showEncroachmentSurveyor={showEncroachmentSurveyor}
                    showSpecificDeliverySurveyor={showSpecificDeliverySurveyor}
                    onEncroachmentExpenseRecorded={onEncroachmentExpenseRecorded}
                />
            ) : null}
            <div className="rounded-xl border border-indigo-500/20 bg-indigo-950/15 p-4">
                <div className="flex items-center gap-2 mb-3">
                    <Send size={16} className="text-indigo-400" />
                    <h4 className="text-[11px] font-bold text-indigo-200">إرسال كتاب / مخاطبة جهة</h4>
                </div>

                <div className="mb-3">
                    <label className="mb-1 block text-[9px] text-slate-400">إلى الجهة المُخاطبة *</label>
                    <input
                        type="text"
                        value={targetDirectorate}
                        onChange={(e) => setTargetDirectorate(e.target.value)}
                        placeholder="أدخل اسم الدائرة أو الجهة..."
                        className="w-full bg-black/30 border border-white/10 text-white rounded-xl p-3 text-[11px] focus:outline-none focus:border-indigo-500/50 placeholder:text-white/20"
                    />
                </div>

                <div className="mb-3">
                    <label className="mb-1 block text-[9px] text-slate-400">تاريخ الطلب</label>
                    <input
                        type="date"
                        value={requestDate}
                        onChange={(e) => setRequestDate(e.target.value)}
                        max={new Date().toISOString().slice(0, 10)}
                        dir="rtl"
                        className="w-full bg-black/30 border border-white/10 text-white rounded-xl p-3 text-[11px] focus:outline-none focus:border-indigo-500/50 [&::-webkit-calendar-picker-indicator]:invert"
                    />
                </div>

                <button
                    type="button"
                    onClick={handleCreate}
                    disabled={creating}
                    className="w-full flex items-center justify-center gap-2 py-3 bg-indigo-600/80 text-white hover:bg-indigo-600 rounded-xl font-bold text-[11px] border border-indigo-500/30 transition-all disabled:opacity-50"
                >
                    {creating ? 'جاري الإنشاء...' : (
                        <>
                            <Plus size={16} /> إنشاء الطلب
                        </>
                    )}
                </button>
            </div>

            {awaitingExecutor.length > 0 ? (
                <div className="space-y-2">
                    <h4 className="flex items-center gap-1.5 text-[11px] font-bold text-amber-200 mb-2 px-1">
                        <Clock size={14} />
                        طلبات بانتظار قرار المنفذ
                        <span className="text-[9px] text-slate-500 font-normal">({awaitingExecutor.length})</span>
                    </h4>
                    <div className="space-y-2">{awaitingExecutor.map(renderCommunicationCard)}</div>
                </div>
            ) : null}

            {awaitingResultDecisions.length > 0 ? (
                <div className="space-y-2">
                    <h4 className="flex items-center gap-1.5 text-[11px] font-bold text-cyan-200 mb-2 px-1">
                        <Clock size={14} />
                        مخاطبات بانتظار النتيجة
                        <span className="text-[9px] text-slate-500 font-normal">
                            ({awaitingResultDecisions.length})
                        </span>
                    </h4>
                    <div className="space-y-2">{awaitingResultDecisions.map(renderAwaitingResultCard)}</div>
                </div>
            ) : null}

            <div className="space-y-2">
                <h4 className="flex items-center gap-1.5 text-[11px] font-bold text-emerald-200 mb-2 px-1">
                    <CheckCircle size={14} />
                    سجل المخاطبات
                    {logDecisions.length > 0 ? (
                        <span className="text-[9px] text-slate-500 font-normal">({logDecisions.length})</span>
                    ) : null}
                </h4>
                {logDecisions.length === 0 ? (
                    <p className="px-1 text-[10px] text-slate-500">لا توجد مخاطبات في السجل بعد.</p>
                ) : (
                    <div className="space-y-2">{logDecisions.map(renderCommunicationLogEntry)}</div>
                )}
            </div>
        </div>
    );
};

import React, { memo, useEffect, useMemo, useState } from 'react';
import { AnimatePresence, motion } from 'motion/react';
import type { ElementType } from 'react';
import { type ExecutionFile } from '@/app/types/execution';
import {
    fileHasSpecificDeliveryClaim,
    resolveDossierHeaderFields,
    type DossierHeaderResolved,
} from '@/app/utils/executionDossierHeaderFields';
import {
    Link,
} from 'lucide-react';

interface StatuteStatus {
    daysRemaining: number;
    yearsRemaining: number;
    isCritical: boolean;
    isExpired: boolean;
}

const DetailCell = memo(function DetailCell({
    label,
    value,
    className = '',
    valueClassName = '',
    /** عند false تُعرض الخلية حتى لو فارغة (رقم/تاريخ الحكم) */
    hideIfEmpty = true,
}: {
    label: string;
    value: string;
    className?: string;
    valueClassName?: string;
    hideIfEmpty?: boolean;
}) {
    const trimmed = String(value || '').trim();
    if (hideIfEmpty && (!trimmed || trimmed === '—')) return null;
    const display = trimmed || '—';
    const empty = !trimmed || trimmed === '—';
    return (
        <div
            className={`rounded-md border border-amber-500/22 bg-[#0B1120]/50 px-2 py-1 text-right leading-snug ${className}`}
            dir="rtl"
        >
            <p className="text-[10px] leading-none text-amber-200/55">{label}</p>
            <p
                className={`mt-0.5 text-[12px] font-semibold whitespace-normal [unicode-bidi:plaintext] [word-break:keep-all] [overflow-wrap:normal] ${
                    empty ? 'text-slate-500' : 'text-white'
                } ${valueClassName}`}
            >
                {display}
            </p>
        </div>
    );
});

interface DashboardHeaderSectionProps {
    statuteStatus: StatuteStatus | null;
    isAlimonyClaim: boolean;
    executionPaused: boolean;
    handleResumeExecution: () => void;
    stayOfExecutionActive: boolean;
    executionData: ExecutionFile;
    handleLiftStayOfExecution: () => void;
    XCircle: ElementType;
    isHeaderExpanded: boolean;
    toggleHeaderExpanded: () => void;
    /** حقول الشريط من نموذج الإنشاء (بدون قيم افتراضية وهمية) */
    headerFields: DossierHeaderResolved;
    openEditDossierMeta: () => void;
    Pencil: ElementType;
    isEvictionExecutionModule: boolean;
    classificationDisplay: string;
    showJudgmentMeta: boolean;
    docNumber?: string;
    judgmentDateDisplay: string;
    claimTypeArabicDisplay: string;
    evictionPropertyNumber: string;
    evictionPropertyDistrict: string;
    evictionPropertyTypeField: string;
    evictionFullAddressField: string;
    /** هل هذه إضبارة فرعية (إنابة) */
    isSubFile?: boolean;
    /** إنابة نشطة للإضبارة الأم (لإظهار زر مخاطبة الإنابة) */
    hasActiveInaba?: boolean;
    /** الغاية من الإنابة — تُعرض في الحالة الموسعة فقط */
    delegationPurpose?: string;
    /** رمز مشاركة الإضبارة (طلب توحيد الأضابير) */
    linkToken?: string;
    /** نسخ رمز المشاركة */
    onCopyLinkToken?: () => void;
    /** الأضابير الموحّدة */
    linkedDossiers?: ExecutionFile['linkedDossiers'];
    /** فتح إضبارة موحّدة (قراءة السجل الزمني فقط للزميل) */
    onOpenLinkedDossier?: (dossier: NonNullable<ExecutionFile['linkedDossiers']>[number]) => void;
    onRemoveLinkedDossier?: (linkedId: string) => void;
    onRequestTransferFileNumberChange?: () => void;
    /** حفظ رقم/سنة الإضبارة الفرعية */
    onSaveSubFileNumber?: (fileNumber: string, fileYear: string) => void;
    /** تفاصيل الحاوية الموسّعة من الإضبارة الأم (إنابة) — المديرية والرقم يبقيان للفرعية */
    expandedDossierFromParent?: {
        headerFields: DossierHeaderResolved;
        classificationDisplay: string;
        claimTypeArabicDisplay: string;
        showJudgmentMeta: boolean;
        judgmentDateDisplay: string;
        docNumber?: string;
        evictionPropertyNumber: string;
        evictionPropertyDistrict: string;
        evictionPropertyTypeField: string;
        evictionFullAddressField: string;
        isEvictionExecutionModule: boolean;
        openEditDossierMeta: () => void;
        showSpecificDeliveryMeta?: boolean;
    };
}

export const DashboardHeaderSection = memo(function DashboardHeaderSection({
    statuteStatus,
    isAlimonyClaim,
    executionPaused,
    handleResumeExecution,
    stayOfExecutionActive,
    executionData,
    handleLiftStayOfExecution,
    XCircle,
    isHeaderExpanded,
    toggleHeaderExpanded,
    headerFields,
    openEditDossierMeta,
    Pencil,
    isEvictionExecutionModule,
    classificationDisplay,
    showJudgmentMeta,
    docNumber,
    judgmentDateDisplay,
    claimTypeArabicDisplay,
    evictionPropertyNumber,
    evictionPropertyDistrict,
    evictionPropertyTypeField,
    evictionFullAddressField,
    isSubFile,
    hasActiveInaba,
    delegationPurpose,
    linkToken,
    onCopyLinkToken,
    linkedDossiers,
    onOpenLinkedDossier,
    onRemoveLinkedDossier,
    onRequestTransferFileNumberChange,
    onSaveSubFileNumber,
    expandedDossierFromParent,
}: DashboardHeaderSectionProps) {
    const resolvedFromExecution = useMemo(
        () => resolveDossierHeaderFields(executionData),
        [executionData],
    );
    const effectiveHeaderFields = useMemo((): DossierHeaderResolved => {
        const hasIncoming =
            Boolean(headerFields.directorate?.trim()) ||
            Boolean(headerFields.fileNumber?.trim()) ||
            Boolean(headerFields.fileYear?.trim()) ||
            Boolean(headerFields.fileRefDisplay?.trim() && headerFields.fileRefDisplay !== '—');
        if (hasIncoming) return headerFields;
        return resolvedFromExecution;
    }, [headerFields, resolvedFromExecution]);

    const [localHeaderExpanded, setLocalHeaderExpanded] = useState(isHeaderExpanded);
    useEffect(() => {
        setLocalHeaderExpanded(isHeaderExpanded);
    }, [isHeaderExpanded]);
    const headerExpanded = localHeaderExpanded;

    const showSpecificDeliveryMeta = fileHasSpecificDeliveryClaim(executionData);
    const expanded = expandedDossierFromParent ?? {
        headerFields: effectiveHeaderFields,
        classificationDisplay,
        claimTypeArabicDisplay,
        showJudgmentMeta,
        judgmentDateDisplay,
        docNumber,
        evictionPropertyNumber,
        evictionPropertyDistrict,
        evictionPropertyTypeField,
        evictionFullAddressField,
        isEvictionExecutionModule,
        openEditDossierMeta,
        showSpecificDeliveryMeta,
    };
    const showTransferFileNumberChange =
        Boolean(executionData?.transferPendingFileNumberChange) && typeof onRequestTransferFileNumberChange === 'function';
    const [subFileNumberEditorOpen, setSubFileNumberEditorOpen] = useState(false);
    const [subFileNumberDraft, setSubFileNumberDraft] = useState('');
    const [subFileYearDraft, setSubFileYearDraft] = useState('');

    useEffect(() => {
        if (!isSubFile) {
            setSubFileNumberEditorOpen(false);
            return;
        }
        setSubFileNumberDraft(headerFields.fileNumber || '');
        setSubFileYearDraft(headerFields.fileYear || '');
    }, [isSubFile, effectiveHeaderFields.fileNumber, effectiveHeaderFields.fileYear]);

    const subFileRefFilled = Boolean(
        String(effectiveHeaderFields.fileNumber || '').trim() ||
            String(effectiveHeaderFields.fileYear || '').trim()
    );
    const subFileRefDisplay = subFileRefFilled
        ? `${effectiveHeaderFields.fileNumber || '—'} / ${effectiveHeaderFields.fileYear || '—'}`
        : '';

    const handleSaveSubFileNumber = (e?: React.MouseEvent) => {
        e?.stopPropagation();
        e?.preventDefault();
        const num = subFileNumberDraft.trim();
        const year = subFileYearDraft.trim();
        if (!num && !year) return;
        onSaveSubFileNumber?.(num, year);
        setSubFileNumberEditorOpen(false);
    };

    return (
        <>
            {/* STATUTE EXPIRED BANNER */}
            {statuteStatus && statuteStatus.isExpired && !isAlimonyClaim && (
                <motion.div
                    initial={{ opacity: 0, y: -20 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="mx-3 mt-3 bg-gradient-to-r from-rose-950/80 to-gray-950/80 border-2 border-rose-500/80 rounded-2xl p-4 shadow-lg shadow-rose-500/30"
                >
                    <div className="flex items-center justify-end gap-3 mb-2">
                        <div className="flex items-center gap-2">
                            <XCircle size={24} className="text-rose-400" />
                            <h3 className="text-rose-400 font-bold text-sm">❌ سقطت قوة التنفيذ</h3>
                        </div>
                    </div>
                    <p className="text-white text-sm text-right mb-2">
                        مضى أكثر من 7 سنوات على آخر إجراء - الإضبارة فقدت قوتها التنفيذية
                    </p>
                    <p className="text-gray-300 text-xs text-right">
                        استشر المحكمة لتحديد الخيارات القانونية المتاحة
                    </p>
                </motion.div>
            )}

            {/* 🆕 V8: EXECUTION PAUSED BANNER */}
            {executionPaused && (
                <motion.div
                    initial={{ opacity: 0, y: -10 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="mx-3 mt-3 bg-gradient-to-r from-orange-950/60 to-amber-950/60 border-2 border-amber-500/60 rounded-2xl p-4 shadow-lg shadow-amber-500/20"
                >
                    <div className="flex items-center justify-center gap-3">
                        <svg
                            width="24"
                            height="24"
                            viewBox="0 0 24 24"
                            fill="none"
                            stroke="currentColor"
                            strokeWidth="2"
                            className="text-amber-400 animate-pulse"
                        >
                            <circle cx="12" cy="12" r="10" />
                            <line x1="10" y1="15" x2="10" y2="9" />
                            <line x1="14" y1="15" x2="14" y2="9" />
                        </svg>
                        <p className="text-amber-300 font-bold text-sm">⏸️ الإضبارة موقوفة للمراجعة</p>
                    </div>
                    <p className="text-gray-300 text-xs text-center mt-2">
                        تم إيقاف جميع المهل الزمنية والإجراءات الجبرية
                    </p>
                    <button
                        type="button"
                        onClick={handleResumeExecution}
                        className="mt-3 w-full rounded-lg border border-emerald-500/40 bg-emerald-950/50 py-2 text-[10px] font-bold text-emerald-100 hover:bg-emerald-950/65"
                    >
                        استئناف التنفيذ
                    </button>
                </motion.div>
            )}

            {stayOfExecutionActive && (
                <motion.div
                    initial={{ opacity: 0, y: -10 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="sticky top-0 z-30 mx-3 mt-2 rounded-xl border border-yellow-500/40 bg-amber-950/70 p-2.5 shadow-md shadow-yellow-950/20"
                >
                    <div className="flex flex-col gap-1.5 text-right">
                        <p className="text-center text-[11px] font-bold text-yellow-200">تفاصيل الاستئخار</p>
                        {executionData?.stay_of_execution?.court_name && (
                            <p className="text-[9px] leading-snug text-slate-400">
                                {executionData.stay_of_execution.court_name}
                                {executionData.stay_of_execution.decision_number
                                    ? ` — ${executionData.stay_of_execution.decision_number}`
                                    : ''}
                                {executionData.stay_of_execution.next_hearing_date
                                    ? ` — جلسة: ${executionData.stay_of_execution.next_hearing_date}`
                                    : ''}
                            </p>
                        )}
                        <button
                            type="button"
                            onClick={handleLiftStayOfExecution}
                            className="w-full rounded-lg border border-emerald-500/35 bg-emerald-950/50 py-2 text-[10px] font-bold text-emerald-100"
                        >
                            رفع الاستئخار
                        </button>
                    </div>
                </motion.div>
            )}


            {/* 🆕 V19: FILE HEADER — المديرية ورقم الإضبارة + حالة الإضبارة (داخل الحاوية الجوزية) */}
            <div className="mx-3 mt-1.5 mb-1.5">
                <div
                    className={`relative w-full overflow-hidden backdrop-blur-xl bg-[#0B1120]/65 border border-amber-500/35 px-3 py-2.5 shadow-lg shadow-amber-950/25 ring-1 ring-[#D4AF37]/10 touch-manipulation ${
                        headerExpanded ? 'rounded-t-2xl rounded-b-none' : 'rounded-2xl'
                    }`}
                    role="button"
                    tabIndex={0}
