} from 'react';
import type { Debtor } from '@/app/types/execution';
import type { DebtorLiabilityGroup } from '@/app/utils/debtorLiabilityGroups';
import type { DebtorWorkspaceEntry as DebtorWorkspaceEntryContract } from '@/app/components/lawyer/ExecutionDashboard/hooks/useDebtorWorkspaceEntries';
import { isCustodyRemovalExecutionClaim } from '@/app/utils/executionClaimIsolation';
import { useApplyPartyEditDisplayOverlay } from '../helpers/partyEditDisplayOverlay';
import { DebtorCardRow } from './DebtorCardRow';
import type {
    DebtorsSectionHandle,
    DebtorsSectionProps,
    ExpandControlRegistrar,
} from './DebtorsSection.types';

export type { DebtorsSectionHandle, DebtorsSectionProps } from './DebtorsSection.types';

export const DebtorsSection = forwardRef<DebtorsSectionHandle, DebtorsSectionProps>(function DebtorsSection(
    props,
    ref,
) {
    const expandControlsRef = useRef(new Map<string, () => void>());
    const applyPartyOverlay = useApplyPartyEditDisplayOverlay();

    const registerExpandControl = useCallback<ExpandControlRegistrar>((debtorKey, expand) => {
        expandControlsRef.current.set(debtorKey, expand);
        return () => {
            expandControlsRef.current.delete(debtorKey);
        };
    }, []);

    useImperativeHandle(
        ref,
        () => ({
            expandDebtor: (debtorKey: string) => {
                expandControlsRef.current.get(debtorKey)?.();
            },
        }),
        [],
    );

    const {
        PartyOverflowToggle,
        liabilityGroupTabsMode = false,
        debtorLiabilityGroups = [],
        debtorBrowserTabsMode,
        debtorWorkspaceChipStripRef,
        debtorWorkspaceEntries,
        executionDebtorTabIndex,
        multiDebtorMode,
        effectiveDebtors,
        showExtraDebtors,
        setExecutionDebtorTabIndex,
        setShowExtraDebtors,
        onOpenUnifiedSummonsHub,
        setSummonsContextDebtorKey,
        setSummonsHubInitialMainTab,
        setShowUnifiedSummonsModal,
        executionData,
        claimType,
        activeDebtorHeirsForNotification,
        activeTimelineEvents,
        activeTimelineEventsDebtorScoped,
        realEstateSeizureAssets,
        seizedAssets,
        standaloneExecutionMarks,
        thirdPartySeizureAssets,
        thirdPartySeizures,
    } = props;

    const resolvedOnOpenUnifiedSummonsHub = useCallback(
        (options?: {
            debtorKey?: string | null;
            initialMainTab?: 'tabligh' | 'taklif' | 'nashr' | 'guarantor' | null;
        }) => {
            if (onOpenUnifiedSummonsHub) {
                onOpenUnifiedSummonsHub(options);
                return;
            }
            setSummonsContextDebtorKey?.(options?.debtorKey ?? null);
            setSummonsHubInitialMainTab?.(options?.initialMainTab ?? null);
            setShowUnifiedSummonsModal?.(true);
        },
        [
            onOpenUnifiedSummonsHub,
            setSummonsContextDebtorKey,
            setSummonsHubInitialMainTab,
            setShowUnifiedSummonsModal,
        ],
    );

    const custodyRemovalClaimActive = useMemo(
        () => isCustodyRemovalExecutionClaim(executionData, claimType),
        [executionData, claimType],
    );

    const activeLiabilityGroupEntries = useMemo((): DebtorWorkspaceEntryContract[] => {
        if (!liabilityGroupTabsMode || debtorLiabilityGroups.length === 0) return [];
        return (
            debtorLiabilityGroups[executionDebtorTabIndex]?.entries ??
            debtorLiabilityGroups[0]?.entries ??
            []
        );
    }, [liabilityGroupTabsMode, debtorLiabilityGroups, executionDebtorTabIndex]);

    const debtorRowsToRender = useMemo((): Array<DebtorWorkspaceEntryContract | Debtor> => {
        if (liabilityGroupTabsMode) {
            return activeLiabilityGroupEntries;
        }
        if (debtorBrowserTabsMode) {
            return debtorWorkspaceEntries.slice(
                executionDebtorTabIndex,
                executionDebtorTabIndex + 1,
            );
        }
        if (multiDebtorMode) {
            return debtorWorkspaceEntries;
        }
        return effectiveDebtors;
    }, [
        liabilityGroupTabsMode,
        activeLiabilityGroupEntries,
        debtorBrowserTabsMode,
        debtorWorkspaceEntries,
        executionDebtorTabIndex,
        multiDebtorMode,
        effectiveDebtors,
    ]);

    const safeActiveDebtorHeirsForNotification = Array.isArray(activeDebtorHeirsForNotification)
        ? activeDebtorHeirsForNotification
        : [];
    const safeActiveTimelineEvents = Array.isArray(activeTimelineEvents) ? activeTimelineEvents : [];
    const safeActiveTimelineEventsDebtorScoped = Array.isArray(activeTimelineEventsDebtorScoped)
        ? activeTimelineEventsDebtorScoped
        : [];
    const safeDebtorWorkspaceEntries = Array.isArray(debtorWorkspaceEntries)
        ? debtorWorkspaceEntries
        : [];
    const safeEffectiveDebtors = Array.isArray(effectiveDebtors) ? effectiveDebtors : [];
    const safeRealEstateSeizureAssets = Array.isArray(realEstateSeizureAssets)
        ? realEstateSeizureAssets
        : [];
    const safeSeizedAssets = Array.isArray(seizedAssets) ? seizedAssets : [];
    const safeStandaloneExecutionMarks = Array.isArray(standaloneExecutionMarks)
        ? standaloneExecutionMarks
        : [];
    const safeThirdPartySeizureAssets = Array.isArray(thirdPartySeizureAssets)
        ? thirdPartySeizureAssets
        : [];
    const safeThirdPartySeizures = Array.isArray(thirdPartySeizures) ? thirdPartySeizures : [];

    return (
        <>
            <div className="mx-3 mt-3.5 space-y-1.5">
                <div className="space-y-1.5">
                    {debtorBrowserTabsMode &&
                    (liabilityGroupTabsMode
                        ? debtorLiabilityGroups.length > 0
                        : debtorWorkspaceEntries.length > 0) ? (
                        <div
                            ref={debtorWorkspaceChipStripRef}
                            className="scrollbar-hide flex gap-1 overflow-x-auto rounded-xl border border-rose-500/25 bg-slate-950/40 p-1.5"
                            dir="rtl"
                        >
                            {(liabilityGroupTabsMode
                                ? debtorLiabilityGroups
                                : debtorWorkspaceEntries
                            ).map((item, ti) => (
                                <button
                                    key={
                                        liabilityGroupTabsMode
                                            ? (item as DebtorLiabilityGroup).tabKey
                                            : (item as DebtorWorkspaceEntryContract).key
                                    }
                                    type="button"
                                    onClick={() => setExecutionDebtorTabIndex(ti)}
                                    className={`shrink-0 rounded-lg border px-3 py-2 text-[10px] font-bold transition-all ${
                                        executionDebtorTabIndex === ti
                                            ? 'border-rose-500/50 bg-rose-950/45 text-rose-50'
                                            : 'border-transparent bg-slate-800/60 text-slate-400 hover:border-rose-500/25'
                                    }`}
                                >
                                    {liabilityGroupTabsMode
                                        ? (item as DebtorLiabilityGroup).label
                                        : (item as DebtorWorkspaceEntryContract).unified.name}
                                </button>
                            ))}
                        </div>
                    ) : null}
                    {debtorRowsToRender.map((raw, loopIdx) => (
                        <DebtorCardRow
                            key={
                                multiDebtorMode || debtorBrowserTabsMode
                                    ? (raw as DebtorWorkspaceEntryContract).key ??
                                      `debtor-row-${loopIdx}`
                                    : `debtor-row-${loopIdx}`
                            }
                            {...props}
                            onOpenUnifiedSummonsHub={resolvedOnOpenUnifiedSummonsHub}
                            raw={raw}
                            loopIdx={loopIdx}
                            registerExpandControl={registerExpandControl}
                            applyPartyOverlay={applyPartyOverlay}
                            custodyRemovalClaimActive={custodyRemovalClaimActive}
                            safeActiveDebtorHeirsForNotification={safeActiveDebtorHeirsForNotification}
                            safeActiveTimelineEvents={safeActiveTimelineEvents}
                            safeActiveTimelineEventsDebtorScoped={safeActiveTimelineEventsDebtorScoped}
                            safeDebtorWorkspaceEntries={safeDebtorWorkspaceEntries}
                            safeEffectiveDebtors={safeEffectiveDebtors}
                            safeRealEstateSeizureAssets={safeRealEstateSeizureAssets}
                            safeSeizedAssets={safeSeizedAssets}
                            safeStandaloneExecutionMarks={safeStandaloneExecutionMarks}
                            safeThirdPartySeizureAssets={safeThirdPartySeizureAssets}
                            safeThirdPartySeizures={safeThirdPartySeizures}
                        />
                    ))}
                    {!multiDebtorMode && effectiveDebtors.length > 2 && (
                        <PartyOverflowToggle
                            hiddenCount={effectiveDebtors.length - 2}
                            expanded={showExtraDebtors}
                            onToggle={() => setShowExtraDebtors((v) => !v)}
                            variant="debtor"
                        />
                    )}
                </div>
            </div>
        </>
    );
});

import React, { useMemo, useState, useCallback, useEffect } from 'react';
import {
    Building2,
    Target,
    AlertCircle,
    FileInput,
    Send,
} from 'lucide-react';
import { storageCache } from '@/app/utils/storageCache';
import { EXECUTION_FILES_STORAGE_KEY } from '@/app/utils/executionFilesStorage';
import { purgeExpiredExecutionsFromTrash, isExecutionInTrash } from '@/app/utils/executionTrash';
import type { ExecutionFile } from '@/app/types/execution';
import type { DossierActionPayload, DossierActionType } from './DossierActionsModal';

export function useDossierActionForm(
    actionType: DossierActionType,
    active: boolean,
    currentFileId?: string,
    inabaTargets?: { id: string; directorate: string }[]
) {
    const [delegationTargetDirectorate, setDelegationTargetDirectorate] = useState('');
    const [delegationPurpose, setDelegationPurpose] = useState('');
    const [selectedOwnId, setSelectedOwnId] = useState('');
    const [transferTargetDirectorate, setTransferTargetDirectorate] = useState('');
    const [renewalReason, setRenewalReason] = useState('');
    const [inabaSubFileId, setInabaSubFileId] = useState('');
    const [inabaSubject, setInabaSubject] = useState('');

    const resetFields = useCallback(() => {
        setDelegationTargetDirectorate('');
        setDelegationPurpose('');
        setSelectedOwnId('');
        setTransferTargetDirectorate('');
        setRenewalReason('');
        setInabaSubFileId('');
        setInabaSubject('');
    }, []);

    useEffect(() => {
        if (!active) resetFields();
    }, [active, actionType, resetFields]);

    const today = new Date().toISOString().slice(0, 10);
    const availableDossiers = useMemo(() => {
        if (!active || actionType !== 'unify') return [] as ExecutionFile[];
        try {
            const cached = storageCache.get(EXECUTION_FILES_STORAGE_KEY);
            const allFiles: ExecutionFile[] = Array.isArray(cached) ? (cached as ExecutionFile[]) : [];
            const cleanFiles = purgeExpiredExecutionsFromTrash(allFiles);
            const currentId = String(currentFileId || '').trim();
            const seen = new Set<string>();
            return cleanFiles.filter((d) => {
                const id = String(d?.id || '').trim();
                if (!id) return false;
                if (seen.has(id)) return false;
                seen.add(id);
                if (currentId && id === currentId) return false;
                if (isExecutionInTrash(d as any)) return false;
                const isActive = d.dossier_lifecycle_status === 'active' || !d.dossier_lifecycle_status;
                if (!isActive) return false;
                const hasValidNumber = d.fileNumber && String(d.fileNumber).trim().length > 0;
                if (!hasValidNumber) return false;
                const notAlreadyChild = !(d as any).parentId;
                if (!notAlreadyChild) return false;
                return true;
            });
        } catch {
            return [] as ExecutionFile[];
        }
    }, [active, actionType, currentFileId]);

    const buildPayload = useCallback((): DossierActionPayload => {
        const payload: DossierActionPayload = { actionType };
        if (actionType === 'delegation') {
            payload.delegationTargetDirectorate = delegationTargetDirectorate.trim();
            payload.delegationPurpose = delegationPurpose.trim();
        } else if (actionType === 'unify') {
            payload.unificationTargetType = 'own';
            payload.unificationTargetId = selectedOwnId.trim();
            const selected = availableDossiers.find((d) => String(d.id) === String(selectedOwnId));
            payload.unificationTargetMeta = {
                directorate: (selected?.directorate as string) || undefined,
                fileNumber: selected?.fileNumber || undefined,
                fileYear: (selected as any)?.fileYear || undefined,
            };
        } else if (actionType === 'transfer') {
            payload.transferTargetDirectorate = transferTargetDirectorate.trim();
        } else if (actionType === 'renew') {
            payload.renewalReason = renewalReason.trim();
        } else if (actionType === 'inaba_correspondence') {
            const targets = Array.isArray(inabaTargets) ? inabaTargets : [];
            const selectedId = String(inabaSubFileId || '').trim() || String(targets[0]?.id || '').trim();
            const selected = targets.find((t) => String(t.id) === selectedId) || targets[0];
            payload.inabaCorrespondenceSubFileId = selectedId;
            payload.inabaCorrespondenceDirectorate = String(selected?.directorate || '').trim();
            payload.inabaCorrespondenceSubject = inabaSubject.trim();
        }
        return payload;
    }, [
        actionType,
        delegationTargetDirectorate,
        delegationPurpose,
        selectedOwnId,
        transferTargetDirectorate,
        renewalReason,
        inabaSubFileId,
        inabaSubject,
        availableDossiers,
        inabaTargets,
    ]);

    const isConfirmDisabled = useMemo(() => {
        if (actionType === 'delegation') {
            return !delegationTargetDirectorate.trim() || !delegationPurpose.trim();
        }
        if (actionType === 'unify') return !selectedOwnId.trim();
        if (actionType === 'transfer') return !transferTargetDirectorate.trim();
        if (actionType === 'renew') return !renewalReason.trim();
        if (actionType === 'inaba_correspondence') {
            const targets = Array.isArray(inabaTargets) ? inabaTargets : [];
            const selectedId = String(inabaSubFileId || '').trim() || String(targets[0]?.id || '').trim();
            return !selectedId || !inabaSubject.trim();
        }
        return false;
    }, [
        actionType,
        delegationTargetDirectorate,
        delegationPurpose,
        selectedOwnId,
        transferTargetDirectorate,
        renewalReason,
        inabaSubFileId,
        inabaSubject,
        inabaTargets,
    ]);

    return {
        today,
        availableDossiers,
        resetFields,
        buildPayload,
        isConfirmDisabled,
        delegationTargetDirectorate,
        setDelegationTargetDirectorate,
        delegationPurpose,
        setDelegationPurpose,
        selectedOwnId,
        setSelectedOwnId,
        transferTargetDirectorate,
        setTransferTargetDirectorate,
        renewalReason,
        setRenewalReason,
        inabaSubFileId,
        setInabaSubFileId,
        inabaSubject,
        setInabaSubject,
    };
}

export type DossierActionFormFieldsProps = {
    actionType: DossierActionType;
    form: ReturnType<typeof useDossierActionForm>;
    inabaTargets?: { id: string; directorate: string }[];
};

export const DossierActionFormFields: React.FC<DossierActionFormFieldsProps> = ({
    actionType,
    form,
    inabaTargets,
}) => {
    const {
        today,
        availableDossiers,
        delegationTargetDirectorate,
        setDelegationTargetDirectorate,
        delegationPurpose,
        setDelegationPurpose,
        selectedOwnId,
        setSelectedOwnId,
        transferTargetDirectorate,
        setTransferTargetDirectorate,
        renewalReason,
        setRenewalReason,
        inabaSubFileId,
        setInabaSubFileId,
        inabaSubject,
        setInabaSubject,
    } = form;

    return (
        <div className="space-y-3 text-right" dir="rtl">
            {actionType !== 'unify' ? (
                <div>
                    <label className="mb-1 block text-[9px] text-slate-400">تاريخ الطلب</label>
                    <input
                        type="date"
                        value={today}
                        readOnly
                        className="w-full cursor-default rounded-xl border border-white/10 bg-black/30 p-3 text-[11px] text-white"
                    />
                </div>
            ) : null}

            {actionType === 'delegation' ? (
                <>
                    <div>
                        <label className="mb-1.5 flex items-center gap-1.5 text-[10px] font-bold text-slate-400">
                            <Building2 size={13} className="text-amber-400" />
                            الدائرة المناب إليها
                        </label>
                        <input
                            type="text"
                            value={delegationTargetDirectorate}
                            onChange={(e) => setDelegationTargetDirectorate(e.target.value)}
                            placeholder="أدخل اسم الدائرة / المحكمة المناب إليها..."
                            className="w-full rounded-xl border border-white/10 bg-black/30 p-3 text-[11px] text-white placeholder:text-white/20 focus:border-amber-500/50 focus:outline-none"
                        />
                    </div>
                    <div>
                        <label className="mb-1.5 flex items-center gap-1.5 text-[10px] font-bold text-slate-400">
                            <Target size={13} className="text-amber-400" />
                            الغاية من الإنابة
                        </label>
                        <textarea
                            value={delegationPurpose}
                            onChange={(e) => setDelegationPurpose(e.target.value)}
                            placeholder="صف الغاية من الإنابة التنفيذية..."
                            rows={3}
                            className="w-full resize-none rounded-xl border border-white/10 bg-black/30 p-3 text-[11px] text-white placeholder:text-white/20 focus:border-amber-500/50 focus:outline-none"
                        />
                    </div>
                </>
            ) : null}

            {actionType === 'unify' ? (
                <div>
                    <label className="mb-1.5 flex items-center gap-1.5 text-[10px] font-bold text-slate-400">
                        <FileInput size={13} className="text-amber-400" />
                        الإضبارة المراد دمجها
                    </label>
                    <p className="mb-2 text-[10px] text-slate-400">
                        اختيار إضبارة من مخزنك لتصبح فرعية بعد موافقة المنفذ
                    </p>
                    <select
                        value={selectedOwnId}
                        onChange={(e) => setSelectedOwnId(e.target.value)}
                        className="w-full rounded-xl border border-white/10 bg-black/30 px-3 py-2.5 text-[11px] text-white outline-none focus:border-amber-500/50"
                    >
                        <option value="">-- اختر إضبارة --</option>
                        {availableDossiers.length > 0 ? (
                            availableDossiers.map((dossier: ExecutionFile) => (
                                <option key={dossier.id} value={dossier.id}>
                                    {dossier.fileNumber || '---'} / {(dossier as any).fileYear || '---'} —{' '}
                                    {String(dossier.directorate || '').trim() || '---'}
                                </option>
                            ))
                        ) : (
                            <option disabled value="">
                                لا توجد أضابير قابلة للدمج
                            </option>
                        )}
                    </select>
                </div>
            ) : null}

            {actionType === 'transfer' ? (
                <div>
                    <label className="mb-1.5 flex items-center gap-1.5 text-[10px] font-bold text-slate-400">
                        <Building2 size={13} className="text-amber-400" />
                        الدائرة المراد النقل إليها
                    </label>
                    <input
                        type="text"
                        value={transferTargetDirectorate}
                        onChange={(e) => setTransferTargetDirectorate(e.target.value)}
                        placeholder="أدخل اسم الدائرة..."
                        className="w-full rounded-xl border border-white/10 bg-black/30 p-3 text-[11px] text-white placeholder:text-white/20 focus:border-amber-500/50 focus:outline-none"
                    />
                </div>
            ) : null}

            {actionType === 'renew' ? (
                <div>
                    <label className="mb-1.5 flex items-center gap-1.5 text-[10px] font-bold text-slate-400">
                        <AlertCircle size={13} className="text-amber-400" />
                        سبب التجديد
                    </label>
                    <textarea
                        value={renewalReason}
                        onChange={(e) => setRenewalReason(e.target.value)}
                        placeholder="اذكر سبب طلب تجديد الإضبارة..."
                        rows={3}
                        className="w-full resize-none rounded-xl border border-white/10 bg-black/30 p-3 text-[11px] text-white placeholder:text-white/20 focus:border-amber-500/50 focus:outline-none"
                    />
                </div>
            ) : null}

            {actionType === 'inaba_correspondence' ? (
                <>
                    <div>
                        <label className="mb-1.5 flex items-center gap-1.5 text-[10px] font-bold text-slate-400">
                            <Building2 size={13} className="text-amber-400" />
                            مديرية الإنابة المراد مخاطبتها
                        </label>
                        {Array.isArray(inabaTargets) && inabaTargets.length > 1 ? (
                            <select
                                value={inabaSubFileId}
                                onChange={(e) => setInabaSubFileId(e.target.value)}
                                className="w-full rounded-xl border border-white/10 bg-black/30 px-3 py-2.5 text-[11px] text-white outline-none focus:border-amber-500/50"
                            >
                                <option value="">-- اختر مديرية الإنابة --</option>
                                {inabaTargets.map((t) => (
                                    <option key={t.id} value={t.id}>
                                        {t.directorate || '---'}
                                    </option>
                                ))}
                            </select>
                        ) : (
                            <input
                                type="text"
                                readOnly
                                value={String(inabaTargets?.[0]?.directorate || '').trim() || '—'}
                                className="w-full cursor-default rounded-xl border border-white/10 bg-black/30 p-3 text-[11px] text-white"
                            />
                        )}
                    </div>
                    <div>
                        <label className="mb-1.5 flex items-center gap-1.5 text-[10px] font-bold text-slate-400">
                            <Target size={13} className="text-amber-400" />
                            موضوع المخاطبة
                        </label>
                        <textarea
                            value={inabaSubject}
                            onChange={(e) => setInabaSubject(e.target.value)}
                            placeholder="مثال: طلب تحويل أموال / طلب إجراء معين..."
                            rows={3}
                            className="w-full resize-none rounded-xl border border-white/10 bg-black/30 p-3 text-[11px] text-white placeholder:text-white/20 focus:border-amber-500/50 focus:outline-none"
                        />
                    </div>
                </>
            ) : null}
        </div>
    );
};

export type DossierActionFormFooterProps = {
    saving?: boolean;
    disabled: boolean;
    onCancel: () => void;
    onConfirm: () => void;
};

export const DossierActionFormFooter: React.FC<DossierActionFormFooterProps> = ({
