        setTaskDueDate,
        setTaskStatus,
    ]);
    const closeAppointmentModal = useCallback(() => {
        onCloseAppointmentModal();
        setEditingAppointmentId(null);
        setAppointmentPurpose('');
        setAppointmentDateOnly('');
        setAppointmentTimeOptional('');
