                                        renderNoteExtra={(n) => {
                                            const isInventoryNote =
                                                String(n.title || '').trim() ===
                                                'جرد الأثاث — كسر الأقفال والجرد';
                                            if (!isInventoryNote) return null;
                                            const hit = findApprovedBreakInventoryNeedingLedger(
                                                decisionsStorageExecutionId
