                                            if (!hit) return null;
                                            return (
                                                <button
                                                    type="button"
                                                    onClick={() => {
                                                        const ts = new Date().toISOString();
                                                        patchExecutorDecisionRow(
                                                            decisionsStorageExecutionId,
