                                                size={14}
                                                className="text-slate-400 transition-transform group-open:rotate-180"
                                                aria-hidden
                                            />
                                        </span>
                                    </summary>
                                    {items.length ? renderList(items, allowEdit) : renderEmpty(emptyLabel)}
                                </details>
                            );

                            return (
                                <div className="mt-4" dir="rtl">
                                    {renderAccordion(
                                        'سجل المواعيد النشطة',
