                                                : deductionLabel
                                        }
                                    >
                                        {deductionLabel}
                                    </div>
                                </div>
                            </>
                        ) : null}
                    </div>
                    <button
                        type="button"
                        onClick={() => {
                            onOpenUnifiedSummonsHub?.({
                                debtorKey: null,
                                initialMainTab: 'guarantor',
