import React from 'react';
import type { ExecutionFile } from '@/app/types/execution';
import {
    isExecutorRowRejectedAndFinal,
    patchExecutorDecisionRowEverywhere,
    readExecutorDecisionsArray,
} from '@/app/utils/executorSeizureDecisionQueue';
import { isExecutorRowApprovedWorkflowActive } from '@/app/utils/executorRequestAppealSync';
import {
    ExecutionInlineAccordion,
    ExecutionInlineExecutorDecisionActions,
    type ExecutionInlineStep,
} from '@/app/components/lawyer/ExecutionDashboard/components/ExecutionInlineAccordion';

export type GuarantorWorkspaceWrapperProps = {
    executionId: string;
    row: Record<string, unknown>;
    guarantorFollowup: ExecutionFile['guarantor_followup'] | null | undefined;
    persistGuarantorFollowupDetails: (
        guarantorName: string,
        guarantorWorkplace: string,
        opts?: {
            salaryIqd: number | null;
            deductionIqd: number | null;
        }
    ) => void;
    disabled?: boolean;
    onOpenAppeals: (decisionId?: string) => void;
    onOpenDecisions: (decisionId?: string) => void;
    onOpenGuarantorDetails: (decisionId?: string) => void;
    requestTitle?: string;
};

export const GuarantorWorkspaceWrapper: React.FC<GuarantorWorkspaceWrapperProps> = ({
    executionId,
    row,
    persistGuarantorFollowupDetails,
    disabled,
    onOpenAppeals,
    onOpenDecisions,
    requestTitle = 'طلب كفيل ضامن',
}) => {
    const allDecisions = React.useMemo(
        () => readExecutorDecisionsArray(executionId) as Record<string, unknown>[],
        [executionId, row]
    );
    const decisionId = String(row?.id || '').trim();
    const rejected = Boolean(decisionId) && isExecutorRowRejectedAndFinal(row);
    const outcome = String(row?.executorOutcome ?? 'pending').trim();
    const alternative = outcome === 'alternative';
    const approved =
        Boolean(decisionId) &&
        !rejected &&
        (alternative || isExecutorRowApprovedWorkflowActive(row, allDecisions));
    const detailsSaved = Boolean(String(row?.guarantorDetailsSavedAt || '').trim());
    const needsCompletion = approved && !detailsSaved;
    const vanish = approved && detailsSaved;

    const [expanded, setExpanded] = React.useState(false);
    const prevNeedsCompletionRef = React.useRef<boolean>(false);
    React.useEffect(() => {
        const prev = prevNeedsCompletionRef.current;
        prevNeedsCompletionRef.current = needsCompletion;
        if (needsCompletion && !prev) setExpanded(true);
        if (!needsCompletion) setExpanded(false);
    }, [needsCompletion]);

    const [name, setName] = React.useState<string>('');
    const [workplace, setWorkplace] = React.useState<string>('');
    const [salary, setSalary] = React.useState<string>('');
    const [deduction, setDeduction] = React.useState<string>('');

    React.useEffect(() => {
        if (!needsCompletion) return;
        setName('');
        setWorkplace('');
        setSalary('');
        setDeduction('');
    }, [decisionId, needsCompletion]);

    const parseIqd = (s: string): number | null => {
        const t = String(s).replace(/,/g, '').replace(/\s/g, '').trim();
        if (!t) return null;
        const x = Number(t);
        return Number.isFinite(x) ? x : null;
    };

    const canSave =
        Boolean(String(name || '').trim()) && Boolean(String(workplace || '').trim()) && !disabled;

    if (!decisionId) return null;
    if (vanish) return null;

    if (rejected) {
        return (
            <div className="mt-2 rounded-2xl border p-3 border-rose-500/35 bg-rose-950/25">
                <p className="text-[11px] font-black text-right text-rose-200">قرار المنفذ</p>
                <p className="mt-1 text-[10px] text-slate-400 text-right">تم رفض الطلب</p>
                <div className="mt-3 border-t border-white/10 pt-3">
                    <button
                        type="button"
                        onClick={() => onOpenAppeals(decisionId)}
                        className="w-full rounded-xl border border-amber-500/35 bg-amber-500/10 px-3 py-2 text-[11px] font-extrabold text-amber-200 hover:bg-amber-500/15"
                    >
                        تقديم طعن (الذهاب لمركز القرارات)
                    </button>
                </div>
            </div>
        );
    }

    const pending = !approved && !rejected;

    if (pending) {
        return (
            <div className="mt-2 rounded-2xl border border-white/10 bg-black/15 p-3">
                <p className="text-[11px] font-black text-right text-slate-200">قرار المنفذ</p>
                <p className="mt-1 text-[10px] text-slate-400 text-right">قيد البت</p>
                <div className="mt-3 border-t border-white/10 pt-3">
                    <ExecutionInlineExecutorDecisionActions
                        executionId={executionId}
                        decisionId={decisionId}
                        requestKind="guarantor_request"
                    />
                </div>
            </div>
        );
    }

    if (!needsCompletion) return null;

    const steps: ExecutionInlineStep[] = [
        {
            id: `${decisionId}:sent`,
            title: requestTitle,
            subtitle: 'تم إرسال الطلب',
            status: 'done',
            tone: 'success',
        },
        {
            id: `${decisionId}:executor`,
            title: 'قرار المنفذ',
            subtitle: alternative ? 'قرار بديل — أكمل بيانات الكفيل' : 'تمت الموافقة',
            status: 'done',
            tone: 'success',
        },
        {
            id: `${decisionId}:complete`,
            title: 'إكمال بيانات الكفيل',
            subtitle: 'أكمل البيانات ثم احفظ',
            status: 'active',
            tone: 'neutral',
            content: (
                <div className="space-y-2">
                    <div className="grid grid-cols-1 gap-3">
                        <div>
                            <label className="mb-1 block text-[11px] font-bold text-slate-300">اسم الكفيل</label>
                            <input
                                type="text"
                                disabled={disabled}
                                value={name}
                                onChange={(e) => setName(e.target.value)}
                                className="w-full rounded-xl border border-white/10 bg-white/5 px-3 py-2 text-[12px] text-slate-100 text-right"
                                placeholder="اسم الكفيل"
                            />
                        </div>

                        <div>
                            <label className="mb-1 block text-[11px] font-bold text-slate-300">مكان العمل</label>
                            <input
                                type="text"
                                disabled={disabled}
                                value={workplace}
                                onChange={(e) => setWorkplace(e.target.value)}
                                className="w-full rounded-xl border border-white/10 bg-white/5 px-3 py-2 text-[12px] text-slate-100 text-right"
                                placeholder="مكان العمل"
                            />
                        </div>

                        <div className="grid grid-cols-1 gap-2 sm:grid-cols-2">
                            <div>
                                <label className="mb-1 block text-[11px] font-bold text-slate-300">
                                    الراتب (اختياري)
                                </label>
                                <input
                                    type="text"
                                    inputMode="numeric"
                                    disabled={disabled}
                                    value={salary}
                                    onChange={(e) => setSalary(e.target.value)}
                                    className="w-full rounded-xl border border-white/10 bg-white/5 px-3 py-2 text-[12px] text-slate-100 text-right"
                                    placeholder="0"
                                />
                            </div>
                            <div>
                                <label className="mb-1 block text-[11px] font-bold text-slate-300">
                                    الاستقطاع (اختياري)
                                </label>
                                <input
                                    type="text"
                                    inputMode="numeric"
                                    disabled={disabled}
                                    value={deduction}
                                    onChange={(e) => setDeduction(e.target.value)}
                                    className="w-full rounded-xl border border-white/10 bg-white/5 px-3 py-2 text-[12px] text-slate-100 text-right"
                                    placeholder="0"
                                />
                            </div>
                        </div>
                    </div>

                    <button
                        type="button"
                        disabled={!canSave}
                        onClick={() => {
                            persistGuarantorFollowupDetails(String(name || ''), String(workplace || ''), {
                                salaryIqd: parseIqd(salary),
                                deductionIqd: parseIqd(deduction),
                            });
                            const ts = new Date().toISOString();
                            patchExecutorDecisionRowEverywhere(decisionId, { guarantorDetailsSavedAt: ts });
                        }}
                        className="w-full rounded-xl bg-gradient-to-l from-indigo-500 to-violet-700 px-5 py-2.5 text-[12px] font-black text-white shadow-md shadow-black/20 disabled:opacity-40"
                    >
                        حفظ بيانات الكفيل
                    </button>

                    <button
                        type="button"
                        onClick={() => onOpenDecisions(decisionId)}
                        className="w-full rounded-xl border border-white/10 bg-white/5 py-2.5 text-[11px] font-bold text-slate-200 hover:bg-white/10"
                    >
                        فتح مركز القرارات
                    </button>
                </div>
            ),
        },
    ];

    return (
        <div className="mt-2">
            <button
                type="button"
                aria-expanded={expanded}
                onClick={() => setExpanded((v) => !v)}
                className="flex w-full items-center justify-center gap-2 rounded-xl border border-white/10 bg-black/10 py-2 text-[11px] font-bold text-slate-200 transition hover:bg-black/20"
            >
                <span className="text-[#D4AF37]/85">{expanded ? 'تصغير' : 'توسيع'}</span>
            </button>
            {expanded ? (
                <div className="mt-2">
                    <ExecutionInlineAccordion steps={steps} />
                </div>
            ) : null}
        </div>
    );
};

import React from 'react';
import { Hammer, Send } from 'lucide-react';
import { InlineActionGate } from './InlineActionGate';
import {
    ExecutionInlineAccordion,
    ExecutionInlineExecutorDecisionActions,
    type ExecutionInlineStep,
} from '@/app/components/lawyer/ExecutionDashboard/components/ExecutionInlineAccordion';
import {
    appendEvictionExecutorRequest,
    dispatchDecisionsReload,
    isExecutorRowRejectedAndFinal,
    patchExecutorDecisionRow,
} from '@/app/utils/executorSeizureDecisionQueue';
import { isExecutorRowApprovedWorkflowActive } from '@/app/utils/executorRequestAppealSync';
import {
    HIDDEN_BREAK_INVENTORY_REQUEST_BODY,
    HIDDEN_BREAK_INVENTORY_REQUEST_TITLE,
    resolveHiddenBreakInventoryRequest,
    type HiddenFollowupVisibilityInput,
} from './hiddenFollowupRequestsUtils';

export interface HiddenBreakInventoryRequestOptionsProps {
    executionId: string;
    flags: HiddenFollowupVisibilityInput;
    decisions: Record<string, unknown>[];
    coerciveUiLocked: boolean;
    isHistoricalMode: boolean;
    /** داخل قائمة موحّدة — بدون عناوين مكررة */
    embedded?: boolean;
    showToast: (
        message: string,
        type?: 'success' | 'error' | 'warning' | 'info',
        opts?: { decisionsLink?: boolean; decisionId?: string; decisionsTab?: 'current' | 'previous' | 'appeals' }
    ) => void;
    onOpenDecisions: (opts?: {
        tab?: 'current' | 'previous' | 'appeals';
        decisionId?: string | null;
    }) => void;
}

export const HiddenBreakInventoryRequestOptions: React.FC<HiddenBreakInventoryRequestOptionsProps> = ({
    executionId,
    flags,
    decisions,
    coerciveUiLocked,
    isHistoricalMode,
    embedded = false,
    showToast,
    onOpenDecisions,
}) => {
    const exId = String(executionId || '').trim();
    const [inlineGateKey, setInlineGateKey] = React.useState<'hidden_break_inventory' | null>(null);
    const [submitting, setSubmitting] = React.useState(false);

    const resolved = React.useMemo(
        () => resolveHiddenBreakInventoryRequest(decisions),
        [decisions]
    );

    const submitDisabledReason = React.useMemo(() => {
        if (isHistoricalMode || coerciveUiLocked) return 'الوضع مقفل — لا يمكن إرسال طلب جديد.';
        if (resolved.status === 'pending') return 'يوجد طلب قيد البت لدى المنفذ.';
        if (resolved.resendBlocked && !resolved.workflowComplete) {
            return 'الطلب موافق عليه — أكمل الإجراء من القرارات أولاً.';
        }
        return '';
    }, [coerciveUiLocked, isHistoricalMode, resolved]);

    const runSubmit = React.useCallback(
        (resubmit?: boolean) => {
        if (!exId || isHistoricalMode || coerciveUiLocked) return;
        if (resolved.status === 'pending') return;
        if (resolved.resendBlocked && !resubmit) return;
        setSubmitting(true);
        try {
            const ok = appendEvictionExecutorRequest({
                executionId: exId,
                title: HIDDEN_BREAK_INVENTORY_REQUEST_TITLE,
                body: HIDDEN_BREAK_INVENTORY_REQUEST_BODY,
                requestKind: 'eviction_procedure',
                evictionWorkflowKey: 'break_inventory',
                supersedeCompletedHub: resubmit,
            });
            if (!ok) {
                showToast('يوجد طلب مماثل لدى المنفذ.', 'warning', { decisionsLink: true });
                return;
            }
            dispatchDecisionsReload();
            showToast('تم حفظ الطلب وتحويله إلى مركز القرارات بانتظار موافقة المنفذ.', 'success', {
                decisionsLink: true,
            });
        } finally {
            setSubmitting(false);
            setInlineGateKey(null);
        }
    },
        [coerciveUiLocked, exId, isHistoricalMode, resolved.resendBlocked, resolved.status, showToast]
    );

    const finalizeBreakInventory = React.useCallback(() => {
        const decisionId = String(resolved.row?.id || '').trim();
        if (!decisionId) return;
        const ok = patchExecutorDecisionRow(exId, decisionId, {
            breakInventoryFurnitureFinalizedAt: new Date().toISOString(),
        });
        if (!ok) {
            showToast('تعذر تأكيد الإجراء', 'error');
            return;
        }
        dispatchDecisionsReload();
        showToast('تم تأكيد اكتمال كسر الأقفال.', 'success');
    }, [exId, resolved.row?.id, showToast]);

    const steps: ExecutionInlineStep[] = React.useMemo(() => {
        const row = resolved.row;
        if (!row?.id) return [];
        const decisionId = String(row.id || '').trim();
        const rejected = isExecutorRowRejectedAndFinal(row);
        const pending =
            String(row.executorOutcome ?? 'pending') === 'pending' ||
            String(row.executorOutcome ?? '') === '';
        const approved = isExecutorRowApprovedWorkflowActive(row, decisions) && !rejected;
        const needsFinalize =
            approved &&
            !resolved.workflowComplete &&
            !String((row as { breakInventoryFurnitureFinalizedAt?: string }).breakInventoryFurnitureFinalizedAt || '').trim();

        return [
            {
                id: 'hidden-break:sent',
                title: HIDDEN_BREAK_INVENTORY_REQUEST_TITLE,
                subtitle: 'تم إرسال الطلب',
                status: 'done',
                tone: 'success',
            },
            {
                id: 'hidden-break:executor',
                title: 'قرار المنفذ',
                subtitle: rejected
                    ? 'تم رفض الطلب'
                    : resolved.workflowComplete
                      ? 'تمت الموافقة — اكتمل الإجراء'
                      : approved
                        ? 'تمت الموافقة'
                        : pending
                          ? 'قيد البت'
                          : '—',
                status: rejected || pending ? 'active' : 'done',
                tone: rejected ? 'danger' : approved ? 'success' : 'neutral',
                content: pending ? (
                    <ExecutionInlineExecutorDecisionActions
                        executionId={exId}
                        decisionId={decisionId}
                        requestKind="eviction_procedure"
                    />
                ) : needsFinalize ? (
                    <button
                        type="button"
                        onClick={finalizeBreakInventory}
                        className="w-full rounded-xl border border-emerald-500/35 bg-emerald-500/10 px-3 py-2 text-[11px] font-extrabold text-emerald-200 hover:bg-emerald-500/15"
                    >
                        تأكيد اكتمال كسر الأقفال
                    </button>
                ) : approved ? (
                    <button
                        type="button"
                        onClick={() => onOpenDecisions({ tab: 'previous', decisionId })}
                        className="w-full rounded-xl border border-emerald-500/30 bg-emerald-500/10 py-2 text-[10px] font-bold text-emerald-100 hover:bg-emerald-500/15"
                    >
                        متابعة في القرارات
                    </button>
                ) : undefined,
            },
        ];
    }, [exId, finalizeBreakInventory, onOpenDecisions, resolved.row, resolved.workflowComplete]);

    if (!flags.showHiddenBreakInventoryRequest) return null;

    const panel = (
        <div className="rounded-xl border border-white/10 bg-black/20 p-3 space-y-3">
            {!embedded ? (
                <div className="flex flex-row-reverse items-center gap-3 text-right">
                    <span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-white/5">
                        <Hammer className="h-5 w-5 text-white/70" />
                    </span>
                    <div className="min-w-0 flex-1">
                        <p className="text-[11px] font-bold text-slate-100">
                            {HIDDEN_BREAK_INVENTORY_REQUEST_TITLE}
                        </p>
                        <p className="mt-0.5 text-[9px] text-slate-400">{resolved.statusLabel}</p>
                    </div>
                </div>
            ) : (
                <p className="text-[9px] text-slate-400 text-right">{resolved.statusLabel}</p>
            )}

            {resolved.status !== 'pending' ? (
                <div className="relative">
                    <button
                        type="button"
                        disabled={Boolean(submitDisabledReason) || submitting}
                        onClick={() => {
                            if (submitDisabledReason) {
                                showToast(submitDisabledReason, 'warning');
                                return;
                            }
                            setInlineGateKey('hidden_break_inventory');
                        }}
                        className="flex w-full items-center justify-center gap-2 rounded-xl border border-emerald-500/30 bg-emerald-700/70 py-2.5 text-[11px] font-bold text-white transition-all hover:bg-emerald-700 disabled:cursor-not-allowed disabled:opacity-40"
                    >
                        <Send size={13} />
                        {resolved.workflowComplete ? 'تقديم طلب جديد' : 'إرسال الطلب إلى المنفذ'}
                    </button>
                    {inlineGateKey === 'hidden_break_inventory' ? (
                        <InlineActionGate
                            gateKey="hidden_break_inventory"
                            activeKey={inlineGateKey}
                            mode={resolved.workflowComplete ? 'resubmit_warning' : 'initial'}
                            warningMessage="سبق واتخاذ طلب كسر الأقفال سابقاً. يمكنك تقديم طلب جديد أو التراجع."
                            onConfirm={() => runSubmit(resolved.workflowComplete)}
                            onCancel={() => setInlineGateKey(null)}
                        />
                    ) : null}
                </div>
            ) : null}

            {resolved.row && steps.length > 0 ? <ExecutionInlineAccordion steps={steps} /> : null}
        </div>
    );

    if (embedded) {
        return panel;
    }

    return (
        <div className="space-y-3 border-t border-white/8 pt-3">
            <p className="text-[9px] font-bold text-emerald-300/75">إجراء ميداني مخفي</p>
            {panel}
        </div>
    );
};

