import React from 'react';
import {
    Building2,
    ChevronRight,
    Gavel,
    Hammer,
    Package,
    Plane,
    Scale,
    Shield,
    ShieldAlert,
    UserX,
    Wallet,
} from 'lucide-react';
import { HiddenGuarantorRequestOptions } from './HiddenGuarantorRequestOptions';
import { HiddenBreakInventoryRequestOptions } from './HiddenBreakInventoryRequestOptions';
import { HiddenPersonalCoerciveRequestOptions } from './HiddenPersonalCoerciveRequestOptions';
import {
    hasAnyHiddenFollowupContent,
    listHiddenGuarantorCatalog,
    listHiddenPersonalCoerciveCatalog,
    shouldShowHiddenBreakInventoryRequest,
    type HiddenFollowupVisibilityInput,
    type HiddenGuarantorContext,
    type HiddenGuarantorRequestKey,
    type HiddenPersonalCoerciveRequestKey,
} from './hiddenFollowupRequestsUtils';
import type { HiddenGuarantorRequestOptionsProps } from './HiddenGuarantorRequestOptions';
import type { HiddenPersonalCoerciveRequestOptionsProps } from './HiddenPersonalCoerciveRequestOptions';
import type { ExecutionDomainContext } from '@/app/utils/executionDomainIsolation';

export interface HiddenFollowupRequestOptionsProps {
    executionId: string;
    breakDecisions: Record<string, unknown>[];
    domainContext?: ExecutionDomainContext | null;
    flags: HiddenFollowupVisibilityInput;
    personal: Omit<
        HiddenPersonalCoerciveRequestOptionsProps,
        'flags' | 'embeddedSelectedKey' | 'executionId' | 'decisions'
    >;
    guarantor: Omit<
        HiddenGuarantorRequestOptionsProps,
        'flags' | 'guarantorCtx' | 'embeddedSelectedKey' | 'executionId'
    >;
    guarantorCtx: HiddenGuarantorContext;
}

type HiddenSelection =
    | { type: 'break' }
    | { type: 'personal'; key: HiddenPersonalCoerciveRequestKey }
    | { type: 'guarantor'; key: HiddenGuarantorRequestKey };

const PERSONAL_ICONS: Record<
    HiddenPersonalCoerciveRequestKey,
    React.ComponentType<{ size?: number; className?: string }>
> = {
    forced_bring_in: UserX,
    travel_ban: Plane,
    arrest_warrant_investigation: ShieldAlert,
    executive_dossier_presentation: Scale,
    executive_detention_judge: Gavel,
};

const GUARANTOR_ICONS: Record<
    HiddenGuarantorRequestKey,
    React.ComponentType<{ size?: number; className?: string }>
> = {
    guarantor_request: Shield,
    guarantor_seizure_salary: Wallet,
    guarantor_seizure_property: Building2,
    guarantor_seizure_movable: Package,
};

function selectionMatches(a: HiddenSelection, b: HiddenSelection): boolean {
    if (a.type !== b.type) return false;
    if (a.type === 'break') return true;
    if (a.type === 'personal' && b.type === 'personal') return a.key === b.key;
    if (a.type === 'guarantor' && b.type === 'guarantor') return a.key === b.key;
    return false;
}

export const HiddenFollowupRequestOptions: React.FC<HiddenFollowupRequestOptionsProps> = ({
    executionId: executionIdProp,
    breakDecisions,
    domainContext = null,
    flags,
    personal,
    guarantor,
    guarantorCtx,
}) => {
    const [selection, setSelection] = React.useState<HiddenSelection | null>(null);

    const personalCatalog = React.useMemo(
        () => listHiddenPersonalCoerciveCatalog(flags, domainContext),
        [flags, domainContext]
    );
    const guarantorCatalog = React.useMemo(
        () => listHiddenGuarantorCatalog(flags, guarantorCtx, domainContext),
        [flags, guarantorCtx, domainContext]
    );
    const showBreak = shouldShowHiddenBreakInventoryRequest(flags, domainContext);

    const pickerButtons = React.useMemo(() => {
        const items: Array<{
            id: string;
            label: string;
            Icon: React.ComponentType<{ size?: number; className?: string }>;
            selection: HiddenSelection;
        }> = [];

        if (showBreak) {
            items.push({
                id: 'break',
                label: 'كسر الأقفال',
                Icon: Hammer,
                selection: { type: 'break' },
            });
        }
        for (const item of personalCatalog) {
            items.push({
                id: `pc-${item.key}`,
                label: item.shortLabel,
                Icon: PERSONAL_ICONS[item.key],
                selection: { type: 'personal', key: item.key },
            });
        }
        for (const item of guarantorCatalog) {
            items.push({
                id: `gu-${item.key}`,
                label: item.shortLabel,
                Icon: GUARANTOR_ICONS[item.key],
                selection: { type: 'guarantor', key: item.key },
            });
        }
        return items;
    }, [guarantorCatalog, personalCatalog, showBreak]);

    const activeButton = React.useMemo(
        () =>
            selection
                ? pickerButtons.find((btn) => selectionMatches(btn.selection, selection))
                : null,
        [pickerButtons, selection]
    );

    const hasContent = hasAnyHiddenFollowupContent(flags, guarantorCtx, domainContext);
    const executionId = String(executionIdProp || '').trim();

    if (!hasContent) {
        return (
            <div className="rounded-xl border border-white/10 bg-black/20 px-3 py-4 text-center">
                <p className="text-[10px] leading-relaxed text-slate-400">
                    لا توجد طلبات مخفية في هذا المسار حالياً — كل الإجراءات ظاهرة في تبويباتها
                    المعتادة.
                </p>
            </div>
        );
    }

    if (!selection) {
        return (
            <div className="space-y-2">
                <p className="text-[9px] font-bold text-emerald-300/80">
                    اختر نوع الطلب — تظهر تفاصيله بعد الضغط
                </p>
                <div className="grid grid-cols-2 gap-2">
                    {pickerButtons.map(({ id, label, Icon, selection: nextSelection }) => (
                        <button
                            key={id}
                            type="button"
                            onClick={() => setSelection(nextSelection)}
                            className="flex items-center gap-2 rounded-xl border border-white/10 bg-white/[0.03] p-3 text-[10px] font-bold text-slate-300 transition-all hover:border-emerald-500/35 hover:bg-emerald-950/25 hover:text-emerald-100"
                        >
                            <Icon size={16} className="shrink-0 opacity-75" />
                            <span className="flex-1 text-right leading-tight">{label}</span>
                        </button>
                    ))}
                </div>
            </div>
        );
    }

    return (
        <div className="space-y-3">
            <button
                type="button"
                onClick={() => setSelection(null)}
                className="inline-flex items-center gap-1.5 rounded-lg border border-white/10 bg-white/5 px-2.5 py-1.5 text-[9px] font-bold text-slate-300 transition-all hover:border-emerald-400/25 hover:text-emerald-100"
            >
                <ChevronRight size={14} className="opacity-70" />
                رجوع إلى قائمة الطلبات
            </button>

            {activeButton ? (
                <p className="text-[11px] font-bold text-emerald-100/95">{activeButton.label}</p>
            ) : null}

            {selection.type === 'break' ? (
                <HiddenBreakInventoryRequestOptions
                    flags={flags}
                    executionId={executionId}
                    decisions={breakDecisions}
                    coerciveUiLocked={personal.coerciveUiLocked}
                    isHistoricalMode={personal.isHistoricalMode}
                    showToast={personal.showToast}
                    onOpenDecisions={personal.onOpenDecisions}
                    embedded
                />
            ) : null}

            {selection.type === 'personal' ? (
                <HiddenPersonalCoerciveRequestOptions
                    executionId={executionId}
                    flags={flags}
                    domainContext={domainContext}
                    embeddedSelectedKey={selection.key}
                    decisions={breakDecisions}
                    {...personal}
                />
            ) : null}

            {selection.type === 'guarantor' ? (
                <HiddenGuarantorRequestOptions
                    executionId={executionId}
                    flags={flags}
                    guarantorCtx={guarantorCtx}
                    domainContext={domainContext}
                    embeddedSelectedKey={selection.key}
                    {...guarantor}
                />
            ) : null}
        </div>
    );
};

// @ts-nocheck
import React from 'react';
import { Building2, Send, Shield, Wallet, Package } from 'lucide-react';
import type { ExecutionFile } from '@/app/types/execution';
import { InlineActionGate } from './InlineActionGate';
import type { InlineActionGateKey } from '../types';
import {
    listHiddenGuarantorCatalog,
    resolveHiddenGuarantorRequests,
    type HiddenFollowupVisibilityInput,
    type HiddenGuarantorContext,
    type HiddenGuarantorRequestKey,
} from './hiddenFollowupRequestsUtils';
import { resolveAmountGuarantorRequestVisible } from '@/app/slices/financial/specialtyPublic';
import {
    findGuarantorSeizureRowFromDecisions,
    findOpenGuarantorRequestDecisionRow,
    hasActiveFinancialGuarantorFollowup,
} from './guarantorExternalUtils';
import { isSalarySeizureAsset } from '@/app/utils/execution/isSalarySeizureAsset';
import { resolveSalarySeizureSubject } from '@/app/components/lawyer/ExecutionDashboard/utils/salarySeizureDisplayUtils';
import {
    ExecutionInlineAccordion,
    ExecutionInlineExecutorDecisionActions,
    type ExecutionInlineStep,
} from '@/app/components/lawyer/ExecutionDashboard/components/ExecutionInlineAccordion';
import {
    DECISIONS_RELOAD_EVENT,
    readExecutorDecisionsArray,
    isExecutorRowRejectedAndFinal,
} from '@/app/utils/executorSeizureDecisionQueue';
import { isExecutorRowApprovedWorkflowActive } from '@/app/utils/executorRequestAppealSync';
import type { ExecutionDomainContext } from '@/app/utils/executionDomainIsolation';

const GUARANTOR_ICONS: Record<
    HiddenGuarantorRequestKey,
    React.ComponentType<{ size?: number; className?: string }>
> = {
    guarantor_request: Shield,
    guarantor_seizure_salary: Wallet,
    guarantor_seizure_property: Building2,
    guarantor_seizure_movable: Package,
};

function gateKeyForGuarantor(key: HiddenGuarantorRequestKey): InlineActionGateKey {
    if (key === 'guarantor_request') return 'hidden_guarantor_amount';
    if (key === 'guarantor_seizure_salary') return 'hidden_guarantor_salary';
    if (key === 'guarantor_seizure_property') return 'hidden_guarantor_property';
    return 'hidden_guarantor_movable';
}

function seizureKindForKey(
    key: HiddenGuarantorRequestKey
): 'salary' | 'property' | 'movable' | null {
    if (key === 'guarantor_seizure_salary') return 'salary';
    if (key === 'guarantor_seizure_property') return 'property';
    if (key === 'guarantor_seizure_movable') return 'movable';
    return null;
}

export interface HiddenGuarantorRequestOptionsProps {
    executionId: string;
    flags: HiddenFollowupVisibilityInput;
    guarantorCtx: HiddenGuarantorContext;
    domainContext?: ExecutionDomainContext | null;
    executionData: ExecutionFile | null;
    /** عند التضمين من قائمة موحّدة — يُعرض لوحة التفاصيل فقط */
    embeddedSelectedKey?: HiddenGuarantorRequestKey;
    coerciveUiLocked: boolean;
    isHistoricalMode: boolean;
    handleGuarantorRequestFromFollowup: () => void;
    requestGuarantorSeizure: (
        kind: 'salary' | 'movable' | 'property',
        opts?: { inline?: boolean }
    ) => void;
    onOpenDecisions: (opts?: {
        tab?: 'current' | 'previous' | 'appeals';
        decisionId?: string | null;
    }) => void;
    showToast: (message: string, type?: 'success' | 'error' | 'warning' | 'info') => void;
}

export const HiddenGuarantorRequestOptions: React.FC<HiddenGuarantorRequestOptionsProps> = ({
    executionId,
    flags,
    guarantorCtx,
    domainContext = null,
    executionData,
    embeddedSelectedKey,
    coerciveUiLocked,
    isHistoricalMode,
    handleGuarantorRequestFromFollowup,
    requestGuarantorSeizure,
    onOpenDecisions,
    showToast,
}) => {
    const exId = String(executionId || '').trim();
    const allDecisions = React.useMemo(
        () => (exId ? (readExecutorDecisionsArray(exId) as Record<string, unknown>[]) : []),
        [exId]
    );
    const catalog = React.useMemo(
        () => listHiddenGuarantorCatalog(flags, guarantorCtx, domainContext),
        [flags, guarantorCtx, domainContext]
    );
    const resolved = React.useMemo(
        () => resolveHiddenGuarantorRequests(flags, guarantorCtx),
        [flags, guarantorCtx]
    );
    const [selectedKey, setSelectedKey] = React.useState<HiddenGuarantorRequestKey | null>(
        embeddedSelectedKey ?? null
    );
    const [inlineGateKey, setInlineGateKey] = React.useState<InlineActionGateKey | null>(null);
    const [guarantorExistingWarningOpen, setGuarantorExistingWarningOpen] = React.useState(false);
    const [decisions, setDecisions] = React.useState<Record<string, unknown>[]>(() =>
        readExecutorDecisionsArray(exId)
    );

    React.useEffect(() => {
        const sync = () => setDecisions(readExecutorDecisionsArray(exId));
        sync();
        window.addEventListener(DECISIONS_RELOAD_EVENT, sync);
        window.addEventListener('hami-execution-decision-outcome', sync as EventListener);
        window.addEventListener('focus', sync);
        return () => {
            window.removeEventListener(DECISIONS_RELOAD_EVENT, sync);
            window.removeEventListener('hami-execution-decision-outcome', sync as EventListener);
            window.removeEventListener('focus', sync);
        };
    }, [exId]);

    React.useEffect(() => {
        if (embeddedSelectedKey) {
            setSelectedKey(embeddedSelectedKey);
        }
    }, [embeddedSelectedKey]);

    const effectiveKey = embeddedSelectedKey ?? selectedKey;
    const selectedCatalog = catalog.find((x) => x.key === effectiveKey) ?? null;
    const selectedResolved = resolved.find((x) => x.key === effectiveKey) ?? null;

    const openGuarantorRow = React.useMemo(
        () => findOpenGuarantorRequestDecisionRow(decisions, executionData),
        [decisions, executionData]
    );

    const seizureKind = effectiveKey ? seizureKindForKey(effectiveKey) : null;
    const guarantorSeizureRow = React.useMemo(() => {
        if (!seizureKind) return null;
        return findGuarantorSeizureRowFromDecisions(decisions, seizureKind);
    }, [decisions, seizureKind]);

    const amountEligible = resolveAmountGuarantorRequestVisible({
        isFinancialDebtCollectionClaim: flags.isFinancialDebtCollection,
        financialCenterTotalIqd: guarantorCtx.financialCenterTotalIqd,
        settlementBreachTriggeredAt: guarantorCtx.settlementBreachTriggeredAt,
        pendingSettlement: guarantorCtx.ledgerPendingSettlement as never,
        hideAllGuarantorPresence: false,
    });
    const guarantorActive = hasActiveFinancialGuarantorFollowup(executionData);

    const guarantorSalaryLaneOccupied = React.useMemo(
        () =>
            (executionData?.seizedAssets || []).some((a) => {
                if (!isSalarySeizureAsset(a)) return false;
                if (String(a.status || '') === 'released') return false;
                const subj = resolveSalarySeizureSubject(
                    a as Record<string, unknown>,
                    executionData,
                    exId
                );
                return subj.roleLabel.includes('كفيل');
            }),
        [executionData, exId]
    );

    const submitDisabledReason = React.useMemo(() => {
        if (!selectedCatalog) return '';
        if (isHistoricalMode || coerciveUiLocked) return 'الوضع مقفل — لا يمكن إرسال طلب جديد.';
        if (selectedCatalog.key === 'guarantor_request') {
            if (guarantorActive) return 'يوجد كفيل ضامن نشط.';
            if (!guarantorCtx.activeDebtorIsEmployee && !amountEligible && !flags.hideAllGuarantorPresence) {
                return 'يتاح بعد إخلال التسوية (عدم السداد وإلغاء التسوية).';
            }
            if (openGuarantorRow) {
                const pending =
                    String(openGuarantorRow.executorOutcome ?? 'pending') === 'pending' ||
                    String(openGuarantorRow.executorOutcome ?? '') === '';
                if (pending) return 'يوجد طلب كفيل قيد البت لدى المنفذ.';
            }
        } else if (!guarantorActive) {
            return 'يتطلب تسجيل كفيل ضامن للمبلغ أولاً.';
        } else if (selectedCatalog.key === 'guarantor_seizure_salary' && guarantorSalaryLaneOccupied) {
            return 'يوجد حجز راتب للكفيل — لا يمكن التكرار قبل فك الحجز.';
        } else if (guarantorSeizureRow) {
            const pending =
                String(guarantorSeizureRow.executorOutcome ?? 'pending') === 'pending' ||
                String(guarantorSeizureRow.executorOutcome ?? '') === '';
            if (pending) return 'يوجد طلب حجز قيد البت لدى المنفذ.';
        }
        return '';
    }, [
        amountEligible,
        coerciveUiLocked,
        flags.hideAllGuarantorPresence,
        guarantorActive,
        guarantorCtx.activeDebtorIsEmployee,
        guarantorSalaryLaneOccupied,
        guarantorSeizureRow,
        isHistoricalMode,
        openGuarantorRow,
        selectedCatalog,
    ]);

    const runSubmit = React.useCallback(() => {
        if (!selectedCatalog || submitDisabledReason) return;
        if (selectedCatalog.key === 'guarantor_request') {
            if (executionData?.guarantor_followup?.details_saved === true) {
                setGuarantorExistingWarningOpen(true);
                setInlineGateKey(null);
                return;
            }
            handleGuarantorRequestFromFollowup();
        } else if (seizureKind) {
            requestGuarantorSeizure(seizureKind, { inline: true });
        }
        setInlineGateKey(null);
    }, [
        executionData?.guarantor_followup?.details_saved,
        handleGuarantorRequestFromFollowup,
        requestGuarantorSeizure,
        seizureKind,
        selectedCatalog,
        submitDisabledReason,
    ]);

    const guarantorRequestSteps: ExecutionInlineStep[] = React.useMemo(() => {
        const row = openGuarantorRow;
        if (!row?.id || selectedCatalog?.key !== 'guarantor_request') return [];
        const decisionId = String(row.id || '').trim();
        const rejected = isExecutorRowRejectedAndFinal(row);
        const pending =
            String(row.executorOutcome ?? 'pending') === 'pending' ||
            String(row.executorOutcome ?? '') === '';
        const approved = isExecutorRowApprovedWorkflowActive(row, allDecisions) && !rejected;
        return [
            {
                id: `hidden-gu-request:sent`,
                title: 'طلب الكفيل',
                subtitle: 'تم إرسال الطلب إلى مركز القرارات',
                status: 'done',
                tone: 'success',
            },
            {
                id: `hidden-gu-request:executor`,
                title: 'قرار المنفذ',
                subtitle: rejected
                    ? 'تم رفض الطلب'
                    : pending
                      ? 'قيد البت لدى المنفذ'
                      : approved
                        ? 'تمت الموافقة — أكمل من القرارات'
                        : '—',
                status: rejected || pending || approved ? 'active' : 'done',
                tone: rejected ? 'danger' : approved ? 'success' : 'neutral',
                content: pending ? (
                    <ExecutionInlineExecutorDecisionActions
                        executionId={exId}
                        decisionId={decisionId}
                        requestKind="guarantor_request"
                    />
                ) : approved ? (
                    <button
                        type="button"
                        onClick={() =>
                            onOpenDecisions({
                                tab: 'current',
                                decisionId,
                            })
                        }
                        className="w-full rounded-xl border border-emerald-500/30 bg-emerald-500/10 py-2 text-[10px] font-bold text-emerald-100 hover:bg-emerald-500/15"
                    >
                        متابعة إكمال الكفيل في القرارات
                    </button>
                ) : undefined,
            },
        ];
    }, [exId, onOpenDecisions, openGuarantorRow, selectedCatalog?.key]);

    const seizureSteps: ExecutionInlineStep[] = React.useMemo(() => {
        const row = guarantorSeizureRow;
        if (!row?.id || !selectedCatalog) return [];
        const decisionId = String(row.id || '').trim();
        const rejected = isExecutorRowRejectedAndFinal(row);
        const pending =
            String(row.executorOutcome ?? 'pending') === 'pending' ||
            String(row.executorOutcome ?? '') === '';
        const approved = isExecutorRowApprovedWorkflowActive(row, allDecisions) && !rejected;
        return [
            {
                id: `hidden-gu-seizure:${selectedCatalog.key}:sent`,
                title: selectedCatalog.label,
                subtitle: 'تم إرسال الطلب',
                status: 'done',
                tone: 'success',
            },
            {
                id: `hidden-gu-seizure:${selectedCatalog.key}:executor`,
                title: 'قرار المنفذ',
                subtitle: rejected
                    ? 'تم رفض الطلب'
                    : pending
                      ? 'قيد البت لدى المنفذ'
                      : approved
                        ? 'تمت الموافقة — أكمل من القرارات'
                        : '—',
                status: rejected || pending || approved ? 'active' : 'done',
                tone: rejected ? 'danger' : approved ? 'success' : 'neutral',
                content: pending ? (
                    <ExecutionInlineExecutorDecisionActions
                        executionId={exId}
                        decisionId={decisionId}
                        requestKind="seizure"
                    />
                ) : approved ? (
                    <button
                        type="button"
                        onClick={() =>
                            onOpenDecisions({
                                tab: 'current',
                                decisionId,
                            })
                        }
                        className="w-full rounded-xl border border-emerald-500/30 bg-emerald-500/10 py-2 text-[10px] font-bold text-emerald-100 hover:bg-emerald-500/15"
                    >
                        متابعة إكمال الحجز في القرارات
                    </button>
                ) : undefined,
            },
        ];
    }, [exId, guarantorSeizureRow, onOpenDecisions, selectedCatalog]);

    if (catalog.length === 0) return null;
    if (!selectedCatalog) return null;

    const detailPanel = (
        <div className="rounded-xl border border-white/10 bg-black/20 p-3 space-y-3">
            <p className="text-[9px] text-slate-400 text-right">{selectedResolved?.statusLabel}</p>

            {guarantorExistingWarningOpen ? (
                <div className="rounded-2xl border border-amber-500/40 bg-amber-950/20 p-3 text-right">
                    <p className="text-[11px] font-black text-amber-200">
                        يوجد كفيل ضامن مُسجَّل في الإضبارة
                    </p>
                    <p className="mt-1 text-[10px] leading-relaxed text-amber-100/85">
                        أكمل الطلب فقط إذا كنت تريد استبدال الكفيل الحالي.
                    </p>
                    <div className="mt-3 grid grid-cols-2 gap-2">
                        <button
                            type="button"
                            onClick={() => {
                                setGuarantorExistingWarningOpen(false);
                                handleGuarantorRequestFromFollowup();
                            }}
                            className="rounded-xl border border-amber-400/55 bg-gradient-to-r from-amber-900/40 to-amber-800/30 py-2.5 text-[11px] font-extrabold text-amber-100"
                        >
                            أتفهم — متابعة
                        </button>
                        <button
                            type="button"
                            onClick={() => setGuarantorExistingWarningOpen(false)}
                            className="rounded-xl border border-white/10 bg-white/5 py-2.5 text-[11px] font-bold text-slate-200"
                        >
                            إلغاء
                        </button>
                    </div>
                </div>
            ) : null}

            {!openGuarantorRow || selectedCatalog.key !== 'guarantor_request' ? (
                <div className="relative">
                    <button
                        type="button"
                        disabled={Boolean(submitDisabledReason)}
                        onClick={() => {
                            if (submitDisabledReason) {
                                showToast(submitDisabledReason, 'warning');
                                return;
                            }
                            if (
                                selectedCatalog.key === 'guarantor_request' &&
                                executionData?.guarantor_followup?.details_saved === true
                            ) {
                                setGuarantorExistingWarningOpen(true);
                                return;
                            }
                            setInlineGateKey(gateKeyForGuarantor(selectedCatalog.key));
                        }}
                        className="flex w-full items-center justify-center gap-2 rounded-xl border border-emerald-500/30 bg-emerald-700/70 py-2.5 text-[11px] font-bold text-white transition-all hover:bg-emerald-700 disabled:cursor-not-allowed disabled:opacity-40"
                    >
                        <Send size={13} />
                        {selectedCatalog.key === 'guarantor_request'
                            ? 'إرسال طلب الكفيل'
                            : 'إرسال طلب الحجز'}
                    </button>
                    {inlineGateKey === gateKeyForGuarantor(selectedCatalog.key) ? (
                        <InlineActionGate
                            gateKey={gateKeyForGuarantor(selectedCatalog.key)}
                            activeKey={inlineGateKey}
                            onConfirm={runSubmit}
                            onCancel={() => setInlineGateKey(null)}
                        />
                    ) : null}
                </div>
            ) : null}

            {selectedCatalog.key === 'guarantor_request' &&
            openGuarantorRow &&
            guarantorRequestSteps.length > 0 ? (
                <ExecutionInlineAccordion steps={guarantorRequestSteps} />
            ) : null}

            {selectedCatalog.key !== 'guarantor_request' &&
            guarantorSeizureRow &&
            seizureSteps.length > 0 ? (
                <ExecutionInlineAccordion steps={seizureSteps} />
            ) : null}
        </div>
    );

    if (embeddedSelectedKey) {
        return detailPanel;
    }

    return (
        <div className="space-y-3 border-t border-white/8 pt-3">
            {!selectedKey ? (
                <div className="grid grid-cols-2 gap-2">
                    {catalog.map((item) => {
                        const Icon = GUARANTOR_ICONS[item.key];
                        return (
                            <button
                                key={item.key}
                                type="button"
                                onClick={() => setSelectedKey(item.key)}
                                className="flex items-center gap-2 rounded-xl border border-white/10 bg-white/[0.03] p-3 text-[10px] font-bold text-slate-300 transition-all hover:border-emerald-500/35 hover:bg-emerald-950/25 hover:text-emerald-100"
                            >
                                <Icon size={16} className="shrink-0 opacity-70" />
                                <span className="leading-tight text-right flex-1">{item.shortLabel}</span>
                            </button>
                        );
                    })}
                </div>
            ) : (
                <>
                    <button
                        type="button"
                        onClick={() => setSelectedKey(null)}
                        className="inline-flex items-center gap-1.5 rounded-lg border border-white/10 bg-white/5 px-2.5 py-1.5 text-[9px] font-bold text-slate-300 hover:text-emerald-100"
                    >
                        رجوع
                    </button>
                    {detailPanel}
                </>
            )}
        </div>
    );
};

// @ts-nocheck
import React from 'react';
import { Gavel, Plane, Scale, Send, ShieldAlert, UserX } from 'lucide-react';
import { InlineActionGate } from './InlineActionGate';
import type { InlineActionGateKey } from '../types';
import {
    ExecutionInlineAccordion,
    ExecutionInlineExecutorDecisionActions,
    type ExecutionInlineStep,
} from '@/app/components/lawyer/ExecutionDashboard/components/ExecutionInlineAccordion';
import { ExecutorDecisionFollowupMirror } from '@/app/components/lawyer/ExecutionDashboard/components/ExecutorDecisionFollowupMirror';
import {
    appendPersonalCoerciveExecutorRequest,
    dispatchDecisionsReload,
    getGoverningPersonalCoerciveSubtypeRowFromDecisions,
    isExecutorHubRowSuperseded,
    isExecutorRowRejectedAndFinal,
    type PersonalCoerciveSubtype,
} from '@/app/utils/executorSeizureDecisionQueue';
import {
    listHiddenPersonalCoerciveCatalog,
    resolveHiddenPersonalCoerciveRequests,
    type HiddenFollowupVisibilityInput,
    type HiddenPersonalCoerciveRequestKey,
} from './hiddenFollowupRequestsUtils';
import type { AppealUiPerspective } from '@/app/components/lawyer/DecisionsAndAppealsEngine/appealUiLabels';
import type { ExecutionDomainContext } from '@/app/utils/executionDomainIsolation';

const OPTION_ICONS: Record<
    HiddenPersonalCoerciveRequestKey,
    React.ComponentType<{ size?: number; className?: string }>
> = {
    forced_bring_in: UserX,
    travel_ban: Plane,
    arrest_warrant_investigation: ShieldAlert,
    executive_dossier_presentation: Scale,
    executive_detention_judge: Gavel,
};

function gateKeyForOption(key: HiddenPersonalCoerciveRequestKey): InlineActionGateKey | null {
    if (key === 'forced_bring_in') return 'hidden_pc_forced_bring';
    if (key === 'travel_ban') return 'hidden_pc_travel_ban';
    if (key === 'arrest_warrant_investigation') return 'hidden_pc_arrest';
    if (key === 'executive_dossier_presentation') return 'hidden_pc_dossier';
    return null;
}

export interface HiddenPersonalCoerciveRequestOptionsProps {
    executionId: string;
    flags: HiddenFollowupVisibilityInput;
    domainContext?: ExecutionDomainContext | null;
    /** عند التضمين من قائمة موحّدة — يُعرض لوحة التفاصيل فقط */
    embeddedSelectedKey?: HiddenPersonalCoerciveRequestKey;
    decisions: Record<string, unknown>[];
    coerciveUiLocked: boolean;
    isHistoricalMode: boolean;
    activeDebtorKey?: string;
    primaryDebtorKey?: string;
    kasabRelaxedGates?: boolean;
    forcedSummonAllowed?: boolean;
    forcedSummonLockReason?: string;
    onOpenSummonsCenter?: () => void;
    showToast: (
        message: string,
        type?: 'success' | 'error' | 'warning' | 'info',
        opts?: { decisionsLink?: boolean; decisionId?: string; decisionsTab?: 'current' | 'previous' | 'appeals' }
    ) => void;
    persistExecutionMerge: (patch: Record<string, unknown>) => void;
    onOpenDecisions: (opts?: {
        tab?: 'current' | 'previous' | 'appeals';
        decisionId?: string | null;
    }) => void;
    appealPerspective?: AppealUiPerspective;
}

export const HiddenPersonalCoerciveRequestOptions: React.FC<HiddenPersonalCoerciveRequestOptionsProps> = ({
    executionId,
    flags,
    domainContext = null,
    embeddedSelectedKey,
    decisions,
    coerciveUiLocked,
    isHistoricalMode,
    activeDebtorKey = '',
    primaryDebtorKey = '',
    kasabRelaxedGates = false,
    forcedSummonAllowed = false,
    forcedSummonLockReason = '',
    onOpenSummonsCenter,
    showToast,
    persistExecutionMerge,
    onOpenDecisions,
    appealPerspective = 'creditor_agent',
}) => {
    const exId = String(executionId || '').trim();
    const catalog = React.useMemo(
        () => listHiddenPersonalCoerciveCatalog(flags, domainContext),
        [flags, domainContext]
    );
    const resolved = React.useMemo(
        () => resolveHiddenPersonalCoerciveRequests(flags, decisions),
        [flags, decisions]
    );
    const [selectedKey, setSelectedKey] = React.useState<HiddenPersonalCoerciveRequestKey | null>(
        embeddedSelectedKey ?? null
    );
    const [inlineGateKey, setInlineGateKey] = React.useState<InlineActionGateKey | null>(null);
    const [submitting, setSubmitting] = React.useState(false);

    React.useEffect(() => {
        if (embeddedSelectedKey) {
            setSelectedKey(embeddedSelectedKey);
        }
    }, [embeddedSelectedKey]);

    const effectiveKey = embeddedSelectedKey ?? selectedKey;
    const selectedCatalog = catalog.find((x) => x.key === effectiveKey) ?? null;
    const selectedResolved = resolved.find((x) => x.key === effectiveKey) ?? null;

    const governingRow = React.useMemo(() => {
        if (!selectedCatalog?.subtype) return null;
        return getGoverningPersonalCoerciveSubtypeRowFromDecisions(decisions, selectedCatalog.subtype);
    }, [decisions, selectedCatalog?.subtype]);

    const submitDisabledReason = React.useMemo(() => {
        if (!selectedCatalog?.subtype || !selectedCatalog.submitTitle) {
            return 'يُتابَع بعد موافقة المنفذ على عرض الإضبارة.';
        }
        if (isHistoricalMode || coerciveUiLocked) return 'الوضع مقفل — لا يمكن إرسال طلب جديد.';
        const status = selectedResolved?.status;
        if (status === 'pending') return 'يوجد طلب قيد البت لدى المنفذ.';
        if (status === 'approved') return 'الطلب موافق عليه — تابع الإكمال من القرارات.';
        return '';
    }, [
        coerciveUiLocked,
        isHistoricalMode,
        selectedCatalog,
        selectedResolved?.status,
    ]);

    const runSubmit = React.useCallback(
        async (subtype: PersonalCoerciveSubtype, title: string, body: string) => {
            if (!exId || isHistoricalMode || coerciveUiLocked) return;
            setSubmitting(true);
            try {
                const submitted = appendPersonalCoerciveExecutorRequest({
                    executionId: exId,
                    subtype,
                    title,
                    body,
                    debtorKey: activeDebtorKey,
                    primaryDebtorKey,
                });
                if (!submitted.ok || !submitted.decisionId) {
                    showToast('يوجد طلب مماثل قيد البت لدى المنفذ.', 'warning', {
                        decisionsLink: true,
                    });
                    return;
                }
                if (subtype === 'forced_bring_in') {
                    persistExecutionMerge({
                        forced_bring_in_personal_outcome: null,
                        forced_bring_in_personal_followup_logged: false,
                    });
                }
                if (subtype === 'travel_ban') {
                    persistExecutionMerge({ travel_ban_withdrawn_at: null });
                }
                if (subtype === 'executive_dossier_presentation') {
                    persistExecutionMerge({
                        executive_dossier_phase: null,
                        executive_detention_judge_outcome: null,
                        executive_detention_judge_eligible_decision_id: null,
                    });
                }
                dispatchDecisionsReload();
                showToast('تم حفظ الطلب وتحويله إلى مركز القرارات بانتظار موافقة المنفذ.', 'success', {
                    decisionsLink: true,
                    decisionId: submitted.decisionId,
                    decisionsTab: 'previous',
                });
            } finally {
                setSubmitting(false);
                setInlineGateKey(null);
            }
        },
        [
            activeDebtorKey,
            coerciveUiLocked,
            exId,
            isHistoricalMode,
            persistExecutionMerge,
            primaryDebtorKey,
            showToast,
        ]
    );

    const steps: ExecutionInlineStep[] = React.useMemo(() => {
        const row = governingRow as Record<string, unknown> | null;
        if (!row?.id || !selectedCatalog) return [];
        const decisionId = String(row.id || '').trim();
        const rejected = isExecutorRowRejectedAndFinal(row);
        const rejectedClosed = rejected && isExecutorHubRowSuperseded(row);
        const pending =
            String(row.executorOutcome ?? 'pending') === 'pending' ||
            String(row.executorOutcome ?? '') === '';
        const approved = !rejected && !pending;
        return [
            {
                id: `hidden-pc:${selectedCatalog.key}:submit`,
                title: String(row.title || selectedCatalog.label).trim(),
                subtitle: 'تم إرسال الطلب إلى مركز القرارات',
                status: 'done',
                tone: 'success',
            },
            {
                id: `hidden-pc:${selectedCatalog.key}:executor`,
                title: 'قرار المنفذ',
                subtitle: rejected
                    ? 'تم رفض الطلب'
                    : pending
                      ? 'قيد البت لدى المنفذ'
                      : approved
                        ? appealPerspective === 'debtor_agent'
                            ? 'موافقة ضد موكّلك'
                            : 'تمت الموافقة'
                        : '—',
                status: rejectedClosed ? 'done' : rejected || pending ? 'active' : 'done',
                tone:
                    rejected
                        ? 'danger'
                        : approved
                          ? appealPerspective === 'debtor_agent'
                              ? 'danger'
                              : 'success'
                          : 'neutral',
                content:
                    rejected && !rejectedClosed ? (
                        <ExecutorDecisionFollowupMirror
                            executionId={exId}
                            row={row}
                            requestKind="personal_coercive"
                            compact
                            appealPerspective={appealPerspective}
                        />
                    ) : pending ? (
                        <ExecutionInlineExecutorDecisionActions
                            executionId={exId}
                            decisionId={decisionId}
                            requestKind="personal_coercive"
                        />
                    ) : approved ? (
                        appealPerspective === 'debtor_agent' ? (
                            <ExecutorDecisionFollowupMirror
                                executionId={exId}
                                row={row}
                                requestKind="personal_coercive"
                                compact
                                appealPerspective={appealPerspective}
                            />
                        ) : (
                            <button
                                type="button"
                                onClick={() =>
                                    onOpenDecisions({
                                        tab: 'previous',
                                        decisionId,
                                    })
                                }
                                className="w-full rounded-xl border border-emerald-500/30 bg-emerald-500/10 py-2 text-[10px] font-bold text-emerald-100 hover:bg-emerald-500/15"
                            >
                                متابعة الإكمال في القرارات
                            </button>
                        )
                    ) : undefined,
            },
        ];
    }, [appealPerspective, exId, governingRow, onOpenDecisions, selectedCatalog]);

    const activeGate = effectiveKey ? gateKeyForOption(effectiveKey) : null;

    if (catalog.length === 0) return null;
    if (!selectedCatalog) return null;

    const detailPanel = (
        <div className="rounded-xl border border-white/10 bg-black/20 p-3 space-y-3">
            <p className="text-[9px] text-slate-400 text-right">{selectedResolved?.statusLabel}</p>

            {selectedCatalog.subtype && selectedCatalog.submitTitle ? (
                <div className="relative">
                    <button
                        type="button"
                        disabled={Boolean(submitDisabledReason) || submitting}
                        onClick={() => {
                            if (submitDisabledReason) {
                                showToast(submitDisabledReason, 'warning');
                                return;
                            }
                            const gate = gateKeyForOption(selectedCatalog.key);
                            if (gate) setInlineGateKey(gate);
                        }}
                        className="flex w-full items-center justify-center gap-2 rounded-xl border border-emerald-500/30 bg-emerald-700/70 py-2.5 text-[11px] font-bold text-white transition-all hover:bg-emerald-700 disabled:cursor-not-allowed disabled:opacity-40"
                    >
                        <Send size={13} />
                        إرسال الطلب إلى المنفذ
                    </button>
                    {activeGate && inlineGateKey === activeGate ? (
                        <InlineActionGate
                            gateKey={activeGate}
                            activeKey={inlineGateKey}
                            onConfirm={() => {
                                void runSubmit(
                                    selectedCatalog.subtype!,
                                    selectedCatalog.submitTitle!,
                                    selectedCatalog.submitBody || ''
                                );
                            }}
                            onCancel={() => setInlineGateKey(null)}
                        />
                    ) : null}
                </div>
            ) : (
                <p className="text-[10px] leading-relaxed text-slate-400">
                    يُسجَّل قرار قاضي البداءة بعد موافقة المنفذ على عرض الإضبارة — تابع من مركز
                    القرارات.
                </p>
            )}

            {governingRow && steps.length > 0 ? <ExecutionInlineAccordion steps={steps} /> : null}
        </div>
    );

    if (embeddedSelectedKey) {
        return detailPanel;
    }

    return (
        <div className="space-y-3 border-t border-white/8 pt-3">
            {!selectedKey ? (
                <div className="grid grid-cols-2 gap-2">
                    {catalog.map((item) => {
                        const Icon = OPTION_ICONS[item.key];
                        const itemStatus = resolved.find((x) => x.key === item.key)?.status;
                        return (
                            <button
                                key={item.key}
                                type="button"
                                onClick={() => setSelectedKey(item.key)}
                                className="flex items-center gap-2 rounded-xl border border-white/10 bg-white/[0.03] p-3 text-[10px] font-bold text-slate-300 transition-all hover:border-emerald-500/35 hover:bg-emerald-950/25 hover:text-emerald-100"
                            >
                                <Icon size={16} className="shrink-0 opacity-70" />
                                <span className="leading-tight text-right flex-1">{item.shortLabel}</span>
                                {itemStatus === 'pending' ? (
                                    <span className="h-1.5 w-1.5 shrink-0 rounded-full bg-amber-400" />
                                ) : null}
                                {itemStatus === 'approved' ? (
                                    <span className="h-1.5 w-1.5 shrink-0 rounded-full bg-emerald-400" />
                                ) : null}
                            </button>
                        );
                    })}
                </div>
            ) : (
                <>
                    <button
                        type="button"
                        onClick={() => setSelectedKey(null)}
                        className="inline-flex items-center gap-1.5 rounded-lg border border-white/10 bg-white/5 px-2.5 py-1.5 text-[9px] font-bold text-slate-300 hover:text-emerald-100"
                    >
                        رجوع
                    </button>
                    {detailPanel}
                </>
            )}
        </div>
    );
};

import React, { useMemo } from 'react';
import { X, Clock, Calendar, FileText, User, Ban } from 'lucide-react';
import { storageCache } from '@/app/utils/storageCache';
import { EXECUTION_FILES_STORAGE_KEY } from '@/app/utils/executionFilesStorage';

interface LinkedDossierTimelineModalProps {
    dossier: {
        linkedId: string;
        type: 'own' | 'colleague';
        directorate?: string;
        fileNumber?: string;
        fileYear?: string;
        linkToken?: string;
    };
    onClose: () => void;
}

const timelineTypeIcon: Record<string, React.ReactNode> = {
    system: <Calendar size={14} />,
    decision: <FileText size={14} />,
    action: <User size={14} />,
};

const timelineTypeColor: Record<string, string> = {
    system: 'border-emerald-500/30 bg-emerald-950/20 text-emerald-300',
    decision: 'border-amber-500/30 bg-amber-950/20 text-amber-300',
    action: 'border-blue-500/30 bg-blue-950/20 text-blue-300',
};

export function LinkedDossierTimelineModal({ dossier, onClose }: LinkedDossierTimelineModalProps) {
    const { timelineEvents, hasLocalFile } = useMemo(() => {
        try {
            const cached = storageCache.get(EXECUTION_FILES_STORAGE_KEY);
            const allFiles: any[] = Array.isArray(cached) ? cached : [];
            const linkedFile = allFiles.find((f: any) => String(f.id) === dossier.linkedId);
            if (linkedFile?.timelineEvents && Array.isArray(linkedFile.timelineEvents)) {
                return {
                    hasLocalFile: true,
                    timelineEvents: linkedFile.timelineEvents.slice().sort(
                    (a: any, b: any) => new Date(b.createdAt || b.date || 0).getTime() - new Date(a.createdAt || a.date || 0).getTime()
                    ),
                };
            }
            return { hasLocalFile: Boolean(linkedFile), timelineEvents: [] as any[] };
        } catch {
            return { hasLocalFile: false, timelineEvents: [] as any[] };
        }
    }, [dossier.linkedId]);

    return (
        <div className="fixed inset-0 z-[9999] flex items-center justify-center bg-black/60 backdrop-blur-sm" onClick={onClose}>
            <div
                className="w-full max-w-lg max-h-[80vh] overflow-y-auto rounded-2xl border border-white/10 bg-slate-900 p-6 shadow-2xl"
                onClick={(e) => e.stopPropagation()}
            >
                <div className="mb-5 flex items-center justify-between">
                    <div className="flex items-center gap-2">
                        <Clock size={16} className="text-blue-400" />
                        <h3 className="text-base font-bold text-white">
                            السجل الزمني — إضبارة زميل
                        </h3>
                    </div>
                    <button type="button" onClick={onClose} className="text-slate-400 hover:text-white transition-colors">
                        <X size={18} />
                    </button>
                </div>

                <div className="mb-4 rounded-lg bg-blue-950/30 border border-blue-500/20 px-3 py-2 text-xs text-blue-300/80">
                    {dossier.fileNumber || '---'} / {dossier.fileYear || '---'} — {dossier.directorate || '---'}
                    <span className="mr-2 text-[9px] text-yellow-400/70">(إضبارة زميل — قراءة فقط)</span>
                </div>

                {timelineEvents.length === 0 ? (
                    <div className="rounded-lg border border-white/10 bg-white/5 p-6 text-center">
                        <Clock size={32} className="text-slate-500 mx-auto mb-2" />
                        <p className="text-sm text-slate-300">
                            {hasLocalFile ? 'لا توجد أحداث في السجل الزمني لهذه الإضبارة' : 'لا يمكن عرض سجل هذه الإضبارة على هذا الجهاز'}
                        </p>
                        {dossier.linkToken ? (
                            <div className="mt-3 space-y-2">
                                <p className="text-[10px] text-slate-500">رمز الربط:</p>
                                <div className="flex items-center justify-center gap-2">
                                    <span className="rounded-lg border border-slate-600/40 bg-slate-950/30 px-2 py-1 text-[10px] font-mono text-slate-200">
                                        {dossier.linkToken}
                                    </span>
                                    <button
                                        type="button"
                                        className="rounded-lg border border-slate-600/40 bg-slate-900/40 px-2 py-1 text-[10px] font-semibold text-slate-200 hover:bg-slate-900/60"
                                        onClick={() => {
                                            navigator.clipboard.writeText(dossier.linkToken || '').catch(() => {});
                                        }}
                                    >
                                        نسخ
                                    </button>
                                </div>
                                <p className="text-[10px] text-slate-500">قدّم هذا الرمز للزميل لتمكين الربط عنده.</p>
                            </div>
                        ) : (
                            <p className="mt-1 text-[10px] text-slate-500">قد لا تكون الإضبارة متاحة للمشاهدة حالياً</p>
                        )}
                    </div>
                ) : (
                    <div className="relative space-y-2">
                        {timelineEvents.map((event: any, idx: number) => {
                            const icon = timelineTypeIcon[event.type] || <Calendar size={14} />;
                            const color = timelineTypeColor[event.type] || timelineTypeColor.system;
                            return (
                                <div key={event.id || idx} className={`flex items-start gap-3 rounded-lg border p-3 ${color}`}>
                                    <div className="mt-0.5 shrink-0">
                                        {icon}
                                    </div>
                                    <div className="min-w-0 flex-1">
                                        <p className="text-xs font-bold">{event.title}</p>
                                        {event.description && (
                                            <p className="mt-0.5 text-[10px] opacity-80">{event.description}</p>
                                        )}
                                        <p className="mt-1 text-[9px] opacity-50">{event.date || event.createdAt?.split('T')[0] || ''}</p>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                )}
            </div>
        </div>
    );
}

