                    </span>
                ) : (
                    <span className="rounded-lg border border-sky-500/25 bg-sky-500/10 px-2 py-1 font-bold text-sky-200">
                        فتح الإدارة
                    </span>
                )}
            </div>
        </button>
    );
}

function MaritalFurnitureWorkspaceSheet({
    open,
    onClose,
    headerActions,
    children,
}: {
    open: boolean;
    onClose: () => void;
    headerActions: ReactNode;
    children: ReactNode;
}) {
    if (!open || typeof document === 'undefined') return null;

    return createPortal(
        <div
            className={`fixed inset-0 flex flex-col ${EXEC_MODAL_BACKDROP_STRONG}`}
            style={{ zIndex: WORKSPACE_Z }}
            role="dialog"
            aria-modal="true"
            aria-label="إدارة الأثاث الزوجية"
            data-testid="marital-furniture-workspace"
            onClick={onClose}
        >
            <div
                className="mt-auto flex h-[min(96dvh,100%)] w-full max-w-lg flex-col self-center overflow-hidden rounded-t-3xl border border-[#E6C673]/25 bg-[#0B1120] shadow-2xl sm:my-auto sm:h-[min(92dvh,820px)] sm:rounded-3xl pt-[env(safe-area-inset-top)] pb-[env(safe-area-inset-bottom)]"
                onClick={(e) => e.stopPropagation()}
                dir="rtl"
            >
                <div className="flex shrink-0 items-center gap-2 border-b border-white/10 bg-[#0A0F1C]/95 px-3 py-3 backdrop-blur-md flex-row-reverse">
                    <button
                        type="button"
                        data-testid="marital-furniture-close"
                        onClick={onClose}
                        className="inline-flex min-h-[44px] min-w-[44px] items-center justify-center rounded-xl border border-white/10 bg-white/5 text-slate-300 hover:bg-white/10 touch-manipulation"
                        aria-label="إغلاق"
                    >
                        <X size={18} />
                    </button>
                    <div className="min-w-0 flex-1 text-right">
                        <p className="text-sm font-bold text-[#E6C673]">إدارة الأثاث الزوجية</p>
                        <p className="text-[10px] text-slate-500">القائمة · الموعد · التسليم الميداني</p>
                    </div>
                    <div className="flex shrink-0 items-center gap-2 flex-row-reverse">{headerActions}</div>
                </div>
                <div className="flex min-h-0 flex-1 flex-col overflow-y-auto overscroll-contain px-4 py-4">
                    {children}
                </div>
            </div>
        </div>,
        document.body,
    );
}

export const MaritalFurnitureModule: React.FC<MaritalFurnitureModuleProps> = ({
    executionData,
    persistExecutionMerge,
    showToast,
    pushTimelineEvent,
    setTimelineEvents,
    timelineEvents = [],
    nextTimelineId,
    todayYmd: todayYmdProp,
    locked = false,
}) => {
    const [workspaceOpen, setWorkspaceOpen] = useState(false);
    const [search, setSearch] = useState('');
    const [isEditing, setIsEditing] = useState(false);
    const [draftItems, setDraftItems] = useState<MaritalFurnitureItem[]>([]);
    const [scheduleYmdDraft, setScheduleYmdDraft] = useState('');
    const [earlyDeliveryUnlocked, setEarlyDeliveryUnlocked] = useState(false);
    const [savingSchedule, setSavingSchedule] = useState(false);
    const [savingItemId, setSavingItemId] = useState<string | null>(null);
    const [localItems, setLocalItems] = useState<MaritalFurnitureItem[]>([]);
    const [localSchedule, setLocalSchedule] = useState<{ ymd: string; label: string }>({
        ymd: '',
        label: '',
    });
    const [editingSchedule, setEditingSchedule] = useState(false);
    const [pendingDelivery, setPendingDelivery] = useState<{
        itemId: string;
        outcome: Exclude<MaritalFurnitureDeliveryOutcome, 'pending'>;
        itemName: string;
    } | null>(null);
    const materializedRef = useRef(false);

    const todayYmd = todayYmdProp ?? getLocalTodayYmd();

    const items = useMemo(
        () => readMaritalFurnitureItems(executionData as MaritalFurnitureModuleProps['executionData']),
        [executionData],
    );

    const itemsDeliverySig = useMemo(
        () =>
            items
                .map(
                    (row) =>
                        `${row.id}:${row.deliveryOutcome ?? ''}:${row.delivered ?? ''}:${row.deliveryRecordedAt ?? ''}`,
                )
                .join('|'),
        [items],
    );

    useEffect(() => {
        setLocalItems((prev) => {
            if (items.length === 0) return prev.length > 0 ? prev : items;
            const merged = items.map((serverRow) => {
                const localRow = prev.find((p) => String(p.id) === String(serverRow.id));
                if (!localRow) return serverRow;
                const serverLocked = isMaritalFurnitureItemDeliveryLocked(serverRow);
                const localLocked = isMaritalFurnitureItemDeliveryLocked(localRow);
                if (localLocked && !serverLocked) return localRow;
                if (serverLocked) return serverRow;
                return localRow.deliveryRecordedAt ? localRow : serverRow;
            });
            return merged;
        });
    }, [items, itemsDeliverySig]);

    const deliverySchedule = useMemo(
        () => readMaritalFurnitureDeliverySchedule(executionData),
        [executionData],
    );

    useEffect(() => {
        setLocalSchedule((prev) => {
            if (deliverySchedule.ymd) return deliverySchedule;
            if (prev.ymd) return prev;
            return deliverySchedule;
        });
        if (deliverySchedule.ymd) setEditingSchedule(false);
    }, [deliverySchedule.ymd, deliverySchedule.label]);

    useEffect(() => {
        if (locked || materializedRef.current || !executionData) return;
        if (hasAnyMaritalFurnitureDeliveryRecorded(items)) return;
        const stored = (executionData as { maritalFurnitureItems?: MaritalFurnitureItem[] })
            .maritalFurnitureItems;
        if (Array.isArray(stored) && stored.length > 0) return;
        const details = String(
            (executionData as { furnitureDetails?: string }).furnitureDetails || '',
        ).trim();
        if (!details || items.length === 0) return;
        materializedRef.current = true;
        const furnitureValue = sumMaritalFurnitureTotal(items);
        const ok = persistExecutionMerge({
            maritalFurnitureItems: items,
            furnitureValue,
            furnitureDetails: furnitureDetailsFromItems(items),
        });
        if (ok === false) materializedRef.current = false;
    }, [executionData, items, locked, persistExecutionMerge]);

    const displayItems = localItems.length > 0 ? localItems : items;
    const total = useMemo(() => sumMaritalFurnitureTotal(displayItems), [displayItems]);
    const deliveryRecorded = useMemo(
        () => isMaritalFurnitureDeliveryStatusRecorded(executionData),
        [executionData],
    );
    const deliveryCounts = useMemo(() => countMaritalFurnitureDeliveryStatus(displayItems), [displayItems]);
    const deliveredTotal = useMemo(() => sumDeliveredMaritalFurnitureTotal(displayItems), [displayItems]);
    const undeliveredTotal = useMemo(() => sumUndeliveredMaritalFurnitureTotal(displayItems), [displayItems]);
    const lockedDeliveryCount = useMemo(() => countLockedDeliveryItems(displayItems), [displayItems]);

    const visibleItems = useMemo(() => {
        const q = search.trim().toLowerCase();
        if (!q) return displayItems;
        return displayItems.filter((row) => row.name.toLowerCase().includes(q));
    }, [displayItems, search]);

    const undeliveredItems = useMemo(
        () => displayItems.filter((row) => row.delivered === false),
        [displayItems],
    );
    const canEditAfterDelivery = deliveryRecorded && undeliveredItems.length > 0;

    const isDeliveredRowLocked = useCallback(
        (row: MaritalFurnitureItem) => deliveryRecorded && row.delivered === true,
        [deliveryRecorded],
    );

    const startEdit = useCallback(() => {
        if (deliveryRecorded && undeliveredItems.length === 0) {
            showToast('جميع القطع مُسلَّمة — لا يمكن التعديل', 'info');
            return;
        }
        setDraftItems(
            items.length > 0 ? items.map((row) => ({ ...row })) : [createEmptyMaritalFurnitureItem()],
        );
        setIsEditing(true);
    }, [items, deliveryRecorded, undeliveredItems.length, showToast]);

    const cancelEdit = useCallback(() => {
        setIsEditing(false);
        setDraftItems([]);
    }, []);

    const handleSave = useCallback(() => {
        const hasDeliveryRecorded = isMaritalFurnitureDeliveryStatusRecorded(executionData);
        const normalized = normalizeMaritalFurnitureItems(draftItems).map((row) => {
            const src = draftItems.find((d) => d.id === row.id);
            if (typeof src?.delivered === 'boolean') {
                return { ...row, delivered: src.delivered };
            }
            return row;
        });
        if (normalized.length === 0) {
            showToast('أضف قطعة واحدة على الأقل باسم صالح', 'warning');
            return;
        }
        if (hasDeliveryRecorded) {
            const missingDelivered = items.filter(
                (row) => row.delivered === true && !normalized.some((n) => n.id === row.id),
            );
            if (missingDelivered.length > 0) {
                showToast('لا يمكن حذف القطع المُسلَّمة', 'warning');
                return;
            }
            for (const row of normalized) {
                if (row.delivered !== true) continue;
                const original = items.find((i) => i.id === row.id);
                if (!original) continue;
                if (
                    row.name !== original.name ||
                    row.quantity !== original.quantity ||
                    row.unitPriceIqd !== original.unitPriceIqd
                ) {
                    showToast('القطع المُسلَّمة مقفلة — التعديل للغير مُسلَّم فقط', 'warning');
                    return;
                }
            }
        }
        const furnitureValue = sumMaritalFurnitureTotal(normalized);
        const financialAmount = hasDeliveryRecorded
            ? sumUndeliveredMaritalFurnitureTotal(normalized)
            : 0;
        const ok = persistExecutionMerge({
            maritalFurnitureItems: normalized,
            furnitureValue,
            furnitureDetails: furnitureDetailsFromItems(normalized),
            totalAmount: financialAmount,
            debtAmount: financialAmount,
        });
        if (ok === false) {
            showToast('تعذّر حفظ قائمة الأثاث — تحقق من الإضبارة', 'error');
            return;
        }
        setLocalItems(normalized);
        setIsEditing(false);
        setDraftItems([]);
        showToast(
            hasDeliveryRecorded ? 'تم حفظ تعديلات غير المُسلَّم' : 'تم حفظ قائمة الأثاث',
            'success',
        );
    }, [draftItems, executionData, items, persistExecutionMerge, showToast]);

    const editTotal = useMemo(() => sumMaritalFurnitureTotal(draftItems), [draftItems]);

    const canManageDelivery = !locked && displayItems.length > 0 && !isEditing;
    const scheduleYmd = localSchedule.ymd || deliverySchedule.ymd;
    const scheduleLabel = localSchedule.label || deliverySchedule.label;
    const showScheduleForm = canManageDelivery && (!scheduleYmd || editingSchedule);

    const scheduleHint = scheduleYmd
        ? scheduleLabel || `موعد: ${scheduleYmd}`
        : 'لم يُحدَّد موعد التسليم بعد';

    const requestCloseWorkspace = useCallback(() => {
        if (isEditing) {
            if (!window.confirm('لديك تعديلات غير محفوظة. إغلاق مساحة الإدارة؟')) return;
            cancelEdit();
        }
        setPendingDelivery(null);
        setWorkspaceOpen(false);
    }, [isEditing, cancelEdit]);

    useEffect(() => {
        if (!workspaceOpen) return;
        const onKeyDown = (event: KeyboardEvent) => {
            if (event.key === 'Escape') requestCloseWorkspace();
        };
        window.addEventListener('keydown', onKeyDown);
        const previousOverflow = document.body.style.overflow;
        document.body.style.overflow = 'hidden';
        return () => {
            window.removeEventListener('keydown', onKeyDown);
            document.body.style.overflow = previousOverflow;
        };
    }, [workspaceOpen, requestCloseWorkspace]);

    const timelineDeps = useMemo(
        () => ({
            persistExecutionMerge,
            pushTimelineEvent,
            setTimelineEvents,
            getTimelineEvents: () => timelineEvents,
            nextTimelineId,
        }),
        [
            persistExecutionMerge,
            pushTimelineEvent,
            setTimelineEvents,
            timelineEvents,
            nextTimelineId,
        ],
    );

    const handleSaveSchedule = useCallback(() => {
        if (typeof persistExecutionMerge !== 'function') {
            showToast('تعذّر الحفظ — الإضبارة غير جاهزة', 'error');
            return;
        }
        const ymd = (scheduleYmdDraft || scheduleYmd).trim();
        if (!ymd) {
            showToast('اختر تاريخ موعد التسليم', 'warning');
            return;
        }
        setSavingSchedule(true);
        try {
            const nextScheduleLabel = buildArabicScheduleLabel(ymd);
            const ok = runPersistMaritalFurnitureDeliverySchedule(
                { ymd, displayAr: ymd, scheduleLabel: nextScheduleLabel },
                timelineDeps,
            );
            if (!ok) {
                showToast('تعذّر حفظ موعد التسليم — تحقق من الإضبارة', 'error');
                return;
            }
            setLocalSchedule({ ymd, label: nextScheduleLabel });
            setScheduleYmdDraft('');
            setEditingSchedule(false);
            showToast('تم حفظ موعد التسليم الميداني', 'success');
        } finally {
            setSavingSchedule(false);
        }
    }, [scheduleYmdDraft, scheduleYmd, timelineDeps, showToast]);

    const executeItemOutcome = useCallback(
        (itemId: string, outcome: Exclude<MaritalFurnitureDeliveryOutcome, 'pending'>) => {
            if (locked || savingItemId) return;
            if (typeof persistExecutionMerge !== 'function') {
                showToast('تعذّر الحفظ — الإضبارة غير جاهزة', 'error');
                return;
            }
            const row = displayItems.find((r) => String(r.id) === String(itemId));
            if (!row || isMaritalFurnitureItemDeliveryLocked(row)) return;

            const ts = new Date().toISOString();
            const previousItems = displayItems;
            const optimisticItems = previousItems.map((item) =>
                String(item.id) === String(itemId)
                    ? applyMaritalFurnitureDeliveryOutcome(item, outcome, ts)
                    : item,
            );
            setLocalItems(optimisticItems);
            setSavingItemId(itemId);
            try {
                const ok = runPersistMaritalFurnitureItemDeliveryOutcome(
                    { itemId, outcome },
                    {
                        executionData,
                        items: optimisticItems,
                        showToast,
                        ...timelineDeps,
                    },
                );
                if (!ok) {
                    setLocalItems(previousItems);
                    showToast('تعذّر حفظ حالة التسليم — تحقق من الإضبارة', 'error');
                }
            } catch {
                setLocalItems(previousItems);
                showToast('تعذّر حفظ حالة التسليم', 'error');
            } finally {
                setSavingItemId(null);
            }
        },
        [
            displayItems,
            locked,
            savingItemId,
            executionData,
            timelineDeps,
            showToast,
            persistExecutionMerge,
        ],
    );

    const requestItemOutcome = useCallback(
        (itemId: string, outcome: MaritalFurnitureDeliveryOutcome) => {
            if (locked || savingItemId || outcome === 'pending') return;
            const row = displayItems.find((r) => String(r.id) === String(itemId));
            if (!row || isMaritalFurnitureItemDeliveryLocked(row)) return;
            setPendingDelivery({
                itemId,
                outcome: outcome as Exclude<MaritalFurnitureDeliveryOutcome, 'pending'>,
                itemName: row.name,
            });
        },
        [displayItems, locked, savingItemId],
    );

    const confirmPendingDelivery = useCallback(() => {
        if (!pendingDelivery) return;
        const { itemId, outcome } = pendingDelivery;
        setPendingDelivery(null);
        executeItemOutcome(itemId, outcome);
    }, [pendingDelivery, executeItemOutcome]);

    const headerActions = !locked ? (
        isEditing ? (
            <>
                <button
                    type="button"
                    data-testid="marital-furniture-save-list"
                    onClick={handleSave}
                    className="inline-flex min-h-[40px] items-center gap-1.5 rounded-xl border border-emerald-500/40 bg-emerald-500/15 px-3 py-1.5 text-[11px] font-bold text-emerald-200 hover:bg-emerald-500/25 touch-manipulation"
                >
                    حفظ
                </button>
                <button
                    type="button"
                    data-testid="marital-furniture-cancel-edit"
                    onClick={cancelEdit}
                    className="inline-flex min-h-[40px] items-center gap-1 rounded-xl border border-white/15 bg-white/5 px-3 py-1.5 text-[11px] font-bold text-slate-300 hover:bg-white/10 touch-manipulation"
                >
                    إلغاء
                </button>
            </>
        ) : deliveryRecorded && !canEditAfterDelivery ? null : (
            <button
                type="button"
                data-testid="marital-furniture-start-edit"
                onClick={startEdit}
                className="inline-flex min-h-[40px] items-center gap-1.5 rounded-xl border border-[#E6C673]/35 bg-[#E6C673]/10 px-3 py-1.5 text-[11px] font-bold text-[#E6C673] hover:bg-[#E6C673]/20 touch-manipulation"
            >
                <Pencil size={12} />
                {displayItems.length === 0 ? 'إضافة' : deliveryRecorded ? 'تعديل غير المُسلَّم' : 'تعديل'}
            </button>
        )
    ) : null;

    const workspaceBody = (
        <div className="space-y-4">
            {isEditing ? (
                <>
                    {deliveryRecorded ? (
                        <p className="text-[11px] text-amber-300/90 text-right rounded-xl border border-amber-500/20 bg-amber-500/5 px-3 py-2.5">
                            القطع المُسلَّمة مقفلة — يمكنك تعديل أو حذف غير المُسلَّم فقط.
                        </p>
                    ) : null}
                    <MaritalFurnitureSetupSection
                        items={draftItems}
                        onChange={setDraftItems}
                        formatCurrency={formatCurrency}
                        onPriceInput={(e, onParsed) => {
                            handleMoneyInputChange(e.target.value, (raw) => {
                                onParsed(parseMoneyInput(raw));
                            });
                        }}
                        isRowLocked={isDeliveredRowLocked}
                        allowAddRows={!deliveryRecorded}
                    />
                    <div className="rounded-xl border border-[#E6C673]/25 bg-[#E6C673]/8 px-4 py-3 text-right">
                        <p className="text-[10px] text-slate-400">المجموع الكلي (قبل الحفظ)</p>
                        <p className="text-xl font-black text-[#E6C673] font-mono">
                            {formatMaritalFurnitureIqd(editTotal)} <span className="text-xs">د.ع</span>
                        </p>
                    </div>
                </>
            ) : displayItems.length === 0 ? (
                <div className="rounded-2xl border border-white/10 bg-black/20 px-4 py-8 text-center">
                    <p className="text-sm text-slate-400">لم تُسجَّل قطع الأثاث بعد.</p>
                    {!locked ? (
                        <button
                            type="button"
                            onClick={startEdit}
                            className="mt-4 inline-flex min-h-[44px] items-center rounded-xl border border-[#E6C673]/35 bg-[#E6C673]/10 px-4 py-2 text-xs font-bold text-[#E6C673] hover:bg-[#E6C673]/20 touch-manipulation"
                        >
                            إضافة أول قطعة
                        </button>
                    ) : null}
                </div>
            ) : (
                <>
                    {canManageDelivery && (scheduleYmd || showScheduleForm) ? (
                        <div className="rounded-xl border border-sky-500/25 bg-sky-500/6 px-3 py-3 text-right space-y-2">
                            <p className="text-[11px] font-bold text-sky-200">موعد التسليم الميداني</p>
                            {showScheduleForm ? (
                                <div className="flex flex-col gap-2">
                                    <input
                                        type="date"
                                        value={scheduleYmdDraft || scheduleYmd}
                                        min={todayYmd}
                                        onChange={(e) => setScheduleYmdDraft(e.target.value)}
                                        className="w-full bg-black/30 border border-white/12 text-white text-sm px-3 py-2.5 rounded-xl focus:border-sky-400/45 outline-none text-right min-h-[44px]"
                                    />
                                    <div className="flex flex-row-reverse gap-2">
                                        <button
                                            type="button"
                                            data-testid="marital-furniture-save-schedule"
                                            disabled={savingSchedule || !(scheduleYmdDraft || scheduleYmd).trim()}
                                            onClick={handleSaveSchedule}
                                            className="inline-flex flex-1 min-h-[44px] items-center justify-center rounded-xl border border-sky-500/40 bg-sky-500/15 px-3 py-2 text-xs font-bold text-sky-100 hover:bg-sky-500/25 disabled:opacity-45 touch-manipulation"
                                        >
                                            حفظ الموعد
                                        </button>
                                        {scheduleYmd ? (
                                            <button
                                                type="button"
                                                onClick={() => {
                                                    setEditingSchedule(false);
                                                    setScheduleYmdDraft('');
                                                }}
                                                className="inline-flex min-h-[44px] items-center justify-center rounded-xl border border-white/12 bg-white/5 px-3 py-2 text-xs font-bold text-slate-300 hover:bg-white/10 touch-manipulation"
                                            >
                                                إلغاء
                                            </button>
                                        ) : null}
                                    </div>
                                </div>
                            ) : (
                                <div className="flex items-center gap-2 flex-row-reverse justify-between">
                                    <div className="flex items-center gap-2 flex-row-reverse min-w-0">
                                        <Calendar size={15} className="text-sky-300 shrink-0" />
                                        <p className="text-xs text-sky-100/95 leading-snug">{scheduleLabel}</p>
                                    </div>
                                    <button
                                        type="button"
                                        onClick={() => {
                                            setScheduleYmdDraft(scheduleYmd);
                                            setEditingSchedule(true);
                                        }}
                                        className="shrink-0 inline-flex min-h-[36px] items-center gap-1 rounded-lg border border-sky-500/30 bg-sky-500/10 px-2.5 py-1.5 text-[10px] font-bold text-sky-200 hover:bg-sky-500/18 touch-manipulation"
                                    >
                                        <Pencil size={11} />
                                        تعديل
                                    </button>
                                </div>
                            )}
                            {scheduleYmd &&
                            !showScheduleForm &&
                            !isScheduleYmdReached(scheduleYmd, todayYmd) &&
                            !earlyDeliveryUnlocked ? (
                                <button
                                    type="button"
                                    onClick={() => setEarlyDeliveryUnlocked(true)}
                                    className="w-full text-[10px] font-bold text-amber-300/90 underline underline-offset-2 text-right touch-manipulation min-h-[36px]"
                                >
                                    تفعيل التسليم قبل الموعد
                                </button>
                            ) : null}
                        </div>
                    ) : null}

                    {deliveryRecorded ? (
                        <div className="rounded-xl border border-white/10 bg-black/20 px-3 py-2.5 space-y-1 text-[11px]">
                            <p className="text-emerald-300/90">
                                مُسلَّم / خارجي: {deliveryCounts.delivered + deliveryCounts.external}{' '}
                                قطعة — {formatMaritalFurnitureIqd(deliveredTotal)} د.ع
                            </p>
                            <p className="text-rose-300/90">
                                تعذّر (المركز المالي): {deliveryCounts.failed} قطعة —{' '}
                                {formatMaritalFurnitureIqd(undeliveredTotal)} د.ع
                            </p>
                        </div>
                    ) : null}

                    {displayItems.length >= SEARCH_MIN ? (
                        <div className="relative">
                            <Search
                                size={15}
                                className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-500 pointer-events-none"
                            />
                            <input
                                type="search"
                                value={search}
                                onChange={(e) => setSearch(e.target.value)}
                                placeholder="بحث في قائمة الأثاث…"
                                className="w-full bg-black/30 border border-white/10 text-white text-sm pr-10 pl-3 py-2.5 rounded-xl focus:border-[#E6C673]/40 outline-none text-right min-h-[44px]"
                            />
                        </div>
                    ) : null}

                    <p className="text-[10px] text-slate-400 text-right leading-relaxed px-0.5">
                        {scheduleYmd && !isScheduleYmdReached(scheduleYmd, todayYmd) && !earlyDeliveryUnlocked
                            ? 'قبل الموعد: «تسليم خارجي» فقط — يُقفل الصف ولا يدخل المركز المالي.'
                            : 'بعد الموعد: «تسليم» أو «تعذّر» — التعذّر فقط ينتقل للمركز المالي.'}
                    </p>

                    <div className="overflow-hidden rounded-2xl border border-white/10">
                        <div className="max-h-[min(42vh,300px)] overflow-y-auto overscroll-contain">
                            <div
                                className={`sticky top-0 z-10 ${TABLE_GRID} py-2 bg-[#0A0F1C]/98 border-b border-white/10 text-[10px] font-bold text-slate-400 text-right backdrop-blur-sm items-center`}
                            >
                                <span>اسم الأثاث</span>
                                <span className="text-center">العدد</span>
                                <span>السعر</span>
                                <span>الإجمالي</span>
                                <span className="text-center">التسليم</span>
                            </div>
                            {visibleItems.length === 0 ? (
                                <p className="px-3 py-8 text-center text-sm text-slate-500">لا توجد نتائج</p>
                            ) : (
                                visibleItems.map((row) => {
                                    const rowDeliveryLocked =
                                        isMaritalFurnitureItemDeliveryLocked(row);
                                    return (
                                    <div
                                        key={row.id}
                                        className={`${TABLE_GRID} py-2.5 min-h-[44px] border-b border-white/5 text-right even:bg-white/[0.015] items-center ${
                                            rowDeliveryLocked
                                                ? 'bg-white/[0.02] opacity-90'
                                                : ''
                                        }`}
                                    >
                                        <span className="font-bold text-white text-[11px] leading-snug break-words min-w-0 flex items-start gap-1 justify-end">
                                            {rowDeliveryLocked ? (
                                                <Lock
                                                    size={10}
                                                    className="shrink-0 text-slate-500 mt-0.5"
                                                    aria-hidden
                                                />
                                            ) : null}
                                            <span className={rowDeliveryLocked ? 'text-slate-300' : ''}>
                                                {row.name}
                                            </span>
                                        </span>
                                        <span className="text-slate-300 font-mono text-[11px] text-center">
                                            {row.quantity}
                                        </span>
                                        <span className="text-slate-300 font-mono text-[10px] tabular-nums truncate">
                                            {formatMaritalFurnitureIqd(row.unitPriceIqd)}
                                        </span>
                                        <span className="text-[#E6C673] font-bold font-mono text-[10px] tabular-nums truncate">
                                            {formatMaritalFurnitureIqd(lineTotalIqd(row))}
                                        </span>
                                        <DeliveryRowActions
                                            row={row}
                                            scheduleYmd={scheduleYmd}
                                            todayYmd={todayYmd}
                                            earlyDeliveryUnlocked={earlyDeliveryUnlocked}
                                            busy={savingItemId === row.id}
                                            locked={locked}
                                            isPendingConfirm={
                                                pendingDelivery?.itemId === row.id
                                            }
                                            onConfirmPending={() => {
                                                if (pendingDelivery?.itemId === row.id) {
                                                    confirmPendingDelivery();
                                                }
                                            }}
                                            onCancelPending={() => {
                                                if (pendingDelivery?.itemId === row.id) {
                                                    setPendingDelivery(null);
                                                }
                                            }}
                                            onRequestOutcome={requestItemOutcome}
                                        />
                                    </div>
                                    );
                                })
                            )}
                        </div>
                    </div>

                    <div className="rounded-xl border border-[#E6C673]/25 bg-[#E6C673]/8 px-4 py-3 text-right space-y-1">
                        <p className="text-[10px] text-slate-400">المجموع الكلي للقائمة</p>
                        <p className="text-xl font-black text-[#E6C673] font-mono">
                            {formatMaritalFurnitureIqd(total)} <span className="text-xs">د.ع</span>
                        </p>
                        {deliveryRecorded ? (
                            <p className="text-[11px] text-rose-300/90 pt-1 border-t border-white/5">
                                المتبقي في المركز المالي:{' '}
                                <span className="font-bold font-mono">
                                    {formatMaritalFurnitureIqd(undeliveredTotal)} د.ع
                                </span>
                            </p>
                        ) : null}
                    </div>
                </>
            )}
        </div>
    );

    return (
        <>
            <MaritalFurnitureLauncherCard
                itemCount={displayItems.length}
                lockedCount={lockedDeliveryCount}
                totalLabel={formatMaritalFurnitureIqd(total)}
                scheduleHint={scheduleHint}
                onOpen={() => setWorkspaceOpen(true)}
                locked={locked}
            />
            <MaritalFurnitureWorkspaceSheet
                open={workspaceOpen}
                onClose={requestCloseWorkspace}
                headerActions={headerActions}
            >
                {workspaceBody}
            </MaritalFurnitureWorkspaceSheet>
        </>
    );
};

// @ts-nocheck
import React, { lazy, Suspense } from 'react';
import {
    Building2,
    ArrowUpLeft,
    ChevronDown,
    Gavel,
    Hammer,
    Package,
    Plane,
    Scale,
    Shield,
    ShieldAlert,
    UserX,
    Wallet,
    X,
} from 'lucide-react';
import {
    resolveOtherPartyRequestOptionBadges,
    type OtherPartyRequestBadge,
    type OtherPartyRequestOutcome,
} from '@/app/utils/otherPartyEffectiveRequestsUtils';
import type { CreditorMirrorWorkflowContext } from '@/app/utils/creditorOtherPartyMirrorVisibility';
import type { HiddenFollowupVisibilityInput, HiddenGuarantorContext } from './hiddenFollowupRequestsUtils';
import type { OtherPartyActionLogEntry, OtherPartyRequestTrackEntry } from '@/app/types/execution';

const ManualOtherPartyLogBlock = lazy(() => import('../../execution/OtherPartyActionsLog').then(mod => ({ default: mod.ManualOtherPartyLogBlock })));
import {
    mergeExternalTracksPreferLocalAdvance,
    patchOtherPartyRequestTrack,
    readOtherPartyRequestTracks,
    removeOtherPartyRequestTrack,
    trackMapByOptionId,
    tracksLogicalEqual,
    tracksLogicalSignature,
} from '@/app/utils/otherPartyRequestTrackUtils';
import { getLocalTodayYmd } from '@/app/utils/executionStateMachine';
import {
    readDecisionsForManualTrackSync,
    readDecisionsForManualTrackSyncEnriched,
    resolveManualTrackDisplayState,
    syncAllManualTracksFromDecisions,
    type ManualTrackDisplayState,
} from '@/app/utils/otherPartyManualTrackDecisionSync';
import {
    filterDecisionsForDomainContext,
    filterOtherPartyCatalogOptionIds,
    resolveExecutionDomainContext,
} from '@/app/utils/executionDomainIsolation';
import { WaiveInitialAppealButton } from '@/app/components/lawyer/DecisionsAndAppealsEngine/decisionCardPresentation';
import type { Decision } from '@/app/components/lawyer/DecisionsAndAppealsEngine/types';

export interface CreditorTrackDecisionHandlers {
    onSubmitCreditorRequest: (input: {
        optionId: string;
        label: string;
        date: string;
    }) => { ok: boolean; decisionId?: string };
    onResolveCreditorDecision: (input: {
        decisionId: string;
        resolution: 'approved' | 'rejected';
    }) => boolean;
    onOpenDecision?: (decisionId: string) => void;
    showMessage?: (message: string, type?: 'warning' | 'success') => void;
}

export interface OtherPartyEffectiveRequestsPanelProps {
    executionId: string | undefined;
    claimType: string;
    flags: HiddenFollowupVisibilityInput;
    guarantorCtx: HiddenGuarantorContext;
    activeDebtorKey?: string;
    primaryDebtorKey?: string;
    remainingBalanceIqd?: number;
    executionData?: import('@/app/types/execution').ExecutionFile | null;
    activeDebtorIsDeceased?: boolean;
    mirrorWorkflow?: CreditorMirrorWorkflowContext;
    debtorAgentManualTrack?: boolean;
    onPersistTracks?: (next: OtherPartyRequestTrackEntry[]) => void;
    onOpenAppeals?: (decisionId?: string) => void;
    creditorTrackHandlers?: CreditorTrackDecisionHandlers;
    manualLog?: {
        entries: OtherPartyActionLogEntry[];
        onPersist: (next: OtherPartyActionLogEntry[]) => void;
        onSubmitToDecisions: (input: { date: string; content: string }) => { ok: boolean; decisionId?: string };
        executionId?: string;
        appealPerspective?: import('@/app/components/lawyer/DecisionsAndAppealsEngine/appealUiLabels').AppealUiPerspective;
    };
}

const STATUS_CHIP: Record<OtherPartyRequestOutcome, string> = {
    available: 'border-sky-400/25 bg-sky-500/10 text-sky-100',
    effective: 'border-emerald-400/30 bg-emerald-500/12 text-emerald-100',
    pending: 'border-amber-400/30 bg-amber-500/12 text-amber-50',
    rejected: 'border-rose-400/25 bg-rose-500/10 text-rose-100',
    alternative: 'border-violet-400/25 bg-violet-500/10 text-violet-100',
    none: 'border-white/10 bg-white/5 text-slate-400',
};

const STATUS_ICON: Record<OtherPartyRequestOutcome, string> = {
    available: 'text-sky-300/80',
    effective: 'text-emerald-300/90',
    pending: 'text-amber-300/90',
    rejected: 'text-rose-300/90',
    alternative: 'text-violet-300/90',
    none: 'text-slate-500',
};

const STATUS_ACCENT: Record<OtherPartyRequestOutcome, string> = {
    available: 'border-r-sky-500/35',
    effective: 'border-r-emerald-500/45',
    pending: 'border-r-amber-500/40',
    rejected: 'border-r-rose-500/35',
    alternative: 'border-r-violet-500/35',
    none: 'border-r-white/10',
};

const BTN_PRIMARY =
    'inline-flex shrink-0 flex-row-reverse items-center gap-1 rounded-md border px-2 py-1 text-[9px] font-bold transition disabled:opacity-40';
const BTN_ROW =
    'inline-flex flex-1 flex-row-reverse items-center justify-center gap-1 rounded-md py-1.5 text-[9px] font-bold transition';

function CollapsibleTracksSection({
    title,
    subtitle,
    children,
    defaultExpanded = false,
}: {
    title: string;
    subtitle?: string;
    children: React.ReactNode;
    defaultExpanded?: boolean;
}) {
    const [expanded, setExpanded] = React.useState(defaultExpanded);
    return (
        <div className="overflow-hidden rounded-xl border border-white/10 bg-black/20">
            <button
                type="button"
                aria-expanded={expanded}
                onClick={() => setExpanded((v) => !v)}
                className="flex w-full flex-row-reverse items-center justify-between gap-2 border-b border-white/5 px-3 py-2 text-right transition hover:bg-white/[0.03]"
            >
                <ChevronDown
                    size={16}
                    className={`shrink-0 text-slate-400 transition-transform duration-200 ${expanded ? 'rotate-180' : ''}`}
                />
                <div className="min-w-0 flex-1">
                    <p className="text-[10px] font-bold text-slate-300">{title}</p>
                    {subtitle ? (
                        <p className="mt-0.5 text-[9px] text-slate-500">{subtitle}</p>
                    ) : null}
                </div>
            </button>
            {expanded ? <div className="p-2">{children}</div> : null}
        </div>
    );
}

function iconForBadge(id: string): React.ComponentType<{ size?: number; className?: string }> {
    if (id.startsWith('pc-forced_bring_in')) return UserX;
    if (id.startsWith('pc-travel_ban')) return Plane;
    if (id.startsWith('pc-arrest')) return ShieldAlert;
    if (id.startsWith('pc-executive_dossier')) return Scale;
    if (id.startsWith('pc-executive_detention')) return Gavel;
    if (id.includes('salary')) return Wallet;
    if (id.includes('property')) return Building2;
    if (id.includes('movable')) return Package;
    if (id.startsWith('gu-request') || id.startsWith('gu-guarantor')) return Shield;
    if (id.includes('break') || id.includes('Lock')) return Hammer;
    return Scale;
}

function ManualRequestBlock({
    badge,
    track,
    displayState,
    executionId,
    allDecisions,
    onUpdateTrack,
    onClearManualTrack,
    onOpenAppeals,
    creditorTrackHandlers,
}: {
    badge: OtherPartyRequestBadge;
    track: OtherPartyRequestTrackEntry | undefined;
    displayState: ManualTrackDisplayState;
    executionId: string | undefined;
    allDecisions: Decision[];
    onUpdateTrack: (patch: Partial<OtherPartyRequestTrackEntry>) => void;
    onClearManualTrack: () => void;
    onOpenAppeals?: (decisionId?: string) => void;
    creditorTrackHandlers?: CreditorTrackDecisionHandlers;
}) {
    const Icon = iconForBadge(badge.id);
    const [submitting, setSubmitting] = React.useState(false);
    const [resolving, setResolving] = React.useState<'approved' | 'rejected' | null>(null);
    const isClosed = displayState.phase === 'closed';
    const hasFooter =
        displayState.showExecutorVerdict || displayState.showAppealStrip || isClosed;
    const subtitle =
        displayState.phase === 'idle'
            ? 'لم يُسجَّل تقدّم بعد'
            : [displayState.statusShort, displayState.submittedDate].filter(Boolean).join(' · ');

    const applyOutcome = (value: 'approved' | 'rejected') => {
        if (resolving || !displayState.showExecutorVerdict) return;
        const decisionId = String(track?.decisionId || displayState.decisionId || '').trim();
        if (!decisionId || !creditorTrackHandlers) return;
        setResolving(value);
        try {
            const ok = creditorTrackHandlers.onResolveCreditorDecision({
                decisionId,
                resolution: value,
            });
            if (!ok) {
                creditorTrackHandlers.showMessage?.('تعذّر تسجيل قرار المنفذ — أعد المحاولة.', 'warning');
                return;
            }
            onUpdateTrack({
                label: badge.label,
                executorOutcome: value,
                submittedDate:
                    displayState.submittedDate || track?.submittedDate || getLocalTodayYmd(),
                decisionId,
            });
        } finally {
            setResolving(null);
        }
    };

    const handleCreditorSubmit = async () => {
        if (submitting) return;
        if (!displayState.showCreditorSubmit && !displayState.showResubmit) return;
        if (!creditorTrackHandlers) return;
        setSubmitting(true);
        const date = getLocalTodayYmd();
        const res = creditorTrackHandlers.onSubmitCreditorRequest({
            optionId: badge.id,
            label: badge.label,
            date,
        });
        if (!res.ok || !res.decisionId) {
            setSubmitting(false);
            return;
        }
        onUpdateTrack({
            label: badge.label,
            submittedDate: date,
            executorOutcome: 'submitted',
            decisionId: res.decisionId,
        });
        setSubmitting(false);
    };

    const handleOpenAppealsAndDismiss = () => {
        const decisionId =
            String(displayState.decisionId || track?.decisionId || '').trim() || undefined;
        onClearManualTrack();
        onOpenAppeals?.(decisionId);
    };

    return (
        <div
            className={`overflow-hidden rounded-lg border border-white/[0.07] border-r-2 bg-white/[0.02] ${STATUS_ACCENT[badge.outcome]}`}
        >
            <div className="flex flex-row-reverse items-center gap-2 px-2.5 py-2">
                <span
                    className={`flex h-7 w-7 shrink-0 items-center justify-center rounded-md border border-white/8 bg-black/25 ${STATUS_ICON[badge.outcome]}`}
                >
                    <Icon size={13} />
                </span>
                <div className="min-w-0 flex-1 text-right">
                    <p className="truncate text-[11px] font-semibold text-slate-100">{badge.label}</p>
                    <p className="truncate text-[9px] text-slate-500">{subtitle}</p>
                </div>
                {displayState.showCreditorSubmit ? (
                    <button
                        type="button"
                        disabled={submitting}
                        onClick={() => void handleCreditorSubmit()}
                        className={`${BTN_PRIMARY} border-sky-400/25 bg-sky-500/10 text-sky-100 hover:bg-sky-500/16`}
                    >
                        <ArrowUpLeft size={10} />
                        {submitting ? '…' : isClosed ? 'تقدّم جديد' : 'سجّل تقدّم الدائن'}
                    </button>
                ) : displayState.showResubmit ? (
                    <button
                        type="button"
                        disabled={submitting}
                        onClick={() => void handleCreditorSubmit()}
                        className={`${BTN_PRIMARY} border-amber-400/25 bg-amber-500/10 text-amber-50 hover:bg-amber-500/16`}
                    >
                        <ArrowUpLeft size={10} />
                        {submitting ? '…' : 'طلب جديد'}
                    </button>
                ) : (
                    <span
                        className={`shrink-0 rounded-md border px-1.5 py-0.5 text-[8px] font-bold ${STATUS_CHIP[badge.outcome]}`}
                    >
                        {displayState.statusShort}
                    </span>
                )}
            </div>

            {hasFooter ? (
                <div className="space-y-1.5 border-t border-white/5 bg-black/10 px-2.5 py-1.5 text-right">
                    {displayState.showExecutorVerdict ? (
                        <div className="flex flex-row-reverse items-center gap-1.5">
                            <button
                                type="button"
                                disabled={Boolean(resolving)}
                                onClick={(e) => {
                                    e.stopPropagation();
                                    applyOutcome('approved');
                                }}
                                className={`${BTN_ROW} bg-emerald-500/10 text-emerald-100 hover:bg-emerald-500/16 disabled:pointer-events-none disabled:opacity-40`}
                            >
                                <Scale size={10} />
                                {resolving === 'approved' ? '…' : 'موافق'}
                            </button>
                            <button
                                type="button"
                                disabled={Boolean(resolving)}
                                onClick={(e) => {
                                    e.stopPropagation();
                                    applyOutcome('rejected');
                                }}
                                className={`${BTN_ROW} bg-rose-500/8 text-rose-100 hover:bg-rose-500/14 disabled:pointer-events-none disabled:opacity-40`}
                            >
                                <X size={10} />
                                {resolving === 'rejected' ? '…' : 'رفض'}
                            </button>
                            {displayState.decisionId && creditorTrackHandlers?.onOpenDecision ? (
                                <button
                                    type="button"
                                    onClick={() =>
                                        creditorTrackHandlers.onOpenDecision!(displayState.decisionId!)
                                    }
                                    className="shrink-0 rounded-md border border-white/10 px-2 py-1.5 text-[8px] font-bold text-slate-400 hover:text-slate-200"
                                >
                                    البطاقة
                                </button>
                            ) : null}
                        </div>
                    ) : null}

                    {displayState.showAppealStrip ? (
                        <>
                            <p className="text-[9px] leading-snug text-rose-100/90">
                                قرار نافذ — يحق التظلم أو الطعن خلال المدة النظامية.
                            </p>
                            <div className="flex flex-row-reverse gap-1.5">
                                {onOpenAppeals ? (
                                    <button
                                        type="button"
                                        onClick={handleOpenAppealsAndDismiss}
                                        className={`${BTN_ROW} border border-[#E6C673]/30 bg-[#E6C673]/10 text-[#F5E6A8] hover:bg-[#E6C673]/16`}
                                    >
                                        القرارات والطعون
                                    </button>
                                ) : null}
                                <div className="flex flex-1 [&>button]:w-full [&>button]:rounded-md [&>button]:border-white/10 [&>button]:bg-white/5 [&>button]:py-1.5 [&>button]:text-[9px] [&>button]:font-bold [&>button]:text-slate-300 [&>button]:hover:bg-white/10">
                                    <WaiveInitialAppealButton
                                        executionId={executionId}
                                        decisionId={String(
                                            displayState.decisionId || track?.decisionId || ''
                                        ).trim()}
                                        allDecisions={allDecisions}
                                        onApplied={(result) => {
                                            if (!result.ok) {
                                                creditorTrackHandlers?.showMessage?.(
                                                    result.message ??
                                                        'تعذّر تسجيل الاستغناء عن الطعن.',
                                                    'warning'
                                                );
                                                return;
                                            }
                                            creditorTrackHandlers?.showMessage?.(
                                                result.message ??
                                                    'لا حاجة للطعن — أُغلقت دورة الطلب.',
                                                'success'
                                            );
                                        }}
                                    />
                                </div>
                            </div>
                        </>
                    ) : null}

                    {isClosed ? (
                        <p className="text-[9px] text-slate-400">
                            لم يعد نافذاً — يمكن تسجيل تقدّم جديد.
                        </p>
                    ) : null}
                </div>
            ) : null}
        </div>
    );
}

export const OtherPartyEffectiveRequestsPanel: React.FC<OtherPartyEffectiveRequestsPanelProps> = ({
    executionId,
    claimType,
    flags,
    guarantorCtx,
    activeDebtorKey,
    primaryDebtorKey,
    remainingBalanceIqd,
    executionData,
    activeDebtorIsDeceased = false,
    mirrorWorkflow,
    debtorAgentManualTrack = false,
    onPersistTracks,
    onOpenAppeals,
    creditorTrackHandlers,
    manualLog,
}) => {
    const externalTracks = React.useMemo(
        () => readOtherPartyRequestTracks(executionData),
        [executionData?.other_party_request_tracks]
    );
    const externalTracksSig = React.useMemo(
        () => tracksLogicalSignature(externalTracks),
        [externalTracks]
    );
    const [tracks, setTracks] = React.useState<OtherPartyRequestTrackEntry[]>(externalTracks);
    const [decisionsTick, setDecisionsTick] = React.useState(0);
    const onPersistTracksRef = React.useRef(onPersistTracks);
    const skipExternalTracksMergeRef = React.useRef(false);
    const catalogOptionIdsRef = React.useRef<string[]>([]);
    const catalogLabelsByIdRef = React.useRef<Map<string, string>>(new Map());
    onPersistTracksRef.current = onPersistTracks;

    React.useEffect(() => {
        if (skipExternalTracksMergeRef.current) {
            skipExternalTracksMergeRef.current = false;
            return;
        }
        setTracks((prev) => {
            const merged = mergeExternalTracksPreferLocalAdvance(prev, externalTracks);
            return tracksLogicalEqual(merged, prev) ? prev : merged;
        });
    }, [externalTracksSig]);

    const domainContext = React.useMemo(
        () => resolveExecutionDomainContext(executionData ?? null, executionId),
        [executionData, executionId]
    );

    const decisions = React.useMemo(() => {
        const raw = readDecisionsForManualTrackSyncEnriched(executionId, tracks);
        return filterDecisionsForDomainContext(domainContext, raw);
    }, [executionId, decisionsTick, tracks, domainContext]);

    const catalogOptions = React.useMemo(() => {
        const all = resolveOtherPartyRequestOptionBadges({
            claimType,
            flags,
            guarantorCtx,
            decisions: [],
            activeDebtorKey,
            primaryDebtorKey,
            remainingBalanceIqd,
            executionData,
            activeDebtorIsDeceased,
            mirrorWorkflow,
            debtorAgentManualTrack,
        });
        if (!debtorAgentManualTrack) return all;
        const allowedIds = new Set(
            filterOtherPartyCatalogOptionIds(
                domainContext,
                all.map((b) => b.id)
            )
        );
        return all.filter((b) => allowedIds.has(b.id));
    }, [
        claimType,
        flags,
        guarantorCtx,
        activeDebtorKey,
        primaryDebtorKey,
        remainingBalanceIqd,
        executionData,
        activeDebtorIsDeceased,
        mirrorWorkflow,
        debtorAgentManualTrack,
        domainContext,
    ]);

    const catalogLabelsById = React.useMemo(() => {
        const map = new Map<string, string>();
        for (const badge of catalogOptions) map.set(badge.id, badge.label);
        return map;
    }, [catalogOptions]);

    const catalogOptionIds = React.useMemo(
        () => catalogOptions.map((b) => b.id),
        [catalogOptions]
    );
    catalogOptionIdsRef.current = catalogOptionIds;
    catalogLabelsByIdRef.current = catalogLabelsById;

    React.useEffect(() => {
        if (!debtorAgentManualTrack) return;

        const onDecisionChange = () => {
            setDecisionsTick((n) => n + 1);
            setTracks((prev) => {
                const nextDecisions = readDecisionsForManualTrackSyncEnriched(executionId, prev);
                const synced = syncAllManualTracksFromDecisions(
                    prev,
                    nextDecisions,
                    catalogOptionIdsRef.current,
                    catalogLabelsByIdRef.current,
                    executionId
                );
                if (tracksLogicalEqual(synced, prev)) return prev;
                skipExternalTracksMergeRef.current = true;
                onPersistTracksRef.current?.(synced);
                return synced;
            });
        };

        window.addEventListener('hami-decisions-reload', onDecisionChange);
        window.addEventListener('hami-execution-decision-outcome', onDecisionChange);
        return () => {
            window.removeEventListener('hami-decisions-reload', onDecisionChange);
            window.removeEventListener('hami-execution-decision-outcome', onDecisionChange);
        };
    }, [debtorAgentManualTrack, executionId]);

    const trackById = React.useMemo(() => trackMapByOptionId(tracks), [tracks]);

    const displayStateById = React.useMemo(() => {
        const map = new Map<string, ManualTrackDisplayState>();
        for (const badge of catalogOptions) {
            map.set(
                badge.id,
                resolveManualTrackDisplayState(
                    decisions,
                    trackById.get(badge.id),
                    badge.id,
                    executionId
                )
            );
        }
        return map;
    }, [catalogOptions, trackById, decisions]);

    const displayOptions = React.useMemo(() => {
        if (!debtorAgentManualTrack) return catalogOptions;
        return catalogOptions.map((badge) => {
            const display = displayStateById.get(badge.id)!;
            return {
                ...badge,
                outcome: display.badgeOutcome,
                statusShort: display.statusShort,
                hasRequest: display.phase !== 'idle',
            };
        });
    }, [catalogOptions, debtorAgentManualTrack, displayStateById]);

    const updateTrack = React.useCallback(
        (optionId: string, patch: Partial<OtherPartyRequestTrackEntry>) => {
            setTracks((prev) => {
                const next = patchOtherPartyRequestTrack(prev, optionId, patch);
                if (tracksLogicalEqual(next, prev)) return prev;
                skipExternalTracksMergeRef.current = true;
                onPersistTracksRef.current?.(next);
                return next;
            });
            if (
                patch.executorOutcome === 'submitted' ||
                patch.executorOutcome === 'approved' ||
                patch.executorOutcome === 'rejected' ||
                patch.executorOutcome === 'alternative'
            ) {
                setDecisionsTick((n) => n + 1);
            }
        },
        []
    );

    const clearManualTrack = React.useCallback((optionId: string) => {
        setTracks((prev) => {
            const next = removeOtherPartyRequestTrack(prev, optionId);
            if (tracksLogicalEqual(next, prev)) return prev;
            skipExternalTracksMergeRef.current = true;
            onPersistTracksRef.current?.(next);
            return next;
        });
    }, []);

    const manualTrackBlocks =
        displayOptions.length === 0 ? (
            <p className="py-6 text-center text-[11px] text-slate-400">
                {debtorAgentManualTrack
                    ? 'لا تحركات ظاهرة للدائن في هذه المرحلة.'
                    : 'لا طلبات ظاهرة في هذه المرحلة.'}
            </p>
        ) : (
            <div className="space-y-1">
                {displayOptions.map((badge) =>
                    debtorAgentManualTrack ? (
                        <ManualRequestBlock
                            key={badge.id}
                            badge={badge}
                            track={trackById.get(badge.id)}
                            displayState={displayStateById.get(badge.id)!}
                            executionId={executionId}
                            allDecisions={decisions as Decision[]}
                            onUpdateTrack={(patch) => updateTrack(badge.id, patch)}
                            onClearManualTrack={() => clearManualTrack(badge.id)}
                            onOpenAppeals={onOpenAppeals}
                            creditorTrackHandlers={creditorTrackHandlers}
                        />
                    ) : null
                )}
            </div>
        );

    const manualLogBlock = manualLog ? (
        <Suspense fallback={null}>
            <ManualOtherPartyLogBlock
                entries={manualLog.entries}
                onPersist={manualLog.onPersist}
                onSubmitToDecisions={manualLog.onSubmitToDecisions}
                hideSavedEntries={debtorAgentManualTrack}
                executionId={manualLog.executionId || executionId}
                appealPerspective={manualLog.appealPerspective}
            />
        </Suspense>
    ) : null;

    if (displayOptions.length === 0 && !manualLog) {
        return (
            <p className="py-6 text-center text-[11px] text-slate-400">
                لا طلبات ظاهرة في هذه المرحلة.
            </p>
        );
    }

    const tracksSectionTitle = mirrorWorkflow
        ? 'تتبّع تحركات الدائن يدوياً'
        : 'تحركات الدائن';
    const tracksSectionSubtitle = mirrorWorkflow
        ? 'سجّل تقدّم الدائن ثم موافقة أو رفض المنفذ.'
        : undefined;

    const tracksPanel =
        debtorAgentManualTrack && displayOptions.length > 0 ? (
            <CollapsibleTracksSection
                title={tracksSectionTitle}
                subtitle={tracksSectionSubtitle}
            >
                {manualTrackBlocks}
            </CollapsibleTracksSection>
        ) : (
            manualTrackBlocks
        );

    return (
        <div className="space-y-2">
            {tracksPanel}
            {manualLogBlock}
        </div>
    );
};

import React, { Suspense, useCallback, useMemo } from 'react';
import { OtherPartyEffectiveRequestsPanel } from './OtherPartyEffectiveRequestsPanel';
import type { OtherPartyEffectiveRequestsPanelProps, CreditorTrackDecisionHandlers } from './OtherPartyEffectiveRequestsPanel';
import type { OtherPartyActionLogEntry, OtherPartyRequestTrackEntry } from '@/app/types/execution';
import type { AppealUiPerspective } from '@/app/components/lawyer/DecisionsAndAppealsEngine/appealUiLabels';

export interface OtherPartyTabProps {
    executionData: Record<string, any> | null | undefined;
    decisionsStorageExecutionId?: string;
    persistExecutionMerge: (patch: Record<string, unknown>) => void;
    handleOtherPartyActionSubmitToDecisions: (input: { date: string; content: string }) => { ok: boolean; decisionId?: string };
    EXEC_OVERLAY_LAZY_FALLBACK: React.ReactNode;
    LazyOtherPartyActionsLog: React.LazyExoticComponent<React.ComponentType<any>>;
    appealPerspective?: AppealUiPerspective;
    showCreditorRequestsMirror?: boolean;
    creditorRequestsMirror?: Omit<
        OtherPartyEffectiveRequestsPanelProps,
        'manualLog' | 'onPersistTracks' | 'debtorAgentManualTrack' | 'creditorTrackHandlers'
    >;
    onOpenAppeals?: (decisionId?: string) => void;
    creditorTrackHandlers?: CreditorTrackDecisionHandlers;
}

const EMPTY_OTHER_PARTY_LOG: OtherPartyActionLogEntry[] = [];

export const OtherPartyTab: React.FC<OtherPartyTabProps> = ({
    executionData,
    decisionsStorageExecutionId,
    persistExecutionMerge,
    handleOtherPartyActionSubmitToDecisions,
    EXEC_OVERLAY_LAZY_FALLBACK,
    LazyOtherPartyActionsLog,
    showCreditorRequestsMirror = false,
    creditorRequestsMirror,
    onOpenAppeals,
    creditorTrackHandlers,
    appealPerspective = 'creditor_agent',
}) => {
    const decisionsExecutionId = String(
        decisionsStorageExecutionId || executionData?.id || ''
    ).trim();
    const manualEntries = (executionData?.other_party_actions_log ??
        EMPTY_OTHER_PARTY_LOG) as OtherPartyActionLogEntry[];

    const persistTracks = useCallback(
        (next: OtherPartyRequestTrackEntry[]) => {
            persistExecutionMerge({ other_party_request_tracks: next });
        },
        [persistExecutionMerge]
    );

    const persistManualLog = useCallback(
        (next: OtherPartyActionLogEntry[]) => {
            persistExecutionMerge({ other_party_actions_log: next });
        },
        [persistExecutionMerge]
    );

    const manualLog = useMemo(
        () => ({
            entries: manualEntries,
            onPersist: persistManualLog,
            onSubmitToDecisions: handleOtherPartyActionSubmitToDecisions,
            executionId: decisionsExecutionId,
            appealPerspective,
        }),
        [
            appealPerspective,
            decisionsExecutionId,
            manualEntries,
            persistManualLog,
            handleOtherPartyActionSubmitToDecisions,
        ]
    );

    if (showCreditorRequestsMirror && creditorRequestsMirror) {
        return (
            <div className="p-2 md:p-3" onClick={(e) => e.stopPropagation()}>
                <OtherPartyEffectiveRequestsPanel
                    {...creditorRequestsMirror}
                    debtorAgentManualTrack
                    onOpenAppeals={onOpenAppeals}
                    creditorTrackHandlers={creditorTrackHandlers}
                    onPersistTracks={persistTracks}
                    manualLog={manualLog}
                />
            </div>
        );
    }

    return (
        <div className="space-y-4 p-4" onClick={(e) => e.stopPropagation()}>
            <Suspense fallback={EXEC_OVERLAY_LAZY_FALLBACK}>
                <LazyOtherPartyActionsLog
                    entries={manualEntries}
                    onPersist={persistManualLog}
                    onSubmitToDecisions={handleOtherPartyActionSubmitToDecisions}
                    executionId={decisionsExecutionId}
                    appealPerspective={appealPerspective}
                />
            </Suspense>
        </div>
    );
};

