export interface TimelineEditModalProps {
    /** حالة ظهور النافذة */
    visible: boolean;
    /** حدث السجل الحالي للتحرير */
    timelineEvent: TimelineEvent | null;
    /** دالة إغلاق النافذة */
    onClose: () => void;
    /** دالة حفظ التعديلات */
    onSave: (event: TimelineEvent) => void;
    /** دالة حذف الحدث */
    onDelete: (id: string) => void;
}

