/**
 * نموذج قرارات المخاطبات — predicates + عرض الحالة (منطق خالص).
 */
import {
    isExecutorRowRejectedAndFinal,
} from '@/app/utils/executorSeizureDecisionQueue';
import { isExecutorRowApprovedWorkflowActive } from '@/app/utils/executorRequestAppealSync';

export const COMMUNICATION_KEYWORD = 'إرسال كتاب / مخاطبة جهة';

export function isCommunicationDecision(decision: any): boolean {
    const t = String(decision?.title || '');
    return t.includes(COMMUNICATION_KEYWORD) || /مخاطبة جهة/i.test(t);
}

export function hasResult(decision: any): boolean {
    return Boolean(decision?.deputationResultDetails) || decision?.deputationClosed === true;
}

export function isFollowupDismissed(decision: any): boolean {
    return decision?.deputationFollowupDismissed === true;
}

export function isNoResponseConfirmed(decision: any): boolean {
    return decision?.deputationNoResponseConfirmed === true;
}

export function isCommunicationFollowupComplete(decision: any): boolean {
    return hasResult(decision) || isFollowupDismissed(decision) || isNoResponseConfirmed(decision);
}

export function isAwaitingCommunicationResult(
    decision: any,
    decisionRows: Record<string, unknown>[],
): boolean {
    const rejected = isExecutorRowRejectedAndFinal(decision);
    const approved = isExecutorRowApprovedWorkflowActive(decision, decisionRows);
    return approved && !rejected && !isCommunicationFollowupComplete(decision);
}

export type CommunicationDisplayContext = {
    directorate: string;
    statusLabel: string;
    statusTone: 'success' | 'warning' | 'danger' | 'neutral' | 'muted';
    requestDate: string;
    referenceLabel: string;
    /** عنوان حاوية المرجع (إجابة واردة أو كتاب تأكيد) */
    referenceTitle: string;
    outcomeTitle: string;
    outcomeBody: string;
};

/** نص نتيجة «عدم ورود إجابة» — يشير إلى الكتاب السابق وتاريخه */
export function buildNoResponseConfirmationDetails(input: {
    previousLetterDate?: string;
    confirmationDate?: string;
}): string {
    const prev = String(input.previousLetterDate || '').trim().slice(0, 10);
    const conf = String(input.confirmationDate || '').trim().slice(0, 10);
    const onPrev = prev
        ? `تم التأكيد على الكتاب السابق المؤرّخ في ${prev}`
        : 'تم التأكيد على الكتاب السابق';
    const base = `${onPrev} — عدم ورود إجابة من الجهة المخاطبة.`;
    if (!conf) return base;
    return `${base}\nتاريخ كتاب التأكيد: ${conf}`;
}

export function buildCommunicationDisplayContext(
    decision: any,
    decisionRows: Record<string, unknown>[],
): CommunicationDisplayContext {
    const title = String(decision?.title || '').trim() || COMMUNICATION_KEYWORD;
    const directorateFromTitle = title.includes('— ')
        ? title.split('— ').slice(1).join('— ').trim()
        : title;
    const directorate =
        String(decision?.deputationTargetDirectorate || '').trim() || directorateFromTitle;
    const rejected = isExecutorRowRejectedAndFinal(decision);
    const approved = isExecutorRowApprovedWorkflowActive(decision, decisionRows);
    const pending =
        String(decision?.executorOutcome ?? 'pending') === 'pending' ||
        String(decision?.executorOutcome ?? '') === '';
    const dismissed = isFollowupDismissed(decision);
    const noResponse = isNoResponseConfirmed(decision);
    const hasRes = hasResult(decision);
    const requestDate = String(decision?.date || decision?.resolvedAt || '').trim().slice(0, 10);
    const referenceLabel = String(decision?.deputationReferralDate || '').trim();

    let statusLabel = '—';
    let statusTone: CommunicationDisplayContext['statusTone'] = 'neutral';
    if (rejected) {
        statusLabel = 'مرفوض';
        statusTone = 'danger';
    } else if (pending) {
        statusLabel = 'قيد البت';
        statusTone = 'warning';
    } else if (approved) {
        if (noResponse) {
            statusLabel = 'موافق — عدم ورود إجابة';
            statusTone = 'warning';
        } else if (dismissed) {
            statusLabel = 'موافق — مُتجاهَل';
            statusTone = 'muted';
        } else if (hasRes && String(decision?.deputationResultDetails || '').trim()) {
            statusLabel = 'مكتمل';
            statusTone = 'success';
        } else {
            statusLabel = 'موافق — بانتظار النتيجة';
            statusTone = 'warning';
        }
    }

    let outcomeTitle = 'مضمون الإجابة';
    let outcomeBody = String(decision?.deputationResultDetails || '').trim();
    let referenceTitle = 'مرجع الإجابة';
    if (noResponse) {
        outcomeTitle = 'النتيجة';
        outcomeBody =
            outcomeBody ||
            buildNoResponseConfirmationDetails({
                previousLetterDate: requestDate,
                confirmationDate: referenceLabel,
            });
        referenceTitle = 'تاريخ كتاب التأكيد';
    } else if (dismissed) {
        outcomeTitle = 'المتابعة';
        outcomeBody = outcomeBody || 'تم تجاهل متابعة نتيجة المخاطبة.';
    } else if (rejected) {
        outcomeTitle = 'ملاحظة';
        outcomeBody =
            String(decision?.executorNote || decision?.body || '').trim() ||
            'تم رفض الطلب من قبل المنفذ.';
    } else if (!outcomeBody) {
        outcomeTitle = 'تفاصيل الطلب';
        outcomeBody = String(decision?.body || '').trim() || '—';
    }

    return {
        directorate,
        statusLabel,
        statusTone,
        requestDate,
        referenceLabel,
        referenceTitle,
        outcomeTitle,
        outcomeBody,
    };
}

export const STATUS_TONE_CLASS: Record<CommunicationDisplayContext['statusTone'], string> = {
    success: 'border-emerald-500/35 bg-emerald-500/10 text-emerald-100',
    warning: 'border-amber-500/35 bg-amber-500/10 text-amber-100',
    danger: 'border-rose-500/35 bg-rose-500/10 text-rose-100',
    neutral: 'border-slate-500/35 bg-slate-500/10 text-slate-200',
    muted: 'border-slate-600/35 bg-slate-800/50 text-slate-400',
};

export function extractDirectorate(title: string): string {
    if (!title.includes('— ')) return title;
    return title.split('— ').slice(1).join('— ').trim() || title;
}

import React from 'react';
import {
    ExecutionInlineExecutorDecisionActions,
    type ExecutionInlineStep,
} from '@/app/components/lawyer/ExecutionDashboard/components/ExecutionInlineAccordion';
import { isExecutorRowRejectedAndFinal } from '@/app/utils/executorSeizureDecisionQueue';
import { isExecutorRowApprovedWorkflowActive } from '@/app/utils/executorRequestAppealSync';

export function SeizureDecisionInlineActions(props: {
    row: any;
    requestKind: string;
    resolvedExecutionId: string;
    onOpenAppeals: (decisionId: string) => void;
}): React.ReactNode {
    const { row, requestKind, resolvedExecutionId, onOpenAppeals } = props;
    if (!row?.id) return null;
    const decisionId = String(row.id || '').trim();
    if (!decisionId) return null;
    const rejected = isExecutorRowRejectedAndFinal(row);
    const pending =
        String(row.executorOutcome ?? 'pending') === 'pending' ||
        String(row.executorOutcome ?? '') === '';
    if (!pending && !rejected) return null;
    if (rejected) {
        return (
            <div className="rounded-2xl border border-rose-500/30 bg-rose-950/20 p-3">
                <p className="text-[11px] font-black text-rose-200 text-right">
                    تم رفض الطلب من قبل المنفذ
                </p>
                <div className="mt-2">
                    <ExecutionInlineExecutorDecisionActions
                        executionId={resolvedExecutionId}
                        decisionId={decisionId}
                        requestKind={requestKind}
                        disabled
                        onOpenAppealCenter={() => onOpenAppeals(decisionId)}
                    />
                </div>
            </div>
        );
    }
    return (
        <ExecutionInlineExecutorDecisionActions
            executionId={resolvedExecutionId}
            decisionId={decisionId}
            requestKind={requestKind}
        />
    );
}

export function buildSeizureRequestSteps(args: {
    title: string;
    row: any;
    requestKind: string;
    decisions: Record<string, unknown>[];
    resolvedExecutionId: string;
    onOpenAppeals: (decisionId: string) => void;
    extra?: React.ReactNode;
}): ExecutionInlineStep[] {
    const { title, row, requestKind, decisions, resolvedExecutionId, onOpenAppeals, extra } = args;
    const hasRow = Boolean(row?.id);
    const rejected = hasRow ? isExecutorRowRejectedAndFinal(row) : false;
    const approved = hasRow ? isExecutorRowApprovedWorkflowActive(row, decisions) : false;
    const pending = hasRow
        ? String(row.executorOutcome ?? 'pending') === 'pending' ||
          String(row.executorOutcome ?? '') === ''
        : false;
    return [
        {
            id: `${title}:submit`,
            title,
            subtitle: hasRow ? 'تم إرسال الطلب إلى سلطة المنفذ' : 'لم يتم إرسال الطلب بعد',
            status: hasRow ? 'done' : 'active',
            tone: hasRow ? 'success' : 'neutral',
        } satisfies ExecutionInlineStep,
        {
            id: `${title}:executor`,
            title: 'قرار المنفذ',
            subtitle: rejected
                ? 'تم رفض الطلب'
                : approved
                  ? 'تمت الموافقة'
                  : pending
                    ? 'قيد البت'
                    : '—',
            status: rejected ? 'active' : pending ? 'active' : hasRow ? 'done' : 'locked',
            tone: rejected ? 'danger' : approved ? 'success' : 'neutral',
            content: hasRow ? (
                <SeizureDecisionInlineActions
                    row={row}
                    requestKind={requestKind}
                    resolvedExecutionId={resolvedExecutionId}
                    onOpenAppeals={onOpenAppeals}
                />
            ) : null,
        } satisfies ExecutionInlineStep,
        ...(extra
            ? [
                  {
                      id: `${title}:details`,
                      title: 'إكمال البيانات',
                      subtitle: 'حقول مدمجة داخل نفس البطاقة',
                      status: approved && !rejected ? 'active' : 'locked',
                      tone: approved && !rejected ? 'neutral' : 'neutral',
                      content: approved && !rejected ? extra : null,
                  } satisfies ExecutionInlineStep,
              ]
            : []),
    ];
}

import type { SeizureRequestSubtype } from '@/app/utils/executorDecisionContracts';
import {
    getGoverningSeizureDecisionBySubtype,
    isExecutorHubRowInactiveForGoverning,
    isExecutorRowRejectedAndFinal,
} from '@/app/utils/executorSeizureDecisionQueue';
import { isExecutorRowApprovedWorkflowActive } from '@/app/utils/executorRequestAppealSync';

export function resolveGoverningSalaryDecision(
    resolvedExecutionId: string,
    decisions: Record<string, unknown>[]
): any | null {
    const bySubtype = getGoverningSeizureDecisionBySubtype(
        resolvedExecutionId,
        'salary',
        decisions
    );
    if (bySubtype) return bySubtype as any;

    const isGuarantorRelated = (txt: string) => /الكفيل|كفيل/i.test(String(txt || ''));
    const isSalaryRelated = (txt: string) =>
        /حجز\s*راتب|حجز\s*الحوافز|الحوافز|المخصصات|الراتب/i.test(String(txt || ''));

    const candidates = decisions.filter((r) => {
        const rk = String((r as any)?.requestKind || '').trim();
        const rid = String((r as any)?.id || '').trim();
        const isSeizureLike = rk === 'seizure' || (!rk && /^seizure_req_/i.test(rid));
        if (!isSeizureLike) return false;
        const st = String((r as any)?.seizureSubtype || '').trim();
        if (st && st !== 'salary') return false;
        const title = String((r as any)?.title || '');
        const body = String((r as any)?.body || '');
        if (isGuarantorRelated(title) || isGuarantorRelated(body)) return false;
        return isSalaryRelated(title) || isSalaryRelated(body);
    });
    if (candidates.length === 0) return null;
    const first = candidates[0] as any;
    return candidates.reduce((acc: any, cur: any) => {
        const a = String(acc?.resolvedAt ?? acc?.date ?? '');
        const b = String(cur?.resolvedAt ?? cur?.date ?? '');
        return b.localeCompare(a, undefined, { numeric: true }) > 0 ? cur : acc;
    }, first) as any;
}

export function isSeizureRequestFullyRegistered(
    row: any,
    allDecisions: Record<string, unknown>[]
): boolean {
    if (!row?.id) return false;
    if (isExecutorRowRejectedAndFinal(row)) return false;
    if (isExecutorHubRowInactiveForGoverning(row, allDecisions)) return false;
    if (!isExecutorRowApprovedWorkflowActive(row, allDecisions)) return false;
    return Boolean(String(row.seizureRequestSavedAt || '').trim());
}

/** اكتمال التسجيل — يبقى زر «السجل» ظاهراً حتى أثناء الطعن */
export function isSeizureRegistrationComplete(
    row: any,
    allDecisions: Record<string, unknown>[]
): boolean {
    if (!row?.id) return false;
    if (isExecutorRowRejectedAndFinal(row)) return false;
    if (isExecutorHubRowInactiveForGoverning(row, allDecisions)) return false;
    return Boolean(String(row.seizureRequestSavedAt || '').trim());
}

export type UnifiedSeizureLogTab = 'movable' | 'property' | 'third_party' | 'salary';

export const SEIZURE_LOG_TAB_SUBTYPE: Record<UnifiedSeizureLogTab, SeizureRequestSubtype> = {
    movable: 'movable_auction',
    third_party: 'third_party',
    property: 'property',
