            actionType === 'vehicle'
                ? JSON.stringify({
                      movableDescription: String(details.movableDescription || '').trim(),
                      movableLocation: String(details.movableLocation || '').trim(),
                      judicialCustodianName: String(details.judicialCustodianName || '').trim(),
                      subject: String(label || '').trim(),
                  })
                : undefined;
        seizureDecisionId = appendPendingSeizureDecisionLite({
            executionId: decisionsStorageExecutionId,
            requestTitle: `${label} — قيد البت لدى المنفذ`,
            requestBody: seizureBody,
            seizureSubtype:
                actionType === 'salary' ? 'salary' : actionType === 'vehicle' ? ('movable_auction' as any) : 'property',
            ...(payloadJson ? { seizurePayloadJson: payloadJson } : {}),
        });
    }

    const newEvent: TimelineEvent = {
        id: nextTimelineId(),
        date: now,
        timestamp: now,
        title: isSeizureRequest ? `📋 ${label} — قيد البت` : `⚖️ ${label}`,
        description: isSeizureRequest
            ? [`طلب ${label} بشأن المدين${subj.name ? ` (${subj.name})` : ''}.`, descWithRouting.trim() || null]
                  .filter(Boolean)
                  .join('\n')
            : `${label}.${descWithRouting ? ` ${descWithRouting}` : ''}`,
        type: 'coercive',
        source: 'التنفيذ والمحجوزات',
        metadata:
            seizureDecisionId != null
                ? {
                      timelineThreadKey: `executor_decision:${seizureDecisionId}`,
                      decisionRowId: seizureDecisionId,
                  }
                : undefined,
    };
    let nextDrafts = seizureDraftsByDecisionId;
    if (isSeizureRequest && seizureDecisionId) {
        const dayYmd = now.slice(0, 10);
        const detailsWithDecision: Record<string, string> = {
            ...details,
            decisionRowId: seizureDecisionId,
        };
        const newAsset: SeizedAsset = {
            id: `draft_${seizureDecisionId}`,
            type:
                actionType === 'salary'
                    ? 'طلب حجز راتب (قيد البت)'
                    : actionType === 'vehicle'
                      ? 'طلب حجز مال منقول (قيد البت)'
                      : 'طلب حجز عقار (قيد البت)',
            details: detailsWithDecision,
            status: 'pending',
            seizureDate: dayYmd,
        };
        if (details.description?.trim()) {
            newAsset.description = details.description.trim();
        }
        nextDrafts = { ...seizureDraftsByDecisionId, [seizureDecisionId]: newAsset };
        setSeizureDraftsByDecisionId(nextDrafts);
    }
    const nextTimeline = [newEvent, ...timelineEvents];
    setTimelineEvents(nextTimeline);

    const persistPatch: Record<string, unknown> = { timelineEvents: nextTimeline };
    if (isSeizureRequest && seizureDecisionId) {
        persistPatch.seizureDraftsByDecisionId = nextDrafts;
    }
    if (actionType === 'salary' && /\S/.test(String(details.salaryAmount || '').trim())) {
        const parsedSalary = Number(String(details.salaryAmount || '').replace(/,/g, '').trim());
        if (Number.isFinite(parsedSalary) && parsedSalary > 0) {
            const garnishment = parsedSalary / 5;
            if (activeWorkspaceDebtorForFollowup?.isPrimary) {
                persistPatch.employeeSalary = parsedSalary;
                persistPatch.garnishmentAmount = garnishment;
            } else if (activeWorkspaceDebtorForFollowup?.key) {
                const debtorKey = String(activeWorkspaceDebtorForFollowup.key);
                persistPatch.perDebtorSalaries = {
                    ...(executionData?.perDebtorSalaries || {}),
                    [debtorKey]: String(parsedSalary),
                };
                persistPatch.perDebtorGarnishments = {
                    ...(executionData?.perDebtorGarnishments || {}),
                    [debtorKey]: String(garnishment),
                };
            }
        }
    }
    persistExecutionMerge(persistPatch);

    const msgQueuedExecutor =
        'تم حفظ الطلب بنجاح وتحويله إلى مركز القرارات بانتظار موافقة المنفذ';
    if (isSeizureRequest) {
        showToast(msgQueuedExecutor, 'success', { decisionsLink: true });
    } else {
        showToast(`تم تسجيل ${label}`, 'success');
    }
    setLastActionDate(getLocalTodayYmd());
}

import type { FinalizeCoerciveSeizureInput } from './executionDashboardCoerciveFinalizeTypes';
import {
    buildNextSeizedAssets,
    commitCoerciveFinalize,
    resolveFinalizeIdentity,
} from './executionDashboardCoerciveFinalizeShared';
import {
    buildSalarySeizureDescriptionTextLite,
    resolveSalarySeizureSubjectLite,
} from './executionDashboardSalarySubjectLite';

export function finalizeCoerciveSalarySeizure(input: FinalizeCoerciveSeizureInput): void {
    const { decisionRowId, assetId } = resolveFinalizeIdentity(input);
    const dedRaw = String((input.details as any).monthlyDeductionIqd || '').trim();
    const parsedDeductionEarly = Number(dedRaw.replace(/,/g, ''));
    const resolvedSubject = resolveSalarySeizureSubjectLite(
        {
            details: {
                ...input.details,
                decisionRowId: String(decisionRowId),
            },
        },
        input.executionData ?? null,
        String(input.decisionsStorageExecutionId ?? input.executionId ?? '').trim() || undefined,
    );
    const mergedDesc =
        String(input.details.description || '').trim() ||
        buildSalarySeizureDescriptionTextLite({
            employerName: String(input.details.employerName || ''),
            salaryAmount: String(input.details.salaryAmount || ''),
            monthlyDeductionIqd:
                Number.isFinite(parsedDeductionEarly) && parsedDeductionEarly > 0
                    ? Math.trunc(parsedDeductionEarly)
                    : undefined,
            activeDebtorIsDeceased: input.activeDebtorIsDeceased,
            subject: resolvedSubject,
        });

    const nextAssets = buildNextSeizedAssets({
        seizedAssets: input.seizedAssets,
        assetId,
        baseAssetType: 'salary',
        actionType: input.actionType,
        decisionRowId,
        details: {
            ...input.details,
            seizureTarget: String(input.details.seizureTarget || '').trim() || 'debtor',
            subjectRole: resolvedSubject.roleLabel,
            subjectName: resolvedSubject.personName,
        },
        mergedDesc,
    });

    const persistPatch: Record<string, unknown> = {};
    const parsedSalary = Number(String(input.details.salaryAmount || '').replace(/,/g, '').trim());
    if (Number.isFinite(parsedSalary) && parsedSalary > 0) {
        const garnishment = parsedSalary / 5;
        if (input.activeWorkspaceDebtorForFollowup?.isPrimary) {
            persistPatch.employeeSalary = parsedSalary;
            persistPatch.garnishmentAmount = garnishment;
        } else if (input.activeWorkspaceDebtorForFollowup?.key) {
            const debtorKey = String(input.activeWorkspaceDebtorForFollowup.key);
            persistPatch.perDebtorSalaries = {
                ...(input.executionData?.perDebtorSalaries || {}),
                [debtorKey]: String(parsedSalary),
            };
            persistPatch.perDebtorGarnishments = {
                ...(input.executionData?.perDebtorGarnishments || {}),
                [debtorKey]: String(garnishment),
            };
        }
    }
    if (Number.isFinite(parsedDeductionEarly) && parsedDeductionEarly > 0) {
        persistPatch.seizedAssets = nextAssets.map((a) => {
            if (a.id !== assetId) return a;
            const prevDetails =
                typeof a.details === 'object' && a.details && !Array.isArray(a.details)
                    ? (a.details as Record<string, unknown>)
                    : {};
            return {
                ...a,
                details: {
                    ...prevDetails,
                    monthlyDeductionIqd: Math.trunc(parsedDeductionEarly),
                },
            };
        });
    }

    commitCoerciveFinalize({
        source: input,
        decisionRowId,
        assetId,
        mergedDesc,
        nextAssets: (persistPatch.seizedAssets as typeof nextAssets) ?? nextAssets,
        persistPatch,
    });
}

import { getLocalTodayYmd } from './executionDashboardCoreDate';
import { patchExecutionDecisionRowLite } from './executionDashboardDecisionStorageLiteWrite';
import type { SeizedAsset, TimelineEvent } from '@/app/types/execution';
import type { FinalizeCoerciveSeizureInput } from './executionDashboardCoerciveFinalizeTypes';

export function resolveFinalizeIdentity(input: FinalizeCoerciveSeizureInput): {
    decisionRowId: string;
    assetId: string;
} {
    const decisionRowId = input.directDecisionRowId || input.seizureDetailCompletion!.decisionRowId;
    const existingByDecisionRowId = input.seizedAssets.find(
        (a) => String((a.details as any)?.decisionRowId || '') === String(decisionRowId),
    );
    const assetId =
        input.directDecisionRowId && existingByDecisionRowId?.id
            ? existingByDecisionRowId.id
            : input.seizureDetailCompletion?.assetId || `sz_${String(decisionRowId)}_${Date.now()}`;
    if (input.seizureDetailCompletion && !input.directDecisionRowId) {
        input.setSeizureDetailCompletion(null);
    }
    return { decisionRowId, assetId };
}

export function buildNextSeizedAssets(input: {
    seizedAssets: SeizedAsset[];
    assetId: string;
    baseAssetType: string;
    actionType: string;
    decisionRowId: string;
    details: Record<string, string>;
    mergedDesc: string;
}): SeizedAsset[] {
    const today = getLocalTodayYmd();
    const existing = input.seizedAssets.find((a) => a.id === input.assetId);
    if (!existing) {
        return [
            {
                id: input.assetId,
                type: input.baseAssetType,
                description: input.mergedDesc || undefined,
                status: 'seized',
                seizureDate: today,
                details: {
                    ...input.details,
                    decisionRowId: String(input.decisionRowId),
                    seizureUiKind: input.actionType,
                } as any,
            },
            ...input.seizedAssets,
        ] as any;
    }
    return input.seizedAssets.map((a) => {
        if (a.id !== input.assetId) return a;
        const prevDetails =
            typeof a.details === 'object' && a.details && !Array.isArray(a.details)
                ? (a.details as Record<string, unknown>)
                : {};
        return {
            ...a,
            type: String((a as any).type || '').trim() ? (a as any).type : input.baseAssetType,
            status: String((a as any).status || '').trim() ? (a as any).status : 'seized',
            seizureDate: (a as any).seizureDate || today,
            description: input.mergedDesc || a.description,
            estimatedValue: a.estimatedValue,
            notes: a.notes,
            details: {
                ...prevDetails,
                ...input.details,
                decisionRowId: String(input.decisionRowId),
                seizureUiKind: input.actionType,
            },
        };
    });
}

export function resolveCoerciveFinalizeTitle(actionType: string, activeDebtorIsDeceased: boolean): string {
    if (actionType === 'salary') {
        return activeDebtorIsDeceased ? '💼 حجز الحوافز والمخصصات' : '💼 حجز الراتب';
    }
    if (actionType === 'property') return '🏠 تثبيت بيانات حجز العقار';
    return '📦 تثبيت بيانات حجز مال منقول';
}

export function commitCoerciveFinalize(input: {
    source: FinalizeCoerciveSeizureInput;
    decisionRowId: string;
    assetId: string;
    mergedDesc: string;
    nextAssets: SeizedAsset[];
    persistPatch: Record<string, unknown>;
}): void {
    const { source, decisionRowId, assetId, mergedDesc, nextAssets, persistPatch } = input;
    source.setSeizedAssets(nextAssets);

    const now = new Date().toISOString();
    const today = getLocalTodayYmd();
    const ev: TimelineEvent = {
        id: source.nextTimelineId(),
        date: today,
        timestamp: now,
        title: resolveCoerciveFinalizeTitle(source.actionType, source.activeDebtorIsDeceased),
        description: mergedDesc || undefined,
        type: 'coercive',
        source: 'محضر المتابعة — الحجز المالي',
        metadata: {
            timelineThreadKey: `seizure_details_saved:${assetId}`,
            seizureAssetId: assetId,
            decisionRowId,
        },
    };
    const nextTimeline = [ev, ...source.timelineEvents];
    source.setTimelineEvents(nextTimeline);

    const patch: Record<string, unknown> = {
        ...persistPatch,
        seizedAssets: nextAssets,
        timelineEvents: nextTimeline,
    };
    source.persistExecutionMerge(patch);

    const nextDraftsAfterSave = { ...source.seizureDraftsByDecisionIdRef.current };
    if (nextDraftsAfterSave[decisionRowId]) {
        delete nextDraftsAfterSave[decisionRowId];
        source.setSeizureDraftsByDecisionId(nextDraftsAfterSave);
        source.persistExecutionMerge({ seizureDraftsByDecisionId: nextDraftsAfterSave });
    }

    patchExecutionDecisionRowLite(source.decisionsStorageExecutionId, decisionRowId, {
        seizureRequestSavedAt: now,
        seizureRequestDetails: mergedDesc || undefined,
    });
    source.showToast('تم حفظ تفاصيل الحجز بعد موافقة المنفذ.', 'success');
    source.setLastActionDate(today);
}

