export function useExecutionDashboardDeceasedDebtorCoerciveReset({
    activeDebtorIsDeceased,
    activeCoerciveActions,
    debtorArrested,
    investigationPathDebtorPresent,
    executionData,
    setActiveCoerciveActions,
    setDebtorArrested,
    setInvestigationPathDebtorPresent,
