            if (!d) return;
            if (!(forcedBringDecisionState.approved && !forcedBringDecisionState.pending)) {
                showToast('لا يمكن تسجيل نتيجة أمر القبض قبل موافقة المنفذ على طلب الإحضار الجبري.', 'warning');
