                              type: 'summons',
                              source: 'التبليغ',
                              metadata: timelineDebtorMetadata(targetKey),
                          }
                        : {
                              id: nextTimelineId(),
                              date: ts.slice(0, 10),
                              timestamp: ts,
                              title: '⏹ إنهاء التكليف بالحضور',
                              description: 'أُنهي التكليف دون إحضار (تسجيل يدوي).',
                              type: 'summons',
                              source: 'التبليغ',
