/** Phase C — callbacks قبول المنفذ للقرارات (مواعيد، قوة جبرية، حراس، مهام) */
import { useMemo, type Dispatch, type MutableRefObject, type SetStateAction } from 'react';
import type { ExecutionFile, TimelineEvent } from '@/app/types/execution';
import SecureStoreService from '@/app/services/SecureStoreService';
import { syncExecutionTimelineAppointment } from '@/app/services/calendarDossierSync';
import { patchExecutorDecisionRow } from '@/app/utils/executorSeizureDecisionQueue';
import { fieldVisitAppointmentStorageKey } from '@/app/utils/executorApprovalWorkflow';
import type { ExecutorApprovalActions } from '../../executionDashboardRuntimeChunkScope';

export type UseExecutionDashboardExecutorApprovalActionsParams = {
    executionData: ExecutionFile | null | undefined;
    executionId: string | undefined;
    file: ExecutionFile | null | undefined;
    currentFileId: string;
    isMaritalFurnitureClaim: boolean;
    nextTimelineId: () => string;
    timelineEventsRef: MutableRefObject<TimelineEvent[]>;
    persistExecutionMergeRef: MutableRefObject<((patch: Record<string, unknown>) => void) | null>;
    executionFileSnapshotRef: MutableRefObject<ExecutionFile | null | undefined>;
    showToast: (message: string, type?: string) => void;
    setShowDecisionsModal: (show: boolean) => void;
    setShowUnifiedExecutionModal: (show: boolean) => void;
    setUnifiedModalTab: Dispatch<SetStateAction<string>>;
    setFollowupExpandProcedureKey: Dispatch<SetStateAction<string | null>>;
    setCaseTasksPending: Dispatch<SetStateAction<Array<Record<string, unknown>>>>;
    setTimelineEvents: Dispatch<SetStateAction<TimelineEvent[]>>;
    setExecutionReportPrompt: Dispatch<
        SetStateAction<{ onConfirm: () => void } | null>
    >;
    setJudicialCustodianModalCtx: Dispatch<
        SetStateAction<{ requestTitle: string; onSaved?: () => void } | null>
    >;
    setJudicialCustodianModalOpen: (open: boolean) => void;
    setCaseNotesLog: Dispatch<SetStateAction<Array<Record<string, unknown>>>>;
};

export function useExecutionDashboardExecutorApprovalActions(
    params: UseExecutionDashboardExecutorApprovalActionsParams,
): ExecutorApprovalActions {
    const {
        executionData,
        executionId,
        file,
        currentFileId,
        isMaritalFurnitureClaim,
        nextTimelineId,
        timelineEventsRef,
        persistExecutionMergeRef,
        executionFileSnapshotRef,
        showToast,
        setShowDecisionsModal,
        setShowUnifiedExecutionModal,
        setUnifiedModalTab,
        setFollowupExpandProcedureKey,
        setCaseTasksPending,
        setTimelineEvents,
        setExecutionReportPrompt,
        setJudicialCustodianModalCtx,
        setJudicialCustodianModalOpen,
        setCaseNotesLog,
    } = params;

    return useMemo(
        () => ({
            openScheduledDateModal: ({ requestTitle }) => {
                setShowDecisionsModal(false);
                setShowUnifiedExecutionModal(true);
                setUnifiedModalTab('coercive');
                setFollowupExpandProcedureKey(
                    isMaritalFurnitureClaim ? 'marital_furniture_delivery' : 'field_visit',
                );
                showToast(
                    isMaritalFurnitureClaim
                        ? `تمت موافقة المنفذ — ثبّت موعد التسليم من بطاقة «تسليم أثاث».\n(${requestTitle})`
                        : `تمت موافقة المنفذ — أكمل تسجيل الموعد من «الإجراءات الجبرية» داخل نفس البطاقة.\n(${requestTitle})`,
                    'info',
                );
            },
            openPoliceAssistanceModal: ({ decisionId, requestTitle }) => {
                void decisionId;
                void requestTitle;
                setShowDecisionsModal(false);
                setShowUnifiedExecutionModal(true);
                setUnifiedModalTab('coercive');
                setFollowupExpandProcedureKey('police');
                showToast(
                    'تمت الموافقة — أكمل بيانات القوة الإجرائية من البطاقة المنسدلة في الإجراءات الجبرية.',
                    'info',
                );
            },
            showToast,
            appendDossierTask: (task) => {
                const now = new Date().toISOString();
                const taskId = nextTimelineId();
                setCaseTasksPending((prev) => [
                    ...prev,
                    {
                        id: taskId,
                        title: task.title,
                        body: task.body,
                        dueDate: task.dueDate,
                        createdAt: now,
                    },
                ]);
                setTimelineEvents((prev) => [
                    {
                        id: nextTimelineId(),
                        type: 'other',
                        date: now,
                        timestamp: now,
                        title: `📌 مهمة قيد الإنجاز: ${task.title}`,
                        description: `${task.body}\n\n📅 تاريخ الإنجاز المطلوب: ${new Date(task.dueDate).toLocaleDateString('ar-EG')}`,
                        source: 'القرارات والطعون — قبول المنفذ',
                    },
                    ...prev,
                ]);
            },
            getFieldVisitDeadlineIso: () => {
                const did = String(executionData?.id ?? executionId ?? '');
                try {
                    const v = SecureStoreService.getItemSync(fieldVisitAppointmentStorageKey(did));
                    if (v) return v;
                } catch {
                    /* ignore */
                }
                const hit = timelineEventsRef.current.find(
                    (e) =>
                        e.type === 'appointment' &&
                        typeof e.source === 'string' &&
                        e.source.includes('موعد ميداني'),
                );
                return hit?.date ?? null;
            },
            promptOpenExecutionReport: (onConfirm) => {
                setExecutionReportPrompt({ onConfirm });
            },
            pushCalendarAppointment: ({ dossierId, decisionId, purpose, eventIso, recordedAt }) => {
                const newEvent: TimelineEvent = {
                    id: nextTimelineId(),
                    type: 'appointment',
                    date: eventIso,
                    timestamp: recordedAt,
                    title: `📅 ${purpose}`,
                    description: `موعد معتمد من قبول المنفذ — مرجع القرار: ${decisionId}`,
                    source: 'القرارات والطعون — موعد ميداني',
                };
                setTimelineEvents((prev) => [newEvent, ...prev]);
                syncExecutionTimelineAppointment({
                    executionId: currentFileId,
                    event: newEvent,
                    caseNo:
                        String(executionData?.fileNumber ?? executionData?.caseNo ?? file?.fileNumber ?? '').trim() ||
                        undefined,
                    clientName:
                        String(
                            executionData?.creditors?.[0]?.name ??
                                executionData?.clientName ??
                                file?.creditors?.[0]?.name ??
                                '',
                        ).trim() ||
                        undefined,
                });
                showToast('تم ربط الموعد بالسجل الزمني', 'success');
                void dossierId;
            },
            patchDecision: (decisionId, patch) => {
                patchExecutorDecisionRow(executionData?.id ?? executionId, decisionId, patch);
            },
            openBreakInventoryFurnitureModal: ({ decisionId, requestTitle, onSaved, onFinalize }) => {
                void decisionId;
                void requestTitle;
                void onSaved;
                void onFinalize;
                setShowDecisionsModal(false);
                setShowUnifiedExecutionModal(true);
                setUnifiedModalTab('coercive');
                setFollowupExpandProcedureKey(
                    isMaritalFurnitureClaim ? 'marital_furniture_delivery' : 'break_inventory',
                );
                showToast(
                    isMaritalFurnitureClaim
                        ? 'تمت الموافقة — أكمل جرد التسليم من بطاقة «تسليم أثاث».'
                        : 'تمت الموافقة — أكمل محضر الجرد من البطاقة المنسدلة في الإجراءات الجبرية.',
                    'info',
                );
            },
            openJudicialCustodianModal: ({ decisionId, requestTitle, onSaved }) => {
                void decisionId;
                setShowDecisionsModal(false);
                setJudicialCustodianModalCtx({ requestTitle, onSaved });
                setJudicialCustodianModalOpen(true);
            },
            appendCaseNote: ({ title, body }) => {
                const now = new Date().toISOString();
                const id = `note_${Date.now()}`;
                setCaseNotesLog((prev) => {
                    const next = [{ id, title, body, createdAt: now }, ...prev];
                    queueMicrotask(() => {
                        persistExecutionMergeRef.current?.({ caseNotesLog: next });
                    });
                    return next;
                });
            },
            persistJudicialCustodianDetails: ({ decisionId, fullName, salary, recordId }) => {
                const savedAt = new Date().toISOString();
                queueMicrotask(() => {
                    const snap = executionFileSnapshotRef.current;
                    const prevArr = Array.isArray(snap?.eviction_judicial_custodians)
                        ? [...(snap!.eviction_judicial_custodians as NonNullable<
                              ExecutionFile['eviction_judicial_custodians']
                          >)]
                        : [];
                    const legacy = snap?.eviction_judicial_custodian;
                    let list = prevArr;
                    if (!list.length && legacy?.fullName?.trim() && legacy.savedAt) {
                        list = [
                            {
                                id: 'legacy_custodian',
                                fullName: legacy.fullName,
                                salary: legacy.salary,
                                decisionId: legacy.decisionId,
                                savedAt: legacy.savedAt,
                            },
                        ];
                    }
                    let next;
                    if (recordId) {
                        next = list.map((c) =>
                            String(c.id) === String(recordId)
                                ? {
                                      ...c,
                                      fullName,
                                      salary,
                                      decisionId: decisionId || c.decisionId,
                                      savedAt,
                                  }
                                : c,
                        );
                    } else {
                        next = [
                            {
                                id: `cust_${Date.now()}`,
                                fullName,
                                salary,
                                decisionId,
                                savedAt,
                            },
                            ...list,
                        ];
                    }
                    persistExecutionMergeRef.current?.({
                        eviction_judicial_custodians: next,
                        eviction_judicial_custodian: null,
                    });
                });
            },
        }),
        [
            executionData?.id,
            executionId,
            isMaritalFurnitureClaim,
            nextTimelineId,
            setShowDecisionsModal,
            showToast,
            currentFileId,
            file,
            timelineEventsRef,
            persistExecutionMergeRef,
            executionFileSnapshotRef,
            setShowUnifiedExecutionModal,
            setUnifiedModalTab,
            setFollowupExpandProcedureKey,
            setCaseTasksPending,
            setTimelineEvents,
            setExecutionReportPrompt,
            setJudicialCustodianModalCtx,
            setJudicialCustodianModalOpen,
            setCaseNotesLog,
        ],
    );
}

import { useCallback, useMemo, type MutableRefObject, type RefObject } from 'react';
import type { Dispatch, SetStateAction } from 'react';
import type { ExecutionFile } from '@/app/types/execution';
import type { FollowupUnifiedModalTab } from '../../followupModalTabTypes';
import { useFollowupModalTabGuards } from './useFollowupModalTabGuards';
import {
    canOpenSeizureRequestsTab,
    computeShowGuarantorInSeizureFollowupTab,
    filterSeizureFromFollowupModalTabs,
    filterSeizureFromFollowupSectionTabOrder,
    resolveOpenSeizureRequestsTabBlockedMessage,
    type FollowupSeizureSpecialization,
    type SeizureMatrixSeizureTabSlice,
    type SettlementGuarantorGateSlice,
} from './executionDashboardFollowupSeizureTabs';

export type FollowupModalTabEntry = {
    id:
        | 'personal'
        | 'coercive'
        | 'seizure_requests'
        | 'correspondences'
        | 'admin'
        | 'dossier_controls'
        | 'other_party';
    label: string;
};

export type UseExecutionDashboardFollowupSeizureTabsParams = {
    activeDebtorIsDeceased: boolean;
    activeDebtorIsEmployee: boolean;
    viewExecutionData: ExecutionFile | null | undefined;
    followupSpecialization: FollowupSeizureSpecialization;
    remainingBalanceForSeizure: number;
    settlementGuarantorGate: SettlementGuarantorGateSlice;
    followupSectionTabOrder: readonly string[];
    followupModalTabs: readonly FollowupModalTabEntry[];
    seizureMatrix: SeizureMatrixSeizureTabSlice;
    followupTabsRestricted: boolean;
    restrictedFollowupTabIds: ReadonlySet<string>;
    openSeizureRequestsTabRef: MutableRefObject<() => void>;
    setUnifiedModalTab: Dispatch<SetStateAction<FollowupUnifiedModalTab>>;
    showToast: (message: string, type: 'info' | 'success' | 'error' | 'warning') => void;
    showUnifiedExecutionModal: boolean;
    unifiedModalTab: FollowupUnifiedModalTab;
    hideFollowupCoerciveTab: boolean;
    hideCoerciveTabsForDebtorAgent: boolean;
    showPersonalCoerciveFollowupTab: boolean;
    setShowSolidaryCoerciveTargetModal: (open: boolean) => void;
    setSolidaryCoerciveActionPending: (action: string | null) => void;
    followupModalChipTablistRef: RefObject<HTMLDivElement | null>;
    followupModalDebtorTabsRef: RefObject<HTMLDivElement | null>;
    isSolidaryLiability: boolean;
    solidaryDebtorCount: number;
};

export function useExecutionDashboardFollowupSeizureTabs({
    activeDebtorIsDeceased,
    activeDebtorIsEmployee,
    viewExecutionData,
    followupSpecialization,
    remainingBalanceForSeizure,
    settlementGuarantorGate,
    followupSectionTabOrder,
    followupModalTabs,
    seizureMatrix,
    followupTabsRestricted,
    restrictedFollowupTabIds,
    openSeizureRequestsTabRef,
    setUnifiedModalTab,
    showToast,
    showUnifiedExecutionModal,
    unifiedModalTab,
    hideFollowupCoerciveTab,
    hideCoerciveTabsForDebtorAgent,
    showPersonalCoerciveFollowupTab,
    setShowSolidaryCoerciveTargetModal,
    setSolidaryCoerciveActionPending,
    followupModalChipTablistRef,
    followupModalDebtorTabsRef,
    isSolidaryLiability,
    solidaryDebtorCount,
}: UseExecutionDashboardFollowupSeizureTabsParams) {
    const showGuarantorInSeizureFollowupTab = useMemo(
        () =>
            computeShowGuarantorInSeizureFollowupTab({
                activeDebtorIsDeceased,
                activeDebtorIsEmployee,
                viewExecutionData,
                followupSpecialization,
                remainingBalanceForSeizure,
                settlementGuarantorGate,
            }),
        [
            activeDebtorIsDeceased,
            activeDebtorIsEmployee,
            followupSpecialization.hideAllGuarantorPresence,
            followupSpecialization.isFinancialDebtCollection,
            followupSpecialization.showFinancialGuarantorRequestOnly,
            remainingBalanceForSeizure,
            settlementGuarantorGate.pendingSettlement,
            settlementGuarantorGate.settlementBreachTriggeredAt,
            viewExecutionData,
        ],
    );

    const effectiveFollowupSectionTabOrder = useMemo(
        () =>
            filterSeizureFromFollowupSectionTabOrder(
                followupSectionTabOrder,
                seizureMatrix.hideSeizureTab,
                followupSpecialization.hideFollowupSeizureRequestsTab,
            ),
        [
            followupSectionTabOrder,
            seizureMatrix.hideSeizureTab,
            followupSpecialization.hideFollowupSeizureRequestsTab,
        ],
    );

    const effectiveFollowupModalTabs = useMemo(
        () =>
            filterSeizureFromFollowupModalTabs(
                followupModalTabs,
                seizureMatrix.hideSeizureTab,
                followupSpecialization.hideFollowupSeizureRequestsTab,
                followupTabsRestricted,
                restrictedFollowupTabIds,
            ),
        [
            followupModalTabs,
            seizureMatrix.hideSeizureTab,
            followupSpecialization.hideFollowupSeizureRequestsTab,
            followupTabsRestricted,
            restrictedFollowupTabIds,
        ],
    );

    const openSeizureRequestsTab = useCallback(() => {
        if (
            !canOpenSeizureRequestsTab(seizureMatrix, followupSpecialization.hideFollowupSeizureRequestsTab)
        ) {
            showToast(
                resolveOpenSeizureRequestsTabBlockedMessage(
                    followupSpecialization.hideFollowupSeizureRequestsTab,
                    seizureMatrix,
                ),
                'info',
            );
            return;
        }
        setUnifiedModalTab('seizure_requests');
    }, [
        seizureMatrix,
        followupSpecialization.hideFollowupSeizureRequestsTab,
        showToast,
        setUnifiedModalTab,
    ]);

    openSeizureRequestsTabRef.current = openSeizureRequestsTab;

    useFollowupModalTabGuards({
        showUnifiedExecutionModal,
        unifiedModalTab,
        setUnifiedModalTab,
        effectiveFollowupSectionTabOrder,
        seizureMatrix,
        hideFollowupCoerciveTab,
        hideFollowupSeizureRequestsTab: followupSpecialization.hideFollowupSeizureRequestsTab,
        followupTabsRestricted,
        restrictedFollowupTabIds,
        hideCoerciveTabsForDebtorAgent,
        showPersonalCoerciveFollowupTab,
        setShowSolidaryCoerciveTargetModal,
        setSolidaryCoerciveActionPending,
        followupModalChipTablistRef,
        followupModalDebtorTabsRef,
        isSolidaryLiability,
        solidaryDebtorCount,
    });

    return {
        showGuarantorInSeizureFollowupTab,
        effectiveFollowupSectionTabOrder,
        effectiveFollowupModalTabs,
        openSeizureRequestsTab,
    };
}

// @ts-nocheck
/** Phase C — تجميع تبويبات محضر المتابعة + تخصص الإضبارة */
import { useCallback, useMemo, useState, type MutableRefObject } from 'react';
import type { ExecutionFile } from '@/app/types/execution';
import {
    applyDebtorDeathFollowupOverlay,
} from '@/app/utils/partyDeathClaimPolicy';
import {
    resolveExecutionDomainContext,
} from '@/app/utils/executionDomainIsolation';
import { isCustodyRemovalExecutionClaim } from '@/app/utils/executionClaimIsolation';
import { useFollowupModalPersistNavigation } from '../useFollowupModalPersistNavigation';
import {
    useExecutionDashboardEmployeeCompulsoryBannerReset,
    useExecutionDashboardEmployeePersonalTabUnlockHydrate,
} from './useExecutionDashboardRuntimeSyncEffects';

export type FollowupModalTabId =
    | 'personal'
    | 'coercive'
    | 'seizure_requests'
    | 'correspondences'
    | 'admin'
    | 'dossier_controls'
    | 'other_party';

export type UseExecutionDashboardFollowupTabAssemblyParams = {
    executionData: ExecutionFile | null | undefined;
    viewExecutionData: ExecutionFile | null | undefined;
    executionId: string | undefined;
    decisionsStorageExecutionId: string | undefined;
    claimType: string | undefined;
    activeDebtorIsDeceased: boolean;
    activeDebtorIsLegalEntity: boolean;
    activeDebtorIsEmployee: boolean;
    followupModalDebtorIsEmployee: boolean;
    followupModalDebtorIsDeceased: boolean;
    followupModalSpecializationEffective: {
        hidePersonalCoerciveFollowupTab?: boolean;
        hideFollowupCoerciveTab?: boolean;
        hideFollowupSeizureRequestsTab?: boolean;
    };
    modalShowEmployeeAssignmentCoerciveBlock: boolean;
    followupAssignmentWorkspaceCtx: { activeDebtorKey?: string | null };
    primaryDebtorWorkspaceKey: string | undefined;
    employeeAssignmentPhaseForCoercive: string | undefined;
    employeeCompulsoryBannerDismissed: boolean;
    setEmployeeCompulsoryBannerDismissed: (dismissed: boolean) => void;
    showUnifiedExecutionModal: boolean;
    unifiedModalTab: string;
    setUnifiedModalTab: (tab: string) => void;
    dossierFileKey: string;
    setShowUnifiedExecutionModal: (show: boolean) => void;
    followupModalBodyScrollRef: MutableRefObject<HTMLDivElement | null>;
    followupModalSectionTabsRef: MutableRefObject<HTMLDivElement | null>;
    followupModalOpenGenerationRef: MutableRefObject<number>;
    seizureMatrixRef: MutableRefObject<unknown>;
    openSeizureRequestsTabRef: MutableRefObject<(() => void) | null>;
    hideCoerciveTabsForDebtorAgent: boolean;
};

export function useExecutionDashboardFollowupTabAssembly({
    executionData,
    viewExecutionData,
    executionId,
    decisionsStorageExecutionId,
    claimType,
    activeDebtorIsDeceased,
    activeDebtorIsLegalEntity,
    activeDebtorIsEmployee,
    followupModalDebtorIsEmployee,
    followupModalDebtorIsDeceased,
    followupModalSpecializationEffective,
    modalShowEmployeeAssignmentCoerciveBlock,
    followupAssignmentWorkspaceCtx,
    primaryDebtorWorkspaceKey,
    employeeAssignmentPhaseForCoercive,
    employeeCompulsoryBannerDismissed,
    setEmployeeCompulsoryBannerDismissed,
    showUnifiedExecutionModal,
    unifiedModalTab,
    setUnifiedModalTab,
    dossierFileKey,
    setShowUnifiedExecutionModal,
    followupModalBodyScrollRef,
    followupModalSectionTabsRef,
    followupModalOpenGenerationRef,
    seizureMatrixRef,
    openSeizureRequestsTabRef,
    hideCoerciveTabsForDebtorAgent,
}: UseExecutionDashboardFollowupTabAssemblyParams) {
    const executionDomainContext = useMemo(
        () =>
            resolveExecutionDomainContext(
                executionData as Record<string, unknown> | null | undefined,
                decisionsStorageExecutionId ?? executionId,
            ),
        [executionData, decisionsStorageExecutionId, executionId],
    );

    const followupSpecialization = executionDomainContext.flags;

    const followupSpecializationEffective = useMemo(
        () => applyDebtorDeathFollowupOverlay(followupSpecialization, Boolean(activeDebtorIsDeceased)),
        [followupSpecialization, activeDebtorIsDeceased],
    );

    const showPersonalCoerciveFollowupTab =
        !followupSpecializationEffective.hidePersonalCoerciveFollowupTab;

    const showSalarySeizureInFollowupModal = followupModalDebtorIsEmployee;
    const followupSalarySeizureLabel =
        followupModalDebtorIsDeceased && followupModalDebtorIsEmployee
            ? 'حجز مستحقات ومكافأة نهاية الخدمة'
            : 'طلب حجز راتب (١/٥)';

    useExecutionDashboardEmployeeCompulsoryBannerReset(
        employeeAssignmentPhaseForCoercive,
        setEmployeeCompulsoryBannerDismissed,
    );

    const showEmployeeCompulsoryProceduresBanner =
        employeeAssignmentPhaseForCoercive === 'absent_declared' && !employeeCompulsoryBannerDismissed;

    const activeFollowupDebtorKey = String(
        followupAssignmentWorkspaceCtx.activeDebtorKey ??
            primaryDebtorWorkspaceKey ??
            executionId ??
            '',
    );

    const [personalTabUnlockByDebtor, setPersonalTabUnlockByDebtor] = useState<Record<string, boolean>>({});

    const employeePersonalTabUnlockStorageKey = useMemo(() => {
        const ex = String(decisionsStorageExecutionId ?? executionData?.id ?? executionId ?? '').trim();
        return ex ? `hami:employee_personal_unlock:${ex}` : '';
    }, [decisionsStorageExecutionId, executionData?.id, executionId]);

    useExecutionDashboardEmployeePersonalTabUnlockHydrate(
        employeePersonalTabUnlockStorageKey,
        setPersonalTabUnlockByDebtor,
    );

    const custodyRemovalClaimActive = useMemo(
        () =>
            isCustodyRemovalExecutionClaim(
                viewExecutionData as Record<string, unknown> | null | undefined,
                String(claimType || '').trim() || undefined,
            ),
        [viewExecutionData, claimType],
    );

    const employeeCoerciveDetentionRestricted =
        Boolean(activeDebtorIsEmployee) && !custodyRemovalClaimActive;

    const modalEmployeeCoerciveDetentionRestricted =
        Boolean(followupModalDebtorIsEmployee) && !custodyRemovalClaimActive;

    const modalShowPersonalCoerciveFollowupTab =
        !followupModalSpecializationEffective.hidePersonalCoerciveFollowupTab ||
        modalShowEmployeeAssignmentCoerciveBlock;

    const personalTabLockedForEmployee =
        employeeCoerciveDetentionRestricted &&
        !Boolean(personalTabUnlockByDebtor[activeFollowupDebtorKey]);

    const modalPersonalTabLockedForEmployee =
        modalEmployeeCoerciveDetentionRestricted &&
        !Boolean(personalTabUnlockByDebtor[activeFollowupDebtorKey]) &&
        !followupModalSpecializationEffective.hidePersonalCoerciveFollowupTab;

    const followupTabsRestricted = activeDebtorIsLegalEntity || hideCoerciveTabsForDebtorAgent;

    const followupSectionTabOrder = useMemo(
        () =>
            [
                ...(showPersonalCoerciveFollowupTab && !followupTabsRestricted
                    ? (['personal'] as const)
                    : []),
                ...(followupSpecialization.hideFollowupCoerciveTab || followupTabsRestricted
                    ? []
                    : (['coercive'] as const)),
                ...(followupTabsRestricted ? [] : (['seizure_requests'] as const)),
                'correspondences',
                'admin',
                'dossier_controls',
                'other_party',
            ] as const,
        [
            showPersonalCoerciveFollowupTab,
            followupSpecialization.hideFollowupCoerciveTab,
            followupTabsRestricted,
        ],
    );

    const {
        openFollowupModalPersisted,
        closeFollowupModalPersisted,
        persistFollowupModalViewport,
        goFollowupSectionTabByDelta,
    } = useFollowupModalPersistNavigation({
        showUnifiedExecutionModal,
        unifiedModalTab,
        setUnifiedModalTab,
        followupSectionTabOrder,
        dossierFileKey,
        setShowUnifiedExecutionModal,
        followupModalBodyScrollRef,
        followupModalSectionTabsRef,
        followupModalOpenGenerationRef,
        seizureMatrixRef,
        openSeizureRequestsTabRef,
    });

    const followupModalTabs = useMemo(() => {
        const tabs: Array<{ id: FollowupModalTabId; label: string }> = [];
        if (modalShowPersonalCoerciveFollowupTab && !followupTabsRestricted) {
            tabs.push({
                id: 'personal',
                label: modalPersonalTabLockedForEmployee
                    ? '🔒 التنفيذ الجبري الشخصي'
                    : 'التنفيذ الجبري الشخصي',
            });
        }
        if (!followupModalSpecializationEffective.hideFollowupCoerciveTab && !followupTabsRestricted) {
            tabs.push({ id: 'coercive', label: 'الإجراءات الجبرية' });
        }
        if (!followupTabsRestricted && !followupModalSpecializationEffective.hideFollowupSeizureRequestsTab) {
            tabs.push({ id: 'seizure_requests', label: 'طلبات الحجز المالية' });
        }
        tabs.push(
            { id: 'correspondences', label: 'المخاطبات' },
            { id: 'admin', label: 'نماذج الطلبات' },
            { id: 'dossier_controls', label: 'التحكم في الإضبارة' },
            { id: 'other_party', label: 'تحركات الطرف الآخر' },
        );
        return tabs;
    }, [
        modalShowPersonalCoerciveFollowupTab,
        modalPersonalTabLockedForEmployee,
        modalShowEmployeeAssignmentCoerciveBlock,
        followupModalSpecializationEffective.hideFollowupCoerciveTab,
        followupModalSpecializationEffective.hideFollowupSeizureRequestsTab,
        followupTabsRestricted,
    ]);

    const isFollowupTabActive = useCallback(
        (tabId: FollowupModalTabId) => {
            if (tabId === 'coercive') {
                if (followupModalSpecializationEffective.hideFollowupCoerciveTab) return false;
                return (
                    unifiedModalTab === 'coercive' ||
                    (unifiedModalTab === 'personal' && !modalShowPersonalCoerciveFollowupTab)
                );
            }
            return unifiedModalTab === tabId;
        },
        [
            unifiedModalTab,
            modalShowPersonalCoerciveFollowupTab,
            followupModalSpecializationEffective.hideFollowupCoerciveTab,
        ],
    );

    return {
        executionDomainContext,
        followupSpecialization,
        followupSpecializationEffective,
        showPersonalCoerciveFollowupTab,
        showSalarySeizureInFollowupModal,
        followupSalarySeizureLabel,
        showEmployeeCompulsoryProceduresBanner,
        activeFollowupDebtorKey,
        personalTabUnlockByDebtor,
        setPersonalTabUnlockByDebtor,
        employeePersonalTabUnlockStorageKey,
        custodyRemovalClaimActive,
        employeeCoerciveDetentionRestricted,
        modalEmployeeCoerciveDetentionRestricted,
        modalShowPersonalCoerciveFollowupTab,
        personalTabLockedForEmployee,
        modalPersonalTabLockedForEmployee,
        followupTabsRestricted,
        followupSectionTabOrder,
        followupModalTabs,
        isFollowupTabActive,
        openFollowupModalPersisted,
        closeFollowupModalPersisted,
        persistFollowupModalViewport,
        goFollowupSectionTabByDelta,
    };
}

// @ts-nocheck
/** مهلة قانونية + إحضار جبري + رسوم التحصيل — تجميع hooks موجودة */
import { useEffect, useMemo } from 'react';
import type { Debtor, ExecutionFile } from '@/app/types/execution';
import { meetsEarnerPersonalCoerciveFinancialThreshold } from '@/app/utils/earnerPersonalCoerciveFinancialGate';
import { useGracePeriodCalculations } from '../useGracePeriodCalculations';
import { useForcedSummoningAndFees } from '../useForcedSummoningAndFees';

export type UseExecutionDashboardGraceAndSummoningParams = {
    executionData: ExecutionFile | null | undefined;
    executionId: string | undefined;
    debtorNotificationDate: string | null | undefined;
    debtors: ExecutionFile['debtors'];
    effectiveDebtors: Debtor[];
    isEvictionExecutionModule: boolean;
    notificationCount: number;
    manualGraceCalendarExtra: boolean;
    voluntaryEndOptimistic: boolean;
    setVoluntaryEndOptimistic: (value: boolean) => void;
    noticeVoluntaryPeriodEndOptimistic: boolean;
    setNoticeVoluntaryPeriodEndOptimistic: (value: boolean) => void;
    debtorBrowserTabsMode: boolean;
    effectiveFollowupDebtorEntry: { d: Debtor; isPrimary?: boolean } | null | undefined;
    activeWorkspaceDebtorForFollowup: { d: Debtor; isPrimary?: boolean } | null | undefined;
    activeTimelineEventsDebtorScoped: { title?: string; description?: string }[];
    debtorAttendedVoluntarily: boolean;
    voluntaryAttendanceCount: number;
    claimType: string | undefined;
    isAlimonyClaim: boolean;
    monetaryStrictForSummoningEngine: boolean;
    forcedAttendanceIssued: boolean;
    initiator: string | undefined;
    paidDebt: number;
    totalOwed: number;
    parsedCourtFees: number;
    financialPrincipalAmount: number;
    paidCourtFees: number;
    paidDirectorateFees: number;
    paidClientFees: number;
    /** مدين المتابعة النشط — لحساب حدّ الكاسب المالي */
    earnerGateIsEmployee?: boolean;
};

export function useExecutionDashboardGraceAndSummoning(params: UseExecutionDashboardGraceAndSummoningParams) {
    const {
        executionData,
        debtorNotificationDate,
        debtors,
        effectiveDebtors,
        isEvictionExecutionModule,
        notificationCount,
        manualGraceCalendarExtra,
        voluntaryEndOptimistic,
        setVoluntaryEndOptimistic,
        noticeVoluntaryPeriodEndOptimistic,
        setNoticeVoluntaryPeriodEndOptimistic,
        debtorBrowserTabsMode,
        effectiveFollowupDebtorEntry,
        activeWorkspaceDebtorForFollowup,
        activeTimelineEventsDebtorScoped,
        debtorAttendedVoluntarily,
        voluntaryAttendanceCount,
        claimType,
        isAlimonyClaim,
        monetaryStrictForSummoningEngine,
        forcedAttendanceIssued,
        initiator,
        paidDebt,
        totalOwed,
        parsedCourtFees,
        financialPrincipalAmount,
        paidCourtFees,
        paidDirectorateFees,
        paidClientFees,
        earnerGateIsEmployee = false,
    } = params;

    const gracePeriod = useGracePeriodCalculations(
        executionData,
        debtorNotificationDate,
        debtors,
        effectiveDebtors,
        isEvictionExecutionModule,
        notificationCount,
        manualGraceCalendarExtra,
        voluntaryEndOptimistic,
        noticeVoluntaryPeriodEndOptimistic,
    );

    useEffect(() => {
        if (executionData?.eviction_voluntary_period_end_declared === true) {
            setVoluntaryEndOptimistic(false);
        }
    }, [executionData?.eviction_voluntary_period_end_declared, setVoluntaryEndOptimistic]);

    useEffect(() => {
        if (executionData?.notice_voluntary_period_end_declared === true) {
            setNoticeVoluntaryPeriodEndOptimistic(false);
        }
    }, [executionData?.notice_voluntary_period_end_declared, setNoticeVoluntaryPeriodEndOptimistic]);

    const earnerPersonalCoerciveFinancialThresholdMet = useMemo(() => {
        if (earnerGateIsEmployee) return false;
        const shouldCalculateExecutionFeeBase =
            initiator === 'الدائن' &&
            gracePeriod.daysSinceNoticeCalculated > 7 &&
            paidDebt < totalOwed;
        const shouldCalculateExecutionFee =
            shouldCalculateExecutionFeeBase &&
            (!isEvictionExecutionModule || Boolean(executionData?.eviction_lawyer_fee_requested));
        const calculatedExecutionFee = shouldCalculateExecutionFee
            ? (financialPrincipalAmount + parsedCourtFees) * 0.03
            : 0;
        const totalWithExecutionFee = totalOwed + calculatedExecutionFee;
        const provisionalRemaining =
            totalWithExecutionFee -
            (paidDebt + paidCourtFees + paidDirectorateFees + paidClientFees);
        return meetsEarnerPersonalCoerciveFinancialThreshold(provisionalRemaining);
    }, [
        earnerGateIsEmployee,
        initiator,
        gracePeriod.daysSinceNoticeCalculated,
        paidDebt,
        totalOwed,
        isEvictionExecutionModule,
        executionData?.eviction_lawyer_fee_requested,
        financialPrincipalAmount,
        parsedCourtFees,
        paidCourtFees,
        paidDirectorateFees,
        paidClientFees,
    ]);

    const summoningAndFees = useForcedSummoningAndFees(
        executionData,
        effectiveDebtors,
        debtorBrowserTabsMode,
        effectiveFollowupDebtorEntry ?? activeWorkspaceDebtorForFollowup,
        isEvictionExecutionModule,
        gracePeriod.evictionGraceAnchorDate,
        debtorNotificationDate,
        activeTimelineEventsDebtorScoped,
        debtorAttendedVoluntarily,
        voluntaryAttendanceCount,
        claimType,
        isAlimonyClaim,
        monetaryStrictForSummoningEngine,
        forcedAttendanceIssued,
        manualGraceCalendarExtra,
        notificationCount,
        voluntaryEndOptimistic,
        initiator,
        gracePeriod.daysSinceNoticeCalculated,
        paidDebt,
        totalOwed,
        parsedCourtFees,
        financialPrincipalAmount,
        paidCourtFees,
        paidDirectorateFees,
        paidClientFees,
        earnerPersonalCoerciveFinancialThresholdMet,
    );

    return {
        ...gracePeriod,
        ...summoningAndFees,
    };
}

