    useRef,
    type Dispatch,
    type MutableRefObject,
    type SetStateAction,
} from 'react';
import type { ExecutionFile, TimelineEvent } from '@/app/types/execution';
import { useStandardSubmit } from '@/app/hooks/useStandardSubmit';
import { syncExecutionTaskDue } from '@/app/services/calendarDossierSync';
import { useExecutionDashboardStore } from '@/app/stores/executionDashboardStore';

export type UseExecutionDashboardNotesTasksHandlersParams = {
    noteTitle: string;
    noteBody: string;
    isTask: boolean;
    taskDueDate: string;
    taskStatus: string;
    editingTaskId: string | null;
    caseTasksPending: Array<{ id: string; title?: string; body?: string; dueDate?: string }>;
    caseNotesLogRef: MutableRefObject<Array<{ id: string; title: string; body: string; createdAt: string }>>;
    caseTasksPendingRef: MutableRefObject<
        Array<{ id: string; title: string; body: string; dueDate?: string; createdAt: string; steps?: unknown[] }>
    >;
    timelineEventsRef: MutableRefObject<TimelineEvent[]>;
    currentFileId: string;
    executionData: ExecutionFile | null | undefined;
    file: ExecutionFile | null | undefined;
    nextTimelineId: () => string;
    persistExecutionMerge: (patch: Record<string, unknown>) => void;
    showToast: (message: string, type?: string, opts?: Record<string, unknown>) => void;
    pushTimelineEvent: (event: TimelineEvent) => void;
    moveCaseTaskToTrash: (taskId: string) => void;
    setNoteTitle: Dispatch<SetStateAction<string>>;
    setNoteBody: Dispatch<SetStateAction<string>>;
    setIsTask: Dispatch<SetStateAction<boolean>>;
    setTaskDueDate: Dispatch<SetStateAction<string>>;
    setTaskStatus: Dispatch<SetStateAction<string>>;
    setEditingTaskId: Dispatch<SetStateAction<string | null>>;
    setEditingNoteId: Dispatch<SetStateAction<string | null>>;
    setCaseNotesLog: Dispatch<SetStateAction<Array<{ id: string; title: string; body: string; createdAt: string }>>>;
    setCaseTasksPending: Dispatch<
        SetStateAction<
            Array<{ id: string; title: string; body: string; dueDate?: string; createdAt: string; steps?: unknown[] }>
        >
    >;
    setTimelineEvents: Dispatch<SetStateAction<TimelineEvent[]>>;
    setShowNotesModal: (show: boolean) => void;
    openFollowupModalPersisted?: () => void;
    closeUnifiedSeizureLog?: () => void;
};

export function useExecutionDashboardNotesTasksHandlers({
    noteTitle,
    noteBody,
    isTask,
    taskDueDate,
    taskStatus,
    editingTaskId,
    caseTasksPending,
    caseNotesLogRef,
    caseTasksPendingRef,
    timelineEventsRef,
    currentFileId,
    executionData,
    file,
    nextTimelineId,
    persistExecutionMerge,
    showToast,
    pushTimelineEvent,
    moveCaseTaskToTrash,
    setNoteTitle,
    setNoteBody,
    setIsTask,
    setTaskDueDate,
    setTaskStatus,
    setEditingTaskId,
    setEditingNoteId,
    setCaseNotesLog,
    setCaseTasksPending,
    setTimelineEvents,
    setShowNotesModal,
    openFollowupModalPersisted,
    closeUnifiedSeizureLog,
}: UseExecutionDashboardNotesTasksHandlersParams) {
    const noteSuccessMsgRef = useRef('');
    const noteSuccessVariantRef = useRef<'success' | 'info' | 'warning'>('success');

    const { runSubmit: runSaveNoteSubmit } = useStandardSubmit({
        successMessage: 'تم الحفظ',
        validationMessage: '',
        onClose: () => {
            setNoteTitle('');
            setNoteBody('');
            setIsTask(false);
            setTaskDueDate('');
            setTaskStatus('pending');
            setEditingTaskId(null);
        },
        showToast,
        validate: () => {
            if (!noteTitle.trim() || !noteBody.trim()) {
                showToast('يرجى تعبئة عنوان الملاحظة والتفاصيل', 'warning');
                return false;
            }
            return true;
        },
        getSuccessMessage: () => noteSuccessMsgRef.current,
        getSuccessVariant: () => noteSuccessVariantRef.current,
        submit: async () => {
            const now = new Date().toISOString();
            const sourceLabel = 'سجل الملاحظات والمهام';
            const titleTrim = noteTitle.trim();
            const bodyTrim = noteBody.trim();
            const curNotes = caseNotesLogRef.current;
            const curTasks = caseTasksPendingRef.current;
            const curTimeline = timelineEventsRef.current;
            if (!isTask) {
                noteSuccessMsgRef.current = 'تم حفظ الملاحظة بنجاح';
                noteSuccessVariantRef.current = 'success';
                const entryId = nextTimelineId();
                const nextNotes = [{ id: entryId, title: titleTrim, body: bodyTrim, createdAt: now }, ...curNotes];
                const nextTimeline = [
                    {
                        id: nextTimelineId(),
                        type: 'other',
                        date: now,
                        timestamp: now,
                        title: `📝 إضافة ملاحظة: ${titleTrim}`,
                        description: bodyTrim,
                        source: sourceLabel,
                    },
                    ...curTimeline,
                ];
                setCaseNotesLog(nextNotes);
                setTimelineEvents(nextTimeline);
                persistExecutionMerge({ caseNotesLog: nextNotes, timelineEvents: nextTimeline });
            } else if (taskStatus === 'pending') {
                const effectiveDueDate = taskDueDate || now.slice(0, 10);
                if (editingTaskId) {
                    noteSuccessMsgRef.current = 'تم تعديل المهمة بنجاح';
                    noteSuccessVariantRef.current = 'success';
                    const nextTasks = curTasks.map((task) =>
                        task.id === editingTaskId
                            ? {
                                  ...task,
                                  title: titleTrim,
                                  body: bodyTrim,
                                  dueDate: effectiveDueDate,
                              }
                            : task,
                    );
                    const nextTimeline = [
                        {
                            id: nextTimelineId(),
                            type: 'other',
                            date: now,
                            timestamp: now,
                            title: `✏️ تعديل مهمة: ${titleTrim}`,
                            description: bodyTrim,
                            source: sourceLabel,
                        },
                        ...curTimeline,
                    ];
                    setCaseTasksPending(nextTasks);
                    setTimelineEvents(nextTimeline);
                    persistExecutionMerge({ caseTasksPending: nextTasks, timelineEvents: nextTimeline });
                } else {
                    noteSuccessMsgRef.current = 'تم إنشاء المهمة — ستظهر في الملاحظات بعد الإنجاز';
                    noteSuccessVariantRef.current = 'info';
                    const taskId = nextTimelineId();
                    const nextTasks = [
                        {
                            id: taskId,
                            title: titleTrim,
                            body: bodyTrim,
                            dueDate: effectiveDueDate,
                            createdAt: now,
                        },
                        ...curTasks,
                    ];
                    const nextTimeline = [
                        {
                            id: nextTimelineId(),
                            type: 'other',
                            date: now,
                            timestamp: now,
                            title: `📌 مهمة قيد الإنجاز: ${titleTrim}`,
                            description: bodyTrim,
                            source: sourceLabel,
                        },
                        ...curTimeline,
                    ];
                    setCaseTasksPending(nextTasks);
                    setTimelineEvents(nextTimeline);
                    persistExecutionMerge({ caseTasksPending: nextTasks, timelineEvents: nextTimeline });
                }
            } else {
                noteSuccessMsgRef.current = 'تم تسجيل إنجاز المهمة';
                noteSuccessVariantRef.current = 'success';
                const entryId = nextTimelineId();
                const nextNotes = [{ id: entryId, title: titleTrim, body: bodyTrim, createdAt: now }, ...curNotes];
                const nextTimeline = [
                    {
                        id: nextTimelineId(),
                        type: 'other',
                        date: now,
                        timestamp: now,
                        title: `✅ إنجاز مهمة: ${titleTrim}`,
                        description: bodyTrim,
                        source: sourceLabel,
                    },
                    ...curTimeline,
                ];
                setCaseNotesLog(nextNotes);
                setTimelineEvents(nextTimeline);
                persistExecutionMerge({ caseNotesLog: nextNotes, timelineEvents: nextTimeline });
            }
        },
    });

    const handleSaveNote = useCallback(async () => {
        await runSaveNoteSubmit();
    }, [runSaveNoteSubmit]);

    const commitDossierNote = useCallback(
        async (payload: { title: string; bodyHtml: string; noteId?: string }) => {
            const titleTrim = String(payload.title || '').trim();
            const bodyTrim = String(payload.bodyHtml || '').trim();
            if (!titleTrim || !bodyTrim) {
                showToast('يرجى تعبئة عنوان الملاحظة والتفاصيل', 'warning');
                return;
            }
            const now = new Date().toISOString();
            const sourceLabel = 'سجل الملاحظات والمهام';
            const curNotes = caseNotesLogRef.current;
            const curTimeline = timelineEventsRef.current;
            const noteId = String(payload.noteId ?? '').trim();

            if (noteId) {
                if (!curNotes.some((n) => n.id === noteId)) {
                    showToast('تعذر العثور على الملاحظة للتعديل', 'error');
                    return;
                }
                const nextNotes = curNotes.map((n) =>
                    n.id === noteId ? { ...n, title: titleTrim, body: bodyTrim } : n,
                );
                const nextTimeline = [
                    {
                        id: nextTimelineId(),
                        type: 'other' as const,
                        date: now,
                        timestamp: now,
                        title: `✏️ تعديل ملاحظة: ${titleTrim}`,
                        description: bodyTrim,
                        source: sourceLabel,
                    },
                    ...curTimeline,
                ];
                setCaseNotesLog(nextNotes);
                setTimelineEvents(nextTimeline);
                persistExecutionMerge({ caseNotesLog: nextNotes, timelineEvents: nextTimeline });
                showToast('تم حفظ التعديل بنجاح', 'success');
            } else {
                const entryId = nextTimelineId();
                const nextNotes = [
                    { id: entryId, title: titleTrim, body: bodyTrim, createdAt: now },
                    ...curNotes,
                ];
                const nextTimeline = [
                    {
                        id: nextTimelineId(),
                        type: 'other' as const,
                        date: now,
                        timestamp: now,
                        title: `📝 إضافة ملاحظة: ${titleTrim}`,
                        description: bodyTrim,
                        source: sourceLabel,
                    },
                    ...curTimeline,
                ];
                setCaseNotesLog(nextNotes);
                setTimelineEvents(nextTimeline);
                persistExecutionMerge({ caseNotesLog: nextNotes, timelineEvents: nextTimeline });
                showToast('تم حفظ الملاحظة بنجاح', 'success');
            }
            setNoteTitle('');
            setNoteBody('');
            setEditingNoteId(null);
        },
        [
            caseNotesLogRef,
            timelineEventsRef,
            nextTimelineId,
            persistExecutionMerge,
            showToast,
            setCaseNotesLog,
            setTimelineEvents,
            setNoteTitle,
            setNoteBody,
            setEditingNoteId,
        ],
    );

    const completePendingTask = useCallback(
        (taskId: string) => {
            const task = caseTasksPending.find((t) => t.id === taskId);
            if (!task) return;
            const now = new Date().toISOString();
            const nextTasks = caseTasksPendingRef.current.filter((t) => t.id !== taskId);
            const nextNotes = [
                {
                    id: nextTimelineId(),
                    title: task.title,
                    body: task.body,
                    createdAt: now,
                },
                ...caseNotesLogRef.current,
            ];
            const nextTimeline = [
                {
                    id: nextTimelineId(),
                    type: 'other',
                    date: now,
                    timestamp: now,
                    title: `✅ إنجاز مهمة: ${task.title}`,
                    description: task.body,
                    source: 'سجل الملاحظات والمهام',
                },
                ...timelineEventsRef.current,
            ];
            setCaseTasksPending(nextTasks);
            setCaseNotesLog(nextNotes);
            setTimelineEvents(nextTimeline);
            persistExecutionMerge({
                caseTasksPending: nextTasks,
                caseNotesLog: nextNotes,
                timelineEvents: nextTimeline,
            });
            showToast('تم تسجيل إنجاز المهمة', 'success');
        },
        [
            caseTasksPending,
            caseTasksPendingRef,
            caseNotesLogRef,
            timelineEventsRef,
            nextTimelineId,
            persistExecutionMerge,
            showToast,
            setCaseTasksPending,
            setCaseNotesLog,
            setTimelineEvents,
        ],
    );

    const beginEditPendingTask = useCallback(
        (taskId: string) => {
            const task = caseTasksPending.find((t) => t.id === taskId);
            if (!task) return;
            setEditingTaskId(task.id);
            setNoteTitle(task.title || '');
            setNoteBody(task.body || '');
            setIsTask(true);
            setTaskStatus('pending');
            setTaskDueDate(task.dueDate || '');
            setShowNotesModal(true);
        },
        [
            caseTasksPending,
            setEditingTaskId,
            setNoteTitle,
            setNoteBody,
            setIsTask,
            setTaskStatus,
            setTaskDueDate,
            setShowNotesModal,
        ],
    );

    const handleSaveTask = useCallback(
        (taskData: { title: string; body: string; dueDate: string; steps?: unknown[] }) => {
            const now = new Date().toISOString();
            const newId = `task_${Date.now()}_${Math.random().toString(36).slice(2, 6)}`;
            const newTask = {
                id: newId,
                title: taskData.title,
                body: taskData.body,
                dueDate: taskData.dueDate,
                createdAt: now,
                steps: taskData.steps,
            };
            const nextTasks = [...caseTasksPendingRef.current, newTask];
            setCaseTasksPending(nextTasks);
            persistExecutionMerge({ caseTasksPending: nextTasks });
            syncExecutionTaskDue({
                executionId: currentFileId,
                task: newTask,
                caseNo:
                    String(executionData?.fileNumber ?? executionData?.caseNo ?? file?.fileNumber ?? '').trim() ||
                    undefined,
                clientName:
                    String(
                        executionData?.creditors?.[0]?.name ??
                            executionData?.clientName ??
                            file?.creditors?.[0]?.name ??
                            '',
                    ).trim() || undefined,
            });
            showToast('تم حفظ المهمة', 'success');
        },
        [caseTasksPendingRef, persistExecutionMerge, showToast, currentFileId, executionData, file, setCaseTasksPending],
    );

    const handleUpdateTask = useCallback(
        (taskId: string, updates: Partial<{ title: string; body: string; dueDate: string; steps?: unknown[] }>) => {
            const nextTasks = caseTasksPendingRef.current.map((t) =>
                t.id === taskId ? { ...t, ...updates } : t,
            );
            setCaseTasksPending(nextTasks);
            persistExecutionMerge({ caseTasksPending: nextTasks });
            const updated = nextTasks.find((t) => t.id === taskId);
            if (updated) {
                syncExecutionTaskDue({
                    executionId: currentFileId,
                    task: updated,
                    caseNo:
                        String(executionData?.fileNumber ?? executionData?.caseNo ?? file?.fileNumber ?? '').trim() ||
                        undefined,
                    clientName:
                        String(
                            executionData?.creditors?.[0]?.name ??
                                executionData?.clientName ??
                                file?.creditors?.[0]?.name ??
                                '',
                        ).trim() || undefined,
                });
            }
        },
        [caseTasksPendingRef, persistExecutionMerge, currentFileId, executionData, file, setCaseTasksPending],
    );

    const handleDeleteTask = useCallback(
        (taskId: string) => {
            moveCaseTaskToTrash(taskId);
        },
        [moveCaseTaskToTrash],
    );

    const handleAddTimelineEvent = useCallback(
        (event: { title: string; body?: string }) => {
            const newEvent: TimelineEvent = {
                id: `timeline_${Date.now()}_${Math.random().toString(36).slice(2, 6)}`,
                date: new Date().toISOString(),
                type: 'note',
                title: event.title,
                description: event.body,
            };
            pushTimelineEvent(newEvent);
        },
        [pushTimelineEvent],
    );

    const handleCompleteTask = useCallback(
        (taskId: string) => {
            completePendingTask(taskId);
        },
        [completePendingTask],
    );

    const handleMemoFollowupClick = useCallback(() => {
        if (typeof closeUnifiedSeizureLog === 'function') {
            closeUnifiedSeizureLog();
        }
        if (typeof openFollowupModalPersisted === 'function') {
            openFollowupModalPersisted();
            return;
        }
        try {
            useExecutionDashboardStore.getState().openModal('showUnifiedExecutionModal');
        } catch {
            showToast('تعذر فتح محضر المتابعة لأن الربط الحقيقي لم يصل إلى الواجهة بعد.', 'error');
        }
    }, [openFollowupModalPersisted, closeUnifiedSeizureLog, showToast]);

    return useMemo(
        () => ({
            handleSaveNote,
            commitDossierNote,
            completePendingTask,
            beginEditPendingTask,
            handleSaveTask,
            handleUpdateTask,
            handleDeleteTask,
            handleAddTimelineEvent,
            handleCompleteTask,
            handleMemoFollowupClick,
        }),
        [
            handleSaveNote,
            commitDossierNote,
            completePendingTask,
            beginEditPendingTask,
            handleSaveTask,
            handleUpdateTask,
            handleDeleteTask,
            handleAddTimelineEvent,
            handleCompleteTask,
            handleMemoFollowupClick,
        ],
    );
}

// @ts-nocheck
/** Phase C — تبليغ المدين (مذكرة أولى + تبليغات لاحقة) */
import { useCallback, type Dispatch, type SetStateAction } from 'react';
import type { ExecutionFile, EvictionSubsequentSummonsMeta, TimelineEvent } from '@/app/types/execution';
import { AR_TABLIGH_RAQM } from '../../executionDashboardLazyShellUi';
import { getLocalTodayYmd } from '@/app/utils/executionStateMachine';
import {
    buildDebtorNoticePatchForKey,
    buildDebtorNotificationCountPatchForKey,
    buildDebtorSummonsMarkerPatchForKey,
} from '@/app/utils/noticeDebtorScope';
import { buildEmployeeAssignmentPatchForDebtorKey } from '@/app/utils/employeeSummonsAssignment';
import { buildPublicationNoticePatchForDebtorKey } from '@/app/utils/publicationNoticeDebtor';
import { timelineDebtorMetadata } from '@/app/utils/timelineDebtorScope';

export type UseExecutionDashboardNotifyDebtorHandlerParams = {
    executionData: ExecutionFile | null | undefined;
    unifiedSummonsTargetDebtorKey: string;
    primaryDebtorKeyResolved: string;
    activeDebtorNoticeScope: { notificationDate?: string | null };
    debtorNotificationDate: string | null | undefined;
    notificationPurpose: string;
    notificationCount: number;
    subsequentNoticeUnlocked: boolean;
    isEvictionExecutionModule: boolean;
    nextTimelineId: () => string;
    persistExecutionMerge: (patch: Record<string, unknown>) => void;
    showToast: (message: string, type?: string) => void;
    setDebtorNotificationDate: Dispatch<SetStateAction<string | null | undefined>>;
    setLastActionDate: Dispatch<SetStateAction<string>>;
    setActiveNoticeState: Dispatch<SetStateAction<string | null>>;
    setNoticeVoluntaryPeriodEndOptimistic: Dispatch<SetStateAction<boolean>>;
    setVoluntaryEndOptimistic: Dispatch<SetStateAction<boolean>>;
    setNotificationCount: Dispatch<SetStateAction<number>>;
    setTimelineEvents: Dispatch<SetStateAction<TimelineEvent[]>>;
    setDebtorSummonsMarkerLocal: Dispatch<SetStateAction<Record<string, unknown> | null>>;
    setNotificationPurpose: Dispatch<SetStateAction<string>>;
    setSummonsMarkerPopoverOpen: (open: boolean) => void;
};

export function useExecutionDashboardNotifyDebtorHandler(params: UseExecutionDashboardNotifyDebtorHandlerParams) {
    const {
        executionData,
        unifiedSummonsTargetDebtorKey,
        primaryDebtorKeyResolved,
        activeDebtorNoticeScope,
        debtorNotificationDate,
        notificationPurpose,
        notificationCount,
        subsequentNoticeUnlocked,
        isEvictionExecutionModule,
        nextTimelineId,
        persistExecutionMerge,
        showToast,
        setDebtorNotificationDate,
        setLastActionDate,
        setActiveNoticeState,
        setNoticeVoluntaryPeriodEndOptimistic,
        setVoluntaryEndOptimistic,
        setNotificationCount,
        setTimelineEvents,
        setDebtorSummonsMarkerLocal,
        setNotificationPurpose,
        setSummonsMarkerPopoverOpen,
    } = params;

    const handleNotifyDebtor = useCallback(
        (
            explicitNotificationDate?: string | null,
            evictionSubsequentMeta?: EvictionSubsequentSummonsMeta,
            initialNoticeLawyerFeesIncluded?: boolean,
            summonsPurposeFromModal?: string,
            notifyOpts?: { forceExecutionMemo?: boolean },
        ) => {
            const targetDebtorKey = unifiedSummonsTargetDebtorKey;
            const targetIsPrimary = targetDebtorKey === primaryDebtorKeyResolved;
            const fallbackDay = getLocalTodayYmd();
            const picked =
                typeof explicitNotificationDate === 'string' && explicitNotificationDate.trim() !== ''
                    ? explicitNotificationDate.trim()
                    : null;
            const dateToUse =
                picked ??
                activeDebtorNoticeScope.notificationDate ??
                (targetIsPrimary ? debtorNotificationDate : null) ??
                fallbackDay;

            const purposeText = String(summonsPurposeFromModal ?? notificationPurpose ?? '').trim();

            const wasInitialNotice = notificationCount === 0;
            const forceMemo = Boolean(notifyOpts?.forceExecutionMemo && notificationCount === 1);

            if (!wasInitialNotice && !subsequentNoticeUnlocked && !forceMemo) {
                showToast(
                    'سجّل حضور المدين، أو «انتهاء المهلة» بعد السبعة أيام، أو نفّذ إجراء التنفيذ المناسب قبل تسجيل تبليغ لاحق.',
                    'warning',
                );
                return;
            }

            if (targetIsPrimary) setDebtorNotificationDate(dateToUse);
            setLastActionDate(dateToUse);

            const isMemoRegistration = wasInitialNotice || forceMemo;
            const nextCount = isMemoRegistration ? 1 : notificationCount + 1;

            let eventTitle = '';
            let eventDescription = '';

            if (isMemoRegistration) {
                eventTitle = forceMemo ? '📋 إعادة تبليغ بمذكرة الإخبار بالتنفيذ' : '📋 مذكرة الإخبار بالتنفيذ';
                eventDescription = forceMemo
                    ? `إعادة مذكرة الإخبار بالتنفيذ. تاريخ التبليغ الفعلي: ${dateToUse}.`
                    : `مذكرة الإخبار بالتنفيذ. تاريخ التبليغ الفعلي: ${dateToUse}.`;
                if (typeof initialNoticeLawyerFeesIncluded === 'boolean') {
                    eventDescription += initialNoticeLawyerFeesIncluded
                        ? '\nأتعاب المحاماة مشمولة في المذكرة (تخلية — كاسب).'
                        : '\nأتعاب المحاماة: مسار اعتيادي دون شمول في المذكرة.';
                }
                setActiveNoticeState('initial_notice');
                if (targetIsPrimary) setNoticeVoluntaryPeriodEndOptimistic(false);
                setVoluntaryEndOptimistic(false);
            } else {
                const raqm = nextCount - 1;
                const raqmLabel = AR_TABLIGH_RAQM[raqm] ?? String(raqm);
                eventTitle = `🔔 تبليغ رقم ${raqmLabel}${purposeText ? ` — ${purposeText}` : ''}`;
                eventDescription = `الغاية: ${purposeText || '—'}. تاريخ التبليغ: ${dateToUse}`;
            }

            const recorded = new Date().toISOString();
            const eventId = nextTimelineId();
            const newEvent: TimelineEvent = {
                id: eventId,
                date: dateToUse,
                timestamp: recorded,
                title: eventTitle,
                description: eventDescription,
                type: 'notification',
                source: 'التبليغ',
                metadata: timelineDebtorMetadata(targetDebtorKey),
            };

            const markerPurpose = purposeText || 'تبليغ';
            const markerTrimmed =
                markerPurpose.length > 280 ? `${markerPurpose.slice(0, 280)}…` : markerPurpose;
            const markerPayload = isMemoRegistration
                ? null
                : {
                      id: eventId,
                      date: dateToUse,
                      purpose: markerTrimmed,
                      recordedAt: new Date().toISOString(),
                  };
            const scopedDebtorPatch = executionData?.id
                ? {
                      ...buildDebtorNoticePatchForKey(
                          executionData,
                          targetDebtorKey,
                          primaryDebtorKeyResolved,
                          {
                              notificationDate: dateToUse,
                              ...(isMemoRegistration
                                  ? {
                                        memoAnchorDate: dateToUse,
                                        voluntaryPeriodEndDeclared: false,
                                        absenceBadgeDismissed: false,
                                        activeNoticeState: 'initial_notice',
                                    }
                                  : {}),
                          },
                      ),
                      ...buildDebtorNotificationCountPatchForKey(
                          executionData,
                          targetDebtorKey,
                          primaryDebtorKeyResolved,
                          nextCount,
                      ),
                      ...buildDebtorSummonsMarkerPatchForKey(
                          executionData,
                          targetDebtorKey,
                          primaryDebtorKeyResolved,
                          markerPayload,
                      ),
                  }
                : { debtorNotificationDate: dateToUse };

            const persistPatch: Record<string, unknown> = {
                lastActionDate: dateToUse,
                ...(targetIsPrimary ? { notificationCount: nextCount } : {}),
                ...(targetIsPrimary ? { debtor_summons_marker: markerPayload } : {}),
                ...scopedDebtorPatch,
            };

            if (!isMemoRegistration && executionData?.id) {
                Object.assign(persistPatch, {
                    ...buildEmployeeAssignmentPatchForDebtorKey(
                        executionData,
                        targetDebtorKey,
                        null,
                        primaryDebtorKeyResolved,
                    ),
                    ...buildPublicationNoticePatchForDebtorKey(executionData, targetDebtorKey, null),
                });
            }

            if (isMemoRegistration) {
                setNotificationCount(1);
                if (isEvictionExecutionModule) {
                    Object.assign(persistPatch, {
                        eviction_first_notice_date: dateToUse,
                        eviction_voluntary_period_end_declared: false,
                        debtor_absence_badge_dismissed: false,
                    });
                    if (typeof initialNoticeLawyerFeesIncluded === 'boolean') {
                        persistPatch.eviction_initial_notice_lawyer_fees_included =
                            initialNoticeLawyerFeesIncluded;
                        persistPatch.eviction_lawyer_fee_waived_at_intake = !initialNoticeLawyerFeesIncluded;
                        if (initialNoticeLawyerFeesIncluded) {
                            persistPatch.eviction_lawyer_fee_requested = true;
                        }
                    }
                } else if (targetIsPrimary) {
                    Object.assign(persistPatch, {
                        execution_memo_anchor_date: dateToUse,
                        notice_voluntary_period_end_declared: false,
                        debtor_absence_badge_dismissed: false,
                    });
                }
            } else {
                setNotificationCount((p) => p + 1);
                if (isEvictionExecutionModule) {
                    const forCol = Boolean(evictionSubsequentMeta?.forCollection);
                    const branch = forCol ? (evictionSubsequentMeta?.branch ?? null) : null;
                    Object.assign(persistPatch, {
                        eviction_voluntary_period_end_declared: false,
                        eviction_last_summons_for_collection: forCol,
                        eviction_last_collection_summons_branch: branch,
                    });
                }
            }

            setTimelineEvents((prev) => {
                const next = [newEvent, ...prev];
                persistExecutionMerge({
                    ...persistPatch,
                    timelineEvents: next,
                });
                return next;
            });

            if (!isMemoRegistration) {
                setDebtorSummonsMarkerLocal(markerPayload);
            } else {
                setDebtorSummonsMarkerLocal(null);
            }

            setNotificationPurpose('');
            setSummonsMarkerPopoverOpen(false);

            showToast(
                forceMemo
                    ? 'تم تسجيل إعادة التبليغ بمذكرة الإخبار بالتنفيذ'
                    : wasInitialNotice
                      ? 'تم تسجيل مذكرة الإخبار بالتنفيذ'
                      : 'تم تسجيل التبليغ',
                'success',
            );
        },
        [
            unifiedSummonsTargetDebtorKey,
            primaryDebtorKeyResolved,
            activeDebtorNoticeScope.notificationDate,
            debtorNotificationDate,
            notificationPurpose,
            notificationCount,
            subsequentNoticeUnlocked,
            isEvictionExecutionModule,
            executionData,
            nextTimelineId,
            persistExecutionMerge,
            showToast,
            setDebtorNotificationDate,
            setLastActionDate,
            setActiveNoticeState,
            setNoticeVoluntaryPeriodEndOptimistic,
            setVoluntaryEndOptimistic,
            setNotificationCount,
            setTimelineEvents,
            setDebtorSummonsMarkerLocal,
            setNotificationPurpose,
            setSummonsMarkerPopoverOpen,
        ],
    );

    return { handleNotifyDebtor };
}

// @ts-nocheck
/** hami-open-decisions-modal — يحافظ على openDecisionsModalWithBoot (موجة 13) */
import { useEffect } from 'react';
import { matchesDecisionsModalOpenTarget } from '@/app/components/lawyer/DecisionsAndAppealsEngine/engine/resolveDecisionsStorageExecutionId';

export function useExecutionDashboardOpenDecisionsModalBridge({
    executionDataId,
    executionId,
    decisionsStorageExecutionId,
    executionData,
    setShowExecutionFinancialHub,
    setShowUnifiedExecutionModal,
    setShowUnifiedSummonsModal,
    setShowNotesModal,
    setShowDocumentsModal,
    setShowAppointmentModal,
    setShowTimelineModal,
    setShowNotificationModal,
    openDecisionsModalWithBoot,
}: {
    executionDataId: string | undefined;
    executionId: string | undefined;
    decisionsStorageExecutionId?: string | undefined;
    executionData?: Record<string, unknown> | null;
    setShowExecutionFinancialHub: (show: boolean) => void;
    setShowUnifiedExecutionModal: (show: boolean) => void;
    setShowUnifiedSummonsModal: (show: boolean) => void;
    setShowNotesModal: (show: boolean) => void;
    setShowDocumentsModal: (show: boolean) => void;
    setShowAppointmentModal: (show: boolean) => void;
    setShowTimelineModal: (show: boolean) => void;
    setShowNotificationModal: (show: boolean) => void;
    openDecisionsModalWithBoot: (boot?: { tab?: string; decisionId?: string | null }) => void;
}) {
    useEffect(() => {
        const handler = (e: Event) => {
            const ce = e as CustomEvent<{ executionId?: string; decisionId?: string; tab?: string }>;
            if (
                !matchesDecisionsModalOpenTarget(ce.detail?.executionId, {
                    executionDataId,
                    executionId,
                    decisionsStorageExecutionId,
                    executionData,
                })
            ) {
                return;
            }
            setShowExecutionFinancialHub(false);
            setShowUnifiedExecutionModal(false);
            setShowUnifiedSummonsModal(false);
            setShowNotesModal(false);
            setShowDocumentsModal(false);
            setShowAppointmentModal(false);
            setShowTimelineModal(false);
            setShowNotificationModal(false);
            const tabRaw = String(ce.detail?.tab || '').trim();
            const tab =
                tabRaw === 'current' || tabRaw === 'previous' || tabRaw === 'appeals'
                    ? tabRaw
                    : undefined;
            const did = String(ce.detail?.decisionId || '').trim() || null;
            openDecisionsModalWithBoot(
                tab || did ? { tab: tab ?? undefined, decisionId: did } : undefined,
            );
        };
        window.addEventListener('hami-open-decisions-modal', handler as EventListener);
        return () => window.removeEventListener('hami-open-decisions-modal', handler as EventListener);
    }, [
        executionDataId,
        executionId,
        decisionsStorageExecutionId,
        executionData,
        setShowExecutionFinancialHub,
