            seizureMarkDateDraft,
            seizureMarkEntityDraft,
            executionDataRef,
            persistExecutionMerge,
            pushTimelineEvent,
            nextTimelineId,
            setSeizureMarkModalOpen,
            setSeizureMarkModalEntityId,
            setSeizureMarkLetterNumberDraft,
            setSeizureMarkDateDraft,
            setSeizureMarkEntityDraft,
            showToast,
        });
