    const forcedBringDecisionState = useMemo(
        () =>
            getPersonalCoerciveSubtypeOutcome(
                p.executionData?.id ?? p.executionId,
                'forced_bring_in',
            ),
        [p.executionData?.id, p.executionId, decisionsReloadEpoch],
    );

    const employeeForcedBringAwaitingPersonalOutcome = useMemo(
        () =>
            Boolean(
                forcedBringDecisionState.approved &&
                    p.executionData?.forced_bring_in_personal_outcome !== 'brought' &&
                    p.executionData?.forced_bring_in_personal_outcome !== 'absconded',
            ),
        [forcedBringDecisionState.approved, p.executionData?.forced_bring_in_personal_outcome],
    );

    const [executionFeeInjected, setExecutionFeeInjected] = useState(
        p.executionData?.executionFeeInjected || false,
    );

    const financialOrchestrator = useExecutionFinancialOrchestrator({
        setShowUnifiedExecutionModal: followupOrchestrator.setShowUnifiedExecutionModal,
    });
    const {
        isFinancialCenterExpanded,
        setIsFinancialCenterExpanded,
        activeFinancialTab,
        setActiveFinancialTab,
        showExecutionFinancialHub,
        setShowExecutionFinancialHub,
        financialHubAutoOpenMode,
        setFinancialHubAutoOpenMode,
        financialHubSeizedMovableId,
        setFinancialHubSeizedMovableId,
        financialHubSeizedPropertyId,
        setFinancialHubSeizedPropertyId,
        openFinancialHubLedger,
    } = financialOrchestrator;

    useExecutionDashboardOpenDecisionsModalBridge({
        executionDataId: p.executionData?.id,
        executionId: p.executionId,
        decisionsStorageExecutionId: p.decisionsStorageExecutionId,
        executionData: p.executionData,
        setShowExecutionFinancialHub,
        setShowUnifiedExecutionModal: followupOrchestrator.setShowUnifiedExecutionModal,
        setShowUnifiedSummonsModal,
        setShowNotesModal: p.setShowNotesModal,
        setShowDocumentsModal: p.setShowDocumentsModal,
        setShowAppointmentModal: p.setShowAppointmentModal,
        setShowTimelineModal: p.setShowTimelineModal,
        setShowNotificationModal: p.setShowNotificationModal,
        openDecisionsModalWithBoot,
    });

    const { thirdPartySeizuresUi, setThirdPartySeizuresUi, applyThirdPartySeizuresFromPatch } =
        useThirdPartySeizuresUi(p.executionData);

    useSeizureApprovalToast({
        executionDataId: p.executionData?.id,
        executionId: p.executionId,
        showToast,
    });

    useExecutionDashboardPerformanceMonitor();

    return {
        isPaused,
        setIsPaused,
        pauseReason,
        setPauseReason,
        executionFeeAdded,
        toastVisible,
        toastMessage,
        toastType,
        toastEpoch,
        showToast,
        hideToast,
        showToastRef,
        decisionsOrchestrator,
        decisionsReloadEpoch,
        setDecisionsReloadEpoch,
        decisionsModalBootHubTab,
        setDecisionsModalBootHubTab,
        decisionsModalBootListTab,
        setDecisionsModalBootListTab,
        decisionsModalScrollToDecisionId,
        setDecisionsModalScrollToDecisionId,
        appealsModalScrollToDecisionId,
        setAppealsModalScrollToDecisionId,
        clearDecisionsModalBootState,
        openDecisionsModalWithBoot,
        forcedBringDecisionState,
        employeeForcedBringAwaitingPersonalOutcome,
        executionFeeInjected,
        setExecutionFeeInjected,
        financialOrchestrator,
        isFinancialCenterExpanded,
        setIsFinancialCenterExpanded,
        activeFinancialTab,
        setActiveFinancialTab,
        showExecutionFinancialHub,
        setShowExecutionFinancialHub,
        financialHubAutoOpenMode,
        setFinancialHubAutoOpenMode,
        financialHubSeizedMovableId,
        setFinancialHubSeizedMovableId,
        financialHubSeizedPropertyId,
        setFinancialHubSeizedPropertyId,
        openFinancialHubLedger,
        thirdPartySeizuresUi,
        setThirdPartySeizuresUi,
        applyThirdPartySeizuresFromPatch,
    };
}

/** Placeholders until execution-core-handlers loads — must never fail silently. */
const HANDLER_STUB_BRAND = Symbol.for('hami.executionHandlerStub');

const STUB_TOAST_COOLDOWN_MS = 2_400;

type StubNotifier = (path: string) => void;

let stubNotifier: StubNotifier | null = null;
let lastStubToastAt = 0;
let stubInvocationCount = 0;

export function registerExecutionHandlerStubNotifier(notifier: StubNotifier | null): void {
    stubNotifier = notifier;
}

export function resetExecutionHandlerStubNotifierForTests(): void {
    stubNotifier = null;
    lastStubToastAt = 0;
    stubInvocationCount = 0;
}

export function getExecutionHandlerStubInvocationCountForTests(): number {
    return stubInvocationCount;
}

function notifyStubInvocation(path: string): void {
    stubInvocationCount += 1;
    const now = Date.now();
    if (now - lastStubToastAt < STUB_TOAST_COOLDOWN_MS) return;
    lastStubToastAt = now;
    try {
        stubNotifier?.(path);
    } catch {
        /* لا نكسر المسار إن فشل الإشعار */
    }
}

function handlerLeaf(path: string): unknown {
    const fn = (..._args: unknown[]) => {
        notifyStubInvocation(path);
        return undefined;
    };
    return new Proxy(fn, {
        get(_target, prop) {
            if (prop === HANDLER_STUB_BRAND) return true;
            if (prop === 'then') return undefined;
            if (prop === Symbol.toPrimitive) return () => '';
            if (prop === 'toString') return () => `ExecutionHandlerStub(${path})`;
            if (typeof prop === 'symbol') return undefined;
            return handlerLeaf(`${path}.${String(prop)}`);
        },
        apply(_target, _thisArg, _args) {
            notifyStubInvocation(path);
            return undefined;
        },
    });
}

const HANDLER_STUB = handlerLeaf('cluster');

/**
 * Fallback لمعالِج لم يصل بعد من handler cluster (نافذة الـ stubs).
 * تسطيح scope bag يتخطى قيم الـ stubs (functions)، فتصل المفاتيح المسطّحة undefined —
 * هذا البديل يستدعي إشعار «جاري تجهيز الأدوات» بدل انهيار "X is not a function".
 */
export function executionHandlerNotReadyFallback(path: string): (...args: unknown[]) => undefined {
    return (..._args: unknown[]) => {
        notifyStubInvocation(path);
        return undefined;
    };
}

const REST_EXTRA_DEFAULTS = {
    showResidentialEvictionGraceControl: false,
    showResidentialGraceEarlyEndRequest: false,
    residentialGraceAllowsFieldwork: false,
    showBreakInventoryRequest: false,
    firstActiveAppealDecisionId: null as string | null,
};

/** Keys consumed by pickHandlerClusterAssemblyHandlers + rest extras */
const ASSEMBLY_HANDLER_KEYS = [
    'notesTasksHandlers',
    'paymentHandlers',
    'notifyDebtorHandler',
    'heirsNotificationHandlers',
    'debtorSummonsCoerciveHandlers',
    'gracePeriodEndHandler',
    'evictionHeirsMemoHandlers',
    'evictionResidentialGraceHandlers',
    'policeAssistanceHandlers',
    'breakInventoryHandlers',
    'guarantorFollowupHandlers',
    'evictionFinancialHandlers',
    'moduleExpenseHandlers',
    'followupSeizureHandlers',
    'seizureAssetModalHandlers',
    'coerciveActionBridge',
    'coerciveActionHandlers',
    'seizureReleaseHandlers',
    'thirdPartyReceiveHandlers',
    'standaloneMarkHandlers',
    'salarySeizurePatch',
    'thirdPartySeizureHandlers',
    'realEstateSeizureHandlers',
    'dossierFollowupHandlers',
    'debtorEmploymentHandler',
    'stayHandlers',
    'voluntaryPeriodHandlers',
    'employeeAssignmentHandlers',
    'publicationNoticeHandlers',
    'appointmentHandler',
    'parentDossierPersistence',
    'pushTimelineEventBinding',
    'dossierLifecycleActions',
    'dossierMetaWorkflow',
    'evictionProceduresHandlers',
] as const;

function buildStubCluster(): Record<string, unknown> {
    const out: Record<string, unknown> = {
        pushTimelineEvent: (..._args: unknown[]) => {
            notifyStubInvocation('pushTimelineEvent');
            return undefined;
        },
        ...REST_EXTRA_DEFAULTS,
    };
    for (const key of ASSEMBLY_HANDLER_KEYS) {
        out[key] = handlerLeaf(key);
    }
    return out;
}

export const EXECUTION_HANDLER_CLUSTER_STUBS: Record<string, unknown> = buildStubCluster();

export function isExecutionHandlerClusterStub(cluster: Record<string, unknown>): boolean {
    return cluster === EXECUTION_HANDLER_CLUSTER_STUBS;
}

export function isExecutionHandlerStubLeaf(value: unknown): boolean {
    return typeof value === 'function' && (value as { [HANDLER_STUB_BRAND]?: boolean })[HANDLER_STUB_BRAND] === true;
}

export { HANDLER_STUB_BRAND };

import { useMemo } from 'react';
import type { Debtor, ExecutionFile } from '@/app/types/execution';
import { getPartyDeathCaseForRole } from '@/app/utils/partyDeathCaseScope';

export function useActiveDebtorHeirsForNotification(
    executionData: ExecutionFile | null | undefined,
    debtorBrowserTabsMode: boolean,
    activeWorkspaceDebtorForFollowup: { d: Debtor; isPrimary?: boolean; key?: string } | null,
): string[] {
    return useMemo(() => {
        const activeDebtorHeirsFromTabs =
            debtorBrowserTabsMode && activeWorkspaceDebtorForFollowup
                ? ((activeWorkspaceDebtorForFollowup.d as { heirs?: string[] } | undefined)?.heirs || [])
                : [];
        const fromPrimary = (executionData?.debtors?.[0]?.heirs || []).filter((s) => /\S/.test(String(s)));
        const debtorDeathCase = getPartyDeathCaseForRole(executionData, 'debtor');
        const fromDeathCase = (debtorDeathCase?.heir_names || []).filter((s) => /\S/.test(String(s)));
        const base =
            activeDebtorHeirsFromTabs.length > 0
                ? activeDebtorHeirsFromTabs
                : fromPrimary.length > 0
                  ? fromPrimary
                  : fromDeathCase;
        const seen = new Set<string>();
        return base
            .map((s) => String(s).trim())
            .filter(Boolean)
            .filter((name) => {
                if (seen.has(name)) return false;
                seen.add(name);
                return true;
            });
    }, [
        debtorBrowserTabsMode,
        activeWorkspaceDebtorForFollowup,
        executionData?.debtors,
        executionData?.debtor_party_death_case,
        executionData?.party_death_case,
    ]);
}

import { useMemo } from 'react';
import type { Debtor, ExecutionFile } from '@/app/types/execution';
import { isDebtorRowEmployee } from '@/app/stores';

export function useActiveDebtorProfile(
    executionData: ExecutionFile | null | undefined,
    debtorBrowserTabsMode: boolean,
    activeWorkspaceDebtorForFollowup: { d: Debtor; isPrimary?: boolean; key?: string } | null,
    effectiveDebtors: Debtor[],
) {
    const activeDebtorIsEmployee = useMemo(() => {
        const d0 = effectiveDebtors[0] as Debtor | undefined;
        if (!executionData) {
            return isDebtorRowEmployee(d0);
        }
        if (debtorBrowserTabsMode && activeWorkspaceDebtorForFollowup) {
            if (activeWorkspaceDebtorForFollowup.isPrimary) {
                return isDebtorRowEmployee((executionData.debtors?.[0] as Debtor | undefined) ?? d0);
            }
            const ad = executionData.party_multiplicity?.additionalDebtors?.find(
                (a) => String(a.id) === activeWorkspaceDebtorForFollowup.key
            );
            if (ad) return isDebtorRowEmployee(ad);
            return isDebtorRowEmployee(activeWorkspaceDebtorForFollowup.d as Debtor);
        }
        return isDebtorRowEmployee((executionData.debtors?.[0] as Debtor | undefined) ?? d0);
    }, [
        executionData,
        executionData?.debtors,
        executionData?.party_multiplicity?.additionalDebtors,
        debtorBrowserTabsMode,
        activeWorkspaceDebtorForFollowup,
        effectiveDebtors,
    ]);

    const activeDebtorIsDeceased = useMemo(() => {
        const d0 = effectiveDebtors[0] as (Debtor & { isDeceased?: boolean }) | undefined;
        if (!executionData) {
            return Boolean(d0?.isDeceased);
        }
        if (debtorBrowserTabsMode && activeWorkspaceDebtorForFollowup) {
            if (activeWorkspaceDebtorForFollowup.isPrimary) {
                const p = (executionData.debtors?.[0] as (Debtor & { isDeceased?: boolean }) | undefined) ?? d0;
                return Boolean(p?.isDeceased || executionData?.is_debtor_deceased);
            }
            const ad = executionData.party_multiplicity?.additionalDebtors?.find(
                (a) => String(a.id) === activeWorkspaceDebtorForFollowup.key
            ) as unknown as ({ isDeceased?: boolean } & Record<string, unknown>) | undefined;
            if (ad) return Boolean(ad.isDeceased);
            return Boolean((activeWorkspaceDebtorForFollowup.d as { isDeceased?: boolean } | undefined)?.isDeceased);
        }
        const p = (executionData.debtors?.[0] as (Debtor & { isDeceased?: boolean }) | undefined) ?? d0;
        return Boolean(p?.isDeceased || executionData?.is_debtor_deceased);
    }, [
        executionData,
        executionData?.debtors,
        executionData?.is_debtor_deceased,
        executionData?.party_multiplicity?.additionalDebtors,
        debtorBrowserTabsMode,
        activeWorkspaceDebtorForFollowup,
        effectiveDebtors,
    ]);

    return { activeDebtorIsEmployee, activeDebtorIsDeceased };
}

import { useMemo } from 'react';

export function useCaseTasksAndNotes(
    timelineEvents: any[],
    activeCaseNotesLog: any[],
    caseTasksPending: any[],
    caseNotesLog: any[],
) {
    const completedTaskTitles = useMemo(() => {
        const out = new Set<string>();
        for (const ev of timelineEvents) {
            const title = String((ev as any)?.title || '').trim();
            if (!title.startsWith('✅ إنجاز مهمة:')) continue;
            const taskTitle = title.replace(/^✅\s*إنجاز\s*مهمة:\s*/u, '').trim();
            if (taskTitle) out.add(taskTitle);
        }
        return out;
    }, [timelineEvents]);

    const savedNotesSplit = useMemo(() => {
        const doneTasks: typeof activeCaseNotesLog = [];
        const notes: typeof activeCaseNotesLog = [];
        for (const n of activeCaseNotesLog) {
            const t = String((n as any)?.title || '').trim();
            if (t && completedTaskTitles.has(t)) doneTasks.push(n);
            else notes.push(n);
        }
        return { notes, doneTasks };
    }, [activeCaseNotesLog, completedTaskTitles]);

    const activeCaseTasksPendingAll = useMemo(
        () => caseTasksPending.filter((t) => !t.trashedAt),
        [caseTasksPending]
    );

    const activeGraceTasks = useMemo(
        () =>
            activeCaseTasksPendingAll.filter((t) =>
                /انتهاء المهلة/.test(String((t as any)?.title || '').trim())
            ),
        [activeCaseTasksPendingAll]
    );

    const activeCaseTasksPending = useMemo(
        () =>
            activeCaseTasksPendingAll.filter(
                (t) => !/انتهاء المهلة/.test(String((t as any)?.title || '').trim())
            ),
        [activeCaseTasksPendingAll]
    );

    const trashedTimelineEvents = useMemo(
        () => timelineEvents.filter((e) => Boolean(e.trashedAt)),
        [timelineEvents]
    );

    const trashedCaseNotes = useMemo(
        () => caseNotesLog.filter((n) => Boolean(n.trashedAt)),
        [caseNotesLog]
    );

    const trashedCaseTasks = useMemo(
        () => caseTasksPending.filter((t) => Boolean(t.trashedAt)),
        [caseTasksPending]
    );

    return {
        completedTaskTitles,
        savedNotesSplit,
        activeCaseTasksPendingAll,
        activeGraceTasks,
        activeCaseTasksPending,
        trashedTimelineEvents,
        trashedCaseNotes,
        trashedCaseTasks,
    };
}

import { useMemo } from 'react';
import { resolvePartyStoredName } from '@/app/utils/executionPartyNormalize';

export function useCreditorWorkspace(
    effectiveCreditors: any[],
    additionalCreditorsPm: any[],
) {
    const creditorWorkspaceEntries = useMemo(() => {
        const out: Array<{
            key: string;
            c: Record<string, unknown>;
            isPmCreditor: boolean;
            ecIndex: number;
            pmCreditor?: any;
        }> = [];
        effectiveCreditors.forEach((c, i) => {
            out.push({
                key: String(c.id ?? `ec-${i}`),
                c: c as unknown as Record<string, unknown>,
                isPmCreditor: false,
                ecIndex: i,
            });
        });
        additionalCreditorsPm.forEach((ac) => {
            const occ = ac.occupation ?? ac.employmentType ?? 'كاسب';
            out.push({
                key: `pmc-${ac.id}`,
                c: {
                    id: ac.id,
                    name: resolvePartyStoredName(ac),
                    phone: ac.phone ?? '',
                    address: ac.address ?? '',
                    occupation: occ,
                    isClient: Boolean(ac.isClient),
                },
                isPmCreditor: true,
                ecIndex: -1,
                pmCreditor: ac,
            });
        });
        return out;
    }, [effectiveCreditors, additionalCreditorsPm]);

    const creditorNamesTextList = useMemo(() => {
        const fromMain = effectiveCreditors.map((c) => resolvePartyStoredName(c)).filter(Boolean);
        const fromPm = additionalCreditorsPm.map((c) => resolvePartyStoredName(c)).filter(Boolean);
        const merged = [...fromMain, ...fromPm];
        return merged.length ? merged.join('، ') : '';
    }, [effectiveCreditors, additionalCreditorsPm]);

    return { creditorWorkspaceEntries, creditorNamesTextList };
}

import { useMemo } from 'react';

export function useDebtorScopedTimeline(
    activeTimelineEvents: any[],
    debtorBrowserTabsMode: boolean,
    activeWorkspaceDebtorForFollowup: { key: string; isPrimary: boolean } | null,
    primaryDebtorWorkspaceKey: string | undefined,
    timelineEventBelongsToDebtorWorkspace: (e: any, ak: string, pk: string) => boolean,
) {
    const activeTimelineEventsDebtorScoped = useMemo(() => {
        if (!debtorBrowserTabsMode || !activeWorkspaceDebtorForFollowup || !primaryDebtorWorkspaceKey) {
            return activeTimelineEvents;
        }
        const ak = activeWorkspaceDebtorForFollowup.key;
        return activeTimelineEvents.filter((e) =>
            timelineEventBelongsToDebtorWorkspace(e, ak, primaryDebtorWorkspaceKey)
        );
    }, [
        debtorBrowserTabsMode,
        activeWorkspaceDebtorForFollowup,
        activeTimelineEvents,
        primaryDebtorWorkspaceKey,
    ]);

    const timelineRadarPreviewLimit = useMemo(() => {
        const ev = debtorBrowserTabsMode ? activeTimelineEventsDebtorScoped : activeTimelineEvents;
        return ev.some((e) => Boolean(e.isPinned)) ? 5 : 3;
    }, [debtorBrowserTabsMode, activeTimelineEventsDebtorScoped, activeTimelineEvents]);

    return { activeTimelineEventsDebtorScoped, timelineRadarPreviewLimit };
}

import { useEffect, useMemo, useRef, useState } from 'react';
import { isPartyDeathCaseForRole } from '@/app/utils/partyDeathCaseScope';
import {
    isHeirSubstitutionAllowedClaimLite,
    isLikelyAlimonyClaimLite,
    isPersonalStatusNoHeirClaim,
} from '@/app/utils/partyDeathClaimPolicyLite';
import { resolveAlimonyBeneficiaryProfile } from '@/app/utils/alimonyBeneficiaryDeathUtils';

type DossierDeathStatusHeavyResult = {
    heirSubstitutionAllowed: boolean;
    ongoingAlimonyClaim: boolean;
    alimonyBeneficiaryProfile: {
        hasWifeBenefit?: boolean;
        childrenAlive?: number;
        anyBeneficiaryAlive?: boolean;
    } | null;
    needsCreditorHeirsEntry: boolean;
    needsDebtorHeirsEntry: boolean;
    creditorDeathMenuLabel: string;
    debtorDeathMenuLabel: string;
};

function resolveClaimForLite(claimType: string | undefined, executionData: any): string {
    if (claimType && String(claimType).trim()) return String(claimType);
    const direct = String(executionData?.claimType ?? '').trim();
    if (direct) return direct;
    const types = executionData?.claimTypes;
    if (Array.isArray(types)) {
        const hit = types.find((t: unknown) => typeof t === 'string' && String(t).trim());
        if (hit) return String(hit);
    }
    return '';
}

/**
 * علامات وفاة خفيفة فورية + إثراء سياسة/تسميات بعد إطار (dynamic import).
 * يُبقي مسار cold-open بلا partyDeathClaimPolicy / نفقة / طابور قرارات ثقيل.
 */
export function useDossierDeathStatus(
    executionData: any,
    debtors: any[],
    claimType?: string,
    decisionsStorageExecutionId?: string,
    decisionsReloadEpoch?: number,
) {
    const executionDataRef = useRef(executionData);
    executionDataRef.current = executionData;

    const isDebtorDeceasedForEvictionHeirs =
        executionData?.is_debtor_deceased === true ||
        isPartyDeathCaseForRole(executionData, 'debtor') ||
        Boolean(debtors[0] && (debtors[0] as { isDeceased?: boolean }).isDeceased);

    const creditorDeathMarked = useMemo(() => {
        const c0 = executionData?.creditors?.[0] as { isDeceased?: boolean } | undefined;
        return Boolean(executionData?.is_creditor_deceased || c0?.isDeceased);
    }, [executionData?.is_creditor_deceased, executionData?.creditors]);

    const debtorDeathMarked = useMemo(() => {
        const d0 = executionData?.debtors?.[0] as { isDeceased?: boolean } | undefined;
        return Boolean(executionData?.is_debtor_deceased || d0?.isDeceased);
    }, [executionData?.is_debtor_deceased, executionData?.debtors]);

    const claimForLite = resolveClaimForLite(claimType, executionData);
    const heirAllowedLite = isHeirSubstitutionAllowedClaimLite(claimForLite);
    const alimonyLite = isLikelyAlimonyClaimLite(claimForLite);
    const personalNoHeirLite = isPersonalStatusNoHeirClaim(claimForLite);

    const liteAlimonyBeneficiaryProfile = useMemo(() => {
        if (!alimonyLite) return null;
        try {
            return resolveAlimonyBeneficiaryProfile(executionData);
        } catch {
            return null;
        }
    }, [alimonyLite, executionData]);

    const liteCreditorDeathMenuLabel = useMemo(() => {
        if (alimonyLite) return 'الإبلاغ عن وفاة مستحقي النفقة';
        if (!heirAllowedLite || personalNoHeirLite) return 'الإبلاغ عن وفاة الدائن';
        return creditorDeathMarked
            ? 'طلب إحلال ورثة محل الدائن المتوفي'
            : 'الإبلاغ عن وفاة الدائن';
    }, [alimonyLite, creditorDeathMarked, heirAllowedLite, personalNoHeirLite]);

    const liteDebtorDeathMenuLabel = useMemo(() => {
        if (!heirAllowedLite) return 'الإبلاغ عن وفاة المدين';
        return debtorDeathMarked
            ? 'طلب إحلال ورثة محل المدين المتوفي'
            : 'الإبلاغ عن وفاة المدين';
    }, [debtorDeathMarked, heirAllowedLite]);

    const [heavy, setHeavy] = useState<DossierDeathStatusHeavyResult | null>(null);

    const alimonySourceKey = useMemo(() => {
        try {
            return JSON.stringify({
                claimTypes: executionData?.claimTypes,
                alimony: executionData?.alimony,
                death: executionData?.alimony_beneficiary_death,
                w: executionData?.monthlyWifeAlimony,
                c: executionData?.monthlyChildrenAlimony,
                n: executionData?.childrenCount ?? executionData?.children_count,
                ic: executionData?.is_creditor_deceased,
                id: executionData?.is_debtor_deceased,
            });
        } catch {
            return String(claimType ?? '');
        }
    }, [executionData, claimType]);

    useEffect(() => {
        let alive = true;
        void import('@/app/utils/dossierDeathStatusHeavy')
            .then(({ computeDossierDeathStatusHeavy }) => {
                if (!alive) return;
                setHeavy(
                    computeDossierDeathStatusHeavy({
                        executionData: executionDataRef.current,
                        claimType,
                        decisionsStorageExecutionId,
                        creditorDeathMarked,
                        debtorDeathMarked,
                    }),
                );
            })
            .catch(() => {
                /* الإبقاء على القيم الخفيفة */
            });
        return () => {
            alive = false;
        };
    }, [
        alimonySourceKey,
        claimType,
        creditorDeathMarked,
        debtorDeathMarked,
        decisionsReloadEpoch,
        decisionsStorageExecutionId,
    ]);

    return {
        isDebtorDeceasedForEvictionHeirs,
        creditorDeathMarked,
        debtorDeathMarked,
        creditorDeathMenuLabel: heavy?.creditorDeathMenuLabel ?? liteCreditorDeathMenuLabel,
        debtorDeathMenuLabel: heavy?.debtorDeathMenuLabel ?? liteDebtorDeathMenuLabel,
        heirSubstitutionAllowed: heavy?.heirSubstitutionAllowed ?? heirAllowedLite,
        ongoingAlimonyClaim: heavy?.ongoingAlimonyClaim ?? alimonyLite,
        alimonyBeneficiaryProfile: heavy?.alimonyBeneficiaryProfile ?? liteAlimonyBeneficiaryProfile,
        needsCreditorHeirsEntry: heavy?.needsCreditorHeirsEntry ?? false,
        needsDebtorHeirsEntry: heavy?.needsDebtorHeirsEntry ?? false,
        /** اكتمل إثراء السياسة الثقيلة (نفقة / قرارات إحلال) */
        deathStatusEnriched: heavy != null,
    };
}

import { useMemo } from 'react';
import type { ExecutionFile } from '@/app/types/execution';
import type { EvictionPremisesUse } from '@/app/utils/executionModuleStrategies';
import {
    inferEvictionPremisesUse,
    hasAnyEvictionFieldStepRecorded,
} from '@/app/utils/executionModuleStrategies';
import { resolveDossierHeaderFields } from '@/app/utils/executionDossierHeaderFields';
import { executionFileContentSignature } from './useExecutionData';

export function useDossierHeaderMetadata(
    executionData: ExecutionFile | null | undefined,
    classification: string | undefined,
    claimType: string,
    evictionCaseExpenses: any[],
    visitChildNames: string[],
    custodyWardNamesList: string[],
    evictionPremisesUseRaw: string | undefined,
    evictionPropertyTypeField: string,
    judgmentDate: string | undefined,
    activeCoerciveActions: any[],
    activeTimelineEvents: any[],
    docType: string,
    docNumber: string,
) {
    const headerFields = useMemo(
        () => resolveDossierHeaderFields(executionData),
        [executionData ? executionFileContentSignature(executionData) : ''],
    );

    const evictionPremisesUseResolved = useMemo(
        () =>
            inferEvictionPremisesUse({
                explicit: evictionPremisesUseRaw as EvictionPremisesUse | null | undefined,
                propertyTypeText: evictionPropertyTypeField,
            }),
        [evictionPremisesUseRaw, evictionPropertyTypeField]
    );

    const evictionCaseExpensesSum = useMemo(
        () => evictionCaseExpenses.reduce((s, x) => s + (Number(x.amount) || 0), 0),
        [evictionCaseExpenses]
    );

    const creditorExtraMinorNames =
        claimType === 'مشاهدة' ? visitChildNames : claimType === 'تسليم ولد' ? custodyWardNamesList : [];
    const creditorExtraMinorLabel =
        claimType === 'مشاهدة' ? 'أسماء الأولاد' : claimType === 'تسليم ولد' ? 'أسماء المحضونين' : '';

    const classificationDisplay = headerFields.classificationDisplay || '—';
    const claimTypeArabicDisplay = headerFields.claimTypeDisplay || '—';

    const lawyerStartedPostNoticeExecution = useMemo(
        () =>
            activeCoerciveActions.length > 0 ||
            hasAnyEvictionFieldStepRecorded(activeTimelineEvents),
        [activeCoerciveActions, activeTimelineEvents]
    );

    const judgmentDateDisplay = useMemo(() => {
        if (!judgmentDate) return '';
        const dt = new Date(judgmentDate);
        return Number.isNaN(dt.getTime()) ? judgmentDate : dt.toLocaleDateString('ar-IQ');
    }, [judgmentDate]);

    const showJudgmentMeta =
        Boolean(headerFields.docType) ||
        Boolean(headerFields.docNumber) ||
        Boolean(headerFields.judgmentDate);

    return {
        headerFields,
        evictionPremisesUseResolved,
        evictionCaseExpensesSum,
        creditorExtraMinorNames,
        creditorExtraMinorLabel,
        classificationDisplay,
        claimTypeArabicDisplay,
        lawyerStartedPostNoticeExecution,
        judgmentDateDisplay,
        showJudgmentMeta,
    };
}

import { useMemo } from 'react';
import { executionRowAppealPipelineActive } from '@/app/utils/executionDecisionAppealActive';
import { readExecutorDecisionsArray } from '@/app/utils/executorSeizureDecisionQueue';

interface UseExecutionAICopilotParams {
    decisionsStorageExecutionId: string;
    decisionsReloadEpoch: number;
}

/** قرارات المنفذ + أول طعن نشط — بدون مسار AI copilot (أُزيل في V1). */
export function useExecutionAICopilot(params: UseExecutionAICopilotParams) {
    const { decisionsStorageExecutionId, decisionsReloadEpoch } = params;

    const executionCopilotDecisions = useMemo(
        () => readExecutorDecisionsArray(decisionsStorageExecutionId),
        [decisionsStorageExecutionId, decisionsReloadEpoch],
    );

    const firstActiveAppealDecisionId = useMemo(() => {
        const rows = readExecutorDecisionsArray(decisionsStorageExecutionId);
        for (let i = 0; i < rows.length; i++) {
            const r = rows[i];
            if (executionRowAppealPipelineActive(r)) {
                const id = r.id;
                if (typeof id === 'string' && id) return id;
            }
        }
        return null;
    }, [decisionsStorageExecutionId, decisionsReloadEpoch]);

    const hasApprovedCollectionDecision = useMemo(() => {
        if (!Array.isArray(executionCopilotDecisions)) return false;
        return executionCopilotDecisions.some(
            (r) => r?.requestKind === 'unified_collection' && r?.executorOutcome === 'approved',
        );
    }, [executionCopilotDecisions]);

    return {
        executionCopilotDecisions,
        firstActiveAppealDecisionId,
        hasApprovedCollectionDecision,
    };
}

import { useLayoutEffect, useRef, type MutableRefObject } from 'react';
import { EXECUTION_FOLLOWUP_MODAL_SNAPSHOT_FIELD_KEYS } from '../followupSnapshotFieldKeys';
import { assignExecutionPhoneBodyScope } from './pickExecutionPhoneBodyProps';
import { assignExecutionShellOverlayScope } from './pickExecutionShellOverlayProps';

/**
 * مزامنة scope ref أثناء الـ render عند تغيّر syncToken — وليس فقط في useLayoutEffect.
 *
 * السبب: PhoneBody / ShellOverlays يقرآن الـ ref في نفس دورة الـ render التي يتغيّر فيها
 * الـ fingerprint. إن أُجّلت المزامنة إلى layout effect، يقرآن قيماً قديمة (مثلاً
 * showExecutionFinancialHub=false) ثم لا يحدث re-render ثانٍ بعد تحديث الـ ref — فيبدو
 * أن المركز المالي / سجل الحجز «لا يفتح» أو «لا يُغلق».
 */
function useExecutionScopedChunkScopeRef(
    syncScope: boolean,
    syncToken: string,
    getSources: () => Record<string, unknown>,
    assignScope: (target: Record<string, unknown>, sources: Record<string, unknown>) => void,
): MutableRefObject<Record<string, unknown>> {
    const scopeRef = useRef<Record<string, unknown>>({});
    const getSourcesRef = useRef(getSources);
    const lastSyncedTokenRef = useRef<string | null>(null);
    getSourcesRef.current = getSources;

    if (syncScope && lastSyncedTokenRef.current !== syncToken) {
        assignScope(scopeRef.current, getSourcesRef.current());
        lastSyncedTokenRef.current = syncToken;
    }

    useLayoutEffect(() => {
        if (!syncScope) return;
        // شبكة أمان إن تغيّر getSources بعد commit دون قفزة token جديدة
        assignScope(scopeRef.current, getSourcesRef.current());
        lastSyncedTokenRef.current = syncToken;
    }, [syncScope, syncToken]);

    return scopeRef;
}

export function useExecutionPhoneBodyChunkScopeRef(
    syncPhoneBody: boolean,
    syncToken: string,
    getSources: () => Record<string, unknown>,
): MutableRefObject<Record<string, unknown>> {
    return useExecutionScopedChunkScopeRef(syncPhoneBody, syncToken, getSources, assignExecutionPhoneBodyScope);
}

function assignExecutionShellOverlayScopeWithFollowupSnapshot(
    target: Record<string, unknown>,
    sources: Record<string, unknown>,
): void {
    assignExecutionShellOverlayScope(target, sources);
    for (const key of EXECUTION_FOLLOWUP_MODAL_SNAPSHOT_FIELD_KEYS) {
        if (Object.prototype.hasOwnProperty.call(sources, key)) {
            target[key] = sources[key];
        }
    }
}

export function useExecutionShellOverlayChunkScopeRef(
    syncShellOverlays: boolean,
    syncToken: string,
    getSources: () => Record<string, unknown>,
): MutableRefObject<Record<string, unknown>> {
    return useExecutionScopedChunkScopeRef(
        syncShellOverlays,
        syncToken,
        getSources,
        assignExecutionShellOverlayScopeWithFollowupSnapshot,
    );
}

