/** Phone-body local state + dossier lifecycle safe wrappers */
import React from 'react';
import { useExecutionDashboardStore as executionDashboardStoreApi } from '@/app/stores/executionDashboardStore';
import type { DossierLifecycleStatus } from '@/app/types/execution';
import { normalizeDossierLifecycleStatus } from '@/app/types/execution';
import { applyPhoneBodyDossierLifecycleFallback } from '../components/executionDashboardPhoneBodyBridges';
import { isExecutionHandlerStubLeaf } from './executionHandlerClusterStubs';
import { readExecutionPhoneBodyScope } from './executionPhoneBodyScope';

function resolveLiveLifecycleHandler(
    scope: Record<string, unknown>,
    flatKey: 'handleDossierLifecyclePick' | 'handleDossierLifecycleConfirmDetails',
): ((...args: unknown[]) => void) | null {
    const actions =
        scope.dossierLifecycleActions && typeof scope.dossierLifecycleActions === 'object'
            ? (scope.dossierLifecycleActions as Record<string, unknown>)
            : null;
    const candidates = [scope[flatKey], actions?.[flatKey]];
    for (const candidate of candidates) {
        if (typeof candidate !== 'function') continue;
        if (isExecutionHandlerStubLeaf(candidate)) continue;
        return candidate as (...args: unknown[]) => void;
    }
    return null;
}

export function useExecutionDashboardPhoneBodyLocalState(
    scope: Record<string, any>,
    scopeRef?: React.MutableRefObject<Record<string, unknown>>,
) {
    // المفاتيح المسطّحة لحالة دورة حياة الإضبارة لم تَعُد تُنسَخ إلى الـ chunk scope —
    // المصدر الوحيد هو dossierLifecyclePanel (+ dossierLifecycleActions / dossierStatusDraft).
    const {
        activeGraceTasks,
        dossierLifecycleActions,
        dossierLifecyclePanel,
        dossierStatusDraft,
        executionData,
        followupSpecialization,
        inabaTargets,
        resolveCalendarUserId,
        setShowAppointmentModal,
        setShowDocumentsModal,
        setShowExecutionTrashModal,
        setShowNotesModal,
        shouldShowGuarantorExternalHub,
        showToast,
        subFiles,
        toggleHeaderExpanded,
        trashedCaseNotes,
        trashedCaseTasks,
        trashedTimelineEvents,
    } = scope;

    const followupSpec =
        followupSpecialization && typeof followupSpecialization === 'object'
            ? (followupSpecialization as Record<string, unknown>)
            : ({} as Record<string, unknown>);
    const safeInabaTargets = Array.isArray(inabaTargets) ? inabaTargets : [];
    const safeSubFiles = Array.isArray(subFiles) ? subFiles : [];
    const safeTrashedTimelineEvents = Array.isArray(trashedTimelineEvents) ? trashedTimelineEvents : [];
    const safeTrashedCaseNotes = Array.isArray(trashedCaseNotes) ? trashedCaseNotes : [];
    const safeTrashedCaseTasks = Array.isArray(trashedCaseTasks) ? trashedCaseTasks : [];
    const safeActiveGraceTasks = Array.isArray(activeGraceTasks) ? activeGraceTasks : [];
    const safeDossierLifecyclePanel =
        dossierLifecyclePanel && typeof dossierLifecyclePanel === 'object'
            ? (dossierLifecyclePanel as Record<string, unknown>)
            : ({} as Record<string, unknown>);
    const safeDossierLifecycleActions =
        dossierLifecycleActions && typeof dossierLifecycleActions === 'object'
            ? (dossierLifecycleActions as Record<string, unknown>)
            : ({} as Record<string, unknown>);
    const localDossierLifecyclePopoverRef = React.useRef<HTMLDivElement | null>(null);
    const localDossierLifecyclePanelPortalRef = React.useRef<HTMLDivElement | null>(null);
    const safeResolveCalendarUserId =
        typeof resolveCalendarUserId === 'function'
            ? resolveCalendarUserId
            : (() => null);
    const createModalSetterFallback = React.useMemo(
        () =>
            (modalName: string) =>
            (show: boolean) => {
                if (!modalName) return;
                const store = executionDashboardStoreApi.getState();
                if (show) {
                    store.openModal(modalName as never);
                    return;
                }
                store.closeModal(modalName as never);
            },
        [],
    );
    const [timelineAccordionExpandedFallback, setTimelineAccordionExpandedFallback] = React.useState(false);
    const safeShouldShowGuarantorExternalHub =
        typeof shouldShowGuarantorExternalHub === 'function'
            ? shouldShowGuarantorExternalHub
            : (() => false);
    const safeSetDossierReasonDraft =
        typeof safeDossierLifecyclePanel.setDossierReasonDraft === 'function'
            ? (safeDossierLifecyclePanel.setDossierReasonDraft as (value: string) => void)
            : (() => undefined);
    const safeSetDossierDateDraft =
        typeof safeDossierLifecyclePanel.setDossierDateDraft === 'function'
            ? (safeDossierLifecyclePanel.setDossierDateDraft as (value: string) => void)
            : (() => undefined);
    const safeSetDossierLifecyclePanelOpen =
        typeof safeDossierLifecyclePanel.setDossierLifecyclePanelOpen === 'function'
            ? (safeDossierLifecyclePanel.setDossierLifecyclePanelOpen as (updater: unknown) => void)
            : (() => undefined);
    const safeSetDossierLifecyclePanelPhase =
        typeof safeDossierLifecyclePanel.setDossierLifecyclePanelPhase === 'function'
            ? (safeDossierLifecyclePanel.setDossierLifecyclePanelPhase as (phase: string) => void)
            : (() => undefined);
    const safeSetDossierPendingStatus =
        typeof safeDossierLifecyclePanel.setDossierPendingStatus === 'function'
            ? (safeDossierLifecyclePanel.setDossierPendingStatus as (status: unknown) => void)
            : (() => undefined);
    const safeDossierLifecyclePanelOpen = Boolean(
        safeDossierLifecyclePanel.dossierLifecyclePanelOpen,
    );
    const safeDossierLifecyclePanelPhase =
        typeof safeDossierLifecyclePanel.dossierLifecyclePanelPhase === 'string'
            ? safeDossierLifecyclePanel.dossierLifecyclePanelPhase
            : 'menu';
    const safeDossierPendingStatus = safeDossierLifecyclePanel.dossierPendingStatus ?? null;
    const safeDossierStatusDraft =
        typeof dossierStatusDraft === 'string'
            ? dossierStatusDraft
            : typeof safeDossierLifecyclePanel.dossierStatusDraft === 'string'
              ? safeDossierLifecyclePanel.dossierStatusDraft
              : 'active';
    const committedDossierLifecycleStatus = React.useMemo<DossierLifecycleStatus>(
        () =>
            normalizeDossierLifecycleStatus(
                executionData?.dossier_lifecycle_status ?? safeDossierStatusDraft,
            ),
        [executionData?.dossier_lifecycle_status, safeDossierStatusDraft],
    );
    const [localDossierStatusDraft, setLocalDossierStatusDraft] = React.useState<DossierLifecycleStatus>(
        committedDossierLifecycleStatus,
    );
    const [localDossierLifecyclePanelOpen, setLocalDossierLifecyclePanelOpen] = React.useState(false);
    const [localDossierLifecyclePanelPhase, setLocalDossierLifecyclePanelPhase] = React.useState<'menu' | 'details'>('menu');
    const [localDossierPendingStatus, setLocalDossierPendingStatus] = React.useState<DossierLifecycleStatus | null>(null);
    React.useEffect(() => {
        setLocalDossierStatusDraft(committedDossierLifecycleStatus);
    }, [committedDossierLifecycleStatus]);
    const safeDossierReasonDraft =
        typeof safeDossierLifecyclePanel.dossierReasonDraft === 'string'
            ? safeDossierLifecyclePanel.dossierReasonDraft
            : '';
    const safeDossierDateDraft =
        typeof safeDossierLifecyclePanel.dossierDateDraft === 'string'
            ? safeDossierLifecyclePanel.dossierDateDraft
            : '';
    const safeDossierLifecyclePopoverRef = safeDossierLifecyclePanel.dossierLifecyclePopoverRef;
    const safeDossierLifecyclePanelPortalRef =
        safeDossierLifecyclePanel.dossierLifecyclePanelPortalRef;
    const safeDossierLifecyclePopStyle = safeDossierLifecyclePanel.dossierLifecyclePopStyle ?? null;
    const safeHandleDossierLifecyclePick = React.useCallback(
        (status: unknown) => {
            const latest = {
                ...scope,
                ...(scopeRef ? readExecutionPhoneBodyScope(scopeRef) : {}),
            } as Record<string, unknown>;
            const handler = resolveLiveLifecycleHandler(latest, 'handleDossierLifecyclePick');
            if (handler) {
                handler(status);
                return;
            }
            showToast('تعذر تغيير حالة الإضبارة لأن الربط الحقيقي لم يصل إلى الواجهة بعد.', 'error');
        },
        [scope, scopeRef, showToast],
    );
    const safeHandleDossierLifecycleConfirmDetails = React.useCallback(
        (reasonOverride?: string, dateOverride?: string) => {
            const latest = {
                ...scope,
                ...(scopeRef ? readExecutionPhoneBodyScope(scopeRef) : {}),
            } as Record<string, unknown>;
            const handler = resolveLiveLifecycleHandler(
                latest,
                'handleDossierLifecycleConfirmDetails',
            );
            if (handler) {
                handler(reasonOverride, dateOverride);
                return;
            }
            showToast('تعذر اعتماد حالة الإضبارة لأن الربط الحقيقي لم يصل إلى الواجهة بعد.', 'error');
        },
        [scope, scopeRef, showToast],
    );
    const safeApplyDossierLifecycleToFileAndTimeline = React.useCallback(
        (status: DossierLifecycleStatus, reason: string, date: string) => {
            return applyPhoneBodyDossierLifecycleFallback({
                status,
                reason,
                date,
                apply:
                    typeof safeDossierLifecycleActions.applyDossierLifecycleToFileAndTimeline ===
                    'function'
                        ? (safeDossierLifecycleActions.applyDossierLifecycleToFileAndTimeline as (
                              nextStatus: DossierLifecycleStatus,
                              nextReason: string,
                              nextDate: string,
                          ) => boolean)
                        : null,
                pick: safeHandleDossierLifecyclePick,
                confirm: safeHandleDossierLifecycleConfirmDetails,
            });
        },
        [
            safeDossierLifecycleActions,
            safeHandleDossierLifecycleConfirmDetails,
            safeHandleDossierLifecyclePick,
        ],
    );
    const currentDossierStatusReason = React.useMemo(() => {
        const value = executionData?.dossier_status_reason;
        return typeof value === 'string' ? value : '';
    }, [executionData?.dossier_status_reason]);
    const currentDossierStatusDate = React.useMemo(() => {
        const value = executionData?.dossier_status_date;
        return typeof value === 'string' ? value : '';
    }, [executionData?.dossier_status_date]);
    const localDossierReasonSeed =
        localDossierPendingStatus && localDossierPendingStatus === committedDossierLifecycleStatus
            ? currentDossierStatusReason
            : '';
    const localDossierDateSeed =
        localDossierPendingStatus && localDossierPendingStatus === committedDossierLifecycleStatus
            ? currentDossierStatusDate
            : '';
    const safeSetShowAppointmentModal =
        typeof setShowAppointmentModal === 'function'
            ? setShowAppointmentModal
            : createModalSetterFallback('showAppointmentModal');
    const safeSetShowNotesModal =
        typeof setShowNotesModal === 'function'
            ? setShowNotesModal
            : createModalSetterFallback('showNotesModal');
    const safeSetShowDocumentsModal =
        typeof setShowDocumentsModal === 'function'
            ? setShowDocumentsModal
            : createModalSetterFallback('showDocumentsModal');
    const safeSetShowExecutionTrashModal =
        typeof setShowExecutionTrashModal === 'function'
            ? setShowExecutionTrashModal
            : createModalSetterFallback('showExecutionTrashModal');
    const safeToggleHeaderExpanded =
        typeof toggleHeaderExpanded === 'function'
            ? toggleHeaderExpanded
            : (() => undefined);

    return {
        followupSpec,
        safeInabaTargets,
        safeSubFiles,
        safeTrashedTimelineEvents,
        safeTrashedCaseNotes,
        safeTrashedCaseTasks,
        safeActiveGraceTasks,
        safeDossierLifecyclePanel,
        safeDossierLifecycleActions,
        localDossierLifecyclePopoverRef,
        localDossierLifecyclePanelPortalRef,
        safeResolveCalendarUserId,
        createModalSetterFallback,
        timelineAccordionExpandedFallback,
        setTimelineAccordionExpandedFallback,
        safeShouldShowGuarantorExternalHub,
        safeSetDossierReasonDraft,
        safeSetDossierDateDraft,
        safeSetDossierLifecyclePanelOpen,
        safeSetDossierLifecyclePanelPhase,
        safeSetDossierPendingStatus,
        safeDossierLifecyclePanelOpen,
        safeDossierLifecyclePanelPhase,
        safeDossierPendingStatus,
        safeDossierStatusDraft,
        committedDossierLifecycleStatus,
        localDossierStatusDraft,
        setLocalDossierStatusDraft,
        localDossierLifecyclePanelOpen,
        setLocalDossierLifecyclePanelOpen,
        localDossierLifecyclePanelPhase,
        setLocalDossierLifecyclePanelPhase,
        localDossierPendingStatus,
        setLocalDossierPendingStatus,
        safeDossierReasonDraft,
        safeDossierDateDraft,
        safeDossierLifecyclePopoverRef,
        safeDossierLifecyclePanelPortalRef,
        safeDossierLifecyclePopStyle,
        safeHandleDossierLifecyclePick,
        safeHandleDossierLifecycleConfirmDetails,
        safeApplyDossierLifecycleToFileAndTimeline,
        currentDossierStatusReason,
        currentDossierStatusDate,
        localDossierReasonSeed,
        localDossierDateSeed,
        safeSetShowAppointmentModal,
        safeSetShowNotesModal,
        safeSetShowDocumentsModal,
        safeSetShowExecutionTrashModal,
        safeToggleHeaderExpanded,
    };
}

/** Phone-body bridge / safe modal + edit handlers */
import React from 'react';
import { flushSync } from 'react-dom';
import { readExecutionPhoneBodyScope } from './executionPhoneBodyScope';
import {
    bridgeOpenEditDossierMeta,
    bridgeOpenEditParty,
    bridgeOpenParentDossierMetaEdit,
    buildFallbackDossierMetaDraftFromScope,
    openPhoneBodyModalWithBridge,
} from '../components/executionDashboardPhoneBodyBridges';
import {
    prefetchExecutionDocumentsOverlay,
    prefetchExecutionFinanceOverlay,
    prefetchExecutionNotesOverlay,
} from '../executionDashboardOverlayPrefetch';
import {
    LazyExecutionFinancialHubPortal,
    LazyFinancialOperationsCenter,
} from '../executionDashboardLazyRegistry';
import { useExecutionDashboardStore } from '@/app/stores/executionDashboardStore';
import { isExecutionHandlerStubLeaf } from './executionHandlerClusterStubs';

export function useExecutionDashboardPhoneBodySafeHandlers(
    input: Record<string, any>,
) {
    const {
        scopeRef,
        debtorsSectionRef,
        handleDebtorEmploymentToggle,
        handleMemoFollowupClick,
        openDecisionsModalWithBoot,
        openFinancialHubLedger,
        openGuarantorDetailsModal,
        primaryDebtorWorkspaceKey,
        setExecutionDebtorTabIndex,
        setFinancialHubAutoOpenMode,
        setFinancialHubSeizedMovableId,
        setFinancialHubSeizedPropertyId,
        setIsFinancialCenterExpanded,
        setShowAppointmentModal,
        setShowDecisionsModal: _setShowDecisionsModal,
        setShowEvictionExpenseModal,
        setShowExecutionFinancialHub,
        setShowLedgerModal,
        setShowNotesModal,
        setShowPaymentCalculator,
        setShowSettlementCalculator,
        setShowTimelineModal,
        setShowUnifiedExecutionModal,
        setShowUnifiedSummonsModal,
        setSummonsContextDebtorKey,
        setSummonsHubInitialMainTab,
        setTimelineAccordionExpanded,
        showToast,
        timelineAccordionExpanded,
        createModalSetterFallback,
        safeSetShowAppointmentModal,
        safeSetShowNotesModal,
        safeSetShowDocumentsModal,
        timelineAccordionExpandedFallback,
        setTimelineAccordionExpandedFallback,
    } = input;

    const readLatestPhoneBodyScope = React.useCallback(
        () => readExecutionPhoneBodyScope(scopeRef) as Record<string, any>,
        [scopeRef],
    );
    const schedulePhoneBodyScopeBridge = React.useCallback((task: () => void) => {
        if (typeof requestAnimationFrame === 'function') {
            requestAnimationFrame(() => {
                task();
            });
            return;
        }
        window.setTimeout(task, 0);
    }, []);
    const safeOpenEditDossierMeta = React.useCallback(() => {
        if (
            bridgeOpenEditDossierMeta({
                readLatestScope: readLatestPhoneBodyScope,
                scheduleBridge: schedulePhoneBodyScopeBridge,
                buildFallbackDraft: buildFallbackDossierMetaDraftFromScope,
            })
        ) {
            return;
        }
        showToast('تعذر فتح تعديل بيانات الإضبارة لأن الربط الحقيقي لم يصل إلى الواجهة بعد.', 'error');
    }, [
        readLatestPhoneBodyScope,
        schedulePhoneBodyScopeBridge,
        showToast,
    ]);
    const safeOpenParentDossierMetaEdit = React.useCallback(() => {
        if (
            bridgeOpenParentDossierMetaEdit({
                readLatestScope: readLatestPhoneBodyScope,
                scheduleBridge: schedulePhoneBodyScopeBridge,
            })
        ) {
            return;
        }
        showToast('تعذر فتح تعديل بيانات الحاوية الأبوية لأن الربط الحقيقي لم يصل إلى الواجهة بعد.', 'error');
    }, [readLatestPhoneBodyScope, schedulePhoneBodyScopeBridge, showToast]);
    const safeOpenEditParty = React.useCallback(
        (
            kind: 'creditor' | 'debtor',
            index: number,
            opts?: { forceHeirs?: boolean; party?: unknown },
        ) => {
            if (
                bridgeOpenEditParty({
                    kind,
                    index,
                    opts,
                    readLatestScope: readLatestPhoneBodyScope,
                    scheduleBridge: schedulePhoneBodyScopeBridge,
                })
            ) {
                return;
            }
            showToast(
                kind === 'debtor'
                    ? 'تعذر فتح تعديل بيانات المدين لأن الربط الحقيقي لم يصل إلى الواجهة بعد.'
                    : 'تعذر فتح تعديل بيانات الدائن لأن الربط الحقيقي لم يصل إلى الواجهة بعد.',
                'error',
            );
        },
        [readLatestPhoneBodyScope, schedulePhoneBodyScopeBridge, showToast],
    );
    const safeHandleDebtorEmploymentToggle = React.useCallback(
        (payload: { debtorKey: string; isPrimary: boolean }) => {
            if (typeof handleDebtorEmploymentToggle === 'function') {
                handleDebtorEmploymentToggle(payload);
                return;
            }
            showToast('تعذر تبديل صفة المدين لأن الربط الحقيقي لم يصل إلى الواجهة بعد.', 'error');
        },
        [handleDebtorEmploymentToggle, showToast],
    );
    const directHandleMemoFollowupClick = React.useCallback(() => {
        const latest = readLatestPhoneBodyScope();
        const fromScope = latest?.handleMemoFollowupClick;
        const openPersisted = latest?.openFollowupModalPersisted;
        const candidates = [fromScope, handleMemoFollowupClick, openPersisted];
        for (const candidate of candidates) {
            if (typeof candidate !== 'function') continue;
            if (isExecutionHandlerStubLeaf(candidate)) continue;
            candidate();
            return;
        }
        try {
            useExecutionDashboardStore.getState().openModal('showUnifiedExecutionModal');
        } catch {
            showToast('تعذر فتح محضر المتابعة لأن الربط الحقيقي لم يصل إلى الواجهة بعد.', 'error');
        }
    }, [handleMemoFollowupClick, readLatestPhoneBodyScope, showToast]);
    const directOpenDecisionsModalWithBoot = React.useCallback(
        (opts: { tab: string }) => {
            if (typeof openDecisionsModalWithBoot === 'function') {
                openDecisionsModalWithBoot(opts);
                return;
            }
            if (typeof _setShowDecisionsModal === 'function') {
                flushSync(() => {
                    _setShowDecisionsModal(true);
                });
                return;
            }
            showToast('تعذر فتح القرارات والطعون حالياً.', 'error');
        },
        [_setShowDecisionsModal, openDecisionsModalWithBoot, showToast],
    );
    const safeOpenAppointmentModal = React.useCallback(() => {
        prefetchExecutionNotesOverlay();
        openPhoneBodyModalWithBridge({
            readLatestScope: readLatestPhoneBodyScope,
            scheduleBridge: schedulePhoneBodyScopeBridge,
            commitBridge: (task) => flushSync(task),
            modalFlagKey: 'showAppointmentModal',
            modalSetterKey: 'setShowAppointmentModal',
            fallbackSetter: createModalSetterFallback('showAppointmentModal'),
            directSetter: safeSetShowAppointmentModal,
        });
    }, [
        createModalSetterFallback,
        readLatestPhoneBodyScope,
        safeSetShowAppointmentModal,
        schedulePhoneBodyScopeBridge,
    ]);
    const directOpenNotesModal = React.useCallback(() => {
        prefetchExecutionNotesOverlay();
        openPhoneBodyModalWithBridge({
            readLatestScope: readLatestPhoneBodyScope,
            scheduleBridge: schedulePhoneBodyScopeBridge,
            commitBridge: (task) => flushSync(task),
            modalFlagKey: 'showNotesModal',
            modalSetterKey: 'setShowNotesModal',
            fallbackSetter: createModalSetterFallback('showNotesModal'),
            directSetter: safeSetShowNotesModal,
        });
    }, [
        createModalSetterFallback,
        readLatestPhoneBodyScope,
        safeSetShowNotesModal,
        schedulePhoneBodyScopeBridge,
    ]);
    const directOpenDocumentsModal = React.useCallback(() => {
        prefetchExecutionDocumentsOverlay();
        safeSetShowDocumentsModal(true);
    }, [safeSetShowDocumentsModal]);
    const directOpenTimelineModal = React.useCallback(() => {
        if (typeof setShowTimelineModal === 'function') {
            setShowTimelineModal(true);
            return;
        }
        showToast('تعذر فتح السجل الكامل لأن الربط الحقيقي لم يصل إلى الواجهة بعد.', 'error');
    }, [setShowTimelineModal, showToast]);
    const directOpenLedgerModal = React.useCallback(() => {
        if (typeof setShowLedgerModal === 'function') {
            setShowLedgerModal(true);
            return;
        }
        showToast('تعذر فتح دفتر الأستاذ لأن الربط الحقيقي لم يصل إلى الواجهة بعد.', 'error');
    }, [setShowLedgerModal, showToast]);
    const directOpenEvictionExpenseModal = React.useCallback(() => {
        if (typeof setShowEvictionExpenseModal === 'function') {
            setShowEvictionExpenseModal(true);
            return;
        }
        showToast('تعذر فتح مصاريف الإخلاء لأن الربط الحقيقي لم يصل إلى الواجهة بعد.', 'error');
    }, [setShowEvictionExpenseModal, showToast]);
    const directOpenPaymentCalculator = React.useCallback(() => {
        if (typeof setShowPaymentCalculator === 'function') {
            setShowPaymentCalculator(true);
            return;
        }
        showToast('تعذر فتح حاسبة الدفع لأن الربط الحقيقي لم يصل إلى الواجهة بعد.', 'error');
    }, [setShowPaymentCalculator, showToast]);
    const directOpenSettlementCalculator = React.useCallback(() => {
        if (typeof setShowSettlementCalculator === 'function') {
            setShowSettlementCalculator(true);
            return;
        }
        showToast('تعذر فتح حاسبة التسوية لأن الربط الحقيقي لم يصل إلى الواجهة بعد.', 'error');
    }, [setShowSettlementCalculator, showToast]);
    const directOpenUnifiedSummonsHub = React.useCallback(
        (
            options: {
                debtorKey?: string | null;
                initialMainTab?: 'tabligh' | 'taklif' | 'nashr' | 'guarantor' | null;
            } = {},
        ) => {
            if (
                typeof setSummonsContextDebtorKey === 'function' &&
                typeof setSummonsHubInitialMainTab === 'function' &&
                typeof setShowUnifiedSummonsModal === 'function'
            ) {
                setSummonsContextDebtorKey(options.debtorKey ?? null);
                setSummonsHubInitialMainTab(options.initialMainTab ?? null);
                setShowUnifiedSummonsModal(true);
                return;
            }
            showToast('تعذر فتح مركز التبليغات لأن الربط الحقيقي لم يصل إلى الواجهة بعد.', 'error');
        },
        [
            setShowUnifiedSummonsModal,
            setSummonsContextDebtorKey,
            setSummonsHubInitialMainTab,
            showToast,
        ],
    );
    const directOpenFinancialCenter = React.useCallback(() => {
        prefetchExecutionFinanceOverlay({ force: true });

        const openHub = () => {
            const latest = readLatestPhoneBodyScope();
            const setHub =
                typeof setShowExecutionFinancialHub === 'function'
                    ? setShowExecutionFinancialHub
                    : typeof latest.setShowExecutionFinancialHub === 'function'
                      ? (latest.setShowExecutionFinancialHub as (v: boolean) => void)
                      : null;
            const setExpanded =
                typeof setIsFinancialCenterExpanded === 'function'
                    ? setIsFinancialCenterExpanded
                    : typeof latest.setIsFinancialCenterExpanded === 'function'
                      ? (latest.setIsFinancialCenterExpanded as (v: boolean) => void)
                      : null;
            const setUnified =
                typeof setShowUnifiedExecutionModal === 'function'
                    ? setShowUnifiedExecutionModal
                    : typeof latest.setShowUnifiedExecutionModal === 'function'
                      ? (latest.setShowUnifiedExecutionModal as (v: boolean) => void)
                      : null;
            const openLedger =
                typeof openFinancialHubLedger === 'function'
                    ? openFinancialHubLedger
                    : typeof latest.openFinancialHubLedger === 'function'
                      ? (latest.openFinancialHubLedger as () => void)
                      : null;

            if (setUnified) setUnified(false);
            if (setExpanded) setExpanded(true);
            if (openLedger) {
                openLedger();
                return true;
            }
            if (setHub) {
                setHub(true);
                return true;
            }
            return false;
        };

        // فتح فوري — لا حجب النقرة بانتظار preload (FocInstantShell يملأ الفجوة إن لزم)
        let opened = false;
        flushSync(() => {
            opened = openHub();
        });
        if (!opened) {
            if (typeof setShowLedgerModal === 'function') {
                setShowLedgerModal(true);
            } else {
                showToast('تعذر فتح المركز المالي حالياً.', 'error');
            }
        }

        const hubReady =
            typeof LazyExecutionFinancialHubPortal.isPreloaded === 'function' &&
            LazyExecutionFinancialHubPortal.isPreloaded();
        const focReady =
            typeof LazyFinancialOperationsCenter.isPreloaded === 'function' &&
            LazyFinancialOperationsCenter.isPreloaded();
        if (!hubReady || !focReady) {
            void Promise.all([
                LazyExecutionFinancialHubPortal.preload(),
                LazyFinancialOperationsCenter.preload(),
            ]).catch(() => undefined);
        }
    }, [
        openFinancialHubLedger,
        readLatestPhoneBodyScope,
        setIsFinancialCenterExpanded,
        setShowExecutionFinancialHub,
        setShowLedgerModal,
        setShowUnifiedExecutionModal,
        showToast,
    ]);
    const closeFinancialHubPortal = React.useCallback(() => {
        if (typeof setFinancialHubAutoOpenMode === 'function') {
            setFinancialHubAutoOpenMode(null);
        }
        if (typeof setFinancialHubSeizedMovableId === 'function') {
            setFinancialHubSeizedMovableId(null);
        }
        if (typeof setFinancialHubSeizedPropertyId === 'function') {
            setFinancialHubSeizedPropertyId(null);
        }
        if (typeof setShowExecutionFinancialHub === 'function') {
            setShowExecutionFinancialHub(false);
        }
    }, [
        setFinancialHubAutoOpenMode,
        setFinancialHubSeizedMovableId,
        setFinancialHubSeizedPropertyId,
        setShowExecutionFinancialHub,
    ]);
    const toggleFinancialCenterExpanded = React.useCallback(() => {
        if (typeof setIsFinancialCenterExpanded === 'function') {
            setIsFinancialCenterExpanded((prev) => !prev);
            return;
        }
        showToast('تعذر فتح المركز المالي لأن الربط الحقيقي لم يصل إلى الواجهة بعد.', 'error');
    }, [setIsFinancialCenterExpanded, showToast]);
    const openGuarantorFollowupDetails = React.useCallback(() => {
        if (
            typeof setExecutionDebtorTabIndex !== 'function' ||
            typeof openGuarantorDetailsModal !== 'function'
        ) {
            showToast('تعذر فتح بيانات الكفيل لأن الربط الحقيقي لم يصل إلى الواجهة بعد.', 'error');
            return;
        }
        if (typeof setShowUnifiedExecutionModal === 'function') {
            setShowUnifiedExecutionModal(false);
        }
        setExecutionDebtorTabIndex(0);
        if (primaryDebtorWorkspaceKey) {
            debtorsSectionRef.current?.expandDebtor(primaryDebtorWorkspaceKey);
        }
        openGuarantorDetailsModal();
    }, [
        openGuarantorDetailsModal,
        primaryDebtorWorkspaceKey,
        setExecutionDebtorTabIndex,
        setShowUnifiedExecutionModal,
        showToast,
    ]);
    const safeTimelineAccordionExpanded =
        typeof timelineAccordionExpanded === 'boolean'
            ? timelineAccordionExpanded
            : timelineAccordionExpandedFallback;
    const safeSetTimelineAccordionExpanded =
        typeof setTimelineAccordionExpanded === 'function'
            ? setTimelineAccordionExpanded
            : setTimelineAccordionExpandedFallback;

    return {
        readLatestPhoneBodyScope,
        schedulePhoneBodyScopeBridge,
        safeOpenEditDossierMeta,
        safeOpenParentDossierMetaEdit,
        safeOpenEditParty,
        safeHandleDebtorEmploymentToggle,
        directHandleMemoFollowupClick,
        directOpenDecisionsModalWithBoot,
        safeOpenAppointmentModal,
        directOpenNotesModal,
        directOpenDocumentsModal,
        directOpenTimelineModal,
        directOpenLedgerModal,
        directOpenEvictionExpenseModal,
        directOpenPaymentCalculator,
        directOpenSettlementCalculator,
        directOpenUnifiedSummonsHub,
        directOpenFinancialCenter,
        closeFinancialHubPortal,
        toggleFinancialCenterExpanded,
        openGuarantorFollowupDetails,
        safeTimelineAccordionExpanded,
        safeSetTimelineAccordionExpanded,
    };
}

/** Read phone-body scope + fallback + raw prop destructure */
import {
    readExecutionPhoneBodyScope,
    useExecutionPhoneBodyScopeRef,
} from './executionPhoneBodyScope';
import { withPhoneBodyScopeFallback } from '../components/executionDashboardPhoneBodyScopeFallback';
import { pickExecutionPhoneBodyScopeReadBag } from './pickExecutionPhoneBodyScopeReadBag';

export function useExecutionDashboardPhoneBodyScopeRead(renderFingerprint?: string) {
    const scopeRef = useExecutionPhoneBodyScopeRef();
    const props = withPhoneBodyScopeFallback({
        ...readExecutionPhoneBodyScope(scopeRef),
        renderFingerprint,
    }) as Record<string, any>;
    return {
        scopeRef,
        props,
        ...pickExecutionPhoneBodyScopeReadBag(props),
    };
}

/**
 * توأم تجميع تاريخي — المسار الحيّ للإنتاج هو useExecutionDashboardCore
 * عبر ExecutionDashboardViewResolved → ResolvedRuntimeSurface.
 * يُبقى للعقود الهيكلية/المقارنات؛ لا يُستدعى كـ hook من Surface الحيّ.
 */
import { useCallback, useEffect, useMemo } from 'react';
import { registerExecutionHandlerStubNotifier } from './executionHandlerClusterStubs';
import { prefetchExecutionCoreHandlers } from '../executionCoreHandlersPrefetch';
import {
    shouldLoadExecutionHandlerClusterCoerciveHeavy,
    shouldLoadExecutionHandlerClusterDossierSupport,
    shouldLoadExecutionHandlerClusterFollowupAdminSpecial,
    shouldLoadExecutionHandlerClusterFollowupDossierControls,
    shouldLoadExecutionHandlerClusterFollowupHeavy,
    shouldLoadExecutionHandlerClusterFollowupOtherParty,
    shouldLoadExecutionHandlerClusterLight,
    shouldLoadExecutionHandlerClusterSeizureHeavy,
    shouldLoadExecutionHandlerClusterSeizureLog,
    shouldLoadExecutionHandlerClusterSeizureRequests,
} from './executionHandlerClusterGate';
import { buildExecutionDashboardCoreRuntimeTailInput } from './executionDashboardCore/buildExecutionDashboardCoreRuntimeTailInput';
import { buildExecutionDashboardCoreRuntimeVars } from './executionDashboardCore/buildExecutionDashboardCoreRuntimeVars';
import { pickCoreAssemblyHandlers } from './executionDashboardCore/pickCoreAssemblyHandlers';
import { buildExecutionDashboardCoreModalScopeInput } from './executionDashboardCore/buildExecutionDashboardCoreModalScopeInput';
import { buildExecutionDashboardCoreChunkFingerprint } from './executionDashboardCore/buildExecutionDashboardCoreChunkFingerprint';
import { SCOPE_LOCAL_ALL_KEYS, SCOPE_REST_ALL_KEYS } from './executionDashboardCore/buildScopeBundleGroups';
import { useExecutionDashboardCoreScopeAndChunk } from './executionDashboardCore/useExecutionDashboardCoreScopeAndChunk';
import {
    pickHandlerClusterAssemblyHandlers,
    pickHandlerClusterRestExtras,
} from './executionDashboardCore/pickHandlerClusterAssemblyHandlers';
import { pickKeysFromRuntimeBag } from './executionDashboardCore/pickKeysFromRuntimeBag';
import { useExecutionDashboardDossierAdminFollowupHandlers } from './executionDashboardCore/useExecutionDashboardDossierAdminFollowupHandlers';
import { useExecutionDossierLifecycleActionsOrchestrator } from '../orchestrators/useExecutionDossierLifecycleActionsOrchestrator';
import { useExecutionDashboardSupabaseTimelineHydrate } from './executionDashboardCore/useExecutionDashboardSupabaseTimelineHydrate';
import { useExecutionDashboardStore } from '@/app/stores/executionDashboardStore';
import { useExecutionDashboardDebtorEmploymentHandlers } from './executionDashboardCore/useExecutionDashboardDebtorEmploymentHandlers';
import { useExecutionDashboardPartyDeathOpeners } from './executionDashboardCore/useExecutionDashboardPartyDeathOpeners';
import type { PartyDeathLiveHandlers } from './executionDashboardCore/useExecutionDashboardPartyDeathOpeners';
import { useExecutionDashboardUnifiedDossierMetaWorkflow } from './executionDashboardCore/useExecutionDashboardUnifiedDossierMetaWorkflow';
import { useExecutionHandlerClusterAssembly } from './useExecutionHandlerClusterAssembly';
import { buildExecutionDashboardRuntimeAssemblyResult } from './executionDashboardCore/buildExecutionDashboardRuntimeAssemblyResult';
import type { ExecutionDashboardProps } from '../types';
import { prefetchExecutionHandlerClusterPartyDeathBridge } from '../executionDashboardHandlerClusterBridgeLazy';
import { scheduleIdleWork } from '@/app/utils/scheduleIdleWork';

export type RuntimeAssemblyBaseVm = {
    boot: Record<string, any>;
    pipelines: Record<string, any>;
    file: ExecutionDashboardProps['file'];
    executionId: ExecutionDashboardProps['executionId'];
    onClose: ExecutionDashboardProps['onClose'];
    onUpdate?: ExecutionDashboardProps['onUpdate'];
    viewExecutionData: unknown;
};

export function useExecutionDashboardRuntimeAssembly(baseVm: RuntimeAssemblyBaseVm) {
    const { boot, pipelines, file, executionId, onClose, onUpdate } = baseVm;

    const {
        workspacePipeline,
        fileMetadataBinding,
        followupDebtor,
        claimFinancialLedger,
        graceMasterPipeline,
        persistHandlerPipeline,
        financialStatus,
        specificDeliveryConvertedAmount,
        specificDeliveryFinancialized,
    } = pipelines;

    const {
        followupOrchestrator,
        seizureOrchestrator,
        coercionOrchestrator,
        dossierLifecyclePanel,
        decisionsOrchestrator,
        activeFinancialTab,
        activeTimelineFilter,
        executionPaused,
        toastVisible,
        toastMessage,
        toastType,
        toastEpoch,
        hideToast,
        showUnifiedExecutionModal,
        setShowUnifiedSummonsModal,
        setShowLedgerModal,
        setEditingNoteId,
        noticeVoluntaryPeriodEndOptimistic,
        voluntaryEndOptimistic,
        notificationCount,
        showExecutionFinancialHub,
        timelineAccordionExpanded,
        isFinancialCenterExpanded,
        isHeaderExpanded,
        setSeizedAssets,
        seizureDraftsByDecisionId,
        setSeizureDraftsByDecisionId,
        activeCoerciveActions,
        setActiveCoerciveActions,
    } = workspacePipeline;

    useExecutionDashboardSupabaseTimelineHydrate({
        executionDataId: workspacePipeline.executionData?.id,
        setTimelineEvents: workspacePipeline.setTimelineEvents,
    });

    const { claimFinancials } = claimFinancialLedger;
    const { isEvictionExecutionModule, total_execution_expenses } = claimFinancialLedger;
    const { graceAndSummoning, daysRemainingInGracePeriod, statuteStatus } = graceMasterPipeline;
    const { debtorWorkspaceContext, followupTabAssembly } = followupDebtor;
    const { followupSeizureTabs } = claimFinancialLedger;
    const { subsequentNoticeFlow, executorApprovalActions } = persistHandlerPipeline;
    const {
        classification,
        directorate,
        fileNumber,
        fileYear,
        docNumber,
        judgmentDate,
        evictionFullAddressField,
        evictionPremisesUseRaw,
        evictionPropertyDistrict,
        evictionPropertyNumber,
        evictionPropertyTypeField,
    } = fileMetadataBinding;

    const debtorEmploymentHandler = useExecutionDashboardDebtorEmploymentHandlers({
        executionDataRef: boot.executionDataRef,
        debtorWorkspaceEntries: followupDebtor.debtorWorkspaceEntries,
        nextTimelineId: workspacePipeline.nextTimelineId,
        persistExecutionMerge: persistHandlerPipeline.persistExecutionMerge,
        showToast: workspacePipeline.showToast,
        setTimelineEvents: workspacePipeline.setTimelineEvents,
    });

    /**
     * وفاة الخصوم — فتحات خفيفة على المسار البارد؛ الجسر الحقيقي يُحمَّل عند
     * نية قائمة ⋮ / نافذة الوفاة (لا stubs صامتة).
     */
    const {
        partyDeathHandlers,
        loadPartyDeathHandlerCluster,
        commitLiveHandlers: commitPartyDeathLiveHandlers,
    } = useExecutionDashboardPartyDeathOpeners({
        decisionsStorageExecutionId: boot.decisionsStorageExecutionId,
        decisionsReloadEpoch: workspacePipeline.decisionsReloadEpoch,
        executionId,
        executionDataId: boot.executionData?.id,
        executionDataRef: boot.executionDataRef,
        partyDeathModalParty: followupOrchestrator.partyDeathModalParty,
        setPartyDeathModalParty: followupOrchestrator.setPartyDeathModalParty,
        setPartyDeathModalDecisionId: followupOrchestrator.setPartyDeathModalDecisionId,
        showToast: workspacePipeline.showToast,
    });

    useEffect(() => {
        if (!loadPartyDeathHandlerCluster) return;
        return scheduleIdleWork(() => {
            prefetchExecutionHandlerClusterPartyDeathBridge();
        }, 80);
    }, [loadPartyDeathHandlerCluster]);

    const onPartyDeathHandlerClusterReady = useCallback((cluster: Record<string, unknown>) => {
        commitPartyDeathLiveHandlers(cluster as PartyDeathLiveHandlers);
    }, [commitPartyDeathLiveHandlers]);

    const dossierMetaWorkflow = useExecutionDashboardUnifiedDossierMetaWorkflow({
        executionData: boot.executionData,
        directorate,
        fileNumber,
        fileYear,
        docNumber,
        judgmentDate,
        classification,
        evictionPropertyNumber,
        evictionPropertyDistrict,
        evictionPropertyTypeField,
        evictionFullAddressField,
        evictionPremisesUseRaw,
        isEvictionExecutionModule,
        persistExecutionMerge: persistHandlerPipeline.persistExecutionMerge,
        parentDossierId: boot.parentDossierId,
        parentExecutionFile: boot.parentExecutionFile,
        onUpdate,
        setExecutionStorageTick: boot.setExecutionStorageTick,
        showToast: workspacePipeline.showToast,
    });

    useEffect(() => {
        const showToast = workspacePipeline.showToast;
        registerExecutionHandlerStubNotifier((path) => {
            prefetchExecutionCoreHandlers('light');
            prefetchExecutionCoreHandlers('dossier-support');
            if (typeof showToast === 'function') {
                showToast(
                    'جاري تجهيز أدوات الإضبارة — أعد المحاولة بعد لحظة.',
                    'info',
                );
            }
            if (typeof process !== 'undefined' && process.env?.NODE_ENV === 'development') {
                console.warn('[execution] handler still stub:', path);
            }
        });
        return () => {
            registerExecutionHandlerStubNotifier(null);
        };
    }, [workspacePipeline.showToast]);

    const handlerClusterGateInput = useMemo(
        () => ({
            showUnifiedExecutionModal,
            showUnifiedSummonsModal: boot.modals.showUnifiedSummonsModal,
            unifiedModalTab: followupDebtor.unifiedModalTab,
            showUnifiedSeizureLogModal: followupDebtor.showUnifiedSeizureLogModal,
            showCoerciveModal: boot.modals.showCoerciveModal,
            showAppointmentModal: boot.modals.showAppointmentModal,
            showSeizedAssetsModal: boot.modals.showSeizedAssetsModal,
            showPaymentModal: boot.modals.showPaymentModal,
            showNotificationModal: boot.modals.showNotificationModal,
            showNotesModal: boot.modals.showNotesModal,
            showCoerciveActionForm: workspacePipeline.showCoerciveActionForm,
            showEditDossierMetaModal: dossierMetaWorkflow.showEditDossierMetaModal,
            partyDeathModalParty: followupOrchestrator.partyDeathModalParty,
            dossierLifecyclePanelOpen: dossierLifecyclePanel.dossierLifecyclePanelOpen,
            isHeaderExpanded,
        }),
        [
            showUnifiedExecutionModal,
            boot.modals.showUnifiedSummonsModal,
            followupDebtor.unifiedModalTab,
            followupDebtor.showUnifiedSeizureLogModal,
            boot.modals.showCoerciveModal,
            boot.modals.showAppointmentModal,
            boot.modals.showSeizedAssetsModal,
            boot.modals.showPaymentModal,
            boot.modals.showNotificationModal,
            boot.modals.showNotesModal,
            workspacePipeline.showCoerciveActionForm,
            dossierMetaWorkflow.showEditDossierMetaModal,
            followupOrchestrator.partyDeathModalParty,
            dossierLifecyclePanel.dossierLifecyclePanelOpen,
            isHeaderExpanded,
        ],
    );

    // حمّل light فوراً عند وجود بيانات إضبارة — يقلّص نافذة stubs الصامتة لأدوات الملاحظات/الدفع/المواعيد
    const loadLightHandlerCluster = shouldLoadExecutionHandlerClusterLight(handlerClusterGateInput);
    const loadFollowupHeavyHandlerCluster =
        shouldLoadExecutionHandlerClusterFollowupHeavy(handlerClusterGateInput);
    const loadFollowupAdminSpecialHandlerCluster =
        shouldLoadExecutionHandlerClusterFollowupAdminSpecial(handlerClusterGateInput);
    const loadFollowupDossierControlsHandlerCluster =
        shouldLoadExecutionHandlerClusterFollowupDossierControls(handlerClusterGateInput);
    const loadFollowupOtherPartyHandlerCluster =
        shouldLoadExecutionHandlerClusterFollowupOtherParty(handlerClusterGateInput);
    const loadSeizureHeavyHandlerCluster =
        shouldLoadExecutionHandlerClusterSeizureHeavy(handlerClusterGateInput);
    const loadSeizureRequestsHandlerCluster =
        shouldLoadExecutionHandlerClusterSeizureRequests(handlerClusterGateInput);
    const loadSeizureLogHandlerCluster =
        shouldLoadExecutionHandlerClusterSeizureLog(handlerClusterGateInput);
    const loadCoerciveHeavyHandlerCluster =
        shouldLoadExecutionHandlerClusterCoerciveHeavy(handlerClusterGateInput);
    const loadPublicationNoticeHandlerCluster = Boolean(
        boot.modals.showUnifiedSummonsModal && !workspacePipeline.activeDebtorIsEmployee,
    );
    const loadDossierSupportHandlerCluster =
        shouldLoadExecutionHandlerClusterDossierSupport(handlerClusterGateInput);
    const loadAnyHeavyHandlerCluster =
        loadFollowupHeavyHandlerCluster || loadSeizureHeavyHandlerCluster || loadCoerciveHeavyHandlerCluster;

    const coreRuntimeTailInput = useMemo(
        () =>
            buildExecutionDashboardCoreRuntimeTailInput({
                boot,
                props: { file, executionId, onClose, onUpdate },
                specificDeliveryConvertedAmount,
                specificDeliveryFinancialized,
                financialStatus,
                daysRemainingInGracePeriod,
                statuteStatus,
                followupOrchestrator,
            }),
        [
            boot,
            file,
            executionId,
            onClose,
            onUpdate,
            specificDeliveryConvertedAmount,
            specificDeliveryFinancialized,
            financialStatus,
            daysRemainingInGracePeriod,
            statuteStatus,
            followupOrchestrator,
        ],
    );

    const handleMemoFollowupClick = useCallback(() => {
        if (typeof followupDebtor.closeUnifiedSeizureLog === 'function') {
            followupDebtor.closeUnifiedSeizureLog();
        }
        try {
            useExecutionDashboardStore.getState().openModal('showUnifiedExecutionModal');
        } catch {
            /* ignore */
        }
        if (typeof followupDebtor.openFollowupModalPersisted === 'function') {
            followupDebtor.openFollowupModalPersisted();
        }
    }, [followupDebtor]);

    const pushTimelineEventFromCore = useCallback(
        (...args: Parameters<NonNullable<typeof workspacePipeline.pushTimelineEventRef.current>>) => {
            const pushTimelineEvent = workspacePipeline.pushTimelineEventRef.current;
            if (typeof pushTimelineEvent === 'function') {
                return pushTimelineEvent(...args);
            }
            return false;
        },
        [workspacePipeline.pushTimelineEventRef],
    );

    const coreDossierAdminFollowupHandlersRaw = useExecutionDashboardDossierAdminFollowupHandlers({
        executionData: workspacePipeline.executionData,
        decisionsStorageExecutionId: boot.decisionsStorageExecutionId,
        specialRequestDate: followupOrchestrator.specialRequestDate,
        specialRequestManualTitle: followupOrchestrator.specialRequestManualTitle,
        specialRequestContent: followupOrchestrator.specialRequestContent,
        nextTimelineId: workspacePipeline.nextTimelineId,
        pushTimelineEvent: pushTimelineEventFromCore,
        showToast: workspacePipeline.showToast,
        setSpecialRequestTemplatePick: followupOrchestrator.setSpecialRequestTemplatePick,
        setSpecialRequestContent: followupOrchestrator.setSpecialRequestContent,
        setSpecialRequestManualTitle: followupOrchestrator.setSpecialRequestManualTitle,
        setSpecialRequestDate: followupOrchestrator.setSpecialRequestDate,
    });
    const coreDossierAdminFollowupHandlers = useMemo(
        () => ({ ...coreDossierAdminFollowupHandlersRaw }),
        [
            coreDossierAdminFollowupHandlersRaw.runSpecialFollowupSubmit,
        ],
    );

    const persistExecutionMergeFromCore = useCallback(
        (...args: Parameters<NonNullable<typeof workspacePipeline.persistExecutionMergeRef.current>>) => {
            const persistExecutionMerge = workspacePipeline.persistExecutionMergeRef.current;
            if (typeof persistExecutionMerge === 'function') {
                return persistExecutionMerge(...args);
            }
            return false;
        },
        [workspacePipeline.persistExecutionMergeRef],
    );

    const coreDossierLifecycleActionsRaw = useExecutionDossierLifecycleActionsOrchestrator({
        executionData: workspacePipeline.executionData,
        executionId,
        executionDataRef: boot.executionDataRef,
        dossierFileKey: boot.dossierFileKey,
        financialLedgerRef: workspacePipeline.financialLedgerRef,
        seizedAssetsSnapshotRef: workspacePipeline.seizedAssetsSnapshotRef,
        setTimelineEvents: workspacePipeline.setTimelineEvents,
        nextTimelineId: workspacePipeline.nextTimelineId,
        persistExecutionMerge: persistExecutionMergeFromCore,
        reconcileDossierLifecycle: boot.reconcileDossierLifecycle,
        showToast: workspacePipeline.showToast,
        dossierPendingStatus: dossierLifecyclePanel.dossierPendingStatus,
        dossierReasonDraft: dossierLifecyclePanel.dossierReasonDraft,
        dossierDateDraft: dossierLifecyclePanel.dossierDateDraft,
        setDossierReasonDraft: dossierLifecyclePanel.setDossierReasonDraft,
        setDossierDateDraft: dossierLifecyclePanel.setDossierDateDraft,
        setDossierPendingStatus: dossierLifecyclePanel.setDossierPendingStatus,
        setDossierLifecyclePanelOpen: dossierLifecyclePanel.setDossierLifecyclePanelOpen,
        setDossierLifecyclePanelPhase: dossierLifecyclePanel.setDossierLifecyclePanelPhase,
        closeDossierLifecyclePanel: dossierLifecyclePanel.closeDossierLifecyclePanel,
    });
    const coreDossierLifecycleActions = useMemo(
        () => ({ ...coreDossierLifecycleActionsRaw }),
        [
            coreDossierLifecycleActionsRaw.applyDossierLifecycleToFileAndTimeline,
            coreDossierLifecycleActionsRaw.handleDossierLifecyclePick,
            coreDossierLifecycleActionsRaw.handleDossierLifecycleConfirmDetails,
        ],
    );

    const coreRuntimeVars = useMemo(
        () =>
            buildExecutionDashboardCoreRuntimeVars({
                ...workspacePipeline,
                ...followupDebtor,
                ...claimFinancialLedger,
                ...graceMasterPipeline,
                ...persistHandlerPipeline,
                ...fileMetadataBinding,
                ...debtorEmploymentHandler,
                partyDeathHandlers,
                ...dossierMetaWorkflow,
                dossierMetaWorkflow,
                ...coreRuntimeTailInput,
                ...coreDossierAdminFollowupHandlers,
                ...coreDossierLifecycleActions,
                dossierLifecycleActions: coreDossierLifecycleActions,
                handleMemoFollowupClick,
            }),
        [
            workspacePipeline,
            followupDebtor,
            claimFinancialLedger,
            graceMasterPipeline,
            persistHandlerPipeline,
            fileMetadataBinding,
            debtorEmploymentHandler,
            partyDeathHandlers,
            dossierMetaWorkflow,
            coreRuntimeTailInput,
            coreDossierAdminFollowupHandlers,
            coreDossierLifecycleActions,
            handleMemoFollowupClick,
        ],
    );

    const {
        handlerCluster,
        handlerClusterEpoch,
        handlerClusterMountKey,
        lightHandlerClusterInput,
        followupAdminSpecialHandlerClusterInput,
        followupDossierControlsHandlerClusterInput,
        followupOtherPartyHandlerClusterInput,
        seizureHeavyHandlerClusterInput,
        coerciveHeavyHandlerClusterInput,
        publicationNoticeHandlerClusterInput,
        dossierSupportHandlerClusterInput,
        onLightHandlerClusterReady,
        onFollowupAdminSpecialHandlerClusterReady,
        onFollowupDossierControlsHandlerClusterReady,
        onFollowupOtherPartyHandlerClusterReady,
        onSeizureHeavyHandlerClusterReady,
        onCoerciveHeavyHandlerClusterReady,
        onDossierSupportHandlerClusterReady,
    } = useExecutionHandlerClusterAssembly({
        loadLightHandlerCluster,
        loadAnyHeavyHandlerCluster,
        loadFollowupAdminSpecialHandlerCluster,
        loadFollowupDossierControlsHandlerCluster,
        loadFollowupOtherPartyHandlerCluster,
        loadSeizureHeavyHandlerCluster,
        loadCoerciveHeavyHandlerCluster,
        loadPublicationNoticeHandlerCluster,
        loadDossierSupportHandlerCluster,
        coreRuntimeVars,
        followupOrchestrator,
        seizureOrchestrator,
        coercionOrchestrator,
        dossierLifecyclePanel,
        claimFinancials,
        graceAndSummoning,
        debtorWorkspaceContext,
        subsequentNoticeFlow,
        followupTabAssembly,
        followupSeizureTabs,
        decisionsOrchestrator,
        executionId,
        activeTabId: boot.activeTabId,
        decisionsReloadEpoch: workspacePipeline.decisionsReloadEpoch,
        activeFollowupDebtorKey: followupDebtor.activeFollowupDebtorKey,
    });

    const scopeLocalFlat = useMemo(
        () => pickKeysFromRuntimeBag(coreRuntimeVars, SCOPE_LOCAL_ALL_KEYS),
        [coreRuntimeVars],
    );
    const scopeRestFlat = useMemo(
        () => pickKeysFromRuntimeBag(coreRuntimeVars, SCOPE_REST_ALL_KEYS),
        [coreRuntimeVars],
    );

    const scopeRuntimeInput = useMemo(
        () => ({
            isEvictionExecutionModule,
            executionData: boot.executionData,
            executionId,
            file,
            executorApprovalActions,
            total_execution_expenses,
            setSeizedAssets,
            seizureDraftsByDecisionId,
            setSeizureDraftsByDecisionId,
            activeCoerciveActions,
            setActiveCoerciveActions,
            handlerClusterRestExtras: pickHandlerClusterRestExtras(handlerCluster),
        }),
        [
            isEvictionExecutionModule,
            boot.executionData,
            executionId,
            file,
            executorApprovalActions,
            total_execution_expenses,
            setSeizedAssets,
            seizureDraftsByDecisionId,
            setSeizureDraftsByDecisionId,
            activeCoerciveActions,
            setActiveCoerciveActions,
            handlerCluster,
        ],
    );

    const assemblyHandlers = useMemo(() => {
        const clusterHandlers = pickHandlerClusterAssemblyHandlers(handlerCluster);
        const coreHandlers = pickCoreAssemblyHandlers(coreRuntimeVars);
        const coreActions = coreHandlers.dossierLifecycleActions;
        const clusterActions = clusterHandlers.dossierLifecycleActions;
        const dossierLifecycleActions =
            coreActions && typeof coreActions === 'object' && !Array.isArray(coreActions)
                ? coreActions
                : clusterActions &&
                    typeof clusterActions === 'object' &&
                    !Array.isArray(clusterActions)
                  ? clusterActions
                  : coreActions;
        return {
            ...clusterHandlers,
            ...coreHandlers,
            ...(dossierLifecycleActions ? { dossierLifecycleActions } : {}),
            handleMemoFollowupClick: coreRuntimeVars.handleMemoFollowupClick,
            openFollowupModalPersisted: coreRuntimeVars.openFollowupModalPersisted,
        };
    }, [handlerCluster, coreRuntimeVars]);

    const modalScopeInput = useMemo(
        () =>
            buildExecutionDashboardCoreModalScopeInput({
                modals: boot.modals,
                setExecutionModal: boot.setExecutionModal,
                showLinkedDossierTimeline: boot.showLinkedDossierTimeline,
                showTransferFileNumberChangeModal: boot.showTransferFileNumberChangeModal,
                showEvictionExpenseModal: followupOrchestrator.showEvictionExpenseModal,
                showEvictionLawyerFeeModal: followupOrchestrator.showEvictionLawyerFeeModal,
                showEvictionResidentialGraceModal:
                    followupOrchestrator.showEvictionResidentialGraceModal,
                showGuarantorDetailsModal: seizureOrchestrator.showGuarantorDetailsModal,
                showHeirsNotificationModal: followupOrchestrator.showHeirsNotificationModal,
                showRealEstateSeizureModal: seizureOrchestrator.showRealEstateSeizureModal,
                showSolidaryCoerciveTargetModal:
                    followupOrchestrator.showSolidaryCoerciveTargetModal,
                showStayOfExecutionModal: followupOrchestrator.showStayOfExecutionModal,
                setShowDecisionsModal: boot.setShowDecisionsModal,
                setShowDocumentsModal: boot.setShowDocumentsModal,
                setShowTimelineModal: boot.setShowTimelineModal,
                setShowCoerciveModal: boot.setShowCoerciveModal,
                setShowNotificationModal: boot.setShowNotificationModal,
                setShowUnifiedSummonsModal,
                setShowPaymentModal: boot.setShowPaymentModal,
                setShowSeizedAssetsModal: boot.setShowSeizedAssetsModal,
                setShowNotesModal: boot.setShowNotesModal,
                setShowAppointmentModal: boot.setShowAppointmentModal,
                setShowPaymentCalculator: boot.setShowPaymentCalculator,
                setShowSettlementCalculator: boot.setShowSettlementCalculator,
                setShowPauseModal: boot.setShowPauseModal,
                setShowLedgerModal,
                showEditDossierMetaModal: dossierMetaWorkflow.showEditDossierMetaModal,
                setShowEditDossierMetaModal: dossierMetaWorkflow.setShowEditDossierMetaModal,
                setShowLinkedDossierTimeline: boot.setShowLinkedDossierTimeline,
                setShowTransferFileNumberChangeModal: boot.setShowTransferFileNumberChangeModal,
                setEditingNoteId,
                followupOrchestrator,
                seizureOrchestrator,
            }),
        [
            boot.modals,
            boot.setExecutionModal,
            boot.showLinkedDossierTimeline,
            boot.showTransferFileNumberChangeModal,
            followupOrchestrator.showEvictionExpenseModal,
            followupOrchestrator.showEvictionLawyerFeeModal,
            followupOrchestrator.showEvictionResidentialGraceModal,
            seizureOrchestrator.showGuarantorDetailsModal,
            followupOrchestrator.showHeirsNotificationModal,
            seizureOrchestrator.showRealEstateSeizureModal,
            followupOrchestrator.showSolidaryCoerciveTargetModal,
            followupOrchestrator.showStayOfExecutionModal,
            boot.setShowDecisionsModal,
            boot.setShowDocumentsModal,
            boot.setShowTimelineModal,
            boot.setShowCoerciveModal,
            boot.setShowNotificationModal,
            setShowUnifiedSummonsModal,
            boot.setShowPaymentModal,
            boot.setShowSeizedAssetsModal,
            boot.setShowNotesModal,
            boot.setShowAppointmentModal,
            boot.setShowPaymentCalculator,
            boot.setShowSettlementCalculator,
            boot.setShowPauseModal,
            setShowLedgerModal,
            setEditingNoteId,
            followupOrchestrator,
            seizureOrchestrator,
            dossierMetaWorkflow.setShowEditDossierMetaModal,
        ],
    );

    const chunkSetupInput = useMemo(
        () => ({
            fingerprintInput: buildExecutionDashboardCoreChunkFingerprint({
                executionId,
                activeTabId: boot.activeTabId,
                activeFinancialTab,
                activeTimelineFilter,
                executionPaused,
                dossierLifecyclePanel,
                toastEpoch,
                unifiedLedgerRevision: claimFinancialLedger.unifiedLedgerRevision,
                executionStorageTick: boot.executionStorageTick,
                financialPrincipalAmount: claimFinancialLedger.financialPrincipalAmount,
                followupOrchestrator,
                showUnifiedSeizureLogModal: followupDebtor.showUnifiedSeizureLogModal,
                timelineAccordionExpanded,
                isFinancialCenterExpanded,
                isHeaderExpanded,
                coercionOrchestrator,
                noticeVoluntaryPeriodEndOptimistic,
                voluntaryEndOptimistic,
                notificationCount,
                showExecutionFinancialHub,
                handlerClusterEpoch,
            }),
            chunkDataReady: Boolean(boot.executionData),
        }),
        [
            executionId,
            boot.activeTabId,
            activeFinancialTab,
            activeTimelineFilter,
            executionPaused,
            dossierLifecyclePanel,
            toastEpoch,
            claimFinancialLedger.unifiedLedgerRevision,
            boot.executionStorageTick,
            claimFinancialLedger.financialPrincipalAmount,
            followupOrchestrator,
            followupDebtor.showUnifiedSeizureLogModal,
            timelineAccordionExpanded,
            isFinancialCenterExpanded,
            isHeaderExpanded,
            coercionOrchestrator,
            noticeVoluntaryPeriodEndOptimistic,
            voluntaryEndOptimistic,
            notificationCount,
            showExecutionFinancialHub,
            handlerClusterEpoch,
            boot.executionData,
        ],
    );

    const {
        phoneBodyFingerprint,
        shellOverlayFingerprint,
        phoneBodyReady,
        shellOverlaysReady,
        phoneBodyScopeRef,
        shellOverlayScopeRef,
        shellOverlayScopeSnapshot,
        followupModalSnapshot,
    } = useExecutionDashboardCoreScopeAndChunk({
        specificDeliveryConvertedAmount,
        specificDeliveryFinancialized,
        scopeRuntimeInput,
        handlerCluster,
        assemblyHandlers,
        scopeLocalFlat,
        scopeRestFlat,
        modalScopeInput,
        chunkSetupInput,
    });

