// @ts-nocheck
import { useCallback, useEffect, useState, type Dispatch, type MutableRefObject, type SetStateAction } from 'react';
import { CalendarBridge } from '@/app/services/calendarBridge';
import { syncExecutionTaskDue } from '@/app/services/calendarDossierSync';
import type { ExecutionFile, TimelineEvent } from '@/app/types/execution';

type CaseNotesLog = NonNullable<ExecutionFile['caseNotesLog']>;
type CaseTasksPending = NonNullable<ExecutionFile['caseTasksPending']>;

type ShowToast = (
    message: string,
    type?: 'success' | 'error' | 'warning' | 'info',
) => void;

export interface UseExecutionTrashAndPinsParams {
    showExecutionTrashModal: boolean;
    setShowExecutionTrashModal: (open: boolean) => void;
    timelineEventsRef: MutableRefObject<TimelineEvent[]>;
    caseNotesLogRef: MutableRefObject<CaseNotesLog>;
    caseTasksPendingRef: MutableRefObject<CaseTasksPending>;
    setTimelineEvents: Dispatch<SetStateAction<TimelineEvent[]>>;
    setCaseNotesLog: Dispatch<SetStateAction<CaseNotesLog>>;
    setCaseTasksPending: Dispatch<SetStateAction<CaseTasksPending>>;
    persistExecutionMerge: (patch: Record<string, unknown>) => void;
    showToast: ShowToast;
    currentFileId: string;
    setPermanentDeleteTimelineId: Dispatch<SetStateAction<string | null>>;
}

export function useExecutionTrashAndPins({
    showExecutionTrashModal,
    setShowExecutionTrashModal,
    timelineEventsRef,
    caseNotesLogRef,
    caseTasksPendingRef,
    setTimelineEvents,
    setCaseNotesLog,
    setCaseTasksPending,
    persistExecutionMerge,
    showToast,
    currentFileId,
    setPermanentDeleteTimelineId,
}: UseExecutionTrashAndPinsParams) {
    const [timelineEditDraft, setTimelineEditDraft] = useState<TimelineEvent | null>(null);

    useEffect(() => {
        if (!showExecutionTrashModal) return;
        const onKey = (e: KeyboardEvent) => {
            if (e.key === 'Escape') setShowExecutionTrashModal(false);
        };
        document.addEventListener('keydown', onKey);
        return () => document.removeEventListener('keydown', onKey);
    }, [showExecutionTrashModal, setShowExecutionTrashModal]);

    const moveTimelineEventToTrash = useCallback(
        (ev: TimelineEvent) => {
            const cur = timelineEventsRef.current.find((e) => e.id === ev.id);
            if (!cur) {
                showToast('لا يمكن حذف حدث تابع لإضبارة أخرى من هذا العرض.', 'warning');
                return;
            }
            if (cur.trashedAt) return;
            const iso = new Date().toISOString();
            setTimelineEvents((prev) => {
                const next = prev.map((e) => (e.id === ev.id ? { ...e, trashedAt: iso } : e));
                queueMicrotask(() => persistExecutionMerge({ timelineEvents: next }));
                return next;
            });
            if (String(ev.type || '') === 'appointment') {
                CalendarBridge.remove('execution', String(currentFileId), String(ev.id));
            }
            showToast('نُقل الحدث إلى سلة مهملات الإضبارة', 'info');
        },
        [persistExecutionMerge, showToast, currentFileId, timelineEventsRef, setTimelineEvents],
    );

    const toggleTimelineEventPin = useCallback(
        (ev: TimelineEvent) => {
            if (!timelineEventsRef.current.some((e) => e.id === ev.id)) {
                showToast('لا يمكن تثبيت/إلغاء تثبيت حدث تابع لإضبارة أخرى من هذا العرض.', 'warning');
                return;
            }
            setTimelineEvents((prev) => {
                const next = prev.map((e) =>
                    e.id === ev.id ? { ...e, isPinned: !e.isPinned } : e,
                );
                queueMicrotask(() => persistExecutionMerge({ timelineEvents: next }));
                return next;
            });
        },
        [persistExecutionMerge, showToast, timelineEventsRef, setTimelineEvents],
    );

    const requestEditTimelineEvent = useCallback(
        (ev: TimelineEvent) => {
            if (!timelineEventsRef.current.some((e) => e.id === ev.id)) {
                showToast('لا يمكن تعديل حدث تابع لإضبارة أخرى من هذا العرض.', 'warning');
                return;
            }
            setTimelineEditDraft({ ...ev });
        },
        [showToast, timelineEventsRef],
    );

    const restoreTimelineEventFromTrash = useCallback(
        (id: string, trashedAt: string | undefined) => {
            const idTrim = String(id || '').trim();
            if (!idTrim) return;
            const cur = timelineEventsRef.current.find(
                (e) => e.id === idTrim && String(e.trashedAt || '') === String(trashedAt || ''),
            );
            if (!cur || !cur.trashedAt) return;
            setTimelineEvents((prev) => {
                const next = prev.map((e) =>
                    e.id === idTrim && String(e.trashedAt || '') === String(trashedAt || '')
                        ? { ...e, trashedAt: undefined }
                        : e,
                );
                queueMicrotask(() => persistExecutionMerge({ timelineEvents: next }));
                return next;
            });
            showToast('أُعيد الحدث إلى السجل الزمني', 'success');
        },
        [persistExecutionMerge, showToast, timelineEventsRef, setTimelineEvents],
    );

    const permanentlyDeleteTimelineEvent = useCallback(
        (id: string) => {
            const had = timelineEventsRef.current.some((e) => e.id === id);
            setPermanentDeleteTimelineId(null);
            if (!had) return;
            setTimelineEvents((prev) => {
                const next = prev.filter((e) => e.id !== id);
                queueMicrotask(() => persistExecutionMerge({ timelineEvents: next }));
                return next;
            });
            showToast('حُذف الحدث نهائياً من السجل', 'success');
        },
        [persistExecutionMerge, showToast, timelineEventsRef, setTimelineEvents, setPermanentDeleteTimelineId],
    );

    const moveCaseNoteToTrash = useCallback(
        (id: string) => {
            const cur = caseNotesLogRef.current.find((n) => n.id === id);
            if (!cur || cur.trashedAt) return;
            const iso = new Date().toISOString();
            setCaseNotesLog((prev) => {
                const next = prev.map((n) =>
                    n.id === id ? { ...n, trashedAt: iso, pinned: false } : n,
                );
                queueMicrotask(() => persistExecutionMerge({ caseNotesLog: next }));
                return next;
            });
            showToast('نُقلت الملاحظة إلى السلة', 'info');
        },
        [persistExecutionMerge, showToast, caseNotesLogRef, setCaseNotesLog],
    );

    const moveCaseTaskToTrash = useCallback(
        (id: string) => {
            const cur = caseTasksPendingRef.current.find((t) => t.id === id);
            if (!cur || cur.trashedAt) return;
            const iso = new Date().toISOString();
            setCaseTasksPending((prev) => {
                const next = prev.map((t) =>
                    t.id === id ? { ...t, trashedAt: iso, pinned: false } : t,
                );
                queueMicrotask(() => persistExecutionMerge({ caseTasksPending: next }));
                return next;
            });
            const trashed = caseTasksPendingRef.current.find((t) => t.id === id);
            if (trashed) {
                syncExecutionTaskDue({
                    executionId: currentFileId,
                    task: { ...trashed, trashedAt: iso, pinned: false },
                });
            }
            showToast('نُقلت المهمة إلى السلة', 'info');
        },
        [persistExecutionMerge, showToast, currentFileId, caseTasksPendingRef, setCaseTasksPending],
    );

    const toggleCaseNotePin = useCallback(
        (id: string) => {
            setCaseNotesLog((prev) => {
                const next = prev.map((n) => (n.id === id ? { ...n, pinned: !n.pinned } : n));
                queueMicrotask(() => persistExecutionMerge({ caseNotesLog: next }));
                return next;
            });
        },
        [persistExecutionMerge, setCaseNotesLog],
    );

    const toggleCaseTaskPin = useCallback(
        (id: string) => {
            setCaseTasksPending((prev) => {
                const next = prev.map((t) => (t.id === id ? { ...t, pinned: !t.pinned } : t));
                queueMicrotask(() => persistExecutionMerge({ caseTasksPending: next }));
                return next;
            });
        },
        [persistExecutionMerge, setCaseTasksPending],
    );

    const saveTimelineEditDraft = useCallback(() => {
        if (!timelineEditDraft) return;
        setTimelineEvents((prev) => {
            const next = prev.map((e) =>
                e.id === timelineEditDraft.id
                    ? {
                          ...e,
                          title: timelineEditDraft.title,
                          description: timelineEditDraft.description,
                          date: timelineEditDraft.date,
                      }
                    : e,
            );
            queueMicrotask(() => persistExecutionMerge({ timelineEvents: next }));
            return next;
        });
        setTimelineEditDraft(null);
        showToast('تم تحديث الحدث في السجل', 'success');
    }, [timelineEditDraft, persistExecutionMerge, showToast, setTimelineEvents]);

    const restoreCaseNoteFromTrash = useCallback(
        (id: string, trashedAt: string | undefined) => {
            const idTrim = String(id || '').trim();
            if (!idTrim) return;
            const cur = caseNotesLogRef.current.find(
                (n) => n.id === idTrim && String(n.trashedAt || '') === String(trashedAt || ''),
            );
            if (!cur || !cur.trashedAt) return;
            setCaseNotesLog((prev) => {
                const next = prev.map((n) =>
                    n.id === idTrim && String(n.trashedAt || '') === String(trashedAt || '')
                        ? { ...n, trashedAt: undefined }
                        : n,
                );
                queueMicrotask(() => persistExecutionMerge({ caseNotesLog: next }));
                return next;
            });
            showToast('أُعيدت الملاحظة', 'success');
        },
        [persistExecutionMerge, showToast, caseNotesLogRef, setCaseNotesLog],
    );

    const permanentlyDeleteCaseNote = useCallback(
        (id: string) => {
            const had = caseNotesLogRef.current.some((n) => n.id === id);
            if (!had) return;
            setCaseNotesLog((prev) => {
                const next = prev.filter((n) => n.id !== id);
                queueMicrotask(() => persistExecutionMerge({ caseNotesLog: next }));
                return next;
            });
            showToast('حُذفت الملاحظة نهائياً', 'success');
        },
        [persistExecutionMerge, showToast, caseNotesLogRef, setCaseNotesLog],
    );

    const restoreCaseTaskFromTrash = useCallback(
        (id: string, trashedAt: string | undefined) => {
            const idTrim = String(id || '').trim();
            if (!idTrim) return;
            const cur = caseTasksPendingRef.current.find(
                (t) => t.id === idTrim && String(t.trashedAt || '') === String(trashedAt || ''),
            );
            if (!cur || !cur.trashedAt) return;
            setCaseTasksPending((prev) => {
                const next = prev.map((t) =>
                    t.id === idTrim && String(t.trashedAt || '') === String(trashedAt || '')
                        ? { ...t, trashedAt: undefined }
                        : t,
                );
                queueMicrotask(() => persistExecutionMerge({ caseTasksPending: next }));
                return next;
            });
            showToast('أُعيدت المهمة', 'success');
        },
        [persistExecutionMerge, showToast, caseTasksPendingRef, setCaseTasksPending],
    );

    const permanentlyDeleteCaseTask = useCallback(
        (id: string) => {
            const had = caseTasksPendingRef.current.some((t) => t.id === id);
            if (!had) return;
            setCaseTasksPending((prev) => {
                const next = prev.filter((t) => t.id !== id);
                queueMicrotask(() => persistExecutionMerge({ caseTasksPending: next }));
                return next;
            });
            showToast('حُذفت المهمة نهائياً', 'success');
        },
        [persistExecutionMerge, showToast, caseTasksPendingRef, setCaseTasksPending],
    );

    return {
        timelineEditDraft,
        setTimelineEditDraft,
        moveTimelineEventToTrash,
        toggleTimelineEventPin,
        requestEditTimelineEvent,
        restoreTimelineEventFromTrash,
        permanentlyDeleteTimelineEvent,
        moveCaseNoteToTrash,
        moveCaseTaskToTrash,
        toggleCaseNotePin,
        toggleCaseTaskPin,
        saveTimelineEditDraft,
        restoreCaseNoteFromTrash,
        permanentlyDeleteCaseNote,
        restoreCaseTaskFromTrash,
        permanentlyDeleteCaseTask,
    };
}

import * as React from 'react';
import { DECISIONS_RELOAD_EVENT } from '@/app/utils/executorSeizureDecisionQueue';
import { readExecutorDecisionsUnionAcrossCandidateIds } from '@/app/utils/executionDecisionsNamespace';
import { getEffectiveClaimTypes } from '@/app/components/lawyer/ExecutionCreationView/hooks/executionFormUtils';
import {
    readExecutionDataForDomainGate,
    resolveExecutionDataForDomainGate,
} from '@/app/utils/executionDomainIsolation';
import { resolveDecisionsStorageExecutionId } from '@/app/components/lawyer/DecisionsAndAppealsEngine/engine/resolveDecisionsStorageExecutionId';

function readUnionForExecutorHook(
    executionId: string | undefined,
    executionData?: Record<string, unknown> | null,
): Record<string, unknown>[] {
    const exId = String(executionId || '').trim();
    if (!exId || exId === 'default') return [];
    const data = resolveExecutionDataForDomainGate(exId, executionData);
    const canonical = resolveDecisionsStorageExecutionId(exId, data);
    return readExecutorDecisionsUnionAcrossCandidateIds(
        canonical !== 'default' ? canonical : exId,
        data
    );
}

export function useExecutorDecisions(
    executionId: string | undefined,
    executionData?: Record<string, unknown> | null,
) {
    const exId = String(executionId || '').trim();
    const executionDataHintKey = React.useMemo(() => {
        if (!executionData || typeof executionData !== 'object') return '';
        const types = getEffectiveClaimTypes(executionData);
        const single = String(executionData.claimType || '').trim();
        return [
            String(executionData.id || '').trim(),
            String(executionData.parentDossierId || executionData.parentFileId || '').trim(),
            types.length ? types.join('|') : single,
        ].join(':');
    }, [executionData]);
    const [rows, setRows] = React.useState<Record<string, unknown>[]>(() =>
        readUnionForExecutorHook(exId, executionData)
    );

    React.useEffect(() => {
        const sync = () => setRows(readUnionForExecutorHook(exId, executionData));
        sync();
        window.addEventListener(DECISIONS_RELOAD_EVENT, sync);
        window.addEventListener('hami-execution-decision-outcome', sync as EventListener);
        window.addEventListener('focus', sync);
        return () => {
            window.removeEventListener(DECISIONS_RELOAD_EVENT, sync);
            window.removeEventListener('hami-execution-decision-outcome', sync as EventListener);
            window.removeEventListener('focus', sync);
        };
    }, [exId, executionData, executionDataHintKey]);

    return { executionId: exId, decisions: rows };
}

import { useMemo } from 'react';
import { parseLooseAmountFromText } from '@/app/utils/looseAmountParse';

export function useFinancialTotals(
    executionData: unknown,
    evictionCaseExpensesSum: number,
    isEvictionExecutionModule: boolean,
    parsedLawyerFees: number,
    principalDebtAmount: number,
    total_execution_expenses: number,
) {
    const ed = executionData as Record<string, unknown> | null | undefined;

    const judicialCustodiansResolved = useMemo(() => {
        const d = executionData as Record<string, unknown> | null | undefined;
        if (!d) return [];
        const arr = d.eviction_judicial_custodians;
        if (Array.isArray(arr) && arr.length > 0) {
            return arr.filter((c: unknown) => {
                const item = c as { fullName?: string; savedAt?: string };
                return item && String(item.fullName || '').trim() && String(item.savedAt || '').trim();
            });
        }
        const leg = d.eviction_judicial_custodian as { fullName?: string; salary?: string; decisionId?: string; savedAt?: string } | undefined;
        if (leg?.fullName?.trim() && leg.savedAt) {
            return [
                {
                    id: 'legacy_custodian',
                    fullName: leg.fullName,
                    salary: leg.salary,
                    decisionId: leg.decisionId,
                    savedAt: leg.savedAt,
                },
            ];
        }
        return [];
    }, [ed?.eviction_judicial_custodians, ed?.eviction_judicial_custodian]);

    const judicialCustodianSalariesExpenseIqd = useMemo(
        () => judicialCustodiansResolved.reduce((t: number, c: { salary?: string }) => t + parseLooseAmountFromText(c.salary), 0),
        [judicialCustodiansResolved]
    );

    const evictionCaseExpensesTotalForFinancial = useMemo(
        () => evictionCaseExpensesSum + (isEvictionExecutionModule ? judicialCustodianSalariesExpenseIqd : 0),
        [evictionCaseExpensesSum, isEvictionExecutionModule, judicialCustodianSalariesExpenseIqd]
    );

    const evictionLawyerFeesInTotals = isEvictionExecutionModule
        ? ed?.eviction_initial_notice_lawyer_fees_included === true
            ? parsedLawyerFees
            : 0
        : parsedLawyerFees;

    const totalOwed =
        principalDebtAmount +
        total_execution_expenses +
        evictionLawyerFeesInTotals +
        (isEvictionExecutionModule ? evictionCaseExpensesTotalForFinancial : 0);

    return {
        judicialCustodiansResolved,
        judicialCustodianSalariesExpenseIqd,
        evictionCaseExpensesTotalForFinancial,
        evictionLawyerFeesInTotals,
        totalOwed,
    };
}

import { useMemo } from 'react';
import type { ExecutionFile } from '@/app/types/execution';

export function useHeirsWorkflowByHeir(
    executionData: ExecutionFile | null | undefined,
    activeDebtorHeirsForNotification: string[],
    normalizeHeirWorkflowKey: (name: string) => string,
): Record<string, any> {
    return useMemo(() => {
        const raw = executionData?.heirs_notification_workflow?.byHeir || {};
        const next: Record<string, any> = {};
        activeDebtorHeirsForNotification.forEach((heirName) => {
            const key = normalizeHeirWorkflowKey(heirName);
            if (!key) return;
            const prev = (raw[key] || {}) as {
                memoDate?: string | null;
                memoStatus?: string;
                summonDate?: string | null;
                summonStatus?: string;
                lastActionAt?: string | null;
            };
            const normalizedSummonStatus =
                String(prev.summonStatus || 'none') === 'expired' ? 'none' : (prev.summonStatus ?? 'none');
            next[key] = {
                heirName,
                memoDate: prev.memoDate ?? null,
                memoStatus: prev.memoStatus ?? 'none',
                summonDate: prev.summonDate ?? null,
                summonStatus: normalizedSummonStatus,
                investigationRequestStatus: 'none',
                investigationDecisionStatus: 'none',
                investigationDecisionId: null,
                arrestWarrantStatus: 'none',
                lastActionAt: prev.lastActionAt ?? null,
            };
        });
        return next;
    }, [executionData?.heirs_notification_workflow?.byHeir, activeDebtorHeirsForNotification, normalizeHeirWorkflowKey]);
}

import { useMemo } from 'react';
import { parseTimelineDeadlineDate } from '@/app/utils/timelineSmartDisplay';
import {
    filterTimelineEventsForInabaDossier,
    filterTimelineEventsForParentDossier,
    isInabaSubFileId,
} from '@/app/stores/executionDashboardStore';

interface SubFile {
    id: string;
    fileNumber?: string;
    timelineEvents?: any[];
    [key: string]: unknown;
}

export function useMergedTimelineEvents(
    activeTimelineEvents: any[],
    subFiles: SubFile[],
    showOnlyActiveFileTimeline: boolean,
    activeSubFileId: string | null,
    parentDossierId?: string | null,
) {
    const mergedTimelineEvents = useMemo(() => {
        const events = Array.isArray(activeTimelineEvents) ? activeTimelineEvents : [];
        const files = Array.isArray(subFiles) ? subFiles : [];
        const sortKeyMs = (e: any): number => {
            const raw = e?.timestamp || e?.date || e?.createdAt;
            const d = parseTimelineDeadlineDate(raw ? String(raw) : undefined);
            return d ? d.getTime() : 0;
        };
        const parentId = String(parentDossierId || '').trim();
        const hasSubFiles = files.length > 0;

        if (showOnlyActiveFileTimeline && activeSubFileId && isInabaSubFileId(activeSubFileId)) {
            const sf = files.find((f) => f.id === activeSubFileId);
            const fromSub = filterTimelineEventsForInabaDossier(sf?.timelineEvents || [], activeSubFileId);
            const fromActive = filterTimelineEventsForInabaDossier(events, activeSubFileId);
            const byId = new Map<string, any>();
            for (const e of [...fromSub, ...fromActive]) {
                if (e?.id) byId.set(String(e.id), e);
            }
            return [...byId.values()].map((e) => ({
                ...e,
                _dossierSource: 'sub' as const,
                _dossierLabel: 'الإضبارة الفرعية',
                title: e.title,
            }));
        }

        if (!hasSubFiles) {
            const mainOnly = parentId
                ? filterTimelineEventsForParentDossier(events, parentId)
                : events;
            return mainOnly.map((e) => ({
                ...e,
                _dossierSource: 'main' as const,
                _dossierLabel: 'الإضبارة الأم',
                title: e.title,
            }));
        }

        if (showOnlyActiveFileTimeline) {
            const mainOnly = parentId
                ? filterTimelineEventsForParentDossier(events, parentId)
                : events;
            return mainOnly.map((e) => ({
                ...e,
                _dossierSource: 'main' as const,
                _dossierLabel: 'الإضبارة الأم',
                title: e.title,
            }));
        }

        const mainEvents = (parentId
            ? filterTimelineEventsForParentDossier(events, parentId)
            : events
        ).map((e) => ({
            ...e,
            _dossierSource: 'main' as const,
            _dossierLabel: 'الإضبارة الأم',
            title: `[الإضبارة الأم] ${e.title || ''}`,
        }));
        const subEvents = files.flatMap((sf) =>
            filterTimelineEventsForInabaDossier(sf.timelineEvents || [], sf.id)
                .filter((e: any) => !e.trashedAt)
                .map((e: any) => ({
                    ...e,
                    _dossierSource: 'sub' as const,
                    _dossierLabel: 'الإضبارة الفرعية',
                    title: `[الإضبارة الفرعية] ${e.title || ''}`,
                }))
        );
        return [...mainEvents, ...subEvents].sort((a, b) => sortKeyMs(b) - sortKeyMs(a));
    }, [activeTimelineEvents, subFiles, showOnlyActiveFileTimeline, activeSubFileId, parentDossierId]);

    return mergedTimelineEvents;
}

