                                    className="w-full rounded-xl bg-sky-600/75 py-2.5 text-white text-xs font-bold disabled:opacity-40 disabled:cursor-not-allowed"
                                >
                                    تسجيل مصروف
                                </button>
                            </div>
                            <ul className="space-y-2 max-h-40 overflow-y-auto text-right text-[11px] text-slate-400">
                                {store.expenses.map((r) => (
                                    <li key={r.id} className="border-b border-white/5 pb-1">
                                        <span className="text-sky-400 font-bold tabular-nums">
                                            {r.amount.toLocaleString('ar-IQ')}
                                        </span>{' '}
                                        — {r.reason}
                                    </li>
                                ))}
                            </ul>
                        </motion.div>
                    </FocModalPortal>
                )}
            </AnimatePresence>

            <AnimatePresence>
                {showGarnishModal && (
                    <FocModalPortal
                        open
                        onBackdropClick={closeGarnishModal}
                        backdropClassName="bg-black/55"
                    >
                        <motion.div
                            layout
                            initial={{ scale: 0.94, opacity: 0, y: 12 }}
                            animate={{ scale: 1, opacity: 1, y: 0 }}
                            exit={{ scale: 0.96, opacity: 0, y: 8 }}
                            transition={{ type: 'spring', stiffness: 380, damping: 28 }}
                            onClick={(e) => e.stopPropagation()}
                            className="w-full max-w-md rounded-2xl bg-[#0A1122]/80 backdrop-blur-xl p-6 border border-white/10 shadow-2xl space-y-5"
                        >
                            <div className="text-center border-b border-white/5 pb-4">
                                <h3 className="text-base font-black text-white">حجز الراتب</h3>
                                <p className="text-[11px] text-slate-500 mt-1">قاعدة الخُمس (١/٥) — مدين موظف</p>
                            </div>

                            <div className="rounded-xl border border-violet-500/20 bg-gradient-to-b from-indigo-950/50 via-violet-950/30 to-transparent px-4 py-3.5 text-right">
                                <p className="text-violet-100 text-sm font-bold">بيانات الاستقطاع والكتاب</p>
                                <p className="text-[11px] text-slate-400 mt-2 leading-relaxed">
                                    خصم شهري لا يتجاوز الخُمس؛ يُتابع لدى المنفذ وجهة العمل. أكمل الحقول ثم أكّد.
                                </p>
                            </div>

                            <motion.div
                                layout
                                initial={{ opacity: 0, height: 0 }}
                                animate={{ opacity: 1, height: 'auto' }}
                                transition={{ duration: 0.25, ease: [0.25, 0.46, 0.45, 0.94] }}
                                className="space-y-4 overflow-hidden"
                            >
                                <label className="block text-right">
                                    <span className="text-[11px] text-slate-400 mb-1.5 block">
                                        مقدار الاستقطاع الشهري (قاعدة الخُمس)
                                    </span>
                                    <input
                                        type="text"
                                        inputMode="decimal"
                                        autoFocus
                                        placeholder="المبلغ الشهري (د.ع)"
                                        value={garnishMonthlyInput}
                                        onChange={(e) =>
                                            setGarnishMonthlyInput(formatNumberInput(e.target.value))
                                        }
                                        className="w-full rounded-xl bg-white/5 border border-white/10 px-3 py-2.5 text-white text-right text-sm placeholder:text-slate-500 focus:outline-none focus:ring-2 focus:ring-violet-500/35"
                                    />
                                </label>
                                <label className="block text-right">
                                    <span className="text-[11px] text-slate-400 mb-1.5 block">رقم الكتاب</span>
                                    <input
                                        type="text"
                                        placeholder="رقم الكتاب / المرجع"
                                        value={garnishMemoInput}
                                        onChange={(e) => setGarnishMemoInput(e.target.value)}
                                        className="w-full rounded-xl bg-white/5 border border-white/10 px-3 py-2.5 text-white text-right text-sm placeholder:text-slate-500 focus:outline-none focus:ring-2 focus:ring-violet-500/35"
                                    />
                                </label>
                            </motion.div>

                            <p className="text-slate-400 text-xs text-right border-t border-white/5 pt-3">
                                المتبقي على الوعاء:{' '}
                                <span className="text-[#E6C673] font-black tabular-nums">
                                    {remainingUnified.toLocaleString('ar-IQ')} د.ع
                                </span>
                            </p>

                            <div className="flex flex-col-reverse sm:flex-row gap-2 sm:justify-end pt-1">
                                <button
                                    type="button"
                                    onClick={closeGarnishModal}
                                    className="px-4 py-2.5 rounded-xl bg-white/5 border border-white/10 text-slate-300 text-sm font-semibold hover:bg-white/10 transition"
                                >
                                    إلغاء
                                </button>
                                <button
                                    type="button"
                                    onClick={confirmGarnishment}
                                    disabled={!canConfirmGarnishment}
                                    className="px-4 py-2.5 rounded-xl bg-gradient-to-l from-indigo-600 via-violet-600 to-purple-800 text-white text-sm font-bold shadow-lg shadow-violet-950/40 hover:brightness-110 transition disabled:opacity-40 disabled:cursor-not-allowed"
                                >
                                    تأكيد حجز الراتب
                                </button>
                            </div>
                        </motion.div>
                    </FocModalPortal>
                )}
            </AnimatePresence>

            {showGuarantorModal && (
                <GuarantorRegistrationModal
                    isOpen={showGuarantorModal}
                    onClose={() => setShowGuarantorModal(false)}
                    onSave={handleSaveGuarantor}
                />
            )}

            <AnimatePresence>{renderAlimonyDetailModal()}</AnimatePresence>
        </div>
    );
});

// @ts-nocheck
import React from 'react';
import { AnimatePresence, motion } from 'motion/react';
import { BadgeCheck, ChevronDown, Handshake, Wallet } from 'lucide-react';
import { formatIqdDisplay, formatNumberInput } from '../utils';
import type { SettlementDuePhase } from '../utils';
import type { PendingSettlement, UnifiedLedgerStore } from '../types';

export interface DebtorAgentSeizedItem {
    id: string;
    kind: 'property' | 'salary' | 'movable' | 'third_party' | 'mark';
    title: string;
    subtitle?: string;
    statusLabel?: string;
}

export interface DebtorAgentFinancialHubPanelProps {
    remainingUnified: number;
    totalOwedUnified: number;
    repaymentInput: string;
    setRepaymentInput: (v: string) => void;
    applyDebtRepayment: () => boolean;
    canApplyRepayment: boolean;
    store: UnifiedLedgerStore;
    settlementInput: string;
    setSettlementInput: (v: string) => void;
    settlementDueDateInput: string;
    setSettlementDueDateInput: (v: string) => void;
    registerSettlementPlan: () => Promise<boolean>;
    revertSettlementPlan: () => void;
    markPendingSettlementPaid: () => void;
    showSettlementDueActions: boolean;
    pendingSettlementDuePhase: SettlementDuePhase | null;
    seizedItems: DebtorAgentSeizedItem[];
    completed: boolean;
}

function CollapsibleActionStrip({
    tone,
    icon: Icon,
    title,
    expanded,
    onToggle,
    disabled = false,
    badge,
    children,
}: {
    tone: 'emerald' | 'violet';
    icon: React.ComponentType<{ size?: number; className?: string }>;
    title: string;
    expanded: boolean;
    onToggle: () => void;
    disabled?: boolean;
    badge?: string;
    children: React.ReactNode;
}) {
    const toneClasses =
        tone === 'emerald'
            ? {
                  shell: 'border-emerald-500/15 bg-emerald-500/[0.04]',
                  hover: 'hover:bg-emerald-500/[0.05]',
                  icon: 'border-emerald-400/20 bg-emerald-500/10 text-emerald-300',
                  title: 'text-emerald-100',
                  divider: 'border-emerald-500/10',
              }
            : {
                  shell: 'border-violet-500/15 bg-violet-500/[0.04]',
                  hover: 'hover:bg-violet-500/[0.05]',
                  icon: 'border-violet-400/20 bg-violet-500/10 text-violet-300',
                  title: 'text-violet-100',
                  divider: 'border-violet-500/10',
              };

    return (
        <div className={`overflow-hidden rounded-xl border ${toneClasses.shell}`}>
            <button
                type="button"
                disabled={disabled}
                onClick={onToggle}
                aria-expanded={expanded}
                className={`flex w-full flex-row-reverse items-center justify-between gap-2 px-3 py-2.5 text-right transition-colors disabled:cursor-not-allowed disabled:opacity-40 ${toneClasses.hover}`}
            >
                <span className="flex min-w-0 flex-row-reverse items-center gap-2">
                    <span
                        className={`flex h-8 w-8 shrink-0 items-center justify-center rounded-lg border ${toneClasses.icon}`}
                    >
                        <Icon size={15} />
                    </span>
                    <span className={`text-[11px] font-bold ${toneClasses.title}`}>{title}</span>
                </span>
                <span className="flex shrink-0 flex-row-reverse items-center gap-1.5">
                    {badge ? (
                        <span className="rounded-md border border-white/10 bg-white/[0.05] px-1.5 py-0.5 text-[8px] font-bold text-slate-300">
                            {badge}
                        </span>
                    ) : null}
                    <motion.span
                        animate={{ rotate: expanded ? 180 : 0 }}
                        transition={{ duration: 0.2 }}
                        className="flex h-6 w-6 items-center justify-center rounded-md border border-white/10 text-slate-400"
                    >
                        <ChevronDown size={13} />
                    </motion.span>
                </span>
            </button>

            <AnimatePresence initial={false}>
                {expanded ? (
                    <motion.div
                        initial={{ height: 0, opacity: 0 }}
                        animate={{ height: 'auto', opacity: 1 }}
                        exit={{ height: 0, opacity: 0 }}
                        transition={{ duration: 0.2, ease: 'easeOut' }}
                        className="overflow-hidden"
                    >
                        <div className={`space-y-2 border-t px-3 pb-3 pt-2 ${toneClasses.divider}`}>
                            {children}
                        </div>
                    </motion.div>
                ) : null}
            </AnimatePresence>
        </div>
    );
}

function formatPaymentYmd(at: string): string {
    const raw = String(at || '').trim();
    if (raw.length >= 10) return raw.slice(0, 10);
    return '—';
}

function duePhaseLabel(phase: SettlementDuePhase | null): string | null {
    if (phase === 'waiting') return 'بانتظار موعد السداد';
    if (phase === 'due') return 'حان موعد السداد';
    if (phase === 'overdue') return 'تجاوز موعد السداد';
    return null;
}

export const DebtorAgentFinancialHubPanel: React.FC<DebtorAgentFinancialHubPanelProps> = ({
    remainingUnified,
    totalOwedUnified,
    repaymentInput,
    setRepaymentInput,
    applyDebtRepayment,
    canApplyRepayment,
    store,
    settlementInput,
    setSettlementInput,
    settlementDueDateInput,
    setSettlementDueDateInput,
    registerSettlementPlan,
    revertSettlementPlan,
    markPendingSettlementPaid,
    showSettlementDueActions,
    pendingSettlementDuePhase,
    seizedItems,
    completed,
}) => {
    const pending = store.pendingSettlement as PendingSettlement | null | undefined;
    const [repaymentExpanded, setRepaymentExpanded] = React.useState(false);
    const [settlementExpanded, setSettlementExpanded] = React.useState(false);

    const showRepayment = !completed && remainingUnified > 0;
    const recentPayments = React.useMemo(
        () =>
            store.payments
                .filter((p) => p.entryType !== 'disburse')
                .slice(0, 4),
        [store.payments]
    );

    React.useEffect(() => {
        if (!showRepayment) setRepaymentExpanded(false);
    }, [showRepayment]);

    React.useEffect(() => {
        if (pending) setSettlementExpanded(true);
    }, [pending?.id]);

    const phaseLabel = duePhaseLabel(pendingSettlementDuePhase);

    return (
        <div className="space-y-2 pb-1" dir="rtl">
            <div className="rounded-xl border border-white/10 bg-white/[0.03] px-3 py-2.5 text-right">
                <div className="flex flex-row-reverse gap-3">
                    <div className="min-w-0 flex-1">
                        <p className="text-[9px] font-medium text-slate-500">المبلغ المتبقي على موكلك</p>
                        <p className="mt-0.5 text-xl font-black tabular-nums text-[#E6C673]">
                            {formatIqdDisplay(remainingUnified)}{' '}
                            <span className="text-[10px] font-semibold text-slate-400">د.ع</span>
                        </p>
                        {totalOwedUnified > remainingUnified ? (
                            <p className="mt-0.5 text-[9px] text-slate-500">
                                إجمالي الوعاء {formatIqdDisplay(totalOwedUnified)} د.ع
                            </p>
                        ) : null}
                    </div>
                    <div className="min-w-0 flex-1 border-r border-white/8 pr-3">
                        <p className="text-[9px] font-medium text-slate-500">سجل الدفعات</p>
                        {pending ? (
                            <p className="mt-1 text-[9px] leading-snug text-violet-200/90">
                                تسوية {formatIqdDisplay(pending.amount)} د.ع
                                <span className="text-slate-500"> — استحقاق </span>
                                <span className="tabular-nums text-slate-300">{pending.dueDate}</span>
                            </p>
                        ) : null}
                        {recentPayments.length > 0 ? (
                            <ul className="mt-1 space-y-0.5">
                                {recentPayments.map((p) => (
                                    <li
                                        key={p.id}
                                        className="flex flex-row-reverse items-center justify-between gap-2 text-[9px]"
                                    >
                                        <span className="tabular-nums font-semibold text-emerald-100/90">
                                            {formatIqdDisplay(p.amount)} د.ع
                                        </span>
                                        <span className="truncate text-slate-500">
                                            {formatPaymentYmd(p.at)}
                                            {p.entryType === 'settlement' ? ' · تسوية' : ''}
                                        </span>
                                    </li>
                                ))}
                            </ul>
                        ) : !pending ? (
                            <p className="mt-1 text-[9px] text-slate-600">لا دفعات مسجّلة بعد</p>
                        ) : null}
                    </div>
                </div>
            </div>

            {showRepayment ? (
                <CollapsibleActionStrip
                    tone="emerald"
                    icon={Wallet}
                    title="تسديد"
                    expanded={repaymentExpanded}
                    onToggle={() => setRepaymentExpanded((v) => !v)}
                >
                    <div className="flex flex-col gap-2 sm:flex-row-reverse">
                        <input
                            type="text"
                            inputMode="decimal"
                            value={repaymentInput}
                            onChange={(e) => setRepaymentInput(formatNumberInput(e.target.value))}
                            placeholder="مبلغ التسديد"
                            className="min-w-0 flex-1 rounded-lg border border-white/10 bg-black/30 px-3 py-1.5 text-sm text-white outline-none focus:border-emerald-400/40"
                        />
                        <button
                            type="button"
                            disabled={!canApplyRepayment}
                            onClick={() => {
                                if (applyDebtRepayment()) setRepaymentExpanded(false);
                            }}
                            className="shrink-0 rounded-lg border border-emerald-500/35 bg-emerald-600/20 px-3 py-1.5 text-[10px] font-bold text-emerald-50 disabled:opacity-40"
                        >
                            تسجيل دفعة
                        </button>
                    </div>
                </CollapsibleActionStrip>
            ) : null}

            <CollapsibleActionStrip
                tone="violet"
                icon={Handshake}
                title="التسوية"
                expanded={settlementExpanded}
                onToggle={() => setSettlementExpanded((v) => !v)}
                badge={pending ? 'مقفلة' : undefined}
                disabled={false}
            >
                {pending ? (
                    <div className="space-y-2 rounded-lg border border-violet-500/20 bg-black/20 p-2.5">
                        <div className="flex flex-row-reverse items-start justify-between gap-2">
                            <div className="min-w-0 text-right">
                                <p className="text-[9px] text-slate-400">تسوية مسجّلة ومقفلة</p>
                                <p className="text-[13px] font-black tabular-nums text-violet-100">
                                    {formatIqdDisplay(pending.amount)} د.ع
                                </p>
                                <p className="mt-0.5 text-[9px] text-slate-400">
                                    موعد السداد{' '}
                                    <span className="font-semibold tabular-nums text-slate-200">
                                        {pending.dueDate}
                                    </span>
                                </p>
                                {phaseLabel ? (
                                    <p
                                        className={`mt-0.5 text-[9px] font-bold ${
                                            pendingSettlementDuePhase === 'waiting'
                                                ? 'text-slate-500'
                                                : pendingSettlementDuePhase === 'due'
                                                  ? 'text-amber-300'
                                                  : 'text-rose-300'
                                        }`}
                                    >
                                        {phaseLabel}
                                    </p>
                                ) : null}
                            </div>
                        </div>

                        {showSettlementDueActions ? (
                            <button
                                type="button"
                                onClick={markPendingSettlementPaid}
                                className="flex w-full flex-row-reverse items-center justify-center gap-1.5 rounded-lg border border-emerald-500/30 bg-emerald-500/10 py-2 text-[10px] font-bold text-emerald-100 hover:bg-emerald-500/16"
                            >
                                <BadgeCheck size={13} />
                                تم دفع المبلغ
                            </button>
                        ) : null}

                        <button
                            type="button"
                            onClick={(e) => {
                                e.stopPropagation();
                                revertSettlementPlan();
                                setSettlementExpanded(false);
                                setSettlementInput('');
                                setSettlementDueDateInput('');
                            }}
                            className="w-full text-center text-[8px] font-medium text-slate-500 underline decoration-slate-600/60 underline-offset-2 hover:text-slate-300"
                        >
                            إلغاء التسوية
                        </button>
                    </div>
                ) : (
                    <div className="space-y-2">
                        <input
                            type="text"
                            inputMode="decimal"
                            value={settlementInput}
                            onChange={(e) => setSettlementInput(formatNumberInput(e.target.value))}
                            placeholder="مبلغ التسوية"
                            className="w-full rounded-lg border border-white/10 bg-black/30 px-3 py-1.5 text-sm text-white outline-none focus:border-violet-400/35"
                        />
                        <input
                            type="date"
                            value={settlementDueDateInput}
                            onChange={(e) => setSettlementDueDateInput(e.target.value)}
                            className="w-full rounded-lg border border-white/10 bg-black/30 px-3 py-1.5 text-sm text-white outline-none focus:border-violet-400/35"
                        />
                        <button
                            type="button"
                            onClick={async () => {
                                const ok = await registerSettlementPlan();
                                if (ok) setSettlementExpanded(true);
                            }}
                            className="w-full rounded-lg border border-violet-500/30 bg-violet-600/15 py-2 text-[10px] font-bold text-violet-50"
                        >
                            تسجيل تسوية
                        </button>
                    </div>
                )}
            </CollapsibleActionStrip>

            {seizedItems.length > 0 ? (
                <div className="space-y-1.5 rounded-xl border border-amber-500/15 bg-amber-950/10 p-2.5">
                    <p className="text-[10px] font-bold text-amber-100">ما تم حجزه (قرار الدائن)</p>
                    <ul className="space-y-1">
                        {seizedItems.map((item) => (
                            <li
                                key={item.id}
                                className="rounded-lg border border-white/8 bg-black/25 px-2 py-1.5 text-right"
                            >
                                <p className="text-[10px] font-semibold text-slate-100">{item.title}</p>
                                {item.subtitle ? (
                                    <p className="text-[9px] text-slate-400">{item.subtitle}</p>
                                ) : null}
                                {item.statusLabel ? (
                                    <p className="mt-0.5 text-[8px] font-bold text-amber-200/90">
                                        {item.statusLabel}
                                    </p>
                                ) : null}
                            </li>
                        ))}
                    </ul>
                </div>
            ) : null}
        </div>
    );
};

import React, { useEffect, useMemo, useState } from 'react';
import { CheckCircle, Send, X, Handshake, Trophy, PencilLine } from 'lucide-react';
import { formatIqdDisplay } from '../utils';
import { SECTION_GLASS } from '../constants';
import type { UnifiedLedgerStore, FinancialLedgerEntry } from '../types';
import { ReactiveSettlementEntry } from './ReactiveSettlementEntry';
import { SettlementBuriedKebab } from './SettlementBuriedKebab';
import LedgerExpenseEditCluster from './LedgerExpenseEditCluster';
import { SettlementRepaymentStrip } from './SettlementRepaymentStrip';
import type { SettlementUxTier } from '../settlementUxMatrix';
import { DECISIONS_RELOAD_EVENT, readExecutorDecisionsArray } from '@/app/utils/executorSeizureDecisionQueue';
import { ExecutionInlineExecutorDecisionActions } from '@/app/components/shared/ExecutionInlineExecutorDecisionActions';

interface StandardFinancialLedgerProps {
    executionId: string | undefined;
    totalOwedUnified: number;
    remainingUnified: number;
    baseDossierAmount: number;
    store: UnifiedLedgerStore;
    setExpenseSheetOpen: (v: boolean) => void;
    setFeesSheetOpen: (v: boolean) => void;
    canShowDisburse: boolean;
    onOpenDisburse: () => void;
    retractCollectionRequest: () => void;
    unifiedCollectionExecutorApproved: boolean;
    showEmployeeCollection: boolean;
    showNonEmployeePhase2: boolean;
    applyFullPayment: () => void;
    setShowGarnishModal: (v: boolean) => void;
    undoLastPayment: () => void;
    financialLedger: FinancialLedgerEntry[];
    onPayment: () => void;
    canEditDebtTotals?: boolean;
    onOpenDebtEdit?: () => void;
    flatChrome?: boolean;
    settlementUxTier?: SettlementUxTier;
    settlementPanelOpen?: boolean;
    onActivateSettlement?: () => void;
    onDeactivateSettlement?: () => void;
    repaymentInput?: string;
    setRepaymentInput?: (v: string) => void;
    canApplyRepayment?: boolean;
    applyDebtRepayment?: () => boolean;
    repaymentExceedsRemaining?: boolean;
    /** إجمالي النفقة الشهرية المستمرة (زوجة + أولاد) — يُعرض تحت متبقي الوعاء */
    ongoingMonthlyAlimony?: number;
    /** إظهار حاوية النفقة المستمرة — تُخفى حصراً عند وفاة المدين */
    showOngoingAlimonyMonthly?: boolean;
    /** تفاصيل المستحقين الأحياء (زوجة / أولاد) */
    ongoingAlimonyDetailLines?: string[];
    /** إظهار مداخل التسوية — يُخفى عند نشاط مسار حجز الراتب */
    showSettlementEntry?: boolean;
}

export const StandardFinancialLedger = ({
    executionId,
    totalOwedUnified,
    remainingUnified,
    store,
    setExpenseSheetOpen,
    setFeesSheetOpen,
    canShowDisburse,
    onOpenDisburse,
    retractCollectionRequest,
    unifiedCollectionExecutorApproved,
    showEmployeeCollection,
    showNonEmployeePhase2,
    applyFullPayment,
    setShowGarnishModal,
    undoLastPayment,
    financialLedger,
    onPayment,
    canEditDebtTotals = false,
    onOpenDebtEdit,
    flatChrome = false,
    settlementUxTier = 'hidden',
    settlementPanelOpen = false,
    onActivateSettlement,
    onDeactivateSettlement,
    repaymentInput = '',
    setRepaymentInput,
    canApplyRepayment = false,
    applyDebtRepayment,
    repaymentExceedsRemaining = false,
    ongoingMonthlyAlimony,
    showOngoingAlimonyMonthly,
    ongoingAlimonyDetailLines = [],
    showSettlementEntry = true,
}: StandardFinancialLedgerProps) => {
    const ongoingAlimonyVisible =
        showOngoingAlimonyMonthly ??
        (ongoingMonthlyAlimony != null && ongoingMonthlyAlimony > 0);
    const [fullPayOpen, setFullPayOpen] = useState(false);
    const [fullPayCountdown, setFullPayCountdown] = useState(0);

    useEffect(() => {
        if (!fullPayOpen || fullPayCountdown <= 0) return;
        const timer = window.setTimeout(() => setFullPayCountdown((c) => c - 1), 1000);
        return () => window.clearTimeout(timer);
    }, [fullPayOpen, fullPayCountdown]);

    const openFullPaymentConfirm = () => {
        setFullPayOpen(true);
        setFullPayCountdown(3);
    };

    const cancelFullPaymentConfirm = () => {
        setFullPayOpen(false);
        setFullPayCountdown(0);
    };

    const confirmFullPayment = () => {
        applyFullPayment();
        cancelFullPaymentConfirm();
    };
    const [decisions, setDecisions] = React.useState<Record<string, unknown>[]>(() =>
        readExecutorDecisionsArray(executionId)
    );
    React.useEffect(() => {
        const sync = () => setDecisions(readExecutorDecisionsArray(executionId));
        sync();
        window.addEventListener(DECISIONS_RELOAD_EVENT, sync);
        window.addEventListener('hami-execution-decision-outcome', sync as EventListener);
        window.addEventListener('focus', sync);
        return () => {
            window.removeEventListener(DECISIONS_RELOAD_EVENT, sync);
            window.removeEventListener('hami-execution-decision-outcome', sync as EventListener);
            window.removeEventListener('focus', sync);
        };
    }, [executionId]);
    const settlementInProgress =
        settlementPanelOpen || Boolean(store.pendingSettlement);
    const highlightedUnifiedAmount = remainingUnified;
    const pendingUnifiedCollectionDecision = useMemo(() => {
        const list = Array.isArray(decisions) ? decisions : [];
        const pending = list
            .filter((d: any) => String(d?.requestKind || '') === 'unified_collection')
            .filter((d: any) => String(d?.executorOutcome ?? 'pending') === 'pending' || String(d?.executorOutcome ?? '') === '')
            .sort((a: any, b: any) => {
                const da = String(a?.resolvedAt ?? a?.date ?? '');
                const db = String(b?.resolvedAt ?? b?.date ?? '');
                return db.localeCompare(da, undefined, { numeric: true });
            });
        return pending[0] || null;
    }, [decisions]);

    const latestUnifiedCollectionDecision = useMemo(() => {
        const list = Array.isArray(decisions) ? decisions : [];
        const all = list
            .filter((d: any) => String(d?.requestKind || '') === 'unified_collection')
            .sort((a: any, b: any) => {
                const da = String(a?.resolvedAt ?? a?.date ?? '');
                const db = String(b?.resolvedAt ?? b?.date ?? '');
                return db.localeCompare(da, undefined, { numeric: true });
            });
        return all[0] || null;
    }, [decisions]);

    const latestUnifiedOutcome = String((latestUnifiedCollectionDecision as any)?.executorOutcome ?? '');
    const unifiedRejected = latestUnifiedOutcome === 'rejected';

    const openAppealCenter = () => {
        if (!executionId) return;
        try {
            window.dispatchEvent(
                new CustomEvent('hami-open-decisions-modal', {
                    detail: {
                        executionId,
                        tab: 'previous',
                        decisionId: String((latestUnifiedCollectionDecision as any)?.id || '').trim() || undefined,
                    },
                })
            );
        } catch {
            /* ignore */
        }
    };

    return (
        <div
            className={
                flatChrome
                    ? 'flex flex-col gap-y-4'
                    : `${SECTION_GLASS} flex flex-col gap-y-4`
            }
        >
            <div
                className={
                    flatChrome
                        ? 'flex flex-col items-center text-center pb-2 gap-y-1.5'
                        : 'flex flex-col items-center text-center pb-4 mb-1 border-b border-white/10 gap-y-2'
                }
            >
                <p className="text-[10px] text-slate-500 tracking-wide">متبقي الوعاء</p>
                <div className="flex flex-wrap items-center justify-center gap-2">
                    <p
                        className="text-2xl sm:text-3xl font-black tabular-nums leading-none tracking-tight bg-gradient-to-b from-[#FFF8DC] via-[#E6C673] to-amber-700 bg-clip-text text-transparent"
                        style={{ filter: 'drop-shadow(0 0 14px rgba(230, 198, 115, 0.32))' }}
                    >
                        {formatIqdDisplay(highlightedUnifiedAmount)}
                    </p>
                    {showSettlementEntry &&
                    settlementUxTier === 'buried' &&
                    !settlementInProgress &&
                    onActivateSettlement ? (
                        <SettlementBuriedKebab onActivate={onActivateSettlement} />
                    ) : null}
                    {canEditDebtTotals && onOpenDebtEdit && !flatChrome ? (
                        <button
                            type="button"
                            onClick={onOpenDebtEdit}
                            className="inline-flex items-center justify-center gap-1 min-w-[3.6rem] py-1.5 px-2 rounded-md border border-[#E6C673]/30 bg-[#E6C673]/10 text-[#F5E6A8] hover:bg-[#E6C673]/15 transition"
                        >
                            <PencilLine size={13} strokeWidth={1.85} className="shrink-0" />
                            <span className="text-[10px] font-semibold leading-tight text-center">تعديل</span>
                        </button>
                    ) : null}
                    <LedgerExpenseEditCluster
                        onExpenses={() => setExpenseSheetOpen(true)}
                        onEditFees={() => setFeesSheetOpen(true)}
                        hideFees
                    />
                </div>
                {showSettlementEntry &&
                settlementUxTier === 'primary' &&
                onActivateSettlement &&
                !ongoingAlimonyVisible ? (
                    <div className="w-full pt-2">
                        <ReactiveSettlementEntry
                            tier="primary"
                            isActive={settlementInProgress}
                            onActivate={onActivateSettlement}
                            onDeactivate={onDeactivateSettlement}
                        />
                    </div>
                ) : null}
                {ongoingAlimonyVisible && ongoingMonthlyAlimony != null && ongoingMonthlyAlimony > 0 ? (
                    <div className="mt-3 w-full border-t border-white/[0.06] pt-3">
                        <p className="text-[10px] text-emerald-400/85 tracking-wide">
                            النفقة المستمرة المطلوبة
                        </p>
                        <p className="mt-1 text-lg sm:text-xl font-black tabular-nums text-emerald-300/95 leading-none">
                            {formatIqdDisplay(ongoingMonthlyAlimony)}
                            <span className="text-[11px] font-semibold text-slate-500 mr-1">/ شهرياً</span>
                        </p>
                        {ongoingAlimonyDetailLines.length > 0 ? (
                            <div className="mt-2 space-y-0.5">
                                {ongoingAlimonyDetailLines.map((line) => (
                                    <p
                                        key={line}
                                        className="text-[10px] text-slate-400 leading-relaxed"
                                    >
                                        {line}
                                    </p>
                                ))}
                            </div>
                        ) : null}
                        {showSettlementEntry && settlementUxTier === 'primary' && onActivateSettlement ? (
                            <div className="mt-3">
                                <ReactiveSettlementEntry
                                    tier="primary"
                                    shortLabel
                                    isActive={settlementInProgress}
                                    onActivate={onActivateSettlement}
                                    onDeactivate={onDeactivateSettlement}
                                />
                            </div>
                        ) : null}
                    </div>
                ) : null}
            </div>

            <div className="space-y-3">
                {remainingUnified > 0 &&
                !store.completed &&
                setRepaymentInput &&
                applyDebtRepayment ? (
                    <SettlementRepaymentStrip
                        repaymentInput={repaymentInput}
                        setRepaymentInput={setRepaymentInput}
                        canApplyRepayment={canApplyRepayment}
                        onApply={applyDebtRepayment}
                        remainingUnified={remainingUnified}
                        repaymentExceedsRemaining={repaymentExceedsRemaining}
                    />
                ) : null}

                {(store.completed || remainingUnified <= 0) && totalOwedUnified > 0 && (
                    <div className="flex items-center justify-center gap-2 text-emerald-300 text-xs font-bold">
                        <CheckCircle size={16} />
                        منجز — الوعاء مغلق
                    </div>
                )}

                {store.garnishment && !store.completed && (
                    <p className="text-center text-xs text-indigo-200/90 leading-relaxed">
                        مسار حجز الراتب (١/٥) مفعّل — تابع من «التنفيذ والمحجوزات» ومفاتحة جهة العمل.
                    </p>
                )}

                {store.collectionRequestActive && !store.completed && !unifiedCollectionExecutorApproved ? (
                    <div className="w-full rounded-lg backdrop-blur-sm py-3 px-3.5 flex flex-col items-center justify-center gap-2 text-xs font-bold border border-slate-500/30 bg-slate-800/40 text-slate-300">
                        <div className="flex items-center justify-center gap-2">
                            <CheckCircle size={17} className="shrink-0" />
                            {unifiedRejected
                                ? 'تم رفض طلب الاستحصال من قبل المنفذ'
                                : 'طلب الاستحصال قيد البت — اتخذ قرار المنفذ هنا'}
                        </div>
                        {unifiedRejected ? (
                            <ExecutionInlineExecutorDecisionActions
                                executionId={executionId}
                                decisionId={String((latestUnifiedCollectionDecision as any)?.id || '').trim()}
                                requestKind="unified_collection"
                                disabled
                                onOpenAppealCenter={openAppealCenter}
                            />
                        ) : pendingUnifiedCollectionDecision ? (
                            <ExecutionInlineExecutorDecisionActions
                                executionId={executionId}
                                decisionId={String((pendingUnifiedCollectionDecision as any)?.id || '').trim()}
                                requestKind="unified_collection"
                            />
                        ) : null}
                    </div>
                ) : canShowDisburse ? (
                    <button
                        type="button"
                        onClick={onOpenDisburse}
                        className="w-full rounded-lg bg-gradient-to-l from-[#E6C673] to-amber-600 py-3.5 px-4 text-[#0A0F1C] font-black text-xs shadow-md shadow-amber-900/25 disabled:opacity-35 disabled:cursor-not-allowed flex items-center justify-center gap-2"
                    >
                        <Send size={17} className="shrink-0" />
                        الصرف
                    </button>
                ) : null}

                {store.collectionRequestActive && unifiedCollectionExecutorApproved && (
                    <div className="flex flex-col gap-2">
                        <div className="flex items-center gap-2">
                            <button
                                type="button"
                                onClick={onPayment}
                                className="flex-1 rounded-lg bg-gradient-to-l from-emerald-500 to-emerald-700 py-3.5 px-4 text-white font-extrabold text-xs shadow-md shadow-emerald-950/30 disabled:opacity-30 disabled:cursor-not-allowed flex items-center justify-center gap-2"
                            >
                                <Handshake size={17} className="shrink-0" />
                                تحصيل دفعة
                            </button>
                            <button
                                type="button"
                                onClick={retractCollectionRequest}
                                className="flex-1 rounded-lg bg-gradient-to-l from-rose-500/80 to-rose-800/80 py-3.5 px-4 text-rose-100 font-extrabold text-xs shadow-md shadow-rose-950/20 disabled:opacity-30 disabled:cursor-not-allowed flex items-center justify-center gap-2"
                            >
                                <X size={17} className="shrink-0" />
                                إلغاء الطلب
                            </button>
                        </div>
                        {showSettlementEntry && settlementUxTier === 'secondary' && onActivateSettlement ? (
                            <ReactiveSettlementEntry
                                tier="secondary"
                                isActive={settlementInProgress}
                                onActivate={onActivateSettlement}
                                onDeactivate={onDeactivateSettlement}
                            />
                        ) : null}
                    </div>
                )}

                {showSettlementEntry &&
                settlementUxTier === 'secondary' &&
                onActivateSettlement &&
                !(store.collectionRequestActive && unifiedCollectionExecutorApproved) &&
                !store.completed &&
                remainingUnified > 0 ? (
                    <ReactiveSettlementEntry
                        tier="secondary"
                        isActive={settlementInProgress}
                        onActivate={onActivateSettlement}
                        onDeactivate={onDeactivateSettlement}
                    />
                ) : null}

                {unifiedCollectionExecutorApproved && (
                    <div className="flex flex-col gap-2">
                        <div className="flex items-center gap-2">
                            {showEmployeeCollection && (
                                <button
                                    type="button"
                                    onClick={() => setShowGarnishModal(true)}
                                    className="w-full rounded-lg border border-violet-500/30 bg-violet-950/50 backdrop-blur-sm py-3.5 px-4 text-violet-100/95 text-[11px] font-bold shadow-sm shadow-black/25 disabled:opacity-30 disabled:cursor-not-allowed transition-colors hover:bg-violet-900/42 hover:border-violet-400/32"
                                >
                                    حجز الراتب (1/5)
                                </button>
                            )}
                            {showNonEmployeePhase2 && !fullPayOpen && (
                                <button
                                    type="button"
                                    onClick={openFullPaymentConfirm}
                                    disabled={remainingUnified <= 0 || store.completed}
                                    className="flex-1 rounded-lg border border-emerald-500/30 bg-emerald-950/55 backdrop-blur-sm py-3.5 px-4 text-emerald-50/95 text-[11px] font-bold shadow-sm shadow-black/25 disabled:opacity-30 disabled:cursor-not-allowed transition-colors hover:bg-emerald-900/45 hover:border-emerald-400/35"
                                >
                                    تحصيل كامل الوعاء
                                </button>
                            )}
                        </div>
                        {showNonEmployeePhase2 && fullPayOpen && (
                            <div className="rounded-xl border border-emerald-500/35 bg-emerald-950/35 p-3 space-y-3 text-right">
                                <p className="text-[11px] font-bold text-emerald-100 leading-relaxed">
                                    تأكيد تحصيل كامل الوعاء بمبلغ{' '}
                                    <span className="tabular-nums text-emerald-300">
                                        {formatIqdDisplay(remainingUnified)} د.ع
                                    </span>
                                    — سيُغلق الوعاء نهائياً.
                                </p>
                                {fullPayCountdown > 0 ? (
                                    <div className="flex flex-col items-center gap-2 py-2 rounded-lg border border-emerald-500/25 bg-emerald-500/10">
                                        <Trophy size={28} className="text-emerald-300 animate-pulse" />
                                        <p className="text-xs font-black text-emerald-200">
                                            انتصار — اكتمال الوعاء
                                        </p>
                                        <p className="text-[10px] text-emerald-300/90">
                                            زر الموافقة يتاح بعد {fullPayCountdown} ثانية
                                        </p>
                                    </div>
                                ) : (
                                    <button
                                        type="button"
                                        onClick={confirmFullPayment}
                                        className="w-full rounded-lg bg-gradient-to-l from-emerald-500 to-emerald-700 py-3 px-4 text-white text-xs font-black shadow-md shadow-emerald-950/30"
                                    >
                                        موافقة — تنفيذ التحصيل الكامل
                                    </button>
                                )}
                                <button
                                    type="button"
                                    onClick={cancelFullPaymentConfirm}
                                    className="w-full text-center text-[11px] text-slate-400 hover:text-slate-200 py-1"
                                >
                                    إلغاء
                                </button>
                            </div>
                        )}
                    </div>
                )}

                {store.completed && (
                    <button
                        type="button"
                        onClick={undoLastPayment}
                        className="w-full text-center text-[11px] font-medium text-[#A0AEC0] hover:text-[#CBD5E0] transition-colors duration-200 py-2.5 underline-offset-4 hover:underline"
                    >
                        تراجع عن آخر دفعة
                    </button>
                )}

                {(store.collectionRequestActive || store.completed) && !unifiedCollectionExecutorApproved && (
                    <button
                        type="button"
                        onClick={retractCollectionRequest}
                        className="w-full text-center text-[11px] font-medium text-[#A0AEC0] hover:text-[#CBD5E0] transition-colors duration-200 py-2.5 underline-offset-4 hover:underline"
                    >
                        إلغاء طلب الاستحصال
                    </button>
                )}
            </div>
        </div>
    );
};

import React from 'react';
import { motion } from 'motion/react';
import { BadgeCheck, CalendarClock, ChevronDown, ChevronUp, Handshake, X, XCircle } from 'lucide-react';
import { formatIqdDisplay } from '../utils';
import type { SettlementDuePhase } from '../utils';
import type { UnifiedLedgerStore } from '../types';
import type { SettlementUxTier } from '../settlementUxMatrix';
import { resolveSettlementContext } from '../settlementContext';
import { SettlementScheduleCard } from './SettlementScheduleCard';

export interface UnifiedLedgerSettlementPanelProps {
    settlementUxTier: SettlementUxTier;
    panelOpen: boolean;
    onClosePanel: () => void;
    store: UnifiedLedgerStore;
    remainingUnified: number;
    settlementInput: string;
    setSettlementInput: (v: string) => void;
    settlementDueDateInput: string;
    setSettlementDueDateInput: (v: string) => void;
    showSettlementForm: boolean;
    setShowSettlementForm: (v: boolean) => void;
    registerSettlementPlan: () => boolean | Promise<boolean>;
    markPendingSettlementPaid: () => void;
    cancelPendingSettlement: () => void;
    canApplySettlementAny: boolean;
    showSettlementDueActions: boolean;
    pendingSettlementDuePhase: SettlementDuePhase | null;
    pendingSettlementDueYmd: string;
    onNotify: (message: string, type?: 'warning' | 'info' | 'success') => void;
    salarySeizureActive?: boolean;
}

export const UnifiedLedgerSettlementPanel: React.FC<UnifiedLedgerSettlementPanelProps> = ({
    settlementUxTier,
    panelOpen,
    onClosePanel,
    store,
    remainingUnified,
    settlementInput,
    setSettlementInput,
    settlementDueDateInput,
    setSettlementDueDateInput,
    showSettlementForm,
    setShowSettlementForm,
    registerSettlementPlan,
    markPendingSettlementPaid,
    cancelPendingSettlement,
    canApplySettlementAny,
    showSettlementDueActions,
    pendingSettlementDuePhase,
    pendingSettlementDueYmd,
    onNotify,
    salarySeizureActive = false,
}) => {
    const [settlementBreachOpen, setSettlementBreachOpen] = React.useState(false);
    const [bodyExpanded, setBodyExpanded] = React.useState(true);
    const currentYmd = React.useMemo(() => {
        const d = new Date();
        const y = d.getFullYear();
        const m = String(d.getMonth() + 1).padStart(2, '0');
        const day = String(d.getDate()).padStart(2, '0');
        return `${y}-${m}-${day}`;
    }, []);

    React.useEffect(() => {
        setSettlementBreachOpen(false);
    }, [store.pendingSettlement?.id, store.pendingSettlement?.dueDate, pendingSettlementDueYmd]);

    React.useEffect(() => {
        if (panelOpen || store.pendingSettlement) setBodyExpanded(true);
    }, [panelOpen, store.pendingSettlement?.id]);

    const handleCollapseToggle = () => {
        if (bodyExpanded) {
            setBodyExpanded(false);
            if (!store.pendingSettlement) onClosePanel();
            return;
        }
        setBodyExpanded(true);
    };

    const settlementContext = resolveSettlementContext({
        settlementUxTier,
        remainingUnified,
        completed: store.completed,
        panelOpen,
        showSettlementForm,
        pendingSettlement: store.pendingSettlement,
        pendingSettlementDueYmd,
        currentYmd,
        isFinancialDebtCollectionClaim: false,
        financialCenterTotalIqd: remainingUnified,
        settlementBreachTriggeredAt: store.settlementBreachTriggeredAt,
        salarySeizureActive,
    });

    if (!settlementContext.showSettlementPanel) return null;

    const pending = store.pendingSettlement;
    const showNewSettlementForm = settlementContext.showNewSettlementForm;
    const showPendingSummary = settlementContext.showPendingSummary;
    const showDueActions = settlementContext.showSettlementDueActions;
    const phase = settlementContext.pendingSettlementDuePhase ?? pendingSettlementDuePhase;

    const duePhaseLabel =
        phase === 'waiting'
            ? 'بانتظار موعد السداد'
            : phase === 'due'
              ? 'حان موعد السداد'
              : phase === 'overdue'
                ? 'تجاوز موعد السداد'
                : null;

    return (
        <motion.div
            key={`${settlementUxTier}-${panelOpen ? 'open' : 'closed'}`}
            initial={{ opacity: 0, y: 6 }}
            animate={{ opacity: 1, y: 0 }}
            layout
            className="space-y-3 border-t border-white/10 pt-3"
        >
            <div className="flex items-center justify-between gap-2">
                <button
                    type="button"
                    onClick={handleCollapseToggle}
                    className="shrink-0 inline-flex items-center justify-center rounded-lg border border-white/10 p-1.5 text-slate-400 transition hover:border-cyan-400/30 hover:text-cyan-200"
                    aria-label={bodyExpanded ? 'طي التسوية' : 'توسيع التسوية'}
                    aria-expanded={bodyExpanded}
                >
                    {bodyExpanded ? (
                        <ChevronUp size={16} strokeWidth={2.25} />
                    ) : (
                        <ChevronDown size={16} strokeWidth={2.25} />
                    )}
                </button>
                <p className="text-sm text-cyan-100/90 text-right font-semibold flex-1">التسوية المالية</p>
            </div>

            {bodyExpanded && showNewSettlementForm ? (
                <SettlementScheduleCard
                    settlementInput={settlementInput}
                    setSettlementInput={setSettlementInput}
                    settlementDueDateInput={settlementDueDateInput}
                    setSettlementDueDateInput={setSettlementDueDateInput}
                    canApply={canApplySettlementAny}
                    onSave={async () => {
                        const ok = await Promise.resolve(registerSettlementPlan());
                        if (ok) setShowSettlementForm(false);
                    }}
                />
            ) : null}

            {bodyExpanded && showPendingSummary ? (
                <div className="space-y-2 text-right">
                    <div className="flex flex-row-reverse items-start justify-between gap-2">
                        <div className="min-w-0 flex-1">
                            <p className="text-[10px] font-medium text-cyan-300/80">تسوية مسجلة</p>
                            <p className="text-[15px] font-black text-cyan-50 tabular-nums">
                                {formatIqdDisplay(pending!.amount)} د.ع
                            </p>
                            <p className="mt-1 flex flex-row-reverse items-center gap-1.5 text-[10px] text-slate-400">
                                <CalendarClock size={12} className="text-cyan-400/80" />
                                موعد السداد:{' '}
                                <span className="font-semibold text-slate-200 tabular-nums">
                                    {pending!.dueDate}
                                </span>
                            </p>
                            {duePhaseLabel ? (
                                <p
                                    className={`mt-1 text-[10px] font-bold ${
                                        phase === 'waiting'
                                            ? 'text-slate-400'
                                            : phase === 'due'
                                              ? 'text-amber-300'
                                              : 'text-rose-300'
                                    }`}
                                >
                                    {duePhaseLabel}
                                </p>
                            ) : null}
                        </div>
                        <Handshake size={16} className="shrink-0 text-cyan-400" />
                    </div>

                    {showDueActions && !settlementBreachOpen ? (
                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                            <button
                                type="button"
                                onClick={markPendingSettlementPaid}
                                className="w-full rounded-xl border border-emerald-500/30 bg-emerald-500/10 px-3 py-2.5 text-emerald-100 text-[11px] font-black hover:bg-emerald-500/20 transition flex items-center justify-center gap-2"
                            >
                                <BadgeCheck size={14} className="text-emerald-400" />
                                تم التسديد
                            </button>
                            <button
                                type="button"
                                onClick={() => {
                                    setSettlementBreachOpen(true);
                                    onNotify(
                                        'لم يتم التسديد ضمن الموعد — يمكنك إلغاء التسوية أو متابعة الإجراءات الجبرية.',
                                        'warning'
                                    );
                                }}
                                className="w-full rounded-xl border border-rose-500/30 bg-rose-500/10 px-3 py-2.5 text-rose-100 text-[11px] font-black hover:bg-rose-500/20 transition flex items-center justify-center gap-2"
                            >
                                <X size={14} className="text-rose-300" />
                                لم يتم التسديد
                            </button>
                        </div>
                    ) : null}

                    {settlementBreachOpen ? (
                        <motion.div
                            initial={{ opacity: 0, y: 6 }}
                            animate={{ opacity: 1, y: 0 }}
                            className="rounded-xl border border-rose-500/35 bg-rose-950/30 p-3 space-y-2"
                        >
                            <p className="text-[10px] text-rose-200/90 text-right leading-relaxed">
                                نكس التسوية — يمكن إلغاؤها لإعادة دورة الحياة كما لم تكن موجودة.
                            </p>
                            <button
                                type="button"
                                onClick={() => {
                                    cancelPendingSettlement();
                                    setSettlementBreachOpen(false);
                                }}
                                className="w-full rounded-xl border border-rose-400/40 bg-rose-500/20 px-3 py-2.5 text-rose-50 text-[11px] font-black hover:bg-rose-500/30 transition flex items-center justify-center gap-2"
                            >
                                <XCircle size={14} />
                                إلغاء التسوية
                            </button>
                            <button
                                type="button"
                                onClick={() => setSettlementBreachOpen(false)}
                                className="w-full text-center text-[10px] text-slate-400 hover:text-slate-200 py-1"
                            >
                                تراجع
                            </button>
                        </motion.div>
                    ) : null}
                </div>
            ) : null}
        </motion.div>
    );
};

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import type { Dispatch, MutableRefObject, SetStateAction } from 'react';
import { DECISIONS_RELOAD_EVENT } from '@/app/utils/executorDecisionContracts';
import type { UnifiedCollectionDecisionState } from '@/app/utils/executorDecisionContracts';
import {
    getLatestUnifiedCollectionDecisionState,
    hasApprovedUnifiedCollection,
} from '@/app/utils/executorDecisionReadQueries';
import { storageCache } from '@/app/utils/storageCache';
import {
    hydrateUnifiedLedgerFromRawStorage,
    reseedDossierBaselineLedgerRows,
    seedUnifiedLedgerStoreForExecution,
    type UnifiedLedgerHydrateParams,
} from './unifiedLedgerHydrate';
import {
    computeTrustBalanceFromPayments,
    emptyStore,
    isUnifiedLedgerLocked,
    notifyUnifiedLedgerUpdated,
    parseStoredMoney,
    parseUnifiedLedgerFromStorage,
    pickRicherLedgerStore,
    resolvePersistedLedgerStore,
    storageKey,
    type UnifiedLedgerTotalParams,
} from './utils';
import type { LocalPaymentRow, UnifiedLedgerStore } from './types';

type NotifyFn = (
    message: string,
    variant?: 'success' | 'error' | 'warning' | 'info',
    options?: { decisionsLink?: boolean }
) => void;

export interface UseFocLedgerStoreParams {
    executionId?: string;
    principal_amount: number;
    courtOrderedFeesSafe: number;
    executionExpensesSumSafe: number;
    evictionCaseExpensesSumSafe: number;
    evictionLawyerFeeWaivedAtIntake: boolean;
    isEvictionFundsModule: boolean;
    notify: NotifyFn;
    setDisburseModalOpen: (value: boolean) => void;
    autoOpenLedgerMode?: 'disburse' | null;
    onAutoOpenHandled?: () => void;
}

export interface UseFocLedgerStoreResult {
    store: UnifiedLedgerStore;
    setStore: Dispatch<SetStateAction<UnifiedLedgerStore>>;
    storeRef: MutableRefObject<UnifiedLedgerStore>;
    persist: (next: UnifiedLedgerStore) => void;
    getLatestLedgerStore: () => UnifiedLedgerStore;
    ledgerTotalParams: UnifiedLedgerTotalParams;
    isEvictionCollectionRequested: boolean;
    setIsEvictionCollectionRequested: (value: boolean) => void;
    unifiedCollectionExecutorApproved: boolean;
    unifiedCollectionDecisionState: UnifiedCollectionDecisionState;
}

/**
 * قراءة متزامنة للوعاء من التخزين — تفادي emptyStore flash عند أول paint.
 * لا تُبطِل الكاش (عكس effect الترطيب الذي يعيد الجلب).
 */
export function readInitialFocLedgerStore(
    executionId: string | undefined,
    totals: Omit<UnifiedLedgerHydrateParams, 'executionId' | 'seedLawyerId' | 'seedExpenseId'>,
): UnifiedLedgerStore {
    if (!executionId) return emptyStore();
    try {
        const raw = storageCache.get(storageKey(executionId));
        const hydrateParams: UnifiedLedgerHydrateParams = {
            ...totals,
            seedLawyerId: `seed-lawyer-${executionId}`,
            seedExpenseId: `seed-exp-${executionId}`,
            executionId,
        };
        if (raw) {
            const { store } = hydrateUnifiedLedgerFromRawStorage(
                raw,
                hydrateParams,
                getLatestUnifiedCollectionDecisionState(executionId),
            );
            return store;
        }
        return seedUnifiedLedgerStoreForExecution(hydrateParams);
    } catch {
        return emptyStore();
    }
}

/**
 * الوعاء الموحّد: الحالة + الترطيب من التخزين + المزامنة الخارجية (تسوية/قرارات) —
 * مُستخرَجة من FinancialOperationsCenter.tsx لتقليص حجم الملف الرئيسي.
 */
export function useFocLedgerStore(params: UseFocLedgerStoreParams): UseFocLedgerStoreResult {
    const {
        executionId,
        principal_amount,
        courtOrderedFeesSafe,
        executionExpensesSumSafe,
        evictionCaseExpensesSumSafe,
        evictionLawyerFeeWaivedAtIntake,
        isEvictionFundsModule,
        notify,
        setDisburseModalOpen,
        autoOpenLedgerMode,
        onAutoOpenHandled,
    } = params;

    const [store, setStore] = useState<UnifiedLedgerStore>(() =>
        readInitialFocLedgerStore(executionId, {
            principal_amount,
            courtOrderedFeesSafe,
            evictionLawyerFeeWaivedAtIntake,
            executionExpensesSumSafe,
            evictionCaseExpensesSumSafe,
        }),
    );
    const storeRef = useRef(store);
    useEffect(() => {
        storeRef.current = store;
    }, [store]);

    const [isEvictionCollectionRequested, setIsEvictionCollectionRequested] = useState(false);

    useEffect(() => {
        const handler = (e: Event) => {
            const ce = e as CustomEvent<{ executionId?: string; mode?: string }>;
            if (String(ce.detail?.executionId ?? '') !== String(executionId ?? '')) return;
            const mode = String(ce.detail?.mode ?? '').trim();
            if (mode === 'disburse') {
                const trustNow = computeTrustBalanceFromPayments(store.payments);
                if (trustNow <= 0) {
                    notify('لا يمكن الصرف: رصيد الأمانات = 0.', 'warning');
                    return;
                }
                setDisburseModalOpen(true);
            }
        };
        window.addEventListener('hami-open-financial-ledger-modal', handler as EventListener);
        return () => window.removeEventListener('hami-open-financial-ledger-modal', handler as EventListener);
    }, [executionId, notify, setDisburseModalOpen, store.payments]);

    useEffect(() => {
        if (autoOpenLedgerMode !== 'disburse') return;
        if (!executionId) {
            if (onAutoOpenHandled) onAutoOpenHandled();
            return;
        }
        const trustNow = computeTrustBalanceFromPayments(store.payments);
        if (trustNow <= 0) {
            notify('لا يمكن الصرف: رصيد الأمانات = 0.', 'warning');
            if (onAutoOpenHandled) onAutoOpenHandled();
            return;
        }
        setDisburseModalOpen(true);
        if (onAutoOpenHandled) onAutoOpenHandled();
    }, [autoOpenLedgerMode, executionId, notify, onAutoOpenHandled, setDisburseModalOpen, store.payments]);

    const [unifiedCollectionExecutorApproved, setUnifiedCollectionExecutorApproved] = useState(() =>
        hasApprovedUnifiedCollection(executionId)
    );
    const [unifiedCollectionDecisionState, setUnifiedCollectionDecisionState] = useState(() =>
        getLatestUnifiedCollectionDecisionState(executionId)
    );
    const [ledgerExternalRevision, setLedgerExternalRevision] = useState(0);

    useEffect(() => {
        const bump = () => {
            setUnifiedCollectionExecutorApproved(hasApprovedUnifiedCollection(executionId));
            setUnifiedCollectionDecisionState(getLatestUnifiedCollectionDecisionState(executionId));
        };
        bump();
        window.addEventListener(DECISIONS_RELOAD_EVENT, bump);
        window.addEventListener('hami-execution-decision-outcome', bump);
        window.addEventListener('storage', bump);
        window.addEventListener('focus', bump);
        return () => {
            window.removeEventListener(DECISIONS_RELOAD_EVENT, bump);
            window.removeEventListener('hami-execution-decision-outcome', bump);
            window.removeEventListener('storage', bump);
            window.removeEventListener('focus', bump);
        };
    }, [executionId]);

    useEffect(() => {
        const bumpLedger = (e: Event) => {
            const ce = e as CustomEvent<{ executionId?: string }>;
            const target = String(ce.detail?.executionId ?? '').trim();
            if (target && target !== String(executionId ?? '').trim()) return;
            setLedgerExternalRevision((n) => n + 1);
        };
        window.addEventListener('hami-unified-ledger-updated', bumpLedger);
        window.addEventListener('hami-unified-ledger-payment-undo', bumpLedger);
        return () => {
            window.removeEventListener('hami-unified-ledger-updated', bumpLedger);
            window.removeEventListener('hami-unified-ledger-payment-undo', bumpLedger);
        };
    }, [executionId]);

    const clearCollectionRequestIfUnifiedRejected = useCallback(() => {
        if (!executionId) return;
        if (getLatestUnifiedCollectionDecisionState(executionId) !== 'rejected') return;
        setStore((prev) => {
            if (!prev.collectionRequestActive) return prev;
            const next = { ...prev, collectionRequestActive: false };
            storageCache.set(storageKey(executionId), next);
            return next;
        });
        if (isEvictionFundsModule) setIsEvictionCollectionRequested(false);
    }, [executionId, isEvictionFundsModule]);

    useEffect(() => {
        clearCollectionRequestIfUnifiedRejected();
        window.addEventListener(DECISIONS_RELOAD_EVENT, clearCollectionRequestIfUnifiedRejected);
        window.addEventListener('hami-execution-decision-outcome', clearCollectionRequestIfUnifiedRejected);
        return () => {
            window.removeEventListener(DECISIONS_RELOAD_EVENT, clearCollectionRequestIfUnifiedRejected);
            window.removeEventListener('hami-execution-decision-outcome', clearCollectionRequestIfUnifiedRejected);
        };
    }, [clearCollectionRequestIfUnifiedRejected]);

    const persist = useCallback(
        (next: UnifiedLedgerStore) => {
            const cached = executionId
                ? parseUnifiedLedgerFromStorage(storageCache.get(storageKey(executionId)))
                : null;
            const resolved = resolvePersistedLedgerStore(storeRef.current, next, cached);
            storeRef.current = resolved;
            setStore(resolved);
            if (executionId) {
                storageCache.set(storageKey(executionId), resolved);
            }
            notifyUnifiedLedgerUpdated(executionId);
        },
        [executionId]
    );

    const ledgerTotalParams = useMemo(
        (): UnifiedLedgerTotalParams => ({
            principal_amount,
            courtOrderedFeesSafe,
            evictionLawyerFeeWaivedAtIntake,
            executionExpensesSumSafe,
            evictionCaseExpensesSumSafe,
            seedLawyerId: executionId ? `seed-lawyer-${executionId}` : '',
            seedExpenseId: executionId ? `seed-exp-${executionId}` : '',
        }),
        [
            courtOrderedFeesSafe,
            evictionCaseExpensesSumSafe,
            evictionLawyerFeeWaivedAtIntake,
            executionExpensesSumSafe,
            executionId,
            principal_amount,
        ]
    );

    const getLatestLedgerStore = useCallback((): UnifiedLedgerStore => {
        const stateStore = storeRef.current;
        if (!executionId) return stateStore;
        const cached = parseUnifiedLedgerFromStorage(storageCache.get(storageKey(executionId)));
        if (!cached) return stateStore;
        return pickRicherLedgerStore(stateStore, cached);
    }, [executionId]);

    useEffect(() => {
        setIsEvictionCollectionRequested(false);
    }, [executionId]);

    useEffect(() => {
        if (!executionId) {
            setStore(emptyStore());
            return;
        }
        try {
            storageCache.invalidate(storageKey(executionId));
            const raw = storageCache.get(storageKey(executionId));
            const hydrateParams: UnifiedLedgerHydrateParams = {
                principal_amount,
                courtOrderedFeesSafe,
                evictionLawyerFeeWaivedAtIntake,
                executionExpensesSumSafe,
                evictionCaseExpensesSumSafe,
                seedLawyerId: `seed-lawyer-${executionId}`,
                seedExpenseId: `seed-exp-${executionId}`,
                executionId,
            };
            if (raw) {
                const { store: merged, persistImmediately } = hydrateUnifiedLedgerFromRawStorage(
                    raw,
                    hydrateParams,
                    getLatestUnifiedCollectionDecisionState(executionId)
                );
                setStore(merged);
                if (persistImmediately) {
                    storageCache.set(storageKey(executionId), merged);
                }
                return;
            }

            const next = seedUnifiedLedgerStoreForExecution(hydrateParams);
            setStore(next);
            storageCache.set(storageKey(executionId), next);
        } catch {
            setStore(emptyStore());
        }
    }, [
        evictionCaseExpensesSumSafe,
        executionExpensesSumSafe,
        executionId,
        courtOrderedFeesSafe,
        evictionLawyerFeeWaivedAtIntake,
        principal_amount,
        ledgerExternalRevision,
    ]);

    useEffect(() => {
        if (!executionId) return;
        const principal = Number.isFinite(principal_amount) ? Math.max(0, principal_amount) : 0;
        if (principal <= 0) return;
        setStore((prev) => {
            if (typeof prev.principalSnapshot === 'number' && Math.abs(prev.principalSnapshot - principal) <= 0.001) {
                return prev;
            }
            const next = { ...prev, principalSnapshot: principal };
            storageCache.set(storageKey(executionId), next);
            return next;
        });
    }, [executionId, principal_amount]);

    useEffect(() => {
        if (!executionId) return;
        setStore((prev) => {
            if (
                isUnifiedLedgerLocked(executionId, prev, getLatestUnifiedCollectionDecisionState(executionId))
            ) {
                return prev;
            }
            const { lawyerFees: nextLawyer, expenses: nextExpenses } = reseedDossierBaselineLedgerRows(
                prev.lawyerFees,
                prev.expenses,
                executionId,
                {
                    principal_amount,
                    courtOrderedFeesSafe,
                    evictionLawyerFeeWaivedAtIntake,
                    executionExpensesSumSafe,
                    evictionCaseExpensesSumSafe,
                    seedLawyerId: `seed-lawyer-${executionId}`,
                    seedExpenseId: `seed-exp-${executionId}`,
                }
            );

            const unchangedLawyer =
                nextLawyer.length === prev.lawyerFees.length &&
                nextLawyer.every((r, i) => r.id === prev.lawyerFees[i]?.id && r.amount === prev.lawyerFees[i]?.amount);
            const unchangedExpenses =
                nextExpenses.length === prev.expenses.length &&
                nextExpenses.every((r, i) => r.id === prev.expenses[i]?.id && r.amount === prev.expenses[i]?.amount);
            if (unchangedLawyer && unchangedExpenses) return prev;

            const next = {
                ...prev,
                lawyerFees: nextLawyer,
                expenses: nextExpenses,
                seeded: nextLawyer.length > 0 || nextExpenses.length > 0,
            };
            storageCache.set(storageKey(executionId), next);
            return next;
        });
    }, [
        executionId,
        evictionLawyerFeeWaivedAtIntake,
        courtOrderedFeesSafe,
        executionExpensesSumSafe,
        evictionCaseExpensesSumSafe,
    ]);

    useEffect(() => {
        if (!isEvictionFundsModule) return;
        if (store.collectionRequestActive) {
            setIsEvictionCollectionRequested(true);
        }
    }, [isEvictionFundsModule, store.collectionRequestActive]);

    return {
        store,
        setStore,
        storeRef,
        persist,
        getLatestLedgerStore,
        ledgerTotalParams,
        isEvictionCollectionRequested,
        setIsEvictionCollectionRequested,
        unifiedCollectionExecutorApproved,
        unifiedCollectionDecisionState,
    };
}

export interface UseFocLedgerExternalCollectSyncParams {
    executionId?: string;
    totalOwedUnified: number;
    setStore: Dispatch<SetStateAction<UnifiedLedgerStore>>;
    storeRef: MutableRefObject<UnifiedLedgerStore>;
}

/**
 * استقبال حصيلة تحصيل خارجية (hami-unified-ledger-external-collect) — يُستدعى بعد معرفة
 * totalOwedUnified (من useFocLedgerDerived) لأن حساب الرصيد بعد كل دفعة يعتمد عليه.
 */
export function useFocLedgerExternalCollectSync(params: UseFocLedgerExternalCollectSyncParams): void {
    const { executionId, totalOwedUnified, setStore, storeRef } = params;

    useEffect(() => {
        const handler = (e: Event) => {
            const ce = e as CustomEvent<{
                executionId?: string;
                payment?: { id?: string; amount?: unknown; at?: string };
            }>;
            if (String(ce.detail?.executionId ?? '') !== String(executionId ?? '')) return;
            const p = ce.detail?.payment;
            const amt = typeof p?.amount === 'number' ? p.amount : parseStoredMoney(p?.amount);
            const safeAmt = Number.isFinite(amt) ? Math.max(0, Math.trunc(amt)) : 0;
            if (!safeAmt) return;
            const pid = String(p?.id || `pay-ext-${Date.now()}`);
            const at = String(p?.at || new Date().toISOString());
            setStore((prev) => {
                if (prev.payments.some((x) => String(x.id) === pid)) return prev;
                let debtPaid = 0;
                for (const r of prev.payments) {
                    const a = Number.isFinite(r.amount) ? r.amount : 0;
                    const et = (r.entryType ?? 'collect') as 'collect' | 'disburse' | 'settlement';
                    if (et === 'disburse') continue;
                    debtPaid += a;
                }
                const nextDebtPaid = Math.min(Math.max(0, debtPaid + safeAmt), Math.max(0, totalOwedUnified));
                const debtAfter = Math.max(0, totalOwedUnified - nextDebtPaid);
                const trustNow = computeTrustBalanceFromPayments(prev.payments);
                const trustAfter = Math.max(0, trustNow + safeAmt);
                const row: LocalPaymentRow = {
                    id: pid,
                    amount: safeAmt,
                    at,
                    kind: 'partial',
                    entryType: 'collect',
                    balanceAfter: debtAfter,
                    debtBalanceAfter: debtAfter,
                    trustBalanceAfter: trustAfter,
                };
                const next = { ...prev, payments: [row, ...prev.payments] };
                if (executionId) {
                    storageCache.set(storageKey(executionId), next);
                    notifyUnifiedLedgerUpdated(executionId);
                }
                storeRef.current = next;
                return next;
            });
        };
        window.addEventListener('hami-unified-ledger-external-collect', handler as EventListener);
        return () =>
            window.removeEventListener('hami-unified-ledger-external-collect', handler as EventListener);
    }, [executionId, totalOwedUnified, setStore, storeRef]);
}

import {
    isIqrarRequest,
    resolveStoredPathwayType,
    resolveProcedureCategory,
    PETITION_ORDER_MANUAL_OPTION,
    UNIFIED_URGENT_FORM_HEADER,
} from './constants';
import type { UrgentActionFormData, UrgentPartyEntry } from './urgentActionsFormTypes';

export type UrgentSubmitContext = {
    formData: UrgentActionFormData;
    party1List: UrgentPartyEntry[];
    party2List: UrgentPartyEntry[];
    selectedSubActionType: string;
    customSpecificActionType: string;
    party2Hidden: boolean;
    isRespondentClient: boolean;
};

export function resolveUrgentSpecificActionType(ctx: UrgentSubmitContext): string {
    if (
        ctx.selectedSubActionType === 'other' ||
        ctx.selectedSubActionType === PETITION_ORDER_MANUAL_OPTION
    ) {
        return ctx.customSpecificActionType.trim();
    }
    return String(ctx.formData.specificActionType || '').trim();
}

export function validateUrgentActionsForm(ctx: UrgentSubmitContext): Record<string, string> {
    const resolvedSpecificActionType = resolveUrgentSpecificActionType(ctx);
    const errors: Record<string, string> = {};
    const party1First = String(ctx.party1List[0]?.name ?? '').trim();
    const party2First = String(ctx.party2List[0]?.name ?? '').trim();
    const isIqrarSubmit = isIqrarRequest(resolvedSpecificActionType);
    const { formData, party2Hidden, isRespondentClient, selectedSubActionType, customSpecificActionType } =
        ctx;

    if (!formData.courtName.trim()) errors.courtName = 'حقل المحكمة إلزامي';

    if (isIqrarSubmit) {
        const rd = String(formData.requestDate || '').trim();
        if (!/^\d{4}-\d{2}-\d{2}$/.test(rd)) {
            errors.requestDate = 'موعد الحضور للمصادقة إلزامي';
        }
        if (!String(formData.requestSubject || '').trim()) {
            errors.requestSubject = 'موضوع الإقرار/الحجة إلزامي';
        }
    } else if (isRespondentClient) {
        const ep = formData.defenderEntryPhase;
        if (ep === 2) {
            const od = String(formData.stateOrderIssuedDate || '').trim();
            if (!/^\d{4}-\d{2}-\d{2}$/.test(od)) {
                errors.stateOrderIssuedDate = 'تاريخ صدور الأمر الولائي إلزامي';
            }
        }
        if (ep === 3) {
            const gd = String(formData.defenderPhase3GrievanceDecisionDate || '').trim();
            if (!/^\d{4}-\d{2}-\d{2}$/.test(gd)) {
                errors.defenderPhase3GrievanceDecisionDate = 'تاريخ قرار التظلم إلزامي';
            }
        }
    }

    if (!resolvedSpecificActionType) errors.specificActionType = 'حقل نوع الطلب / الإجراء إلزامي';
    if (
        (selectedSubActionType === 'other' || selectedSubActionType === PETITION_ORDER_MANUAL_OPTION) &&
        !customSpecificActionType.trim()
    ) {
        errors.customSpecificActionType = 'يرجى كتابة نوع الإجراء يدوياً';
    }
    if (!party1First) {
        errors.party1Name = isIqrarSubmit
            ? 'لا يمكن الحفظ بدون اسم المُقَر له (المستفيد) الأول'
            : 'لا يمكن حفظ الطلب بدون اسم طالب القرار (المستدعي) الأول';
    }
    if (!party2Hidden && !party2First) {
        errors.party2Name = isIqrarSubmit
            ? 'لا يمكن الحفظ بدون اسم المُقِر الأول'
            : 'لا يمكن حفظ الطلب بدون اسم المطلوب ضده الأول';
    }

    ctx.party1List.forEach((p, i) => {
        if (!String(p.address ?? '').trim()) {
            errors[`party1_${i}_address`] = 'العنوان إلزامي للتبليغ والإخطار القانوني';
        }
    });
    if (!party2Hidden) {
        ctx.party2List.forEach((p, i) => {
            if (!String(p.address ?? '').trim()) {
                errors[`party2_${i}_address`] = 'العنوان إلزامي للتبليغ والإخطار القانوني';
            }
        });
    }

    return errors;
}

export function buildUrgentActionsSubmitPayload(ctx: UrgentSubmitContext): Record<string, unknown> {
    const resolvedSpecificActionType = resolveUrgentSpecificActionType(ctx);
    const isIqrarSubmit = isIqrarRequest(resolvedSpecificActionType);
    const { formData, party1List, party2List, party2Hidden, isRespondentClient } = ctx;

    const allParty2Norm = party2List.map((p) => ({ ...p, isClient: !!p.isRepresented }));
    const representedParty: 'client' | 'opponent' | null = (() => {
        const p1Rep = party1List.some((p) => !!p.isRepresented);
        const p2Rep = party2List.some((p) => !!p.isRepresented);
        if (p1Rep && !p2Rep) return 'client';
        if (p2Rep && !p1Rep) return 'opponent';
        return null;
    })();
    const clientRole =
        representedParty === 'opponent' ? 'respondent' : representedParty === 'client' ? 'applicant' : null;

    const storedPathway = resolveStoredPathwayType(resolvedSpecificActionType);

    const payload: Record<string, unknown> = {
        ...formData,
        actionType: storedPathway,
        pathwayTitle: UNIFIED_URGENT_FORM_HEADER.title,
        actionPath: UNIFIED_URGENT_FORM_HEADER.title,
        createdAt: new Date().toISOString(),
        specificActionType: resolvedSpecificActionType,
        procedureCategory: resolveProcedureCategory(null, resolvedSpecificActionType),
        procedureDetails: isIqrarSubmit ? '' : String(formData.procedureDetails || '').trim(),
        firstHearingDate:
            isIqrarSubmit || !String(formData.firstHearingDate || '').trim()
                ? null
                : String(formData.firstHearingDate).trim(),
        deadlineGrievance3Days: isIqrarSubmit ? false : formData.deadlineGrievance3Days,
        deadlineTamyeez7Days: isIqrarSubmit ? false : formData.deadlineTamyeez7Days,
        hasIntervention: false,
        initialEntryMode: 'normal',
        initialJudgeDecisionDate: '',
        defenderEntryPhase: !isIqrarSubmit && isRespondentClient ? formData.defenderEntryPhase : null,
        stateOrderIssuedDate:
            !isIqrarSubmit && isRespondentClient && formData.defenderEntryPhase >= 2
                ? formData.stateOrderIssuedDate
                : '',
        defenderPhase3GrievanceDecisionDate:
            !isIqrarSubmit && isRespondentClient && formData.defenderEntryPhase === 3
                ? formData.defenderPhase3GrievanceDecisionDate
                : '',
        representedParty: isIqrarSubmit ? null : representedParty,
        clientRole: isIqrarSubmit ? null : clientRole,
        party1Name: party1List[0]?.name || '',
        party1Type: party1List[0]?.type || 'person',
        party1Phone: party1List[0]?.phone || '',
        party1Address: party1List[0]?.address || '',
        party2Name: party2List[0]?.name || '',
        party2Type: party2List[0]?.type || 'person',
        party2Address: party2List[0]?.address || '',
        allParty1: party1List,
        allParty2: allParty2Norm,
    };

    if (!isIqrarSubmit && isRespondentClient && formData.defenderEntryPhase === 2) {
        payload.initialEntryMode = 'defender_phase2';
        payload.judgeDecision = 'rejected';
        payload.judgeDecisionDate = String(formData.stateOrderIssuedDate || '').trim();
        payload.legalState = 'Awaiting_Grievance';
    } else if (!isIqrarSubmit && isRespondentClient && formData.defenderEntryPhase === 3) {
        const req = String(formData.requestDate || '').trim();
        const gDate = String(formData.defenderPhase3GrievanceDecisionDate || '').trim();
        payload.initialEntryMode = 'defender_phase3';
        payload.judgeDecision = 'rejected';
        payload.judgeDecisionDate = req;
        payload.grievanceOutcome = 'filed';
        payload.grievanceFilingDate = req;
        payload.grievanceFirstHearingDate = req;
        payload.phase2FirstHearingDate = req;
        payload.grievanceDecision = 'confirmed';
        payload.grievanceDecisionDate = gDate;
        payload.preDecisionClosed = true;
        payload.grievanceTimingConfirmed = true;
        payload.grievanceDetailsConfirmed = true;
        payload.legalState = 'Awaiting_Cassation';
    }

    return payload;
}

import { useState, useEffect, useMemo, useRef } from 'react';
import type Fuse from 'fuse.js';
import { useCaseStore } from '@/app/stores/caseStore';
import type { FileData } from '@/app/components/lawyer/LawyerShared';
import type { BuildGlobalSearchIndexInput, GlobalSearchEntry } from '@/app/services/globalSearchIndex';
import type { GlobalSearchExtras } from '@/app/services/globalSearchLoad';
import {
    computeGlobalSearchIndexKey,
    prepareGlobalSearchIndexInput,
} from '@/app/services/globalSearchIndexPrepare';
import { getCachedGlobalSearchIndex, resolveGlobalSearchIndex } from '@/app/services/globalSearchIndexRuntime';
import {
    getCachedGlobalSearchFuse,
    getOrCreateGlobalSearchFuse,
} from '@/app/services/globalSearchFuse';
import { isLitePerformanceActive } from '@/app/runtime/devicePerformanceTier';
import { getLawyerSettingsSnapshot } from '@/app/services/settings/settingsRuntime';

function resolveSearchIndexPriority(overlayOpen: boolean): 'interactive' | 'idle' {
    if (!overlayOpen) return 'idle';
    try {
        const s = getLawyerSettingsSnapshot();
        if (isLitePerformanceActive(s.performance.litePerformance)) return 'idle';
    } catch {
        /* ignore */
    }
    return 'interactive';
}

export interface UseSearchIndexOptions {
    files: FileData[];
    executionFiles?: (FileData & { executionTrashDeletedAt?: string | null })[];
    globalNotes: { id: number | string; title?: string; body?: string; type?: string }[];
    notifications?: { id: string; title: string; message: string; type: string }[];
    criminalCases: unknown[];
    userId: string | null;
    profileLine: string;
    extras: GlobalSearchExtras | null;
    isLoadingExtras: boolean;
    indexVersion?: number;
    overlayOpen?: boolean;
}

export interface UseSearchIndexReturn {
    fuse: Fuse<GlobalSearchEntry> | null;
    isBuildingIndex: boolean;
    isIndexReady: boolean;
}

function buildPreparedInput(
    options: UseSearchIndexOptions,
    cases: ReturnType<typeof useCaseStore.getState>['cases'],
    extras?: GlobalSearchExtras,
): BuildGlobalSearchIndexInput {
    return prepareGlobalSearchIndexInput({
        files: options.files,
        executionFiles: options.executionFiles,
        globalNotes: options.globalNotes,
        cases,
        criminalCases: options.criminalCases,
        profileLine: options.profileLine,
        userId: options.userId,
        notifications: options.notifications,
        extras,
        cacheGeneration: options.indexVersion,
    });
}

async function resolveFuseForKey(
    cacheKey: string,
    input: BuildGlobalSearchIndexInput,
    priority: 'interactive' | 'idle',
): Promise<Fuse<GlobalSearchEntry>> {
    const cachedFuse = getCachedGlobalSearchFuse(cacheKey);
    if (cachedFuse) return cachedFuse;

    const cachedIndex = getCachedGlobalSearchIndex(cacheKey);
    const index = cachedIndex ?? (await resolveGlobalSearchIndex(input, priority));
    return getOrCreateGlobalSearchFuse(cacheKey, index);
}

export function useSearchIndex(options: UseSearchIndexOptions): UseSearchIndexReturn {
    const cases = useCaseStore((s) => s.cases);

    const preparedFullInput = useMemo(
        () => buildPreparedInput(options, cases, options.extras ?? undefined),
        [
            options.files,
            options.executionFiles,
            options.globalNotes,
            options.notifications,
            cases,
            options.criminalCases,
            options.profileLine,
            options.userId,
            options.extras,
            options.indexVersion,
        ],
    );

    const preparedCoreInput = useMemo(
        () => buildPreparedInput(options, cases, undefined),
        [
            options.files,
            options.executionFiles,
            options.globalNotes,
            options.notifications,
            cases,
            options.criminalCases,
            options.profileLine,
            options.userId,
            options.indexVersion,
        ],
    );

    const fullCacheKey = useMemo(() => computeGlobalSearchIndexKey(preparedFullInput), [preparedFullInput]);
    const coreCacheKey = useMemo(() => computeGlobalSearchIndexKey(preparedCoreInput), [preparedCoreInput]);

    const [fuse, setFuse] = useState<Fuse<GlobalSearchEntry> | null>(
        () => getCachedGlobalSearchFuse(fullCacheKey) ?? getCachedGlobalSearchFuse(coreCacheKey),
    );
    const [isBuildingIndex, setIsBuildingIndex] = useState(false);
    const activeKeyRef = useRef<string | null>(null);

    useEffect(() => {
        let cancelled = false;
        const priority = resolveSearchIndexPriority(Boolean(options.overlayOpen));

        const applyFuse = (instance: Fuse<GlobalSearchEntry>, key: string) => {
            if (cancelled) return;
            activeKeyRef.current = key;
            setFuse(instance);
        };

        const run = async () => {
            const fullHit = getCachedGlobalSearchFuse(fullCacheKey);
            if (fullHit) {
                setIsBuildingIndex(false);
                applyFuse(fullHit, fullCacheKey);
                return;
            }

            const coreHit = getCachedGlobalSearchFuse(coreCacheKey);
            if (!options.overlayOpen) {
                if (coreHit) {
                    setIsBuildingIndex(false);
                    applyFuse(coreHit, coreCacheKey);
                }
                return;
            }

            if (coreHit && activeKeyRef.current !== fullCacheKey && !getCachedGlobalSearchFuse(fullCacheKey)) {
                applyFuse(coreHit, coreCacheKey);
            }

            const needsFullIndex = Boolean(options.extras);
            const canUseCore =
                needsFullIndex && fullCacheKey !== coreCacheKey && (options.isLoadingExtras || !options.extras);

            if (canUseCore) {
                const coreHit = getCachedGlobalSearchFuse(coreCacheKey);
                if (coreHit) {
                    applyFuse(coreHit, coreCacheKey);
                } else if (!fuse) {
                    setIsBuildingIndex(true);
                    try {
                        const coreInstance = await resolveFuseForKey(coreCacheKey, preparedCoreInput, priority);
                        applyFuse(coreInstance, coreCacheKey);
                    } catch {
                        /* يُكمَل بالفهرس الكامل */
                    }
                }
            }

            if (!needsFullIndex) {
                if (!getCachedGlobalSearchFuse(coreCacheKey) && activeKeyRef.current !== coreCacheKey) {
                    setIsBuildingIndex(true);
                    try {
                        const coreInstance = await resolveFuseForKey(coreCacheKey, preparedCoreInput, priority);
                        applyFuse(coreInstance, coreCacheKey);
                    } catch {
                        if (!cancelled && !fuse) setFuse(null);
                    } finally {
                        if (!cancelled) setIsBuildingIndex(false);
                    }
                } else {
                    setIsBuildingIndex(false);
                }
                return;
            }

            setIsBuildingIndex(true);
            try {
                const fullInstance = await resolveFuseForKey(fullCacheKey, preparedFullInput, priority);
                applyFuse(fullInstance, fullCacheKey);
            } catch {
                if (!cancelled && !fuse && activeKeyRef.current !== coreCacheKey) setFuse(null);
            } finally {
                if (!cancelled) setIsBuildingIndex(false);
            }
        };

        void run();

        return () => {
            cancelled = true;
        };
        // eslint-disable-next-line react-hooks/exhaustive-deps -- fuse kept intentionally during enrichment
    }, [
        fullCacheKey,
        coreCacheKey,
        preparedCoreInput,
        preparedFullInput,
        options.extras,
        options.isLoadingExtras,
        options.overlayOpen,
    ]);

    const isIndexReady = Boolean(fuse) && !isBuildingIndex;

    return { fuse, isBuildingIndex, isIndexReady };
}

import { useState, useEffect, useMemo, useCallback } from 'react';
import SecureStoreService from '@/app/services/SecureStoreService';
import {
    clampRecentSearchLabel,
    globalSearchRecentStorageKey,
    GLOBAL_SEARCH_MAX_RECENT_COUNT,
} from '@/app/services/search/globalSearchQuerySecurity';
import { readGlobalSearchRecentSearchesSync } from '@/app/services/search/readGlobalSearchRecentSearchesSync';
import type { GlobalSearchNavigate, GroupedSearchResults } from '@/app/services/globalSearchIndex';
import type { WorkspacePinLookupContext } from '@/app/workspace/buildPinFromSearchEntry';
import type { FileData } from '@/app/components/lawyer/LawyerShared';
import { useGlobalSearchRuntime } from '@/app/components/lawyer/GlobalSearchOverlay/hooks/GlobalSearchRuntimeProvider';
import { useSearchQuery } from '@/app/components/lawyer/GlobalSearchOverlay/hooks/useSearchQuery';

export type { GlobalSearchNavigate, GroupedSearchResults };

export interface UseGlobalSearchOptions {
    files: FileData[];
    executionFiles?: (FileData & { executionTrashDeletedAt?: string | null })[];
    globalNotes: { id: number | string; title?: string; body?: string; type?: string }[];
    notifications?: { id: string; title: string; message: string; type: string }[];
    criminalCases?: unknown[];
    userId: string | null;
    initialQuery?: string;
    indexVersion?: number;
    searchSessionKey?: number;
}

export interface UseGlobalSearchReturn {
    query: string;
    setQuery: React.Dispatch<React.SetStateAction<string>>;
    isSearching: boolean;
    isLoadingIndex: boolean;
    isEnrichingIndex: boolean;
    results: GroupedSearchResults | null;
    recentSearches: string[];
    handleResultClick: (navigate: GlobalSearchNavigate, label: string) => void;
    clearRecent: () => void;
    pinLookup: WorkspacePinLookupContext;
}

export function useGlobalSearch(
    onClose: () => void,
    onNavigate: (navigate: GlobalSearchNavigate) => void,
    options: UseGlobalSearchOptions,
): UseGlobalSearchReturn {
    const criminalCases = options.criminalCases ?? [];
    const { fuse, extras, isLoadingIndex, isEnrichingIndex } = useGlobalSearchRuntime();

    const { query, setQuery, isSearching, results } = useSearchQuery(
        options.initialQuery ?? '',
        fuse,
        isLoadingIndex,
        options.searchSessionKey ?? 0,
    );

    const recentStorageKey = globalSearchRecentStorageKey(options.userId);
    const [recentSearches, setRecentSearches] = useState<string[]>(() =>
        readGlobalSearchRecentSearchesSync(options.userId),
    );

    useEffect(() => {
        if (!recentStorageKey) {
            setRecentSearches([]);
            return;
        }
        setRecentSearches(readGlobalSearchRecentSearchesSync(options.userId));
    }, [recentStorageKey, options.userId]);

    const handleResultClick = useCallback(
        (navigate: GlobalSearchNavigate, label: string) => {
            const safeLabel = clampRecentSearchLabel(label);
            if (!safeLabel) return;
            const newRecent = [safeLabel, ...recentSearches.filter((s) => s !== safeLabel)].slice(
                0,
                GLOBAL_SEARCH_MAX_RECENT_COUNT,
            );
            setRecentSearches(newRecent);
            if (recentStorageKey) {
                SecureStoreService.setItemSync(recentStorageKey, JSON.stringify(newRecent));
            }
            onNavigate(navigate);
            /* الإغلاق من Nav فقط — تجنّب double close / sessionKey مزدوج */
        },
        [recentSearches, onNavigate, recentStorageKey],
    );

    const clearRecent = useCallback(() => {
        setRecentSearches([]);
        if (recentStorageKey) {
            SecureStoreService.deleteItemSync(recentStorageKey);
        }
    }, [recentStorageKey]);

    const pinLookup = useMemo<WorkspacePinLookupContext>(
        () => ({
            files: options.files,
            executionFiles: options.executionFiles ?? [],
            notes: options.globalNotes,
            tasks: extras?.quantumTasks ?? [],
            urgentCases: extras?.urgentCases ?? [],
            criminalCases,
            threadingTransactions: extras?.threadingTransactions ?? [],
        }),
        [options.files, options.executionFiles, options.globalNotes, extras, criminalCases],
    );

    return {
        query,
        setQuery,
        isSearching,
        isLoadingIndex,
        isEnrichingIndex,
        results,
        recentSearches,
        handleResultClick,
        clearRecent,
        pinLookup,
    };
}

import React, { memo, useEffect, useMemo, useState } from 'react';
import { RefreshCw } from 'lucide-react';
import { useLawyerSettingsData, useLawyerSettingsSecurity } from '@/app/context/LawyerSettingsContext';
import {
    isCloudSyncBuildEnabled,
    resolveCloudSyncStatusMessage,
} from '@/app/services/cloudSync/cloudSyncStatusDisplay';
import {
    BUCKET_ORDER,
    useCloudSyncStatusStore,
} from '@/app/services/cloudSync/cloudSyncStatusStore';
import { useSettingsSectionActive } from '../settingsSectionActiveContext';

const TONE_CLASS: Record<ReturnType<typeof resolveCloudSyncStatusMessage>['tone'], string> = {
    muted: 'text-white/40',
    active: 'text-[#E6C673]/85',
    success: 'text-emerald-400/85',
    warning: 'text-amber-300/85',
    error: 'text-red-300/90',
};

function selectIsSyncing(s: ReturnType<typeof useCloudSyncStatusStore.getState>): boolean {
    return BUCKET_ORDER.some((id) => s.buckets[id].isSyncing);
}

function selectLastSyncTimeMs(s: ReturnType<typeof useCloudSyncStatusStore.getState>): number | null {
    const ms = BUCKET_ORDER.reduce((max, id) => Math.max(max, s.buckets[id].lastSyncTime ?? 0), 0);
    return ms > 0 ? ms : null;
}

function selectLastError(s: ReturnType<typeof useCloudSyncStatusStore.getState>): string | null {
    for (let i = BUCKET_ORDER.length - 1; i >= 0; i -= 1) {
        const err = s.buckets[BUCKET_ORDER[i]].syncError;
        if (err) return err;
    }
    return null;
}

export const DataSyncStatusLine = memo(function DataSyncStatusLine() {
    const isSectionActive = useSettingsSectionActive();
    const data = useLawyerSettingsData();
    const security = useLawyerSettingsSecurity();
    const signedIn = useCloudSyncStatusStore((s) => s.signedIn);
    const isOnline = useCloudSyncStatusStore((s) => s.isOnline);
    const isSyncing = useCloudSyncStatusStore(selectIsSyncing);
    const lastSyncTime = useCloudSyncStatusStore(selectLastSyncTimeMs);
    const lastError = useCloudSyncStatusStore(selectLastError);
    const syncAllNow = useCloudSyncStatusStore((s) => s.syncAllNow);
    const [tick, setTick] = useState(0);

    useEffect(() => {
        if (!isSectionActive) return;

        let timer: number | undefined;

        const start = () => {
            if (document.hidden) return;
            timer = window.setInterval(() => setTick((n) => n + 1), 30_000);
        };

        const stop = () => {
            if (timer !== undefined) {
                window.clearInterval(timer);
                timer = undefined;
            }
        };

        const onVisibility = () => {
            stop();
            if (!document.hidden) start();
        };

        start();
        document.addEventListener('visibilitychange', onVisibility);
        return () => {
            stop();
            document.removeEventListener('visibilitychange', onVisibility);
        };
    }, [isSectionActive]);

    const message = useMemo(
        () =>
            resolveCloudSyncStatusMessage({
                localOnlyMode: security.localOnlyMode,
                cloudSyncEnabled: data.cloudSync,
                anyBucketEnabled: data.cloudSync,
                cloudBuildEnabled: isCloudSyncBuildEnabled(),
                signedIn,
                isOnline,
                isSyncing,
                lastSyncTime,
                lastError,
                now: new Date(),
            }),
        [
            security.localOnlyMode,
            data.cloudSync,
            signedIn,
            isOnline,
            isSyncing,
            lastSyncTime,
            lastError,
            tick,
        ],
    );

    const onSyncNow = () => {
        void syncAllNow();
    };

    return (
        <div
            className="flex items-center justify-between gap-3 px-4 pb-3 -mt-1 border-b border-white/[0.03]"
            data-testid="settings-sync-status-row"
        >
            <p
                data-testid="settings-sync-status"
                data-sync-tone={message.tone}
                className={`text-[10px] leading-relaxed min-w-0 ${TONE_CLASS[message.tone]}`}
            >
                {message.text}
            </p>
            {message.canSyncNow ? (
                <button
                    type="button"
                    data-testid="settings-sync-now"
                    onClick={onSyncNow}
                    className="shrink-0 inline-flex items-center gap-1 rounded-lg border border-white/[0.08] bg-white/[0.04] px-2 py-1 text-[10px] font-semibold text-[#E6C673]/90 transition-opacity active:opacity-80"
                >
                    <RefreshCw size={11} aria-hidden />
                    مزامنة الآن
                </button>
            ) : null}
        </div>
    );
});

import { useMemo, useRef } from 'react';
import type { SettingsSectionId } from '@/app/services/settings';

/** أقسام زُرتها تبقى mounted (مخفية) — يمنع إعادة تحميل/chunk crash عند العودة للتبويب */
export function useSettingsSectionMountSet(activeSection: SettingsSectionId) {
    const visitedRef = useRef<Set<SettingsSectionId> | null>(null);
    if (!visitedRef.current) {
        visitedRef.current = new Set<SettingsSectionId>([activeSection]);
    } else {
        visitedRef.current.add(activeSection);
    }

    return useMemo(() => new Set(visitedRef.current), [activeSection]);
}

