                                <option value="1/4">ربع الراتب (1/4)</option>
                            </select>
                        </div>
                    </>
                );
            case 'حجز مركبة':
                return (
                    <>
                        <div>
                            <label className="block text-slate-400 text-sm mb-2">مديرية المرور المخاطبة</label>
