                                snapshot={activeSnapshot}
                                onOpenKind={(kind) => trySelectHubKind(kind)}
                            />
                        </motion.div>
                    )}

                    {hubMainTab === 'tabligh' && SummonsHubTablighTab(model)}

                    {hubMainTab === 'nashr' &&
