import { useCallback, useEffect, useMemo, useState } from 'react';
import { useNotificationStore } from '@/app/stores/notificationStore';
import type { NotificationTab } from '@/app/components/lawyer/NotificationPanel/types';
import {
    isForumNotification,
    isSystemNotification,
} from '@/app/components/lawyer/NotificationPanel/utils/notificationFilters';
import { groupNotificationsByTime } from '@/app/components/lawyer/NotificationPanel/utils/timeGrouping';
import { useIncomingCaseShares } from '@/app/hooks/useIncomingCaseShares';
import { useNotificationPolling } from '@/app/components/lawyer/NotificationPanel/hooks/useNotificationPolling';
import { useNotificationActions } from '@/app/components/lawyer/NotificationPanel/hooks/useNotificationActions';

export function useNotificationPanel(
    isOpen: boolean,
    userId: string,
    panelSessionKey: number,
    onClose: () => void,
    onNavigate: (path: string, payload: Record<string, unknown>) => void,
) {
    const notifications = useNotificationStore((s) => s.notifications);
    const unreadCount = useNotificationStore((s) => s.unreadCount);
    const isLoading = useNotificationStore((s) => s.isLoading);
    const markAsRead = useNotificationStore((s) => s.markAsRead);
    const markAllAsRead = useNotificationStore((s) => s.markAllAsRead);

    const [activeTab, setActiveTab] = useState<NotificationTab>('forum');
    const [isMarkingAllRead, setIsMarkingAllRead] = useState(false);

    useEffect(() => {
        setActiveTab('forum');
    }, [panelSessionKey]);

    useNotificationPolling(isOpen, userId);

    const {
        incoming: caseShareIncoming,
        shares: caseShareAll,
        pendingCount: caseSharePendingCount,
        refresh: refreshCaseShares,
    } = useIncomingCaseShares(userId, isOpen);

    const combinedUnreadCount = unreadCount + caseSharePendingCount;

    const { handleTap, handleScan, handleClientRequest } = useNotificationActions(
        userId,
        onClose,
        onNavigate,
        markAsRead,
    );

    const visibleNotifications = useMemo(() => {
        if (activeTab === 'forum') return notifications.filter(isForumNotification);
        return notifications.filter(isSystemNotification);
    }, [notifications, activeTab]);

    const groupedByTime = useMemo(
        () => groupNotificationsByTime(visibleNotifications),
        [visibleNotifications],
    );

    const tabCounts = useMemo(() => {
        const forum = notifications.filter((n) => !n.isRead && isForumNotification(n)).length;
        const system = notifications.filter((n) => !n.isRead && isSystemNotification(n)).length;
        return { forum, system };
    }, [notifications]);

    const handleMarkAllRead = useCallback(async () => {
        if (!userId || isMarkingAllRead) return;
        setIsMarkingAllRead(true);
        try {
            await markAllAsRead(userId);
        } finally {
            setIsMarkingAllRead(false);
        }
    }, [userId, isMarkingAllRead, markAllAsRead]);

    const hasCaseShareContent = useMemo(() => {
        const pendingIncoming = caseShareAll.filter(
            (s) => s.recipientId === userId && s.status === 'pending',
        );
        const activeSessions = caseShareAll.filter(
            (s) => s.status === 'accepted' && (s.ownerId === userId || s.recipientId === userId),
        );
        const recentEnded = caseShareAll
            .filter(
                (s) => s.status === 'ended' && (s.ownerId === userId || s.recipientId === userId),
            )
            .slice(0, 5);
        return pendingIncoming.length > 0 || activeSessions.length > 0 || recentEnded.length > 0;
    }, [caseShareAll, userId]);

    return {
        activeTab,
        setActiveTab,
        unreadCount: combinedUnreadCount,
        isLoading,
        hasCachedNotifications: notifications.length > 0,
        visibleNotifications,
        groupedByTime,
        tabCounts,
        isMarkingAllRead,
        caseShareIncoming: caseShareAll,
        hasCaseShareContent,
        refreshCaseShares,
        handleTap,
        handleScan,
        handleClientRequest,
        handleMarkAllRead,
    };
}

import React, { useMemo } from 'react';
import { motion } from 'motion/react';
import { Pin, Trash2, Pencil } from 'lucide-react';
import type { TimelineEvent as ExecutionTimelineEvent } from '@/app/types/execution';
import {
    cleanTimelineCardTitle,
    formatTimelineWhenAr,
    mergeLegacyEvictionResidentialGracePairs,
    parseTimelineDeadlineDate,
    timelineDescriptionForDisplay,
    timelineSourceForDisplay,
} from '@/app/utils/timelineSmartDisplay';
import { dedupeTimelineEventsForDisplay } from '@/app/utils/timelineDedup';

interface PremiumTimelineAuditLogProps {
    events: ExecutionTimelineEvent[];
    onRequestTrash?: (event: ExecutionTimelineEvent) => void;
    onRequestEdit?: (event: ExecutionTimelineEvent) => void;
    onTogglePin?: (event: ExecutionTimelineEvent) => void;
    pinLimit?: number;
    isHistoricalMode?: boolean;
}

export const PremiumTimelineAuditLog: React.FC<PremiumTimelineAuditLogProps> = ({
    events,
    onRequestTrash,
    onRequestEdit,
    onTogglePin,
    pinLimit = 15,
    isHistoricalMode = false,
}) => {
    const displayEvents = useMemo(() => {
        const merged = dedupeTimelineEventsForDisplay(
            mergeLegacyEvictionResidentialGracePairs(events)
        );
        const sortKeyMs = (ev: ExecutionTimelineEvent): number => {
            const raw = (ev as any).timestamp || (ev as any).date;
            const d = parseTimelineDeadlineDate(raw);
            return d ? d.getTime() : 0;
        };
        return merged.slice().sort((a, b) => sortKeyMs(b) - sortKeyMs(a));
    }, [events]);

    const pickVisualTone = (event: ExecutionTimelineEvent): string => {
        const type = String((event as any).type || '');
        const title = String((event as any).title || '');
        const src = String((event as any).source || '');
        const blob = `${type} ${title} ${src}`;

        const isWarning =
            /نكس|رفض|انتهاء المهلة|لم يتم الدفع|تحذير|إنذار|مستأخرة|مهلة/iu.test(blob) ||
            /deadline|overdue|default/iu.test(blob);
        if (isWarning) {
            return 'border-rose-500/18 bg-rose-500/[0.06] hover:bg-rose-500/[0.09] ring-1 ring-rose-500/10';
        }

        const isFinancial =
            type === 'payment' ||
            type === 'settlement' ||
            /تسوية|دفعة|دفع|رسوم|محفظة|أمانات|مبلغ|الوعاء|تحصيل/iu.test(blob);
        if (isFinancial) {
            return 'border-emerald-500/18 bg-emerald-500/[0.06] hover:bg-emerald-500/[0.09] ring-1 ring-emerald-500/10';
        }

        const isProcedure =
            type === 'appointment' || /موعد|جلسة|تاريخ|زيارة|خروج ميداني|تحديد موعد/iu.test(blob);
        if (isProcedure) {
            return 'border-sky-500/16 bg-sky-500/[0.05] hover:bg-sky-500/[0.08] ring-1 ring-sky-500/10';
        }

        const isCourt = type === 'decision' || /محكمة|قرار|طعون|قضاء|محضر/iu.test(blob);
        if (isCourt) {
            return 'border-indigo-500/16 bg-indigo-500/[0.05] hover:bg-indigo-500/[0.08] ring-1 ring-indigo-500/10';
        }

        const isGuard = /كفيل|حارس|شرطة|أمر قبض|إحضار/iu.test(blob);
        if (isGuard) {
            return 'border-slate-500/18 bg-white/[0.03] hover:bg-white/[0.05] ring-1 ring-white/[0.04]';
        }

        return 'border-slate-500/18 bg-white/[0.02] hover:bg-white/[0.04] ring-1 ring-white/[0.03]';
    };

    const pinned = displayEvents.filter((e) => Boolean((e as any).isPinned));
    const unpinned = displayEvents.filter((e) => !Boolean((e as any).isPinned));

    return (
        <div className="space-y-2">
            {pinned.length > 0 ? (
                <div className="mb-2 rounded-xl border border-[#E6C673]/25 bg-[#0A1122]/35 px-3 py-2" dir="rtl">
                    <div className="flex items-center justify-between">
                        <span className="text-[11px] font-black text-[#E6C673]">الأحداث المثبتة</span>
                        <Pin size={14} className="text-[#E6C673]" />
                    </div>
                </div>
            ) : null}

            {pinned.map((event, index) => {
                const id = `${String((event as any).id || 'p')}_${index}`;
                const descriptionTrim = timelineDescriptionForDisplay(event);
                const title = cleanTimelineCardTitle(event);
                const srcDisp = timelineSourceForDisplay((event as any).source);
                const headerTime = (event as any).timestamp && String((event as any).timestamp).trim() !== '' ? (event as any).timestamp : (event as any).date;
                const when = formatTimelineWhenAr(headerTime);
                const tone = pickVisualTone(event);
                const isPinned = Boolean((event as any).isPinned);
                const canPin = Boolean(onTogglePin);

                return (
                    <motion.div
                        key={id}
                        initial={{ opacity: 0, y: 6 }}
                        animate={{ opacity: 1, y: 0 }}
                        transition={{ delay: Math.min(index, 12) * 0.015 }}
                        dir="rtl"
                        className={`group rounded-2xl border ${tone} px-3.5 py-3 transition-all`}
                    >
                        <div className="flex flex-row-reverse items-start gap-3">
                            <div className="min-w-0 flex-1">
                                <div className="flex flex-row-reverse items-start justify-between gap-2">
                                    <p className="min-w-0 flex-1 text-sm font-black leading-snug text-white break-words">
                                        {title}
                                    </p>
                                    <p className="shrink-0 text-[10px] font-semibold text-slate-500 tabular-nums">
                                        {when}
                                    </p>
                                </div>
                                <p className="mt-0.5 text-[10px] font-semibold text-slate-500">
                                    {srcDisp ? srcDisp : '—'}
                                </p>
                                {descriptionTrim ? (
                                    <p className="mt-2 text-[11px] leading-relaxed text-slate-300 whitespace-pre-line break-words">
                                        {descriptionTrim}
                                    </p>
                                ) : (
                                    <p className="mt-2 text-[11px] text-slate-500">لا يوجد وصف للحدث.</p>
                                )}
                                <div className="mt-3 flex flex-row-reverse items-center justify-between gap-2">
                                    <div className="flex flex-row-reverse items-center gap-2">
                                        {canPin ? (
                                            <button
                                                type="button"
                                                aria-pressed={isPinned}
                                                disabled={isHistoricalMode}
                                                onClick={() => {
                                                    if (isHistoricalMode) return;
                                                    onTogglePin?.(event);
                                                }}
                                                className={`inline-flex items-center justify-center rounded-lg border px-2 py-1 text-[10px] font-bold transition ${
                                                    isPinned
                                                        ? 'border-[#E6C673]/35 bg-[#E6C673]/12 text-[#E6C673]'
                                                        : 'border-white/10 bg-white/[0.03] text-slate-300 hover:bg-white/[0.06]'
                                                } ${isHistoricalMode ? 'opacity-40 cursor-not-allowed' : ''}`}
                                            >
                                                <Pin size={12} />
                                            </button>
                                        ) : null}
                                    </div>
                                    <div className="flex items-center gap-2 opacity-0 transition-opacity group-hover:opacity-100">
                                        {onRequestEdit && !isHistoricalMode ? (
                                            <button
                                                type="button"
                                                onClick={() => onRequestEdit(event)}
                                                className="inline-flex items-center gap-1 rounded-lg border border-indigo-500/25 bg-indigo-500/10 px-2 py-1 text-[10px] font-bold text-indigo-200 hover:bg-indigo-500/15"
                                            >
                                                <Pencil size={12} />
                                                تعديل
                                            </button>
                                        ) : null}
                                        {onRequestTrash && !isHistoricalMode ? (
                                            <button
                                                type="button"
                                                onClick={() => onRequestTrash(event)}
                                                className="inline-flex items-center gap-1 rounded-lg border border-rose-500/25 bg-rose-500/10 px-2 py-1 text-[10px] font-bold text-rose-200 hover:bg-rose-500/15"
                                            >
                                                <Trash2 size={12} />
                                                حذف
                                            </button>
                                        ) : null}
                                    </div>
                                </div>
                            </div>
                        </div>
                    </motion.div>
                );
            })}

            {unpinned.map((event, index) => {
                const id = `${String((event as any).id || 'u')}_${index}`;
                const descriptionTrim = timelineDescriptionForDisplay(event);
                const title = cleanTimelineCardTitle(event);
                const srcDisp = timelineSourceForDisplay((event as any).source);
                const headerTime =
                    (event as any).timestamp && String((event as any).timestamp).trim() !== ''
                        ? (event as any).timestamp
                        : (event as any).date;
                const when = formatTimelineWhenAr(headerTime);
                const tone = pickVisualTone(event);
                const canPin = Boolean(onTogglePin) && index < pinLimit;

                return (
                    <motion.div
                        key={id}
                        initial={{ opacity: 0, y: 6 }}
                        animate={{ opacity: 1, y: 0 }}
                        transition={{ delay: Math.min(index, 12) * 0.015 }}
                        dir="rtl"
                        className={`group rounded-2xl border ${tone} px-3.5 py-3 transition-all`}
                    >
                        <div className="flex flex-row-reverse items-start gap-3">
                            <div className="min-w-0 flex-1">
                                <div className="flex flex-row-reverse items-start justify-between gap-2">
                                    <p className="min-w-0 flex-1 text-sm font-black leading-snug text-white break-words">
                                        {title}
                                    </p>
                                    <p className="shrink-0 text-[10px] font-semibold text-slate-500 tabular-nums">
                                        {when}
                                    </p>
                                </div>
                                <p className="mt-0.5 text-[10px] font-semibold text-slate-500">
                                    {srcDisp ? srcDisp : '—'}
                                </p>
                                {descriptionTrim ? (
                                    <p className="mt-2 text-[11px] leading-relaxed text-slate-300 whitespace-pre-line break-words">
                                        {descriptionTrim}
                                    </p>
                                ) : (
                                    <p className="mt-2 text-[11px] text-slate-500">لا يوجد وصف للحدث.</p>
                                )}
                                <div className="mt-3 flex flex-row-reverse items-center justify-between gap-2">
                                    <div className="flex flex-row-reverse items-center gap-2">
                                        {canPin ? (
                                            <button
                                                type="button"
                                                aria-pressed={false}
                                                disabled={isHistoricalMode}
                                                onClick={() => {
                                                    if (isHistoricalMode) return;
                                                    onTogglePin?.(event);
                                                }}
                                                className={`inline-flex items-center justify-center rounded-lg border px-2 py-1 text-[10px] font-bold transition border-white/10 bg-white/[0.03] text-slate-300 hover:bg-white/[0.06] ${
                                                    isHistoricalMode ? 'opacity-40 cursor-not-allowed' : ''
                                                }`}
                                            >
                                                <Pin size={12} />
                                            </button>
                                        ) : null}
                                    </div>
                                    <div className="flex items-center gap-2 opacity-0 transition-opacity group-hover:opacity-100">
                                        {onRequestEdit && !isHistoricalMode ? (
                                            <button
                                                type="button"
                                                onClick={() => onRequestEdit(event)}
                                                className="inline-flex items-center gap-1 rounded-lg border border-indigo-500/25 bg-indigo-500/10 px-2 py-1 text-[10px] font-bold text-indigo-200 hover:bg-indigo-500/15"
                                            >
                                                <Pencil size={12} />
                                                تعديل
                                            </button>
                                        ) : null}
                                        {onRequestTrash && !isHistoricalMode ? (
                                            <button
                                                type="button"
                                                onClick={() => onRequestTrash(event)}
                                                className="inline-flex items-center gap-1 rounded-lg border border-rose-500/25 bg-rose-500/10 px-2 py-1 text-[10px] font-bold text-rose-200 hover:bg-rose-500/15"
                                            >
                                                <Trash2 size={12} />
                                                حذف
                                            </button>
                                        ) : null}
                                    </div>
                                </div>
                            </div>
                        </div>
                    </motion.div>
                );
            })}

            {displayEvents.length === 0 && (
                <div className="py-8 text-center">
                    <p className="text-xs text-gray-500">لا توجد أحداث بعد</p>
                    <p className="mt-1 text-[11px] text-gray-600">
                        سيتم تسجيل جميع الأحداث تلقائياً هنا
                    </p>
                </div>
            )}
        </div>
    );
};

import React, { useRef, useState } from 'react';
import { Plus, Trash2 } from 'lucide-react';
import type { EditDraft } from '@/app/components/lawyer/RoyalLawyerProfile/types';
import type { ProfileAction } from '@/app/services/lawyer-cloud';
import { ActionIcon } from './ActionIcon';
import { ProfileContactChannel } from './ProfileContactChannel';
import { contactValuePlaceholder } from '@/app/services/profile/profileContactNavigation';
import {
    clampProfileContactLabelLive,
    clampProfileContactValueLive,
} from '@/app/services/profile/profileContactInputSecurity';
import { pickCurrentLocationForProfile } from '@/app/services/profile/profileGeolocation';
import { SmartToast } from '@/app/components/ui/SmartToast';
import { MoroccanGlassFrame } from '@/app/components/shared/MoroccanGlassOverlay';

const CONTACT_CHANNEL_OPTIONS: { type: ProfileAction['type']; label: string }[] = [
    { type: 'whatsapp', label: 'واتساب' },
    { type: 'call', label: 'هاتف' },
    { type: 'email', label: 'بريد' },
    { type: 'location', label: 'الموقع' },
];

export type ProfileContactSectionProps = {
    isEditing: boolean;
    readOnly: boolean;
    draft: EditDraft | null;
    setDraft: React.Dispatch<React.SetStateAction<EditDraft | null>>;
    actions: ProfileAction[];
    visibleActions: ProfileAction[];
    ornatePattern: boolean;
    addContactChannel: (type: ProfileAction['type']) => void;
};

export function ProfileContactSection({
    isEditing,
    readOnly,
    draft,
    setDraft,
    actions,
    visibleActions,
    ornatePattern,
    addContactChannel,
}: ProfileContactSectionProps) {
    const editingActions = isEditing ? actions : visibleActions;
    const hasRenderedActions = editingActions.length > 0;
    const geoGenRef = useRef(0);
    const draftRef = useRef(draft);
    draftRef.current = draft;
    const [locatingActionId, setLocatingActionId] = useState<string | null>(null);
    return (
        <div>
            <MoroccanGlassFrame
                profilePanel
                ornatePattern={ornatePattern}
                className="hami-profile-section-panel"
                patternOpacity={0.07}
            >
                <div className="hami-profile-section-head">
                    <h2 className="hami-profile-section-title hami-profile-section-title--display">
                        قنوات التواصل
                    </h2>
                </div>

                {isEditing ? (
                    <div className="flex flex-wrap gap-2 mb-4">
                        {CONTACT_CHANNEL_OPTIONS.map((opt) => (
                            <button
                                key={opt.type}
                                type="button"
                                onClick={() => addContactChannel(opt.type)}
                                className="inline-flex items-center gap-1.5 px-3 py-2 min-h-[44px] rounded-xl text-[11px] font-bold hami-profile-accent-btn border transition-colors"
                            >
                                <Plus size={12} />
                                {opt.label}
                            </button>
                        ))}
                    </div>
                ) : null}

                {!hasRenderedActions && isEditing ? (
                    <p className="text-xs text-white/35 text-center py-4">
                        اختر نوع القناة أعلاه لإضافتها.
                    </p>
                ) : !hasRenderedActions ? (
                    <p className="text-xs text-white/35 text-center py-4">
                        أضف واتساب، هاتف، بريد، أو الموقع من «تعديل».
                    </p>
                ) : (
                    <div className="hami-profile-contact-stack">
                        {editingActions.map((action) =>
                            isEditing && draft ? (
                                <div key={action.id} className="hami-profile-edit-channel-row">
                                    <ActionIcon type={action.type} />
                                    <input
                                        value={action.label}
                                        onChange={(e) => {
                                            const label = clampProfileContactLabelLive(e.target.value);
                                            setDraft((prev) => {
                                                if (!prev) return prev;
                                                return {
                                                    ...prev,
                                                    actions: prev.actions.map((a) =>
                                                        a.id === action.id ? { ...a, label } : a,
                                                    ),
                                                };
                                            });
                                        }}
                                        className="flex-1 bg-transparent text-xs outline-none min-w-0"
                                        placeholder="التسمية"
                                    />
                                    <input
                                        value={action.value}
                                        onChange={(e) => {
                                            const value = clampProfileContactValueLive(e.target.value);
                                            setDraft((prev) => {
                                                if (!prev) return prev;
                                                return {
                                                    ...prev,
                                                    actions: prev.actions.map((a) =>
                                                        a.id === action.id
                                                            ? {
                                                                  ...a,
                                                                  value,
                                                                  ...(a.type === 'location'
                                                                      ? { locationMode: 'manual' as const }
                                                                      : {}),
                                                              }
                                                            : a,
                                                    ),
                                                };
                                            });
                                        }}
                                        className="flex-[2] bg-white/5 rounded-xl px-2 py-1.5 text-xs outline-none min-w-0"
                                        placeholder={contactValuePlaceholder(action.type)}
                                    />
                                    {action.type === 'location' ? (
                                        <button
                                            type="button"
                                            title="تحديد الموقع عبر GPS"
                                            aria-label="تحديد الموقع عبر GPS"
                                            disabled={locatingActionId === action.id}
                                            onClick={() => {
                                                const requestGen = ++geoGenRef.current;
                                                const actionId = action.id;
                                                setLocatingActionId(actionId);
                                                void pickCurrentLocationForProfile()
                                                    .then((coords) => {
                                                        if (!coords) return;
                                                        if (requestGen !== geoGenRef.current) return;
                                                        const current = draftRef.current;
                                                        if (!current?.actions.some((a) => a.id === actionId)) {
                                                            return;
                                                        }
                                                        setDraft((prev) => {
                                                            if (!prev) return prev;
                                                            if (!prev.actions.some((a) => a.id === actionId)) {
                                                                return prev;
                                                            }
                                                            return {
                                                                ...prev,
                                                                actions: prev.actions.map((a) =>
                                                                    a.id === actionId
                                                                        ? {
                                                                              ...a,
                                                                              value: coords,
                                                                              locationMode: 'gps',
                                                                          }
                                                                        : a,
                                                                ),
                                                            };
                                                        });
                                                        SmartToast.success('تم تحديد موقعك الحالي');
                                                    })
                                                    .finally(() => {
                                                        if (requestGen === geoGenRef.current) {
                                                            setLocatingActionId(null);
                                                        }
                                                    });
                                            }}
                                            className="shrink-0 px-2 py-1.5 min-h-[44px] rounded-lg text-[10px] font-bold hami-profile-accent-btn border whitespace-nowrap disabled:opacity-40"
                                        >
                                            {locatingActionId === action.id ? 'جاري…' : 'تحديد المكان'}
                                        </button>
                                    ) : null}
                                    <button
                                        type="button"
                                        onClick={() =>
                                            setDraft((prev) => {
                                                if (!prev) return prev;
                                                return {
                                                    ...prev,
                                                    actions: prev.actions.filter((a) => a.id !== action.id),
                                                };
                                            })
                                        }
                                        aria-label="حذف القناة"
                                        className="min-h-[44px] min-w-[44px] flex items-center justify-center text-red-400 hover:bg-red-500/10 rounded-xl touch-manipulation"
                                        style={{
                                            WebkitTapHighlightColor: 'transparent',
                                            touchAction: 'manipulation',
                                        }}
                                    >
                                        <Trash2 size={14} aria-hidden />
                                    </button>
                                </div>
                            ) : (
                                <ProfileContactChannel key={action.id} action={action} />
                            ),
                        )}
                    </div>
                )}
            </MoroccanGlassFrame>
        </div>
    );
}

import React, { useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState } from 'react';
import { GripVertical } from 'lucide-react';
import type { ProfileCustomBlock } from '@/app/services/profile/profilePageCustomization';
import {
    estimateProfileCanvasMinHeight,
    inferProfileBlockKind,
    resolveBlockPosition,
    resolveBlockWidthPct,
    sortProfileCustomBlocks,
} from '@/app/services/profile/profilePageCustomization';
import { ProfileCustomBlockView } from './ProfileCustomBlockView';

type ProfileCustomBlocksProps = {
    blocks: ProfileCustomBlock[];
    editable?: boolean;
    /** عند فتح الاستوديو: عطّل تفاعل الصفحة حتى لا ينافس معاينة الـ dock على الـ slot */
    interactionsEnabled?: boolean;
    onBlocksLayoutChange?: (blocks: ProfileCustomBlock[]) => void;
};

function clampPct(value: number, min: number, max: number) {
    return Math.max(min, Math.min(max, value));
}

type DragSession = {
    id: string;
    pointerId: number;
    startX: number;
    startY: number;
    startPosX: number;
    startPosY: number;
    element: HTMLDivElement;
    pendingPosX: number;
    pendingPosY: number;
    canvasWidth: number;
    canvasHeight: number;
};

export function ProfileCustomBlocks({
    blocks,
    editable = false,
    interactionsEnabled = true,
    onBlocksLayoutChange,
}: ProfileCustomBlocksProps) {
    const sorted = useMemo(() => sortProfileCustomBlocks(blocks), [blocks]);
    const canvasRef = useRef<HTMLDivElement>(null);
    const [liveBlocks, setLiveBlocks] = useState(sorted);
    const liveBlocksRef = useRef(sorted);
    const dragRef = useRef<DragSession | null>(null);
    const [canvasMinHeight, setCanvasMinHeight] = useState(() => estimateProfileCanvasMinHeight(sorted));
    const blocksFingerprint = useMemo(
        () =>
            sorted
                .map(
                    (b) =>
                        `${b.id}:${b.order ?? ''}:${b.posX ?? ''}:${b.posY ?? ''}:${b.blockWidthPct ?? ''}`,
                )
                .join('|'),
        [sorted],
    );

    useEffect(() => {
        if (dragRef.current) return;
        setLiveBlocks(sorted);
        liveBlocksRef.current = sorted;
        setCanvasMinHeight(estimateProfileCanvasMinHeight(sorted));
    }, [blocksFingerprint, sorted]);

    useEffect(() => {
        if (editable) return;
        const drag = dragRef.current;
        if (!drag) return;
        drag.element.dataset.dragging = 'false';
        dragRef.current = null;
        /* إلغاء السحب عند إغلاق التحرير — لا تلتزم بمواضع نصف جاهزة */
    }, [editable]);

    const commitBlocks = useCallback(
        (next: ProfileCustomBlock[]) => {
            setLiveBlocks(next);
            liveBlocksRef.current = next;
            onBlocksLayoutChange?.(next);
        },
        [onBlocksLayoutChange],
    );

    useEffect(() => {
        if (!editable) return;
        const onLostCapture = () => {
            const drag = dragRef.current;
            if (!drag) return;
            drag.element.dataset.dragging = 'false';
            const maxOrder = liveBlocksRef.current.reduce((max, b) => Math.max(max, b.order ?? 0), 0);
            const next = sortProfileCustomBlocks(
                liveBlocksRef.current.map((b) =>
                    b.id === drag.id
                        ? {
                              ...b,
                              posX: drag.pendingPosX,
                              posY: drag.pendingPosY,
                              offsetX: 0,
                              offsetY: 0,
                              order: maxOrder + 1,
                          }
                        : b,
                ),
            );
            dragRef.current = null;
            commitBlocks(next);
        };
        const canvas = canvasRef.current;
        canvas?.addEventListener('lostpointercapture', onLostCapture);
        return () => canvas?.removeEventListener('lostpointercapture', onLostCapture);
    }, [editable, commitBlocks]);

    const applyElementPosition = useCallback((el: HTMLDivElement, posX: number, posY: number) => {
        el.style.right = `${posX}%`;
        el.style.top = `${posY}%`;
    }, []);

    const computePosition = useCallback((clientX: number, clientY: number, drag: DragSession) => {
        const dx = clientX - drag.startX;
        const dy = clientY - drag.startY;
        const posX = clampPct(drag.startPosX + (-dx / drag.canvasWidth) * 100, 2, 94);
        const posY = clampPct(drag.startPosY + (dy / drag.canvasHeight) * 100, 2, 90);
        return { posX, posY };
    }, []);

    const finishDrag = useCallback(
        (event: React.PointerEvent<HTMLDivElement>) => {
            const drag = dragRef.current;
            if (!drag || drag.pointerId !== event.pointerId) return;

            /*
             * صفّر الجلسة قبل releasePointerCapture —
             * وإلا lostpointercapture يلتزم order مرتين (+1 ثم +1).
             */
            dragRef.current = null;
            drag.element.dataset.dragging = 'false';

            if (event.currentTarget.hasPointerCapture(event.pointerId)) {
                try {
                    event.currentTarget.releasePointerCapture(event.pointerId);
                } catch {
                    /* ignore */
                }
            }

            const maxOrder = liveBlocksRef.current.reduce((max, b) => Math.max(max, b.order ?? 0), 0);
            const next = sortProfileCustomBlocks(
                liveBlocksRef.current.map((b) =>
                    b.id === drag.id
                        ? {
                              ...b,
                              posX: drag.pendingPosX,
                              posY: drag.pendingPosY,
                              offsetX: 0,
                              offsetY: 0,
                              order: maxOrder + 1,
                          }
                        : b,
                ),
            );
            commitBlocks(next);
        },
        [commitBlocks],
    );

    const onHandlePointerDown = useCallback(
        (blockId: string, block: ProfileCustomBlock, index: number, event: React.PointerEvent<HTMLButtonElement>) => {
            if (!editable) return;
            event.preventDefault();
            event.stopPropagation();
            const canvas = canvasRef.current;
            const element = event.currentTarget.closest('[data-profile-block-item]') as HTMLDivElement | null;
            if (!canvas || !element) return;

            const rect = canvas.getBoundingClientRect();
            const { posX, posY } = resolveBlockPosition(block, index);
            try {
                canvas.setPointerCapture(event.pointerId);
            } catch {
                return;
            }
            element.dataset.dragging = 'true';
            dragRef.current = {
                id: blockId,
                pointerId: event.pointerId,
                startX: event.clientX,
                startY: event.clientY,
                startPosX: posX,
                startPosY: posY,
                element,
                pendingPosX: posX,
                pendingPosY: posY,
                canvasWidth: Math.max(1, rect.width),
                canvasHeight: Math.max(1, rect.height),
            };
        },
        [editable],
    );

    const onCanvasPointerMove = useCallback(
        (event: React.PointerEvent<HTMLDivElement>) => {
            const drag = dragRef.current;
            if (!drag || drag.pointerId !== event.pointerId) return;
            const { posX, posY } = computePosition(event.clientX, event.clientY, drag);
            drag.pendingPosX = posX;
            drag.pendingPosY = posY;
            applyElementPosition(drag.element, posX, posY);
        },
        [applyElementPosition, computePosition],
    );

    if (sorted.length === 0) return null;

    const blockInteractive = interactionsEnabled && !editable;

    return (
        <div className="px-4 mt-5">
            <div
                ref={canvasRef}
                data-profile-blocks-canvas
                data-editable={editable ? 'true' : 'false'}
                className="relative w-full"
                style={{ minHeight: canvasMinHeight }}
                onPointerMove={editable ? onCanvasPointerMove : undefined}
                onPointerUp={editable ? finishDrag : undefined}
                onPointerCancel={editable ? finishDrag : undefined}
            >
                {liveBlocks.map((block, index) => {
                    const kind = inferProfileBlockKind(block);
                    const { posX, posY } = resolveBlockPosition(block, index);
                    const widthPct = resolveBlockWidthPct(block);

                    return (
                        <div
                            key={block.id}
                            data-profile-block-item
                            data-block-kind={kind}
                            data-dragging="false"
                            style={{
                                position: 'absolute',
                                top: `${posY}%`,
                                right: `${posX}%`,
                                width: `${widthPct}%`,
                                maxWidth: '100%',
                                zIndex: (block.order ?? index) + 1,
                            }}
                        >
                            {editable ? (
                                <button
                                    type="button"
                                    className="profile-block-drag-handle"
                                    aria-label="اسحب لتحريك الحاوية"
                                    onPointerDown={(e) => onHandlePointerDown(block.id, block, index, e)}
                                >
                                    <GripVertical size={12} aria-hidden />
                                    <span>اسحب للتحريك</span>
                                </button>
                            ) : null}
                            <ProfileCustomBlockView block={block} interactive={blockInteractive} />
                        </div>
                    );
                })}
            </div>
        </div>
    );
}

import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { scheduleDeferredGoogleFonts } from '@/app/runtime/deferredGoogleFonts';
import { isAndroidNativeShell } from '@/app/runtime/nativePlatform';
import type { ProfileCustomBlock } from '@/app/services/profile/profilePageCustomization';
import { TextBlockCanvasPanel } from './textStudio/TextBlockCanvasPanel';
import { TextBlockStylePanel } from './textStudio/TextBlockStylePanel';
import type { TextStyleScope } from './textStudio/patchTextBlockStyle';

type StudioPanel = 'style' | 'canvas';

type TextBlockStudioEditorProps = {
    block: ProfileCustomBlock;
    onChange: (patch: Partial<ProfileCustomBlock>) => void;
    uploadingCanvasBg?: boolean;
    saving?: boolean;
    onUploadCanvasBg?: () => void;
    onClearCanvasBg?: () => void;
};

const PANELS: { id: StudioPanel; label: string; testId: string }[] = [
    { id: 'style', label: 'النص', testId: 'text-studio-tab-style' },
    { id: 'canvas', label: 'الإطار', testId: 'text-studio-tab-canvas' },
];

/**
 * محرر نص خفيف: تنسيق + إطار فقط.
 * تفاعلات الكشف الثقيلة (ستارة/غبار…) أُزيلت من الاستوديو لأنها تثقل المعاينة والجهاز.
 * النص يُثبَّت فوراً في المسودة — لا debounce يسبق «حفظ» ويفقد آخر الأحرف.
 */
export const TextBlockStudioEditor = React.memo(function TextBlockStudioEditor({
    block,
    onChange,
    uploadingCanvasBg,
    saving = false,
    onUploadCanvasBg,
    onClearCanvasBg,
}: TextBlockStudioEditorProps) {
    const [panel, setPanel] = useState<StudioPanel>('style');
    const [scope, setScope] = useState<TextStyleScope>('all');
    const [lineIndex, setLineIndex] = useState(0);
    const [phraseRange, setPhraseRange] = useState<{ start: number; end: number } | null>(null);
    const [bodyDraft, setBodyDraft] = useState(block.body ?? '');
    const bodyDraftRef = useRef(block.body ?? '');
    const blockRef = useRef(block);
    const onChangeRef = useRef(onChange);
    const armedPanelRef = useRef<StudioPanel | null>(null);

    blockRef.current = block;
    bodyDraftRef.current = bodyDraft;
    onChangeRef.current = onChange;

    const lines = useMemo(() => bodyDraft.split('\n'), [bodyDraft]);

    /* تبديل البلوك فقط — لا تُصفَّر فهرس السطر عند كل حرف في body */
    useEffect(() => {
        const nextBody = block.body ?? '';
        bodyDraftRef.current = nextBody;
        setBodyDraft(nextBody);
        setPhraseRange(null);
        setLineIndex(0);
        setScope('all');
    }, [block.id]);

    useEffect(() => {
        const nextBody = block.body ?? '';
        if (nextBody === bodyDraftRef.current) return;
        bodyDraftRef.current = nextBody;
        setBodyDraft(nextBody);
        setPhraseRange(null);
    }, [block.body]);

    useEffect(() => {
        setLineIndex((idx) => Math.min(idx, Math.max(0, lines.length - 1)));
    }, [lines.length]);

    const activatePanel = useCallback((next: StudioPanel) => {
        setPanel((curr) => (curr === next ? curr : next));
    }, []);

    useEffect(() => {
        if (panel !== 'style') return;
        if (!isAndroidNativeShell()) {
            scheduleDeferredGoogleFonts();
        }
    }, [panel]);

    const styleBlock = useMemo(() => ({ ...block, body: bodyDraft }), [block, bodyDraft]);

    return (
        <div className="profile-studio-editor" data-testid="text-block-studio-editor">
            <textarea
                value={bodyDraft}
                maxLength={2000}
                onChange={(e) => {
                    const body = e.target.value.slice(0, 2000);
                    bodyDraftRef.current = body;
                    setBodyDraft(body);
                    if (body !== (blockRef.current.body ?? '')) {
                        onChangeRef.current({ body });
                    }
                }}
                rows={4}
                className="profile-studio-body-input"
                placeholder="اكتب النص هنا…"
                data-testid="text-block-body-input"
            />

            <div className="profile-studio-panel-tabs" role="tablist" aria-label="أقسام تحرير النص">
                {PANELS.map((p) => (
                    <button
                        key={p.id}
                        type="button"
                        role="tab"
                        aria-selected={panel === p.id}
                        data-active={panel === p.id ? 'true' : 'false'}
                        data-testid={p.testId}
                        className="profile-studio-panel-tab min-h-[44px] touch-manipulation"
                        style={{ WebkitTapHighlightColor: 'transparent', touchAction: 'manipulation' }}
                        onPointerDown={(event) => {
                            if (event.button !== 0) return;
                            event.stopPropagation();
                            /* لا preventDefault — على Android يمرّر click لاحقاً ويغلق الورقة */
                            if (event.pointerType === 'touch' || event.pointerType === 'pen') {
                                armedPanelRef.current = p.id;
                                activatePanel(p.id);
                            }
                        }}
                        onClick={(event) => {
                            event.stopPropagation();
                            if (armedPanelRef.current === p.id) {
                                armedPanelRef.current = null;
                                return;
                            }
                            activatePanel(p.id);
                        }}
                    >
                        {p.label}
                    </button>
                ))}
            </div>

            <div className="profile-studio-panel-slot" role="tabpanel">
                {panel === 'style' ? (
                    <TextBlockStylePanel
                        block={styleBlock}
                        scope={scope}
                        lineIndex={lineIndex}
                        phraseRange={phraseRange}
                        lines={lines}
                        onScopeChange={setScope}
                        onLineIndexChange={setLineIndex}
                        onPhraseRangeChange={setPhraseRange}
                        onChange={onChange}
                    />
                ) : null}
                {panel === 'canvas' ? (
                    <TextBlockCanvasPanel
                        block={styleBlock}
                        uploadingCanvasBg={Boolean(uploadingCanvasBg || saving)}
                        onChange={onChange}
                        onUploadCanvasBg={onUploadCanvasBg}
                        onClearCanvasBg={onClearCanvasBg}
                    />
                ) : null}
            </div>
        </div>
    );
});

import { describe, expect, it, vi, beforeEach } from 'vitest';
