const MENU_MAX_H = 352;

type MenuPos = { top: number; left: number; width: number; maxHeight: number };

type RepositoryFiltersRailProps = {
    activeFilter: string;
    customCategories?: string[];
    docs: SmartVaultDoc[];
    notes?: GlobalNote[];
    rooms: RepositoryRoom[];
    pinnedRoomIds: string[];
    selectedRoomId: RepositoryRoomFilter;
    onSelectRoom: (filter: RepositoryRoomFilter) => void;
    onCreateRoom: (title: string) => void;
    onRemoveRoom: (roomId: string) => void;
    onTogglePinRoom: (roomId: string) => void;
    onFilterChange: (filter: string) => void;
    onAddCategory?: (name: string) => void;
    onRemoveCategory?: (name: string) => void;
    onMainFilterChange?: (filter: RepositoryFeedFilter) => void;
};

function isChipActive(activeFilter: string, value: string): boolean {
    if (value === 'الكل') return !activeFilter || activeFilter === 'الكل';
    if (activeFilter === value) return true;
    return categoryMatchesName(activeFilter, value);
}

function roomLabel(selectedRoomId: RepositoryRoomFilter, rooms: RepositoryRoom[]): string {
    if (selectedRoomId === 'main') return 'العام';
    return rooms.find((r) => r.id === selectedRoomId)?.title?.trim() || 'العام';
}

function computeMenuPos(anchor: HTMLElement): MenuPos {
    const rect = anchor.getBoundingClientRect();
    const width = Math.max(rect.width, 240);
    const gap = 6;
    const vw = window.innerWidth;
    const vh = window.innerHeight;
    const spaceBelow = vh - rect.bottom - gap - 8;
    const spaceAbove = rect.top - gap - 8;
    const preferBelow = spaceBelow >= Math.min(220, MENU_MAX_H) || spaceBelow >= spaceAbove;
    const maxHeight = Math.min(
        MENU_MAX_H,
        Math.round(vh * 0.52),
        preferBelow ? Math.max(160, spaceBelow) : Math.max(160, spaceAbove),
    );
    const top = preferBelow
        ? rect.bottom + gap
        : Math.max(8, rect.top - gap - maxHeight);
    // RTL: محاذاة الحافة اليمنى للزر
    let left = rect.right - width;
    left = Math.max(8, Math.min(left, vw - width - 8));
    return { top, left, width, maxHeight };
}

/**
 * شريط فلاتر موحّد: منتقي الغرفة + رقائق النوع/التصنيف — بلا صندوق «الغرف» المنفصل.
 */
export function RepositoryFiltersRail({
    activeFilter,
    customCategories,
    docs,
    notes = [],
    rooms,
    pinnedRoomIds,
    selectedRoomId,
    onSelectRoom,
    onCreateRoom,
    onRemoveRoom,
    onTogglePinRoom,
    onFilterChange,
    onAddCategory,
    onRemoveCategory = () => undefined,
    onMainFilterChange,
}: RepositoryFiltersRailProps) {
    const customCategoriesSafe = customCategories ?? [];
    const [roomMenuOpen, setRoomMenuOpen] = useState(false);
    const [galleryOpen, setGalleryOpen] = useState(false);
    const [creatingRoom, setCreatingRoom] = useState(false);
    const [newRoomTitle, setNewRoomTitle] = useState('');
    const [creatingCategory, setCreatingCategory] = useState(false);
    const [newCategoryName, setNewCategoryName] = useState('');
    const [menuPos, setMenuPos] = useState<MenuPos | null>(null);
    const triggerRef = useRef<HTMLButtonElement>(null);
    const menuRef = useRef<HTMLDivElement>(null);

    const countsByRoomId = useMemo(
        () => buildRepositoryRoomCounts(rooms.map((r) => r.id), notes, docs),
        [docs, notes, rooms],
    );

    const customOnlyCategories = useMemo(() => {
        const visible = getVisibleVaultCustomCategories([
            ...customCategoriesSafe,
            ...docs.map((d) => d.customCategory?.trim() || '').filter(Boolean),
        ]);
        return visible.filter((c) => !isRepositoryActionCategory(c));
    }, [customCategoriesSafe, docs]);

    useLayoutEffect(() => {
        if (!roomMenuOpen || !triggerRef.current) {
            setMenuPos(null);
            return;
        }
        const update = () => {
            if (triggerRef.current) setMenuPos(computeMenuPos(triggerRef.current));
        };
        update();
        window.addEventListener('resize', update);
        window.addEventListener('scroll', update, true);
        return () => {
            window.removeEventListener('resize', update);
            window.removeEventListener('scroll', update, true);
        };
    }, [roomMenuOpen, creatingRoom, rooms.length]);

    useEffect(() => {
        if (!roomMenuOpen) return;
        const onDoc = (e: MouseEvent) => {
            const t = e.target as Node;
            if (triggerRef.current?.contains(t)) return;
            if (menuRef.current?.contains(t)) return;
            setRoomMenuOpen(false);
            setCreatingRoom(false);
        };
        const onKey = (e: KeyboardEvent) => {
            if (e.key === 'Escape') {
                setRoomMenuOpen(false);
                setCreatingRoom(false);
            }
        };
        document.addEventListener('mousedown', onDoc);
        document.addEventListener('keydown', onKey);
        return () => {
            document.removeEventListener('mousedown', onDoc);
            document.removeEventListener('keydown', onKey);
        };
    }, [roomMenuOpen]);

    const selectFilter = (value: string) => {
        onMainFilterChange?.('all');
        onFilterChange(value);
    };

    const submitRoom = () => {
        const trimmed = newRoomTitle.trim();
        if (!trimmed) return;
        onCreateRoom(trimmed);
        setNewRoomTitle('');
        setCreatingRoom(false);
        setRoomMenuOpen(false);
    };

    const submitCategory = () => {
        const trimmed = newCategoryName.trim();
        if (!trimmed || !onAddCategory) return;
        onAddCategory(trimmed);
        selectFilter(trimmed);
        setNewCategoryName('');
        setCreatingCategory(false);
    };

    const currentRoomTitle = roomLabel(selectedRoomId, rooms);

    const roomMenu =
        roomMenuOpen && menuPos ? (
            <div
                ref={menuRef}
                role="listbox"
                className={`${REPO_ROOM_MENU} fixed`}
                data-testid="repository-room-menu"
                dir="rtl"
                style={{
                    top: menuPos.top,
                    left: menuPos.left,
                    width: menuPos.width,
                    maxHeight: menuPos.maxHeight,
                }}
            >
                {creatingRoom ? (
                    <div className="flex items-center gap-1.5 p-2" data-testid="repository-room-create-form">
                        <input
                            type="text"
                            value={newRoomTitle}
                            onChange={(e) => setNewRoomTitle(e.target.value)}
                            onKeyDown={(e) => {
                                if (e.key === 'Enter') submitRoom();
                                if (e.key === 'Escape') {
                                    setCreatingRoom(false);
                                    setNewRoomTitle('');
                                }
                            }}
                            placeholder="اسم الموكل / الغرفة…"
                            autoFocus
                            data-testid="repository-room-new-title"
                            className={`${REPO_INPUT} !py-1.5 !px-2 text-xs flex-1 min-w-0 !min-h-[40px]`}
                        />
                        <button
                            type="button"
                            onClick={submitRoom}
                            disabled={!newRoomTitle.trim()}
                            data-testid="repository-room-new-save"
                            aria-label="حفظ الغرفة"
                            className={`${REPO_TOUCH_ICON} !min-h-[40px] !min-w-[40px] rounded-lg border border-[#E6C673]/80 bg-[#E6C673]/90 text-[#0A0F1C] disabled:opacity-40`}
                        >
                            <Check size={14} />
                        </button>
                    </div>
                ) : (
                    <>
                        <div className={REPO_ROOM_MENU_SCROLL} role="presentation">
                            <button
                                type="button"
                                role="option"
                                aria-selected={selectedRoomId === 'main'}
                                data-testid="repository-room-filter-main"
                                className={REPO_ROOM_MENU_ITEM}
                                onClick={() => {
                                    onSelectRoom('main');
                                    setRoomMenuOpen(false);
                                }}
                            >
                                العام
                                {selectedRoomId === 'main' ? (
                                    <Check size={14} className="text-[#E6C673]" aria-hidden />
                                ) : null}
                            </button>
                            {rooms.map((room) => (
                                <button
                                    key={room.id}
                                    type="button"
                                    role="option"
                                    aria-selected={selectedRoomId === room.id}
                                    data-testid={`repository-room-filter-${room.id}`}
                                    title={room.title}
                                    className={REPO_ROOM_MENU_ITEM}
                                    onClick={() => {
                                        onSelectRoom(room.id);
                                        setRoomMenuOpen(false);
                                    }}
                                >
                                    <span className="truncate">{room.title}</span>
                                    {selectedRoomId === room.id ? (
                                        <Check size={14} className="text-[#E6C673] shrink-0" aria-hidden />
                                    ) : null}
                                </button>
                            ))}
                        </div>
                        <div className={REPO_ROOM_MENU_FOOTER}>
                            <button
                                type="button"
                                data-testid="repository-room-create"
                                className={REPO_ROOM_MENU_ACTION}
                                onClick={() => setCreatingRoom(true)}
                            >
                                <FolderPlus size={14} aria-hidden />
                                غرفة جديدة
                            </button>
                            {rooms.length > 0 ? (
                                <button
                                    type="button"
                                    data-testid="repository-rooms-open-gallery"
                                    className={REPO_ROOM_MENU_ITEM}
                                    onClick={() => {
                                        setRoomMenuOpen(false);
                                        setGalleryOpen(true);
                                    }}
                                >
                                    <Settings2 size={14} aria-hidden />
                                    إدارة الغرف ({rooms.length})
                                </button>
                            ) : null}
                        </div>
                    </>
                )}
            </div>
        ) : null;

    return (
        <div className={REPO_FILTER_RAIL} dir="rtl" data-testid="repository-filter-row">
            {creatingCategory ? (
                <div className="flex items-center gap-2 w-full min-w-0 px-0">
                    <input
                        type="text"
                        data-testid="smart-vault-new-category"
                        value={newCategoryName}
                        onChange={(e) => setNewCategoryName(e.target.value)}
                        onKeyDown={(e) => {
                            if (e.key === 'Enter') submitCategory();
                            if (e.key === 'Escape') {
                                setCreatingCategory(false);
                                setNewCategoryName('');
                            }
                        }}
                        placeholder="اسم التصنيف..."
                        autoFocus
                        className={`${REPO_INPUT} !py-2 !px-3 text-xs flex-1 min-w-0 !min-h-[44px]`}
                    />
                    <button
                        type="button"
                        onClick={submitCategory}
                        disabled={!newCategoryName.trim()}
                        data-testid="smart-vault-new-category-save"
                        aria-label="حفظ التصنيف"
                        className={`${REPO_TOUCH_ICON} rounded-xl border border-[#E6C673]/80 bg-[#E6C673]/90 text-[#0A0F1C] disabled:opacity-40`}
                    >
                        <Check size={16} />
                    </button>
                    <button
                        type="button"
                        onClick={() => {
                            setCreatingCategory(false);
                            setNewCategoryName('');
                        }}
                        aria-label="إلغاء"
                        className={`${REPO_TOUCH_ICON} rounded-xl border border-white/10 text-white/50`}
                    >
                        <X size={16} />
                    </button>
                </div>
            ) : (
                <div className="flex items-center gap-1.5 overflow-x-auto scrollbar-none touch-pan-x w-full min-w-0">
                    <div className="relative shrink-0" data-testid="repository-rooms-row">
                        <button
                            ref={triggerRef}
                            type="button"
                            data-testid="repository-room-filter-trigger"
                            aria-haspopup="listbox"
                            aria-expanded={roomMenuOpen}
                            onClick={() => setRoomMenuOpen((v) => !v)}
                            className={
                                selectedRoomId !== 'main' ? REPO_ROOM_CHIP_ACTIVE : REPO_ROOM_CHIP
                            }
                        >
                            <Layers size={13} className="shrink-0 opacity-80" aria-hidden />
                            <span className="truncate max-w-[7.5rem]">{currentRoomTitle}</span>
                            <ChevronDown
                                size={13}
                                className={`shrink-0 transition-transform ${roomMenuOpen ? 'rotate-180' : ''}`}
                                aria-hidden
                            />
                        </button>
                        {typeof document !== 'undefined' && roomMenu
                            ? createPortal(roomMenu, document.body)
                            : null}
                    </div>

                    {ACTION_FILTER_CHIPS.map((chip) => {
                        const active = isChipActive(activeFilter, chip.value);
                        const count =
                            chip.value === 'الكل'
                                ? undefined
                                : countRepositoryCategoryItems(docs, notes, chip.value);
                        return (
                            <button
                                key={chip.value}
                                type="button"
                                data-testid={
                                    chip.value === 'الكل'
                                        ? 'repository-filter-all'
                                        : `smart-vault-filter-${chip.value}`
                                }
                                onClick={() => selectFilter(chip.value)}
                                className={active ? REPO_FILTER_CHIP_ACTIVE : REPO_FILTER_CHIP}
                            >
                                <span>{chip.label}</span>
                                {typeof count === 'number' && count > 0 ? (
                                    <span className="opacity-70 tabular-nums text-[10px]">{count}</span>
                                ) : null}
                            </button>
                        );
                    })}

                    {customOnlyCategories.map((category) => {
                        const count = countDocsInCategory(docs, category);
                        const isActive = activeFilter === category;
                        return (
                            <div
                                key={category}
                                className={`${isActive ? REPO_FILTER_CHIP_ACTIVE : REPO_FILTER_CHIP} gap-0.5 !px-1 max-w-[9rem]`}
                            >
                                <button
                                    type="button"
                                    onClick={() => selectFilter(isActive ? 'الكل' : category)}
                                    data-testid={`smart-vault-filter-${category}`}
                                    title={category}
                                    className="min-w-0 flex-1 truncate text-right px-2 min-h-[44px] inline-flex items-center"
                                >
                                    <span className="truncate">{category}</span>
                                    {count > 0 ? (
                                        <span className="mr-1 opacity-70 tabular-nums text-[10px]">
                                            ({count})
                                        </span>
                                    ) : null}
                                </button>
                                <button
                                    type="button"
                                    onClick={(e) => {
                                        e.stopPropagation();
                                        onRemoveCategory(category);
                                    }}
                                    aria-label={`حذف تصنيف ${category}`}
                                    className={`${REPO_TOUCH_ICON} !min-w-[36px] !min-h-[36px] rounded-lg hover:bg-rose-500/20 text-inherit opacity-70 hover:opacity-100`}
                                >
                                    <X size={11} strokeWidth={2.5} />
                                </button>
                            </div>
                        );
                    })}

                    {onAddCategory ? (
                        <button
                            type="button"
                            onClick={() => setCreatingCategory(true)}
                            data-testid="smart-vault-add-category"
                            aria-label="تصنيف مخصص"
                            title="تصنيف مخصص"
                            className={REPO_FILTER_CHIP}
                        >
                            <Plus size={14} aria-hidden />
                            <span>تصنيف</span>
                        </button>
                    ) : null}
                </div>
            )}

            <RepositoryRoomsGallery
                open={galleryOpen}
                rooms={rooms}
                pinnedRoomIds={pinnedRoomIds}
                selectedRoomId={selectedRoomId === 'main' ? null : selectedRoomId}
                countsByRoomId={countsByRoomId}
                onClose={() => setGalleryOpen(false)}
                onSelect={(id) => onSelectRoom(id)}
                onRemove={onRemoveRoom}
                onTogglePin={onTogglePinRoom}
            />
        </div>
    );
}

import { useCallback, useEffect, useMemo, useState } from 'react';
import type { RefObject } from 'react';
import type { GlobalNote } from '@/app/components/lawyer/LawyerDashboardParts/types';
import type { FileData } from '@/app/components/lawyer/LawyerShared';
import type { ExecutionFile } from '@/app/components/lawyer/LawyerDashboardParts/types';
import type { SmartVaultDoc } from '@/app/services/vault/vaultTypes';
import { listLinkableDossiers } from '@/app/services/repository/repositoryDossierRegistry';
import {
    buildRepositoryFeed,
    buildRepositoryVisibleFeedByMainFilter,
    countRepositoryFeedByFilter,
    filterRepositoryFeedByRoom,
    type RepositoryFeedFilter,
} from '@/app/services/repository/repositoryUnifiedFeed';
import type { RepositoryRoomFilter } from '@/app/services/repository/repositoryRooms';
import {
    buildRepositoryFeedCacheKey,
    peekRepositoryFeedCache,
    setRepositoryFeedCache,
    invalidateRepositoryFeedCache,
} from '@/app/services/repository/repositoryFeedWarmCache';
import {
    getRepositoryFeedContainerClass,
    getRepositoryFeedItemClass,
    loadRepositoryFeedLayout,
    persistRepositoryFeedLayout,
    type RepositoryFeedLayoutId,
} from '../repositoryFeedLayout';
import { DOSSIER_NOTES_CHANGED } from '@/app/services/dossier-notes/dossierNoteSyncEvents';

type UseRepositoryFeedParams = {
    notes: GlobalNote[];
    lawsuitFiles: FileData[];
    executionFiles: ExecutionFile[];
    vaultDocs: SmartVaultDoc[];
    vaultCategoryFilter: string;
    vaultSearchQuery: string;
    roomFilter?: RepositoryRoomFilter | null;
    notesBootSettled?: boolean;
    initialFilter: RepositoryFeedFilter;
    focusNoteId?: string;
    feedScrollRef: RefObject<HTMLDivElement | null>;
    vault: {
        setActiveFilter: React.Dispatch<React.SetStateAction<string>>;
    };
};

export function useRepositoryFeed({
    notes,
    lawsuitFiles,
    executionFiles,
    vaultDocs,
    vaultCategoryFilter,
    vaultSearchQuery,
    roomFilter = 'main',
    initialFilter,
    focusNoteId,
    feedScrollRef,
    vault,
}: UseRepositoryFeedParams) {
    const [activeFilter, setActiveFilter] = useState<RepositoryFeedFilter>(initialFilter);
    const [feedEpoch, setFeedEpoch] = useState(0);
    const [feedLayout, setFeedLayout] = useState<RepositoryFeedLayoutId>(() => loadRepositoryFeedLayout());

    const dossiers = useMemo(
        () => listLinkableDossiers(lawsuitFiles, executionFiles),
        [lawsuitFiles, executionFiles],
    );

    useEffect(() => {
        setActiveFilter(initialFilter);
    }, [initialFilter]);

    useEffect(() => {
        const refresh = () => setFeedEpoch((n) => n + 1);
        window.addEventListener(DOSSIER_NOTES_CHANGED, refresh);
        return () => window.removeEventListener(DOSSIER_NOTES_CHANGED, refresh);
    }, []);

    const feedLayoutClass = getRepositoryFeedContainerClass(feedLayout);
    const feedItemLayoutClass = getRepositoryFeedItemClass(feedLayout);

    const handleFeedLayoutChange = useCallback((next: RepositoryFeedLayoutId) => {
        setFeedLayout(next);
        persistRepositoryFeedLayout(next);
    }, []);

    useEffect(() => {
        invalidateRepositoryFeedCache();
        setFeedEpoch((n) => n + 1);
    }, [notes, vaultDocs]);

    const feedItems = useMemo(() => {
        const input = {
            globalNotes: notes,
            lawsuitFiles,
            executionFiles,
            vaultDocs,
        };
        const cacheKey = buildRepositoryFeedCacheKey(input);
        const cached = peekRepositoryFeedCache(cacheKey);
        if (cached) return cached;
        const built = buildRepositoryFeed(input);
        setRepositoryFeedCache(cacheKey, built);
        return built;
    }, [executionFiles, feedEpoch, lawsuitFiles, notes, vaultDocs]);

    const roomScopedFeed = useMemo(
        () => filterRepositoryFeedByRoom(feedItems, roomFilter ?? 'main'),
        [feedItems, roomFilter],
    );

    const visibleByFilter = useMemo(
        () =>
            buildRepositoryVisibleFeedByMainFilter(
                roomScopedFeed,
                vaultCategoryFilter,
                vaultSearchQuery,
                vaultDocs,
            ),
        [roomScopedFeed, vaultCategoryFilter, vaultSearchQuery, vaultDocs],
    );

    const filterCounts = useMemo(
        () => countRepositoryFeedByFilter(roomScopedFeed),
        [roomScopedFeed],
    );

    const vaultDocsById = useMemo(() => new Map(vaultDocs.map((d) => [d.id, d])), [vaultDocs]);

    const unboundVaultDocs = useMemo(
        () => vaultDocs.filter((d) => !d.boundDossierId),
        [vaultDocs],
    );

    useEffect(() => {
        if (!focusNoteId || visibleByFilter[activeFilter].length === 0) return;
        const t = window.setTimeout(() => {
            const el = feedScrollRef.current?.querySelector(`[data-note-id="${focusNoteId}"]`);
            el?.scrollIntoView({ behavior: 'auto', block: 'nearest' });
        }, 80);
        return () => window.clearTimeout(t);
    }, [activeFilter, focusNoteId, feedScrollRef, visibleByFilter]);

    const selectMainFilter = useCallback(
        (filter: RepositoryFeedFilter) => {
            if (filter === activeFilter) {
                if (vaultCategoryFilter !== 'الكل') vault.setActiveFilter('الكل');
                return;
            }
            setActiveFilter(filter);
            if (vaultCategoryFilter !== 'الكل') vault.setActiveFilter('الكل');
        },
        [activeFilter, vault, vaultCategoryFilter],
    );

    return {
        activeFilter,
        feedLayout,
        feedLayoutClass,
        feedItemLayoutClass,
        visibleByFilter,
        filterCounts,
        vaultDocsById,
        unboundVaultDocs,
        dossiers,
        handleFeedLayoutChange,
        selectMainFilter,
    };
}

export const LEGAL_HIGHLIGHT_COLORS = ['#E6C67355', '#7DD3A855', '#F08A7855', '#8AB4F855'] as const;

const HIGHLIGHT_SELECTOR = 'mark[data-legal-hl="1"], mark.legal-hl';

export function nodeInEditor(node: Node | null, editor: HTMLElement | null): boolean {
    if (!node || !editor) return false;
    const el = node.nodeType === Node.TEXT_NODE ? node.parentElement : (node as HTMLElement);
    return Boolean(el && editor.contains(el));
}

export function unwrapElement(el: Element): void {
    const parent = el.parentNode;
    if (!parent) return;
    while (el.firstChild) parent.insertBefore(el.firstChild, el);
    parent.removeChild(el);
}

function normalizeCssColor(value: string): string | null {
    const raw = value.trim().toLowerCase();
    if (!raw || raw === 'transparent' || raw === 'rgba(0, 0, 0, 0)') return null;
    if (raw.startsWith('#')) return raw.length >= 7 ? raw.slice(0, 7) : raw;
    const rgb = /^rgba?\((\d+),\s*(\d+),\s*(\d+)/.exec(raw);
    if (!rgb) return raw;
    const hex = (n: number) => n.toString(16).padStart(2, '0');
    return `#${hex(Number(rgb[1]))}${hex(Number(rgb[2]))}${hex(Number(rgb[3]))}`;
}

export function matchHighlightColor(cssColor: string | null): string | null {
    if (!cssColor) return null;
    const normalized = normalizeCssColor(cssColor);
    if (!normalized) return null;
    for (const candidate of LEGAL_HIGHLIGHT_COLORS) {
        const base = candidate.slice(0, 7);
        if (normalized === base || normalized.startsWith(base)) return candidate;
    }
    return normalized.length >= 7 ? `${normalized}55` : null;
}

function colorsMatch(a: string, b: string): boolean {
    const na = normalizeCssColor(a);
    const nb = normalizeCssColor(b);
    if (na && nb) return na === nb;
    return a.slice(0, 7) === b.slice(0, 7);
}

function isHighlightEl(el: Element | null): el is HTMLElement {
    if (!el || !(el instanceof HTMLElement)) return false;
    if (el.dataset.legalHl === '1') return true;
    if (el.classList.contains('legal-hl')) return true;
    if (el.tagName === 'MARK') {
        const bg = el.style.backgroundColor || el.style.background;
        return Boolean(matchHighlightColor(bg));
    }
    return false;
}

function closestHighlight(node: Node | null, editor: HTMLElement): HTMLElement | null {
    let current: Node | null = node;
    if (current?.nodeType === Node.TEXT_NODE) current = current.parentElement;
    const el = current as HTMLElement | null;
    if (!el || !editor.contains(el)) return null;
    const marked = el.closest(HIGHLIGHT_SELECTOR) as HTMLElement | null;
    if (marked && editor.contains(marked)) return marked;
    let parent: Element | null = el;
    while (parent && parent !== editor) {
        if (isHighlightEl(parent)) return parent;
        parent = parent.parentElement;
    }
    return null;
}

export function getHighlightAtSelection(editor: HTMLElement): string | null {
    const sel = window.getSelection();
    if (!sel?.rangeCount) return null;
    const range = sel.getRangeAt(0);
    if (!nodeInEditor(range.startContainer, editor)) return null;

    if (!range.collapsed) {
        const uniform = getUniformHighlightColorInRange(range, editor);
        if (uniform) return uniform;
    }

    const marked = closestHighlight(range.startContainer, editor);
    if (!marked) return null;
    const bg = marked.style.backgroundColor || marked.style.background || '';
    return matchHighlightColor(bg);
}

function getUniformHighlightColorInRange(range: Range, editor: HTMLElement): string | null {
    const segments = getTextSegmentsInRange(range, editor);
    if (segments.length === 0) return null;

    let color: string | null = null;
    for (const { node, start, end } of segments) {
        if (!node.nodeValue?.slice(start, end).trim()) continue;
        const probe = document.createRange();
        probe.setStart(node, start);
        probe.setEnd(node, Math.min(end, node.nodeValue.length));
        const mark = closestHighlight(probe.startContainer, editor);
        if (!mark) return null;
        const markColor = matchHighlightColor(mark.style.backgroundColor || mark.style.background || '');
        if (!markColor) return null;
        if (!color) color = markColor;
        else if (!colorsMatch(color, markColor)) return null;
    }
    return color;
}

type TextSegment = { node: Text; start: number; end: number };

function getTextSegmentsInRange(range: Range, editor: HTMLElement): TextSegment[] {
    const segments: TextSegment[] = [];
    const walker = document.createTreeWalker(editor, NodeFilter.SHOW_TEXT);
    let textNode: Text | null;
    while ((textNode = walker.nextNode() as Text | null)) {
        if (!range.intersectsNode(textNode)) continue;
        const len = textNode.nodeValue?.length ?? 0;
        if (!len) continue;
        let start = 0;
        let end = len;
        if (textNode === range.startContainer) start = range.startOffset;
        if (textNode === range.endContainer) end = range.endOffset;
        if (start < end) segments.push({ node: textNode, start, end });
    }
    return segments;
}

function createHighlightMark(color: string): HTMLElement {
    const mark = document.createElement('mark');
    mark.className = 'legal-hl';
    mark.dataset.legalHl = '1';
    mark.style.backgroundColor = color;
    mark.style.color = 'inherit';
    return mark;
}

function wrapTextSegment(textNode: Text, start: number, end: number, color: string): void {
    const value = textNode.nodeValue ?? '';
    if (start >= end || start < 0 || end > value.length) return;

    const before = value.slice(0, start);
    const middle = value.slice(start, end);
    const after = value.slice(end);
    if (!middle) return;

    const parent = textNode.parentNode;
    if (!parent) return;

    const mark = createHighlightMark(color);
    mark.textContent = middle;

    if (after) parent.insertBefore(document.createTextNode(after), textNode.nextSibling);
    parent.insertBefore(mark, textNode.nextSibling);

    if (before) textNode.nodeValue = before;
    else parent.removeChild(textNode);
}

function wrapSelectionWithHighlight(range: Range, editor: HTMLElement, color: string): void {
    const segments = getTextSegmentsInRange(range, editor).filter((seg) =>
        Boolean(seg.node.nodeValue?.slice(seg.start, seg.end).replace(/\u200b/g, '')),
    );
    for (let i = segments.length - 1; i >= 0; i--) {
        const { node, start, end } = segments[i];
        wrapTextSegment(node, start, end, color);
    }
}

function collectIntersectingHighlights(range: Range, editor: HTMLElement): HTMLElement[] {
    const found = new Set<HTMLElement>();
    const segments = getTextSegmentsInRange(range, editor);
    for (const { node, start, end } of segments) {
        const probe = document.createRange();
        probe.setStart(node, start);
        probe.setEnd(node, end);
        const mark = closestHighlight(probe.startContainer, editor);
        if (mark) found.add(mark);
    }
    if (range.collapsed) {
        const mark = closestHighlight(range.startContainer, editor);
        if (mark) found.add(mark);
    }
    return [...found];
}

export function removeHighlightsInRange(range: Range, editor: HTMLElement): void {
    const marks = collectIntersectingHighlights(range, editor);
    for (const mark of marks) unwrapElement(mark);
}

function restoreSelectionAround(node: Node): void {
    const sel = window.getSelection();
    if (!sel) return;
    const next = document.createRange();
    next.selectNodeContents(node);
    next.collapse(false);
    sel.removeAllRanges();
    sel.addRange(next);
}

export function pruneFormatResetSpans(editor: HTMLElement): void {
    editor.querySelectorAll('[data-fmt-reset="1"]').forEach((node) => {
        const text = (node.textContent ?? '').replace(/\u200b/g, '').trim();
        if (!text) node.remove();
    });
}

function collapseCaretAfter(node: Node): void {
    const sel = window.getSelection();
    if (!sel) return;
    const next = document.createRange();
    next.setStartAfter(node);
    next.collapse(true);
    sel.removeAllRanges();
    sel.addRange(next);
}

function collapseCaretInsideText(node: Text, offset: number): void {
    const sel = window.getSelection();
    if (!sel) return;
    const next = document.createRange();
    next.setStart(node, safeTextOffset(node, offset));
    next.collapse(true);
    sel.removeAllRanges();
    sel.addRange(next);
}

function safeTextOffset(node: Node, preferred: number): number {
    if (node.nodeType !== Node.TEXT_NODE) return 0;
    const len = (node as Text).length;
    return Math.max(0, Math.min(preferred, len));
}

/** يوقف التأشير عند موضع المؤشر ويمنع امتداده للنص الجديد */
export function endHighlightAtCursor(editor: HTMLElement): boolean {
    const sel = window.getSelection();
    if (!sel?.rangeCount) return false;
    const range = sel.getRangeAt(0);
    if (!nodeInEditor(range.startContainer, editor)) return false;

    if (!range.collapsed) {
        removeHighlightsInRange(range, editor);
        collapseCaretAfter(range.endContainer.nodeType === Node.TEXT_NODE ? range.endContainer : editor);
        pruneFormatResetSpans(editor);
        return true;
    }

    const mark = closestHighlight(range.startContainer, editor);
    if (!mark) {
        pruneFormatResetSpans(editor);
        return false;
    }

    const tailRange = document.createRange();
    tailRange.setStart(range.startContainer, range.startOffset);
    tailRange.setEndAfter(mark.lastChild ?? mark);

    if (tailRange.collapsed) {
        collapseCaretAfter(mark);
        pruneFormatResetSpans(editor);
        return true;
    }

    const tail = tailRange.extractContents();
    mark.parentNode?.insertBefore(tail, mark.nextSibling);

    if (!mark.textContent?.replace(/\u200b/g, '').trim()) {
        unwrapElement(mark);
    }

    const anchor = tail.firstChild ?? mark.nextSibling ?? mark.parentNode;
    if (anchor) {
        if (anchor.nodeType === Node.TEXT_NODE) {
            collapseCaretInsideText(anchor as Text, 0);
        } else {
            collapseCaretAfter(anchor);
        }
    }
    pruneFormatResetSpans(editor);
    return true;
}

export function placeCaretAfterHighlight(editor: HTMLElement): void {
    const sel = window.getSelection();
    if (!sel?.rangeCount) return;
    const mark = closestHighlight(sel.getRangeAt(0).startContainer, editor);
    if (mark) {
        collapseCaretAfter(mark);
        return;
    }
    pruneFormatResetSpans(editor);
}

export function applyLegalHighlight(editor: HTMLElement, color: string): boolean {
    const sel = window.getSelection();
    if (!sel?.rangeCount) return false;
    const range = sel.getRangeAt(0);
    if (!nodeInEditor(range.commonAncestorContainer, editor)) return false;

    if (range.collapsed) {
        const mark = closestHighlight(range.startContainer, editor);
        if (!mark) return false;
        const current = matchHighlightColor(mark.style.backgroundColor || mark.style.background || '');
        if (current && colorsMatch(current, color)) {
            endHighlightAtCursor(editor);
            return true;
        }
        mark.style.backgroundColor = color;
        mark.dataset.legalHl = '1';
        mark.classList.add('legal-hl');
        placeCaretAfterHighlight(editor);
        return true;
    }

    const uniform = getUniformHighlightColorInRange(range, editor);
    if (uniform && colorsMatch(uniform, color)) {
        removeHighlightsInRange(range, editor);
        endHighlightAtCursor(editor);
        return true;
    }

    removeHighlightsInRange(range, editor);
    wrapSelectionWithHighlight(range, editor, color);
    placeCaretAfterHighlight(editor);
    pruneFormatResetSpans(editor);
    return true;
}

export function removeLegalHighlight(editor: HTMLElement): boolean {
    const sel = window.getSelection();
    if (!sel?.rangeCount) return false;
    const range = sel.getRangeAt(0);
    if (!nodeInEditor(range.commonAncestorContainer, editor)) return false;

    if (range.collapsed) {
        return endHighlightAtCursor(editor);
    }

    const marks = collectIntersectingHighlights(range, editor);
    if (marks.length === 0) return false;
    for (const mark of marks) unwrapElement(mark);
    endHighlightAtCursor(editor);
    pruneFormatResetSpans(editor);
    return true;
}

import { useEffect, useState } from 'react';
import type { SmartVaultDoc } from '@/app/services/vault/vaultTypes';
import { resolveVaultDocUrl } from '@/app/services/vaultUploadService';
import { revokeBlobUrlIfNeeded } from '@/app/services/vault/vaultDocUtils';
import { isVaultIdbStoragePath } from '@/app/services/vaultBlobStore';

/**
 * يحلّ رابط عرض ملف الخزنة — يدعم التخزين المحلي (IDB) والروابط الموقّعة المنتهية.
 */
export function useVaultDocDisplayUrl(doc: SmartVaultDoc | null | undefined): string | null {
    const [url, setUrl] = useState<string | null>(() => doc?.signedUrl?.trim() || null);

    useEffect(() => {
        if (!doc) {
            setUrl(null);
            return;
        }

        let cancelled = false;
        let ownedBlob: string | null = null;
        const cached = doc.signedUrl?.trim() || null;

        const hasDurableLocalBlob = isVaultIdbStoragePath(doc.storagePath || '');

        if (cached && !hasDurableLocalBlob) {
            setUrl(cached);
            if (cached.startsWith('blob:') || cached.startsWith('data:')) {
                return;
            }
        }

        void resolveVaultDocUrl(doc).then((resolved) => {
            if (cancelled) {
                revokeBlobUrlIfNeeded(resolved);
                return;
            }
            if (resolved) {
                if (resolved.startsWith('blob:')) ownedBlob = resolved;
                setUrl(resolved);
            } else if (!cached) {
                setUrl(null);
            }
        });

        return () => {
            cancelled = true;
            revokeBlobUrlIfNeeded(ownedBlob);
        };
    }, [doc?.id, doc?.storagePath, doc?.signedUrl, doc?.updatedAt]);

    return url;
}

