import React, { useMemo, useState } from 'react';
import { AnimatePresence, motion } from 'motion/react';
import { useCriminalStore } from '../criminalStore';
import {
    buildProceduralLinkOptions,
    type ProceduralContextValue,
    type ProceduralLinkOption,
} from '../proceduralItemLink';

export type ProceduralContextLinkFieldProps = {
    caseId: string;
    value: ProceduralContextValue;
    onChange: (next: ProceduralContextValue) => void;
};

type PickMode = 'none' | 'timeline' | 'request' | 'text';

const linkPanelMotion = {
    initial: { opacity: 0, height: 0, marginTop: 0 },
    animate: { opacity: 1, height: 'auto', marginTop: 8 },
    exit: { opacity: 0, height: 0, marginTop: 0 },
    transition: { duration: 0.22, ease: [0.22, 1, 0.36, 1] as const },
};

export const ProceduralContextLinkField = ({ caseId, value, onChange }: ProceduralContextLinkFieldProps) => {
    const caseRow = useCriminalStore((s) => s.casesById[caseId]);
    const { timeline, requests } = useMemo(
        () =>
            buildProceduralLinkOptions({
                timelineEvents: caseRow?.timelineEvents,
                lawyerRequests: caseRow?.lawyerRequests,
            }),
        [caseRow?.lawyerRequests, caseRow?.timelineEvents],
    );

    const [mode, setMode] = useState<PickMode>(() =>
        value.link ? value.link.kind : value.contextNote && !value.link ? 'text' : 'none',
    );
    const [query, setQuery] = useState('');

    const list: ProceduralLinkOption[] = mode === 'timeline' ? timeline : mode === 'request' ? requests : [];

    const filtered = useMemo(() => {
        const q = query.trim().toLowerCase();
        if (!q) return list.slice(0, 40);
        return list.filter((o) => `${o.label} ${o.sublabel ?? ''}`.toLowerCase().includes(q)).slice(0, 40);
    }, [list, query]);

    const setModeAndReset = (m: PickMode) => {
        setMode(m);
        setQuery('');
        if (m === 'text') {
            onChange({ link: undefined, contextNote: value.contextNote ?? '' });
        } else if (m === 'none') {
            onChange({});
        } else {
            onChange({ link: undefined, contextNote: value.contextNote });
        }
    };

    const pick = (opt: ProceduralLinkOption) => {
        onChange({
            link: { kind: opt.kind, id: opt.id, label: opt.label },
            contextNote: value.contextNote,
        });
    };

    const tabActiveClass =
        'border-[#E6C673] bg-[#E6C673] text-[#0B1021] shadow-[0_0_14px_rgba(230,198,115,0.45)]';
    const tabIdleClass = 'border-slate-600/50 text-white/55 hover:text-white hover:border-slate-500/70 bg-transparent';

    return (
        <div className="space-y-2">
            <label className="block text-white/70 text-xs font-black">ربط بالقضية (اختياري)</label>
            <div className="flex flex-wrap gap-1">
                {(
                    [
                        { id: 'none', label: 'بدون ربط' },
                        { id: 'timeline', label: '📅 تايم لاين' },
                        { id: 'request', label: '📋 طلب' },
                        { id: 'text', label: 'نص حر' },
                    ] as const
                ).map((tab) => (
                    <button
                        key={tab.id}
                        type="button"
                        onClick={() => setModeAndReset(tab.id as PickMode)}
                        className={`rounded-lg px-2.5 py-1.5 text-[10px] font-black border transition-all duration-200 ${
                            mode === tab.id ? tabActiveClass : tabIdleClass
                        }`}
                    >
                        {tab.label}
                    </button>
                ))}
            </div>

            {value.link ? (
                <div className="rounded-lg border border-[#E6C673]/35 bg-[#E6C673]/10 px-3 py-2 flex items-start justify-between gap-2">
                    <div className="min-w-0 text-[11px] font-bold text-[#E6C673]/95 break-words">
                        {value.link.kind === 'timeline' ? '📅' : '📋'} {value.link.label}
                    </div>
                    <button
                        type="button"
                        onClick={() => onChange({ contextNote: value.contextNote })}
                        className="text-[10px] font-black text-white/50 hover:text-red-300 shrink-0"
                    >
                        إزالة
                    </button>
                </div>
            ) : null}

            <AnimatePresence initial={false} mode="wait">
                {mode === 'timeline' || mode === 'request' ? (
                    <motion.div
                        key={mode}
                        {...linkPanelMotion}
                        className="overflow-hidden"
                    >
                        <div className="rounded-xl border border-slate-700 bg-slate-900/80 p-2 space-y-2">
                            <input
                                className="w-full bg-slate-950 border border-slate-600 rounded-lg px-2 py-1.5 text-xs text-white outline-none focus:border-[#E6C673]/50"
                                value={query}
                                onChange={(e) => setQuery(e.target.value)}
                                placeholder="بحث سريع..."
                            />
                            {filtered.length === 0 ? (
                                <div className="text-white/45 text-[10px] font-bold px-1 py-2 text-center">
                                    لا توجد سجلات — أضفها من تبويب التايم لاين أو الطلبات أولاً
                                </div>
                            ) : (
                                <ul className="max-h-36 overflow-y-auto space-y-1">
                                    {filtered.map((opt) => (
                                        <li key={`${opt.kind}-${opt.id}`}>
                                            <button
                                                type="button"
                                                onClick={() => pick(opt)}
                                                className={`w-full text-right rounded-lg px-2 py-1.5 text-[11px] font-bold transition ${
                                                    value.link?.id === opt.id && value.link?.kind === opt.kind
                                                        ? 'bg-[#E6C673]/20 text-[#E6C673] border border-[#E6C673]/40'
                                                        : 'text-white/80 hover:bg-slate-800 border border-transparent'
                                                }`}
                                            >
                                                <div className="whitespace-normal break-words">{opt.label}</div>
                                                {opt.sublabel ? (
                                                    <div className="text-white/40 text-[9px] mt-0.5">{opt.sublabel}</div>
                                                ) : null}
                                            </button>
                                        </li>
                                    ))}
                                </ul>
                            )}
                        </div>
                    </motion.div>
                ) : null}

                {mode === 'text' ? (
                    <motion.div key="text" {...linkPanelMotion} className="overflow-hidden">
                        <input
                            className="w-full bg-slate-900 border border-slate-700 rounded-xl px-3 py-2 text-sm text-white outline-none focus:border-[#E6C673]/60"
                            value={value.contextNote ?? ''}
                            onChange={(e) => onChange({ contextNote: e.target.value.trim() || undefined })}
                            placeholder="مرجع نصي حر..."
                        />
                    </motion.div>
                ) : null}

                {(mode === 'timeline' || mode === 'request') && value.link ? (
                    <motion.div key="link-note" {...linkPanelMotion} className="overflow-hidden">
                        <input
                            className="w-full bg-slate-900 border border-slate-700 rounded-xl px-3 py-2 text-xs text-white outline-none focus:border-[#E6C673]/60"
                            value={value.contextNote ?? ''}
                            onChange={(e) =>
                                onChange({
                                    link: value.link,
                                    contextNote: e.target.value.trim() || undefined,
                                })
                            }
                            placeholder="ملاحظة إضافية بجانب الربط (اختياري)"
                        />
                    </motion.div>
                ) : null}
            </AnimatePresence>
        </div>
    );
};

import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useCriminalStore } from '../criminalStore';
import {
    CONTAINER_COLOR_PRESETS,
    createProceduralId,
    buildProceduralAttentionBoard,
    buildProceduralPlacementContext,
    buildProceduralSearchVisibility,
    findActionAnchorInTree,
    findContainerAnchorInTree,
    findContainerInTree,
    findSubItemAnchorInTree,
    type ProceduralPlacementContext,
    type ProceduralActionItem,
    type ProceduralContainer,
    type ProceduralNoteItem,
    type ProceduralNavTarget,
    type AddChildKind,
} from '../proceduralContainersEngine';
import { ProceduralContainerFormModal } from './modals/ProceduralContainerFormModal';
import { ProceduralAddChildModal } from './modals/ProceduralAddChildModal';
import { ProceduralNoteFormModal } from './modals/ProceduralNoteFormModal';
import { ProceduralActionFormModal } from './modals/ProceduralActionFormModal';
import { ProceduralAdvancePhaseModal } from './modals/ProceduralAdvancePhaseModal';
import { CriminalModalPortal, CRIMINAL_MODAL_Z } from '../criminalModalPortal';
import {
    formatProceduralLinkDisplay,
    isProceduralLinkBroken,
    normalizeProceduralContextValue,
    resolveLiveLinkLabel,
    type ProceduralItemLink,
} from '../proceduralItemLink';
import { CasePhaseSegmentedControl } from './CasePhaseSegmentedControl';
import {
    filterByCasePhase,
    resolveProceduralRootCasePhase,
    resolveTrialPhasePivotMs,
    type CasePhaseFilter,
} from '../casePhaseFilterEngine';
import { parseProceduralDrag, DRAG_MIME, type DragPayload } from './RecursiveProceduralCanvas/dragUtils';
import type {
    ActionModalMode,
    AdvanceModalMode,
    ContainerModalMode,
    NoteModalMode,
} from './RecursiveProceduralCanvas/types';
import { AttentionColumn } from './RecursiveProceduralCanvas/AttentionBoardColumns';
import {
    ProceduralContainerTreeNode,
    type ProceduralTreeContext,
} from './RecursiveProceduralCanvas/ProceduralContainerTreeNode';

export type RecursiveProceduralCanvasProps = {
    caseId: string;
    readOnly?: boolean;
    onOpenLinkedRecord?: (link: ProceduralItemLink) => void;
    /** انتقال من تبويب آخر (طلب/تايم لاين) */
    navTarget?: ProceduralNavTarget | null;
    onNavTargetHandled?: () => void;
};

/**
 * لوحة مسارات التتبع الإجرائي — نصوص وإجراءات حرة يدوياً.
 * دورة حياة جلسات المحاكمة والأحكام الفورية تُدار حصرياً من تبويب «المحاكمات» (trials[]).
 */

export const RecursiveProceduralCanvas = ({
    caseId,
    readOnly = false,
    onOpenLinkedRecord,
    navTarget,
    onNavTargetHandled,
}: RecursiveProceduralCanvasProps) => {
    const caseRow = useCriminalStore((s) => s.casesById[caseId]);
    const containers = Array.isArray(caseRow?.proceduralContainers) ? caseRow.proceduralContainers : [];
    const addRoot = useCriminalStore((s) => s.addRootProceduralContainer);
    const updateContainer = useCriminalStore((s) => s.updateProceduralContainer);
    const deleteContainer = useCriminalStore((s) => s.deleteProceduralContainer);
    const reorderRoot = useCriminalStore((s) => s.reorderRootProceduralContainers);
    const addSubItem = useCriminalStore((s) => s.addProceduralSubItem);
    const updateSubItem = useCriminalStore((s) => s.updateProceduralSubItem);
    const deleteSubItem = useCriminalStore((s) => s.deleteProceduralSubItem);
    const duplicateSubItem = useCriminalStore((s) => s.duplicateProceduralSubItem);
    const moveSubItem = useCriminalStore((s) => s.moveProceduralSubItem);
    const moveContainer = useCriminalStore((s) => s.moveProceduralContainer);
    const advanceAction = useCriminalStore((s) => s.advanceProceduralActionPhase);
    const duplicateContainer = useCriminalStore((s) => s.duplicateProceduralContainer);

    const [containerModal, setContainerModal] = useState<ContainerModalMode>(null);
    const [addChildParentId, setAddChildParentId] = useState<string | null>(null);
    const [noteModal, setNoteModal] = useState<NoteModalMode>(null);
    const [actionModal, setActionModal] = useState<ActionModalMode>(null);
    const [advanceModal, setAdvanceModal] = useState<AdvanceModalMode>(null);
    const [dragRootId, setDragRootId] = useState<string | null>(null);
    const [confirmDeleteId, setConfirmDeleteId] = useState<string | null>(null);
    const [attentionOpen, setAttentionOpen] = useState(true);
    const [navExpandIds, setNavExpandIds] = useState<Set<string>>(() => new Set());
    const [focusActionId, setFocusActionId] = useState<string | null>(null);
    const [focusNoteId, setFocusNoteId] = useState<string | null>(null);
    const [searchQuery, setSearchQuery] = useState('');

    const stageJourney = Array.isArray(caseRow?.stageJourney) ? caseRow.stageJourney : [];
    const hasTrialPhase = resolveTrialPhasePivotMs(stageJourney) != null;

    /**
     * مرشّح المرحلة للمسارات الإجرائية:
     *   • قبل وجود مرحلة محاكمة ⇒ `'all'` (لا قائمة اختيار حيث لا يوجد فصل بعد).
     *   • مع وجود مرحلة محاكمة ⇒ يَبدأ افتراضياً عند `'trial'` لإخفاء مسارات التحقيق المُغلقة،
     *     ويُمكن للمستخدم التَوسعة يدوياً عبر شريط الترشيح.
     */
    const [pathsPhaseFilter, setPathsPhaseFilter] = useState<CasePhaseFilter>(
        () => (hasTrialPhase ? 'trial' : 'all'),
    );
    const prevHasTrialPhaseRef = useRef(hasTrialPhase);
    useEffect(() => {
        const wasTrial = prevHasTrialPhaseRef.current;
        prevHasTrialPhaseRef.current = hasTrialPhase;
        if (!hasTrialPhase) {
            setPathsPhaseFilter('all');
            return;
        }
        if (!wasTrial) setPathsPhaseFilter('trial');
    }, [hasTrialPhase]);

    const searchVisibility = useMemo(
        () => buildProceduralSearchVisibility(containers, searchQuery),
        [containers, searchQuery],
    );

    const attentionBoard = useMemo(() => buildProceduralAttentionBoard(containers), [containers]);

    const notePlacement = useMemo((): ProceduralPlacementContext | null => {
        if (!noteModal?.parentId) return null;
        return buildProceduralPlacementContext(containers, noteModal.parentId);
    }, [containers, noteModal?.parentId]);

    const actionPlacement = useMemo((): ProceduralPlacementContext | null => {
        if (!actionModal?.parentId) return null;
        return buildProceduralPlacementContext(containers, actionModal.parentId);
    }, [containers, actionModal?.parentId]);

    const focusActionInCanvas = useCallback(
        (actionId: string) => {
            const anchor = findActionAnchorInTree(containers, actionId);
            if (!anchor) return;
            setNavExpandIds(new Set(anchor.expandContainerIds));
            setFocusActionId(actionId);
            window.setTimeout(() => {
                const el = document.getElementById(`procedural-action-${actionId}`);
                el?.scrollIntoView({ behavior: 'smooth', block: 'center' });
            }, 50);
            window.setTimeout(() => setFocusActionId(null), 1000);
        },
        [containers],
    );

    const focusNoteInCanvas = useCallback(
        (noteId: string) => {
            const anchor = findSubItemAnchorInTree(containers, noteId);
            if (!anchor || anchor.itemType !== 'note') return;
            setNavExpandIds(new Set(anchor.expandContainerIds));
            setFocusNoteId(noteId);
            window.setTimeout(() => {
                document.getElementById(`procedural-note-${noteId}`)?.scrollIntoView({ behavior: 'smooth', block: 'center' });
            }, 50);
            window.setTimeout(() => setFocusNoteId(null), 1000);
        },
        [containers],
    );

    const focusContainerInCanvas = useCallback(
        (containerId: string) => {
            const anchor = findContainerAnchorInTree(containers, containerId);
            if (!anchor) return;
            setNavExpandIds(new Set(anchor.expandContainerIds));
            window.setTimeout(() => {
                document.getElementById(`procedural-container-${containerId}`)?.scrollIntoView({ behavior: 'smooth', block: 'center' });
            }, 50);
        },
        [containers],
    );

    useEffect(() => {
        if (!navTarget) return;
        if (navTarget.kind === 'action') focusActionInCanvas(navTarget.id);
        else if (navTarget.kind === 'note') focusNoteInCanvas(navTarget.id);
        else focusContainerInCanvas(navTarget.id);
        onNavTargetHandled?.();
    }, [navTarget, focusActionInCanvas, focusNoteInCanvas, focusContainerInCanvas, onNavTargetHandled]);

    useEffect(() => {
        if (!searchVisibility.active) return;
        setNavExpandIds((prev) => {
            const next = new Set(prev);
            searchVisibility.expandContainerIds.forEach((id) => next.add(id));
            return next;
        });
    }, [searchVisibility.active, searchVisibility.expandContainerIds]);

    const toggleContainerFold = (containerId: string, currentlyCollapsed: boolean) => {
        updateContainer(caseId, containerId, { collapsed: !currentlyCollapsed });
        setNavExpandIds((prev) => {
            const next = new Set(prev);
            if (currentlyCollapsed) next.add(containerId);
            else next.delete(containerId);
            return next;
        });
    };

    const linkResolverInput = useMemo(
        () => ({
            timelineEvents: caseRow?.timelineEvents,
            lawyerRequests: caseRow?.lawyerRequests,
        }),
        [caseRow?.lawyerRequests, caseRow?.timelineEvents],
    );

    const proceduralContextDisplay = (
        item: ProceduralNoteItem | ProceduralActionItem,
    ): { line: string | null; link?: ProceduralItemLink; linkBroken?: boolean } => {
        const ctx = normalizeProceduralContextValue(item.link, item.contextRef, item.contextNote);
        const live =
            ctx.link != null ? resolveLiveLinkLabel(ctx.link, linkResolverInput) : undefined;
        const line = formatProceduralLinkDisplay(ctx, live);
        const linkBroken =
            ctx.link != null ? isProceduralLinkBroken(ctx.link, linkResolverInput) : false;
        return { line, link: ctx.link, linkBroken };
    };

    const phaseFilteredRoots = useMemo(() => {
        if (!hasTrialPhase || pathsPhaseFilter === 'all') return containers;
        return filterByCasePhase(containers, pathsPhaseFilter, (root) =>
            resolveProceduralRootCasePhase(root as ProceduralContainer, stageJourney),
        );
    }, [containers, hasTrialPhase, pathsPhaseFilter, stageJourney]);

    const pathStats = useMemo(() => {
        const completed = phaseFilteredRoots.filter((c) => c.pathStatus === 'completed').length;
        return {
            total: phaseFilteredRoots.length,
            active: phaseFilteredRoots.length - completed,
            completed,
        };
    }, [phaseFilteredRoots]);

    const editingContainer = useMemo(() => {
        if (containerModal?.kind !== 'edit') return null;
        const walk = (list: ProceduralContainer[]): ProceduralContainer | null => {
            for (const c of list) {
                if (c.id === containerModal.containerId) return c;
                for (const item of c.subItems) {
                    if (item.type === 'container') {
                        const hit = walk([item.container]);
                        if (hit) return hit;
                    }
                }
            }
            return null;
        };
        return walk(containers);
    }, [containerModal, containers]);

    const parseDrag = (e: React.DragEvent): DragPayload | null => {
        try {
            const raw = e.dataTransfer.getData(DRAG_MIME);
            if (!raw) return null;
            const o = JSON.parse(raw) as DragPayload;
            if (!o?.id || !o?.kind) return null;
            return o;
        } catch {
            return null;
        }
    };

    const handleRootDrop = (targetId: string) => (e: React.DragEvent) => {
        e.preventDefault();
        const drag = parseProceduralDrag(e);
        if (!drag) return;
        if (drag.kind === 'root' && drag.id !== targetId) {
            reorderRoot(caseId, drag.id, targetId);
        } else if (drag.kind === 'container') {
            moveContainer(caseId, drag.id, null, containers.findIndex((c) => c.id === targetId));
        } else if (drag.kind === 'subitem' && drag.fromParentId) {
            const hit = findContainerInTree(containers, targetId);
            const toIndex = hit?.container.subItems.length ?? 0;
            moveSubItem(caseId, drag.fromParentId, targetId, drag.id, toIndex);
        }
        setDragRootId(null);
    };

    const handleDropOnSubList = (parentId: string, toIndex: number) => (e: React.DragEvent) => {
        e.preventDefault();
        e.stopPropagation();
        const drag = parseProceduralDrag(e);
        if (!drag) return;
        if (drag.kind === 'subitem' && drag.fromParentId) {
            moveSubItem(caseId, drag.fromParentId, parentId, drag.id, toIndex);
        } else if (drag.kind === 'container') {
            moveContainer(caseId, drag.id, parentId, toIndex);
        }
    };

    const handleDropOnContainer = (parentId: string) => (e: React.DragEvent) => {
        e.preventDefault();
        e.stopPropagation();
        const drag = parseProceduralDrag(e);
        if (!drag) return;
        const hit = findContainerInTree(containers, parentId);
        const len = hit?.container.subItems.length ?? 0;
        if (drag.kind === 'container') {
            moveContainer(caseId, drag.id, parentId, len);
        } else if (drag.kind === 'subitem' && drag.fromParentId) {
            moveSubItem(caseId, drag.fromParentId, parentId, drag.id, len);
        }
    };

    const treeCtx: ProceduralTreeContext = {
        caseId,
        readOnly,
        hasTrialPhase,
        stageJourney,
        pathsPhaseFilter,
        searchVisibility,
        navExpandIds,
        dragRootId,
        setDragRootId,
        focusActionId,
        focusNoteId,
        onOpenLinkedRecord,
        proceduralContextDisplay,
        toggleContainerFold,
        handleRootDrop,
        handleDropOnContainer,
        handleDropOnSubList,
        updateContainer,
        duplicateContainer,
        duplicateSubItem,
        updateSubItem,
        deleteSubItem,
        setContainerModal,
        setConfirmDeleteId,
        setAddChildParentId,
        setNoteModal,
        setActionModal,
        setAdvanceModal,
    };


    const displayRoots = useMemo(() => {
        if (!searchVisibility.active) return phaseFilteredRoots;
        return phaseFilteredRoots.filter((c) => searchVisibility.visibleContainerIds.has(c.id));
    }, [phaseFilteredRoots, searchVisibility.active, searchVisibility.visibleContainerIds]);

    return (
        <div
            id="procedural-canvas-root"
            className="flex flex-col p-4 sm:p-6 max-w-3xl mx-auto w-full gap-4"
            dir="rtl"
        >
            <div className="space-y-2 print:hidden">
                {pathStats.total > 0 ? (
                    <div className="text-[10px] font-black text-white/50">
                        {pathStats.active} نشط · {pathStats.completed} منتهٍ · {pathStats.total} مسار
                    </div>
                ) : null}
            </div>

            {hasTrialPhase && containers.length > 0 ? (
                <CasePhaseSegmentedControl
                    value={pathsPhaseFilter}
                    onChange={setPathsPhaseFilter}
                    className="print:hidden"
                    ariaLabel="فلتر مرحلة مسارات التتبع"
                    labelOverrides={{
                        investigation: 'مسارات التحقيق',
                        trial: 'مسارات المحاكمة',
                    }}
                />
            ) : null}

            {containers.length > 0 ? (
                <div className="flex flex-col gap-2 print:hidden">
                    <input
                        type="search"
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        placeholder="بحث في المسارات والملاحظات والإجراءات…"
                        className="w-full rounded-xl border border-slate-600/55 bg-slate-950/60 px-3 py-2 text-sm text-white outline-none focus:border-sky-500/45 placeholder:text-white/35"
                    />
                    {searchVisibility.active ? (
                        <div className="text-[10px] font-bold text-sky-200/80">
                            {searchVisibility.matchedItemIds.size > 0
                                ? `${searchVisibility.matchedItemIds.size} نتيجة مطابقة`
                                : 'لا نتائج — جرّب كلمة أخرى'}
                        </div>
                    ) : null}
                </div>
            ) : null}

            {attentionBoard.total > 0 ? (
                <details
                    className="rounded-xl border border-slate-600/50 bg-slate-900/60 overflow-hidden print:hidden"
                    open={attentionOpen}
                    onToggle={(e) => setAttentionOpen(e.currentTarget.open)}
                >
                    <summary className="list-none cursor-pointer px-3 py-2.5 flex items-center justify-between gap-2 border-b border-slate-700/40 bg-slate-800/40 [&::-webkit-details-marker]:hidden">
                        <div className="text-[11px] font-black text-white/85">
                            🎯 مركز المتابعة والانتباه
                            <span className="text-white/45 font-bold ms-2">
                                ({attentionBoard.total} قيد المتابعة)
                            </span>
                        </div>
                        <span className="text-white/40 text-[10px] font-black">{attentionOpen ? '▾' : '▸'}</span>
                    </summary>
                    <div className="p-2 flex flex-col sm:flex-row gap-2">
                        <AttentionColumn
                            title={`🚨 متأخرة (${attentionBoard.overdue.length})`}
                            entries={attentionBoard.overdue}
                            tone="overdue"
                            emptyHint="—"
                            onFocus={focusActionInCanvas}
                        />
                        <AttentionColumn
                            title={`⏳ قادمة/اليوم (${attentionBoard.upcoming.length})`}
                            entries={attentionBoard.upcoming}
                            tone="upcoming"
                            emptyHint="—"
                            onFocus={focusActionInCanvas}
                        />
                        <AttentionColumn
                            title={`📌 بدون موعد (${attentionBoard.noDate.length})`}
                            entries={attentionBoard.noDate}
                            tone="neutral"
                            emptyHint="—"
                            onFocus={focusActionInCanvas}
                        />
                    </div>
                </details>
            ) : null}

            {containers.length > 0 && !readOnly ? (
                <div className="flex flex-wrap gap-2 print:hidden">
                    <button
                        type="button"
                        onClick={() => setContainerModal({ kind: 'create-root' })}
                        className="flex-1 min-w-[9rem] rounded-xl bg-[#E6C673] text-[#0B1021] py-2.5 text-sm font-black hover:brightness-110 transition"
                    >
                        + مسار جديد
                    </button>
                </div>
            ) : null}

            {containers.length === 0 ? (
                <div className="flex flex-col items-center justify-center rounded-xl border border-dashed border-slate-600/45 px-6 py-16 text-center gap-5">
                    <p className="text-white/55 text-sm font-bold max-w-xs">
                        اللوحة فارغة. ابدأ خطتك الإجرائية الآن.
                    </p>
                    {!readOnly ? (
                        <button
                            type="button"
                            onClick={() => setContainerModal({ kind: 'create-root' })}
                            className="rounded-xl bg-[#E6C673] text-[#0B1021] px-8 py-3 text-sm font-black hover:brightness-110 transition shadow-lg shadow-[#E6C673]/15"
                        >
                            ➕ مسار جديد
                        </button>
                    ) : null}
                </div>
            ) : displayRoots.length === 0 && searchVisibility.active ? (
                <div className="rounded-xl border border-dashed border-slate-600/45 px-6 py-10 text-center text-white/45 text-sm font-bold">
                    لا مسارات تطابق البحث.
                </div>
            ) : displayRoots.length === 0 && pathsPhaseFilter !== 'all' ? (
                <div className="rounded-xl border border-dashed border-slate-600/45 px-6 py-10 text-center text-white/45 text-sm font-bold">
                    لا مسارات في{' '}
                    {pathsPhaseFilter === 'investigation' ? 'مرحلة التحقيق' : 'مرحلة المحاكمة'}.
                </div>
            ) : (
                <div className="flex flex-col gap-8 procedural-print-target">
                    {displayRoots.map((c, mapIdx) => {
                        const rootIdx = containers.indexOf(c);
                        const showDivider = mapIdx > 0;
                        return (
                        <div
                            key={c.id}
                            className={showDivider ? 'pt-6 border-t border-dashed border-slate-600/40' : ''}
                        >
                            {<ProceduralContainerTreeNode
                                ctx={treeCtx}
                                container={c}
                                depth={0}
                                isRoot={true}
                                pathLocked={false}
                                parentNumber={[rootIdx + 1]}
                            />}
                        </div>
                        );
                    })}
                </div>
            )}

            <ProceduralContainerFormModal
                open={containerModal !== null}
                title={
                    containerModal?.kind === 'edit'
                        ? 'تعديل'
                        : containerModal?.kind === 'create-nested'
                          ? containerModal.branchRole === 'primary'
                              ? 'مسار أساسي داخل المسار'
                              : 'مسار فرعي'
                          : 'مسار جديد'
                }
                initial={
                    containerModal?.kind === 'edit' && editingContainer
                        ? {
                              title: editingContainer.title,
                              color: editingContainer.color,
                              icon: editingContainer.icon,
                          }
                        : containerModal?.kind === 'create-nested'
                          ? {
                                title: '',
                                color: CONTAINER_COLOR_PRESETS[containerModal.branchRole === 'primary' ? 0 : 1],
                                icon: containerModal.branchRole === 'primary' ? '🛤️' : '📁',
                            }
                          : undefined
                }
                onClose={() => setContainerModal(null)}
                onSubmit={(payload) => {
                    if (containerModal?.kind === 'create-root') {
                        addRoot(caseId, payload);
                    } else if (containerModal?.kind === 'create-nested') {
                        const branchRole = containerModal.branchRole;
                        addSubItem(caseId, containerModal.parentId, {
                            type: 'container',
                            container: {
                                id: createProceduralId(),
                                title: payload.title,
                                color: payload.color,
                                icon: payload.icon,
                                parentId: containerModal.parentId,
                                branchRole,
                                subItems: [],
                            },
                        });
                    } else if (containerModal?.kind === 'edit') {
                        updateContainer(caseId, containerModal.containerId, payload);
                    }
                    setContainerModal(null);
                }}
            />

            <ProceduralAddChildModal
                open={addChildParentId !== null}
                onClose={() => setAddChildParentId(null)}
                onPick={(kind: AddChildKind) => {
                    const parentId = addChildParentId;
                    if (!parentId) return;
                    setAddChildParentId(null);
                    if (kind === 'note') setNoteModal({ parentId });
                    else if (kind === 'action') setActionModal({ parentId });
                }}
            />

            <ProceduralNoteFormModal
                caseId={caseId}
                open={noteModal !== null}
                placement={notePlacement}
                initial={noteModal?.note ?? null}
                onClose={() => setNoteModal(null)}
                onSubmit={(payload) => {
                    if (!noteModal) return;
                    if (noteModal.note?.id) {
                        updateSubItem(caseId, noteModal.parentId, noteModal.note.id, payload);
                    } else {
                        addSubItem(caseId, noteModal.parentId, {
                            type: 'note',
                            id: createProceduralId(),
                            title: payload.title,
                            body: payload.body,
                            link: payload.link,
                            contextNote: payload.contextNote,
                            tags: payload.tags,
                            isStarred: payload.isStarred,
                        });
                    }
                    setNoteModal(null);
                }}
            />

            <ProceduralActionFormModal
                caseId={caseId}
                open={actionModal !== null}
                placement={actionPlacement}
                initial={actionModal?.action ?? null}
                onClose={() => setActionModal(null)}
                onSubmit={(payload) => {
                    if (!actionModal) return;
                    if (actionModal.action?.id) {
                        updateSubItem(caseId, actionModal.parentId, actionModal.action.id, payload);
                    } else {
                        addSubItem(caseId, actionModal.parentId, {
                            type: 'action',
                            id: createProceduralId(),
                            title: payload.title,
                            date: payload.date,
                            status: payload.status,
                            followUpDate: payload.followUpDate,
                            tags: payload.tags,
                            isStarred: payload.isStarred,
                            link: payload.link,
                            contextNote: payload.contextNote,
                        });
                    }
                    setActionModal(null);
                }}
            />

            <ProceduralAdvancePhaseModal
                open={advanceModal !== null}
                actionTitle={advanceModal?.actionTitle ?? ''}
                onClose={() => setAdvanceModal(null)}
                onSubmit={(payload) => {
                    if (!advanceModal) return;
                    advanceAction(caseId, advanceModal.parentId, advanceModal.actionId, {
                        spawnChildTitle: payload.spawnChildTitle,
                    });
                    setAdvanceModal(null);
                }}
            />

            {confirmDeleteId ? (
                <CriminalModalPortal zIndex={CRIMINAL_MODAL_Z.proceduralConfirm}>
                    <div className="w-full max-w-sm rounded-2xl border border-slate-700 bg-slate-900 p-4 space-y-3">
                        <div className="text-white font-black text-sm">نقل مسار التتبع للسلة؟</div>
                        <p className="text-white/70 text-xs font-bold">
                            سيتم إخفاء المسار بكل مراحله وإجراءاته — يمكن استرجاعه من سلة المهملات.
                        </p>
                        <div className="flex justify-end gap-2">
                            <button
                                type="button"
                                onClick={() => setConfirmDeleteId(null)}
                                className="rounded-xl border border-slate-700 px-4 py-2 text-sm font-black text-white/75"
                            >
                                إلغاء
                            </button>
                            <button
                                type="button"
                                onClick={() => {
                                    deleteContainer(caseId, confirmDeleteId);
                                    setConfirmDeleteId(null);
                                }}
                                className="rounded-xl bg-red-600/80 px-4 py-2 text-sm font-black text-white"
                            >
                                نقل للسلة
                            </button>
                        </div>
                    </div>
                </CriminalModalPortal>
            ) : null}
        </div>
    );
};

import React, { useMemo, useState } from 'react';
import type { CaseStage } from '@/app/types/criminal';
import {
    formatPenaltyDisplay,
    resolvePenaltiesSupplementary,
    resolveStageFinalDecisionActions,
    resolveStageFinalDecisionBadge,
    stageFinalDecisionKindLabel,
    type StageFinalDecisionBadgeTone,
    type StageFinalDecisionUserRole,
} from '../stageFinalDecisionEngine';
import {
    verdictCardShellClass,
    verdictOutcomeLabel,
    type VerdictCard,
    type VerdictCorrectionAppealTrack,
    type VerdictOrdinaryAppealTrack,
} from '../verdictCardsEngine';
import { ModalIsoDate } from './ModalIsoDate';
import { ModalIsoDateInput } from './ModalIsoDateInput';
import {
    VerdictCassationCorrectionModal,
    VerdictCassationResultModal,
} from './VerdictCassationModals';
import type { VerdictCassationResultSaveInput } from '../verdictCassationResultEngine';

export type StageFinalDecisionCardProps = {
    card: VerdictCard;
    caseStage: CaseStage;
    defendantName?: string;
    currentAccusationArticle?: string;
    crimeType?: string;
    readOnly?: boolean;
    userRole?: StageFinalDecisionUserRole;
    onUpdateDraft: (draft: string) => void;
    onSaveOrdinaryAppeal: (patch: Partial<VerdictOrdinaryAppealTrack>) => void;
    onSaveVerdictCassationResult: (input: VerdictCassationResultSaveInput) => string | null | void;
    onSaveCorrectionAppeal: (patch: Partial<VerdictCorrectionAppealTrack>) => void;
    onRecordAbsentiaPublication: (publicationDate: string) => void;
    onRecordAbsentiaObjection: () => void;
    /** يفتح مودال تسجيل الطعن الموحّد في VerdictCardsPanel. */
    onOpenCassationFiling?: () => void;
};

const badgeClassForTone = (tone: StageFinalDecisionBadgeTone): string => {
    if (tone === 'final_green') return 'border-emerald-500/40 bg-emerald-950/30 text-emerald-100';
    if (tone === 'countdown_orange') return 'border-amber-500/45 bg-amber-950/25 text-amber-100';
    if (tone === 'absentee_gray') return 'border-slate-500/40 bg-slate-800/50 text-slate-200';
    if (tone === 'absentee_objection') return 'border-sky-500/40 bg-sky-950/25 text-sky-100';
    if (tone === 'cassation_review') return 'border-sky-500/50 bg-sky-950/35 text-sky-100';
    if (tone === 'cassation_result') return 'border-violet-500/40 bg-violet-950/30 text-violet-100';
    return 'border-white/15 bg-white/5 text-white/80';
};

export const StageFinalDecisionCard = ({
    card,
    caseStage,
    defendantName,
    currentAccusationArticle,
    crimeType,
    readOnly,
    userRole,
    onUpdateDraft,
    onSaveOrdinaryAppeal,
    onSaveVerdictCassationResult,
    onSaveCorrectionAppeal,
    onRecordAbsentiaPublication,
    onRecordAbsentiaObjection,
    onOpenCassationFiling,
}: StageFinalDecisionCardProps) => {
    const [draftValue, setDraftValue] = useState(card.decisionDraft ?? '');
    const [showDraftSection, setShowDraftSection] = useState(() =>
        Boolean(String(card.decisionDraft ?? '').trim()),
    );
    const [pubDateDraft, setPubDateDraft] = useState('');
    const [showPubForm, setShowPubForm] = useState(false);
    const [resultModalOpen, setResultModalOpen] = useState(false);
    const [correctionModalOpen, setCorrectionModalOpen] = useState(false);

    const badge = useMemo(() => resolveStageFinalDecisionBadge(card), [card]);
    const actions = useMemo(
        () => resolveStageFinalDecisionActions(card, { readOnly, userRole, caseStage }),
        [card, readOnly, userRole, caseStage],
    );
    const penaltyLine = formatPenaltyDisplay(card.penalty);
    const supplementaryLine = resolvePenaltiesSupplementary(card.penalty);
    const kindLabel =
        card.decisionProcedurePath === 'summary'
            ? 'أمر جزائي / عقوبة موجزة'
            : stageFinalDecisionKindLabel(card.finalDecisionKind);
    const bindingDirections = String(card.ordinaryAppeal?.bindingDirections ?? '').trim();

    const showStatusBadge = badge.tone !== 'countdown_orange';

    return (
        <>
            <div className={`flex-1 rounded-xl border p-3.5 ${verdictCardShellClass(card.outcome)}`}>
                <div className="flex items-start justify-between gap-2 min-w-0">
                <div className="space-y-2 min-w-0 flex-1">
                    {defendantName ? (
                        <div className="text-[#E6C673]/90 text-xs font-black whitespace-normal break-words">
                            المتهم: {defendantName}
                        </div>
                    ) : null}
                    <div className="text-white font-black text-sm whitespace-normal break-words">
                        {verdictOutcomeLabel(card.outcome)}
                        {kindLabel !== '—' ? (
                            <span className="text-white/50 font-bold text-xs mr-2">· {kindLabel}</span>
                        ) : null}
                    </div>
                    <div className="text-white/65 text-xs font-bold">
                        تاريخ الحكم:{' '}
                        <span dir="ltr" className="unicode-bidi-plaintext tabular-nums text-white/80">
                            <ModalIsoDate value={card.issuedAt} />
                        </span>
                        {card.presenceType ? (
                            <span className="mr-2"> · {card.presenceType === 'غيابي' ? 'غيابي' : 'وجاهي'}</span>
                        ) : null}
                    </div>
                    {penaltyLine ? (
                        <div className="text-[#E6C673]/85 text-xs font-bold whitespace-normal break-words">
                            المحكومية: {penaltyLine}
                        </div>
                    ) : null}
                    {supplementaryLine ? (
                        <div className="text-white/70 text-xs font-bold whitespace-normal break-words">
                            عقوبات تبعية وتكميلية: {supplementaryLine}
                        </div>
                    ) : null}
                </div>
                {!readOnly && !showDraftSection ? (
                    <button
                        type="button"
                        className="shrink-0 rounded-xl border border-white/12 bg-white/[0.04] px-3 py-2 text-[11px] font-black text-white/75 hover:bg-white/[0.07] hover:text-white transition"
                        onClick={() => setShowDraftSection(true)}
                    >
                        إضافة فحوى القرار
                    </button>
                ) : null}
                </div>

                {showStatusBadge ? (
                    <span
                        className={`mt-2 inline-flex rounded-lg border px-2.5 py-1 text-[10px] font-black whitespace-normal break-words ${badgeClassForTone(badge.tone)}`}
                    >
                        {badge.label}
                    </span>
                ) : null}

                {bindingDirections ? (
                    <div className="mt-2 rounded-lg border border-violet-500/30 bg-violet-950/20 px-2.5 py-2 text-[11px] font-bold text-violet-100/90 whitespace-normal break-words">
                        توجيهات محكمة التمييز الملزمة: {bindingDirections}
                    </div>
                ) : null}

                {!readOnly ? (
                    <div className="mt-3 flex flex-wrap items-center justify-end gap-2">
                        {actions.showAbsentiaPublication ? (
                            showPubForm ? (
                                <div className="w-full flex flex-wrap items-end gap-2 rounded-xl border border-white/10 bg-black/20 p-2">
                                    <div className="flex-1 min-w-[10rem]">
                                        <label className="block text-white/60 text-[10px] mb-1">تاريخ التبليغ بالنشر</label>
                                        <ModalIsoDateInput value={pubDateDraft} onChange={setPubDateDraft} />
                                    </div>
                                    <button
                                        type="button"
                                        className="rounded-lg px-3 py-2 text-xs font-black bg-sky-500/15 border border-sky-400/35 text-sky-100"
                                        onClick={() => {
                                            const d = pubDateDraft.trim();
                                            if (!d) return;
                                            onRecordAbsentiaPublication(d);
                                            setShowPubForm(false);
                                            setPubDateDraft('');
                                        }}
                                    >
                                        📅 حفظ التبليغ
                                    </button>
                                    <button
                                        type="button"
                                        className="rounded-lg px-3 py-1.5 text-xs font-bold text-white/60"
                                        onClick={() => setShowPubForm(false)}
                                    >
                                        إلغاء
                                    </button>
                                </div>
                            ) : (
                                <button
                                    type="button"
                                    className="rounded-xl border border-slate-400/35 bg-slate-800/40 px-3 py-2 text-xs font-black text-slate-100"
                                    onClick={() => setShowPubForm(true)}
                                >
                                    📅 تسجيل تاريخ التبليغ بالنشر
                                </button>
                            )
                        ) : null}

                        {actions.showAbsentiaObjection ? (
                            <button
                                type="button"
                                className="rounded-xl border border-sky-400/35 bg-sky-500/12 px-3 py-2 text-xs font-black text-sky-100"
                                onClick={onRecordAbsentiaObjection}
                            >
                                تسجيل اعتراض غيابي
                            </button>
                        ) : null}

                        {actions.showCassationAppeal ? (
                            <button
                                type="button"
                                className="rounded-xl border-2 border-[#E6C673]/55 bg-[#E6C673]/12 px-3 py-2 text-xs font-black text-[#E6C673]"
                                onClick={() => onOpenCassationFiling?.()}
                            >
                                تسجيل طعن تمييزي
                            </button>
                        ) : null}

                        {actions.showComplainantCassation ? (
                            <button
                                type="button"
                                className="rounded-xl border border-violet-400/35 bg-violet-500/12 px-3 py-2 text-xs font-black text-violet-100"
                                onClick={() => onOpenCassationFiling?.()}
                            >
                                تسجيل طعن تمييزي (مشتكي/ادعاء)
                            </button>
                        ) : null}

                        {actions.showRecordCassationResult ? (
                            <button
                                type="button"
                                className="rounded-xl border-2 border-sky-400/55 bg-sky-500/15 px-3 py-2 text-xs font-black text-sky-100"
                                onClick={() => setResultModalOpen(true)}
                            >
                                ⚖️ تسجيل قرار التمييز الوارد
                            </button>
                        ) : null}

                        {actions.showCassationCorrection ? (
                            <button
                                type="button"
                                className="rounded-xl border border-amber-500/50 bg-amber-500/10 px-3 py-2 text-xs font-black text-amber-100"
                                onClick={() => setCorrectionModalOpen(true)}
                            >
                                طلب تصحيح القرار التمييزي
                            </button>
                        ) : null}
                    </div>
                ) : null}

                {showDraftSection ? (
                    <div className="mt-3 space-y-2">
                        <label className="block text-white/60 text-xs font-bold whitespace-normal break-words">
                            فحوى القرار
                        </label>
                        <textarea
                            className="w-full min-h-[88px] bg-slate-950/80 border border-slate-700 rounded-xl px-3 py-2 text-sm text-white outline-none focus:border-[#E6C673]/45 resize-y"
                            value={draftValue}
                            disabled={readOnly}
                            placeholder="نص اختياري لفحوى القرار أو ملاحظات التوثيق..."
                            onChange={(e) => setDraftValue(e.target.value)}
                            onBlur={() => {
                                if (draftValue !== (card.decisionDraft ?? '')) onUpdateDraft(draftValue);
                            }}
                        />
                        {!readOnly ? (
                            <button
                                type="button"
                                className="text-[10px] font-bold text-white/45 hover:text-white/70 transition"
                                onClick={() => {
                                    if (draftValue !== (card.decisionDraft ?? '')) onUpdateDraft(draftValue);
                                    setShowDraftSection(false);
                                }}
                            >
                                إخفاء
                            </button>
                        ) : null}
                    </div>
                ) : null}
            </div>

            <VerdictCassationResultModal
                open={resultModalOpen}
                card={resultModalOpen ? card : null}
                readOnly={readOnly}
                crimeType={crimeType}
                onClose={() => setResultModalOpen(false)}
                onSave={onSaveVerdictCassationResult}
            />
            <VerdictCassationCorrectionModal
                open={correctionModalOpen}
                card={correctionModalOpen ? card : null}
                readOnly={readOnly}
                onClose={() => setCorrectionModalOpen(false)}
                onSave={onSaveCorrectionAppeal}
            />
        </>
    );
};

import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import type { Statement } from '../criminalStore';
import type {
    TrialDeposition,
    TrialDepositionComparison,
    TrialDepositionCrossExam,
    UpdateTrialDepositionPatch,
} from '../trialDepositionsEngine';
import { createTrialDepositionId } from '../trialDepositionsEngine';
import {
    buildLinkableStatementEntries,
    linkedEntryContent,
    linkedEntryDate,
    linkedEntryGiverType,
    linkedEntryHighlights,
    linkedEntryPersonName,
    phaseLabelForEntry,
    resolveComparisonLinkedEntry,
    resolveComparisonTrialExcerpt,
    type LinkableStatementEntry,
} from '../statementLinking';
import {
    statementGiverRoleLabel,
    statementGiverRoleStyle,
    trialDepositionCardShellClass,
} from '../statementGiverDisplay';
import { StatementHighlightedContent } from './StatementHighlightedContent';

export type TrialDepositionWitnessCardProps = {
    deposition: TrialDeposition;
    investigationStatements?: Statement[];
    trialStatements?: Statement[];
    allTrialDepositions?: TrialDeposition[];
    readOnly?: boolean;
    onUpdate: (patch: UpdateTrialDepositionPatch) => void;
    onEdit?: () => void;
    onDelete?: () => void;
};

type FloatBtnState = {
    top: number;
    left: number;
    text: string;
};

type LinkPickerState = {
    trialExcerpt?: string;
};

function StatementReplica({
    phase,
    personName,
    date,
    roleLabel,
    roleStyle,
    content,
    highlights,
    compact,
    isInvestigation,
}: {
    phase: string;
    personName: string;
    date: string;
    roleLabel: string;
    roleStyle: string;
    content: string;
    highlights?: Statement['contentHighlights'];
    compact?: boolean;
    isInvestigation: boolean;
}) {
    return (
        <StatementReplicaShell isInvestigation={isInvestigation}>
            <div className="flex flex-wrap items-center gap-2">
                <span
                    className={`inline-flex rounded-md border px-2 py-0.5 text-[10px] font-black ${
                        isInvestigation
                            ? 'border-slate-600/50 bg-slate-800/80 text-white/65'
                            : 'border-[#E6C673]/40 bg-[#E6C673]/10 text-[#E6C673]'
                    }`}
                >
                    [{phase}]
                </span>
                <span className="text-white/90 text-xs font-black whitespace-normal break-words">{personName}</span>
                <span className="text-white/45 text-[10px] font-bold" dir="ltr">
                    {date}
                </span>
                <span
                    className={`rounded-full border px-2 py-0.5 text-[10px] font-black whitespace-normal break-words ${roleStyle}`}
                >
                    {roleLabel}
                </span>
            </div>
            <div
                className={`text-white/85 whitespace-pre-wrap break-words leading-relaxed ${
                    compact ? 'text-xs line-clamp-4' : 'text-sm'
                }`}
            >
                {highlights?.length ? (
                    <StatementHighlightedContent content={content} highlights={highlights} />
                ) : (
                    content
                )}
            </div>
        </StatementReplicaShell>
    );
}

function StatementReplicaShell({
    isInvestigation,
    children,
}: {
    isInvestigation: boolean;
    children: React.ReactNode;
}) {
    return (
        <div
            className={`rounded-xl border p-3 space-y-2 ${
                isInvestigation
                    ? 'border-slate-700/60 bg-slate-900/50'
                    : 'border-[#E6C673]/35 bg-[#E6C673]/5'
            }`}
        >
            {children}
        </div>
    );
}

function LinkedStatementReplica({
    entry,
    compact,
}: {
    entry: LinkableStatementEntry;
    compact?: boolean;
}) {
    const giverType = linkedEntryGiverType(entry);
    return (
        <StatementReplica
            phase={phaseLabelForEntry(entry)}
            personName={linkedEntryPersonName(entry)}
            date={linkedEntryDate(entry)}
            roleLabel={statementGiverRoleLabel(giverType)}
            roleStyle={statementGiverRoleStyle(giverType)}
            content={linkedEntryContent(entry)}
            highlights={linkedEntryHighlights(entry)}
            compact={compact}
            isInvestigation={entry.phase === 'investigation'}
        />
    );
}

function CurrentDepositionColumn({
    deposition,
    excerpt,
}: {
    deposition: TrialDeposition;
    excerpt: string;
}) {
    const giverType = deposition.giverType ?? 'witness';
    const showHighlights = excerpt === deposition.content;
    return (
        <StatementReplica
            phase="محكمة الموضوع — الإفادة الحالية"
            personName={deposition.witnessName}
            date={deposition.date}
            roleLabel={statementGiverRoleLabel(giverType)}
            roleStyle={statementGiverRoleStyle(giverType)}
            content={excerpt}
            highlights={showHighlights ? deposition.contentHighlights : undefined}
            isInvestigation={false}
        />
    );
}

function SavedComparisonBlock({
    deposition,
    row,
    linkableEntries,
    readOnly,
    onRemove,
}: {
    deposition: TrialDeposition;
    row: TrialDepositionComparison;
    linkableEntries: LinkableStatementEntry[];
    readOnly?: boolean;
    onRemove: () => void;
}) {
    const linked = resolveComparisonLinkedEntry(row, linkableEntries);
    const trialSide = resolveComparisonTrialExcerpt(deposition, row);

    return (
        <div className="rounded-xl border border-orange-500/40 bg-slate-950/50 p-3 space-y-2">
            <div className="flex flex-wrap items-center gap-2">
                <span className="text-orange-200/90 text-[11px] font-black">⚖️ مقارنة مربوطة — المادة 178</span>
                {!readOnly ? (
                    <button
                        type="button"
                        onClick={onRemove}
                        className="mr-auto rounded-md border border-red-500/35 px-2 py-0.5 text-[10px] font-black text-red-300/80 hover:bg-red-950/30"
                    >
                        إلغاء الربط
                    </button>
                ) : null}
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                <CurrentDepositionColumn deposition={deposition} excerpt={trialSide} />
                {linked ? (
                    <LinkedStatementReplica entry={linked} />
                ) : row.investigationText ? (
                    <StatementReplica
                        phase="التحقيق — أرشيف قديم"
                        personName="—"
                        date="—"
                        roleLabel="—"
                        roleStyle="border-slate-600/50 text-white/55"
                        content={row.investigationText}
                        isInvestigation
                    />
                ) : (
                    <MissingLinkNotice />
                )}
            </div>
        </div>
    );
}

function MissingLinkNotice() {
    return (
        <div className="rounded-xl border border-red-500/30 bg-red-950/20 p-3 text-red-200/80 text-xs font-bold">
            الإفادة المربوطة غير موجودة (حُذفت أو نُقلت)
        </div>
    );
}

function CardHeaderNameRow({
    giverType,
    witnessName,
    date,
    roleLabel,
    roleStyle,
}: {
    giverType: string;
    witnessName: string;
    date: string;
    roleLabel: string;
    roleStyle: string;
}) {
    return (
        <>
            <div className="flex flex-wrap items-center gap-2">
                <span
                    className={
                        giverType === 'witness'
                            ? 'text-violet-200 font-black text-base whitespace-normal break-words'
                            : 'text-white font-black text-sm whitespace-normal break-words'
                    }
                >
                    {witnessName}
                </span>
                <span className="text-white/45 text-xs font-bold" dir="ltr">
                    {date}
                </span>
            </div>
            <div className="flex flex-wrap items-center gap-2">
                <span
                    className={`rounded-full border px-2.5 py-1 text-[11px] font-black whitespace-normal break-words ${roleStyle}`}
                >
                    {roleLabel}
                </span>
                <span className="rounded-full border border-[#E6C673]/35 bg-[#E6C673]/10 px-2.5 py-1 text-[10px] font-black text-[#E6C673]/90">
                    محكمة الموضوع
                </span>
            </div>
        </>
    );
}

export const TrialDepositionWitnessCard = ({
    deposition,
    investigationStatements = [],
    trialStatements = [],
    allTrialDepositions = [],
    readOnly,
    onUpdate,
    onEdit,
    onDelete,
}: TrialDepositionWitnessCardProps) => {
    const contentRef = useRef<HTMLDivElement>(null);
    const [floatBtn, setFloatBtn] = useState<FloatBtnState | null>(null);
    const [linkPicker, setLinkPicker] = useState<LinkPickerState | null>(null);
    const [newQuestion, setNewQuestion] = useState('');
    const [crossOpen, setCrossOpen] = useState(true);

    const comparisons = deposition.comparisons ?? [];
    const crossExam = deposition.crossExamination ?? [];
    const giverType = deposition.giverType ?? 'witness';
    const roleLabel = statementGiverRoleLabel(giverType);
    const roleStyle = statementGiverRoleStyle(giverType);

    const linkableEntries = useMemo(
        () =>
            buildLinkableStatementEntries({
                investigationStatements,
                trialStatements,
                trialDepositions: allTrialDepositions,
                excludeDepositionId: deposition.id,
            }),
        [allTrialDepositions, deposition.id, investigationStatements, trialStatements],
    );

    const linkedIds = useMemo(
        () =>
            new Set(
                comparisons
                    .filter((c) => c.linkedKind && c.linkedId)
                    .map((c) => `${c.linkedKind}:${c.linkedId}`),
            ),
        [comparisons],
    );

    const dismissFloat = useCallback(() => setFloatBtn(null), []);

    useEffect(() => {
        if (readOnly) return;
        const onDocMouseDown = (e: MouseEvent) => {
            const target = e.target as Node | null;
            if (!floatBtn || !target) return;
            const btn = document.getElementById(`td-compare-float-${deposition.id}`);
            if (btn?.contains(target)) return;
            if (contentRef.current?.contains(target)) return;
            dismissFloat();
        };
        document.addEventListener('mousedown', onDocMouseDown);
        return () => document.removeEventListener('mousedown', onDocMouseDown);
    }, [deposition.id, dismissFloat, floatBtn, readOnly]);

    const handleContentMouseUp = () => {
        if (readOnly) return;
        const sel = window.getSelection();
        if (!sel || sel.isCollapsed || !contentRef.current) {
            setFloatBtn(null);
            return;
        }
        const anchor = sel.anchorNode;
        const focus = sel.focusNode;
        if (
            !anchor ||
            !focus ||
            !contentRef.current.contains(anchor) ||
            !contentRef.current.contains(focus)
        ) {
            setFloatBtn(null);
            return;
        }
        const text = sel.toString().trim();
        if (!text) {
            setFloatBtn(null);
            return;
        }
        const range = sel.getRangeAt(0);
        const rect = range.getBoundingClientRect();
        setFloatBtn({
            top: Math.max(8, rect.top - 40),
            left: rect.left + rect.width / 2,
            text,
        });
    };

    const openLinkPicker = (trialExcerpt?: string) => {
        setLinkPicker({ trialExcerpt: trialExcerpt?.trim() || undefined });
        setFloatBtn(null);
        window.getSelection()?.removeAllRanges();
    };

    const saveLink = (entry: LinkableStatementEntry) => {
        const linkedKind = entry.kind === 'statement' ? 'statement' : 'trial_deposition';
        const linkedId = entry.record.id;
        const key = `${linkedKind}:${linkedId}`;
        if (linkedIds.has(key) && !linkPicker?.trialExcerpt) {
            setLinkPicker(null);
            return;
        }
        const next: TrialDepositionComparison = {
            id: createTrialDepositionId(),
            trialExcerpt: linkPicker?.trialExcerpt,
            linkedKind,
            linkedId,
        };
        onUpdate({ comparisons: [...comparisons, next] });
        setLinkPicker(null);
    };

    const removeComparison = (comparisonId: string) => {
        onUpdate({ comparisons: comparisons.filter((c) => c.id !== comparisonId) });
    };

    const patchCrossExam = (questionId: string, patch: Partial<TrialDepositionCrossExam>) => {
        const next = crossExam.map((q) => (q.id === questionId ? { ...q, ...patch } : q));
        onUpdate({ crossExamination: next });
    };

    const addCrossQuestion = () => {
        const q = newQuestion.trim();
        if (!q) return;
        onUpdate({
            crossExamination: [
                ...crossExam,
                { id: createTrialDepositionId(), question: q, isAsked: false },
            ],
        });
        setNewQuestion('');
    };

    const removeCrossQuestion = (questionId: string) => {
        onUpdate({ crossExamination: crossExam.filter((q) => q.id !== questionId) });
    };

    const pickerEntries = useMemo(() => {
        const name = deposition.witnessName.trim().toLowerCase();
        const same = name
            ? linkableEntries.filter((e) => linkedEntryPersonName(e).toLowerCase() === name)
            : [];
        const sameIds = new Set(same.map((e) => `${e.kind}:${e.record.id}`));
        const rest = linkableEntries.filter((e) => !sameIds.has(`${e.kind}:${e.record.id}`));
        return [...same, ...rest];
    }, [deposition.witnessName, linkableEntries]);

    const showCrossExam = giverType === 'witness' || giverType === 'defendant';
    const crossExamTitle =
        giverType === 'defendant' ? '🎯 استجواب المشكو منه' : '🎯 خطة استجواب ومناقشة الشاهد';
    const liveResponsePlaceholder =
        giverType === 'defendant' ? 'الإجابة الحية للمشكو منه...' : 'الإجابة الحية للشاهد...';

    return (
        <div className={trialDepositionCardShellClass(giverType)}>
            <div className="flex flex-wrap items-start justify-between gap-2">
                <div className="space-y-1 min-w-0 flex-1">
                    <CardHeaderNameRow
                        giverType={giverType}
                        witnessName={deposition.witnessName}
                        date={deposition.date}
                        roleLabel={roleLabel}
                        roleStyle={roleStyle}
                    />
                </div>
                {!readOnly ? (
                    <div className="flex flex-wrap gap-2 shrink-0">
                        {onEdit ? (
                            <button
                                type="button"
                                onClick={onEdit}
                                className="rounded-lg border border-slate-600/60 px-2.5 py-1 text-[10px] font-black text-white/70 hover:text-[#E6C673]"
                            >
                                تعديل
                            </button>
                        ) : null}
                        {onDelete ? (
                            <button
                                type="button"
                                onClick={onDelete}
                                className="rounded-lg border border-red-500/35 px-2.5 py-1 text-[10px] font-black text-red-300/80 hover:bg-red-950/30"
                            >
                                حذف
                            </button>
                        ) : null}
                    </div>
                ) : null}
            </div>

            {giverType === 'witness' && deposition.witnessDetails?.trim() ? (
                <div className="text-violet-200/90 text-xs font-bold whitespace-normal break-words">
                    {deposition.witnessDetails.trim()}
                </div>
            ) : null}

            <div className="relative">
                <div
                    ref={contentRef}
                    role="presentation"
                    onMouseUp={handleContentMouseUp}
                    className="rounded-xl border border-slate-700/70 bg-slate-950/50 p-3 text-sm text-white/90 whitespace-pre-wrap break-words leading-relaxed select-text cursor-text"
                >
                    <StatementHighlightedContent
                        content={deposition.content}
                        highlights={deposition.contentHighlights}
                    />
                </div>

                {floatBtn && !readOnly ? (
                    <button
                        id={`td-compare-float-${deposition.id}`}
                        type="button"
                        onMouseDown={(e) => e.preventDefault()}
                        onClick={() => openLinkPicker(floatBtn.text)}
                        style={{
                            position: 'fixed',
                            top: floatBtn.top,
                            left: floatBtn.left,
                            transform: 'translateX(-50%)',
                            zIndex: 240,
                        }}
                        className="rounded-full border border-orange-500/50 bg-orange-950/90 px-3 py-1.5 text-[10px] font-black text-orange-100 shadow-lg shadow-black/40 hover:bg-orange-900/90 transition whitespace-nowrap"
                    >
                        🔗 ربط مقطع بإفادة
                    </button>
                ) : null}
            </div>

            {!readOnly && linkableEntries.length > 0 ? (
                <div className="flex justify-end">
                    <button
                        type="button"
                        onClick={() => openLinkPicker()}
                        className="rounded-lg border border-orange-500/45 bg-orange-950/30 px-3 py-1.5 text-[10px] font-black text-orange-100 hover:bg-orange-900/40 transition"
                    >
                        🔗 ربط إفادة
                    </button>
                </div>
            ) : null}

            {linkPicker && !readOnly ? (
                <div className="rounded-xl border border-orange-500/45 bg-slate-950/60 p-3 space-y-3">
                    <div className="text-orange-200/90 text-[11px] font-black">
                        {linkPicker.trialExcerpt
                            ? 'اختر الإفادة المراد ربط المقطع بها'
                            : 'اختر إفادة موجودة للمقارنة'}
                    </div>
                    {linkPicker.trialExcerpt ? (
                        <div className="rounded-lg border border-[#E6C673]/35 bg-[#E6C673]/5 px-3 py-2 text-xs text-white/85 whitespace-pre-wrap break-words">
                            <span className="text-[#E6C673]/90 font-black text-[10px] block mb-1">المقطع المحدّد:</span>
                            {linkPicker.trialExcerpt}
                        </div>
                    ) : null}
                    {pickerEntries.length === 0 ? (
                        <p className="text-white/40 text-[10px] font-bold">لا توجد إفادات أخرى مسجّلة للربط.</p>
                    ) : (
                        <div className="space-y-2 max-h-[320px] overflow-y-auto overscroll-contain">
                            {pickerEntries.map((entry) => {
                                const key = `${entry.kind}:${entry.record.id}`;
                                const alreadyLinked = linkedIds.has(key) && !linkPicker.trialExcerpt;
                                return (
                                    <div
                                        key={key}
                                        className="rounded-xl border border-slate-700/55 bg-slate-900/45 p-3 space-y-2"
                                    >
                                        <LinkedStatementReplica entry={entry} compact />
                                        <button
                                            type="button"
                                            disabled={alreadyLinked}
                                            onClick={() => saveLink(entry)}
                                            className="rounded-md border border-orange-500/40 px-2.5 py-1 text-[10px] font-black text-orange-100 hover:bg-orange-950/30 transition disabled:opacity-40 disabled:pointer-events-none"
                                        >
                                            {alreadyLinked ? 'مربوطة مسبقاً' : '🔗 ربط للمقارنة'}
                                        </button>
                                    </div>
                                );
                            })}
                        </div>
                    )}
                    <div className="flex justify-end">
                        <button
                            type="button"
                            onClick={() => setLinkPicker(null)}
                            className="rounded-lg border border-slate-600/60 px-3 py-1.5 text-[10px] font-black text-white/60"
                        >
                            إلغاء
                        </button>
                    </div>
                </div>
            ) : null}

            {comparisons.length > 0 ? (
                <div className="space-y-3">
                    {comparisons.map((row) => (
                        <SavedComparisonBlock
                            key={row.id}
                            deposition={deposition}
                            row={row}
                            linkableEntries={linkableEntries}
                            readOnly={readOnly}
                            onRemove={() => removeComparison(row.id)}
                        />
                    ))}
                </div>
            ) : null}

            {showCrossExam ? (
            <details
                open={crossOpen}
                onToggle={(e) => setCrossOpen(e.currentTarget.open)}
                className="rounded-xl border border-slate-700/60 bg-slate-900/35 overflow-hidden"
            >
                <summary className="list-none cursor-pointer px-4 py-3 flex items-center justify-between gap-2 bg-slate-800/45 border-b border-slate-700/40 [&::-webkit-details-marker]:hidden">
                    <span className="text-white font-black text-sm">{crossExamTitle}</span>
                    <span className="text-white/40 text-[10px] font-bold">{crossExam.length} سؤال</span>
                </summary>
                <div className="p-4 space-y-3">
                    {crossExam.map((q) => (
                        <div
                            key={q.id}
                            className={`rounded-xl border border-slate-700/55 bg-slate-950/40 p-3 space-y-2 transition ${
                                q.isAsked ? 'opacity-50' : ''
                            }`}
                        >
                            <div className="flex items-start gap-2">
                                <label className="flex items-center gap-2 shrink-0 pt-0.5 cursor-pointer">
                                    <input
                                        type="checkbox"
                                        className="h-4 w-4 accent-[#E6C673]"
                                        checked={q.isAsked}
                                        disabled={readOnly}
                                        onChange={(e) => patchCrossExam(q.id, { isAsked: e.target.checked })}
                                    />
                                    <span className="text-[10px] font-black text-white/55">تم الطرح</span>
                                </label>
                                <p
                                    className={`flex-1 text-sm font-bold text-white/90 whitespace-normal break-words ${
                                        q.isAsked ? 'line-through decoration-white/25' : ''
                                    }`}
                                >
                                    {q.question}
                                </p>
                                {!readOnly ? (
                                    <button
                                        type="button"
                                        onClick={() => removeCrossQuestion(q.id)}
                                        className="text-[10px] font-bold text-red-300/70 hover:text-red-200 shrink-0"
                                    >
                                        ✕
                                    </button>
                                ) : null}
                            </div>
                            <input
                                type="text"
                                disabled={readOnly}
                                placeholder={liveResponsePlaceholder}
                                value={q.liveResponse ?? ''}
                                onChange={(e) => patchCrossExam(q.id, { liveResponse: e.target.value })}
                                className={`w-full rounded-lg border border-slate-700/70 bg-slate-900/80 px-3 py-2 text-sm text-white/85 outline-none focus:border-[#E6C673]/45 ${
                                    q.isAsked ? 'italic text-white/75' : ''
                                }`}
                            />
                        </div>
                    ))}

                    {!readOnly ? (
                        <div className="flex flex-wrap gap-2 pt-1">
                            <input
                                type="text"
                                value={newQuestion}
                                onChange={(e) => setNewQuestion(e.target.value)}
                                onKeyDown={(e) => {
                                    if (e.key === 'Enter') {
                                        e.preventDefault();
                                        addCrossQuestion();
                                    }
                                }}
                                placeholder="صياغة سؤال تكتيكي..."
                                className="flex-1 min-w-[180px] rounded-xl border border-slate-700 bg-slate-950 px-3 py-2 text-sm text-white outline-none focus:border-[#E6C673]/45"
                            />
                            <button
                                type="button"
                                onClick={addCrossQuestion}
                                className="rounded-xl border border-[#E6C673]/45 bg-[#E6C673]/12 px-3 py-2 text-[11px] font-black text-[#E6C673]"
                            >
                                ➕ إضافة سؤال تكتيكي
                            </button>
                        </div>
                    ) : crossExam.length === 0 ? (
                        <p className="text-white/40 text-xs font-bold text-center py-2">لا توجد أسئلة مسجّلة.</p>
                    ) : null}
                </div>
            </details>
            ) : null}
        </div>
    );
};

import React, { useEffect, useMemo, useRef, useState } from 'react';
import type { CaseStage, JudicialDecision } from '@/app/types/criminal';
import type { AddTrialSessionInput, TrialSession } from '../trialSessionsEngine';
import {
    findCurrentPendingTrialSession,
    filterTrialSessionsForDisplay,
    formatTrialSessionIsoDate,
    isTrialDossierConcluded,
    isTrialSessionPostCassationRemand,
    normalizeTrialSessions,
    resolveTrialPresenceFieldConfig,
    sanitizeTrialSessionIsoDateInput,
    sortTrialSessionsAsc,
    sortTrialSessionsDesc,
    suggestNextSessionNumber,
    todayIsoDate,
    trialSessionPresenceBadge,
    trialSessionStatusLabel,
} from '../trialSessionsEngine';
import { resolveLinkedTrialPreparatoryDecision } from '../trialSessionPreparatoryDecisionEngine';
import { TrialSessionPreparatoryAppealBlock } from './TrialSessionPreparatoryAppealBlock';
import { useCriminalStore } from '../criminalStore';
import type { CriminalCaseUserRole } from '../complainantCassationGovernance';
import { getPendingCassationAppealForResult } from '../judicialDecisionsEngine';
import { CriminalModalPortal, CRIMINAL_MODAL_Z } from '../criminalModalPortal';
import { TrialHearingDateHint } from './TrialHearingDateHint';

export type TrialsTabProps = {
    caseId: string;
    caseStage: CaseStage;
    sessions: TrialSession[];
    judicialDecisions?: JudicialDecision[];
    readOnly?: boolean;
    userRole?: CriminalCaseUserRole;
    onAddSession: (payload: AddTrialSessionInput) => string | null;
    onUpdateSession?: (sessionId: string, payload: AddTrialSessionInput) => string | null;
    onDocumentPreparatoryDecision: (input: {
        sessionId?: string;
        session: AddTrialSessionInput;
        preparatory: { title: string; details: string; isBlockingSuit: boolean };
    }) => string | null;
    onPostpone: (
        sessionId: string,
        nextDate: string,
        reason: string,
        prepNote: string,
    ) => string | null;
    /** فتح مودال إصدار القرار الختامي الكامل (StageFinalDecisionModal) بعد حفظ الجلسة. */
    onOpenStageFinalDecision?: (sessionId: string) => void;
    onCassationAppeal: (decision: JudicialDecision) => void;
    onInterventionCassation: (decision: JudicialDecision) => void;
    onCassationCorrection: (decision: JudicialDecision) => void;
    onDeclareJudgmentFinal: (decision: JudicialDecision) => void;
    onRecordAppealResult: (decision: JudicialDecision) => void;
    currentAccusationArticle: string;
    crimeType?: string;
    onError?: (message: string) => void;
    embedded?: boolean;
    addModalOpen?: boolean;
    onAddModalOpenChange?: (open: boolean) => void;
    /** تاريخ نقض التمييز وإعادة الأوراق — لتمييز جلسات الجولة الثانية. */
    remandPivotDate?: string | null;
    /** موعد المحاكمة المسجّل كتلميح — يُعرض بدل جلسة وهمية */
    scheduledHearingDate?: string | null;
};

export const TrialsTab = ({
    caseId,
    caseStage,
    sessions,
    judicialDecisions = [],
    readOnly,
    userRole,
    onAddSession,
    onUpdateSession,
    onDocumentPreparatoryDecision,
    onPostpone,
    onOpenStageFinalDecision,
    onCassationAppeal,
    onInterventionCassation,
    onCassationCorrection,
    onDeclareJudgmentFinal,
    onRecordAppealResult,
    currentAccusationArticle,
    crimeType,
    onError,
    embedded = false,
    addModalOpen,
    onAddModalOpenChange,
    remandPivotDate = null,
    scheduledHearingDate = null,
}: TrialsTabProps) => {
    const scheduledDate = String(scheduledHearingDate ?? '').trim();
    const effectiveSessions = useMemo(
        () => filterTrialSessionsForDisplay(sessions, scheduledDate),
        [sessions, scheduledDate],
    );
    const sorted = useMemo(() => sortTrialSessionsAsc(effectiveSessions), [effectiveSessions]);
    const displaySessions = useMemo(() => sortTrialSessionsDesc(effectiveSessions), [effectiveSessions]);
    const currentPending = useMemo(() => findCurrentPendingTrialSession(sorted), [sorted]);
    const dossierConcluded = isTrialDossierConcluded(sorted);
    const showScheduledHearingHint = Boolean(scheduledDate) && displaySessions.length === 0;

    const [isAddOpenInternal, setIsAddOpenInternal] = useState(false);
    const isAddOpen = addModalOpen ?? isAddOpenInternal;
    const setIsAddOpen = (open: boolean) => {
        if (onAddModalOpenChange) onAddModalOpenChange(open);
        else setIsAddOpenInternal(open);
    };
    const [showPreparatoryInline, setShowPreparatoryInline] = useState(false);
    const [postponeSessionId, setPostponeSessionId] = useState<string | null>(null);

    const [addDate, setAddDate] = useState('');
    const [addSessionNumber, setAddSessionNumber] = useState('');
    const [addPresence, setAddPresence] = useState<'present' | 'absent'>('present');
    const [addNotes, setAddNotes] = useState('');
    const [prepTitle, setPrepTitle] = useState('');
    const [prepDetails, setPrepDetails] = useState('');
    const [isBlockingSuit, setIsBlockingSuit] = useState(false);

    const presenceField = useMemo(
        () => resolveTrialPresenceFieldConfig(addSessionNumber),
        [addSessionNumber],
    );

    const [nextDate, setNextDate] = useState('');
    const [postponeReason, setPostponeReason] = useState('');
    const [prepNote, setPrepNote] = useState('');

    const activeModalSessionIdRef = useRef<string | null>(null);
    const isEditingPendingSession = Boolean(currentPending);

    useEffect(() => {
        if (!isAddOpen) {
            setShowPreparatoryInline(false);
            setPrepTitle('');
            setPrepDetails('');
            setIsBlockingSuit(false);
            activeModalSessionIdRef.current = null;
            return;
        }
        activeModalSessionIdRef.current = currentPending?.id ?? null;
        if (currentPending) {
            setAddDate(currentPending.date);
            setAddSessionNumber(currentPending.sessionNumber);
            setAddPresence(currentPending.presenceStatus);
            setAddNotes(currentPending.sessionNotes ?? '');
        } else {
            setAddDate(todayIsoDate());
            setAddSessionNumber(suggestNextSessionNumber(sessions));
            setAddPresence('present');
            setAddNotes('');
        }
    }, [isAddOpen, currentPending?.id, sessions]);

    useEffect(() => {
        if (!postponeSessionId) return;
        setNextDate('');
        setPostponeReason('');
        setPrepNote('');
    }, [postponeSessionId]);

    useEffect(() => {
        if (dossierConcluded) {
            setShowPreparatoryInline(false);
        }
    }, [dossierConcluded]);

    const reportError = (msg: string) => {
        if (onError) onError(msg);
    };

    const buildSessionPayload = (): AddTrialSessionInput => ({
        date: addDate,
        sessionNumber: addSessionNumber,
        presenceStatus: addPresence,
        sessionNotes: addNotes,
    });

    const ensureSessionIdForAction = (): string | null => {
        const payload = buildSessionPayload();
        const boundId = activeModalSessionIdRef.current;
        if (boundId) {
            if (onUpdateSession) {
                const updateErr = onUpdateSession(boundId, payload);
                if (updateErr) {
                    reportError(updateErr);
                    return null;
                }
            }
            return boundId;
        }
        if (currentPending) {
            activeModalSessionIdRef.current = currentPending.id;
            if (onUpdateSession) {
                const updateErr = onUpdateSession(currentPending.id, payload);
                if (updateErr) {
                    reportError(updateErr);
                    return null;
                }
            }
            return currentPending.id;
        }
        const addErr = onAddSession(payload);
        if (addErr) {
            reportError(addErr);
            return null;
        }
        const fresh = normalizeTrialSessions(useCriminalStore.getState().casesById[caseId]?.trials);
        const pending = findCurrentPendingTrialSession(fresh);
        if (!pending) {
            reportError('تعذّر تهيئة الجلسة — تحقق من تاريخ ورقم الجلسة.');
            return null;
        }
        activeModalSessionIdRef.current = pending.id;
        return pending.id;
    };

    const submitPostpone = () => {
        if (!postponeSessionId) return;
        const err = onPostpone(postponeSessionId, nextDate, postponeReason, prepNote);
        if (err) {
            reportError(err);
            return;
        }
        setPostponeSessionId(null);
    };

    const handleModalPostpone = () => {
        const sessionId = ensureSessionIdForAction();
        if (!sessionId) return;
        setIsAddOpen(false);
        setShowPreparatoryInline(false);
        setPostponeSessionId(sessionId);
    };

    const handleModalFinalDecisionClick = () => {
        const sessionId = ensureSessionIdForAction();
        if (!sessionId) return;
        if (!onOpenStageFinalDecision) {
            reportError('تعذّر فتح نموذج القرار الختامي.');
            return;
        }
        setShowPreparatoryInline(false);
        setIsAddOpen(false);
        onOpenStageFinalDecision(sessionId);
    };

    const handleModalPreparatoryClick = () => {
        setShowPreparatoryInline((prev) => !prev);
    };

    const submitPreparatoryDecision = () => {
        const sessionId = ensureSessionIdForAction();
        if (!sessionId) return;
        const err = onDocumentPreparatoryDecision({
            sessionId,
            session: buildSessionPayload(),
            preparatory: {
                title: prepTitle,
                details: prepDetails,
                isBlockingSuit,
            },
        });
        if (err) {
            reportError(err);
            return;
        }
        setShowPreparatoryInline(false);
        setIsAddOpen(false);
        setPrepTitle('');
        setPrepDetails('');
        setIsBlockingSuit(false);
    };

    const closeAddModal = () => {
        setIsAddOpen(false);
        setShowPreparatoryInline(false);
    };

    const postponeSession = sorted.find((s) => s.id === postponeSessionId);
    const editingPostRemand =
        Boolean(remandPivotDate) &&
        (currentPending
            ? isTrialSessionPostCassationRemand(currentPending, remandPivotDate, sorted)
            : true);

    return (
        <div
            key={`criminal-tab-trials-${caseId}`}
            className={
                embedded
                    ? 'flex flex-col w-full gap-4'
                    : 'flex flex-col p-6 max-w-5xl mx-auto w-full gap-6'
            }
        >
            {!embedded ? (
                <div className="flex flex-wrap items-center justify-between gap-3">
                    <div>
                        <div className="text-white font-black text-base">المحاكمات</div>
                        <p className="text-white/50 text-xs mt-0.5">
                            سجل رسمي للمرافعات والأحكام — مستقل عن مسارات الساندبوكس
                        </p>
                    </div>
                    {!readOnly && !dossierConcluded ? (
                        <button
                            type="button"
                            onClick={() => setIsAddOpen(true)}
                            className="rounded-xl bg-[#E6C673] text-[#0B1021] px-4 py-2.5 text-sm font-black hover:brightness-110 transition"
                        >
                            ➕ إضافة جلسة مرافعة جديدة
                        </button>
                    ) : null}
                </div>
            ) : null}

            {showScheduledHearingHint ? (
                <TrialHearingDateHint hearingDate={scheduledDate} />
            ) : null}

            {displaySessions.length === 0 ? null : (
                <div className="relative pr-4 border-r-2 border-[#E6C673]/35 space-y-4">
                    {displaySessions.map((session, displayIndex) => {
                        const presenceBadge = trialSessionPresenceBadge(
                            session.presenceStatus,
                            session.sessionNumber,
                        );
                        const linkedPrepDecision = resolveLinkedTrialPreparatoryDecision(
                            session,
                            judicialDecisions,
                        );
                        const pendingAppeal = linkedPrepDecision
                            ? getPendingCassationAppealForResult(linkedPrepDecision)
                            : null;
                        const isPresent = session.presenceStatus === 'present';
                        const verdict = session.verdict;
                        const isCurrent = currentPending?.id === session.id;
                        const isPostRemand = isTrialSessionPostCassationRemand(
                            session,
                            remandPivotDate,
                            sorted,
                        );
                        const prevSession = displayIndex > 0 ? displaySessions[displayIndex - 1] : null;
                        const prevPostRemand = prevSession
                            ? isTrialSessionPostCassationRemand(prevSession, remandPivotDate, sorted)
                            : false;
                        const showRemandDivider = Boolean(remandPivotDate) && isPostRemand && !prevPostRemand;

                        return (
                            <React.Fragment key={session.id}>
                                {showRemandDivider ? (
                                    <div
                                        className="mr-6 my-1 flex items-center gap-2"
                                        role="separator"
                                        aria-label="بداية جلسات ما بعد إعادة الأوراق"
                                    >
                                        <div className="h-px flex-1 bg-rose-400/45" />
                                        <span className="shrink-0 rounded-full border border-rose-400/40 bg-rose-950/30 px-2.5 py-0.5 text-[9px] font-black text-rose-100">
                                            ↩ بعد إعادة الأوراق من التمييز
                                        </span>
                                        <div className="h-px flex-1 bg-rose-400/45" />
                                    </div>
                                ) : null}
                            <div className="relative mr-6 space-y-0">
                                <span className="absolute -right-[1.65rem] top-4 h-3 w-3 rounded-full border-2 border-[#E6C673] bg-slate-900" />
                                <div
                                    className={`rounded-xl border bg-slate-800/40 p-3 space-y-2 ${
                                        isCurrent
                                            ? 'border-[#E6C673]/55 ring-1 ring-[#E6C673]/25'
                                            : 'border-slate-700/80'
                                    }`}
                                >
                                    <div className="flex flex-wrap items-center gap-x-2 gap-y-1">
                                        <span className="text-white font-black text-sm">
                                            الجلسة رقم {session.sessionNumber}
                                        </span>
                                        <span
                                            className="text-white/45 text-[11px] font-bold unicode-bidi-plaintext tabular-nums"
                                            dir="ltr"
                                        >
                                            {formatTrialSessionIsoDate(session.date)}
                                        </span>
                                        {isCurrent ? (
                                            <span className="rounded-full border border-sky-400/45 bg-sky-500/12 px-2 py-0.5 text-[9px] font-black text-sky-100">
                                                جلسة المرافعة الحالية
                                            </span>
                                        ) : null}
                                        {isPostRemand ? (
                                            <span className="rounded-full border border-rose-400/40 bg-rose-950/25 px-2 py-0.5 text-[9px] font-black text-rose-100">
                                                مرافعة ما بعد التمييز
                                            </span>
                                        ) : null}
                                    </div>
                                    <div className="flex flex-wrap gap-1.5">
                                        <span
                                            className={`rounded-full border px-2 py-0.5 text-[9px] font-black ${
                                                isPresent
                                                    ? 'border-emerald-500/40 bg-emerald-500/10 text-emerald-200'
                                                    : 'border-amber-500/40 bg-amber-500/10 text-amber-200'
                                            }`}
                                        >
                                            [{presenceBadge}]
                                        </span>
                                        <span className="rounded-full border border-slate-600/50 bg-slate-900/50 px-2 py-0.5 text-[9px] font-black text-white/65">
                                            {trialSessionStatusLabel(session.status)}
                                        </span>
                                        {verdict ? (
                                            <span
                                                className={`rounded-full border px-2 py-0.5 text-[9px] font-black ${
                                                    verdict.outcome === 'conviction'
                                                        ? 'border-red-500/40 bg-red-500/10 text-red-200'
                                                        : verdict.outcome === 'acquittal'
                                                          ? 'border-emerald-500/40 bg-emerald-500/10 text-emerald-200'
                                                          : 'border-yellow-500/40 bg-yellow-500/10 text-yellow-200'
                                                }`}
                                            >
                                                {verdict.outcome === 'conviction'
                                                    ? '🔴 إدانة'
                                                    : verdict.outcome === 'acquittal'
                                                      ? '🟢 براءة'
                                                      : '🟡 إفراج'}
                                            </span>
                                        ) : null}
                                    </div>

                                    {session.preparatoryDecision ? (
                                        <div className="rounded-lg border border-violet-500/30 bg-gradient-to-l from-violet-950/30 to-violet-950/10 p-2.5 space-y-1.5 border-r-[3px] border-r-violet-400/75 shadow-[inset_0_1px_0_rgba(255,255,255,0.04)]">
                                            <div className="inline-flex items-center gap-1.5 rounded-full border border-violet-400/35 bg-violet-500/10 px-2 py-0.5 text-[9px] font-black text-violet-100">
                                                قرار إعدادي
                                                <span className="text-violet-300/60">·</span>
                                                جلسة {session.preparatoryDecision.sessionNumber ?? session.sessionNumber}
                                            </div>
                                            <div className="text-violet-100 text-[11px] font-black leading-snug">
                                                {session.preparatoryDecision.title}
                                            </div>
                                            <p className="text-white/75 text-[11px] whitespace-normal break-words leading-snug">
                                                {session.preparatoryDecision.details}
                                            </p>
                                            {session.preparatoryDecision.isBlockingSuit ? (
                                                <span className="inline-flex rounded-full border border-amber-500/35 bg-amber-950/25 px-2 py-0.5 text-[9px] font-black text-amber-100">
                                                    يوقف سير الدعوى
                                                </span>
                                            ) : null}
                                            {linkedPrepDecision ? (
                                                <TrialSessionPreparatoryAppealBlock
                                                    decision={linkedPrepDecision}
                                                    caseStage={caseStage}
                                                    readOnly={readOnly}
                                                    userRole={userRole}
                                                    onCassationAppeal={() =>
                                                        onCassationAppeal(linkedPrepDecision)
                                                    }
                                                    onInterventionCassation={() =>
                                                        onInterventionCassation(linkedPrepDecision)
                                                    }
                                                    onCassationCorrection={() =>
                                                        onCassationCorrection(linkedPrepDecision)
                                                    }
                                                    onDeclareJudgmentFinal={() =>
                                                        onDeclareJudgmentFinal(linkedPrepDecision)
                                                    }
                                                    onRecordAppealResult={
                                                        pendingAppeal
                                                            ? () => onRecordAppealResult(linkedPrepDecision)
                                                            : undefined
                                                    }
                                                />
                                            ) : null}
                                        </div>
                                    ) : null}

                                    {isCurrent && !readOnly && !session.preparatoryDecision && !dossierConcluded ? (
                                        <button
                                            type="button"
                                            onClick={() => {
                                                setIsAddOpen(true);
                                                setShowPreparatoryInline(true);
                                            }}
                                            className="rounded-lg border border-violet-500/40 bg-violet-950/25 px-2.5 py-1.5 text-[10px] font-black text-violet-100 hover:bg-violet-950/40 transition w-full text-right"
                                        >
                                            ⚖️ تسجيل قرار إعدادي لهذه الجلسة
                                        </button>
                                    ) : null}

                                    {session.sessionNotes ? (
                                        <p className="text-white/80 text-xs whitespace-normal break-words leading-snug">
                                            <span className="text-white/45 font-black">محضر المرافعة: </span>
                                            {session.sessionNotes}
                                        </p>
                                    ) : null}

                                    {session.witnessesAndExperts?.length ? (
                                        <div className="rounded-xl border border-slate-700/60 bg-slate-900/40 p-3 space-y-2">
                                            <div className="text-white/60 text-[11px] font-black">الشهود والخبراء</div>
                                            {session.witnessesAndExperts.map((w, i) => (
                                                <div key={`${session.id}-w-${i}`} className="text-sm">
                                                    <span className="text-[#E6C673] font-bold">
                                                        {w.type === 'expert' ? 'خبير' : 'شاهد'}: {w.name}
                                                    </span>
                                                    {w.summary ? (
                                                        <span className="text-white/70"> — {w.summary}</span>
                                                    ) : null}
                                                </div>
                                            ))}
                                        </div>
                                    ) : null}

                                    {session.status === 'postponed' &&
                                    (session.preparationNote ||
                                        session.postponementReason ||
                                        session.nextSessionDate) ? (
                                        <div className="rounded-lg border border-amber-500/30 bg-amber-950/20 px-2.5 py-2 space-y-1 text-[11px]">
                                            {session.nextSessionDate ? (
                                                <div className="flex flex-wrap items-center gap-1.5 font-bold text-amber-100">
                                                    <span className="text-amber-200/75">التالي:</span>
                                                    <span
                                                        dir="ltr"
                                                        className="unicode-bidi-plaintext tabular-nums text-amber-50"
                                                    >
                                                        {formatTrialSessionIsoDate(session.nextSessionDate)}
                                                    </span>
                                                </div>
                                            ) : null}
                                            {session.postponementReason ? (
                                                <p className="text-white/65 font-bold leading-snug">
                                                    <span className="text-white/45">سبب التأجيل: </span>
                                                    {session.postponementReason}
                                                </p>
                                            ) : null}
                                            {session.preparationNote ? (
                                                <p className="text-amber-100/90 font-bold leading-snug">
                                                    <span className="text-amber-200/60">واجب تحضيري: </span>
                                                    {session.preparationNote}
                                                </p>
                                            ) : null}
                                        </div>
                                    ) : null}
                                </div>
                            </div>
                            </React.Fragment>
                        );
                    })}
                </div>
            )}


            {isAddOpen ? (
                <CriminalModalPortal zIndex={CRIMINAL_MODAL_Z.trial}>
                    <div className="w-full max-w-lg rounded-2xl border border-slate-700 bg-slate-900 overflow-hidden shadow-2xl max-h-[90vh] flex flex-col">
                        <div className="px-4 py-3 border-b border-slate-700 bg-slate-800/50 flex justify-between items-center">
                            <div className="text-white font-black text-sm">
                                {isEditingPendingSession ? 'جلسة المرافعة الحالية' : 'جلسة مرافعة جديدة'}
                            </div>
                            <button type="button" onClick={closeAddModal} className="text-white/60 text-xs font-bold">
                                إغلاق
                            </button>
                        </div>
                        <div className="p-4 space-y-3 overflow-y-auto">
                            <div className="grid grid-cols-2 gap-3">
                                <div>
                                    <label className="block text-white/60 text-xs mb-1">تاريخ الجلسة</label>
                                    <input
                                        type="date"
                                        className="w-full bg-slate-950 border border-slate-700 rounded-xl px-3 py-2 text-sm text-white unicode-bidi-plaintext"
                                        dir="ltr"
                                        value={addDate}
                                        onChange={(e) =>
                                            setAddDate(sanitizeTrialSessionIsoDateInput(e.target.value))
                                        }
                                    />
                                </div>
                                <div>
                                    <label className="block text-white/60 text-xs mb-1">رقم الجلسة</label>
                                    <input
                                        className="w-full bg-slate-950 border border-slate-700 rounded-xl px-3 py-2 text-sm text-white tabular-nums disabled:opacity-80 disabled:cursor-not-allowed"
                                        value={addSessionNumber}
                                        readOnly={!isEditingPendingSession}
                                        onChange={(e) => setAddSessionNumber(e.target.value.replace(/\D/g, ''))}
                                        title={
                                            isEditingPendingSession
                                                ? undefined
                                                : 'يُحسب تلقائياً حسب تسلسل الجلسات المسجّلة'
                                        }
                                    />
                                </div>
                            </div>
                            <div>
                                <label className="block text-white/60 text-xs mb-1">{presenceField.label}</label>
                                <select
                                    className="w-full bg-slate-950 border border-slate-700 rounded-xl px-3 py-2 text-sm text-white"
                                    value={addPresence}
                                    onChange={(e) =>
                                        setAddPresence(e.target.value === 'absent' ? 'absent' : 'present')
                                    }
                                >
                                    {presenceField.options.map((opt) => (
                                        <option key={opt.value} value={opt.value}>
                                            {opt.label}
                                        </option>
                                    ))}
                                </select>
                            </div>
                            {!showPreparatoryInline && !readOnly && !dossierConcluded ? (
                                <button
                                    type="button"
                                    onClick={handleModalPreparatoryClick}
                                    className="w-full rounded-xl border border-violet-500/35 bg-violet-950/20 px-3 py-2 text-[11px] font-black text-violet-100 hover:bg-violet-950/35 transition text-right"
                                >
                                    ⚖️ تسجيل قرار إعدادي (اختياري)
                                </button>
                            ) : null}
                            {showPreparatoryInline ? (
                                <div className="rounded-xl border border-violet-500/35 bg-violet-950/20 p-3 space-y-3">
                                    <div className="flex items-center justify-between gap-2">
                                        <div className="text-violet-100 text-[11px] font-black">
                                            قرار إعدادي — الجلسة رقم {addSessionNumber || '—'}
                                        </div>
                                        <button
                                            type="button"
                                            onClick={() => setShowPreparatoryInline(false)}
                                            className="text-[10px] font-bold text-white/45 hover:text-white/70"
                                        >
                                            إخفاء
                                        </button>
                                    </div>
                                    <div>
                                        <label className="block text-white/60 text-xs mb-1">
                                            اسم القرار الإعدادي / الأمر
                                        </label>
                                        <input
                                            className="w-full bg-slate-950 border border-slate-700 rounded-xl px-3 py-2 text-sm text-white"
                                            value={prepTitle}
                                            onChange={(e) => setPrepTitle(e.target.value)}
                                            placeholder="مثال: تأجيل نظر الدعوى لطلب مستند"
                                        />
                                    </div>
                                    <div
                                        className="rounded-lg border border-white/10 bg-white/[0.03] px-2.5 py-2 space-y-1.5"
                                        role="group"
                                        aria-label="هل القرار يترتب عليه منع أو وقف في سير الدعوى؟"
                                    >
                                        <span className="block text-[10px] font-bold text-white/75">
                                            هل القرار يترتب عليه منع أو وقف في سير الدعوى؟
                                        </span>
                                        <div className="flex flex-wrap items-center gap-1.5">
                                            <button
                                                type="button"
                                                role="radio"
                                                aria-checked={isBlockingSuit}
                                                onClick={() => setIsBlockingSuit(true)}
                                                className={`rounded-lg border px-2.5 py-1 text-[10px] font-black transition ${
                                                    isBlockingSuit
                                                        ? 'border-[#E6C673]/55 bg-[#E6C673]/15 text-[#E6C673]'
                                                        : 'border-white/15 bg-white/[0.04] text-white/60'
                                                }`}
                                            >
                                                نعم
                                            </button>
                                            <button
                                                type="button"
                                                role="radio"
                                                aria-checked={!isBlockingSuit}
                                                onClick={() => setIsBlockingSuit(false)}
                                                className={`rounded-lg border px-2.5 py-1 text-[10px] font-black transition ${
                                                    !isBlockingSuit
                                                        ? 'border-slate-500/45 bg-slate-700/35 text-slate-200'
                                                        : 'border-white/15 bg-white/[0.04] text-white/60'
                                                }`}
                                            >
                                                لا
                                            </button>
                                        </div>
                                    </div>
                                    <div>
                                        <label className="block text-white/60 text-xs mb-1">
                                            تفاصيل ووقائع القرار
                                        </label>
                                        <textarea
                                            className="w-full bg-slate-950 border border-slate-700 rounded-xl px-3 py-2 text-sm text-white min-h-[72px] resize-none"
                                            value={prepDetails}
                                            onChange={(e) => setPrepDetails(e.target.value)}
                                        />
                                    </div>
                                    <div className="flex justify-end">
                                        <button
                                            type="button"
                                            onClick={submitPreparatoryDecision}
                                            className="rounded-xl bg-violet-600/85 px-4 py-2 text-[11px] font-black text-white hover:bg-violet-600 transition"
                                        >
                                            حفظ الجلسة وتوثيق القرار
                                        </button>
                                    </div>
                                </div>
                            ) : null}
                            <div>
                                <label className="block text-white/60 text-xs mb-1">محضر المرافعة / ما جرى</label>
                                <textarea
                                    className="w-full bg-slate-950 border border-slate-700 rounded-xl px-3 py-2 text-sm text-white min-h-[88px] resize-none"
                                    value={addNotes}
                                    onChange={(e) => setAddNotes(e.target.value)}
                                />
                            </div>
                            <div className="flex flex-wrap items-center justify-end gap-2">
                                <button
                                    type="button"
                                    onClick={handleModalPostpone}
                                    className="rounded-xl border border-amber-500/35 bg-amber-950/20 px-3 py-2 text-[11px] font-black text-amber-100 hover:bg-amber-950/35 transition"
                                >
                                    تأجيل المحاكمة
                                </button>
                                <button
                                    type="button"
                                    onClick={handleModalFinalDecisionClick}
                                    className="rounded-xl border border-[#d4af37]/55 bg-[#d4af37]/15 px-4 py-2 text-[11px] font-black text-[#d4af37] hover:bg-[#d4af37]/25 transition"
                                >
                                    إصدار القرار الختامي
                                </button>
                            </div>
                        </div>
                    </div>
                </CriminalModalPortal>
            ) : null}

            {postponeSessionId && postponeSession ? (
                <CriminalModalPortal zIndex={CRIMINAL_MODAL_Z.trialPostpone}>
                    <div className="w-full max-w-md rounded-2xl border border-slate-700 bg-slate-900 overflow-hidden shadow-2xl">
                        <div className="px-4 py-3 border-b border-slate-700 bg-slate-800/50 flex justify-between items-center">
                            <div className="text-white font-black text-sm">
                                تأجيل الجلسة {postponeSession.sessionNumber}
                            </div>
                            <button
                                type="button"
                                onClick={() => setPostponeSessionId(null)}
                                className="text-white/60 text-xs font-bold"
                            >
                                إغلاق
                            </button>
                        </div>
                        <div className="p-4 space-y-3">
                            <input
                                type="date"
                                className="w-full bg-slate-950 border border-slate-700 rounded-xl px-3 py-2 text-sm text-white unicode-bidi-plaintext"
                                dir="ltr"
                                value={nextDate}
                                onChange={(e) =>
                                    setNextDate(sanitizeTrialSessionIsoDateInput(e.target.value))
                                }
                            />
                            <textarea
                                className="w-full bg-slate-950 border border-slate-700 rounded-xl px-3 py-2 text-sm text-white min-h-[72px] resize-none"
                                placeholder="سبب التأجيل"
                                value={postponeReason}
                                onChange={(e) => setPostponeReason(e.target.value)}
                            />
                            <textarea
                                className="w-full bg-slate-950 border border-amber-500/30 rounded-xl px-3 py-2 text-sm text-amber-50 min-h-[72px] resize-none"
                                placeholder="الواجب التحضيري للمحامي"
                                value={prepNote}
                                onChange={(e) => setPrepNote(e.target.value)}
                            />
                            <div className="flex justify-end gap-2 pt-1">
                                <button
                                    type="button"
                                    onClick={() => setPostponeSessionId(null)}
                                    className="rounded-xl border border-slate-700 px-3 py-2 text-xs font-black text-white/70"
                                >
                                    إلغاء
                                </button>
                                <button
                                    type="button"
                                    onClick={submitPostpone}
                                    className="rounded-xl bg-amber-600/80 px-4 py-2 text-sm font-black text-white"
                                >
                                    تأكيد التأجيل
                                </button>
                            </div>
                        </div>
                    </div>
                </CriminalModalPortal>
            ) : null}
        </div>
    );
};

import React, { useEffect, useState } from 'react';
import type { CaseStage } from '@/app/types/criminal';
import { cassationRoutingGuide } from '../trialSessionsEngine';
import type {
    VerdictCard,
    VerdictCorrectionAppealTrack,
    VerdictOrdinaryAppealTrack,
} from '../verdictCardsEngine';
import { verdictOutcomeLabel } from '../verdictCardsEngine';
import {
    VERDICT_CASSATION_RESULT_OPTIONS,
    VERDICT_REFERRAL_COURT_OPTIONS,
    coerceLegacyVerdictCassationResult,
    verdictCassationResultNeedsBindingDirections,
    verdictCassationResultNeedsPenaltyModification,
    verdictCassationResultNeedsReferralCourt,
    validateVerdictCassationResultSave,
    type VerdictCassationResultSaveInput,
    type VerdictCassationResultValue,
    type VerdictReferralCourtValue,
} from '../verdictCassationResultEngine';
import { ModalIsoDate } from './ModalIsoDate';
import { ModalIsoDateInput } from './ModalIsoDateInput';
import { CriminalModalPortal, CRIMINAL_MODAL_Z } from '../criminalModalPortal';

const panelClass =
    'relative w-full max-w-lg max-h-[min(92vh,720px)] flex flex-col rounded-2xl border border-slate-700 bg-slate-900 shadow-2xl overflow-hidden';

type CassationModalBaseProps = {
    open: boolean;
    card: VerdictCard | null;
    readOnly?: boolean;
    onClose: () => void;
};

export type VerdictCassationFilingModalProps = CassationModalBaseProps & {
    caseStage: CaseStage;
    currentAccusationArticle?: string;
    crimeType?: string;
    onSave: (patch: Partial<VerdictOrdinaryAppealTrack>) => void;
};

/** المرحلة 1 — تسجيل تقديم الطعن وإرسال الإضبارة (بدون نتيجة). */
export const VerdictCassationFilingModal = ({
    open,
    card,
    caseStage,
    currentAccusationArticle,
    crimeType,
    readOnly,
    onClose,
    onSave,
}: VerdictCassationFilingModalProps) => {
    const [filedAt, setFiledAt] = useState('');
    const [error, setError] = useState('');

    useEffect(() => {
        if (!open || !card) return;
        setError('');
        setFiledAt(String(card.ordinaryAppeal?.filedAt ?? ''));
    }, [open, card?.id, card?.ordinaryAppeal?.filedAt]);

    if (!open || !card) return null;

    const submit = () => {
        const date = filedAt.trim();
        if (!date) {
            setError('تاريخ التقديم مطلوب.');
            return;
        }
        onSave({
            filedAt: date,
            courtLabel: cassationRoutingGuide(caseStage, { currentAccusationArticle, crimeType }).courtLabel,
        });
        onClose();
    };

    return (
        <CriminalModalPortal zIndex={CRIMINAL_MODAL_Z.verdictCassation} className="isolate">
            <div className={panelClass} onClick={(e) => e.stopPropagation()}>
                <div className="p-4 border-b border-slate-700 bg-slate-800/50">
                    <div className="text-white font-black text-sm whitespace-normal break-words">
                        تسجيل تقديم الطعن وإرسال الإضبارة
                    </div>
                    <div className="text-white/55 text-xs mt-1 whitespace-normal break-words">
                        {verdictOutcomeLabel(card.outcome)} · تاريخ الحكم:{' '}
                        <ModalIsoDate value={card.issuedAt} />
                    </div>
                </div>

                <div className="p-4 space-y-3 overflow-y-auto flex-1">
                    <div>
                        <label className="block text-white/70 text-xs mb-1">تاريخ التقديم *</label>
