            caseAllowsSeveranceOrDossierStrike(
                [{ id: 'c1', fullName: 'أ', address: '', phone: '' } as any],
                [makeDefendant('d1')],
            ),
        ).toBe(false);
        expect(caseAllowsSeveranceOrDossierStrike([], [makeDefendant('d1'), makeDefendant('d2')])).toBe(
            true,
        );
        expect(
            caseAllowsSeveranceOrDossierStrike(
                [
                    { id: 'c1', fullName: 'أ', address: '', phone: '' } as any,
                    { id: 'c2', fullName: 'ب', address: '', phone: '' } as any,
                ],
                [makeDefendant('d1')],
            ),
