            } ${
                fatal
                    ? 'border-rose-500/40 shadow-[0_0_12px_rgba(239,68,68,0.15)]'
                    : markedDone
                      ? 'border-[#1A7059]/35'
                      : ''
            }`}
        >
            {(listOrdinal?.total ?? 0) > 1 ? (
                <TaskListOrdinalBadge
                    ordinal={listOrdinal!}
                    compact
                    placement="edge"
                    testId={`field-tasks-ordinal-${task.id}`}
                />
            ) : null}
            <div className={`absolute top-0 right-0 bottom-0 w-0.5 bg-gradient-to-b ${taskListStripeToneClass(listOrdinal)} to-transparent rounded-r-xl pointer-events-none`} />

            <div className="flex flex-row items-start gap-2">
                <div className="flex-1 min-w-0">
                    <div className="flex flex-wrap items-center gap-1.5 justify-end mb-1">
                        {task.pinnedToFieldCurtain ? (
                            <span className="inline-flex items-center gap-0.5 text-[10px] font-extrabold px-2 py-0.5 rounded-full bg-[#A67C52]/15 text-[#D4B896] border border-[#A67C52]/35">
                                <PanelBottom className="size-3" aria-hidden />
                                ستارة الميدان
                            </span>
                        ) : null}
                        {fatal ? (
                            <span className="text-[10px] font-extrabold text-rose-200 bg-rose-500/20 border border-rose-400/35 px-2 py-0.5 rounded-full">
                                حتمي
                            </span>
                        ) : null}
                    </div>
                    <p className="text-[#E8F5F0] text-base font-extrabold leading-snug break-words">{task.title}</p>
                    {task.location ? (
                        <p className="mt-1 text-[11px] font-bold text-[#6BC4A8]/90 flex flex-row-reverse items-center gap-1 justify-end">
                            <MapPin className="size-3 shrink-0 opacity-80" aria-hidden />
                            {task.location}
                        </p>
                    ) : null}
                    {task.voiceRef ? (
                        <div className="mt-2">
                            <TaskVoicePlayback voiceRef={task.voiceRef} compact />
                        </div>
                    ) : null}
                </div>
                <div className="flex flex-col items-center gap-1.5 shrink-0">
                    {clusterPin ? (
                        <WorkspacePinButton item={clusterPin} className="!w-7 !h-7" size={14} />
                    ) : null}
                    {markedDone ? (
                        <div className="flex flex-col items-center gap-1">
                            <span
                                className={`inline-flex items-center gap-1 px-2 py-1 rounded-lg border text-[10px] font-extrabold whitespace-nowrap ${
                                    readOnly
                                        ? 'bg-[#0c0c0e]/40 border-[#A67C52]/20 text-[#A67C52]/70'
                                        : 'bg-[#1A7059]/25 border-[#1A7059]/40 text-[#E8F5F0]'
                                }`}
                            >
                                <CheckCircle2 className="size-3" aria-hidden />
                                {readOnly ? 'للمعاينة' : 'تم'}
                            </span>
                            {!readOnly ? (
                                <button
                                    type="button"
                                    onClick={() => onReopenTask(task)}
                                    className="text-[9px] font-bold text-[#B8956A] hover:underline"
                                >
                                    تراجع
                                </button>
                            ) : null}
                        </div>
                    ) : (
                        <button
                            type="button"
                            data-testid={`field-tasks-complete-${task.id}`}
                            onClick={() => onCompleteRequest(task)}
                            className="min-h-[44px] px-2.5 py-1 rounded-lg bg-[#1A7059]/70 hover:bg-[#1A7059] border border-[#1A7059]/50 text-[#E8F5F0] text-[10px] font-extrabold whitespace-nowrap touch-manipulation"
                        >
                            إنهاء المهمة
                        </button>
                    )}
                </div>
            </div>

            {hasSubs ? (
                <TaskSubTasksCollapsible
                    subTasks={task.subTasks}
                    readOnly={readOnly}
                    onToggleSubComplete={(subId) => onToggleSubComplete(task.id, subId)}
                    compactActions
                    testIdPrefix={`field-tasks-curtain-card-${task.id}`}
                />
            ) : null}
        </li>
    );
}, (prev, next) => {
    if (prev.listOrdinal?.index !== next.listOrdinal?.index || prev.listOrdinal?.total !== next.listOrdinal?.total) {
        return false;
    }
    if (prev.now.toDateString() !== next.now.toDateString()) return false;
    if (prev.pinLookup !== next.pinLookup) return false;
    if (taskCardSignature(prev.task) !== taskCardSignature(next.task)) return false;
    return true;
});

export const FieldTasksBottomSheet = memo(function FieldTasksBottomSheet({
    open,
    onClose,
    onManageAll,
    lawsuitFiles = [],
    executionFiles = [],
}: FieldTasksBottomSheetProps) {
    const { pendingTasks } = useQuantumTasksData();
    const { completeTask, reopenTask, toggleSubTaskComplete } = useQuantumTasksActions();
    const keyboardInsetPx = useMobileKeyboardInset(open);
    const { fatalOpen, requestComplete, confirmFatalComplete, cancelFatalComplete } =
        useFatalTaskComplete(completeTask);

    const now = useMemo(() => new Date(), [open]);
    const curtainTasks = useMemo(
        () => (open ? listFieldDaySheetTasks(pendingTasks, now) : []),
        [open, pendingTasks, now],
    );
    const pinLookup = useMemo(
        () => (open ? buildLinkedCaseLookup(lawsuitFiles, executionFiles) : null),
        [open, lawsuitFiles, executionFiles],
    );

    const [sheetVisible, setSheetVisible] = useState(open);
    const [sheetHydrated, setSheetHydrated] = useState(false);

    useEffect(() => {
        if (!open) setSheetHydrated(false);
    }, [open]);

    useTasksLifecycle(open, sheetVisible, () => setSheetHydrated(true));

    useLayoutEffect(() => {
        if (!open) {
            setSheetVisible(false);
            return;
        }
        setSheetVisible(true);
    }, [open]);

    useBodyScrollLock(open);

    const handleClose = useCallback(() => {
        onClose();
    }, [onClose]);

    const handleReopenTask = useCallback(
        (task: LegalTask) => {
            reopenTask(task.id);
        },
        [reopenTask],
    );

    useEffect(() => {
        if (!open && fatalOpen) {
            cancelFatalComplete();
        }
    }, [open, fatalOpen, cancelFatalComplete]);

    useEffect(() => {
        if (!fatalOpen) return;
        blockTasksOverlayEscape('field-fatal');
        const onKeyDown = (e: KeyboardEvent) => {
            if (e.key !== 'Escape') return;
            e.preventDefault();
            e.stopPropagation();
            cancelFatalComplete();
        };
        window.addEventListener('keydown', onKeyDown, true);
        return () => {
            unblockTasksOverlayEscape('field-fatal');
            window.removeEventListener('keydown', onKeyDown, true);
        };
    }, [fatalOpen, cancelFatalComplete]);

    if (typeof document === 'undefined') return null;

    const layerVisible = open || isFieldTasksForceVisible();

    return createPortal(
        <>
            {fatalOpen ? (
                <Dialog
                    open={fatalOpen}
                    onOpenChange={(o) => {
                        if (!o) cancelFatalComplete();
                    }}
                >
                    <DialogContent className="border-[#A67C52]/35 bg-[#0A2E25] text-[#E8F5F0] sm:max-w-md [&]:translate-x-[-50%] [&]:translate-y-[-50%]">
                        <DialogHeader className="text-right sm:text-right space-y-2">
                            <DialogTitle className="text-[#D4B896] text-base font-extrabold leading-relaxed">
                                تحذير — موعد حتمي
                            </DialogTitle>
                            <DialogDescription className="text-[#E8F5F0]/80 text-sm leading-relaxed">
                                هذا موعد حتمي (سقوط حق). هل أنت متأكد من إنجاز الإجراء القانوني بشكل نهائي؟
                            </DialogDescription>
                        </DialogHeader>
                        <DialogFooter className="flex flex-row-reverse gap-2 sm:justify-start">
                            <button
                                type="button"
                                onClick={confirmFatalComplete}
                                className="px-4 py-2 rounded-lg bg-rose-600 hover:bg-rose-500 text-white text-xs font-extrabold"
                            >
                                تأكيد الإكمال
                            </button>
                            <button
                                type="button"
                                onClick={cancelFatalComplete}
                                className="px-4 py-2 rounded-lg border border-[#A67C52]/30 bg-[#0c0c0e]/40 hover:bg-[#0c0c0e]/60 text-[#E8F5F0] text-xs font-bold"
                            >
                                إلغاء
                            </button>
                        </DialogFooter>
                    </DialogContent>
                </Dialog>
            ) : null}

            <div
                data-field-tasks-root=""
                data-open={layerVisible ? 'true' : 'false'}
                aria-hidden={!layerVisible}
                className={layerVisible ? 'hami-field-tasks-layer--visible' : undefined}
                style={{
                    opacity: layerVisible ? 1 : 0,
                    visibility: layerVisible ? 'visible' : 'hidden',
                    pointerEvents: layerVisible ? 'auto' : 'none',
                }}
                {...inertProps(!layerVisible)}
            >
                <button
                    type="button"
                    aria-label="إغلاق الستارة"
                    tabIndex={layerVisible ? 0 : -1}
                    className={`fixed inset-0 bg-[#051410]/75 border-0 cursor-default transition-opacity duration-150 ${
                        sheetVisible ? 'opacity-100' : 'opacity-0'
                    }`}
                    style={{ zIndex: CURTAIN_LAYER_Z }}
                    onClick={handleClose}
                />
                <div
                    role="dialog"
                    aria-modal={layerVisible ? true : undefined}
                    aria-labelledby="field-tasks-sheet-title"
                    data-testid="field-tasks-sheet"
                    data-field-tasks-hydrated={sheetHydrated && sheetVisible ? 'true' : 'false'}
                    className={`${CURTAIN_SHEET} pb-[max(0px,env(safe-area-inset-bottom))] transition-transform duration-200 ease-out will-change-transform ${
                        sheetVisible ? 'translate-y-0' : 'translate-y-full'
                    }`}
                    style={{
                        zIndex: CURTAIN_SHEET_Z,
                        marginBottom: keyboardInsetPx > 0 ? keyboardInsetPx : undefined,
                    }}
                >
                    <div className="shrink-0 flex flex-col items-center pt-2.5 pb-1 relative z-[1]">
                        <div className="w-12 h-1 rounded-full bg-[#A67C52]/40" />
                    </div>

                    <div className="shrink-0 flex items-center justify-between gap-3 px-4 pb-3 border-b border-[#A67C52]/18 relative z-[1]">
                        <div className="flex items-center gap-2 min-w-0">
                            <div className="w-9 h-9 rounded-xl bg-[#0c0c0e]/45 border border-[#A67C52]/25 flex items-center justify-center shrink-0">
                                <ClipboardList size={18} className="text-[#B8956A]" />
                            </div>
                            <div className="min-w-0">
                                <h2 id="field-tasks-sheet-title" className="text-[#E8F5F0] font-extrabold text-base truncate">
                                    مهام اليوم الميدانية
                                </h2>
                                {curtainTasks.length > 0 ? (
                                    <p className="text-[10px] text-[#6BC4A8]/60 font-bold">
                                        {curtainTasks.length} مهمة
                                    </p>
                                ) : null}
                            </div>
                        </div>
                        <button
                            type="button"
                            onClick={handleClose}
                            data-testid="field-tasks-close"
                            tabIndex={layerVisible ? 0 : -1}
                            className="shrink-0 w-11 h-11 rounded-xl border border-[#A67C52]/22 bg-[#0c0c0e]/40 flex items-center justify-center text-[#E8F5F0]/80 hover:bg-[#0c0c0e]/60 touch-manipulation"
                            aria-label="إغلاق"
                        >
                            <X size={20} />
                        </button>
                    </div>

                    <div
                        dir="rtl"
                        className="flex-1 overflow-y-auto overscroll-y-contain px-4 py-3 min-h-0 relative z-[1]"
                    >
                        {curtainTasks.length === 0 ? (
                            <div
                                className={`${CURTAIN_GLASS_INNER} flex flex-col items-center py-12 px-4 text-center`}
                                data-testid="field-tasks-empty"
                            >
                                <p className="text-[#E8F5F0]/55 text-sm font-medium leading-relaxed max-w-xs">
                                    لا مهام ميدانية لليوم. أضف مهمة من مدير المهام أو ثبّتها على الستارة للوصول السريع.
                                </p>
                                <div className={`mt-4 w-20 ${TASKS_BRONZE_LINE}`} />
                            </div>
                        ) : (
                            <ul className="space-y-2.5">
                                {curtainTasks.map((task, i) => (
                                    <FieldCurtainTaskCard
                                        key={task.id}
                                        task={task}
                                        listOrdinal={{ index: i, total: curtainTasks.length }}
                                        now={now}
                                        pinLookup={pinLookup!}
                                        onCompleteRequest={requestComplete}
                                        onReopenTask={handleReopenTask}
                                        onToggleSubComplete={toggleSubTaskComplete}
                                    />
                                ))}
                            </ul>
                        )}
                    </div>

                    <div className="shrink-0 p-4 pt-2 border-t border-[#A67C52]/18 bg-[#0c0c0e]/30 relative z-[1]">
                        <button
                            type="button"
                            data-testid="field-tasks-manage-all"
                            tabIndex={layerVisible ? 0 : -1}
                            onClick={(e) => {
                                e.stopPropagation();
                                onManageAll();
                            }}
                            className={CURTAIN_BTN_MANAGE}
                        >
                            عرض وإدارة جميع المهام ←
                        </button>
                    </div>
                </div>
            </div>
        </>,
        document.body,
    );
});

import React, { useEffect, useState } from 'react';
import { Plus, X } from 'lucide-react';
import { JURISDICTIONS, type JurisdictionId } from '@/app/components/lawyer/LawyerNewCase/wordLists';
import { prefetchLawyerNewCaseModule } from '@/app/runtime/lawyerNewCaseLoader';
import { CIVIL_LAWSUIT_TEST_IDS } from '@/app/components/lawyer/smart-modal/smartFile/civilLawsuitTestIds';
import type { LawsuitsAddCaseFabTone } from './LawsuitsWorkspaceShell';

function prefetchJurisdictionChunk(id: JurisdictionId) {
    if (id === 'criminal') {
        void import('@/app/components/lawyer/criminal-system/criminalStore');
        void import('@/app/components/lawyer/criminal-system/CriminalNewCase');
    }
    if (id === 'personal') {
        void import('@/app/components/lawyer/personal-status/PersonalStatusNewCaseForm');
        void import('@/app/utils/personalStatusLawRemoteCache');
    }
    if (id === 'civil') {
        void import('@/app/components/lawyer/LawyerNewCase/components/CivilNewCaseForm');
        void import('@/app/utils/civilLawRemoteCache').then((m) =>
            m.prefetchCivilLawArticles(['civil_procedure', 'evidence']),
        );
    }
}

/**
 * زر إضبارة جديدة + انبثاق الخيارات من موضع الزر (بدون حاوية وسطية).
 */
export function LawsuitsAddCaseFabWithPicker({
    onSelect,
    onIntent,
    label = 'إضبارة جديدة',
    tone = 'gold',
    testId = CIVIL_LAWSUIT_TEST_IDS.addLawsuit,
}: {
    onSelect: (id: JurisdictionId) => void;
    onIntent?: () => void;
    label?: string;
    tone?: LawsuitsAddCaseFabTone;
    testId?: string;
}): React.ReactElement {
    const [open, setOpen] = useState(false);
    const [reduceMotion, setReduceMotion] = useState(false);

    useEffect(() => {
        const mq = window.matchMedia('(prefers-reduced-motion: reduce)');
        const update = () => setReduceMotion(mq.matches);
        update();
        mq.addEventListener('change', update);
        return () => mq.removeEventListener('change', update);
    }, []);

    useEffect(() => {
        if (!open) return;
        prefetchLawyerNewCaseModule();
    }, [open]);

    useEffect(() => {
        if (!open) return;
        const onKeyDown = (event: KeyboardEvent) => {
            if (event.key !== 'Escape') return;
            event.preventDefault();
            event.stopPropagation();
            setOpen(false);
        };
        window.addEventListener('keydown', onKeyDown, true);
        return () => window.removeEventListener('keydown', onKeyDown, true);
    }, [open]);

    const toneClass =
        tone === 'urgent'
            ? 'border-rose-400/50 bg-gradient-to-r from-rose-600 to-red-600 text-white shadow-lg shadow-rose-900/40'
            : open
              ? 'border-[#E6C673]/55 bg-[linear-gradient(155deg,rgba(230,198,115,0.52)_0%,rgba(11,16,33,0.94)_48%,rgba(201,162,39,0.34)_100%)] text-[#FFF8E8] shadow-[inset_0_1px_0_rgba(255,249,230,0.32),0_12px_32px_rgba(0,0,0,0.4)]'
              : 'border-[#E6C673]/50 bg-[linear-gradient(155deg,rgba(230,198,115,0.42)_0%,rgba(11,16,33,0.92)_48%,rgba(201,162,39,0.28)_100%)] text-[#F8F1DE] shadow-[inset_0_1px_0_rgba(255,249,230,0.28),0_10px_28px_rgba(0,0,0,0.35)]';

    const handleToggle = () => {
        onIntent?.();
        setOpen((value) => !value);
    };

    const handleSelect = (id: JurisdictionId) => {
        setOpen(false);
        onSelect(id);
    };

    return (
        <>
            {open ? (
                <button
                    type="button"
                    className={`fixed inset-0 z-[49] bg-[#03050B]/28 backdrop-blur-[2px] transition-opacity${reduceMotion ? '' : ' animate-[lawsuitsBackdrop_0.22s_ease-out]'}`}
                    onClick={() => setOpen(false)}
                    aria-label="إغلاق"
                />
            ) : null}

            <div className="relative z-[55] flex flex-col items-end">
                {open ? (
                    <div
                        className="mb-2.5 flex w-[min(calc(100vw-2.5rem),17.5rem)] flex-col gap-2"
                        data-testid={CIVIL_LAWSUIT_TEST_IDS.jurisdictionPicker}
                        role="menu"
                        aria-label="اختصاص الدعوى"
                    >
                        {JURISDICTIONS.map((item, index) => (
                            <button
                                key={item.id}
                                type="button"
                                role="menuitem"
                                data-testid={`new-case-jurisdiction-${item.id}`}
                                onClick={() => handleSelect(item.id)}
                                onPointerEnter={() => prefetchJurisdictionChunk(item.id)}
                                onFocus={() => prefetchJurisdictionChunk(item.id)}
                                className={`group w-full min-h-[3.25rem] rounded-2xl border border-white/[0.11] bg-white/[0.04] px-5 py-3.5 text-right backdrop-blur-xl shadow-[0_10px_32px_rgba(0,0,0,0.26),inset_0_1px_0_rgba(255,255,255,0.06)] transition-[background-color,border-color,transform,box-shadow] duration-200 hover:border-[#E6C673]/30 hover:bg-white/[0.085] hover:shadow-[0_12px_36px_rgba(0,0,0,0.32),inset_0_1px_0_rgba(255,255,255,0.09)] active:scale-[0.98]${reduceMotion ? '' : ' animate-[lawsuitsBloom_0.4s_cubic-bezier(0.22,1,0.36,1)_both]'}`}
                                style={
                                    reduceMotion
                                        ? { transformOrigin: 'bottom right' }
                                        : {
                                              animationDelay: `${index * 46}ms`,
                                              transformOrigin: 'bottom right',
                                          }
                                }
                            >
                                <span className="block text-[0.95rem] font-bold text-white/[0.88] transition-colors group-hover:text-[#F4EDE0]">
                                    {item.title}
                                </span>
                            </button>
                        ))}
                    </div>
                ) : null}

                <button
                    type="button"
                    data-testid={testId}
                    onClick={handleToggle}
                    onPointerEnter={() => onIntent?.()}
                    onFocus={() => onIntent?.()}
                    title={open ? 'إغلاق' : `إضافة ${label}`}
                    aria-label={open ? 'إغلاق اختيار الاختصاص' : `إضافة ${label}`}
                    aria-expanded={open}
                    aria-haspopup="menu"
                    className={`inline-flex h-12 w-auto shrink-0 items-center justify-center gap-2 rounded-full border px-4 text-sm font-bold backdrop-blur-md touch-manipulation transition-all duration-200 hover:scale-[1.03] active:scale-95 ${toneClass}`}
                >
                    {open ? <X size={18} strokeWidth={2.5} aria-hidden /> : <Plus size={18} strokeWidth={3} aria-hidden />}
                    <span className="whitespace-nowrap">{open ? 'إغلاق' : label}</span>
                </button>
            </div>

            <style>{`
                @keyframes lawsuitsBloom {
                    0% {
                        opacity: 0;
                        transform: translateY(10px) scale(0.88);
                        filter: blur(4px);
                    }
                    100% {
                        opacity: 1;
                        transform: translateY(0) scale(1);
                        filter: blur(0);
                    }
                }
                @keyframes lawsuitsBackdrop {
                    from { opacity: 0; }
                    to { opacity: 1; }
                }
            `}</style>
        </>
    );
}

