    /** معاينة تاريخية — منع فتح الشارات والتعديل */
    isHistoricalMode?: boolean;
    /** داخل صف موحّد مع شارات المحجوزات — بدون غلاف flex منفصل */
    embeddedInRow?: boolean;
    /** حالة حضور محلية — تسبق executionData عند التسجيل الفوري */
