            (a, b) =>
                String(b.date).localeCompare(String(a.date)) ||
                String(b.savedAt || '').localeCompare(String(a.savedAt || ''))
        );
    }, [entries]);

    const latestTrackedEntry = useMemo(() => {
        if (!exId || sorted.length === 0) return null;
        for (const entry of sorted) {
