    const investigationButtonDisabled =
        isHistoricalMode ||
        coerciveUiLocked ||
        arrest.alternative ||
        ((arrestStage === 'issued' || wanted) && warrantCustodyRecorded);

    const travelButtonLabel = travel.pending
        ? 'منع سفر — قيد البت'
        : travel.alternative
          ? 'منع سفر — قرار بديل'
          : travelShowLiftAction
            ? 'رفع منع السفر'
            : travelBanEnforced && !travelBanWithdrawn
