                            aria-modal="true"
                            className="w-full max-w-sm rounded-2xl border border-rose-500/30 bg-[#0A0F1C] p-4 shadow-2xl text-right space-y-3 pointer-events-auto"
                            onMouseDown={(e) => e.stopPropagation()}
                        >
                            <div className="flex items-center justify-between gap-2 flex-row-reverse border-b border-white/10 pb-2">
                                <p className="text-sm font-bold text-rose-100">تحذير</p>
                                <button
                                    type="button"
                                    aria-label="إغلاق"
                                    className="rounded-lg p-1.5 text-slate-400 hover:bg-white/10 hover:text-white disabled:opacity-40"
                                    disabled={releaseConfirmBusy}
                                    onClick={() => setReleaseConfirmOpen(false)}
                                >
                                    <X size={18} />
                                </button>
                            </div>
                            <p className="text-[12px] leading-relaxed text-rose-100/95">
                                تحذير: يُنهى مسار الحبس التنفيذي وعرض الإضبارة الحالي فقط. الإحضار الجبري ومنع السفر
                                والمفاتحة يبقون كما هي. لا يمكن الرجوع عن إخلاء السبيل.
                            </p>
                            <div className="grid grid-cols-2 gap-2 pt-1">
                                <button
                                    type="button"
                                    disabled={releaseConfirmBusy}
                                    className="rounded-xl bg-slate-800 py-2.5 text-[11px] font-bold text-slate-100 hover:bg-slate-700 disabled:opacity-50"
                                    onClick={() => setReleaseConfirmOpen(false)}
                                >
                                    تراجع
                                </button>
                                <button
                                    type="button"
                                    disabled={releaseConfirmBusy}
                                    className="rounded-xl border border-rose-500/45 bg-rose-950/40 py-2.5 text-[11px] font-black text-rose-100 hover:bg-rose-950/55 disabled:opacity-50"
                                    onClick={() => {
                                        if (releaseConfirmBusy) return;
                                        setReleaseConfirmBusy(true);
                                        setReleaseConfirmOpen(false);
                                        const nowIso = new Date().toISOString();
                                        const releasePatch = buildReleaseDetentionPatch();
                                        persistExecutionMerge(releasePatch);
                                        pushTimelineEvent(
                                            {
                                                id: nextTimelineId(),
                                                date: getLocalTodayYmd(),
                                                timestamp: nowIso,
                                                title: 'تم إخلاء سبيل المدين — انتهاء مسار الحبس التنفيذي',
                                                description:
                                                    'أُنهيت دورة الحبس وعرض الإضبارة فقط؛ باقي الإجراءات الجبرية (إحضار، منع سفر، مفاتحة) لم تُمس.',
                                                type: 'coercive',
                                                source: 'محضر المتابعة',
                                                metadata: debtorTimelineMeta,
                                            },
                                            { mergePatch: releasePatch }
                                        );
                                        archiveExecutiveDetentionCycleDecisions({
                                            executionId: exId,
                                            debtorKey: activeDebtorKey,
                                            primaryDebtorKey,
                                        });
                                        setDetentionRejectionOpen(false);
                                        setDetentionRejectionReason('');
                                        goBackToPersonalCoerciveHub();
                                        setLocalDecisionsTick((n) => n + 1);
                                        showToast(
                                            'تم إخلاء السبيل — يمكنك تقديم طلب عرض إضبارة جديد عند الحاجة.',
                                            'success'
                                        );
                                        setReleaseConfirmBusy(false);
                                    }}
                                >
                                    تأكيد إخلاء السبيل
                                </button>
                            </div>
                        </div>
            </PersonalCoerciveFollowUpPortal>

            <PersonalCoerciveFollowUpPortal
                open={forcedBringWithdrawConfirmOpen}
                dismissDisabled={forcedBringWithdrawBusy}
                onDismiss={() => setForcedBringWithdrawConfirmOpen(false)}
            >
                <div
                    role="dialog"
                    aria-modal="true"
                    className="w-full max-w-sm rounded-2xl border border-amber-500/30 bg-[#0A0F1C] p-4 shadow-2xl text-right space-y-3 pointer-events-auto"
                    onMouseDown={(e) => e.stopPropagation()}
                >
                    <div className="flex items-center justify-between gap-2 flex-row-reverse border-b border-white/10 pb-2">
                        <p className="text-sm font-bold text-amber-100">تنازل عن مفاتحة التحقيق</p>
                        <button
                            type="button"
                            aria-label="إغلاق"
                            className="rounded-lg p-1.5 text-slate-400 hover:bg-white/10 hover:text-white disabled:opacity-40"
                            disabled={forcedBringWithdrawBusy}
                            onClick={() => setForcedBringWithdrawConfirmOpen(false)}
                        >
                            <X size={18} />
                        </button>
                    </div>
                    <p className="text-[12px] leading-relaxed text-amber-100/95">
                        سيتم سحب طلب مفاتحة محكمة التحقيق (إن وُجد) وإخفاء بطاقتها، وإعادة تفعيل تسجيل نتيجة الإحضار
                        الجبري. لن تظهر بطاقة المفاتحة مجدداً إلا بعد تسجيل «المدين متخفي» من جديد.
                    </p>
                    <div className="grid grid-cols-2 gap-2 pt-1">
                        <button
                            type="button"
                            disabled={forcedBringWithdrawBusy}
                            className="rounded-xl bg-slate-800 py-2.5 text-[11px] font-bold text-slate-100 hover:bg-slate-700 disabled:opacity-50"
                            onClick={() => setForcedBringWithdrawConfirmOpen(false)}
                        >
                            إلغاء
                        </button>
                        <button
                            type="button"
                            disabled={forcedBringWithdrawBusy}
                            className="rounded-xl border border-amber-500/45 bg-amber-950/40 py-2.5 text-[11px] font-black text-amber-100 hover:bg-amber-950/55 disabled:opacity-50"
                            onClick={() => withdrawInvestigationCourtPath()}
                        >
                            تأكيد التنازل
                        </button>
                    </div>
                </div>
            </PersonalCoerciveFollowUpPortal>

            {/* 1 — إحضار جبري */}
            {showEmbeddedSection('forced_bring_in') ? (
            <div className="relative space-y-2">
            <div
                className={`overflow-visible rounded-2xl border border-violet-500/25 bg-violet-950/15 text-right ${kasabCoerciveEmphasis ? 'ring-2 ring-[#E6C673]/45 border-[#E6C673]/35' : ''}`}
            >
                <div className="relative">
                    {forcedHasExpandablePanel ? (
                        <div
                            className={`w-full ${BTN_BASE} bg-gradient-to-l from-violet-500/12 to-transparent`}
                        >
                            <div className="flex flex-row-reverse items-center gap-3">
                                <span className="flex h-12 w-12 items-center justify-center rounded-2xl bg-white/5">
                                    <Gavel className="h-6 w-6 text-white/70" />
                                </span>
                                <div className="min-w-0 flex-1">
                                    <p className="text-sm font-bold text-white">{forcedButtonLabel}</p>
                                </div>
                            </div>
                        </div>
                    ) : (
                        <button
                            type="button"
                            onClick={() => {
                                if (canWithdrawInvestigationPath) {
                                    setForcedBringWithdrawConfirmOpen(true);
                                    return;
                                }
                                if (forcedButtonDisabled) return;
                                if (!relaxedPersonal && !guardSummonsGate()) return;
                                if (forcedShowStartStrip) return;
                            }}
                            disabled={
                                (forcedButtonDisabled && !forcedHasExpandablePanel) ||
                                (forcedShowStartStrip && !forcedHasExpandablePanel)
                            }
                            className={`w-full ${BTN_BASE} bg-gradient-to-l from-violet-500/12 to-transparent hover:from-violet-500/18 ${(forcedButtonDisabled && !forcedHasExpandablePanel) || (forcedShowStartStrip && !forcedHasExpandablePanel) ? BTN_DISABLED : ''}`}
                        >
                            <div className="flex flex-row-reverse items-center gap-3">
                                <span className="flex h-12 w-12 items-center justify-center rounded-2xl bg-white/5">
                                    <Gavel className="h-6 w-6 text-white/70" />
                                </span>
                                <div className="min-w-0 flex-1">
                                    <p className="text-sm font-bold text-white">{forcedButtonLabel}</p>
                                </div>
                            </div>
                        </button>
                    )}
                    {forcedEffective.pending ? (
                        <div className="border-t border-white/10 px-3 py-3">
                            <CoerciveSubsectionFold
                                flat
                                title="طلب الإحضار الجبري — قيد البت لدى المنفذ"
                                titleClassName="text-amber-100"
                            >
                                <p className="text-[10px] leading-relaxed text-amber-200/75 text-right">
                                    تم إرسال الطلب — بانتظار موافقة أو رفض المنفذ العدل.
                                </p>
                                <ExecutionInlineExecutorDecisionActions
                                    executionId={exId}
                                    decisionId={findLatestDecisionIdForSubtype('forced_bring_in') || ''}
                                    decisionRow={findLatestDecisionRowForSubtype('forced_bring_in')}
                                    requestKind="personal_coercive"
                                    personalCoerciveSubtype="forced_bring_in"
                                    suppressNavigatorToast
                                    onResolved={handleExecutorInlineResolved}
                                />
                            </CoerciveSubsectionFold>
                        </div>
                    ) : null}

                    {renderAppealSyncFollowup(forcedSync)}

                    {forcedEffective.rejected &&
                    !isExecutorRejectedAppealFollowupDismissed(
                        findLatestDecisionIdForSubtype('forced_bring_in'),
                        allDecisionRows
                    ) ? (
                        <div className="border-t border-white/10 px-3 pb-3 pt-2">
                            {renderRejectedExecutorAppealSection({
                                decisionId: findLatestDecisionIdForSubtype('forced_bring_in'),
                                personalCoerciveSubtype: 'forced_bring_in',
                            })}
                        </div>
                    ) : null}

                    {forcedShowStartStrip ? (
                        <div className="space-y-2 border-t border-white/10 px-3 pb-3 pt-2">
                                <button
                                    type="button"
                                    disabled={sendingKey === 'forced_bring_in'}
                                    onClick={(e) => {
                                        e.stopPropagation();
                                        runForcedBringSubmit(true);
                                    }}
                                    className="group w-full rounded-xl border border-[#E6C673]/35 bg-gradient-to-l from-amber-500/18 via-amber-600/10 to-violet-950/20 py-3 text-[11px] font-black text-amber-100 shadow-[inset_0_1px_0_rgba(255,255,255,0.06)] transition-all hover:border-[#E6C673]/55 hover:from-amber-500/28 hover:shadow-[0_0_24px_rgba(230,198,115,0.12)] disabled:opacity-50"
                                >
                                    <span className="flex flex-row-reverse items-center justify-center gap-2">
                                        <Gavel
                                            size={15}
                                            className="text-[#E6C673]/85 transition-colors group-hover:text-[#E6C673]"
                                        />
                                        تفعيل بقرار المنفذ العدل
                                    </span>
                                </button>
                                <RejectedExecutorResubmitStrip
                                    showReplaceHint={hasOpenCardForSubtype('forced_bring_in')}
                                    submitting={sendingKey === 'forced_bring_in'}
                                    disabled={sendingKey === 'forced_bring_in'}
                                    onConfirmSubmit={() => {
                                        if (!relaxedPersonal && !guardSummonsGate()) return;
                                        if (!relaxedPersonal && !forcedSummonAllowed) {
                                            showToast(
                                                forcedSummonLockReason ||
                                                    'غير مسموح بالإحضار الجبري وفقاً للوضع القانوني الحالي.',
                                                'warning',
                                                {
                                                    action: {
                                                        label: 'مركز التبليغات',
                                                        onClick: () => onOpenSummonsCenter(),
                                                    },
                                                }
                                            );
                                            return;
                                        }
                                        runForcedBringSubmit(false);
                                    }}
                                />
                        </div>
                    ) : null}

                    {forcedFlowStep === 'outcome_choice' ? (
                        <div className="border-t border-white/10 px-3 pb-2 pt-3 space-y-3 text-right">
                            <div className="space-y-1.5 border-b border-white/10 pb-2">
                                <p className="text-[10px] font-bold text-emerald-200/90">
                                    {forcedByExecutorOrder
                                        ? '✓ بناء على قرار المنفذ العدل'
                                        : '✓ طلب إحضار جبري — تم الإرسال'}
                                </p>
                                {!forcedByExecutorOrder ? (
                                    <p className="text-[10px] font-bold text-emerald-200/90">
                                        ✓ قرار المنفذ — تمت الموافقة
                                    </p>
                                ) : null}
                                <p className="text-[10px] text-slate-500">
                                    {forcedByExecutorOrder
                                        ? 'الخطوة التالية: تسجيل نتيجة التنفيذ الميداني — والمدين هو الطاعن في بطاقة القرارات عند الحاجة.'
                                        : 'الخطوة التالية: تسجيل نتيجة التنفيذ الميداني.'}
                                </p>
                            </div>
                            <div className="space-y-2">
                                <p className="text-[11px] font-black text-amber-100">تسجيل النتيجة</p>
                                <p className="text-[10px] text-slate-400">اختر أحد الخيارين ثم أكّد</p>
                                <div
                                    className="grid grid-cols-1 gap-2"
                                    role="radiogroup"
                                    aria-label="نتيجة الإحضار الجبري"
                                >
                                    <button
                                        type="button"
                                        disabled={coerciveUiLocked}
                                        aria-pressed={forcedOutcomePick === 'brought'}
                                        onClick={(e) => {
                                            e.stopPropagation();
                                            setForcedOutcomePick('brought');
                                        }}
                                        className={`w-full rounded-xl border px-3 py-2.5 text-[11px] font-bold transition ${
                                            forcedOutcomePick === 'brought'
                                                ? 'border-emerald-500/50 bg-emerald-950/45 text-emerald-100 ring-1 ring-emerald-500/35'
                                                : 'border-white/10 bg-[#0A0F1C]/80 text-slate-200 hover:border-emerald-500/30 hover:bg-emerald-950/25'
                                        } disabled:opacity-40`}
                                    >
                                        تم إحضار المدين
                                    </button>
                                    <button
                                        type="button"
                                        disabled={coerciveUiLocked}
                                        aria-pressed={forcedOutcomePick === 'absconded'}
                                        onClick={(e) => {
                                            e.stopPropagation();
                                            setForcedOutcomePick('absconded');
                                        }}
                                        className={`w-full rounded-xl border px-3 py-2.5 text-[11px] font-bold transition ${
                                            forcedOutcomePick === 'absconded'
                                                ? 'border-rose-500/45 bg-rose-950/40 text-rose-100 ring-1 ring-rose-500/35'
                                                : 'border-white/10 bg-[#0A0F1C]/80 text-slate-200 hover:border-rose-500/30 hover:bg-rose-950/25'
                                        } disabled:opacity-40`}
                                    >
                                        المدين متخفي عن الأنظار
                                    </button>
                                </div>
                                <button
                                    type="button"
                                    disabled={!forcedOutcomePick || coerciveUiLocked}
                                    className="w-full rounded-xl bg-gradient-to-l from-amber-500 to-yellow-600 py-2.5 text-[11px] font-black text-[#0A0F1C] disabled:opacity-40"
                                    onClick={(e) => {
                                        e.stopPropagation();
                                        if (
                                            forcedOutcomePick !== 'brought' &&
                                            forcedOutcomePick !== 'absconded'
                                        ) {
                                            return;
                                        }
                                        recordForcedOutcome(forcedOutcomePick);
                                        setForcedOutcomePick('');
                                    }}
                                >
                                    تأكيد التسجيل
                                </button>
                            </div>
                        </div>
                    ) : null}
                </div>
            </div>
            </div>
            ) : null}

            {/* 2 — مفاتحة تحقيق */}
            {showEmbeddedSection('arrest_warrant_investigation') && showInvestigationBlock ? (
                <div className="overflow-visible rounded-2xl border border-violet-500/25 bg-violet-950/15 text-right">
                    <div className="relative">
                        <button
                            type="button"
                            onClick={() => {
                                if (investigationButtonDisabled) return;
                                if (arrest.rejected) return;
                                if (investigationHasExpandablePanel) {
                                    return;
                                }
                                if (!guardSummonsGate()) return;
                                setConfirmingKey('arrest_warrant_investigation');
                            }}
                            disabled={investigationButtonDisabled && !investigationHasExpandablePanel}
                            className={`w-full ${BTN_BASE} bg-gradient-to-l from-rose-500/12 to-transparent hover:from-rose-500/18 ${investigationButtonDisabled && !investigationHasExpandablePanel ? BTN_DISABLED : ''}`}
                        >
                            <div className="flex flex-row-reverse items-center gap-3">
                                <span className="flex h-12 w-12 items-center justify-center rounded-2xl bg-white/5">
                                    <ShieldAlert className="h-6 w-6 text-white/70" />
                                </span>
                                <div className="min-w-0 flex-1">
                                    <p className="text-sm font-bold text-white">{investigationButtonLabel}</p>
                                </div>
                            </div>
                        </button>

                        {investigationFlowStep === 'followup_blocked'
                            ? renderAppealSyncFollowup(arrestSync)
                            : null}

                        {investigationFlowStep === 'executor_pending' ? (
                            <div className="border-t border-white/10 px-3 py-3">
                                <CoerciveSubsectionFold
                                    flat
                                    title="طلب المفاتحة — قيد البت لدى المنفذ"
                                    titleClassName="text-amber-100"
                                >
                                    <ExecutionInlineExecutorDecisionActions
                                        executionId={exId}
                                        decisionId={
                                            findLatestDecisionIdForSubtype('arrest_warrant_investigation') || ''
                                        }
                                        decisionRow={findLatestDecisionRowForSubtype(
                                            'arrest_warrant_investigation'
                                        )}
                                        requestKind="personal_coercive"
                                        personalCoerciveSubtype="arrest_warrant_investigation"
                                        suppressNavigatorToast
                                        onResolved={handleExecutorInlineResolved}
                                    />
                                </CoerciveSubsectionFold>
                            </div>
                        ) : null}

                        {renderInlineGate('arrest_warrant_investigation', () => {
                            setSendingKey('arrest_warrant_investigation');
                            void submitRequest(
                                'arrest_warrant_investigation',
                                'طلب مفاتحة محكمة التحقيق لإصدار أمر قبض',
                                'بعد تعذّر الإحضار الجبري وتخلّف المدين عن المثول، طُلب توجيه كتاب مفاتحة لمحكمة التحقيق المختصة لإصدار أمر قبض أصولي.'
                            ).then(() => {
                                setSendingKey(null);
                                setConfirmingKey(null);
                            });
                        })}

                        {arrest.rejected &&
                        !isExecutorRejectedAppealFollowupDismissed(
                            findLatestDecisionIdForSubtype('arrest_warrant_investigation'),
                            allDecisionRows
                        ) ? (
                            <div className="border-t border-white/10 px-3 pb-3 pt-2">
                                {renderRejectedExecutorAppealSection({
                                    decisionId: findLatestDecisionIdForSubtype('arrest_warrant_investigation'),
                                    personalCoerciveSubtype: 'arrest_warrant_investigation',
                                })}
                            </div>
                        ) : null}

                        {investigationFlowStep === 'outcome_choice' ? (
                            <div className="relative z-10 mx-3 mb-2 mt-2 space-y-3 rounded-2xl border border-white/10 bg-black/15 px-3 pb-3 pt-3 text-right">
                                <div className="space-y-1 border-b border-white/10 pb-2">
                                    <p className="text-[11px] font-black text-amber-100">
                                        مفاتحة محكمة التحقيق — بعد موافقة المنفذ
                                    </p>
                                    <p className="text-[10px] text-slate-400">اختر النتيجة المناسبة.</p>
                                </div>
                                <div className="grid grid-cols-1 gap-2">
                                    <button
                                        type="button"
                                        disabled={coerciveUiLocked}
                                        className="w-full rounded-xl border border-rose-500/40 bg-rose-950/40 py-2.5 text-[11px] font-bold text-rose-100 disabled:opacity-40"
                                        onClick={() => markWarrantIssued()}
                                    >
                                        تم إصدار مذكرة قبض
                                    </button>
                                    <button
                                        type="button"
                                        disabled={coerciveUiLocked}
                                        className="w-full rounded-xl border border-emerald-500/35 bg-emerald-800/55 py-2.5 text-[11px] font-bold text-white disabled:opacity-40"
                                        onClick={() => recordInvestigationDebtorAttended()}
                                    >
                                        حضور المدين
                                    </button>
                                </div>
                            </div>
                        ) : null}

                        {investigationFlowStep === 'warrant_custody' ? (
                            <div className="relative z-10 mx-3 mb-2 mt-2 space-y-3 rounded-2xl border border-white/10 bg-black/15 px-3 pb-3 pt-3 text-right">
                                <div className="space-y-1 border-b border-white/10 pb-2">
                                    <p className="text-[11px] font-black text-rose-100">مذكرة قبض — تأمين الإحضار</p>
                                    <p className="text-[10px] text-slate-400">
                                        بعد صدور المذكرة، سجّل تأمين الإحضار لإغلاق الدورة.
                                    </p>
                                </div>
                                <button
                                    type="button"
                                    disabled={coerciveUiLocked}
                                    className="w-full rounded-xl border border-emerald-500/35 bg-emerald-800/55 py-2.5 text-[11px] font-bold text-white disabled:opacity-40"
                                    onClick={() => recordSecuredBringAfterWarrant()}
                                >
                                    تم تأمين إحضار
                                </button>
                            </div>
                        ) : null}
                    </div>
                </div>
            ) : null}

            {showOptionalRemainingProceduresEntry ? (
                <div className="relative pt-1">
                    <button
                        type="button"
                        disabled={coerciveUiLocked || isHistoricalMode}
                        onClick={() => setOptionalRemainingProceduresOpen(true)}
                        className={`w-full ${BTN_BASE} bg-gradient-to-l from-violet-500/10 to-transparent hover:from-violet-500/16 ${coerciveUiLocked || isHistoricalMode ? BTN_DISABLED : ''}`}
                    >
                        <div className="flex flex-row-reverse items-center gap-3">
                            <span className="flex h-12 w-12 items-center justify-center rounded-2xl bg-white/5">
                                <ChevronDown className="h-6 w-6 text-violet-200/80" />
                            </span>
                            <div className="min-w-0 flex-1 text-right">
                                <p className="text-sm font-bold text-violet-100">
                                    إظهار الإجراءات المتبقية
                                </p>
                                <p className="mt-0.5 text-[10px] text-slate-400">
                                    خطوة اختيارية: منع سفر أو طلب عرض الإضبارة على قاضي البداءة
                                </p>
                            </div>
                        </div>
                    </button>
                </div>
            ) : null}

            {/* 3 — منع سفر */}
            {showTravelBanInMainFlow ? (
            <div className="relative space-y-2">
            <div className="overflow-visible rounded-2xl border border-violet-500/25 bg-violet-950/15 text-right">
                <div className="relative">
                    {travelShowInitialSubmit ? (
                        <button
                            type="button"
                            disabled={travelSubmitButtonDisabled}
                            onClick={() => {
                                if (travelSubmitButtonDisabled) return;
                                if (!canSubmitTravelBan) return;
                                setConfirmingKey('travel_ban');
                            }}
                            className={`w-full ${BTN_BASE} bg-gradient-to-l from-sky-500/12 to-transparent hover:from-sky-500/18 ${travelSubmitButtonDisabled ? BTN_DISABLED : ''}`}
                        >
                            <div className="flex flex-row-reverse items-center gap-3">
                                <span className="flex h-12 w-12 items-center justify-center rounded-2xl bg-white/5">
                                    <Plane className="h-6 w-6 text-white/70" />
                                </span>
                                <div className="min-w-0 flex-1">
                                    <p className="text-sm font-bold text-sky-100">{travelButtonLabel}</p>
                                </div>
                            </div>
                        </button>
                    ) : travelEnforcedSettled ? (
                        <details
                            open={travelPanelOpen}
                            onToggle={(e) =>
                                setTravelPanelOpen((e.target as HTMLDetailsElement).open)
                            }
                            className="group/travel text-right"
                        >
                            <summary className="flex cursor-pointer list-none flex-row-reverse items-center justify-between gap-2 px-4 py-3.5 transition-colors hover:bg-white/[0.03] [&::-webkit-details-marker]:hidden">
                                <span className="flex flex-row-reverse items-center gap-3 min-w-0">
                                    <span className="flex h-12 w-12 shrink-0 items-center justify-center rounded-2xl bg-white/5">
                                        <Plane className="h-6 w-6 text-white/70" />
                                    </span>
                                    <span className="text-sm font-bold text-sky-100">منع سفر — مفعّل</span>
                                </span>
                                <ChevronDown
                                    size={18}
                                    className="shrink-0 text-slate-400 transition-transform duration-200 group-open/travel:rotate-180"
                                    aria-hidden
                                />
                            </summary>
                            <div className="space-y-2 border-t border-white/10 px-3 pb-3 pt-2">
                                <p className="text-[11px] font-bold text-emerald-200">
                                    تمت الموافقة فعلاً على منع المدين من السفر.
                                </p>
                                {travelAppealFollowupVisible ? renderAppealSyncFollowup(travelSync) : null}
                                {travelShowLiftAction ? (
                                    <button
                                        type="button"
                                        onClick={() => liftTravelBanEnforcement()}
                                        className="w-full rounded-xl border border-sky-400/35 bg-sky-800/45 py-2.5 text-[11px] font-bold text-sky-50 hover:bg-sky-800/60"
                                    >
                                        رفع إشارة منع السفر
                                    </button>
                                ) : debtRemainingIqd > 0 ? (
                                    <p className="text-[10px] text-sky-200/75">
                                        يُرفع منع السفر تلقائياً بعد سداد الدين بالكامل.
                                    </p>
                                ) : null}
                                <button
                                    type="button"
                                    disabled={coerciveUiLocked || isHistoricalMode}
                                    onClick={() => setConfirmingKey('travel_ban_withdraw')}
                                    className="w-full rounded-xl border border-amber-500/35 bg-amber-500/10 py-2.5 text-[11px] font-bold text-amber-100 hover:bg-amber-500/15 disabled:opacity-40"
                                >
                                    التراجع عن الطلب
                                </button>
                            </div>
                        </details>
                    ) : travelShowLiftAction ? (
                        <button
                            type="button"
                            onClick={() => liftTravelBanEnforcement()}
                            className={`w-full ${BTN_BASE} bg-gradient-to-l from-sky-500/12 to-transparent hover:from-sky-500/18`}
                        >
                            <div className="flex flex-row-reverse items-center gap-3">
                                <span className="flex h-12 w-12 items-center justify-center rounded-2xl bg-white/5">
                                    <Plane className="h-6 w-6 text-white/70" />
                                </span>
                                <div className="min-w-0 flex-1">
                                    <p className="text-sm font-bold text-sky-100">{travelButtonLabel}</p>
                                </div>
                            </div>
                        </button>
                    ) : (
                        <div className={`w-full ${BTN_BASE} bg-gradient-to-l from-sky-500/12 to-transparent`}>
                            <div className="flex flex-row-reverse items-center gap-3">
                                <span className="flex h-12 w-12 items-center justify-center rounded-2xl bg-white/5">
                                    <Plane className="h-6 w-6 text-white/70" />
                                </span>
                                <div className="min-w-0 flex-1">
                                    <p className="text-sm font-bold text-sky-100">{travelButtonLabel}</p>
                                </div>
                            </div>
                        </div>
                    )}

                    {!travelEnforcedSettled && travelAppealFollowupVisible
                        ? renderAppealSyncFollowup(travelSync)
                        : null}

                    {!travelBanWithdrawn &&
                    travelCycleActive &&
                    (travel.pending ||
                        (travel.rejected &&
                            !isExecutorRejectedAppealFollowupDismissed(
                                findLatestDecisionIdForSubtype('travel_ban'),
                                allDecisionRows
                            ))) ? (
                        <div className="border-t border-white/10 px-3 pb-3 pt-2">
                            {travel.rejected ? (
                                renderRejectedExecutorAppealSection({
                                    decisionId: findLatestDecisionIdForSubtype('travel_ban'),
                                    personalCoerciveSubtype: 'travel_ban',
                                })
                            ) : (
                                <CoerciveSubsectionFold
                                    flat
                                    title="طلب منع السفر — قيد البت لدى المنفذ"
                                    titleClassName="text-sky-100"
                                >
                                    <ExecutionInlineExecutorDecisionActions
                                        executionId={exId}
                                        decisionId={findLatestDecisionIdForSubtype('travel_ban') || ''}
                                        decisionRow={findLatestDecisionRowForSubtype('travel_ban')}
                                        requestKind="personal_coercive"
                                        personalCoerciveSubtype="travel_ban"
                                        suppressNavigatorToast
                                        onResolved={handleExecutorInlineResolved}
                                    />
                                </CoerciveSubsectionFold>
                            )}
                        </div>
                    ) : null}

                    {travel.alternative ? (
                        <div className="border-t border-white/10 px-3 pb-3 pt-2">
                            <p className="text-[10px] text-sky-200/90">
                                🔄 سُجّل قرار بديل للمنفذ — راجع المهام ومحضر المتابعة.
                            </p>
                        </div>
                    ) : null}
                    {renderInlineGate('travel_ban', () => {
                        if (!guardSummonsGate()) {
                            setConfirmingKey(null);
                            return;
                        }
                        setSendingKey('travel_ban');
                        if (travel.pending || travel.rejected) {
                            setSendingKey(null);
                            setConfirmingKey(null);
                            return;
                        }
                        void submitRequest(
                            'travel_ban',
                            scopedRequestTitle('طلب وضع إشارة منع سفر على المدين'),
                            'طلب توجيه كتاب إلى مديرية الجوازات والإقامة لمنع سفر المدين لحين البتّ في التنفيذ.'
                        ).then(() => {
                            setSendingKey(null);
                            setConfirmingKey(null);
                        });
                    })}
                    {renderInlineGate(
                        'travel_ban_withdraw',
                        () => withdrawTravelBanRequestCycle(),
                        {
                            confirmLabel: 'تأكيد التراجع',
                            gateExtra: (
                                <p className="text-[10px] leading-relaxed text-amber-100/90">
                                    يُغلق طلب منع السفر الحالي وتعود دورة التقديم. تبقى إشارة المنع
                                    مفعّلة حتى سداد الدين بالكامل.
                                </p>
                            ),
                        }
                    )}
                </div>
            </div>
            {travelBanRequestCycleWithdrawn && travelBanEnforced && travelShowLiftAction ? (
                <div className="px-1">
                    <button
                        type="button"
                        onClick={() => liftTravelBanEnforcement()}
                        className="w-full rounded-xl border border-sky-400/35 bg-sky-800/45 py-2.5 text-[11px] font-bold text-sky-50 hover:bg-sky-800/60"
                    >
                        رفع إشارة منع السفر
                    </button>
                </div>
            ) : null}
            </div>
            ) : null}

            {/* 4أ — طلب عرض الإضبارة (قرار المنفذ فقط) */}
            {showEmbeddedSection('executive_dossier_presentation') && showDossierPresentationCard ? (
                <div className="relative space-y-2">
                <div
                    className={`overflow-visible rounded-2xl border border-violet-500/25 bg-violet-950/15 text-right ${kasabCoerciveEmphasis ? 'ring-2 ring-[#E6C673]/45 border-[#E6C673]/35' : ''}`}
                >
                    <div className="relative">
                        {dossierHasExpandablePanel && !dossierIdle ? (
                            <div
                                className={`w-full ${BTN_BASE} bg-gradient-to-l from-orange-500/12 to-transparent`}
                            >
                                <div className="flex flex-row-reverse items-center gap-3">
                                    <span className="flex h-12 w-12 items-center justify-center rounded-2xl bg-white/5">
                                        <Scale className="h-6 w-6 text-white/70" />
                                    </span>
                                    <div className="min-w-0 flex-1">
                                        <p className="text-sm font-bold text-amber-100">
                                            عرض الإضبارة على قاضي البداءة
                                        </p>
                                    </div>
                                </div>
                            </div>
                        ) : (
                            <button
                                type="button"
                                disabled={dossierButtonDisabled}
                                onClick={() => {
                                    if (dossierButtonDisabled) return;
                                    if (!relaxedPersonal && !guardSummonsGate()) return;
                                    if (
                                        !dossierCanResubmitToExecutor &&
                                        !detentionInAbsentia &&
                                        !debtorPresentEffective &&
                                        !relaxedPersonal
                                    ) {
                                        showToast(
                                            'فعّل مسار الغياب أو أكّد مثول المدين أمام المنفذ.',
                                            'warning'
                                        );
                                        return;
                                    }
                                    setConfirmingKey('executive_dossier_presentation');
                                }}
                                className={`w-full ${BTN_BASE} bg-gradient-to-l from-orange-500/12 to-transparent hover:from-orange-500/18 ${dossierButtonDisabled ? BTN_DISABLED : ''}`}
                            >
                                <div className="flex flex-row-reverse items-center gap-3">
                                    <span className="flex h-12 w-12 items-center justify-center rounded-2xl bg-white/5">
                                        <Scale className="h-6 w-6 text-white/70" />
                                    </span>
                                    <div className="min-w-0 flex-1">
                                        <p className="text-sm font-bold text-amber-100">
                                            عرض الإضبارة على قاضي البداءة
                                        </p>
                                    </div>
                                </div>
                            </button>
                        )}

                        {dossierIdle && !relaxedPersonal && !debtorNotified ? (
                            <div className="border-t border-white/10 px-3 py-2">
                                <p className="text-[10px] leading-relaxed text-amber-200/90 rounded-xl border border-amber-500/20 bg-amber-950/15 px-3 py-2">
                                    يجب تبليغ المدين أولاً قبل تقديم طلب عرض الإضبارة.
                                </p>
                            </div>
                        ) : null}

                        {dossier.pending ? (
                            <div className="border-t border-white/10 px-3 py-3">
                            <CoerciveSubsectionFold
                                flat
                                title="طلب عرض الإضبارة — قيد البت لدى المنفذ"
                                titleClassName="text-amber-200"
                            >
                                <ExecutionInlineExecutorDecisionActions
                                    executionId={exId}
                                    decisionId={findGoverningDossierDecisionId() || ''}
                                    decisionRow={dossierGoverningRow}
                                    requestKind="personal_coercive"
                                    personalCoerciveSubtype="executive_dossier_presentation"
                                    suppressNavigatorToast
                                    onResolved={handleExecutorInlineResolved}
                                />
                            </CoerciveSubsectionFold>
                            </div>
                        ) : dossier.rejected &&
                          !isExecutorRejectedAppealFollowupDismissed(
                              findGoverningDossierDecisionId(),
                              allDecisionRows
                          ) ? (
                            <div className="border-t border-white/10 px-3 pb-3 pt-2">
                                {renderRejectedExecutorAppealSection({
                                    decisionId: findGoverningDossierDecisionId(),
                                    title: 'رفض المنفذ طلب عرض الإضبارة',
                                    personalCoerciveSubtype: 'executive_dossier_presentation',
                                })}
                            </div>
                        ) : dossier.alternative ? (
                            <div className="border-t border-white/10 px-3 pb-3 pt-2">
                            <p className="text-[10px] text-amber-200/90">
                                🔄 سُجّل قرار بديل للمنفذ — راجع المهام ومحضر المتابعة.
                            </p>
                            </div>
                        ) : dossier.approved && dossierSync.followupBlock ? (
                            <div className="border-t border-white/10 px-3 pb-3 pt-2">
                                {renderAppealSyncFollowup(dossierSync)}
                            </div>
                        ) : null}
                        {renderInlineGate('executive_dossier_presentation', () => {
                            void runDossierPresentationSubmit();
                        })}
                    </div>
                </div>
                </div>
            ) : null}

            {/* 4ب — قرار القاضي والحبس التنفيذي (بطاقة مستقلة) */}
            {showEmbeddedSection('executive_detention_judge') && showJudgeDetentionCard ? (
                <details
                    open={judgeDetailsOpen}
                    onToggle={(e) => setJudgeDetailsOpen((e.target as HTMLDetailsElement).open)}
                    className={`${COERCIVE_SECTION_DETAILS_CLASS} open:border-orange-400/40`}
                >
                    <summary className="flex cursor-pointer list-none flex-row-reverse items-center justify-between gap-2 px-3 py-3 transition-colors duration-300 hover:bg-white/[0.04] [&::-webkit-details-marker]:hidden">
                        <span className="flex flex-row-reverse items-center gap-2">
                            <span className="flex size-12 items-center justify-center rounded-2xl bg-white/5">
                                <UserX className="size-6 text-white/70" />
                            </span>
                            <span className="text-xs font-bold text-orange-100">قرار القاضي — الحبس التنفيذي</span>
                        </span>
                        <ChevronDown
                            size={18}
                            className="shrink-0 text-slate-400 transition-transform duration-300 group-open:rotate-180"
                            aria-hidden
                        />
                    </summary>
                    <div className="space-y-2 border-t border-white/10 px-3 pb-3 pt-2">
                        {dossierHandedToJudgeStalled ? renderAppealSyncFollowup(dossierSync) : null}
                        {!detentionActive && dossierAwaitingJudge ? (
                            <div className="space-y-2">
                                <p className="text-[11px] font-black text-violet-200">بانتظار قرار قاضي البداءة</p>
                                <p className="text-[10px] leading-relaxed text-violet-200/80">
                                    انتهى دور المنفذ — سجّل موافقة أو رفض القاضي. يُنشأ قرار مستقل في مركز
                                    القرارات.
                                </p>
                                <div className="grid grid-cols-1 gap-2">
                                    <button
                                        type="button"
                                        disabled={coerciveWriteLocked}
                                        className="w-full rounded-xl bg-emerald-800/55 py-2 text-[11px] font-bold text-white border border-emerald-500/35 disabled:opacity-40"
                                        onClick={() => {
                                            if (coerciveWriteLocked) return;
                                            recordExecutiveDetentionJudgeOutcome(
                                                'approved',
                                                new Date().toISOString()
                                            );
                                        }}
                                    >
                                        وافق القاضي على الحبس
                                    </button>
                                    <button
                                        type="button"
                                        disabled={coerciveWriteLocked}
                                        className="w-full rounded-xl border border-rose-500/45 bg-rose-950/35 py-2 text-[11px] font-bold text-rose-100 disabled:opacity-40"
                                        onClick={() => {
                                            if (coerciveWriteLocked) return;
                                            setDetentionRejectionOpen(true);
                                        }}
                                    >
                                        رفض القاضي حبس المدين
                                    </button>
                                </div>
                                {detentionRejectionOpen ? (
                                    <div className="space-y-2 rounded-2xl border border-rose-500/25 bg-rose-950/15 p-3">
                                        <p className="text-[10px] font-bold text-rose-200">يرجى ذكر سبب الرفض</p>
                                        <textarea
                                            value={detentionRejectionReason}
                                            onChange={(e) => setDetentionRejectionReason(e.target.value)}
                                            rows={3}
                                            className="w-full resize-none rounded-xl border border-white/10 bg-white/[0.06] px-2 py-2 text-[11px] text-white"
                                        />
                                        <div className="grid grid-cols-2 gap-2">
                                            <button
                                                type="button"
                                                disabled={detentionRejectionSaving || coerciveWriteLocked}
                                                className="rounded-xl border border-rose-500/40 bg-rose-900/30 py-2.5 text-[11px] font-black text-rose-100 disabled:opacity-50"
                                                onClick={() => {
                                                    if (coerciveWriteLocked) return;
                                                    const reason = detentionRejectionReason.trim();
                                                    if (!reason) {
                                                        showToast('سبب الرفض مطلوب.', 'warning');
                                                        return;
                                                    }
                                                    if (detentionRejectionSaving) return;
                                                    setDetentionRejectionSaving(true);
                                                    recordExecutiveDetentionJudgeOutcome(
                                                        'rejected',
                                                        new Date().toISOString(),
                                                        reason
                                                    );
                                                    setDetentionRejectionSaving(false);
                                                    setDetentionRejectionOpen(false);
                                                    setDetentionRejectionReason('');
                                                }}
                                            >
                                                حفظ السبب والانتقال للطعن
                                            </button>
                                            <button
                                                type="button"
                                                disabled={detentionRejectionSaving}
                                                className="rounded-xl bg-slate-800 py-2.5 text-[11px] font-bold text-slate-100 hover:bg-slate-700 disabled:opacity-50"
                                                onClick={() => {
                                                    setDetentionRejectionOpen(false);
                                                    setDetentionRejectionReason('');
                                                }}
                                            >
                                                إلغاء
                                            </button>
                                        </div>
                                    </div>
                                ) : null}
                            </div>
                        ) : null}
                        {!detentionActive &&
                        judgeDetention === 'approved' &&
                        judgeDetentionStored === 'rejected' &&
                        dossierPhase === 'judge_decided' ? (
                            <p className="rounded-xl border border-emerald-500/25 bg-emerald-950/20 px-3 py-2.5 text-[10px] leading-relaxed text-emerald-100/90">
                                تم نقض رفض القاضي تمييزياً — أصبح الحبس التنفيذي موافقاً عليه. يمكنك بدء
                                المدة أدناه.
                            </p>
                        ) : null}
                        {!detentionActive && dossierShowStartPeriod ? (
                            <CoerciveSubsectionFold
                                title="بدء مدة الحبس التنفيذي"
                                titleClassName="text-emerald-200"
                            >
                                <p className="text-[10px] text-emerald-200/90">
                                    وافق القاضي — تُحتسب المدة تلقائياً لمدة 4 أشهر.
                                </p>
                                {inAbsentia ? (
                                    <button
                                        type="button"
                                        disabled={coerciveWriteLocked}
                                        className="w-full rounded-xl bg-orange-800/55 py-2 text-[11px] font-bold text-white disabled:opacity-40"
                                        onClick={() => {
                                            if (coerciveWriteLocked) return;
                                            startDetentionFourMonths({ markCustody: true, markArrested: true });
                                        }}
                                    >
                                        تم إلقاء القبض على المدين — بدء المدة
                                    </button>
                                ) : (
                                    <button
                                        type="button"
                                        disabled={coerciveWriteLocked}
                                        className="w-full rounded-xl bg-orange-800/55 py-2 text-[11px] font-bold text-white disabled:opacity-40"
                                        onClick={() => {
                                            if (coerciveWriteLocked) return;
                                            startDetentionFourMonths({ markCustody: true });
                                        }}
                                    >
                                        بدء المدة (4 أشهر)
                                    </button>
                                )}
                            </CoerciveSubsectionFold>
                        ) : null}
                        {judgeSync.followupBlock ? renderAppealSyncFollowup(judgeSync) : null}
                        {!detentionActive &&
                        !dossierAwaitingJudge &&
                        !judgeSync.followupBlock &&
                        judgeRejectedResubmitVisible
                            ? renderJudgeRejectedResubmitBlock()
                            : null}
                    </div>
                </details>
            ) : null}

            {onGuarantorRequest && (
                <div className="space-y-2">
                    {guarantorDec.pending ? (
                        <p className="text-[10px] text-amber-200/90 text-center leading-relaxed">
                            طلب الكفيل قيد البت لدى المنفذ — راجع «القرارات والطعون».
                        </p>
                    ) : guarantorDec.rejected ? (
                        <p className="text-[10px] text-rose-200/90 text-center leading-relaxed">
                            رُفض طلب الكفيل — يمكنك التقديم مجدداً إن رُفع الرفض أو تغيّر الموقف.
                        </p>
                    ) : guarantorDec.alternative ? (
                        <p className="text-[10px] text-amber-200/90 text-center leading-relaxed">
                            سُجِّل قرار بديل بشأن الكفيل — راجع القرارات.
                        </p>
                    ) : guarantorFollowupBlock ? (
                        <p className="text-[10px] text-amber-200/90 text-center leading-relaxed">
                            متوقف مؤقتاً — راجع مركز القرارات والطعون.
                        </p>
                    ) : guarantorAwaitingSave ? (
                        <p className="text-[10px] text-emerald-200/90 text-center leading-relaxed">
                            وافق المنفذ — أكمل وحفظ بيانات الكفيل من اسم الكفيل أسفل المدين أو من الزر أدناه.
                        </p>
                    ) : null}
                    {guarantorDec.pending ||
                    (guarantorDec.rejected &&
                        !isExecutorRejectedAppealFollowupDismissed(
                            findLatestGuarantorDecisionId(),
                            allDecisionRows
                        )) ? (
                        <div className="mt-2">
                            {guarantorDec.rejected ? (
                                renderRejectedExecutorAppealSection({
                                    decisionId: findLatestGuarantorDecisionId(),
                                    requestKind: 'guarantor_request',
                                })
                            ) : (
                                <ExecutionInlineExecutorDecisionActions
                                    executionId={exId}
                                    decisionId={findLatestGuarantorDecisionId() || ''}
                                    requestKind="guarantor_request"
                                    suppressNavigatorToast
                                />
                            )}
                        </div>
                    ) : null}
                    {guarantorFollowupBlock && findLatestGuarantorDecisionRow() ? (
                        <div className="mt-2">
                            <ExecutorRequestFollowupBlockPanel
                                gate={guarantorFollowupBlock}
                                executionId={exId}
                                decisionId={String(findLatestGuarantorDecisionId() || '').trim()}
                                onOpenAppeals={(id) => onOpenDecisions({ tab: 'previous', decisionId: id })}
                            />
                        </div>
                    ) : null}
                    {guarantorAwaitingSave && !guarantorFollowupBlock && onOpenGuarantorDetails ? (
                        <button
                            type="button"
                            disabled={coerciveUiLocked}
                            onClick={() => onOpenGuarantorDetails()}
                            className="w-full rounded-xl border border-emerald-500/40 bg-emerald-950/25 py-2.5 text-[11px] font-bold text-emerald-100 disabled:opacity-40"
                        >
                            إكمال بيانات الكفيل
                        </button>
                    ) : null}
                </div>
            )}

            {detentionActive && (
                <div className="relative">
                    <button
                        type="button"
                        onClick={() => {
                            if (coerciveUiLocked || isHistoricalMode) return;
                            setReleaseConfirmOpen(true);
                        }}
                        className="w-full flex items-center justify-center gap-2 flex-row-reverse rounded-xl border border-emerald-800 bg-emerald-900/20 py-2.5 text-[11px] font-bold text-emerald-400 hover:bg-emerald-800/30 transition-all disabled:opacity-40"
                        disabled={coerciveUiLocked || isHistoricalMode}
                    >
                        <Unlock size={16} />
                        طلب إخلاء سبيل المدين
                    </button>
                </div>
            )}
        </div>
    );
};

import React, { useEffect, useState } from 'react';
import { formatNumberInput, parseAmount } from '@/app/utils/execution/amountInput';
import type { ThirdPartySeizure, ThirdPartySeizureAsset } from '@/app/types/execution';
import type { TimelineEvent } from '@/app/types/execution';

export function ThirdPartySeizureWorkflowCard(props: {
    seizure: ThirdPartySeizure;
    fundsDraft: string;
    onFundsDraftChange: (value: string) => void;
    onSeizuresChange: (next: ThirdPartySeizure[]) => void;
    seizures: ThirdPartySeizure[];
    persistExecutionMerge: (patch: Record<string, unknown>) => void;
    setTimelineEvents: React.Dispatch<React.SetStateAction<TimelineEvent[]>>;
    nextTimelineId: () => string;
    showToast: (msg: string, kind?: 'success' | 'warning' | 'error' | 'info') => void;
    onCreditToFinancialCenter: (amountIqd: number) => { ok: boolean };
}) {
    const id = String(props.seizure?.id || '').trim();
    const status = String(props.seizure?.status || '').trim();
    const replyStatus = String(props.seizure?.replyStatus || '').trim();
    const deferred = Boolean(props.seizure?.funds_delivery_deferred);
    const thirdPartyName = String(props.seizure?.thirdPartyName || '').trim() || 'جهة غير محددة';

    const isDenied = status === 'replied' && replyStatus === 'denied';
    const isComplete = status === 'funds_received';
    const isAcknowledged = status === 'replied' && replyStatus === 'acknowledged';
    const awaitingReply = status === 'notified';

    const [deliveryFormOpen, setDeliveryFormOpen] = useState(false);
    const showDeliveryForm = deliveryFormOpen || deferred;

    useEffect(() => {
        if (deferred) setDeliveryFormOpen(true);
    }, [deferred]);

    const resolvedDraft = String(props.fundsDraft ?? '').trim();
    const draftAmount = Math.max(0, Math.trunc(parseAmount(resolvedDraft) || 0));
    const draftDisplay = resolvedDraft ? formatNumberInput(resolvedDraft) : '';

    const patchSeizure = (patch: Partial<ThirdPartySeizure>, timeline?: TimelineEvent) => {
        const nextSeizures = props.seizures.map((x) =>
            String(x?.id || '').trim() === id ? { ...x, ...patch } : x
        );
        props.onSeizuresChange(nextSeizures);
        if (timeline) {
            props.setTimelineEvents((prev) => {
                const nextTl = [timeline, ...prev];
                queueMicrotask(() =>
                    props.persistExecutionMerge({
                        thirdPartySeizures: nextSeizures,
                        timelineEvents: nextTl,
                    })
                );
                return nextTl;
            });
        } else {
            props.persistExecutionMerge({ thirdPartySeizures: nextSeizures });
        }
    };

    const completeDelivery = () => {
        if (!draftAmount) {
            props.showToast('أدخل المبلغ المستلم.', 'warning');
            return;
        }
        const credit = props.onCreditToFinancialCenter(draftAmount);
        const nowIso = new Date().toISOString();
        patchSeizure(
            {
                status: 'funds_received',
                transferredAmountIqd: draftAmount,
                funds_delivery_deferred: false,
            },
            {
                id: props.nextTimelineId(),
                date: nowIso.slice(0, 10),
                timestamp: nowIso,
                title: '💰 استلام أموال محجوزة لدى الغير',
                description: `الجهة: ${thirdPartyName}\nالمبلغ المُسلَّم: ${draftAmount.toLocaleString('ar-IQ')} د.ع`,
                type: 'payment',
                source: 'المركز المالي — حجز لدى الغير',
                metadata: { thirdPartySeizureId: id },
            }
        );
        props.onFundsDraftChange('');
        if (credit.ok) {
            props.showToast(
                `تم التسليم وإيداع ${draftAmount.toLocaleString('ar-IQ')} د.ع في الأمانات — يُخصم من المتبقي.`,
                'success'
            );
        } else {
            props.showToast('تم تسجيل التسليم لكن تعذّر ربط المبلغ بالمركز المالي.', 'warning');
        }
    };

    if (isDenied || isComplete) return null;

    if (awaitingReply) {
        return (
            <div className="space-y-2">
                <div className="grid grid-cols-1 gap-2">
                    <button
                        type="button"
                        className="w-full rounded-xl border border-emerald-500/30 bg-emerald-500/10 px-3 py-2.5 text-[11px] font-extrabold text-emerald-200 hover:bg-emerald-500/15"
                        onClick={() => {
                            const nowIso = new Date().toISOString();
                            patchSeizure(
                                { status: 'replied', replyStatus: 'acknowledged', funds_delivery_deferred: false },
                                {
                                    id: props.nextTimelineId(),
                                    date: nowIso.slice(0, 10),
                                    timestamp: nowIso,
                                    title: '📬 إجابة الجهة الثالثة — إقرار بوجود رصيد',
                                    description: `الجهة: ${thirdPartyName}`,
                                    type: 'coercive',
                                    source: 'محضر المتابعة — حجز لدى الغير',
                                    metadata: { thirdPartySeizureId: id },
                                }
                            );
                            props.showToast('تم الإقرار بوجود رصيد.', 'success');
                        }}
                    >
                        إقرار بوجود رصيد
                    </button>
                    <button
                        type="button"
                        className="w-full rounded-xl border border-rose-500/30 bg-rose-500/10 px-3 py-2.5 text-[11px] font-extrabold text-rose-200 hover:bg-rose-500/15"
                        onClick={() => {
                            const nowIso = new Date().toISOString();
                            patchSeizure(
                                { status: 'replied', replyStatus: 'denied', funds_delivery_deferred: false },
                                {
                                    id: props.nextTimelineId(),
                                    date: nowIso.slice(0, 10),
                                    timestamp: nowIso,
                                    title: '📭 إجابة الجهة الثالثة — نفي',
                                    description: `الجهة: ${thirdPartyName}`,
                                    type: 'coercive',
                                    source: 'محضر المتابعة — حجز لدى الغير',
                                    metadata: { thirdPartySeizureId: id },
                                }
                            );
                            props.showToast('تم إغلاق المسار — نفي وجود رصيد.', 'success');
                        }}
                    >
                        نفي وجود رصيد
                    </button>
                </div>
            </div>
        );
    }

    if (isAcknowledged && !showDeliveryForm) {
        return (
            <div className="space-y-2">
                <div className="grid grid-cols-1 gap-2 sm:grid-cols-2">
                    <button
                        type="button"
                        className="w-full rounded-xl border border-emerald-500/35 bg-emerald-500/15 px-3 py-2.5 text-[11px] font-extrabold text-emerald-100 hover:bg-emerald-500/22"
                        onClick={() => {
                            props.onFundsDraftChange('');
                            patchSeizure({ funds_delivery_deferred: false });
                            setDeliveryFormOpen(true);
                        }}
                    >
                        تم تسليم الأموال
                    </button>
                    <button
                        type="button"
                        className="w-full rounded-xl border border-amber-500/35 bg-amber-500/10 px-3 py-2.5 text-[11px] font-extrabold text-amber-200 hover:bg-amber-500/15"
                        onClick={() => {
                            props.onFundsDraftChange('');
                            patchSeizure({ funds_delivery_deferred: true });
                            setDeliveryFormOpen(true);
                            props.showToast('التسليم لاحقاً — أكمل عند استلام الأموال.', 'info');
                        }}
                    >
                        التسليم لاحقاً
                    </button>
                </div>
            </div>
        );
    }

    if (isAcknowledged && showDeliveryForm) {
        return (
            <div className="space-y-2">
                <label className="block text-[11px] font-bold text-slate-300">المبلغ المستلم (د.ع)</label>
                <input
                    type="text"
                    inputMode="numeric"
                    value={draftDisplay}
                    onChange={(e) => props.onFundsDraftChange(formatNumberInput(e.target.value))}
                    className="w-full rounded-xl border border-white/10 bg-white/5 px-3 py-2 text-[12px] text-slate-100 text-right tabular-nums"
                    placeholder="أدخل المبلغ"
                />
                <button
                    type="button"
                    className="w-full rounded-xl bg-gradient-to-l from-emerald-500 to-emerald-700 px-5 py-2.5 text-[12px] font-black text-white shadow-md shadow-black/20 disabled:opacity-40"
                    disabled={!draftAmount}
                    onClick={completeDelivery}
                >
                    تم التسليم
                </button>
            </div>
        );
    }

    return null;
}

export function ThirdPartySeizureRegistryCard(props: {
    asset: ThirdPartySeizureAsset;
    beginReceive: (asset: ThirdPartySeizureAsset) => void;
    updateReceiveDraft: (assetId: string, value: string) => void;
    cancelReceive: (asset: ThirdPartySeizureAsset) => void;
    confirmReceive: (asset: ThirdPartySeizureAsset) => void;
}) {
    const asset = props.asset;
    const locked = Boolean(asset.record_locked);
    const awaiting = Boolean(asset.awaiting_receive);
    const isPlaceholder = /بانتظار\s*الإكمال/i.test(String(asset.thirdPartyName || ''));
    const statusLabel =
        asset.status === 'waiting'
            ? isPlaceholder
                ? 'بانتظار إكمال البيانات'
                : 'بانتظار إجابة الجهة'
            : asset.status === 'received'
              ? 'تم الاستلام'
              : 'مؤرشف';
    const expected =
        typeof asset.expectedAmountIqd === 'number' &&
        Number.isFinite(asset.expectedAmountIqd) &&
        asset.expectedAmountIqd > 0
            ? `${asset.expectedAmountIqd.toLocaleString('ar-IQ')} د.ع`
            : '—';

    if (isPlaceholder) {
        return (
            <p className="text-[10px] text-amber-200/90 text-right">
                أكمل بيانات الحجز لدى الغير من تبويب طلبات الحجز لبدء المتابعة.
            </p>
        );
    }

    if (locked) {
        return (
            <p className="text-[10px] text-slate-400 text-right">
                {statusLabel}
                {asset.actualReceivedAmountIqd
                    ? ` — ${Number(asset.actualReceivedAmountIqd).toLocaleString('ar-IQ')} د.ع`
                    : ''}
            </p>
        );
    }

    if (awaiting) {
        return (
            <div className="space-y-2">
                <input
                    type="text"
                    inputMode="numeric"
                    value={formatNumberInput(String(asset.receive_amount_draft || ''))}
                    onChange={(e) => props.updateReceiveDraft(asset.id, formatNumberInput(e.target.value))}
                    className="w-full rounded-xl border border-white/10 bg-white/5 px-3 py-2 text-[11px] text-slate-100 text-right tabular-nums"
                    placeholder="المبلغ الفعلي المستلم (د.ع)"
                />
                <div className="grid grid-cols-2 gap-2">
                    <button
                        type="button"
                        onClick={() => props.confirmReceive(asset)}
                        className="rounded-xl border border-emerald-500/30 bg-emerald-500/10 py-2 text-[10px] font-bold text-emerald-200 hover:bg-emerald-500/15"
                    >
                        تم التسليم
                    </button>
                    <button
                        type="button"
                        onClick={() => props.cancelReceive(asset)}
                        className="rounded-xl border border-slate-500/30 bg-slate-500/10 py-2 text-[10px] font-bold text-slate-200 hover:bg-slate-500/15"
                    >
                        إلغاء
                    </button>
                </div>
            </div>
        );
    }

    return (
        <button
            type="button"
            onClick={() => props.beginReceive(asset)}
            className="w-full rounded-xl border border-cyan-500/30 bg-cyan-500/10 px-3 py-2 text-[11px] font-extrabold text-cyan-100 hover:bg-cyan-500/15"
        >
            تسجيل استلام الأموال من الجهة
        </button>
    );
}

// @ts-nocheck
import React, { useMemo } from 'react';
import { createPortal } from 'react-dom';
import { Briefcase, Car, Home, Wallet, X } from 'lucide-react';
import { EXEC_MODAL_BACKDROP_STRONG, EXEC_MODAL_Z } from '@/app/components/lawyer/execution/executionModalStack';
import { UNIFIED_SEIZURE_TAB_ORDER } from '@/app/components/lawyer/ExecutionDashboard/utils/unifiedSeizureLogHelpers';

export type UnifiedSeizureLogEntry = {
    id: string;
    kind: 'property' | 'salary' | 'movable' | 'third_party' | 'marks';
    dateYmd: string;
    title: string;
    statusLabel: string;
    statusCode: string;
    description: string;
    entityId?: string;
};

export type SeizureLogTab = 'property' | 'salary' | 'movable' | 'third_party';

const TAB_META: Record<
    SeizureLogTab,
    { label: string; Icon: React.ComponentType<{ size?: number; className?: string }>; active: string; idle: string }
> = {
    property: {
        label: 'عقار',
        Icon: Home,
        active: 'border-emerald-400/35 bg-emerald-500/10 text-emerald-200',
        idle: 'border-white/10 bg-slate-900/35 text-slate-300 hover:bg-slate-900/45',
    },
    salary: {
        label: 'راتب',
        Icon: Wallet,
        active: 'border-amber-400/35 bg-amber-500/10 text-amber-200',
        idle: 'border-white/10 bg-slate-900/35 text-slate-300 hover:bg-slate-900/45',
    },
    movable: {
        label: 'منقول',
        Icon: Car,
        active: 'border-sky-400/35 bg-sky-500/10 text-sky-200',
        idle: 'border-white/10 bg-slate-900/35 text-slate-300 hover:bg-slate-900/45',
    },
    third_party: {
        label: 'لدى الغير',
        Icon: Briefcase,
        active: 'border-violet-400/35 bg-violet-500/10 text-violet-200',
        idle: 'border-white/10 bg-slate-900/35 text-slate-300 hover:bg-slate-900/45',
    },
};

const KIND_ACCENT: Record<SeizureLogTab, string> = {
    property: 'border-amber-500/30',
    salary: 'border-emerald-500/30',
    movable: 'border-sky-500/30',
    third_party: 'border-violet-500/30',
};

function statusTone(statusLabel: string): string {
    const s = String(statusLabel || '');
    if (/مباع|تم البيع|إحالة|استلام|تم الحجز|فعال|مسجّل|إقرار/i.test(s)) {
        return 'border-emerald-500/25 bg-emerald-500/10 text-emerald-100';
    }
    if (/بانتظار|أكمل|موافقة/i.test(s)) {
        return 'border-amber-500/25 bg-amber-500/10 text-amber-100';
    }
    if (/فُك|مؤرشف|ملغى|نفي|رفض/i.test(s)) {
        return 'border-slate-500/25 bg-slate-500/10 text-slate-300';
    }
    return 'border-white/12 bg-white/5 text-slate-200';
}

const TAB_ORDER = UNIFIED_SEIZURE_TAB_ORDER;

export function UnifiedSeizureLogModal(props: {
    open: boolean;
    activeTab: SeizureLogTab;
    onTabChange: (tab: SeizureLogTab) => void;
    counts: Record<SeizureLogTab, number>;
    entries: UnifiedSeizureLogEntry[];
    onClose: () => void;
    renderEntryFooter?: (entry: UnifiedSeizureLogEntry) => React.ReactNode;
}) {
    const visibleEntries = useMemo(
        () => props.entries.filter((e) => e.kind === props.activeTab),
        [props.entries, props.activeTab]
    );

    const tabMeta = TAB_META[props.activeTab];

    if (!props.open || typeof document === 'undefined') return null;

    return createPortal(
        <div
            className={`fixed inset-0 flex items-center justify-center p-4 ${EXEC_MODAL_BACKDROP_STRONG}`}
            style={{ zIndex: EXEC_MODAL_Z.nestedOverFollowUpPortal }}
            role="presentation"
            onClick={(e) => {
                if (e.target === e.currentTarget) props.onClose();
            }}
        >
            <div
                className="flex max-h-[85vh] w-full max-w-2xl flex-col overflow-hidden rounded-3xl border border-[#E6C673]/30 bg-[#0B1120] shadow-2xl shadow-black/60"
                onClick={(e) => e.stopPropagation()}
                dir="rtl"
            >
                <div className="flex shrink-0 items-center justify-between border-b border-[#E6C673]/20 px-4 py-3">
                    <button
                        type="button"
                        onClick={props.onClose}
                        className="rounded-lg p-2 text-slate-400 hover:bg-white/5 hover:text-white"
                        aria-label="إغلاق"
                    >
                        <X size={18} />
                    </button>
                    <div className="text-right">
                        <p className="text-[13px] font-black text-[#E6C673]">سجل الحجز</p>
                        <p className="text-[10px] text-slate-400">
                            {tabMeta.label} — {props.counts[props.activeTab]} سجل
                        </p>
                    </div>
                    <span className="w-8" aria-hidden />
                </div>

                <div className="shrink-0 border-b border-white/6 px-3 py-2.5">
                    <div className="grid grid-cols-2 gap-2 sm:grid-cols-4">
                        {TAB_ORDER.map((tab) => {
                            const meta = TAB_META[tab];
                            const Icon = meta.Icon;
                            const isActive = props.activeTab === tab;
                            return (
                                <button
                                    key={tab}
                                    type="button"
                                    onClick={() => props.onTabChange(tab)}
                                    className={`inline-flex flex-row-reverse items-center justify-center gap-1.5 rounded-2xl border px-2 py-2 text-[10px] font-black transition-colors ${
                                        isActive ? meta.active : meta.idle
                                    }`}
                                >
                                    <Icon size={12} className="opacity-90" />
                                    <span>
                                        {meta.label} ({props.counts[tab]})
                                    </span>
                                </button>
                            );
                        })}
                    </div>
                </div>

                <div className="min-h-0 flex-1 overflow-y-auto px-3 py-3">
                    {visibleEntries.length === 0 ? (
                        <p className="py-10 text-center text-[11px] text-slate-500">
                            لا يوجد سجل حجز في قسم {tabMeta.label} بعد.
                        </p>
                    ) : (
                        <div className="space-y-2">
                            {visibleEntries.map((entry, idx) => {
                                const footer = props.renderEntryFooter?.(entry);
                                return (
                                    <article
                                        key={entry.id}
                                        className={`rounded-2xl border bg-[#05060D]/70 ${KIND_ACCENT[props.activeTab]}`}
                                    >
                                        <div className="flex flex-row-reverse items-start justify-between gap-2 px-3 py-2.5">
                                            <div className="min-w-0 flex-1 text-right">
                                                <div className="mb-1 flex flex-row-reverse items-center gap-1.5">
                                                    <span className="text-[9px] tabular-nums text-slate-500">#{idx + 1}</span>
                                                    {entry.dateYmd ? (
                                                        <span className="text-[9px] tabular-nums text-slate-500">{entry.dateYmd}</span>
                                                    ) : null}
                                                </div>
                                                <p className="truncate text-[12px] font-black text-slate-50">{entry.title}</p>
                                            </div>
                                            <span
                                                className={`shrink-0 rounded-lg border px-2 py-0.5 text-[9px] font-bold ${statusTone(entry.statusLabel)}`}
                                            >
                                                {entry.statusLabel}
                                            </span>
                                        </div>

                                        {String(entry.description || '').trim() && !footer ? (
                                            <pre className="border-t border-white/6 px-3 py-2 text-[10px] leading-relaxed text-slate-300 whitespace-pre-wrap">
                                                {entry.description}
                                            </pre>
                                        ) : null}

                                        {footer ? (
                                            <div className="border-t border-white/6 px-3 py-2.5">{footer}</div>
                                        ) : null}
                                    </article>
                                );
                            })}
                        </div>
                    )}
                </div>
            </div>
        </div>,
        document.body
    );
}

export function isSeizureLogTab(v: string): v is SeizureLogTab {
    return v === 'property' || v === 'salary' || v === 'movable' || v === 'third_party';
}

import {
    getDossierPresentationOutcome,
    getGoverningDossierPresentationRow,
    getGoverningDossierPresentationRowFromDecisions,
    getGoverningPersonalCoerciveSubtypeRowFromDecisions,
    getPersonalCoerciveSubtypeOutcome,
    isExecutorHubRowSuperseded,
    isExecutorRowEffectivelyApproved,
    isExecutorRowRejectedAndFinal,
    readExecutorDecisionsArray,
} from '@/app/utils/executorSeizureDecisionQueue';
import {
    isExecutorDecisionRowEffectivelyEnforced,
    isExecutorRowApprovedWorkflowActive,
} from '@/app/components/lawyer/ExecutionDashboard/utils/executorRequestEnforceability';

type PersonalCoerciveQueueState = ReturnType<typeof getPersonalCoerciveSubtypeOutcome>;

/** إغلاق دورة التنفيذ الجبري (إخلاء سبيل) — تُخفى شارات الطلبات من القرارات */
export function isPersonalCoerciveCycleClosed(
    ed: { personal_coercive_cycle_closed_at?: string | null } | null | undefined
): boolean {
    return Boolean(String(ed?.personal_coercive_cycle_closed_at ?? '').trim());
}

/** انتهاء/إغلاق مسار الحبس دون دورة كاملة (مثلاً انتهاء المدة) */
export function isExecutiveDetentionBadgeSuppressed(
    ed:
        | {
              personal_coercive_cycle_closed_at?: string | null;
              executive_detention_released_or_closed_at?: string | null;
          }
        | null
        | undefined
): boolean {
    if (isPersonalCoerciveCycleClosed(ed)) return true;
    return Boolean(String(ed?.executive_detention_released_or_closed_at ?? '').trim());
}

/** نتيجة قرار القاضي الفعلية — تتزامن مع نقض التمييز لرفض الحبس */
export function resolveExecutiveDetentionJudgeUiOutcome(input: {
    storedOutcome?: 'approved' | 'rejected' | null;
    judgeRow?: Record<string, unknown> | null;
}): 'approved' | 'rejected' | null {
    const row = input.judgeRow;
    if (row && typeof row === 'object') {
        if (isExecutorRowEffectivelyApproved(row)) return 'approved';
        if (isExecutorRowRejectedAndFinal(row)) return 'rejected';
        const raw = String(
            (row as { executiveDetentionJudgeOutcome?: string }).executiveDetentionJudgeOutcome ||
                (row as { executorOutcome?: string }).executorOutcome ||
                ''
        ).trim();
        if (raw === 'approved' || raw === 'rejected') return raw;
    }
    return input.storedOutcome ?? null;
}

/** تراجع صريح عن طلب منع السفر — لا يُربط بإخلاء سبيل الحبس وحده */
export function isTravelBanRequestWithdrawn(
    ed: { travel_ban_withdrawn_at?: string | null } | null | undefined
): boolean {
    return Boolean(String(ed?.travel_ban_withdrawn_at ?? '').trim());
}

/** تراجع عن دورة الطلب مع إبقاء منع السفر نافذاً حتى السداد */
export function isTravelBanRequestCycleWithdrawn(
    ed: { travel_ban_request_cycle_withdrawn_at?: string | null } | null | undefined
): boolean {
    return Boolean(String(ed?.travel_ban_request_cycle_withdrawn_at ?? '').trim());
}

/** دورة منع السفر منتهية — يُعاد تفعيل تقديم طلب جديد */
export function isTravelBanLaneSettled(
    ed:
        | {
              travel_ban_withdrawn_at?: string | null;
              debtor_travel_ban_active?: boolean;
          }
        | null
        | undefined,
    opts: { travelCycleActive: boolean }
): boolean {
    if (isTravelBanRequestWithdrawn(ed)) return true;
    if (!opts.travelCycleActive) return true;
    if (ed?.debtor_travel_ban_active !== true) return true;
    return false;
}

/** إحضار جبري ضمني عند بدء/إنهاء حبس تنفيذي — يمنع بقاء «تسجيل النتيجة» أو activeNoticeState */
export function appendImplicitForcedBringBroughtPatch(
    patch: Record<string, unknown>,
    ed: {
        forced_bring_in_personal_outcome?: string | null;
        forced_bring_in_personal_followup_logged?: boolean;
        debtorForcedToAttend?: boolean;
    } | null | undefined,
    forcedApproved: boolean
): Record<string, unknown> {
    if (!forcedApproved || isForcedBringCycleResolved(ed)) return patch;
    return {
        ...patch,
        forced_bring_in_personal_outcome: 'brought',
        forced_bring_in_personal_followup_logged: true,
        forcedAttendanceIssued: false,
        activeNoticeState: null,
        debtorForcedToAttend: true,
        debtorAttendedVoluntarily: true,
        debtorEvaded: false,
    };
}

/** حبس تنفيذي فعّال — يُخفى الشارة بعد انتهاء المدة أو إخلاء السبيل */
export function isExecutiveDetentionPeriodActive(
    ed: { debtor_executive_detention_active?: boolean; executive_detention_until?: string | null } | null | undefined
): boolean {
    if (ed?.debtor_executive_detention_active !== true) return false;
    const until = String(ed?.executive_detention_until ?? '').trim();
    if (!until) return true;
    const end = new Date(`${until}T23:59:59`);
    if (Number.isNaN(end.getTime())) return true;
    return Date.now() <= end.getTime();
}

/** اكتمال دورة الإحضار الجبري — يعتمد على نتيجة صريحة فقط (لا يخلط مع الحضور الطوعي) */
export function isForcedBringCycleResolved(
    ed: {
        forced_bring_in_personal_outcome?: string | null;
        forced_bring_in_personal_followup_logged?: boolean;
        debtorForcedToAttend?: boolean;
    } | null | undefined
): boolean {
    const o = String(ed?.forced_bring_in_personal_outcome ?? '').trim();
    if (o === 'brought' || o === 'absconded') return true;
    if (ed?.debtorForcedToAttend === true && ed?.forced_bring_in_personal_followup_logged === true) {
        return true;
    }
    return false;
}

export function isInvestigationCourtWithdrawn(
    ed: { investigation_court_withdrawn_at?: string | null } | null | undefined
): boolean {
    return Boolean(String(ed?.investigation_court_withdrawn_at ?? '').trim());
}

/** هل يُعرض محضر «تسجيل نتيجة الإحضار الجبري» بعد موافقة المنفذ */
export function resolveForcedBringNeedsOutcomeUi(input: {
    forcedApproved: boolean;
    forcedPending: boolean;
    outcome?: string | null;
    /** طعن/تظلم يوقف التنفيذ الميداني — لا تسجيل نتيجة */
    appealBlocksFieldwork?: boolean;
    /** الطلب غير نافذ بعد الطعن */
    requestEffectivelyEnforced?: boolean;
    /** أُغلقت دورة الطلب بالطعن */
    appealCycleSuperseded?: boolean;
}): boolean {
    if (input.appealBlocksFieldwork) return false;
    if (input.appealCycleSuperseded) return false;
    if (input.requestEffectivelyEnforced === false) return false;
    if (!input.forcedApproved || input.forcedPending) return false;
    const o = String(input.outcome ?? '').trim();
    return o !== 'brought' && o !== 'absconded';
}

/** اكتمال مسار مفاتحة التحقيق ميدانياً — لا يُعاد فتح الإحضار الجبري تلقائياً */
export function isInvestigationCoerciveLaneSettled(
    ed:
        | {
              investigationPathDebtorPresent?: boolean;
              debtor_arrest_warrant_cleared_after_custody?: boolean;
          }
        | null
        | undefined
): boolean {
    return (
        ed?.investigationPathDebtorPresent === true ||
        ed?.debtor_arrest_warrant_cleared_after_custody === true
    );
}

/** مذكرة قبض نافذة — صدور الأمر فقط، لا عند تقديم مفاتحة التحقيق أو قيد البت */
export function isArrestWarrantEnforceable(
    ed:
        | {
              debtor_wanted_arrest_warrant?: boolean;
              personal_arrest_warrant_stage?: string | null;
              debtor_arrest_warrant_cleared_after_custody?: boolean;
          }
        | null
        | undefined
): boolean {
    if (ed?.debtor_arrest_warrant_cleared_after_custody === true) return false;
    if (ed?.debtor_wanted_arrest_warrant === true) return true;
    return String(ed?.personal_arrest_warrant_stage ?? '').trim() === 'issued';
}

/** منع سفر نافذ — بعد موافقة المنفذ وانتهاء مسار الطعن الموقِف */
export function isTravelBanEnforceable(
    ed: { debtor_travel_ban_active?: boolean; travel_ban_withdrawn_at?: string | null } | null | undefined,
    opts?: {
        travelDecisionRow?: Record<string, unknown> | null;
        allDecisions?: Record<string, unknown>[];
    }
): boolean {
    if (isTravelBanRequestWithdrawn(ed)) return false;
    if (ed?.debtor_travel_ban_active !== true) return false;
    const row = opts?.travelDecisionRow;
    const all = opts?.allDecisions ?? [];
    if (row && all.length > 0) {
        return isExecutorDecisionRowEffectivelyEnforced(row, all);
    }
    return false;
}

/** نتيجة قاضي البداءة الفعلية — من الملف أو صف القرار (بما فيه نقض التمييز) */
export function resolveExecutiveDetentionEffectiveJudgeOutcome(input: {
    executionData:
        | {
              executive_detention_judge_outcome?: 'approved' | 'rejected' | null;
              executive_detention_judge_decision_id?: string | null;
          }
        | null
        | undefined;
    decisionsExecutionId?: string;
}): 'approved' | 'rejected' | null {
    const ed = input.executionData;
    const stored = (ed?.executive_detention_judge_outcome as 'approved' | 'rejected' | null) ?? null;
    const exId = String(input.decisionsExecutionId ?? '').trim();
    if (!exId) return stored;

    const judgeId = String(ed?.executive_detention_judge_decision_id ?? '').trim();
    const rows = readExecutorDecisionsArray(exId);
    let judgeRow: Record<string, unknown> | undefined;
    if (judgeId) {
        judgeRow = rows.find(
            (r) => String((r as { id?: string }).id ?? '').trim() === judgeId
        ) as Record<string, unknown> | undefined;
    }
    if (!judgeRow) {
        judgeRow = rows.find(
            (r) =>
                String((r as { personalCoerciveSubtype?: string }).personalCoerciveSubtype ?? '') ===
                    'executive_detention_judge' &&
                !isExecutorHubRowSuperseded(r as Record<string, unknown>)
        ) as Record<string, unknown> | undefined;
    }
    return resolveExecutiveDetentionJudgeUiOutcome({ storedOutcome: stored, judgeRow });
}

/** مسار حبس نافذ — بعد موافقة/اعتبار قاضي البداءة فقط (لا عند تسليم الإضبارة وحدها) */
export function isExecutiveDetentionPathEnforceable(
    ed:
        | {
              executive_dossier_phase?: string | null;
              debtor_executive_detention_active?: boolean;
              executive_detention_until?: string | null;
              executive_detention_judge_outcome?: 'approved' | 'rejected' | null;
          }
        | null
        | undefined,
    detentionSuppressed: boolean,
    effectiveJudgeOutcome?: 'approved' | 'rejected' | null,
    opts?: {
        judgeDecisionRow?: Record<string, unknown> | null;
        allDecisions?: Record<string, unknown>[];
    }
): boolean {
    if (detentionSuppressed) return false;
    const judgeOutcome =
        effectiveJudgeOutcome ??
        ((ed?.executive_detention_judge_outcome as 'approved' | 'rejected' | null) ?? null);
    if (judgeOutcome === 'rejected') return false;

    const pathOpen =
        isExecutiveDetentionPeriodActive(ed) || judgeOutcome === 'approved';
    if (!pathOpen) return false;

    const row = opts?.judgeDecisionRow;
    const all = opts?.allDecisions;
    if (row && Array.isArray(all) && all.length > 0) {
        return isExecutorDecisionRowEffectivelyEnforced(row, all);
    }
    return true;
}

/** إظهار بطاقة مفاتحة محكمة التحقيق — تُخفى بعد إتمام الدورة (حضور أو تأمين إحضار) حتى يُعاد «متخفي» من الإحضار الجبري */
export function shouldShowInvestigationCourtBlock(
    ed: {
        forced_bring_in_personal_outcome?: string | null;
        investigation_court_withdrawn_at?: string | null;
        personal_arrest_investigation_session_open?: boolean;
        personal_arrest_warrant_stage?: string | null;
        debtor_wanted_arrest_warrant?: boolean;
        investigationCourtRequested?: boolean;
        investigationPathDebtorPresent?: boolean;
        debtor_arrest_warrant_cleared_after_custody?: boolean;
    } | null | undefined,
    arrestSt: { pending: boolean; approved: boolean; alternative: boolean } | null
): boolean {
    if (isInvestigationCourtWithdrawn(ed)) return false;
    if (isInvestigationCoerciveLaneSettled(ed)) return false;
    if (ed?.investigationPathDebtorPresent === true) return false;
    if (ed?.debtor_arrest_warrant_cleared_after_custody === true) return false;

    const outcome = String(ed?.forced_bring_in_personal_outcome ?? '').trim();
    /** المفاتحة لا تُعرض إلا بعد تسجيل «متخفي عن الأنظار» في الإحضار الجبري */
    if (outcome !== 'absconded') return false;

    if (ed?.investigationCourtRequested === true) return true;
    if (arrestSt?.pending || arrestSt?.approved || arrestSt?.alternative) return true;
    const stage = String(ed?.personal_arrest_warrant_stage ?? 'none').trim();
    if (ed?.debtor_wanted_arrest_warrant === true) return true;
    if (stage !== 'none' && stage !== '') return true;
    if (ed?.personal_arrest_investigation_session_open === true) return true;
    return true;
}

function resolveExecutiveDetentionJudgeGoverningRow(
    allDecisions: Record<string, unknown>[],
    ed: {
        executive_detention_judge_decision_id?: string | null;
        executive_detention_judge_eligible_decision_id?: string | null;
    } | null | undefined,
    scope: { debtorKey?: string; primaryDebtorKey?: string }
): Record<string, unknown> | null {
    const byId = String(ed?.executive_detention_judge_decision_id ?? '').trim();
    if (byId) {
        const hit = allDecisions.find(
            (r) => String((r as { id?: string }).id ?? '').trim() === byId
        );
        if (hit && !isExecutorHubRowSuperseded(hit)) return hit;
    }
    const dossierParentId = String(
        (
            getGoverningDossierPresentationRowFromDecisions(allDecisions, scope) as {
                id?: string;
            } | null
        )?.id ?? ''
    ).trim();
    const parentId = String(ed?.executive_detention_judge_eligible_decision_id ?? dossierParentId).trim();
    if (!parentId) return null;
    return (
        allDecisions.find(
            (r) =>
                String((r as { personalCoerciveSubtype?: string }).personalCoerciveSubtype ?? '') ===
                    'executive_detention_judge' &&
                String(
                    (r as { parentExecutorDecisionId?: string }).parentExecutorDecisionId ?? ''
                ).trim() === parentId &&
                !isExecutorHubRowSuperseded(r)
        ) ?? null
    );
}

export function resolvePrimaryDebtorCoerciveStack(args: {
    executionData: any;
    decisionsExecutionId: string | undefined;
    personalCoerciveDecisionBadges: boolean;
    debtorArrested?: boolean;
    forcedAttendancePending?: boolean;
    activeDebtorKey?: string;
    primaryDebtorKey?: string;
}): {
    travelSt: PersonalCoerciveQueueState;
    detentionSt: PersonalCoerciveQueueState;
    arrestSt: PersonalCoerciveQueueState;
    forcedSt: PersonalCoerciveQueueState;
    forcedNeedsOutcome: boolean;
    detentionAbsentia: boolean;
    showArrestWarrantBadge: boolean;
    showForcedAttendance: boolean;
    suppressDebtorAbsence: boolean;
} {
    const ed = args.executionData;
    const pcDecisions = args.personalCoerciveDecisionBadges !== false;
    const decId = args.decisionsExecutionId;
    const travelSt = decId
        ? getPersonalCoerciveSubtypeOutcome(decId, 'travel_ban', {
              debtorKey: args.activeDebtorKey,
              primaryDebtorKey: args.primaryDebtorKey,
          })
        : null;
    const detentionSt = decId
        ? getDossierPresentationOutcome(decId, {
              debtorKey: args.activeDebtorKey,
              primaryDebtorKey: args.primaryDebtorKey,
          })
        : null;
    const arrestSt = decId
        ? getPersonalCoerciveSubtypeOutcome(decId, 'arrest_warrant_investigation', {
              debtorKey: args.activeDebtorKey,
              primaryDebtorKey: args.primaryDebtorKey,
          })
        : null;
    const forcedSt = decId
        ? getPersonalCoerciveSubtypeOutcome(decId, 'forced_bring_in', {
              debtorKey: args.activeDebtorKey,
              primaryDebtorKey: args.primaryDebtorKey,
          })
        : null;
    const detentionAbsentia = ed?.executive_detention_request_in_absentia === true;
    const detentionPeriodActive = isExecutiveDetentionPeriodActive(ed);

    const detentionSuppressed = isExecutiveDetentionBadgeSuppressed(ed);

    const imprisonmentPresentSuppressesWarrant =
        !detentionAbsentia &&
        detentionPeriodActive &&
        !detentionSuppressed;

    const showArrestWarrantBadge =
        !args.debtorArrested &&
        !imprisonmentPresentSuppressesWarrant &&
        isArrestWarrantEnforceable(ed);

    const forcedBringResolved = isForcedBringCycleResolved(ed);
    const forcedNeedsOutcome =
        pcDecisions && Boolean(forcedSt?.approved) && !forcedBringResolved;

    const allDecisions = decId
        ? (readExecutorDecisionsArray(decId) as Record<string, unknown>[])
        : [];
    const scope = { debtorKey: args.activeDebtorKey, primaryDebtorKey: args.primaryDebtorKey };
    const forcedRow =
        decId && allDecisions.length > 0
            ? getGoverningPersonalCoerciveSubtypeRowFromDecisions(
                  allDecisions,
                  'forced_bring_in',
                  scope
              )
            : null;
    const forcedBringWorkflowActive =
        forcedRow != null && allDecisions.length > 0
            ? isExecutorRowApprovedWorkflowActive(forcedRow, allDecisions)
            : false;

    const showForcedAttendance =
        !showArrestWarrantBadge &&
        !forcedBringResolved &&
        forcedBringWorkflowActive &&
        (forcedNeedsOutcome || Boolean(args.forcedAttendancePending));

    const travelDecisionRow =
        decId && allDecisions.length > 0
            ? getGoverningPersonalCoerciveSubtypeRowFromDecisions(allDecisions, 'travel_ban', scope)
            : null;
    const judgeDecisionRow =
        decId && allDecisions.length > 0
            ? resolveExecutiveDetentionJudgeGoverningRow(allDecisions, ed, scope)
            : null;

    const hasTravelBanUi = isTravelBanEnforceable(ed, {
        travelDecisionRow,
        allDecisions,
    });

    const effectiveJudgeOutcome = decId
        ? resolveExecutiveDetentionEffectiveJudgeOutcome({
              executionData: ed,
              decisionsExecutionId: decId,
          })
        : ((ed?.executive_detention_judge_outcome as 'approved' | 'rejected' | null) ?? null);
    const hasDetentionUi = isExecutiveDetentionPathEnforceable(
        ed,
        detentionSuppressed,
        effectiveJudgeOutcome,
        { judgeDecisionRow, allDecisions }
    );

    const suppressDebtorAbsence =
        showArrestWarrantBadge ||
        showForcedAttendance ||
        Boolean(args.debtorArrested) ||
        hasTravelBanUi ||
        hasDetentionUi;

    return {
        travelSt,
        detentionSt,
        arrestSt,
        forcedSt,
        forcedNeedsOutcome,
        detentionAbsentia,
        showArrestWarrantBadge,
        showForcedAttendance,
        suppressDebtorAbsence,
    };
}

/**
 * يصفّر أعلام ملف التنفيذ العالقة عندما أُغلقت دورة الطلب في مركز القرارات (طعن نهائي / أرشفة).
 */
export function buildPersonalCoerciveStaleExecutionPatch(input: {
    executionId: string;
    executionData: Record<string, unknown> | null | undefined;
    debtorKey?: string;
    primaryDebtorKey?: string;
}): Record<string, unknown> | null {
    const exId = String(input.executionId || '').trim();
    if (!exId) return null;
    const ed = input.executionData;
    const scope = { debtorKey: input.debtorKey, primaryDebtorKey: input.primaryDebtorKey };
    const patch: Record<string, unknown> = {};

    const dossierCycleActive = Boolean(getGoverningDossierPresentationRow(exId, scope));
    const detentionActive = isExecutiveDetentionPeriodActive(
        ed as { debtor_executive_detention_active?: boolean; executive_detention_until?: string | null }
    );
    const eligibleId = String(ed?.executive_detention_judge_eligible_decision_id ?? '').trim();
    const judgeDecisionId = String(ed?.executive_detention_judge_decision_id ?? '').trim();
    const judgeOutcome = ed?.executive_detention_judge_outcome;
    const eligibleRow = eligibleId
        ? (readExecutorDecisionsArray(exId).find(
              (r) => String((r as { id?: string }).id ?? '').trim() === eligibleId
          ) as Record<string, unknown> | undefined)
        : undefined;
    const eligibleAnchored =
        Boolean(eligibleRow) && !isExecutorHubRowSuperseded(eligibleRow as Record<string, unknown>);
    const dossierLaneActive =
        dossierCycleActive ||
        detentionActive ||
        Boolean(judgeDecisionId) ||
        judgeOutcome === 'approved' ||
        judgeOutcome === 'rejected' ||
        eligibleAnchored;
    if (!dossierLaneActive) {
        if (ed?.executive_dossier_phase != null && ed.executive_dossier_phase !== undefined) {
            patch.executive_dossier_phase = null;
        }
        if (ed?.executive_detention_judge_outcome != null && ed.executive_detention_judge_outcome !== undefined) {
            patch.executive_detention_judge_outcome = null;
        }
        if (eligibleId) {
            patch.executive_detention_judge_eligible_decision_id = null;
        }
        if (judgeDecisionId) {
            patch.executive_detention_judge_decision_id = null;
        }
        if (String(ed?.executive_detention_judge_rejection_reason ?? '').trim()) {
            patch.executive_detention_judge_rejection_reason = null;
        }
    }

    return Object.keys(patch).length > 0 ? patch : null;
}

import { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import type { CalendarEvent, CalendarEventType } from '@/app/services/cloud/lawyerCalendarTypes';
import {
    fetchCalendarEvents,
    saveCalendarEvent,
    updateCalendarEvent,
    deleteCalendarEvent,
} from '@/app/services/calendar/calendarCloudRuntime';
import { CALENDAR_UPDATED_EVENT } from '@/app/services/calendarBridge.types';
import { resolveCalendarUserId } from '@/app/services/calendar/bridge/core';
import { isBridgedCalendarEvent } from '@/app/services/calendar/calendarEventAuthorship';
import { mapStoredEventsToUnified } from '@/app/components/lawyer/SmartLegalRadar/calendarEventMapping';
import {
    getCachedCalendarEvents,
    hasCachedCalendarEvents,
    invalidateCalendarEventsCache,
    setCachedCalendarEvents,
} from '@/app/services/calendar/calendarEventsCache';
import { readLocalCalendarSnapshotSync } from '@/app/services/calendar/calendarLocalSnapshot';
import type { CalendarSourceModule } from '@/app/services/calendarBridge.types';

export type UnifiedEventBridge = {
    sourceModule: CalendarSourceModule;
    sourceEntityId: string;
    sourceEventId: string;
    calendarRecordId: string;
};

export type UnifiedEvent = {
    id: string;
    title: string;
    date: string;
    time?: string;
    type: CalendarEventType;
    location?: string;
    notes?: string;
    clientName?: string;
    clientPhone?: string;
    revenue?: string;
    caseNo?: string;
    isCompleted?: boolean;
    source: 'deadline' | 'hearing' | 'calendar';
    isBridged?: boolean;
    bridge?: UnifiedEventBridge;
    /** حقول عرض مشتقة — من notes أو جسر التقويم */
    court?: string;
    partiesSummary?: string;
    sourceLabel?: string;
};

const CALENDAR_UPDATE_DEBOUNCE_MS = 300;
const CALENDAR_FETCH_TIMEOUT_MS = 6_000;
const CALENDAR_SAVE_TIMEOUT_MS = 8_000;

function withCalendarOpTimeout<T>(promise: Promise<T>, ms: number, label: string): Promise<T> {
    return Promise.race([
        promise,
        new Promise<T>((_, reject) => {
            window.setTimeout(() => reject(new Error(`${label}:timeout`)), ms);
        }),
    ]);
}

async function fetchCalendarEventsWithTimeout(
    userId: string,
    options?: { forceRefresh?: boolean },
): Promise<CalendarEvent[]> {
    return Promise.race([
        fetchCalendarEvents(userId, options),
        new Promise<CalendarEvent[]>((_, reject) => {
            window.setTimeout(() => reject(new Error('calendar-fetch-timeout')), CALENDAR_FETCH_TIMEOUT_MS);
        }),
    ]);
}

function newCalendarEventId(): string {
    if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
        return crypto.randomUUID();
    }
    return `cal_${Date.now()}_${Math.random().toString(36).slice(2, 11)}`;
}

function resolveInitialCalendarEvents(userId: string): CalendarEvent[] {
    if (hasCachedCalendarEvents(userId)) {
        return getCachedCalendarEvents(userId) ?? [];
    }
    return readLocalCalendarSnapshotSync(userId);
}

function toYmd(date: Date): string {
    const y = date.getFullYear();
    const m = String(date.getMonth() + 1).padStart(2, '0');
    const d = String(date.getDate()).padStart(2, '0');
    return `${y}-${m}-${d}`;
}

export function buildEventsByDateIndex(
    events: UnifiedEvent[],
    year: number,
    month: number,
): Map<string, UnifiedEvent[]> {
    const prefix = `${year}-${String(month + 1).padStart(2, '0')}`;
    const map = new Map<string, UnifiedEvent[]>();
    for (const e of events) {
        if (!e.date.startsWith(prefix)) continue;
        const bucket = map.get(e.date);
        if (bucket) bucket.push(e);
        else map.set(e.date, [e]);
    }
    return map;
}

export function useCalendarData(userId: string) {
    const effectiveUserId = resolveCalendarUserId(userId || null);
    const initialSnapshot = useMemo(
        () => resolveInitialCalendarEvents(effectiveUserId),
        [effectiveUserId],
    );
    const [customEvents, setCustomEvents] = useState<CalendarEvent[]>(initialSnapshot);
    const [syncing, setSyncing] = useState(false);
    const [backgroundSyncing, setBackgroundSyncing] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const hasLoadedOnceRef = useRef(true);
    const fetchInFlightRef = useRef(false);

    const fetchEvents = useCallback(
        async (options?: { background?: boolean; forceRefresh?: boolean }) => {
            if (!effectiveUserId) {
                setCustomEvents([]);
                setError('يجب تسجيل الدخول لعرض التقويم');
                setSyncing(false);
                setBackgroundSyncing(false);
                return;
            }
            if (fetchInFlightRef.current && options?.background) return;
            const isBackground = options?.background ?? hasLoadedOnceRef.current;
            if (isBackground) {
                setBackgroundSyncing(true);
            } else {
                setSyncing(true);
            }
            fetchInFlightRef.current = true;
            setError(null);
            try {
                const events = await fetchCalendarEventsWithTimeout(effectiveUserId, {
                    forceRefresh: options?.forceRefresh,
                });
                setCustomEvents(events);
                setCachedCalendarEvents(effectiveUserId, events);
            } catch (err) {
                const snapshot = readLocalCalendarSnapshotSync(effectiveUserId);
                if (snapshot.length > 0) {
                    setCustomEvents(snapshot);
                    setCachedCalendarEvents(effectiveUserId, snapshot);
                } else if (err instanceof Error && err.message === 'calendar-fetch-timeout') {
                    setError(null);
                } else {
                    setError('فشل تحميل أحداث التقويم');
                }
            } finally {
                hasLoadedOnceRef.current = true;
                fetchInFlightRef.current = false;
                setSyncing(false);
                setBackgroundSyncing(false);
            }
        },
        [effectiveUserId],
    );

    const applyLocalSnapshot = useCallback(() => {
        if (!effectiveUserId) return;
        invalidateCalendarEventsCache(effectiveUserId);
        const snapshot = readLocalCalendarSnapshotSync(effectiveUserId);
        setCustomEvents(snapshot);
        setCachedCalendarEvents(effectiveUserId, snapshot);
        hasLoadedOnceRef.current = true;
        if (snapshot.length > 0) {
            setSyncing(false);
            setBackgroundSyncing(false);
        }
    }, [effectiveUserId]);

    useEffect(() => {
        const snapshot = resolveInitialCalendarEvents(effectiveUserId);
        if (!hasCachedCalendarEvents(effectiveUserId)) {
            setCachedCalendarEvents(effectiveUserId, snapshot);
        }
        hasLoadedOnceRef.current = true;
        setCustomEvents(snapshot);
        setSyncing(false);
        setBackgroundSyncing(false);
        setError(null);

        let cancelled = false;
        void (async () => {
            if (cancelled) return;
            await fetchEvents({ background: true });
        })();

        return () => {
            cancelled = true;
        };
    }, [effectiveUserId, fetchEvents]);

    useEffect(() => {
        if (typeof window === 'undefined') return undefined;
        let debounceTimer: ReturnType<typeof setTimeout> | null = null;
        const onCalendarUpdated = () => {
            if (debounceTimer) clearTimeout(debounceTimer);
            debounceTimer = setTimeout(() => {
                applyLocalSnapshot();
            }, CALENDAR_UPDATE_DEBOUNCE_MS);
        };
        window.addEventListener(CALENDAR_UPDATED_EVENT, onCalendarUpdated);
        return () => {
            if (debounceTimer) clearTimeout(debounceTimer);
            window.removeEventListener(CALENDAR_UPDATED_EVENT, onCalendarUpdated);
        };
    }, [applyLocalSnapshot]);

    const allEvents = useMemo(() => mapStoredEventsToUnified(customEvents), [customEvents]);

    const eventsByDate = useMemo(() => {
        const map = new Map<string, UnifiedEvent[]>();
        for (const e of allEvents) {
            const bucket = map.get(e.date);
            if (bucket) bucket.push(e);
            else map.set(e.date, [e]);
        }
        return map;
    }, [allEvents]);

    const getEventsForDate = useCallback(
        (date: Date): UnifiedEvent[] => {
            return eventsByDate.get(toYmd(date)) ?? [];
        },
        [eventsByDate],
    );

    const addEvent = useCallback(
        async (event: Omit<CalendarEvent, 'id' | 'createdAt' | 'updatedAt'>) => {
            if (!effectiveUserId) {
                setError('يجب تسجيل الدخول لإضافة موعد');
                return null;
            }
            const now = new Date().toISOString();
            const newEvent: CalendarEvent = {
                ...event,
                userId: event.userId || effectiveUserId,
                id: newCalendarEventId(),
                createdAt: now,
                updatedAt: now,
            };

            setCustomEvents((prev) => {
                if (prev.some((e) => e.id === newEvent.id)) return prev;
                return [...prev, newEvent];
            });
            invalidateCalendarEventsCache(effectiveUserId);

            try {
                await saveCalendarEvent(newEvent);
                return newEvent;
            } catch {
                setCustomEvents((prev) => prev.filter((e) => e.id !== newEvent.id));
                setError('فشل إضافة الموعد');
                return null;
            }
        },
        [effectiveUserId],
    );

    const updateEvent = useCallback(async (event: CalendarEvent) => {
        const updated = { ...event, updatedAt: new Date().toISOString() };
        try {
            await updateCalendarEvent(updated);
            if (isBridgedCalendarEvent(updated)) {
                const { propagateBridgedCalendarUpdate } = await import(
                    '@/app/services/calendar/bridgePersistence/propagate'
                );
                await propagateBridgedCalendarUpdate(updated);
            }
            setCustomEvents((prev) => prev.map((e) => (e.id === event.id ? updated : e)));
            invalidateCalendarEventsCache(effectiveUserId);
            return updated;
        } catch {
            setError('فشل تحديث الموعد');
            return null;
        }
    }, [effectiveUserId]);

    const deleteEvent = useCallback(
        async (eventId: string) => {
            try {
                const existing = customEvents.find((e) => e.id === eventId);
                if (existing && isBridgedCalendarEvent(existing)) {
                    const { propagateBridgedCalendarRemoval } = await import(
                        '@/app/services/calendar/bridgePersistence/propagate'
                    );
                    await propagateBridgedCalendarRemoval(existing);
                }
                await deleteCalendarEvent(eventId, effectiveUserId);
                setCustomEvents((prev) => prev.filter((e) => e.id !== eventId));
                invalidateCalendarEventsCache(effectiveUserId);
            } catch {
                setError('فشل حذف الموعد');
            }
        },
        [effectiveUserId, customEvents],
    );

    return {
        allEvents,
        customEvents,
        loading: false,
        backgroundSyncing,
        syncing,
        error,
        effectiveUserId,
        getEventsForDate,
        addEvent,
        updateEvent,
        deleteEvent,
        refresh: () => fetchEvents({ background: false, forceRefresh: true }),
    };
}

