        handleEditEvent,
        handleAddAction,
        handleSaveFastTrack,
        editingEvent,
        setEditingEvent,
        setShowResumeInterruptionModal,
        handleInterruptionToggle,
        handleAbandonment,
        setShowPauseModal,
        isPaused,
