                                                        onClick={() => setShowTaskModal(true)}
                                                        className={PS_BTN_PEARL}
                                                        title="إضافة مهمة"
                                                    >
                                                        <Plus size={11} aria-hidden />
                                                    </button>
                                                }
                                            >
                                                <ToDoList
                                                    tasks={displayStage?.tasks || []}
                                                    visualVariant="personal-pearl"
