                                                />
                                            </PersonalStatusPearlSection>
                                        </div>
                                    ) : null}
                                </div>
                            </div>
                        )
                    ) : null}

                    <PersonalStatusPearlSection
                        label="سجل"
                        variant="glass"
                        className="mb-1 print:block"
                        bodyClassName="p-2 pt-1.5"
                    >
                        <TimelineFeed
                            events={displayTimeline}
                            visualVariant="personal-pearl"
                            onDelete={!isViewingArchived ? handleDeleteEvent : undefined}
