        isNew: true
    }, ...(currentStage.timeline ?? [])];

    // Also update the PARENT status
    setStatus('منتهية');

    debug.log(`🛑 الدعوى منتهية نهائياً. موعد الطعن النهائي: ${addDays(now, 30)}`);
}
}

import type { CaseStage, Party } from '../../../../LawyerShared';
