import type { JudgmentConfirmRuntime, JudgmentConfirmScope } from './judgmentConfirmTypes';

export function applyTransitionScenario(scope: JudgmentConfirmScope, rt: JudgmentConfirmRuntime): void {
    const { currentStage, activeStageIndex, parentData, stages, setStatus, setActiveStageIndex } = scope;
    const {
        judgmentData,
        action,
        judgmentType,
        judgmentForm,
        judgmentDate,
        notes,
        nextStage,
        now,
        stageName,
        addDays,
        updatedStages,
    } = rt;

if (action === 'transition') {
    rt.handled = true;
    debug.log('🔄 بدء عملية الانتقال للمرحلة التالية...');
    
    // Determine Decision Text based on Type
    let decisionText = `انتقال للمرحلة التالية (${judgmentType})`;
    let timelineTitle = `➡️ حكم بـ ${judgmentType} والانتقال`;
    
    if (judgmentType === 'إجابة الدعوى' || judgmentType === 'إجابة الدعوى بالكامل') {
        decisionText = 'إجابة الدعوى (حكم لصالح الموكل)';
        timelineTitle = '✅ حكم بإجابة الدعوى (حكم لصالح الموكل)';
    } else if (judgmentType === 'رد الدعوى' || judgmentType === 'رد الدعوى كلياً') {
        decisionText = 'رد الدعوى (حكم ضد الموكل)';
        timelineTitle = '❌ حكم برد الدعوى (حكم ضد الموكل)';
    } else if (judgmentType === 'رد الدعوى جزئياً') {
        decisionText = 'رد الدعوى جزئياً (حكم جزئي)';
        timelineTitle = '⚠️ حكم برد الدعوى جزئياً';
    }

    // STEP 1: Archive Current Stage
    updatedStages[activeStageIndex] = {
        ...currentStage,
        status: 'locked', 
        finalDecision: decisionText, // ✅ DYNAMIC DECISION
        decisionDate: judgmentDate,
        judgmentForm: judgmentForm
    };

    // Add judgment event to archived stage
    updatedStages[activeStageIndex].timeline = [{
        id: `judgment_${Date.now()}`,
        type: 'decision',
        date: judgmentDate,
        title: timelineTitle, // ✅ DYNAMIC TITLE
        details: `${notes}\n\n⚖️ صدر الحكم بـ "${judgmentType}".\n➡️ تم الانتقال مباشرة للمرحلة القادمة: ${nextStage}\n\n📁 تم أرشفة هذه المرحلة وحفظها كملف فرعي.`,
        isNew: true
    }, ...(currentStage.timeline ?? [])];

    debug.log(`📁 تم أرشفة مرحلة "${currentStage.stageName}" بالكامل`);

    // STEP 2: Wipe Parties (As requested by user)
    // No carrying over names or roles. Completely blank slate.
    const newParties: Party[] = [
        { id: Date.now(), role: 'صفة اطرف الأول', name: '', isClient: true, side: 'right' },
        { id: Date.now() + 1, role: 'صفة الطرف الثاني', name: '', isClient: false, side: 'left' },
    ];

    debug.log(`✨ تم تصفية أطراف الدعوى للمرحلة الجديدة: "${nextStage}"`);

    // STEP 4: CREATE THE NEW CLEAN SLATE STAGE (Child File)
    const newStageId = `stage_${Date.now()}`;
    const newStageObject: CaseStage = {
        id: newStageId,
        name: nextStage,
        stageName: nextStage,
        type: currentStage.type,
        caseNo: '',
        court: '',
        judge: '',
        timeline: [],
        tasks: [],
        incidentalCases: [],
        parties: newParties,
        createdDate: getLocalTodayYmd(),
        finalDecision: null,
        decisionDate: null,
        status: 'active',
    };

    debug.log(`✨ تم إنشاء مرحلة جديدة نظيفة: "${nextStage}"`);
    debug.log('📋 Timeline الجديد فارغ تماماً:', newStageObject.timeline?.length === 0);

    updatedStages.push(newStageObject);
    setActiveStageIndex(updatedStages.length - 1);

    // STEP 6: CRITICAL - Dynamic Stepper Update
    // Instead of searching by name, we rebuild stepper from actual stages
    // This allows for infinite custom stage names (e.g., "إعادة المحاكمة", "التنفيذ")
    debug.log(`🎯 تم تفعيل المرحلة الجديدة: \"${nextStage}\" بشكل ديناميكي`);
    debug.log(`📊 عدد المراحل الكلي: ${updatedStages.length}`);
}
}

import { SmartToast } from '@/app/components/ui/SmartToast';
import { debug } from '@/app/utils/debug';


import {
    interpleaderClientAwaitingOpponentAppeal,
    isInterpleaderJudgmentType,
    resolveInterpleaderDecisionText,
    resolveLawyerJudgmentBucket,
} from '../../../smartFile/interpleaderJudgmentEngine';
import { isPersonalStatusStageName } from '@/app/components/lawyer/personal-status/personalStatusStageDisplay';
import type { JudgmentConfirmRuntime, JudgmentConfirmScope } from './judgmentConfirmTypes';

export function applyWaitAppealScenarios(scope: JudgmentConfirmScope, rt: JudgmentConfirmRuntime): void {
    const { currentStage, activeStageIndex, parentData, stages, setStatus, setActiveStageIndex } = scope;
    const {
        judgmentData,
        action,
        judgmentType,
        judgmentForm,
        judgmentDate,
        notes,
        nextStage,
        now,
        stageName,
        addDays,
        updatedStages,
    } = rt;

if (action === 'waiting_for_appeal') {
    rt.handled = true;
    const isGhayabi = judgmentForm === 'غيابي';
    const plaintiffFavorableGhayabi =
        isGhayabi
        && (judgmentType === 'إجابة الدعوى'
            || judgmentType === 'إجابة الدعوى بالكامل'
            || judgmentType === 'رد الدعوى جزئياً'
            || judgmentType === 'إجابة دعوى المدعي (جزئياً)');

    let appealDeadline: string | undefined;
    let awaitingAbsentJudgmentNotification = false;

    if (plaintiffFavorableGhayabi && !judgmentData.openObjectionModal) {
        awaitingAbsentJudgmentNotification = true;
    } else if (isGhayabi) {
        appealDeadline = addDays(now, 10);
    } else if (judgmentForm === 'حضوري' && (stageName.includes('بداءة') || isPersonalStatusStageName(stageName))) {
        appealDeadline = addDays(now, 15);
    }

    const lawyerBucket = resolveLawyerJudgmentBucket(
        parentData.representedParty,
        currentStage.parties,
    );

    let decisionText = `محسومة - بانتظار الطعن (${judgmentType})`;
    if (isInterpleaderJudgmentType(judgmentType)) {
        decisionText = resolveInterpleaderDecisionText(judgmentType, lawyerBucket);
    } else if (plaintiffFavorableGhayabi && awaitingAbsentJudgmentNotification) {
        decisionText = 'حكم غيابي — بانتظار التبليغ والاعتراض';
    } else if (judgmentType === 'إجابة الدعوى' || judgmentType === 'إجابة الدعوى بالكامل') {
        decisionText = 'محسومة لصالح الموكل - بانتظار الطعن';
    } else if (judgmentType === 'رد الدعوى' || judgmentType === 'رد الدعوى كلياً') {
        decisionText = 'محسومة ضد الموكل - بانتظار الطعن';
    } else if (judgmentType === 'رد الدعوى جزئياً') {
        decisionText = 'محسومة جزئياً - بانتظار الطعن';
    }

    const awaitingOpponentAppeal =
        !awaitingAbsentJudgmentNotification
        && (isInterpleaderJudgmentType(judgmentType)
            ? interpleaderClientAwaitingOpponentAppeal(judgmentType, lawyerBucket)
            : judgmentType === 'إجابة الدعوى' || judgmentType === 'إجابة الدعوى بالكامل');

    updatedStages[activeStageIndex] = {
        ...currentStage,
        status: 'active',
        finalDecision: decisionText,
        judgmentForm:
            judgmentForm === 'غيابي' || judgmentForm === 'حضوري'
                ? judgmentForm
                : undefined,
        lastJudgmentType:
            judgmentForm === 'غيابي' || judgmentForm === 'حضوري'
                ? judgmentForm
                : undefined,
        decisionDate: judgmentDate,
        isPleadingsClosed: true,
        awaitingOpponentAppeal,
        awaitingAbsentJudgmentNotification,
        appealDeadline: appealDeadline,
        legalTimers: {
            appealDeadline: appealDeadline || addDays(now, 15),
            cassationDeadline: addDays(now, 30),
            defaultObjectionDeadline:
                isGhayabi && !awaitingAbsentJudgmentNotification
                    ? appealDeadline
                    : undefined,
        },
    };

    // Add timeline event
    updatedStages[activeStageIndex].timeline = [{
        id: `judgment_${Date.now()}`,
        type: 'decision',
        date: judgmentDate,
        title: `✅ حكم بـ ${judgmentType} (${judgmentForm})`,
        details: `${notes}\n\n⚖️ صدر الحكم بـ "${judgmentType}".\n⏳ الحالة: بانتظار انتهاء المدة القانونية للطعن.\n\n📅 مواعيد الطعن القانونية:\n${
            isPersonalStatusStageName(stageName)
                ? `- التمييز: متاح حتى ${addDays(now, 30)}`
                : `- الاستئناف: متاح حتى ${addDays(now, 15)}\n- التمييز: متاح حتى ${addDays(now, 30)}`
        }`,
        isNew: true
    }, ...(currentStage.timeline ?? [])];

    debug.log(`✅ المرحلة "${stageName}" محسومة: "${decisionText}"`);

    setStatus('بانتظار الطعن');
    rt.successToast = 'تم حفظ الحكم — بانتظار طعن الخصم ⏳';

    if (judgmentData.openObjectionModal) {
        rt.openObjectionModalAfterSave = true;
    }
    if (judgmentData.openRegisterOpponentAppealModal) {
        rt.openAppealModalAfterSave = true;
    }
}

// ========================================
// SCENARIO 1a: انتظار تمييز الخصم (بعد كسب الاستئناف)
// ========================================
else if (action === 'waiting_for_cassation') {
    rt.handled = true;

    let decisionText = `محسومة لصالح الموكل - بانتظار التمييز (${judgmentType})`;
    if (judgmentType === 'فسخ الحكم البدائي كلياً' || judgmentType === 'فسخ الحكم المستأنف كلياً') {
        decisionText = 'محسومة لصالح الموكل - بانتظار تمييز الخصم';
    }

    updatedStages[activeStageIndex] = {
        ...currentStage,
        status: 'active',
        finalDecision: decisionText,
        judgmentForm:
            judgmentForm === 'غيابي' || judgmentForm === 'حضوري' ? judgmentForm : undefined,
        lastJudgmentType:
            judgmentForm === 'غيابي' || judgmentForm === 'حضوري' ? judgmentForm : undefined,
        decisionDate: judgmentDate,
        isPleadingsClosed: true,
        awaitingOpponentAppeal: true,
        legalTimers: {
            cassationDeadline: addDays(now, 30),
        },
    };

    updatedStages[activeStageIndex].timeline = [{
        id: `judgment_cass_wait_${Date.now()}`,
        type: 'decision',
        date: judgmentDate,
        title: `✅ حكم بـ ${judgmentType}`,
        details: `${notes}\n\n⚖️ صدر الحكم بـ "${judgmentType}".\n⏳ الحالة: بانتظار تمييز الخصم.\n\n📅 موعد التمييز: متاح حتى ${addDays(now, 30)}`,
        isNew: true,
    }, ...(currentStage.timeline ?? [])];

    setStatus('بانتظار التمييز');
    rt.successToast = 'تم حفظ القرار — بانتظار تمييز الخصم ⏳';

    if (judgmentData.openRegisterOpponentAppealModal) {
        rt.openAppealModalAfterSave = true;
    }
}

// ========================================
// SCENARIO 1b: ختم لصالح المدعي — لا حق للطعن (وكيل المدعي)
// ========================================
else if (action === 'seal_plaintiff_win') {
    rt.handled = true;
    let appealDeadline: string | undefined;
    if (judgmentForm === 'حضوري' && stageName.includes('البداءة')) {
        appealDeadline = addDays(now, 15);
    }

    const decisionText = 'إجابة الدعوى بالكامل — ختم الإضبارة (لا حق للطعن)';

    updatedStages[activeStageIndex] = {
        ...currentStage,
        status: 'completed',
        finalDecision: decisionText,
        judgmentForm:
            judgmentForm === 'غيابي' || judgmentForm === 'حضوري' ? judgmentForm : undefined,
        lastJudgmentType:
            judgmentForm === 'غيابي' || judgmentForm === 'حضوري' ? judgmentForm : undefined,
        decisionDate: judgmentDate,
        isPleadingsClosed: true,
        appealDeadline,
        legalTimers: {
            appealDeadline: appealDeadline || addDays(now, 15),
            cassationDeadline: addDays(now, 30),
        },
    };

    updatedStages[activeStageIndex].timeline = [{
        id: `judgment_seal_${Date.now()}`,
        type: 'milestone',
        date: judgmentDate,
        title: '✅ حكم بإجابة الدعوى بالكامل — ختم الإضبارة',
        details: `${notes}\n\n🏛️ تم كسب الدعوى لصالح الموكل.\n🔒 خُتمت الإضبارة — لا مصلحة قانونية للطعن من جانب المدعي.\n⏳ يحق للمدعى عليه الطعن تمييزاً خلال المدة القانونية.`,
        isNew: true,
        color: 'emerald',
    }, ...(currentStage.timeline ?? [])];

    setStatus('ختم المرافعة');
    SmartToast.success('تم ختم الإضبارة — كسب الدعوى ✅');
}
}

import type { TimelineEvent } from '../../../LawyerShared';
import { SmartToast } from '@/app/components/ui/SmartToast';
import { debug } from '@/app/utils/debug';
import {
    applyAppealStageTransition,
} from '../../smartFile/appealStageTransition';
import type {
    AppealTransitionPayload,
} from '../../smartFile/judgmentTypes';
import {
    str,
} from '../../smartFile/judgmentTypes';


import { resolveAppealDossierLayout, inferAppellantSideFromLawyer } from '../../smartFile/appealPartyEngine';


import type { UseSmartFileJudgmentActionsOptions } from './judgmentHookTypes';
import { resolveCalendarUserId } from '@/app/services/calendarBridge';
import { buildLawsuitCalendarContext } from '../procedural/lawsuitCalendarContext';
import { mirrorStageLegalDatesToCalendar } from '@/app/services/lawsuitTimelineCalendarMirror';

export function useAppealTransitionAction(options: UseSmartFileJudgmentActionsOptions) {
    const {
        stages,
        setStages,
        activeStageIndex,
        setActiveStageIndex,
        setViewingStageIndex,
        currentStage,
        parentData,
        saveToCloud,
        setStatus,
        tempJudgmentData,
        setTempJudgmentData,
        setShowAppealTransitionModal,
        setShowAppealModal,
        setShowObjectionRegistrationModal,
        setShowJudgmentModal,
        setShowCrossAppealModal,
        setShowTransitionModal,
    } = options;

const handleAppealTransition = (appealData: AppealTransitionPayload) => {
    debug.log('🔄 بدء معالجة الانتقال للطعن:', appealData);

    if (!tempJudgmentData) {
        debug.error('❌ خطأ: لا توجد بيانات حكم مؤقتة');
        return;
    }

    const judgmentType = str(tempJudgmentData.judgmentType);
    const judgmentForm = str(tempJudgmentData.judgmentForm);
    const judgmentDate = str(tempJudgmentData.judgmentDate);
    const judgmentNotes = str(tempJudgmentData.notes);
    const { appealType, appellant, filingDate, newCaseNumber, notes: appealNotes, includedOpponentPartyIds, includedAppellantPartyIds } = appealData;

    const dossierLayout = resolveAppealDossierLayout(currentStage.parties ?? [], {
        judgmentType,
        representedParty: parentData.representedParty,
        incidentalCases: currentStage.incidentalCases,
        standardAppellantSide: inferAppellantSideFromLawyer(
            parentData.representedParty,
            currentStage.parties,
        ),
    });

    let decisionText = `انتقال لمرحلة ${appealType} (${judgmentType})`;
    let timelineTitle = `➡️ حكم بـ ${judgmentType} والانتقال`;

    if (judgmentType === 'إجابة الدعوى' || judgmentType === 'إجابة الدعوى بالكامل') {
        decisionText = 'إجابة الدعوى (حكم لصالح الموكل)';
        timelineTitle = '✅ حكم بإجابة الدعوى (حكم لصالح الموكل)';
    } else if (judgmentType === 'رد الدعوى' || judgmentType === 'رد الدعوى كلياً') {
        decisionText = 'رد الدعوى (حكم ضد الموكل)';
        timelineTitle = '❌ حكم برد الدعوى (حكم ضد الموكل)';
    } else if (judgmentType === 'رد الدعوى جزئياً') {
        decisionText = 'رد الدعوى جزئياً (حكم جزئي)';
        timelineTitle = '⚠️ حكم برد الدعوى جزئياً';
    }

    const archiveJudgmentEvent: TimelineEvent = {
        id: `judgment_${Date.now()}`,
        type: 'decision',
        date: judgmentDate,
        title: timelineTitle,
        details: `${judgmentNotes}\n\n⚖️ صدر الحكم بـ "${judgmentType}".\n➡️ تم الطعن في الحكم والانتقال لمرحلة ${appealType}\n\n📋 تفاصيل الطعن:\n- مقدم الطعن: ${appellant}\n- رقم دعوى ${appealType}: ${newCaseNumber}\n- تاريخ تقديم اللائحة: ${filingDate}\n\n📁 بقيت إضبارة المرحلة السابقة محفوظة ومقفولة.`,
        isNew: true,
    };

    const { updatedStages, newActiveIndex } = applyAppealStageTransition(
        stages,
        activeStageIndex,
        currentStage,
        {
            appealType,
            appellant,
            filingDate,
            newCaseNumber,
            notes: appealNotes,
            archiveTimelineEvent: archiveJudgmentEvent,
            archiveFinalDecision: decisionText,
            archiveDecisionDate: judgmentDate,
            includedOpponentPartyIds,
            includedAppellantPartyIds,
            dossierLayout,
            priorJudgmentType: judgmentType,
        },
    );

    const newStage = updatedStages[newActiveIndex];
    debug.log(`📁 تم قفل مرحلة "${currentStage.stageName}" مع الإبقاء على سجلها`);
    debug.log(`✨ تم انقلاب المراكز — مقدم الطعن: ${appellant}`);
    debug.log('👥 الأطراف بعد انقلاب المراكز:', newStage?.parties?.map((p) => `${p.role}: ${p.name}`).join(', '));

    const calCtx = buildLawsuitCalendarContext(parentData, resolveCalendarUserId());
    const stagesForCalendar = mirrorStageLegalDatesToCalendar(updatedStages, activeStageIndex, calCtx);

    setStages(stagesForCalendar);
    setActiveStageIndex(newActiveIndex);
    setViewingStageIndex(newActiveIndex);
    saveToCloud(stagesForCalendar, parentData, newActiveIndex);
    setShowAppealTransitionModal(false);
    setTempJudgmentData(null);
    setStatus(`مرحلة ${newStage?.stageName ?? appealType}`);

    SmartToast.success(`تم الانتقال لمرحلة ${appealType} — بقيت إضبارة المرحلة السابقة متاحة للعرض`);
    debug.log(`✅ تم الانتقال بنجاح لمرحلة ${appealType} برقم ${newCaseNumber}`);
};


    return {
        handleAppealTransition,
    };
}

