                                    <IncidentalCasesManager 
                                        cases={displayStage?.incidentalCases || []} 
                                        onResolve={!isViewingArchived ? handleResolveIncidentalCase : undefined}
                                        onOpenLinkedFile={onOpenLinkedFile}
                                    />
                                </div>
                            ) : null}

                            {/* 4. Quick Actions */}
                            {!isViewingArchived && !isCassationStage && (
                                <div className="print:hidden">
                                    <QuickActions
                                        variant={quickActionsVariant}
                                        onAction={handleQuickAction}
                                        onPause={() => setShowPauseModal(true)}
                                        onOpenLegalActions={() => setIsActionsMenuOpen(true)}
                                    />
                                </div>
                            )}

                            {/* Civil law reference — القضاء المدني فقط */}
                            {!isViewingArchived && !isCassationStage && (
                                <CivilLawReferenceHub readOnly={isViewingArchived} />
                            )}

                            {/* 5. Session record + Requests — فقط أثناء المرافعة المفتوحة */}
                            {!isViewingArchived && !isCassationStage && !displayStage?.isPleadingsClosed && (
                                <SessionAndRequestsHub
                                    readOnly={isViewingArchived}
                                    visualVariant="civil"
                                    timeline={displayTimeline}
                                    editingSessionRecord={
                                        editingEvent
                                            && isSessionTimelineEvent(editingEvent)
                                            && !isOpponentProceedingsEvent(editingEvent)
                                            ? editingEvent
                                            : null
                                    }
                                    onCancelEditSessionRecord={() => setEditingEvent(null)}
                                    onSubmitSessionRecord={(data) => {
                                        handleAddAction(buildSessionRecordPayload(data, data.id));
                                    }}
                                    onAddFastTrack={(preset) => {
                                        setEditingFastTrack(
                                            preset?.requestType
                                                ? { type: preset.requestType, requestType: preset.requestType }
                                                : null,
                                        );
                                        setShowFastTrackModal(true);
                                    }}
                                    petitions={displayStage?.fastTrackPetitions ?? []}
                                    attachments={displayStage?.attachments ?? []}
                                    onEditPetition={(petition) => {
                                        setEditingFastTrack(petition as unknown as Record<string, unknown>);
                                        setShowFastTrackModal(true);
                                    }}
                                    onEditAttachment={(attachment) => {
                                        setEditingAttachment(attachment as unknown as Record<string, unknown>);
                                        setShowAttachmentModal(true);
                                    }}
                                    onResolvePetition={(petition, outcome) => {
                                        handleSaveFastTrack({
                                            id: petition.id,
                                            type: petition.requestType || petition.type || '',
                                            requestType: petition.requestType || petition.type || '',
                                            reason: petition.subject || petition.reason || '',
                                            subject: petition.subject || petition.reason || '',
                                            requestDate: petition.submissionDate || petition.requestDate || '',
                                            submissionDate: petition.submissionDate || petition.requestDate || '',
                                            status: storedFastTrackStatus(outcome),
                                            notes: '',
                                        });
                                    }}
                                />
                            )}

                            {/* 6. To-Do List - CRITICAL: Display viewedStage tasks - Hide in Cassation OR Pleadings Closed */}
                            {!isViewingArchived && !isCassationStage && !displayStage?.isPleadingsClosed && (
                                <div className="mt-4 pt-1">
                                <ToDoList 
                                    tasks={displayStage?.tasks || []} 
                                    visualVariant="civil"
                                    onAddTask={() => setShowTaskModal(true)}
                                    onToggleTask={handleToggleTask}
                                    onAppealBriefFile={handleAppealBriefFile}
                                    onAppealBriefOutcome={handleAppealBriefOutcome}
                                    onCorrespondenceResponse={handleCorrespondenceResponse}
                                    onEditTask={(task) => setEditingTask(task)}
                                />
                                </div>
                            )}

                            {/* 6. Timeline - collapsible */}
                            <div className="mb-4 print:block">
                                <button
                                    type="button"
                                    onClick={() => setIsTimelineExpanded((v) => !v)}
                                    className="w-full flex items-center justify-between gap-2 pb-2 border-b text-right group/timeline-head print:pointer-events-none border-white/5"
                                    aria-expanded={isTimelineExpanded}
                                >
                                    <span className="text-lg font-bold flex items-center gap-2 min-w-0 text-gray-300">
                                        <Clock size={18} className="shrink-0 text-[#E6C673]" />
                                        السجل الزمني
                                        {timelineEventCount > 0 ? (
                                            <span className="text-[10px] font-bold text-white/40 tabular-nums">
                                                ({timelineEventCount})
                                            </span>
                                        ) : null}
                                    </span>
                                    <ChevronDown
                                        size={18}
                                        className={`shrink-0 transition-transform duration-200 print:hidden ${
                                            isTimelineExpanded ? 'rotate-180' : ''
                                        } text-[#E6C673]/70`}
                                        aria-hidden
                                    />
                                </button>

                                {isTimelineExpanded ? (
                                    <div className="mt-3 print:block">
                                        <TimelineFeed
                                            events={displayTimeline}
                                            visualVariant="civil"
                                            onDelete={!isViewingArchived ? handleDeleteEvent : undefined}
                                        />
                                    </div>
                                ) : null}
                            </div>
                        </div>

                            <SmartFileStageFooterBar
                            isViewingArchived={isViewingArchived}
                            showOpponentAppealBtnEffective={showOpponentAppealBtnEffective}
                            showAbsentJudgmentFooter={showAbsentJudgmentFooter}
                            showAppealStageFooter={showAppealStageFooter}
                            showPetitionVoidFooter={showPetitionVoidFooter}
                            displayStage={displayStage}
                            crossAppealEligibility={crossAppealEligibility}
                            setShowCrossAppealModal={setShowCrossAppealModal}
                            petitionVoidFooterPanel={petitionVoidFooterPanel}
                            absentJudgmentFooterPanel={absentJudgmentFooterPanel}
                            opponentAppealFooterPanel={opponentAppealFooterPanel}
                            appealStageFooterPanel={appealStageFooterPanel}
                            showPleadingCloseFooter={showPleadingCloseFooter}
                            setShowJudgmentModal={setShowJudgmentModal}
                            />
        </div>

    );
}

import React, { useState } from 'react';
import {
    ArrowRightLeft,
    Edit2,
    X,
} from 'lucide-react';
import { getLegalRole, type Party } from '../../LawyerShared';
import {
    classifyPartySideBucket,
    dedupePartiesList,
    partitionPartiesForHeader,
} from '../smartFile/partyRoleClassification';
import type { EditCaseInfoModalProps } from '../smartFile/modalFormTypes';
import { SmartToast } from '@/app/components/ui/SmartToast';
import { getLegalRoleTitle } from '../smartFile/legalRoleTitle';


export const EditCaseInfoModal = ({ isOpen, onClose, formData, onSave }: EditCaseInfoModalProps) => {
    const [caseNo, setCaseNo] = useState('');
    const [court, setCourt] = useState('');
    const [judge, setJudge] = useState('');
    const [stageName, setStageName] = useState(''); // This acts as baseStage
    const [extraordinaryType, setExtraordinaryType] = useState(''); // New State for Appeal Type
    const [caseType, setCaseType] = useState('');
    const [hasCrossAppeal, setHasCrossAppeal] = useState(false);

    // 🎯 CRITICAL: First Instance Data Preservation for Appeal Stage
    const [firstInstanceCaseNumber, setFirstInstanceCaseNumber] = useState('');
    const [firstInstanceCourt, setFirstInstanceCourt] = useState('');

    // 🆕 APPEAL DATA
    const [appealCaseNumber, setAppealCaseNumber] = useState('');
    const [appealCourtName, setAppealCourtName] = useState('');

    // 🆕 THIRD PARTIES DATA
    const [thirdParties, setThirdParties] = useState<any[]>([]);

    // 🆕 Represented Party
    const [representedParty, setRepresentedParty] = useState<string | null>(null);

    const [plaintiffs, setPlaintiffs] = useState<any[]>([]);
    const [defendants, setDefendants] = useState<any[]>([]);
    const [preservedExtraParties, setPreservedExtraParties] = useState<Party[]>([]);

    // 🛡️ AUTO-CALCULATE LEGAL ROLE (based on stage name)
    // calculateLegalRole removed in favor of getLegalRole from LawyerShared

    // Load once when the modal opens — do not depend on formData identity
    // (parent passes a fresh object each render and would wipe in-progress edits).
    React.useEffect(() => {
        if (!isOpen || !formData) return;

        setCaseNo(formData.caseNo || '');
        setCourt(formData.court || '');
        setJudge(formData.judge || '');
        setStageName(formData.stageName || 'البداءة');
        setExtraordinaryType(formData.extraordinaryType || '');
        setCaseType(formData.docType || formData.type || '');
        setHasCrossAppeal(formData.hasCrossAppeal || false);

        setFirstInstanceCaseNumber(formData.firstInstanceCaseNumber || '');
        setFirstInstanceCourt(formData.firstInstanceCourt || '');

        setAppealCaseNumber(formData.appealCaseNumber || '');
        setAppealCourtName(formData.appealCourtName || '');

        setThirdParties(formData.thirdParties || []);

        setRepresentedParty(formData.representedParty || null);

        const allParties = (formData.parties || []).map((p: any) => ({
            ...p,
            lawyers: p.lawyers ? p.lawyers.map((l: any) => ({ ...l })) : [],
        }));

        const { plaintiffs: pList, defendants: dList, interpleaders } = partitionPartiesForHeader(
            allParties as Party[],
        );
        setPreservedExtraParties(interpleaders);

        let nextPlaintiffs = pList;
        let nextDefendants = dList;

        if (nextPlaintiffs.length === 0 && nextDefendants.length === 0) {
            if (allParties.length > 0) nextPlaintiffs = [allParties[0]];
            if (allParties.length > 1) nextDefendants = allParties.slice(1);
        }

        if (nextPlaintiffs.length === 0) nextPlaintiffs = [{ name: '', role: 'plaintiff' }];
        if (nextDefendants.length === 0) nextDefendants = [{ name: '', role: 'defendant' }];

        setPlaintiffs(nextPlaintiffs);
        setDefendants(nextDefendants);
        // eslint-disable-next-line react-hooks/exhaustive-deps -- sync only on open
    }, [isOpen]);

    const handleAddParty = (type: 'plaintiff' | 'defendant') => {
        const activeStage = extraordinaryType || stageName;
        const currentList = type === 'plaintiff' ? plaintiffs : defendants;
        // 🚀 AUTO-INHERIT ROLE: If group has members, new member inherits the first member's role
        const inheritedRole = currentList.length > 0 ? currentList[0].role : (type === 'plaintiff' ? 'مدعي' : 'مدعى عليه');

        const newParty = { 
            name: '', 
            address: '', 
            phone: '',
            lawyerName: '',
            lawyerPhone: '',
            lawyers: [{ name: '', phone: '' }],
            // 🆕 New Lawyer Structure
            lawyer: { name: '', phone: '', isMyOffice: false }, 
            role: inheritedRole,
            legalRole: getLegalRole(activeStage, type === 'plaintiff' ? 1 : 2, 1)
        };
        if (type === 'plaintiff') setPlaintiffs([...plaintiffs, newParty]);
        else setDefendants([...defendants, newParty]);
    };

    const handleRemoveParty = (type: 'plaintiff' | 'defendant', index: number) => {
        if (type === 'plaintiff') {
            if (plaintiffs.length <= 1) return; // Prevent deleting last one
            setPlaintiffs(plaintiffs.filter((_, i) => i !== index));
        } else {
            if (defendants.length <= 1) return; // Prevent deleting last one
            setDefendants(defendants.filter((_, i) => i !== index));
        }
    };

    const handleUpdateParty = (type: 'plaintiff' | 'defendant', index: number, field: string, value: any) => {
        const list = type === 'plaintiff' ? plaintiffs : defendants;
        const setter = type === 'plaintiff' ? setPlaintiffs : setDefendants;

        // 🛡️ IMMUTABLE UPDATE PATTERN
        let newList = list.map((item, i) => {
            if (i !== index) return item;

            const newItem = { ...item };

            // Handle Legacy Lawyer Fields
            if (field === 'lawyerName' || field === 'lawyerPhone') {
                 const currentLawyer = newItem.lawyers?.[0] || { name: '', phone: '' };
                 const newLawyer = { ...currentLawyer };

                 if (field === 'lawyerName') newLawyer.name = value;
                 if (field === 'lawyerPhone') newLawyer.phone = value;

                 newItem.lawyers = [newLawyer];
                 newItem[field] = value; 

                 // Sync with new structure
                 if (!newItem.lawyer) newItem.lawyer = { name: '', phone: '', isMyOffice: false };
                 if (field === 'lawyerName') newItem.lawyer.name = value;
                 if (field === 'lawyerPhone') newItem.lawyer.phone = value;
            } 
            // Handle New Lawyer Structure
            else if (field.startsWith('lawyer.')) {
                if (!newItem.lawyer) newItem.lawyer = { name: '', phone: '', isMyOffice: false };

                const key = field.split('.')[1]; // name, phone, or isMyOffice

                // 🛑 Conflict of Interest Check
                if (key === 'isMyOffice' && value === true) {
                    // Check if opposing side has "My Office" checked
                    const opposingList = type === 'plaintiff' ? defendants : plaintiffs;
                    const hasConflict = opposingList.some(p => p.lawyer?.isMyOffice || p.isClient);

                    if (hasConflict) {
                        SmartToast.error("⚠️ تعارض مصالح: لا يمكن تمثيل الطرفين في نفس الدعوى!");
                        return item; // Abort update
                    }

                    // Auto-mark as client
                    newItem.isClient = true;

                    // 🛡️ Set Represented Party
                    setRepresentedParty(type === 'plaintiff' ? 'المدعي' : 'المدعى عليه');
                } else if (key === 'isMyOffice' && value === false) {
                     // If unchecking, and this was the only client, should we set representedParty to null?
                     // Let's check if there are any other clients for this side.
                     // But for now, just unset isClient.
                     newItem.isClient = false;
                     // We don't unset representedParty here because another party on the same side might still be client.
                     // But if we want perfect sync, we can re-evaluate on save.
                }

                newItem.lawyer = { ...newItem.lawyer, [key]: value };

                // Sync legacy fields
                if (key === 'name') {
                    newItem.lawyerName = value;
                    if (!newItem.lawyers || newItem.lawyers.length === 0) newItem.lawyers = [{}];
                    newItem.lawyers[0].name = value;
                }
                if (key === 'phone') {
                    newItem.lawyerPhone = value;
                    if (!newItem.lawyers || newItem.lawyers.length === 0) newItem.lawyers = [{}];
                    newItem.lawyers[0].phone = value;
                }
            }
            else {
                 newItem[field] = value;
            }
            return newItem;
        });

        // Legal roles are locked — ignore role edits from any leftover callers
        if (field === 'role' || field === 'legalRole') {
            return;
        }

        setter(newList);
    };

    const handleSubmit = () => {
        const activeStage = extraordinaryType || stageName;

        const normalizeSideForSave = (list: typeof plaintiffs, side: 1 | 2) => {
            const named = list.filter((p) => String(p.name ?? '').trim());
            const source = named.length > 0 ? named : list.slice(0, 1);
            const count = named.length > 0 ? named.length : source.length;
            const role = getLegalRole(activeStage, side, count, extraordinaryType || undefined);
            return source.map((p) => ({
                ...p,
                role,
                legalRole: role,
                side: side === 1 ? ('right' as const) : ('left' as const),
                ...(p.lawyer?.isMyOffice === false
                    ? { isClient: false, lawyer: { ...p.lawyer, isMyOffice: false } }
                    : {}),
            }));
        };

        const updatedPlaintiffs = normalizeSideForSave(plaintiffs, 1);
        const updatedDefendants = normalizeSideForSave(defendants, 2);

        const allParties = dedupePartiesList([
            ...updatedPlaintiffs,
            ...updatedDefendants,
            ...preservedExtraParties,
        ] as Party[]);

        const clientParty = allParties.find((p) => p.isClient || p.lawyer?.isMyOffice);
        const resolvedRepresentedParty = clientParty
            ? (() => {
                  const bucket = classifyPartySideBucket(clientParty);
                  if (bucket === 'plaintiff') return 'المدعي';
                  if (bucket === 'defendant') return 'المدعى عليه';
                  return representedParty;
              })()
            : null;

        const saveData: any = {
            caseNo,
            court,
            judge,
            stageName,
            extraordinaryType,
            type: caseType,
            parties: allParties,
            thirdParties: thirdParties,
            hasCrossAppeal: hasCrossAppeal,
            representedParty: resolvedRepresentedParty,
            appealCaseNumber,
            appealCourtName
        };

        // If in appeal stage, preserve First Instance data
        if (stageName?.includes('استئناف')) {
            saveData.firstInstanceCaseNumber = firstInstanceCaseNumber;
            saveData.firstInstanceCourt = firstInstanceCourt;
        }

        onSave(saveData);
        onClose();
    };

    if (!isOpen) return null;

    const glassField =
        'w-full rounded-xl border border-white/10 bg-white/[0.05] backdrop-blur-sm px-3 py-2.5 text-sm text-white outline-none transition-colors placeholder:text-white/30 focus:border-[#E6C673]/45 focus:ring-1 focus:ring-[#E6C673]/15';
    const glassLabel = 'mb-1.5 block text-[10px] font-bold text-white/45';

    return (
        <div className="fixed inset-0 z-[250] flex items-center justify-center bg-black/70 backdrop-blur-md p-4 font-['Tajawal']">
            <div
                className="relative w-full max-w-2xl max-h-[90vh] overflow-y-auto scrollbar-hide rounded-2xl border border-white/12 shadow-[0_24px_60px_rgba(0,0,0,0.45)]"
                style={{
                    background:
                        'radial-gradient(circle at top, rgba(230,198,115,0.1), transparent 40%), linear-gradient(180deg, rgba(14,20,34,0.94), rgba(8,12,22,0.97))',
                    backdropFilter: 'blur(20px)',
                }}
            >
                <div className="sticky top-0 z-10 flex items-center justify-between border-b border-white/10 bg-white/[0.04] px-4 py-3.5 backdrop-blur-xl">
                    <h3 className="font-bold text-[#E6C673] flex items-center gap-2 text-sm">
                        <Edit2 size={16} /> تعديل بيانات الدعوى
                    </h3>
                    <button
                        type="button"
                        onClick={onClose}
                        className="rounded-full p-1.5 text-white/50 hover:bg-white/10 hover:text-white transition-colors"
                        aria-label="إغلاق"
                    >
                        <X size={18} />
                    </button>
                </div>

                <div className="p-5 sm:p-6 space-y-6">
                    <div className="space-y-4 border-b border-white/[0.06] pb-5">
                        <h4 className="text-[#E6C673] text-sm font-bold">بيانات الدعوى</h4>

                        {stageName?.includes('استئناف') && (
                            <div className="rounded-xl border border-white/10 bg-white/[0.03] p-4 space-y-3">
                                <h5 className="text-xs font-bold text-white/50">بيانات مرحلة البداءة (محفوظة)</h5>
                                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                                    <div>
                                        <label className={glassLabel}>رقم دعوى البداءة</label>
                                        <input 
                                            type="text" 
                                            value={firstInstanceCaseNumber} 
                                            readOnly
                                            className={`${glassField} opacity-70 cursor-default`}
                                            dir="ltr"
                                        />
                                    </div>
                                    <div>
                                        <label className={glassLabel}>محكمة البداءة</label>
                                        <input 
                                            type="text" 
                                            value={firstInstanceCourt} 
                                            readOnly
                                            className={`${glassField} opacity-70 cursor-default`}
                                        />
                                    </div>
                                </div>
                            </div>
                        )}

                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                            <div>
                                <label className={glassLabel}>
                                    {stageName?.includes('استئناف') ? 'رقم دعوى الاستئناف' : 'رقم الدعوى'}
                                </label>
                                <input 
                                    type="text" 
                                    value={caseNo} 
                                    onChange={e => setCaseNo(e.target.value)} 
                                    className={`${glassField} text-right`}
                                    dir="ltr" 
                                />
                            </div>
                            <div>
                                <label className={glassLabel}>
                                    {stageName?.includes('استئناف') ? 'محكمة الاستئناف' : 'المحكمة المختصة'}
                                </label>
                                <input 
                                    type="text" 
                                    value={court} 
                                    onChange={e => setCourt(e.target.value)} 
                                    className={glassField}
                                />
                            </div>
                            <div>
                                <label className={glassLabel}>نوع الدعوى</label>
                                <input type="text" value={caseType} onChange={e => setCaseType(e.target.value)} className={glassField} />
                            </div>
                            <div>
                                <label className={glassLabel}>اسم القاضي</label>
                                <input type="text" value={judge} onChange={e => setJudge(e.target.value)} className={glassField} />
                            </div>
                        </div>
                    </div>

                    <div className="space-y-5">
                        <h4 className="text-[#E6C673] text-sm font-bold">أطراف الدعوى</h4>

                        <div className="rounded-xl border border-white/10 bg-white/[0.03] p-4">
                            {plaintiffs.length > 0 && (
                                <div className="flex justify-center w-full mb-4">
                                  <span className="text-xl font-extrabold text-[#E6C673] tracking-wide">
                                    {getLegalRoleTitle(plaintiffs[0].role, plaintiffs.length)}
                                  </span>
                                </div>
                            )}

                            <div className="space-y-5">
                                {plaintiffs.map((party, index) => (
                                    <div key={index} className="relative space-y-3 pt-4 border-t border-white/5 first:border-0 first:pt-0">
                                        {index > 0 && (
                                            <button type="button" onClick={() => handleRemoveParty('plaintiff', index)} className="absolute left-0 top-0 text-red-400 hover:text-red-300 p-1">
                                                <X size={14} />
                                            </button>
                                        )}

                                        <div>
                                            <label className={glassLabel}>الاسم الكامل {plaintiffs.length > 1 ? `(${index + 1})` : ''}</label>
                                            <input 
                                                type="text" 
                                                value={party.name || ''} 
                                                onChange={e => handleUpdateParty('plaintiff', index, 'name', e.target.value)} 
                                                className={glassField}
                                            />
                                        </div>
                                        <div>
                                            <label className={glassLabel}>العنوان</label>
                                            <input 
                                                type="text" 
                                                value={party.address || ''} 
                                                onChange={e => handleUpdateParty('plaintiff', index, 'address', e.target.value)} 
                                                className={glassField}
                                            />
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>

                        <div className="rounded-xl border border-white/10 bg-white/[0.03] p-4">
                            {defendants.length > 0 && (
                                <div className="flex justify-center w-full mb-4">
                                  <span className="text-xl font-extrabold text-rose-300/90 tracking-wide">
                                    {getLegalRoleTitle(defendants[0].role, defendants.length)} 
                                  </span>
                                </div>
                            )}

                            <div className="space-y-5">
                                {defendants.map((party, index) => (
                                    <div key={index} className="relative space-y-3 pt-4 border-t border-white/5 first:border-0 first:pt-0">
                                        {index > 0 && (
                                            <button type="button" onClick={() => handleRemoveParty('defendant', index)} className="absolute left-0 top-0 text-red-400 hover:text-red-300 p-1">
                                                <X size={14} />
                                            </button>
                                        )}

                                        <div>
                                            <label className={glassLabel}>الاسم الكامل {defendants.length > 1 ? `(${index + 1})` : ''}</label>
                                            <input 
                                                type="text" 
                                                value={party.name || ''} 
                                                onChange={e => handleUpdateParty('defendant', index, 'name', e.target.value)} 
                                                className={glassField}
                                            />
                                        </div>
                                        <div>
                                            <label className={glassLabel}>العنوان</label>
                                            <input 
                                                type="text" 
                                                value={party.address || ''} 
                                                onChange={e => handleUpdateParty('defendant', index, 'address', e.target.value)} 
                                                className={glassField}
                                            />
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>

                    {stageName?.includes('استئناف') && (
                        <div className="rounded-xl border border-indigo-400/25 bg-indigo-500/[0.08] p-4 space-y-3">
                            <div className="flex items-center justify-between">
                                <div className="flex items-center gap-3">
                                    <div className="w-10 h-10 rounded-lg bg-indigo-500/20 flex items-center justify-center border border-indigo-500/30">
                                        <ArrowRightLeft size={18} className="text-indigo-300" />
                                    </div>
                                    <div>
                                        <h4 className="text-white text-sm font-bold">استئناف متقابل</h4>
                                        <p className="text-white/40 text-xs">هل يوجد استئناف متقابل من الخصم؟</p>
                                    </div>
                                </div>
                                <button type="button"
                                    onClick={() => setHasCrossAppeal(!hasCrossAppeal)}
                                    className={`relative w-14 h-7 rounded-full transition-all duration-300 ${
                                        hasCrossAppeal ? 'bg-indigo-500' : 'bg-white/10'
                                    }`}
                                >
                                    <div className={`absolute top-1 w-5 h-5 bg-white rounded-full shadow-lg transition-all duration-300 ${
                                        hasCrossAppeal ? 'right-1' : 'left-1'
                                    }`}
                                    />
                                </button>
                            </div>
                            {hasCrossAppeal && (
                                <p className="text-xs text-indigo-200/80 leading-relaxed rounded-lg border border-indigo-400/20 bg-indigo-950/30 px-3 py-2">
                                    سيظهر شريط يوضح وجود استئناف متقابل مقدم من الخصم.
                                </p>
                            )}
                        </div>
                    )}

                    <button
                        type="button"
                        onClick={handleSubmit}
                        className="w-full rounded-xl border border-[#E6C673]/40 bg-[linear-gradient(155deg,rgba(230,198,115,0.35),rgba(11,16,33,0.55)_48%,rgba(201,162,39,0.22))] py-3.5 text-sm font-bold text-[#F8F1DE] shadow-[inset_0_1px_0_rgba(255,249,230,0.2),0_10px_28px_rgba(0,0,0,0.3)] backdrop-blur-md transition-all hover:border-[#E6C673]/55"
                    >
                        حفظ التغييرات
                    </button>
                </div>
            </div>
        </div>
    );
};

import React, { useState } from 'react';
import {
    Eye,
    FileText,
    Loader2,
    Paperclip,
    RefreshCw,
    Trash2,
    UploadCloud,
} from 'lucide-react';
import { getLocalTodayYmd } from '@/app/utils/executionStateMachine';
import { resolveCalendarUserId } from '@/app/services/calendar/bridge';
import {
    prefetchVaultPdfViewerSurface,
    VaultPdfViewerSurfaceLazy,
} from '@/app/components/lawyer/SmartVaultModal/VaultPdfViewerSurfaceLazy';
import { SmartToast } from '@/app/components/ui/SmartToast';
import { SmartVaultDB } from '@/app/services/vault/smartVaultRuntime';
import type { SmartVaultDoc } from '@/app/services/vault/vaultTypes';
import {
    readFilePreviewUrl,
    resolveVaultDocForViewing,
} from '@/app/services/vaultUploadService';
import { revokeBlobUrlIfNeeded } from '@/app/services/vault/vaultDocUtils';
import { readVaultLocalIndexSync } from '@/app/services/vault/vaultLocalIndex';
import { fetchVaultDocsDeduped, seedVaultWarmCacheFromLocalIndex } from '@/app/services/vault/vaultDocsWarmCache';
import { CIVIL_LAWSUIT_TEST_IDS } from '../../smartFile/civilLawsuitTestIds';
import type { AddDocumentModalProps, TimelineEvent } from '../../smartFile/modalFormTypes';
import {
    MoroccanGlassShell,
} from '../../smartFile/moroccanGlassShell';
import { useSmartFileModalTheme } from '../../smartFile/smartFileModalTheme';
import * as Shared from './contentEntryShared';

const {
    SmartModalHeader,
    ModalInlineTimeline,
    normalizeDocLookupValue: _normalizeDocLookupValue,
    normalizeDocLookupStem: _normalizeDocLookupStem,
    findVaultDocForTimelineItem,
    inferDocumentCategoryFromFile,
    extractDocumentUserNotes,
    extractVaultDocSnapshot,
    DocumentTimelinePreview,
    FullDocumentPreviewOverlay,
} = Shared;

export const AddDocumentModal = ({
    isOpen,
    onClose,
    onAdd,
    editMode = false,
    editData,
    recentDocuments = [],
    onDeleteDocument,
    onReplaceDocument,
}: AddDocumentModalProps) => {
    const T = useSmartFileModalTheme();
    const isPearl = T.variant === 'personal-pearl';
    const [title, setTitle] = useState('');
    const [category, setCategory] = useState('');
    const [selectedFile, setSelectedFile] = useState<File | null>(null);
    const [notes, setNotes] = useState('');
    const [saving, setSaving] = useState(false);
    const [previewingEventId, setPreviewingEventId] = useState<string | null>(null);
    const [previewLoading, setPreviewLoading] = useState(false);
    const [fullPreviewOpen, setFullPreviewOpen] = useState(false);
    const [fullPreviewTitle, setFullPreviewTitle] = useState('');
    const [fullPreviewUrl, setFullPreviewUrl] = useState<string | null>(null);
    const [fullPreviewKind, setFullPreviewKind] = useState<'image' | 'pdf' | 'audio' | 'file' | null>(null);
    const [fullPreviewSource, setFullPreviewSource] = useState<string | Blob | null>(null);
    const [fullPreviewNonce, setFullPreviewNonce] = useState(0);
    const [missingPreviewIds, setMissingPreviewIds] = useState<string[]>([]);
    const [isFileDragActive, setIsFileDragActive] = useState(false);
    const fileInputRef = React.useRef<HTMLInputElement>(null);
    const fileInputId = React.useId();
    const isPreviewMissing = React.useCallback(
        (itemId: string) => missingPreviewIds.includes(itemId),
        [missingPreviewIds],
    );
    const markPreviewMissing = React.useCallback((itemId: string) => {
        setMissingPreviewIds((prev) => (prev.includes(itemId) ? prev : [...prev, itemId]));
    }, []);
    const clearPreviewMissing = React.useCallback((itemId: string) => {
        setMissingPreviewIds((prev) => prev.filter((entry) => entry !== itemId));
    }, []);
    const selectedFileKind = !selectedFile
        ? null
        : selectedFile.type.startsWith('image/')
          ? 'image'
          : selectedFile.type === 'application/pdf' || /\.pdf$/i.test(selectedFile.name)
            ? 'pdf'
            : 'file';
    const selectedPreviewUrl = React.useMemo(() => {
        if (!selectedFile) return null;
        try {
            if (selectedFileKind === 'image') return readFilePreviewUrl(selectedFile) ?? null;
            if (selectedFileKind === 'pdf') return URL.createObjectURL(selectedFile);
            return null;
        } catch {
            return null;
        }
    }, [selectedFile, selectedFileKind]);

    React.useEffect(() => {
        if (selectedFileKind === 'pdf' && selectedPreviewUrl) {
            prefetchVaultPdfViewerSurface();
        }
    }, [selectedFileKind, selectedPreviewUrl]);

    React.useEffect(() => {
        return () => revokeBlobUrlIfNeeded(selectedPreviewUrl);
    }, [selectedPreviewUrl]);

    React.useEffect(() => {
        return () => revokeBlobUrlIfNeeded(fullPreviewUrl);
    }, [fullPreviewUrl]);

    React.useEffect(() => {
        if (editMode && editData) {
            setTitle(editData.title || '');
            setCategory(editData.category || editData.docCategory || '');
            setNotes(extractDocumentUserNotes(editData.notes || editData.details || ''));
            setSelectedFile(null);
        } else {
            setTitle('');
            setCategory('');
            setNotes('');
            setSelectedFile(null);
        }
    }, [editMode, editData]);

    const applySelectedFile = React.useCallback(
        (nextFile: File | null) => {
            if (!nextFile) return;
            setPreviewingEventId(null);
            setSelectedFile(nextFile);
            if (!title.trim()) {
                setTitle(nextFile.name.replace(/\.[^/.]+$/, ''));
            }
            if (!category.trim()) {
                setCategory(inferDocumentCategoryFromFile(nextFile));
            }
        },
        [category, title],
    );

    const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
        applySelectedFile(e.target.files?.[0] ?? null);
        e.target.value = '';
    };

    const handleDropSelectedFile = (e: React.DragEvent<HTMLElement>) => {
        e.preventDefault();
        e.stopPropagation();
        setIsFileDragActive(false);
        applySelectedFile(e.dataTransfer.files?.[0] ?? null);
    };

    const handleDragState = (e: React.DragEvent<HTMLElement>, active: boolean) => {
        e.preventDefault();
        e.stopPropagation();
        setIsFileDragActive(active);
    };

    const handlePreviewSavedDocument = async (item: TimelineEvent) => {
        const itemId = String(item.id);
        setPreviewLoading(true);
        setPreviewingEventId(itemId);
        try {
            const snapshot = extractVaultDocSnapshot(item);
            let snapshotFailed = false;
            if (snapshot) {
                const payload = await resolveVaultDocForViewing(snapshot).catch(() => null);
                if (!payload) {
                    snapshotFailed = true;
                } else {
                    revokeBlobUrlIfNeeded(fullPreviewUrl);
                    setFullPreviewTitle(snapshot.fileName || snapshot.title);
                    setFullPreviewUrl(payload.url);
                    setFullPreviewKind(payload.kind);
                    setFullPreviewSource(payload.blob ?? payload.url);
                    setFullPreviewNonce((value) => value + 1);
                    setFullPreviewOpen(true);
                    clearPreviewMissing(itemId);
                    return;
                }
            }

            const candidateUserIds = Array.from(
                new Set([resolveCalendarUserId(), snapshot?.authorId].filter((value): value is string => Boolean(value?.trim()))),
            );
            const localDocs = readVaultLocalIndexSync();
            const findDocInList = (docs: SmartVaultDoc[]) =>
                (snapshotFailed && snapshot?.id ? docs.find((entry) => entry.id === snapshot.id) ?? null : null) ??
                findVaultDocForTimelineItem(item, docs);

            let doc = findDocInList(localDocs);
            for (const candidateUserId of candidateUserIds) {
                if (doc) break;
                const seededDocs = seedVaultWarmCacheFromLocalIndex(candidateUserId);
                doc = findDocInList(seededDocs);
            }
            for (const candidateUserId of candidateUserIds) {
                if (doc) break;
                const fetchedDocs = await fetchVaultDocsDeduped(candidateUserId);
                doc = findDocInList(fetchedDocs);
            }
            if (!doc) {
                markPreviewMissing(itemId);
                SmartToast.error('الملف الأصلي لهذا المستند غير موجود حالياً في الخزنة. أعد إرفاقه عبر استبدال.');
                return;
            }

            const payload = await resolveVaultDocForViewing(doc).catch(() => null);
            if (!payload) {
                markPreviewMissing(itemId);
                SmartToast.error('تعذر تجهيز هذا الملف للمعاينة. أعد إرفاقه عبر استبدال إذا كان مستنداً قديماً.');
                return;
            }
            revokeBlobUrlIfNeeded(fullPreviewUrl);
            setFullPreviewTitle(doc.fileName || doc.title);
            setFullPreviewUrl(payload.url);
            setFullPreviewKind(payload.kind);
            setFullPreviewSource(payload.blob ?? payload.url);
            setFullPreviewNonce((value) => value + 1);
            setFullPreviewOpen(true);
            clearPreviewMissing(itemId);
        } catch {
            markPreviewMissing(itemId);
            SmartToast.error('تعذر فتح هذا المستند حالياً');
        } finally {
            setPreviewLoading(false);
            setPreviewingEventId(null);
        }
    };

    const handleDeleteSavedDocument = async (item: TimelineEvent) => {
        const snapshot = extractVaultDocSnapshot(item);
        const meta = (item.metadata as Record<string, unknown> | undefined) ?? {};
        const attachmentDocId =
            typeof meta.attachmentDocId === 'string' ? meta.attachmentDocId : snapshot?.id;
        const authorId = snapshot?.authorId || resolveCalendarUserId();
        if (attachmentDocId && authorId) {
            await SmartVaultDB.deleteDoc(attachmentDocId, authorId).catch(() => undefined);
        }
        await Promise.resolve(onDeleteDocument?.(String(item.id)));
        if (previewingEventId === String(item.id)) setPreviewingEventId(null);
        clearPreviewMissing(String(item.id));
    };

    const handleSubmit = async () => {
        const trimmedTitle = title.trim();
        const trimmedCategory = category.trim();
        const trimmedNotes = notes.trim();
        if (!trimmedTitle || !trimmedCategory) return;
        if (!editMode && !selectedFile) {
            SmartToast.error('اختر ملف المستند أولاً');
            return;
        }

        setSaving(true);
        try {
            await Promise.resolve(
                onAdd({
                    title: trimmedTitle,
                    category: trimmedCategory,
                    details: trimmedNotes,
                    notes: trimmedNotes,
                    file: selectedFile,
                    fileName: selectedFile?.name,
                    fileType: selectedFile?.type,
                    date: getLocalTodayYmd(),
                    ...(editMode && editData ? { id: editData.id } : {}),
                }),
            );
            if (!editMode) {
                setTitle('');
                setCategory('');
                setNotes('');
                setSelectedFile(null);
            }
        } finally {
            setSaving(false);
        }
    };

    if (!isOpen) return null;

    return (
        <MoroccanGlassShell
            onOverlayClick={onClose}
            overlayTestId={CIVIL_LAWSUIT_TEST_IDS.documentModal}
            maxWidth="max-w-4xl"
            className="min-h-[min(84dvh,760px)]"
        >
            <FullDocumentPreviewOverlay
                key={fullPreviewNonce}
                isOpen={fullPreviewOpen}
                onClose={() => {
                    setFullPreviewOpen(false);
                    setFullPreviewSource(null);
                }}
                title={fullPreviewTitle}
                url={fullPreviewUrl}
                kind={fullPreviewKind}
                pdfSource={fullPreviewSource}
            />
            <SmartModalHeader T={T} icon={Paperclip} title={editMode ? 'تعديل مستند' : 'محفظة الأدلة الذكية'} onClose={onClose} />
            <div
                className={
                    T.useMoroccanCorners
                        ? 'grid gap-5 p-5 sm:p-6 md:min-h-[min(76dvh,640px)] md:grid-cols-[minmax(0,1.05fr)_minmax(0,0.95fr)] md:items-start'
                        : T.body
                }
            >
                <div className="space-y-4">
                    <ModalInlineTimeline
                        title="سجل المستندات داخل هذا القسم"
                        emptyLabel="لا توجد مستندات محفوظة في هذه المرحلة بعد"
                        items={recentDocuments}
                        renderMeta={(item) =>
                            [
                                item.docCategory ? `النوع: ${item.docCategory}` : null,
                                typeof (item.metadata as Record<string, unknown> | undefined)?.fileName === 'string'
                                    ? `الملف: ${String((item.metadata as Record<string, unknown>).fileName)}`
                                    : null,
                            ]
                                .filter(Boolean)
                                .join(' • ') || null
                        }
                        renderActions={(item) => (
                            <div className="flex flex-wrap items-center gap-1.5">
                                <button
                                    type="button"
                                    onClick={(event) => {
                                        event.preventDefault();
                                        event.stopPropagation();
                                        void handlePreviewSavedDocument(item);
                                    }}
                                    disabled={
                                        (previewLoading && previewingEventId === String(item.id)) ||
                                        isPreviewMissing(String(item.id))
                                    }
                                    className="inline-flex items-center gap-1 rounded-xl border border-[#E6C673]/18 bg-[#E6C673]/10 px-3 py-1.5 text-[10px] font-bold text-[#E6C673] transition-colors hover:bg-[#E6C673]/18 disabled:opacity-50"
                                >
                                    {previewLoading && previewingEventId === String(item.id) ? (
                                        <Loader2 size={12} className="animate-spin" />
                                    ) : isPreviewMissing(String(item.id)) ? (
                                        <FileText size={12} />
                                    ) : (
                                        <Eye size={12} />
                                    )}
                                    {isPreviewMissing(String(item.id)) ? 'مفقود' : 'اطلاع'}
                                </button>
                                <button
                                    type="button"
                                    onClick={() => onReplaceDocument?.(item)}
                                    className="inline-flex items-center gap-1 rounded-xl border border-white/[0.12] bg-white/[0.05] px-3 py-1.5 text-[10px] font-bold text-white/70 transition-colors hover:bg-white/[0.08]"
                                >
                                    <RefreshCw size={12} />
                                    استبدال
                                </button>
                                <button
                                    type="button"
                                    onClick={() => void handleDeleteSavedDocument(item)}
                                    className="inline-flex items-center gap-1 rounded-xl border border-rose-500/20 bg-rose-500/10 px-3 py-1.5 text-[10px] font-bold text-rose-200 transition-colors hover:bg-rose-500/16"
                                >
                                    <Trash2 size={12} />
                                    حذف
                                </button>
                            </div>
                        )}
                        renderBody={(item) => <DocumentTimelinePreview item={item} />}
                    />
                </div>
                <div className="space-y-5 md:self-center">
                    <input
                        id={fileInputId}
                        type="file"
                        ref={fileInputRef}
                        onChange={handleFileSelect}
                        accept="image/*,.pdf"
                        className="sr-only"
                        tabIndex={-1}
                        aria-hidden="true"
                    />
                    <div>
                        <label className={T.label}>
                            نوع المستند <span className="text-red-400">*</span>
                        </label>
                        <input
                            type="text"
                            value={category}
                            onChange={(e) => setCategory(e.target.value)}
                            placeholder="مثال: عريضة، وكالة، وصل..."
                            className={T.field}
                        />
                    </div>
                    <div>
                        <label className={T.label}>
                            اسم المستند <span className="text-red-400">*</span>
                        </label>
                        <input
                            type="text"
                            value={title}
                            onChange={(e) => setTitle(e.target.value)}
                            placeholder="مثال: قرار تمييز، عقد بيع..."
                            className={T.field}
                        />
                    </div>
                    <div className="rounded-[24px] border border-white/[0.08] bg-[linear-gradient(180deg,rgba(255,255,255,0.04),rgba(255,255,255,0.02))] p-4 space-y-3">
                        <div className="flex items-center justify-between gap-2">
                            <p className="text-[12px] font-black text-[#E6C673]/85">معاينة المستند</p>
                            <label
                                htmlFor={fileInputId}
                                className="cursor-pointer rounded-xl border border-[#E6C673]/18 bg-[#E6C673]/10 px-3 py-2 text-[11px] font-bold text-[#E6C673] transition-colors hover:bg-[#E6C673]/18"
                            >
                                {selectedFile ? 'تغيير الملف' : 'اختيار ملف'}
                            </label>
                        </div>
                        {selectedFile ? (
                            <div className="space-y-3">
                                {selectedFileKind === 'image' && selectedPreviewUrl ? (
                                    <div className="flex h-44 sm:h-52 items-center justify-center overflow-hidden rounded-[22px] border border-white/[0.08] bg-black/20 p-3">
                                        <img
                                            src={selectedPreviewUrl}
                                            alt={selectedFile.name}
                                            className="block max-h-full max-w-full object-contain"
                                        />
                                    </div>
                                ) : null}
                                {selectedFileKind === 'pdf' && selectedPreviewUrl ? (
                                    <div className="overflow-hidden rounded-[22px] border border-white/[0.08] bg-[#161616]">
                                        <div className="h-56 sm:h-64 w-full">
                                        <VaultPdfViewerSurfaceLazy
                                                source={selectedFile}
                                                title={selectedFile.name}
                                                openUrl={selectedPreviewUrl}
                                                fallbackClassName="flex h-full items-center justify-center text-sm text-white/45"
                                        />
                                        </div>
                                    </div>
                                ) : null}
                                {selectedFileKind === 'file' ? (
                                    <div className="flex h-40 items-center justify-center rounded-[22px] border border-dashed border-white/[0.08] bg-black/10 px-4 text-center">
                                        <div className="space-y-2">
                                            <FileText size={28} className="mx-auto text-[#E6C673]" />
                                            <p className="text-sm font-bold text-[#F4E9CD] truncate max-w-[18rem]">
                                                {selectedFile.name}
                                            </p>
                                            <p className="text-[11px] text-white/40">
                                                لا تتوفر معاينة مضمنة لهذا النوع، لكن الملف جاهز للحفظ.
                                            </p>
                                        </div>
                                    </div>
                                ) : null}
                                <div className="flex flex-wrap items-center gap-2 text-[11px] text-white/45">
                                    <span className="rounded-full border border-white/[0.08] bg-white/[0.04] px-2 py-1">
                                        {selectedFile.name}
                                    </span>
                                    <span className="rounded-full border border-white/[0.08] bg-white/[0.04] px-2 py-1">
                                        {(selectedFile.size / 1024 / 1024).toFixed(2)} MB
                                    </span>
                                    <span className="rounded-full border border-white/[0.08] bg-white/[0.04] px-2 py-1">
                                        {selectedFile.type || 'ملف عام'}
                                    </span>
                                </div>
                            </div>
                        ) : (
                            <label
                                htmlFor={fileInputId}
                                onDrop={handleDropSelectedFile}
                                onDragEnter={(e) => handleDragState(e, true)}
                                onDragOver={(e) => handleDragState(e, true)}
                                onDragLeave={(e) => handleDragState(e, false)}
                                className={`w-full h-36 cursor-pointer rounded-[22px] border-2 border-dashed flex flex-col items-center justify-center gap-2 transition-all backdrop-blur-sm ${
                                    isPearl
                                        ? 'border-[#C9B89A]/15 bg-[#EDE6D6]/[0.02] text-[#9C9890] hover:border-[#C9B89A]/28 hover:text-[#C9B89A]/90 hover:bg-[#C9B89A]/5'
                                        : 'border-white/10 bg-white/[0.02] text-white/40 hover:border-[#E6C673]/30 hover:text-[#E6C673]/80 hover:bg-[#E6C673]/5'
                                } ${isFileDragActive ? 'border-[#E6C673]/45 bg-[#E6C673]/8 text-[#E6C673]' : ''}`}
                            >
                                <UploadCloud size={22} />
                                <span className="text-sm font-bold">اسحب أو اختر ملفاً من الجهاز</span>
                                <span className="text-[11px] text-white/42">PDF أو صورة عالية الدقة</span>
                            </label>
                        )}
                    </div>
                    <div className="rounded-[22px] border border-white/[0.08] bg-white/[0.03] p-4 space-y-3">
                        <div className="flex items-center justify-between gap-2">
                            <p className="text-[12px] font-black text-[#E6C673]/85">ملخص المستند</p>
                            <span className="text-[10px] text-white/35">
                                {selectedFile ? 'جاهز للحفظ' : 'ينتظر الملف'}
                            </span>
                        </div>
                        <textarea
                            value={notes}
                            onChange={(e) => setNotes(e.target.value)}
                            placeholder="وصف مختصر أو ملاحظات قانونية للمستند..."
                            className={`${T.field} min-h-[130px] resize-none`}
                        />
                    </div>
                    <button
                        type="button"
                        onClick={handleSubmit}
                        disabled={saving || !title.trim() || !category.trim() || (!editMode && !selectedFile)}
                        className={T.btn}
                    >
                        {saving ? 'جارٍ حفظ المستند...' : editMode ? 'تحديث المستند' : 'حفظ المستند'}
                    </button>
                </div>
            </div>
        </MoroccanGlassShell>
    );
};

import React, { useState } from 'react';
import {
    Calendar,
    CheckSquare,
    DollarSign,
    FileText,
    Pencil,
    Trash2,
    X,
} from 'lucide-react';
import { getLocalTodayYmd } from '@/app/utils/executionStateMachine';
import { SmartToast } from '@/app/components/ui/SmartToast';
import { resolveCalendarUserId } from '@/app/services/calendar/bridge';
import { DossierFastNoteComposer } from '@/app/components/lawyer/dossier-notes/DossierFastNoteComposer';
import { DossierNotesVault, type DossierVaultNote } from '@/app/components/lawyer/dossier-notes/DossierNotesVault';
import type {
    AddAppointmentModalProps,
    AddNoteModalProps,
    AddPaymentModalProps,
    AddTaskModalProps,
} from '../../smartFile/modalFormTypes';
import {
    MoroccanGlassShell,
} from '../../smartFile/moroccanGlassShell';
import { useSmartFileModalTheme } from '../../smartFile/smartFileModalTheme';
import { SMART_FILE_NESTED_MODAL_OVERLAY_DARK_CLASS } from '../../smartFile/smartFileOverlayZ';
import { CIVIL_LAWSUIT_TEST_IDS } from '../../smartFile/civilLawsuitTestIds';
import { ManualClassificationPicker } from '../../smartFile/ManualClassificationPicker';
