export type { QuantumTasksContextValue } from '@/app/context/quantumTasksContext';
export { QuantumTasksContext } from '@/app/context/quantumTasksContext';

const AGENDA_ROLLOVER_CHECK_MS = 60_000;
const ASYNC_PERSIST_DEBOUNCE_MS = 500;

/** Provider فقط — الـ hook في `useQuantumTasksContext.ts` لتوافق Fast Refresh */
export function QuantumTasksProvider({ children }: { children: React.ReactNode }) {
    /** إقلاع فارغ — القرص يُقرأ async أدناه (لا SecureStore sync على أول رسم للوحة). */
    const bootTasksRef = useRef<LegalTask[]>([]);
    const [storageHydrated, setStorageHydrated] = useState(false);
    const agendaDayRef = useRef(new Date().toDateString());
    const tasksRef = useRef<LegalTask[]>([]);
    const asyncPersistTimerRef = useRef<number | null>(null);
    const pendingAsyncPersistRef = useRef<LegalTask[] | null>(null);
    const hiddenFlushTimerRef = useRef<number | null>(null);

    const notifyTasksChanged = useCallback(() => {
        try {
            if (typeof window !== 'undefined') {
                window.dispatchEvent(new CustomEvent(QUANTUM_TASKS_CHANGED_EVENT));
            }
        } catch {
            /* ignore */
        }
    }, []);

    const flushAsyncPersist = useCallback(() => {
        if (asyncPersistTimerRef.current !== null) {
            window.clearTimeout(asyncPersistTimerRef.current);
            asyncPersistTimerRef.current = null;
        }
        const pending = pendingAsyncPersistRef.current;
        if (!pending) return;
        pendingAsyncPersistRef.current = null;
        void persistQuantumTasksBackground(pending).then(() => {
            notifyTasksChanged();
        });
    }, [notifyTasksChanged]);

    const scheduleAsyncPersist = useCallback(
        (nextTasks: LegalTask[]) => {
            pendingAsyncPersistRef.current = nextTasks;
            if (asyncPersistTimerRef.current !== null) {
                window.clearTimeout(asyncPersistTimerRef.current);
            }
            asyncPersistTimerRef.current = window.setTimeout(() => {
                asyncPersistTimerRef.current = null;
                flushAsyncPersist();
            }, ASYNC_PERSIST_DEBOUNCE_MS);
        },
        [flushAsyncPersist],
    );

    const commitTasksToStorage = useCallback(
        (nextTasks: LegalTask[]) => {
            tasksRef.current = nextTasks;
            persistQuantumTasksSync(nextTasks);
            scheduleAsyncPersist(nextTasks);
        },
        [scheduleAsyncPersist],
    );

    const value = useQuantumTasks(bootTasksRef.current, { onTasksCommitted: commitTasksToStorage });
    tasksRef.current = value.tasks;

    const flushPersist = useCallback(async () => {
        persistQuantumTasksSync(tasksRef.current);
        flushAsyncPersist();
    }, [flushAsyncPersist]);

    const dataValue = useMemo(
        () => ({
            tasks: value.tasks,
            pendingTasks: value.pendingTasks,
            storageHydrated,
        }),
        [value.tasks, value.pendingTasks, storageHydrated],
    );

    const actionsValue = useMemo(
        () => ({
            addTask: value.addTask,
            addTaskFromVoice: value.addTaskFromVoice,
            addWeeklyLocationBundle: value.addWeeklyLocationBundle,
            addSnoozedBacklogTask: value.addSnoozedBacklogTask,
            updateTask: value.updateTask,
            deleteTask: value.deleteTask,
            completeTask: value.completeTask,
            reopenTask: value.reopenTask,
            toggleTaskFatalDeadline: value.toggleTaskFatalDeadline,
            toggleTaskPinnedToFieldCurtain: value.toggleTaskPinnedToFieldCurtain,
            setTaskLocation: value.setTaskLocation,
            addSubTask: value.addSubTask,
            toggleSubTaskComplete: value.toggleSubTaskComplete,
            setSubTaskLocation: value.setSubTaskLocation,
            addDocumentRequirement: value.addDocumentRequirement,
            toggleDocumentRequirement: value.toggleDocumentRequirement,
            addExpense: value.addExpense,
            requestTaskHelp: value.requestTaskHelp,
            acceptTaskHelp: value.acceptTaskHelp,
            addSharedTaskNote: value.addSharedTaskNote,
            markHelpCompleted: value.markHelpCompleted,
            confirmHelpReview: value.confirmHelpReview,
            delegatedTasks: value.delegatedTasks,
            setTasks: value.setTasks,
            flushPersist,
        }),
        [
            value.addTask,
            value.addTaskFromVoice,
            value.addWeeklyLocationBundle,
            value.addSnoozedBacklogTask,
            value.updateTask,
            value.deleteTask,
            value.completeTask,
            value.reopenTask,
            value.toggleTaskFatalDeadline,
            value.toggleTaskPinnedToFieldCurtain,
            value.setTaskLocation,
            value.addSubTask,
            value.toggleSubTaskComplete,
            value.setSubTaskLocation,
            value.addDocumentRequirement,
            value.toggleDocumentRequirement,
            value.addExpense,
            value.requestTaskHelp,
            value.acceptTaskHelp,
            value.addSharedTaskNote,
            value.markHelpCompleted,
            value.confirmHelpReview,
            value.delegatedTasks,
            value.setTasks,
            flushPersist,
        ],
    );

    useEffect(() => {
        let cancelled = false;
        const startHydrate = () => {
            void (async () => {
                const { default: SecureStoreService } = await import('@/app/services/SecureStoreService');
                await SecureStoreService.ensurePersistedReady();
                let blob = await persistenceRepository.loadAsync<unknown>(QUANTUM_TASKS_STORAGE_KEY);
                if (!blob) {
                    const { readLatestDossierBackup } = await import(
                        '@/app/services/dossierPersistence/dossierBackupStore'
                    );
                    const backup = await readLatestDossierBackup('tasks');
                    if (backup?.payload.length) {
                        blob = { tasks: backup.payload };
                    }
                }
                if (cancelled) return;

                const loaded = prepareAgendaTasks(deserializeQuantumTasks(blob), new Date(), {
                    skipRetentionPurge: true,
                });

                value.setTasks((prev) => {
                    const merged = mergeHydratedQuantumTasks(prev, loaded);
                    tasksRef.current = merged;
                    return merged;
                });
                setStorageHydrated(true);
            })();
        };
        /** بعد content-ready — لا تنافس I/O القرص مع HomeTab قبل كشف الشعار */
        const unbind = onBootContentReady(startHydrate);
        return () => {
            cancelled = true;
            unbind();
        };
    }, [value.setTasks]);

    useEffect(() => {
        if (!storageHydrated) return;

        const applyAgendaRollover = () => {
            const now = new Date();
            const dayKey = now.toDateString();
            if (dayKey === agendaDayRef.current) return;
            agendaDayRef.current = dayKey;
            value.setTasks((prev) => {
                const next = prepareAgendaTasks(prev, now);
                return agendaTasksLifecycleRevision(prev) === agendaTasksLifecycleRevision(next)
                    ? prev
                    : next;
            });
        };

        applyAgendaRollover();
        const id = window.setInterval(applyAgendaRollover, AGENDA_ROLLOVER_CHECK_MS);
        return () => window.clearInterval(id);
    }, [storageHydrated, value.setTasks]);

    useEffect(() => {
        publishQuantumTasksMetrics(value.tasks, value.pendingTasks);
    }, [value.tasks, value.pendingTasks]);

    useEffect(() => {
        const onPageHide = () => {
            if (hiddenFlushTimerRef.current !== null) {
                window.clearTimeout(hiddenFlushTimerRef.current);
                hiddenFlushTimerRef.current = null;
            }
            persistQuantumTasksSync(tasksRef.current);
            flushAsyncPersist();
        };
        const onHide = () => {
            if (document.visibilityState !== 'hidden') {
                if (hiddenFlushTimerRef.current !== null) {
                    window.clearTimeout(hiddenFlushTimerRef.current);
                    hiddenFlushTimerRef.current = null;
                }
                return;
            }
            if (hiddenFlushTimerRef.current !== null) {
                window.clearTimeout(hiddenFlushTimerRef.current);
            }
            hiddenFlushTimerRef.current = window.setTimeout(() => {
                hiddenFlushTimerRef.current = null;
                if (document.visibilityState === 'hidden') onPageHide();
            }, 900);
        };
        window.addEventListener('pagehide', onPageHide);
        document.addEventListener('visibilitychange', onHide);
        return () => {
            window.removeEventListener('pagehide', onPageHide);
            document.removeEventListener('visibilitychange', onHide);
            if (hiddenFlushTimerRef.current !== null) {
                window.clearTimeout(hiddenFlushTimerRef.current);
                hiddenFlushTimerRef.current = null;
            }
            if (asyncPersistTimerRef.current !== null) {
                window.clearTimeout(asyncPersistTimerRef.current);
            }
        };
    }, [flushAsyncPersist]);

    return (
        <QuantumTasksActionsContext.Provider value={actionsValue}>
            <QuantumTasksDataContext.Provider value={dataValue}>
                <QuantumTasksContext.Provider value={value}>{children}</QuantumTasksContext.Provider>
            </QuantumTasksDataContext.Provider>
        </QuantumTasksActionsContext.Provider>
    );
}

import React, { useCallback, useContext, useEffect, useMemo, useRef, useState } from 'react';
import { persistenceRepository } from '@/app/infrastructure/persistence/LocalStorageRepository';
import SecureStoreService from '@/app/services/SecureStoreService';
import { useAutoSave } from '@/app/hooks/useAutoSave';
import type { ShapeKey, ThemeKey } from '@/app/types/common';
import { onBootContentReady } from '@/app/bootstrap/bootReveal';
import {
    applySettingsToDom,
    hydrateWallpaperFromSecureStore,
    loadPersistedWallpaper,
    persistWallpaper,
    shouldAllowPush,
} from '@/app/services/settings/apply';
import {
    invalidateLawyerSettingsCache,
    publishLawyerSettingsLive,
} from '@/app/services/settings/settingsSnapshot';
import { LAWYER_SETTINGS_V2_DEFAULTS } from '@/app/services/settings/defaults';
import type { AppSettingsState } from '@/app/services/settings/types';
import { PERSIST_DEBOUNCE_MS } from '@/app/utils/constants';
import { LAWYER_THEME_TOKENS } from '@/app/services/settings/lawyerThemeTokens';
import { clearStoredBiometricCredential } from '@/app/services/security/webAuthnLock';
import { isCapacitorNativePlatform } from '@/app/runtime/nativePlatform';
import {
    LawyerSettingsActionsContext,
    LawyerSettingsAppearanceContext,
    LawyerSettingsContext,
    LawyerSettingsDataContext,
    LawyerSettingsHomeLayoutContext,
    LawyerSettingsPerformanceContext,
    LawyerSettingsSecurityContext,
} from './lawyerSettingsContexts';
import type { LawyerSettingsActionsValue, LawyerSettingsContextValue } from './lawyerSettingsTypes';
import {
    homeLayoutStableKey,
    loadInitialSettingsAsync,
    readProviderBootSettings,
    settingsHydrateEqual,
    stripWallpaperForStorage,
} from './lawyerSettingsPersistence';

export function LawyerSettingsProvider({ children }: { children: React.ReactNode }) {
    const [settingsHydrated, setSettingsHydrated] = useState(false);
    const [settings, setSettings] = useState<AppSettingsState>(readProviderBootSettings);
    const [currentTheme, setCurrentThemeState] = useState<ThemeKey>(settings.appearance.theme);
    const [currentShape, setCurrentShapeState] = useState<ShapeKey>(settings.appearance.shape);
    const settingsRef = useRef(settings);
    settingsRef.current = settings;
    const settingsHydratedRef = useRef(false);

    useEffect(() => {
        let cancelled = false;
        const applyLoaded = (loaded: AppSettingsState, mode: 'initial' | 'reconcile') => {
            if (cancelled) return;
            if (mode === 'reconcile' && settingsHydratedRef.current) {
                return;
            }
            setSettings((prev) => (settingsHydrateEqual(prev, loaded) ? prev : loaded));
            setCurrentThemeState((prev) =>
                prev === loaded.appearance.theme ? prev : loaded.appearance.theme,
            );
            setCurrentShapeState((prev) =>
                prev === loaded.appearance.shape ? prev : loaded.appearance.shape,
            );
            applySettingsToDom(loaded);
            publishLawyerSettingsLive(loaded);
            settingsHydratedRef.current = true;
            setSettingsHydrated(true);
        };

        const startHydrate = () => {
            if (cancelled) return;
            void loadInitialSettingsAsync().then((loaded) => applyLoaded(loaded, 'initial'));

            void SecureStoreService.ensureBootShellReady().then(() => {
                if (cancelled) return;
                void loadInitialSettingsAsync().then((loaded) => applyLoaded(loaded, 'reconcile'));
            });
            void SecureStoreService.ensurePersistedReady();
        };

        const unbind = onBootContentReady(startHydrate);
        return () => {
            cancelled = true;
            unbind();
        };
    }, []);

    const autoSaveOn = settings.data.autoSave;
    const settingsForPersistence = useMemo(() => stripWallpaperForStorage(settings), [settings]);

    useAutoSave(
        'lawyer_settings',
        settingsForPersistence,
        PERSIST_DEBOUNCE_MS.LIGHT,
        autoSaveOn,
        settingsHydrated,
    );
    useAutoSave('lawyer_theme', currentTheme, PERSIST_DEBOUNCE_MS.LIGHT, autoSaveOn, settingsHydrated);
    useAutoSave('lawyer_shape', currentShape, PERSIST_DEBOUNCE_MS.LIGHT, autoSaveOn, settingsHydrated);

    useEffect(() => {
        if (!settingsHydrated) return;
        void hydrateWallpaperFromSecureStore().then((src) => {
            if (!src) return;
            setSettings((prev) => {
                if (prev.appearance.wallpaperStamp && loadPersistedWallpaper()) return prev;
                return {
                    ...prev,
                    appearance: {
                        ...prev.appearance,
                        wallpaper: undefined,
                        wallpaperStamp: Date.now(),
                    },
                };
            });
        });
    }, [settingsHydrated]);

    useEffect(() => {
        if (!settingsHydrated) return;
        const timer = window.setTimeout(() => {
            window.dispatchEvent(new CustomEvent('hami:settings-updated', { detail: settings }));
        }, 120);
        return () => window.clearTimeout(timer);
    }, [settings, settingsHydrated]);

    useEffect(() => {
        if (!settingsHydrated) return;
        if (!settings.performance.prefetchScreens) {
            void import('@/app/runtime/prefetchScheduler').then(({ PrefetchScheduler }) => {
                PrefetchScheduler.reset();
            });
        }
    }, [settings.performance.prefetchScreens, settingsHydrated]);

    const domSettingsSignature = useMemo(
        () =>
            JSON.stringify({
                theme: settings.appearance.theme,
                shape: settings.appearance.shape,
                brandColor: settings.appearance.brandColor,
                glassOpacity: settings.appearance.glassOpacity,
                reduceMotion: settings.appearance.reduceMotion,
                wallpaper: loadPersistedWallpaper() ? '1' : '0',
                wallpaperStamp: settings.appearance.wallpaperStamp ?? 0,
                backgroundPreset: settings.appearance.backgroundPreset,
                backgroundPatternOpacity: settings.appearance.backgroundPatternOpacity,
                backgroundPatternBlur: settings.appearance.backgroundPatternBlur,
                homeContainerBorder: settings.appearance.homeContainerBorder,
                fontSize: settings.appearance.fontSize,
                language: settings.appearance.language,
                highContrast: settings.appearance.highContrast,
                themeMode: settings.appearance.themeMode,
                enableAnimations: settings.performance.enableAnimations,
                localOnlyMode: settings.security.localOnlyMode,
            }),
        [settings.appearance, settings.performance.enableAnimations, settings.security.localOnlyMode],
    );

    useEffect(() => {
        if (!settingsHydrated) return;
        invalidateLawyerSettingsCache();
        applySettingsToDom(settingsRef.current);
    }, [domSettingsSignature, settingsHydrated]);

    const setCurrentTheme = useCallback((theme: ThemeKey) => {
        setCurrentThemeState(theme);
        const token = LAWYER_THEME_TOKENS[theme] ?? LAWYER_THEME_TOKENS.gold;
        setSettings((prev) => ({
            ...prev,
            appearance: { ...prev.appearance, theme, brandColor: token.primary },
        }));
    }, []);

    const setCurrentShape = useCallback((shape: ShapeKey) => {
        setCurrentShapeState(shape);
        setSettings((prev) => ({ ...prev, appearance: { ...prev.appearance, shape } }));
    }, []);

    useEffect(() => {
        if (settings.appearance.theme !== currentTheme) {
            setCurrentThemeState(settings.appearance.theme);
        }
    }, [settings.appearance.theme, currentTheme]);

    useEffect(() => {
        if (settings.appearance.shape !== currentShape) {
            setCurrentShapeState(settings.appearance.shape);
        }
    }, [settings.appearance.shape, currentShape]);

    useEffect(() => {
        if (isCapacitorNativePlatform()) {
            document.body.style.filter = 'none';
            return undefined;
        }
        const onVis = () => {
            if (!document.hidden || !settings.security.privacyBlur) {
                document.body.style.filter = 'none';
                return;
            }
            document.body.style.filter = 'blur(14px)';
        };
        document.addEventListener('visibilitychange', onVis);
        return () => {
            document.removeEventListener('visibilitychange', onVis);
            document.body.style.filter = 'none';
        };
    }, [settings.security.privacyBlur]);

    useEffect(() => {
        if (!settings.security.screenshotDeterrent) return undefined;
        let unbind: (() => void) | undefined;
        let cancelled = false;
        void import('@/app/runtime/screenshotDeterrentRuntime')
            .then((m) => {
                if (cancelled) return;
                unbind = m.bindWebScreenshotDeterrent();
            })
            .catch(() => undefined);
        return () => {
            cancelled = true;
            unbind?.();
        };
    }, [settings.security.screenshotDeterrent]);

    useEffect(() => {
        let unwire: (() => void) | undefined;
        let cancelled = false;
        void import('@/app/runtime/nativeSecurityBoot')
            .then((m) => {
                if (cancelled) return;
                void m.applyNativeSecurityFromSettings();
                unwire = m.wireNativeSecuritySettingsListener();
            })
            .catch(() => undefined);
        return () => {
            cancelled = true;
            unwire?.();
        };
    }, []);

    const patchSettings = useCallback(
        (patch: Partial<AppSettingsState> | ((prev: AppSettingsState) => AppSettingsState)) => {
            setSettings((prev) => (typeof patch === 'function' ? patch(prev) : { ...prev, ...patch }));
        },
        [],
    );

    const resetToDefaults = useCallback(() => {
        const migrated = LAWYER_SETTINGS_V2_DEFAULTS;
        clearStoredBiometricCredential();
        void import('@/app/runtime/nativeBiometricBridge')
            .then((m) => m.clearNativeBiometricEnrollment())
            .catch(() => undefined);
        persistWallpaper(undefined);
        const stripped = stripWallpaperForStorage(migrated);
        setSettings(migrated);
        setCurrentThemeState(migrated.appearance.theme);
        setCurrentShapeState(migrated.appearance.shape);
        persistenceRepository.save('lawyer_settings', stripped);
        persistenceRepository.save('lawyer_theme', migrated.appearance.theme);
        persistenceRepository.save('lawyer_shape', migrated.appearance.shape);
        invalidateLawyerSettingsCache();
        publishLawyerSettingsLive(migrated);
        applySettingsToDom(migrated);
    }, []);

    const actionsValue = useMemo<LawyerSettingsActionsValue>(
        () => ({
            setSettings,
            patchSettings,
            setCurrentTheme,
            setCurrentShape,
            resetToDefaults,
        }),
        [patchSettings, setCurrentTheme, setCurrentShape, resetToDefaults],
    );

    const value = useMemo<LawyerSettingsContextValue>(
        () => ({
            settings,
            setSettings,
            patchSettings,
            currentTheme,
            currentShape,
            setCurrentTheme,
            setCurrentShape,
            pushAllowed: shouldAllowPush(settings),
            resetToDefaults,
        }),
        [settings, patchSettings, currentTheme, currentShape, setCurrentTheme, setCurrentShape, resetToDefaults],
    );

    const appearanceStable = useMemo(
        () => settings.appearance,
        [
            settings.appearance.themeMode,
            settings.appearance.theme,
            settings.appearance.shape,
            settings.appearance.language,
            settings.appearance.fontSize,
            settings.appearance.fontPreset,
            settings.appearance.glassOpacity,
            settings.appearance.homeContainerBorder,
            settings.appearance.wallpaperStamp,
            settings.appearance.backgroundPreset,
            settings.appearance.backgroundPatternOpacity,
            settings.appearance.backgroundPatternBlur,
            settings.appearance.brandColor,
            settings.appearance.reduceMotion,
            settings.appearance.highContrast,
        ],
    );

    const securityStable = useMemo(
        () => settings.security,
        [
            settings.security.privacyBlur,
            settings.security.screenshotDeterrent,
            settings.security.biometricLock,
            settings.security.autoLockMinutes,
            settings.security.localOnlyMode,
        ],
    );

    const dataStable = useMemo(
        () => settings.data,
        [
            settings.data.autoSave,
            settings.data.cloudSync,
            settings.data.syncNotes,
            settings.data.syncFiles,
            settings.data.syncExecution,
        ],
    );

    const performanceStable = useMemo(
        () => settings.performance,
        [
            settings.performance.enableAnimations,
            settings.performance.prefetchScreens,
            settings.performance.litePerformance,
        ],
    );

    const homeLayoutStable = useMemo(
        () => settings.homeLayout,
        [homeLayoutStableKey(settings.homeLayout)],
    );

    return (
        <LawyerSettingsActionsContext.Provider value={actionsValue}>
            <LawyerSettingsPerformanceContext.Provider value={performanceStable}>
                <LawyerSettingsHomeLayoutContext.Provider value={homeLayoutStable}>
                    <LawyerSettingsDataContext.Provider value={dataStable}>
                        <LawyerSettingsSecurityContext.Provider value={securityStable}>
                            <LawyerSettingsAppearanceContext.Provider value={appearanceStable}>
                                <LawyerSettingsContext.Provider value={value}>{children}</LawyerSettingsContext.Provider>
                            </LawyerSettingsAppearanceContext.Provider>
                        </LawyerSettingsSecurityContext.Provider>
                    </LawyerSettingsDataContext.Provider>
                </LawyerSettingsHomeLayoutContext.Provider>
            </LawyerSettingsPerformanceContext.Provider>
        </LawyerSettingsActionsContext.Provider>
    );
}

export function EnsureLawyerSettingsProvider({ children }: { children: React.ReactNode }) {
    const ctx = useContext(LawyerSettingsContext);
    if (ctx) return <>{children}</>;
    return <LawyerSettingsProvider>{children}</LawyerSettingsProvider>;
}

import { useContext, useMemo, type Context, type Dispatch, type SetStateAction } from 'react';
import {
    applySettingsToDom,
    shouldAllowPush,
    shouldAllowPushFromSecurity,
} from '@/app/services/settings/apply';
import {
    getLawyerSettingsSnapshot,
    invalidateLawyerSettingsCache,
} from '@/app/services/settings/settingsSnapshot';
import { LAWYER_SETTINGS_V2_DEFAULTS } from '@/app/services/settings/defaults';
import { SETTINGS_SCHEMA_VERSION } from '@/app/services/settings/types';
import type {
    AppSettingsState,
    AppearanceSettings,
    DataSettings,
    HomeLayoutSettings,
    PerformanceSettings,
    SecuritySettings,
} from '@/app/services/settings/types';
import {
    LawyerSettingsActionsContext,
    LawyerSettingsAppearanceContext,
    LawyerSettingsContext,
    LawyerSettingsDataContext,
    LawyerSettingsHomeLayoutContext,
    LawyerSettingsPerformanceContext,
    LawyerSettingsSecurityContext,
} from './lawyerSettingsContexts';
import type { LawyerSettingsActionsValue, LawyerSettingsContextValue } from './lawyerSettingsTypes';

const noop = () => undefined;

function isDevSettingsFallbackAllowed(): boolean {
    return import.meta.env.DEV && typeof window !== 'undefined';
}

function useSettingsSliceContext<T>(
    context: Context<T | null>,
    hookName: string,
    readSnapshot: () => T,
): T {
    const ctx = useContext(context);
    if (ctx) return ctx;
    if (isDevSettingsFallbackAllowed()) {
        return readSnapshot();
    }
    throw new Error(`${hookName} must be used within LawyerSettingsProvider`);
}

let missingProviderWarned = false;

function buildLawyerSettingsDevFallbackValue(): LawyerSettingsContextValue {
    const snapshot = getLawyerSettingsSnapshot();
    return {
        settings: snapshot,
        setSettings: noop as Dispatch<SetStateAction<AppSettingsState>>,
        patchSettings: noop,
        currentTheme: snapshot.appearance.theme,
        currentShape: snapshot.appearance.shape,
        setCurrentTheme: noop,
        setCurrentShape: noop,
        pushAllowed: shouldAllowPush(snapshot),
        resetToDefaults: () => {
            invalidateLawyerSettingsCache();
            applySettingsToDom(LAWYER_SETTINGS_V2_DEFAULTS);
        },
    };
}

export function useLawyerSettings() {
    const ctx = useContext(LawyerSettingsContext);
    if (ctx) return ctx;
    if (isDevSettingsFallbackAllowed()) {
        if (!missingProviderWarned) {
            missingProviderWarned = true;
            console.warn(
                '[hami] useLawyerSettings outside LawyerSettingsProvider — dev snapshot fallback (HMR only)',
            );
        }
        return buildLawyerSettingsDevFallbackValue();
    }
    throw new Error('useLawyerSettings must be used within LawyerSettingsProvider');
}

export function useLawyerSettingsOptional() {
    return useContext(LawyerSettingsContext);
}

export function useLawyerSettingsAppearance(): AppearanceSettings {
    return useSettingsSliceContext(
        LawyerSettingsAppearanceContext,
        'useLawyerSettingsAppearance',
        () => getLawyerSettingsSnapshot().appearance,
    );
}

export function useLawyerSettingsSecurity(): SecuritySettings {
    return useSettingsSliceContext(
        LawyerSettingsSecurityContext,
        'useLawyerSettingsSecurity',
        () => getLawyerSettingsSnapshot().security,
    );
}

export function useLawyerSettingsPushAllowed(): boolean {
    const security = useLawyerSettingsSecurity();
    return useMemo(() => shouldAllowPushFromSecurity(security), [security.localOnlyMode]);
}

export function useLawyerSettingsFromSlices(): AppSettingsState {
    const appearance = useLawyerSettingsAppearance();
    const security = useLawyerSettingsSecurity();
    const data = useLawyerSettingsData();
    const performance = useLawyerSettingsPerformance();
    const homeLayout = useLawyerSettingsHomeLayout();
    return useMemo(
        (): AppSettingsState => ({
            version: SETTINGS_SCHEMA_VERSION,
            appearance,
            security,
            data,
            performance,
            homeLayout,
        }),
        [appearance, security, data, performance, homeLayout],
    );
}

export function useLawyerSettingsData(): DataSettings {
    return useSettingsSliceContext(
        LawyerSettingsDataContext,
        'useLawyerSettingsData',
        () => getLawyerSettingsSnapshot().data,
    );
}

export function useLawyerSettingsPerformance(): PerformanceSettings {
    return useSettingsSliceContext(
        LawyerSettingsPerformanceContext,
        'useLawyerSettingsPerformance',
        () => getLawyerSettingsSnapshot().performance,
    );
}

export function useLawyerSettingsHomeLayout(): HomeLayoutSettings {
    return useSettingsSliceContext(
        LawyerSettingsHomeLayoutContext,
        'useLawyerSettingsHomeLayout',
        () => getLawyerSettingsSnapshot().homeLayout,
    );
}

export function useLawyerSettingsActions(): LawyerSettingsActionsValue {
    const ctx = useContext(LawyerSettingsActionsContext);
    if (ctx) return ctx;
    if (isDevSettingsFallbackAllowed()) {
        return {
            setSettings: noop as Dispatch<SetStateAction<AppSettingsState>>,
            patchSettings: noop,
            setCurrentTheme: noop,
            setCurrentShape: noop,
            resetToDefaults: () => {
                invalidateLawyerSettingsCache();
                applySettingsToDom(LAWYER_SETTINGS_V2_DEFAULTS);
            },
        };
    }
    throw new Error('useLawyerSettingsActions must be used within LawyerSettingsProvider');
}

export function useLawyerSettingsReset(): () => void {
    return useLawyerSettingsActions().resetToDefaults;
}

import SecureStoreService from '@/app/services/SecureStoreService';

export interface Note {
    id: string;
    content: string;
    type: 'text' | 'voice';
    createdAt: number;
    tags?: string[];
    linkedCaseId?: string; // Optional linkage to a case
}

class NotesVaultService {
    private storageKey = 'hami_notes_vault';
    private notes: Note[] = [];
    private scopedUserId: string | null = null;

    constructor() {
        this.load();
    }

    /** عزل الملاحظات حسب المستخدم المسجّل */
    setUserScope(userId: string | null): void {
        const nextKey = userId ? `hami_notes_vault_${userId}` : 'hami_notes_vault';
        if (nextKey === this.storageKey && userId === this.scopedUserId) return;
        this.scopedUserId = userId;
        this.storageKey = nextKey;
        this.load();
        if (userId) this.migrateLegacyIfEmpty();
    }

    /** نقل ملاحظات المفتاح القديم غير المقيّد إلى حساب المستخدم الحالي */
    migrateLegacyIfEmpty(): void {
        if (this.notes.length > 0) return;
        try {
            const legacy = SecureStoreService.getItemSync('hami_notes_vault');
            if (!legacy) return;
            const parsed: unknown = JSON.parse(legacy);
            if (!Array.isArray(parsed) || parsed.length === 0) return;
            this.notes = parsed.map((n: Record<string, unknown>) => ({
                id: String(n.id ?? Date.now()),
                content: typeof n.content === 'string' ? n.content : String(n.content ?? ''),
                type: n.type === 'voice' ? 'voice' as const : 'text' as const,
                createdAt: typeof n.createdAt === 'number' ? n.createdAt : Date.now(),
                tags: Array.isArray(n.tags) ? (n.tags as string[]) : undefined,
                linkedCaseId: typeof n.linkedCaseId === 'string' ? n.linkedCaseId : undefined,
            }));
            this.save();
        } catch {
            // ignore corrupt legacy bucket
        }
    }

    replaceAll(notes: Note[]): void {
        this.notes = notes;
        this.save();
    }

    private load() {
        try {
            const stored = SecureStoreService.getItemSync(this.storageKey);
            if (stored) {
                const parsed: unknown = JSON.parse(stored);
                if (!Array.isArray(parsed)) {
                    this.notes = [];
                    return;
                }
                // Sanitize: ensure content is always a string to recover from bad data
                this.notes = parsed.map((n: any) => ({
                    ...n,
                    content: typeof n.content === 'object' && n.content !== null && 'content' in n.content 
                        ? n.content.content // Recover nested content if possible
                        : typeof n.content === 'string' 
                            ? n.content 
                            : String(n.content || '')
                }));
            }
        } catch (e) {
            console.error("Failed to load notes vault", e);
        }
    }

    private save() {
        try {
            SecureStoreService.setItemSync(this.storageKey, JSON.stringify(this.notes));
        } catch (e) {
            console.error("Failed to save notes vault", e);
        }
    }

    addNote(content: string, type: 'text' | 'voice' = 'text', linkedCaseId?: string): Note {
        const newNote: Note = {
            id: Date.now().toString(),
            content,
            type,
            createdAt: Date.now(),
            linkedCaseId
        };
        this.notes.unshift(newNote); // Add to top
        this.save();
        return newNote;
    }

    getNotes(): Note[] {
        return this.notes;
    }

    deleteNote(id: string) {
        this.notes = this.notes.filter(n => n.id !== id);
        this.save();
    }

    updateNote(id: string, updates: Partial<Pick<Note, 'content' | 'tags' | 'linkedCaseId'>>): void {
        const idx = this.notes.findIndex(n => n.id === id);
        if (idx === -1) return;
        this.notes[idx] = { ...this.notes[idx], ...updates };
        this.save();
    }

    syncFromGlobal(_userId: string, note: { id: string | number; body: string; type?: string }, isNew: boolean, vaultId?: string): string {
        const body = (note.body || '').trim();
        if (!body) return vaultId || '';

        if (vaultId) {
            this.updateNote(vaultId, {
                content: body,
            });
            return vaultId;
        }

        if (!isNew) {
            const existing = this.notes.find((n) => n.id === `g_${String(note.id)}`);
            if (existing) {
                this.updateNote(existing.id, { content: body });
                return existing.id;
            }
        }

        const created = this.addNote(body, note.type === 'voice' ? 'voice' : 'text');
        return created.id;
    }
}

export const notesVault = new NotesVaultService();

