export type CommitFieldTasksSheetOpenParams = {
    sheetOpenRef: MutableRefObject<boolean>;
    instantPaint: FieldTasksInstantPaintModule | null;
    setFieldTasksHostMounted: (mounted: boolean) => void;
    setTasksManagerFocusTaskId: (id: string | undefined) => void;
    setShowTasksManager: (open: boolean) => void;
    setFieldTasksSheetOpen: (open: boolean) => void;
    closeCommunity?: () => void;
    setActiveTab: (tab: 'home') => void;
};

/** فتح ستارة الميدان: reveal فوري ثم commit + warm في microtask. */
export function commitFieldTasksSheetOpen({
    sheetOpenRef,
    instantPaint,
    setFieldTasksHostMounted,
    setTasksManagerFocusTaskId,
    setShowTasksManager,
    setFieldTasksSheetOpen,
    closeCommunity,
    setActiveTab,
}: CommitFieldTasksSheetOpenParams): void {
    clearFieldTasksPerfMarks();
    markFieldTasksPerfPhase('open-request');
    warmQuantumTasksDiskRead();

    const revealed = instantPaint?.revealFieldTasksWarmSheet() ?? false;

    const commitOpen = () => {
        setFieldTasksHostMounted(true);
        setTasksManagerFocusTaskId(undefined);
        setShowTasksManager(false);
        setFieldTasksSheetOpen(true);
        persistFieldTasksSessionOpen(true, 'sheet');
    };

    if (revealed) {
        requestAnimationFrame(commitOpen);
    } else {
        flushSync(commitOpen);
    }

    queueMicrotask(() => {
        warmFieldTasksOnOpen();
        dismissTransientOverlays('field-tasks');
        closeCommunity?.();
        setActiveTab('home');
    });
}

export type CommitTasksManagerOpenParams = {
    focusTaskId?: string;
    armFieldTasksManagerHost: () => void;
    revealTasksManager: (focusTaskId?: string) => void;
    afterOpen?: () => void;
};

export function commitTasksManagerOpen({
    focusTaskId,
    armFieldTasksManagerHost,
    revealTasksManager,
    afterOpen,
}: CommitTasksManagerOpenParams): void {
    clearFieldTasksPerfMarks();
    markFieldTasksPerfPhase('open-request');
    flushSync(() => {
        armFieldTasksManagerHost();
        revealTasksManager(focusTaskId);
    });
    queueMicrotask(() => {
        dismissTransientOverlays('tasks-manager');
        afterOpen?.();
    });
}

import { useEffect } from 'react';

import { onDashboardInteractive } from '@/app/bootstrap/bootMetrics';
import { loadNotificationStore } from '@/app/hooks/lawyerDashboard/notifications/notificationDashboardLazyImports';

export type SearchNotificationRow = {
    id: string;
    title: string;
    message: string;
    type: string;
};

type UseNotificationStoreSyncParams = {
    showNotifications: boolean;
    initialSessionOpen: boolean;
    setStoreUnreadCount: (count: number) => void;
    setSearchNotifications: (rows: SearchNotificationRow[]) => void;
};

/** ربط zustand بعد interactive أو عند فتح اللوحة — ليس على مسار أول paint. */
export function useNotificationStoreSync({
    showNotifications,
    initialSessionOpen,
    setStoreUnreadCount,
    setSearchNotifications,
}: UseNotificationStoreSyncParams): void {
    useEffect(() => {
        let cancelled = false;
        let unsub: (() => void) | undefined;
        let idleTimer: number | undefined;

        const bind = () => {
            void loadNotificationStore()
                .then(({ useNotificationStore }) => {
                    if (cancelled) return;
                    const sync = () => {
                        const s = useNotificationStore.getState();
                        setStoreUnreadCount(s.unreadCount);
                        setSearchNotifications(
                            s.notifications.map((n) => ({
                                id: n.id,
                                title: n.title,
                                message: n.message,
                                type: n.type,
                            })),
                        );
                    };
                    sync();
                    unsub = useNotificationStore.subscribe(sync);
                })
                .catch(() => undefined);
        };

        if (showNotifications || initialSessionOpen) {
            bind();
            return () => {
                cancelled = true;
                unsub?.();
            };
        }

        const offInteractive = onDashboardInteractive(() => {
            idleTimer = window.setTimeout(bind, 0);
        });

        return () => {
            cancelled = true;
            offInteractive();
            if (idleTimer != null) window.clearTimeout(idleTimer);
            unsub?.();
        };
    }, [showNotifications, initialSessionOpen]);
}

import { useCallback, useEffect, useRef, useState } from 'react';
import type { NotificationModel } from '@/app/infrastructure/NotificationRepository';
import { useNotificationStore } from '@/app/stores/notificationStore';
import { BUILTIN_NOTIFICATIONS_ENABLED } from '@/app/services/settings/builtInBehavior';

const MAX_VISIBLE = 2;
const AUTO_DISMISS_MS = 6_500;

const MAX_KNOWN_NOTIFICATION_IDS = 400;

function rememberNotificationId(knownIds: Set<string>, id: string): void {
    knownIds.add(id);
    if (knownIds.size <= MAX_KNOWN_NOTIFICATION_IDS) return;
    const trimmed = [...knownIds].slice(-MAX_KNOWN_NOTIFICATION_IDS);
    knownIds.clear();
    for (const entry of trimmed) knownIds.add(entry);
}

export type IncomingNotificationPopup = {
    id: string;
    title: string;
    message: string;
    createdAt: string;
};

function toPopup(n: NotificationModel): IncomingNotificationPopup {
    return {
        id: n.id,
        title: n.title,
        message: n.message,
        createdAt: n.createdAt,
    };
}

export function useIncomingNotificationPopups(options: {
    userId: string;
    isPanelOpen: boolean;
    enabled?: boolean;
}) {
    const { userId, isPanelOpen, enabled = true } = options;
    const notifications = useNotificationStore((s) => s.notifications);
    const isLoading = useNotificationStore((s) => s.isLoading);

    const [queue, setQueue] = useState<IncomingNotificationPopup[]>([]);
    const baselineReadyRef = useRef(false);
    const knownIdsRef = useRef(new Set<string>());
    const dismissTimersRef = useRef<Map<string, number>>(new Map());

    const clearTimer = useCallback((id: string) => {
        const t = dismissTimersRef.current.get(id);
        if (t !== undefined) {
            window.clearTimeout(t);
            dismissTimersRef.current.delete(id);
        }
    }, []);

    const dismiss = useCallback(
        (id: string) => {
            clearTimer(id);
            setQueue((prev) => prev.filter((p) => p.id !== id));
        },
        [clearTimer],
    );

    const scheduleDismiss = useCallback(
        (id: string) => {
            clearTimer(id);
            const t = window.setTimeout(() => dismiss(id), AUTO_DISMISS_MS);
            dismissTimersRef.current.set(id, t);
        },
        [clearTimer, dismiss],
    );

    useEffect(() => {
        return () => {
            for (const t of dismissTimersRef.current.values()) {
                window.clearTimeout(t);
            }
            dismissTimersRef.current.clear();
        };
    }, []);

    useEffect(() => {
        if (!userId) {
            baselineReadyRef.current = false;
            knownIdsRef.current = new Set();
            setQueue([]);
            return;
        }
        baselineReadyRef.current = false;
        knownIdsRef.current = new Set();
        setQueue([]);
    }, [userId]);

    useEffect(() => {
        if (!enabled || !BUILTIN_NOTIFICATIONS_ENABLED || !userId) return;

        if (!baselineReadyRef.current) {
            if (isLoading) return;
            knownIdsRef.current = new Set();
            for (const n of notifications) rememberNotificationId(knownIdsRef.current, n.id);
            baselineReadyRef.current = true;
            return;
        }

        if (isPanelOpen) {
            setQueue([]);
            for (const n of notifications) rememberNotificationId(knownIdsRef.current, n.id);
            return;
        }

        const fresh = notifications.filter((n) => !n.isRead && !knownIdsRef.current.has(n.id));
        if (fresh.length === 0) return;

        for (const n of fresh) rememberNotificationId(knownIdsRef.current, n.id);

        setQueue((prev) => {
            const existing = new Set(prev.map((p) => p.id));
            const merged = [...prev];
            for (const n of fresh) {
                if (existing.has(n.id)) continue;
                merged.unshift(toPopup(n));
            }
            return merged.slice(0, MAX_VISIBLE);
        });
    }, [enabled, isLoading, isPanelOpen, notifications, userId]);

    useEffect(() => {
        for (const item of queue) {
            if (!dismissTimersRef.current.has(item.id)) {
                scheduleDismiss(item.id);
            }
        }
        for (const id of [...dismissTimersRef.current.keys()]) {
            if (!queue.some((q) => q.id === id)) clearTimer(id);
        }
    }, [clearTimer, queue, scheduleDismiss]);

    return { queue, dismiss };
}

