const EMPTY_CRIMINAL_CASES_FOR_CLUSTER: unknown[] = [];

function clusterScanSourcesSame(a: ClusterScanSources, b: ClusterScanSources): boolean {
    return (
        a.ready === b.ready &&
        a.lawsuitFiles === b.lawsuitFiles &&
        a.executionFiles === b.executionFiles &&
        a.criminalCases === b.criminalCases &&
        a.urgentCases === b.urgentCases &&
        a.threadingTransactions === b.threadingTransactions &&
        a.notes === b.notes &&
        a.fieldTasks === b.fieldTasks
    );
}

function readDeferredEarlyArm(): boolean {
    if (typeof window === 'undefined') return false;
    if (readInitialCommunityOpen()) return true;
    if (readInitialTransactionsSession().open) return true;
    if (readInitialFieldTasksSession().open) return true;
    if (readInitialGlobalSearchSession().open) return true;
    if (readInitialRepositorySession().open) return true;
    const tab = readInitialLawyerTab();
    return tab === 'schedule';
}

export function useLawyerDashboardCoreOrchestration({
    authUser: _authUserOverride,
    onNavigateToCase,
    pendingFieldTasksCount,
    quantumTasksFingerprint,
    backgroundRuntimeEnabled,
}: Pick<
    UseLawyerDashboardCoreParams,
    | 'authUser'
    | 'onNavigateToCase'
    | 'pendingFieldTasksCount'
    | 'quantumTasksFingerprint'
    | 'backgroundRuntimeEnabled'
>) {
    const criminalBridge = useCriminalDashboardBridge();
    const appearance = useLawyerSettingsAppearance();
    const dataSettings = useLawyerSettingsData();
    const securitySettings = useLawyerSettingsSecurity();
    const performance = useLawyerSettingsPerformance();
    /** بدون homeLayout — HomeTab يقرأ الشريحة مباشرة؛ يمنع إعادة رسم LD عند تعديل الرصيف */
    const settings = useMemo((): AppSettingsState => {
        return {
            version: SETTINGS_SCHEMA_VERSION,
            appearance,
            security: securitySettings,
            data: dataSettings,
            performance,
            homeLayout: LAWYER_SETTINGS_V2_DEFAULTS.homeLayout,
        };
    }, [appearance, securitySettings, dataSettings, performance]);
    const currentTheme = appearance.theme;
    const pushAllowed = useLawyerSettingsPushAllowed();
    const appLock = useAppLock(securitySettings);
    const localAutoSave = dataSettings.autoSave;
    const cloudSyncReady =
        dataSettings.cloudSync && !securitySettings.localOnlyMode;
    const syncNotesOn = cloudSyncReady;
    const syncFilesOn = cloudSyncReady;
    const syncExecutionOn = cloudSyncReady;

    const { user: authUser } = useAuthSafe();
    const { user, authGate } = useLawyerDashboardAuth({
        authUser,
    });

    const shellAuthUserId = resolveShellAuthUserId(authUser?.id, user?.id);

    const notifications = useLawyerDashboardNotifications(shellAuthUserId, {
        backgroundRuntimeEnabled,
    });
    /** حي دائماً — ليس داخل الجزيرة المؤجّلة (كان requestArm يُسبّب تأخير الدخول) */
    const settingsFeature = useLawyerDashboardSettings(shellAuthUserId);
    const appAlerts = useLawyerDashboardAppAlerts(user?.id);
    const archiveAndSync = useLawyerDashboardArchiveAndSyncRefs();

    const overlays = useLawyerDashboardOverlays({
        setArchiveType: archiveAndSync.setArchiveType,
        executionArchiveOpen: archiveAndSync.archiveType === 'execution',
    });

    /** حي دائماً — مثل الإعدادات؛ إلغاء انتظار أول فتح للمنتدى بسبب stubs/deferred */
    const communityFeature = useLawyerDashboardCommunity({
        userId: shellAuthUserId,
        activeTab: overlays.activeTab,
    });

    const dashboardHome = useLawyerDashboardHomeTab({
        activeTab: overlays.activeTab,
        setActiveTab: overlays.setActiveTab,
    });

    const { theme, shapeClass } = useThemeStyles(currentTheme, appearance.shape);

    const [earlyArm] = useState(readDeferredEarlyArm);
    const [forceArm, setForceArm] = useState(false);
    const pendingOpRef = useRef<DeferredPendingOp>(null);
    const [liveBag, setLiveBag] = useState<DeferredFeatureBag | null>(null);

    const requestArm = useCallback((op: DeferredPendingOp) => {
        pendingOpRef.current = op;
        setForceArm(true);
    }, []);

    const stubs = useMemo(() => createDeferredFeatureStubs(requestArm), [requestArm]);
    const bag = liveBag ?? stubs;

    const bumpSearchIndexRef = useRef(() => undefined);
    const closeNotepadRef = useRef(() => undefined);
    bumpSearchIndexRef.current = () => bag.globalSearch.bumpSearchIndex();
    closeNotepadRef.current = () => bag.repository.closeRepository();

    const onDeferredFeaturesReady = useCallback((next: DeferredFeatureBag) => {
        bumpSearchIndexRef.current = () => next.globalSearch.bumpSearchIndex();
        closeNotepadRef.current = () => next.repository.closeRepository();
        setLiveBag((prev) => {
            if (prev === null) {
                const op = pendingOpRef.current;
                pendingOpRef.current = null;
                if (op) {
                    queueMicrotask(() => runDeferredPendingOp(next, op));
                }
            }
            return next;
        });
    }, []);

    const productivityOverlayClosers = useMemo(
        () => ({
            closeGlobalSearch: () => bag.globalSearch.closeGlobalSearch(),
            closeSettings: () => settingsFeature.closeSettings(),
            closeVault: () => bag.repository.closeRepository(),
            closeNotepad: () => bag.repository.closeRepository(),
            closeTransactionsHub: () => bag.transactions.closeTransactionsHub(),
            closeNotifications: () => notifications.closeNotifications(),
            closeCommunity: () => communityFeature.closeCommunity(),
        }),
        [bag, communityFeature, notifications, settingsFeature],
    );

    const openNotificationsInnerRef = useRef(notifications.openNotifications);
    openNotificationsInnerRef.current = notifications.openNotifications;

    const openNotifications = useCallback(() => {
        closeOverlaysBeforeNotificationsOpen(productivityOverlayClosers);
        openNotificationsInnerRef.current();
    }, [productivityOverlayClosers]);

    const openCommunityTabInnerRef = useRef(communityFeature.openCommunityTab);
    openCommunityTabInnerRef.current = communityFeature.openCommunityTab;

    const openCommunityTab = useCallback(() => {
        closeOverlaysBeforeForumOpen(productivityOverlayClosers);
        openCommunityTabInnerRef.current();
    }, [productivityOverlayClosers]);

    const openTransactionsHubInnerRef = useRef(bag.transactions.openTransactionsHub);
    openTransactionsHubInnerRef.current = bag.transactions.openTransactionsHub;

    const openTransactionsHub = useCallback((focusId?: string) => {
        closeOverlaysBeforeTransactionsOpen(productivityOverlayClosers);
        openTransactionsHubInnerRef.current(focusId);
    }, [productivityOverlayClosers]);

    const openSettingsInnerRef = useRef(settingsFeature.openSettings);
    openSettingsInnerRef.current = settingsFeature.openSettings;

    const openSettings = useCallback(() => {
        // افتح أولاً — لا تؤخّر القشرة خلف إغلاق overlays / setActiveTab
        openSettingsInnerRef.current();
        if (overlays.activeTab !== 'home') {
            overlays.setActiveTab('home');
        }
        queueMicrotask(() => {
            closeOverlaysBeforeSettingsOpen(productivityOverlayClosers);
        });
    }, [overlays, productivityOverlayClosers]);

    const hydrateCasesFromLawsuitFiles = useCaseStore((s) => s.hydrateCasesFromLawsuitFiles);
    const selectCase = useCaseStore((s) => s.selectCase);
    const storeCases = useCaseStore((s) => s.cases);
    const quantumPendingForField = useMemo(
        () => getQuantumPendingSnapshot(),
        [quantumTasksFingerprint],
    );
    const quantumTasks = quantumPendingForField;

    const workspace = useLawyerDashboardWorkspace({
        localAutoSave,
        backgroundRuntimeEnabled,
        user,
        authUserId: authUser?.id,
        refreshAppAlerts: appAlerts.refreshAppAlerts,
        showLawsuitsWorkspace: overlays.showLawsuitsWorkspace,
        archiveType: archiveAndSync.archiveType,
        setArchiveType: archiveAndSync.setArchiveType,
        criminalBridge,
        onOpenCriminalDashboard: overlays.openCriminalCase,
        bumpSearchIndex: () => bumpSearchIndexRef.current(),
        selectCase,
        closeNotepad: () => closeNotepadRef.current(),
    });

    const dashboardExecutionFiles = useMemo<DashboardExecutionFile[]>(
        () =>
            (Array.isArray(workspace.executionFiles) ? workspace.executionFiles : []).map((file) =>
                coerceExecutionFilePreserveId(file),
            ),
        [workspace.executionFiles],
    );

    const navigation = useLawyerDashboardNavigation({
        userId: shellAuthUserId,
        files: workspace.files,
        executionFiles: dashboardExecutionFiles,
        setActiveTab: overlays.setActiveTab,
        setShowCommunity: communityFeature.setShowCommunity,
        setCommunityDeepLink: communityFeature.setCommunityDeepLink,
        setArchiveType: archiveAndSync.setArchiveType,
        setActiveFile: workspace.setActiveFile,
        setShowNotifications: notifications.closeNotifications,
        openNotepad: bag.repository.openNotepad,
        setTransactionsFocusId: bag.transactions.setTransactionsFocusId,
        openUrgentInLawsuitsWorkspace: overlays.openUrgentInLawsuitsWorkspace,
        openVaultModal: bag.repository.openVaultModal,
        openTransactionsHub: openTransactionsHub,
        openCommunityTab,
        openFieldTasksSheet: bag.fieldTasks.openFieldTasksSheet,
        openCriminalCase: overlays.openCriminalCase,
        openTasksManager: bag.fieldTasks.openTasksManager,
        openScheduleTab: bag.schedule.openScheduleTab,
    });

    const criminalCasesForCluster = criminalBridge.ready
        ? criminalBridge.criminalCases
        : EMPTY_CRIMINAL_CASES_FOR_CLUSTER;
    const { calendarUserId, clusterScanSources: liteClusterScanSources } =
        useLawyerDashboardCalendarClusterLite({
            enabled: backgroundRuntimeEnabled,
            userId: user?.id,
            authUserId: authUser?.id,
            files: workspace.files,
            executionFiles: dashboardExecutionFiles,
            globalNotes: workspace.globalNotes,
            quantumTasks,
            criminalCasesForCluster,
        });
    const [hydratedClusterScanSources, setHydratedClusterScanSources] =
        useState<ClusterScanSources | null>(null);
    const onClusterScanSources = useCallback((sources: ClusterScanSources) => {
        setHydratedClusterScanSources((prev) =>
            prev && clusterScanSourcesSame(prev, sources) ? prev : sources,
        );
    }, []);
    const clusterScanSources = hydratedClusterScanSources ?? liteClusterScanSources;

    const pendingFieldTasksCountResolved = pendingFieldTasksCount;

    const openGlobalSearchInnerRef = useRef(bag.globalSearch.openGlobalSearch);
    openGlobalSearchInnerRef.current = bag.globalSearch.openGlobalSearch;

    const openGlobalSearch = useCallback(
        (seed = '') => {
            closeOverlaysBeforeGlobalSearchOpen(productivityOverlayClosers);
            const querySeed = typeof seed === 'string' ? seed : '';
            openGlobalSearchInnerRef.current(querySeed);
        },
        [productivityOverlayClosers],
    );

    const openProfileTabInnerRef = useRef(bag.profile.openProfileTab);
    openProfileTabInnerRef.current = bag.profile.openProfileTab;

    const openProfileTab = useCallback(() => {
        // افتح أولاً — لا تؤخّر التبويب خلف إغلاق overlays (نفس معيار الإعدادات)
        openProfileTabInnerRef.current();
        queueMicrotask(() => {
            closeOverlaysBeforeProfileOpen(productivityOverlayClosers);
        });
    }, [productivityOverlayClosers]);

    const closeHubShellOverlays = useCallback(() => {
        overlays.closeHubShellOverlays();
        bag.transactions.closeTransactionsHub();
        bag.repository.closeRepository();
        bag.globalSearch.closeGlobalSearch();
    }, [bag.globalSearch, bag.repository, bag.transactions, overlays]);

    const exitToHomeDashboard = useCallback(() => {
        overlays.exitCriminalDossierToHome();
        closeHubShellOverlays();
        overlays.setActiveTab('home');
        queueMicrotask(() => dismissTransientOverlays());
    }, [closeHubShellOverlays, overlays]);

    const deferredFeatureSurfacesProps = useMemo((): LawyerDashboardDeferredFeatureSurfacesProps => {
        return {
            earlyArm,
            forceArm,
            params: {
                userId: shellAuthUserId,
                activeTab: overlays.activeTab,
                setActiveTab: overlays.setActiveTab,
                setArchiveType: archiveAndSync.setArchiveType,
                setShowLawsuitsWorkspace: overlays.setShowLawsuitsWorkspace,
                files: workspace.files,
                executionFiles: dashboardExecutionFiles,
                openNotifications,
                openCommunityTab,
                setShowCommunity: communityFeature.setShowCommunity,
                closeCommunity: communityFeature.closeCommunity,
                setCommunityDeepLink: communityFeature.setCommunityDeepLink,
                openTransactionsHub,
                openProfileTab,
                openUrgentInLawsuitsWorkspace: overlays.openUrgentInLawsuitsWorkspace,
                openCriminalCase: overlays.openCriminalCase,
                setActiveFile: workspace.setActiveFile,
                selectCase,
                onNavigateToCase,
            },
            onReady: onDeferredFeaturesReady,
        };
    }, [
        archiveAndSync.setArchiveType,
        communityFeature.closeCommunity,
        communityFeature.setCommunityDeepLink,
        communityFeature.setShowCommunity,
        dashboardExecutionFiles,
        earlyArm,
        forceArm,
        onDeferredFeaturesReady,
        onNavigateToCase,
        openCommunityTab,
        openNotifications,
        openProfileTab,
        openTransactionsHub,
        overlays.activeTab,
        overlays.openCriminalCase,
        overlays.openUrgentInLawsuitsWorkspace,
        overlays.setActiveTab,
        overlays.setShowLawsuitsWorkspace,
        selectCase,
        shellAuthUserId,
        workspace.files,
        workspace.setActiveFile,
    ]);

    const dashboardCommunity = { ...communityFeature, openCommunityTab };
    const dashboardSettings = { ...settingsFeature, openSettings };
    const dashboardTransactions = { ...bag.transactions, openTransactionsHub };
    const dashboardRepository = bag.repository;
    const dashboardGlobalSearch = bag.globalSearch;
    const dashboardFieldTasks = bag.fieldTasks;
    const dashboardSchedule = bag.schedule;
    const profileTab = bag.profile;
    const globalSearchNav = bag.globalSearchNav;

    return {
        authGate,
        user,
        authUser,
        settings,
        theme,
        shapeClass,
        pushAllowed,
        syncNotesOn,
        syncFilesOn,
        syncExecutionOn,
        appLock,
        notifications: { ...notifications, openNotifications },
        profileTab,
        dashboardSettings,
        dashboardTransactions,
        dashboardRepository,
        dashboardGlobalSearch,
        dashboardFieldTasks,
        dashboardSchedule,
        dashboardCommunity,
        dashboardHome,
        appAlerts,
        archiveAndSync,
        overlays: {
            ...overlays,
            ...dashboardSettings,
            ...dashboardTransactions,
            ...dashboardRepository,
            ...dashboardGlobalSearch,
            ...dashboardFieldTasks,
            ...dashboardSchedule,
            ...dashboardCommunity,
            openTransactionsHub,
            openCommunityTab,
            ...dashboardHome,
            openGlobalSearch,
            openSettings,
            openProfileTab,
            closeHubShellOverlays,
            exitToHomeDashboard,
        },
        workspace,
        navigation,
        calendarUserId,
        clusterScanSources,
        onClusterScanSources,
        criminalCasesForCluster,
        criminalBridge,
        globalSearchNav,
        quantumPendingForField,
        pendingFieldTasksCount: pendingFieldTasksCountResolved,
        storeCases,
        hydrateCasesFromLawsuitFiles,
        dashboardExecutionFiles,
        deferredFeatureSurfacesProps,
    };
}

import { useCallback, useEffect, useRef, useState } from 'react';
import type { FileData } from '@/app/components/lawyer/LawyerShared';
import { SecretaryOrchestrator, type SecretaryAlert } from '@/app/services/SecretaryOrchestrator';
import { filterAuthenticSecretaryAlerts } from '@/app/services/calendarAuthenticity';
import { enrichAlertClientPhone } from '@/app/services/enrichAlertContact';
import { resolveCalendarUserId } from '@/app/services/calendar/bridge/lite';
import { CALENDAR_UPDATED_EVENT } from '@/app/services/calendarBridge.types';
import { syncPushForNewCriticalAlerts } from '@/app/services/appAlertPushSync';
import { writeHomeHubSecretaryAlertsCache, peekHomeHubSecretaryAlertsCache } from '@/app/services/alerts/homeHubSecretaryAlertsWarmCache';
import { filterAlertsByNotificationSettings, getLawyerSettingsSnapshot } from '@/app/services/settings/settingsRuntime';
import { isBenignSecureFetchError } from '@/app/services/secureFetchErrors';
import type { LegalTask } from '@/app/types/TaskEngine';
import { debug } from '@/app/utils/debug';

function loadCalendarDossierSync() {
    return import('@/app/services/calendarDossierSync');
}

type RawNote = {
    id: string | number;
    title?: string;
    body?: string;
    isPinned?: boolean;
    date?: string;
    apptDate?: string;
    reminder_at?: string;
};

const REFRESH_INTERVAL_MS = 5 * 60 * 1000;
const CALENDAR_REPOPULATE_INTERVAL_MS = 25 * 60 * 1000;
const DEBOUNCE_MS = 350;
const DATA_CHANGE_DEBOUNCE_MS = 2_500;

/** بصمة خفيفة — تجنّب join لآلاف المعرفات على كل تغيير */
function fingerprintIds(items: Array<{ id?: unknown }>): number {
    let h = items.length;
    const step = items.length > 48 ? Math.ceil(items.length / 48) : 1;
    for (let i = 0; i < items.length; i += step) {
        const id = String(items[i]?.id ?? i);
        h = (Math.imul(h, 31) + id.charCodeAt(0)) | 0;
        if (id.length > 1) h = (Math.imul(h, 31) + id.charCodeAt(id.length - 1)) | 0;
    }
    return h;
}

function buildAlertsDataSignature(params: {
    files: FileData[];
    executionFiles: unknown[];
    criminalCases?: unknown[];
    notes: RawNote[];
    fieldTasks?: LegalTask[];
}): string {
    return [
        params.files.length,
        params.executionFiles.length,
        params.criminalCases?.length ?? 0,
        params.notes.length,
        params.fieldTasks?.length ?? 0,
        fingerprintIds(params.files),
        fingerprintIds(params.executionFiles as Array<{ id?: unknown }>),
        fingerprintIds((params.criminalCases ?? []) as Array<{ id?: unknown }>),
        fingerprintIds(params.notes),
        fingerprintIds(params.fieldTasks ?? []),
    ].join('|');
}

export function useAppAlerts(params: {
    lawyerId?: string | null;
    files: FileData[];
    executionFiles: unknown[];
    criminalCases?: unknown[];
    notes: RawNote[];
    fieldTasks?: LegalTask[];
    /** تأجيل توليد تنبيهات السكرتير حتى idle — لا يعيق أول إطار */
    deferUntilIdle?: boolean;
}) {
    const resolvedLawyerId = resolveCalendarUserId(params.lawyerId ?? null);
    const initialCached = peekHomeHubSecretaryAlertsCache(resolvedLawyerId);

    const [alerts, setAlerts] = useState<SecretaryAlert[]>(() => initialCached ?? []);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);

    const filesRef = useRef(params.files);
    const executionRef = useRef(params.executionFiles);
    const notesRef = useRef(params.notes);
    const fieldTasksRef = useRef(params.fieldTasks ?? []);
    const criminalRef = useRef(params.criminalCases ?? []);
    const generationRef = useRef(0);
    const debounceRef = useRef<number | null>(null);
    const hasLoadedOnceRef = useRef(initialCached !== null);
    const dataSignatureRef = useRef('');

    filesRef.current = params.files;
    executionRef.current = params.executionFiles;
    notesRef.current = params.notes;
    fieldTasksRef.current = params.fieldTasks ?? [];
    criminalRef.current = params.criminalCases ?? [];

    const refresh = useCallback(async (options?: { syncCalendar?: boolean }) => {
        const syncCalendar = options?.syncCalendar === true;
        const uid = resolveCalendarUserId(params.lawyerId ?? null);
        const gen = ++generationRef.current;
        setError(null);
        try {
            if (syncCalendar) {
                try {
                    const { ensureCalendarPopulatedFromLiveDossiers } = await loadCalendarDossierSync();
                    await ensureCalendarPopulatedFromLiveDossiers(
                        {
                            lawyerId: uid,
                            lawsuitFiles: filesRef.current,
                            executionFiles: executionRef.current,
                            criminalCases: criminalRef.current,
                            globalNotes: notesRef.current,
                            fieldTasks: fieldTasksRef.current,
                        },
                        { emitUpdated: false },
                    );
                } catch (calendarErr) {
                    debug.warn('[useAppAlerts] calendar populate skipped (non-fatal):', calendarErr);
                }
            }

            const rawList = await SecretaryOrchestrator.getUnifiedAlerts({
                lawyerId: uid,
                files: filesRef.current,
                executionFiles: executionRef.current,
                criminalCases: criminalRef.current,
                notes: notesRef.current,
                fieldTasks: fieldTasksRef.current,
            });
            const enriched = rawList.map((a) =>
                enrichAlertClientPhone(a, {
                    lawsuitFiles: filesRef.current,
                    executionFiles: executionRef.current,
                    criminalCases: criminalRef.current,
                }),
            );
            const list = filterAuthenticSecretaryAlerts(enriched);
            if (gen !== generationRef.current) return;
            const settings = getLawyerSettingsSnapshot();
            const visible = filterAlertsByNotificationSettings(list, settings);
            setAlerts(visible);
            writeHomeHubSecretaryAlertsCache(uid, visible);
            void syncPushForNewCriticalAlerts(list, uid);
        } catch (err) {
            if (gen !== generationRef.current) return;
            const msg = err instanceof Error ? err.message : 'تعذّر تحديث التنبيهات';
            if (isBenignSecureFetchError(err)) {
                debug.warn('[useAppAlerts] refresh skipped (offline/unavailable):', err);
            } else {
                debug.error('[useAppAlerts] refresh failed:', err);
            }
            setError(msg);
        } finally {
            if (gen === generationRef.current) {
                setLoading(false);
                hasLoadedOnceRef.current = true;
            }
        }
    }, [params.lawyerId]);

    useEffect(() => {
        const uid = resolveCalendarUserId(params.lawyerId ?? null);
        const cached = peekHomeHubSecretaryAlertsCache(uid);
        hasLoadedOnceRef.current = cached !== null;
        setAlerts(cached ?? []);
        setError(null);
        dataSignatureRef.current = '';
    }, [params.lawyerId]);

    const scheduleRefresh = useCallback(
        (options?: { syncCalendar?: boolean; debounceMs?: number }) => {
            const debounceMs = options?.debounceMs ?? DEBOUNCE_MS;
            if (debounceRef.current !== null) window.clearTimeout(debounceRef.current);
            debounceRef.current = window.setTimeout(() => {
                debounceRef.current = null;
                void refresh({ syncCalendar: options?.syncCalendar });
            }, debounceMs);
        },
        [refresh],
    );

    useEffect(() => {
        const runInitial = () => scheduleRefresh({ syncCalendar: true });
        let cancelDefer: (() => void) | undefined;
        if (params.deferUntilIdle) {
            if (typeof requestIdleCallback !== 'undefined') {
                const idleId = requestIdleCallback(runInitial, { timeout: 1_500 });
                cancelDefer = () => cancelIdleCallback(idleId);
            } else {
                const t = window.setTimeout(runInitial, 400);
                cancelDefer = () => window.clearTimeout(t);
            }
        } else {
            runInitial();
        }
        let interval: number | null = null;
        let calendarInterval: number | null = null;
        const startInterval = () => {
            if (interval != null) return;
            interval = window.setInterval(
                () => void refresh({ syncCalendar: false }),
                REFRESH_INTERVAL_MS,
            );
            calendarInterval = window.setInterval(
                () => void refresh({ syncCalendar: true }),
                CALENDAR_REPOPULATE_INTERVAL_MS,
            );
        };
        const stopInterval = () => {
            if (interval != null) {
                window.clearInterval(interval);
                interval = null;
            }
            if (calendarInterval != null) {
                window.clearInterval(calendarInterval);
                calendarInterval = null;
            }
        };
        const isVisible = () =>
            typeof document === 'undefined' || document.visibilityState !== 'hidden';
        if (isVisible()) startInterval();

        const onCalendar = () => scheduleRefresh({ syncCalendar: false });
        const onVisibilityChange = () => {
            if (isVisible()) {
                scheduleRefresh({ syncCalendar: false });
                startInterval();
            } else {
                stopInterval();
            }
        };
        window.addEventListener(CALENDAR_UPDATED_EVENT, onCalendar);
        if (typeof document !== 'undefined') {
            document.addEventListener('visibilitychange', onVisibilityChange);
        }
        return () => {
            cancelDefer?.();
            if (debounceRef.current !== null) window.clearTimeout(debounceRef.current);
            stopInterval();
            window.removeEventListener(CALENDAR_UPDATED_EVENT, onCalendar);
            if (typeof document !== 'undefined') {
                document.removeEventListener('visibilitychange', onVisibilityChange);
            }
            generationRef.current += 1;
        };
    }, [scheduleRefresh, refresh, params.deferUntilIdle, params.lawyerId]);

    useEffect(() => {
        const signature = buildAlertsDataSignature(params);
        if (signature === dataSignatureRef.current) return;
        dataSignatureRef.current = signature;
        scheduleRefresh({ syncCalendar: false, debounceMs: DATA_CHANGE_DEBOUNCE_MS });
    }, [
        params.files,
        params.executionFiles,
        params.criminalCases,
        params.notes,
        params.fieldTasks,
        scheduleRefresh,
    ]);

    return {
        alerts,
        loading,
        error,
        refresh: () => refresh({ syncCalendar: true }),
        refreshLight: () => refresh({ syncCalendar: false }),
    };
}

import { useCallback } from 'react';
import type { ExecutionFile, SeizedAsset, TimelineEvent } from '@/app/types/execution';
import { stripPendingLabelsFromExecutorSubject } from '@/app/utils/executorDecisionTitles';
import {
    inferExecutorDispatcherRoute,
    isGuarantorRequestDecisionRow,
    patchExecutorDecisionRowReliable,
    type PersonalCoerciveSubtype,
} from '@/app/utils/executorSeizureDecisionQueue';
import {
    applyPersonalCoerciveExecutorOutcome,
    buildPersonalCoerciveExecutionMerge,
} from '@/app/components/lawyer/ExecutionDashboard/utils/applyPersonalCoerciveExecutorOutcome';
import {
    buildExecutionMergeForCreditorHeirSubstitutionApproval,
    buildExecutionMergeForCreditorPartyDeath,
    parseCreditorPartyDeathPayload,
} from '@/app/utils/creditorPartyDeathPersistence';
import { getLocalTodayYmd } from '@/app/utils/executionStateMachine';
import {
    handleExecutorApproval,
    inferExecutorApprovalDecisionType,
    type EvictionExecutorWorkflowKey,
    type ExecutorApprovalActions,
} from '@/app/utils/executorApprovalWorkflow';
import {
    buildResidentialGraceEarlyEndApprovalMerge,
    dispatchResidentialGraceCleared,
} from '@/app/utils/residentialEvictionGrace';

function cleanSeizureTypePendingSuffix(t: string): string {
    return t
        .replace(/\s*\(\s*قيد\s*البت\s*\)\s*/gi, '')
        .replace(/\s*قيد\s*البت\s*/gi, '')
        .trim();
}

function baseSeizureLabelFromType(tRaw: string): string {
    const t = cleanSeizureTypePendingSuffix(tRaw);
    if (/راتب|خُمس|خمس/i.test(t) || /حجز راتب/i.test(t)) return 'طلب حجز راتب';
    if (/منقول|مركبة|مال منقول/i.test(t)) return 'طلب حجز مال منقول';
    if (/عقار/i.test(t)) return 'طلب حجز عقار';
    return t || tRaw;
}

function coerciveKeyForSeizureDraft(asset: Pick<SeizedAsset, 'type'>): 'salary' | 'property' | 'vehicle' | null {
    const t = String(asset.type || '');
    if (/راتب|خُمس|خمس|حجز راتب/i.test(t)) return 'salary';
    if (/عقار/i.test(t)) return 'property';
    if (/منقول|مركبة|مال منقول/i.test(t)) return 'vehicle';
    return null;
}

export type ExecutorResolutionKind = 'approved' | 'rejected' | 'alternative';

export type AlternativeLegalActionId =
    | 'inventory_only'
    | 'defer_execution'
    | 'police_escort'
    | 'salary_garnishment_instead'
    | 'field_visit_reschedule'
    | 'other';

export const ALTERNATIVE_LEGAL_ACTION_LABELS: Record<AlternativeLegalActionId, string> = {
    inventory_only: 'إجراء مقتصر على محضر جرد أثاث',
    defer_execution: 'تأجيل مؤقت للتنفيذ الميداني',
    police_escort: 'طلب تعزيز قوة إجرائية (شرطة)',
    salary_garnishment_instead: 'تحويل المسار إلى حجز راتب بدلاً من الطلب الأصلي',
    field_visit_reschedule: 'إعادة جدولة الموعد الميداني',
    other: 'إجراء آخر (يُفصَّل في المحضر)',
};

/** صف قرار يُمرَّر لمسار المنفذ — بدون فهرس نصي حتى يقبل `Decision` من الواجهة */
export interface DecisionRowInput {
    id?: string;
    title?: string;
    body?: string;
    date?: string;
    requestKind?: string;
    evictionWorkflowKey?: string;
    creditorPartyDeathPayloadJson?: string;
}

/**
 * وسيط قرارات منفذ العدل: يحدّث التخزين المحلي، يحقن السجل الزمني (محضر المتابعة)،
 * ويطبّق آثاراً جانبية على ملف التنفيذ حسب نوع الطلب.
 */
export function useDecisionDispatcher(params: {
    executionId: string | undefined;
    executionData: ExecutionFile | null;
    seizedAssets: SeizedAsset[];
    /** مسودات حجز قبل موافقة المنفذ — مفتاحها معرّف صف القرار */
    seizureDraftsByDecisionId?: Record<string, SeizedAsset>;
    persistExecutionMerge: (patch: Record<string, unknown>) => void;
    pushTimeline: (e: TimelineEvent, opts?: { mergePatch?: Record<string, unknown> }) => void;
    nextTimelineId: () => string;
    /** لقطة إضبارة عند تسجيل قرار المنفذ في السجل */
    getTimelineSnapshot?: () => unknown;
    /** مزامنة حالة المحجوزات في الواجهة بعد الدمج */
    syncSeizedAssets?: (assets: SeizedAsset[]) => void;
    syncSeizureDrafts?: (drafts: Record<string, SeizedAsset>) => void;
    syncActiveCoerciveActions?: (actions: string[]) => void;
    evictionExecutorWorkflow?: { dossierId: string; actions: ExecutorApprovalActions };
}) {
    const resolveDecision = useCallback(
        (input: {
            row: DecisionRowInput;
            resolution: ExecutorResolutionKind;
            executorNote?: string;
            alternativeActionId?: AlternativeLegalActionId;
        }) => {
            const id = String(input.row.id ?? '');
            if (!id) return;

            const today = getLocalTodayYmd();
            const ts = new Date().toISOString();
            const noteTrim = (input.executorNote || '').trim();
            const route = inferExecutorDispatcherRoute(input.row as Record<string, unknown>);
            const titleBase = String(input.row.title || 'طلب للمنفذ');
            const titleClean = stripPendingLabelsFromExecutorSubject(titleBase);

            const patchRow: Record<string, unknown> = {
                executorOutcome:
                    input.resolution === 'alternative'
                        ? 'alternative'
                        : input.resolution === 'approved'
                          ? 'approved'
                          : 'rejected',
                executorNote: noteTrim || undefined,
                resolvedAt: ts,
            };

            /** بعد الموافقة أو البديل: يبقى الطعن ممكناً للطرف المقابل ضمن المهلة (4/8 أيام) */
            if (input.resolution === 'approved' || input.resolution === 'alternative') {
                patchRow.appealStatus = 'pending';
                patchRow.appealBaseBranch = 'after_approval';
            } else if (input.resolution === 'rejected') {
                patchRow.appealStatus = 'pending';
                patchRow.appealBaseBranch = 'after_rejection';
                patchRow.date = today;
            } else {
                patchRow.appealStatus = 'pending';
            }

            if (input.resolution === 'approved' || input.resolution === 'alternative') {
                patchRow.status = 'accepted';
            } else {
                patchRow.status = 'rejected';
            }
            patchRow.appealPhase = null;

            const pcSubtypeEarly = String(
                (input.row as { personalCoerciveSubtype?: string }).personalCoerciveSubtype || ''
            ).trim();
            if (
                String(input.row.requestKind || '') === 'personal_coercive' &&
                (pcSubtypeEarly === 'executive_detention' ||
                    pcSubtypeEarly === 'executive_dossier_presentation') &&
                input.resolution === 'approved'
            ) {
                patchRow.appealStatus = 'final';
                patchRow.noAppealChosen = true;
                patchRow.executorDetentionHandedToJudge = true;
            }

            if (input.resolution === 'alternative') {
                const aid = (input.alternativeActionId ?? 'other') as AlternativeLegalActionId;
                patchRow.alternativeActionId = aid;
                patchRow.alternativeActionLabel =
                    noteTrim && aid === 'other'
                        ? 'قرار بديل'
                        : ALTERNATIVE_LEGAL_ACTION_LABELS[aid];
            }

            patchExecutorDecisionRowReliable(params.executionId, id, patchRow);

            const trimmedBody = String(input.row.body || '').trim();
            let timelineTitle = '';
            let timelineDescription: string | undefined;
            if (input.resolution === 'approved') {
                timelineTitle = `✅ موافقة المنفذ: ${titleClean || titleBase}`;
                timelineDescription = noteTrim ? noteTrim : undefined;
            } else if (input.resolution === 'rejected') {
                timelineTitle = `❌ رفض الطلب: ${titleClean || titleBase}`;
                timelineDescription = noteTrim ? noteTrim : undefined;
            } else {
                const altLabel =
                    input.alternativeActionId != null
                        ? ALTERNATIVE_LEGAL_ACTION_LABELS[input.alternativeActionId]
                        : '—';
                timelineTitle = `🔄 قرار بديل: ${titleClean || titleBase}`;
                timelineDescription = [noteTrim || undefined, `البديل: ${altLabel}`]
                    .filter(Boolean)
                    .join('\n');
            }

            const snap = params.getTimelineSnapshot?.();
            params.pushTimeline({
                id: params.nextTimelineId(),
                date: today,
                timestamp: ts,
                title: timelineTitle,
                description: timelineDescription,
                type: 'decision',
                source: 'القرارات والطعون',
                metadata: {
                    timelineThreadKey: `executor_decision:${id}`,
                    decisionRowId: id,
                    originalRequestBody: trimmedBody ? trimmedBody.slice(0, 8000) : undefined,
                    executorResolution: input.resolution,
                },
                ...(snap !== undefined ? { snapshot: snap } : {}),
            });

            const merge: Record<string, unknown> = {};

            if (input.resolution === 'approved') {
                if (route === 'Notification') {
                    merge.executor_coercive_unlock = true;
                }
                if (route === 'BreakLocks') {
                    const placeholder: SeizedAsset = {
                        id: `inv_${id}_${Date.now()}`,
                        type: 'movable',
                        description: 'محضر جرد أثاث — مسودة (بعد كسر الأقفال)',
                        status: 'pending',
                        seizureDate: today,
                        notes: 'أُنشئ تلقائياً بعد موافقة المنفذ على طلب كسر الأقفال/الجرد الميداني',
                        details: { origin: 'break_locks_approved', decisionId: id },
                    };
                    const nextAssets = [...params.seizedAssets, placeholder];
                    merge.seizedAssets = nextAssets;
                    params.syncSeizedAssets?.(nextAssets);
                }
                if (isGuarantorRequestDecisionRow(input.row as Record<string, unknown>)) {
                    const prevGf = params.executionData?.guarantor_followup;
                    merge.hasGuarantor = true;
                    merge.guarantor_followup = {
                        executor_approved: true,
                        channel: 'financial',
                        details_saved: false,
                        guarantor_name: prevGf?.guarantor_name,
                        guarantor_workplace: prevGf?.guarantor_workplace,
                        guarantor_salary_iqd: prevGf?.guarantor_salary_iqd ?? null,
                        guarantor_deduction_iqd: prevGf?.guarantor_deduction_iqd ?? null,
                        creditor_notation_registered: prevGf?.creditor_notation_registered === true,
                    };
                    const debtors = params.executionData?.debtors;
                    if (Array.isArray(debtors) && debtors.length > 0 && debtors[0]) {
                        merge.debtors = [
                            { ...debtors[0], hasGuarantor: true },
                            ...debtors.slice(1),
                        ];
                    }
                    const creditors = params.executionData?.creditors;
                    if (Array.isArray(creditors) && creditors.length > 0 && creditors[0]) {
                        merge.creditors = [
                            { ...creditors[0], guarantorExecutionNotation: true },
                            ...creditors.slice(1),
                        ];
                    }
                }

                if (input.row.requestKind === 'creditor_party_death') {
                    const row = input.row as DecisionRowInput;
                    const explicit = String(row.creditorPartyDeathPayloadJson || '').trim();
                    const body = String(row.body || '').trim();
                    const title = String(row.title || '').trim();
                    const id = String(row.id || '').trim();
                    const deathTitleLikely =
                        /وفاة\s*الدائن|إبلاغ\s*وفاة\s*الدائن|إحلال\s*الورثة\s*محل\s*الدائن|دون\s*ورثة/i.test(
                            title
                        );
                    const deathIdLikely = /^creditor_death_req_/i.test(id);
                    const raw = explicit || (deathTitleLikely || deathIdLikely ? body : '');
                    const parsed = raw ? parseCreditorPartyDeathPayload(raw) : null;
                    if (parsed) {
                        const incomingHeirs = parsed.heir_names.filter((s) => /\S/.test(String(s)));
                        if (parsed.action === 'heir_substitution' && incomingHeirs.length === 0) {
                            Object.assign(
                                merge,
                                buildExecutionMergeForCreditorHeirSubstitutionApproval(
                                    params.executionData,
                                    parsed.creditorNameSnapshot
                                )
                            );
                        } else {
                            Object.assign(
                                merge,
                                buildExecutionMergeForCreditorPartyDeath(params.executionData, parsed)
                            );
                        }
                    }
                }

                if (route === 'SalaryGarnishment') {
                    merge.salary_garnishment_installment_schedule = {
                        executionDecisionId: id,
                        monthlyAmountIqd: undefined,
                        startDate: today,
                        notes: noteTrim || 'مبدئي — أكمل بيانات الجدول من إدارة الأموال والمصاريف',
                        createdAt: ts,
                    };
                    try {
                        window.dispatchEvent(
                            new CustomEvent('hami-garnishment-schedule-init', {
                                detail: { executionId: params.executionId, decisionId: id },
                            })
                        );
                    } catch {
                        /* ignore */
                    }
                }

                if (
                    params.evictionExecutorWorkflow &&
                    input.row.requestKind === 'eviction_procedure'
                ) {
                    const branch = inferExecutorApprovalDecisionType({
                        title: String(input.row.title || ''),
                        requestKind: input.row.requestKind,
                        evictionWorkflowKey: input.row.evictionWorkflowKey as
                            | EvictionExecutorWorkflowKey
                            | undefined,
                    });
                    if (branch === 'Residential Grace Early End') {
                        Object.assign(
                            merge,
                            buildResidentialGraceEarlyEndApprovalMerge(params.executionData)
                        );
                        dispatchResidentialGraceCleared(String(params.executionId || ''));
                    }
                    if (branch !== 'other') {
                        handleExecutorApproval(
                            branch,
                            params.evictionExecutorWorkflow.dossierId,
                            id,
                            params.evictionExecutorWorkflow.actions,
                            { requestTitle: titleBase }
                        );
                    }
                }
            }

            if (input.resolution === 'alternative') {
                const taskId = `alt_dec_${Date.now()}`;
                const label =
                    noteTrim && (input.alternativeActionId ?? 'other') === 'other'
                        ? 'قرار بديل'
                        : input.alternativeActionId
                          ? ALTERNATIVE_LEGAL_ACTION_LABELS[input.alternativeActionId]
                          : 'إجراء بديل';
                const pending = params.executionData?.caseTasksPending ?? [];
                merge.caseTasksPending = [
                    ...pending,
                    {
                        id: taskId,
                        title: `متابعة قرار بديل: ${label}`,
                        body: `بُدِّل المسار عن الطلب «${titleClean || titleBase}».${noteTrim ? `\n\nنص القرار:\n${noteTrim}` : ''}`,
                        dueDate: today,
                        createdAt: ts,
                    },
                ];
            }

            if (String(input.row.requestKind || '') === 'seizure') {
                const drafts: Record<string, SeizedAsset> = {
                    ...(params.seizureDraftsByDecisionId || {}),
                };
                const draft = drafts[id];

                const bumpCoerciveForDraft = (asset: SeizedAsset) => {
                    const key = coerciveKeyForSeizureDraft(asset);
                    if (!key) return;
                    const prev = params.executionData?.activeCoerciveActions ?? [];
                    const ac = Array.isArray(prev) ? [...prev] : [];
                    if (!ac.includes(key)) {
                        ac.push(key);
                        merge.activeCoerciveActions = ac;
                        params.syncActiveCoerciveActions?.(ac);
                    }
                };

                if (input.resolution === 'approved' && draft) {
                    const baseType = baseSeizureLabelFromType(String(draft.type));
                    const promoted: SeizedAsset = {
                        ...draft,
                        type: `${baseType} — موافقة المنفذ`,
                        status: 'seized',
                        seizureDate: draft.seizureDate || today,
                    };
                    delete drafts[id];
                    const nextAssets = [...params.seizedAssets, promoted];
                    merge.seizedAssets = nextAssets;
                    merge.seizureDraftsByDecisionId = drafts;
                    params.syncSeizedAssets?.(nextAssets);
                    params.syncSeizureDrafts?.(drafts);
                    bumpCoerciveForDraft(draft);
                } else if (draft && (input.resolution === 'rejected' || input.resolution === 'alternative')) {
                    delete drafts[id];
                    merge.seizureDraftsByDecisionId = drafts;
                    params.syncSeizureDrafts?.(drafts);
                }

                const skipLegacyMap = input.resolution === 'approved' && Boolean(draft);
                if (!skipLegacyMap) {
                    const nextAssets = params.seizedAssets.map((asset) => {
                        const link = asset.details?.decisionRowId;
                        if (!link || String(link) !== id) return asset;
                        const t = String(asset.type);
                        const baseType = baseSeizureLabelFromType(t);
                        if (input.resolution === 'approved') {
                            return {
                                ...asset,
                                type: `${baseType} — موافقة المنفذ`,
                                status: 'seized',
                                seizureDate: asset.seizureDate || today,
                            };
                        }
                        if (input.resolution === 'rejected') {
                            return {
                                ...asset,
                                type: `${baseType} — رفض الطلب`,
                                status: 'pending',
                            };
                        }
                        return {
                            ...asset,
                            type: `${baseType} — قرار بديل`,
                            status: 'pending',
                        };
                    });
                    const changed = nextAssets.some((a, i) => a !== params.seizedAssets[i]);
                    if (changed) {
                        merge.seizedAssets = nextAssets;
                        params.syncSeizedAssets?.(nextAssets);
                    }
                }
            }

            if (String(input.row.requestKind || '') === 'personal_coercive') {
                const pcSubtype = String(
                    (input.row as { personalCoerciveSubtype?: string }).personalCoerciveSubtype || ''
                ).trim() as PersonalCoerciveSubtype;
                if (pcSubtype) {
                    const pcMerge = buildPersonalCoerciveExecutionMerge({
                        subtype: pcSubtype,
                        resolution: input.resolution,
                        decisionId: id,
                    });
                    Object.assign(merge, pcMerge);
                    applyPersonalCoerciveExecutorOutcome({
                        executionId: params.executionId,
                        subtype: pcSubtype,
                        resolution: input.resolution,
                        decisionId: id,
                    });
                }
            }

            if (Object.keys(merge).length > 0) {
                params.persistExecutionMerge(merge);
            }

            try {
                const rk = String(input.row.requestKind || '');
                const requestKindForEvent =
                    rk ||
                    (isGuarantorRequestDecisionRow(input.row as Record<string, unknown>)
                        ? 'guarantor_request'
                        : undefined);
                const pcSubtype = String(
                    (input.row as { personalCoerciveSubtype?: string }).personalCoerciveSubtype || ''
                ).trim();
                window.dispatchEvent(
                    new CustomEvent('hami-execution-decision-outcome', {
                        detail: {
                            executionId: params.executionId,
                            decisionId: id,
                            requestKind: requestKindForEvent,
                            outcome: patchRow.executorOutcome,
                            dispatcherRoute: route,
                            resolution: input.resolution,
                            ...(pcSubtype ? { personalCoerciveSubtype: pcSubtype } : {}),
                        },
                    })
                );
            } catch {
                /* ignore */
            }
        },
        [
            params.executionId,
            params.executionData,
            params.evictionExecutorWorkflow,
            params.persistExecutionMerge,
            params.pushTimeline,
            params.nextTimelineId,
            params.seizedAssets,
            params.seizureDraftsByDecisionId,
            params.syncSeizedAssets,
            params.syncSeizureDrafts,
            params.syncActiveCoerciveActions,
            params.getTimelineSnapshot,
        ]
    );

    return { resolveDecision, alternativeLabels: ALTERNATIVE_LEGAL_ACTION_LABELS };
}

import { useCallback } from 'react';
import type { FileData } from '@/app/components/lawyer/LawyerShared';
import type { ExecutionFile } from '@/app/components/lawyer/LawyerDashboardParts/types';
import {
    applyLawsuitArchive,
    applyLawsuitHardDeleteFilter,
    applyLawsuitPermanentDelete,
    applyLawsuitRestoreFromArchive,
    applyLawsuitRestoreFromTrash,
    applyLawsuitSoftDelete,
    applyLawsuitTrash,
    findLawsuitFile,
    persistLawsuitFiles,
} from '@/app/domain/lawsuit/lawsuitFilesRepository';
import {
    pruneOrphanedBridgeEvents,
    removeAllBridgedEventsForEntity,
    syncLawsuitFileToCalendar,
} from '@/app/services/calendar/dossierSyncLazy';
import { resolveCalendarUserId } from '@/app/services/calendar/bridge/lite';

type ActiveFile = FileData | ExecutionFile | null;

type UseLawsuitFileMutationsOptions = {
    files: FileData[];
    setFiles: React.Dispatch<React.SetStateAction<FileData[]>>;
    setActiveFile: React.Dispatch<React.SetStateAction<ActiveFile>>;
    userId?: string | null;
    authUserId?: string | null;
    refreshAppAlerts: () => void | Promise<void>;
    showLawsuitsWorkspace: boolean;
    unpinWorkspaceForDeletedFile: (file: FileData) => void;
};

export function useLawsuitFileMutations({
    files,
    setFiles,
    setActiveFile,
    userId,
    authUserId,
    refreshAppAlerts,
    unpinWorkspaceForDeletedFile,
}: UseLawsuitFileMutationsOptions) {
    const calendarUid = resolveCalendarUserId(userId ?? authUserId ?? null);

    const moveLawsuitToTrash = useCallback(
        (fileId: string | number) => {
            const idStr = String(fileId);
            setFiles((prev) => {
                const next = persistLawsuitFiles(applyLawsuitTrash(prev, fileId));
                return next;
            });
            setActiveFile((cur) => (cur && String(cur.id) === idStr ? null : cur));
            void removeAllBridgedEventsForEntity('lawsuit', fileId, calendarUid);
            void pruneOrphanedBridgeEvents(calendarUid);
            void refreshAppAlerts();
        },
        [calendarUid, refreshAppAlerts, setActiveFile, setFiles],
    );

    const restoreLawsuitFromTrash = useCallback(
        (fileId: string | number) => {
            setFiles((prev) => {
                const next = applyLawsuitRestoreFromTrash(prev, fileId);
                persistLawsuitFiles(next);
                const restored = findLawsuitFile(next, fileId);
                if (restored) {
                    syncLawsuitFileToCalendar(restored as unknown as Record<string, unknown>, userId);
                }
                return next;
            });
        },
        [setFiles, userId],
    );

    const archiveLawsuit = useCallback(
        (fileId: string | number) => {
            const idStr = String(fileId);
            setFiles((prev) => persistLawsuitFiles(applyLawsuitArchive(prev, fileId)));
            setActiveFile((cur) => (cur && String(cur.id) === idStr ? null : cur));
            void removeAllBridgedEventsForEntity('lawsuit', fileId, calendarUid);
            void pruneOrphanedBridgeEvents(calendarUid);
            void refreshAppAlerts();
        },
        [calendarUid, refreshAppAlerts, setActiveFile, setFiles],
    );

    const restoreArchivedLawsuit = useCallback(
        (fileId: string | number) => {
            setFiles((prev) => {
                const next = applyLawsuitRestoreFromArchive(prev, fileId);
                persistLawsuitFiles(next);
                const restored = findLawsuitFile(next, fileId);
                if (restored) {
                    syncLawsuitFileToCalendar(restored as unknown as Record<string, unknown>, userId);
                }
                return next;
            });
        },
        [setFiles, userId],
    );

    const permanentlyDeleteLawsuits = useCallback(
        (ids: Array<string | number>) => {
            const idSet = new Set(ids.map(String));
            idSet.forEach((id) => {
                void removeAllBridgedEventsForEntity('lawsuit', id, userId);
            });
            setFiles((prev) => persistLawsuitFiles(applyLawsuitPermanentDelete(prev, ids)));
            setActiveFile((cur) => (cur && idSet.has(String(cur?.id)) ? null : cur));
            void pruneOrphanedBridgeEvents(userId);
        },
        [setActiveFile, setFiles, userId],
    );

    /** لا حذف تلقائي من سلة المهملات — فقط حذف دائم بقرار المستخدم */

    const handleDeleteFile = useCallback(
        (fileToDelete: FileData) => {
            const isHardDelete = fileToDelete.status === 'deleted';
            if (isHardDelete) {
                void removeAllBridgedEventsForEntity('lawsuit', fileToDelete.id, userId);
                setFiles((prev) => persistLawsuitFiles(applyLawsuitHardDeleteFilter(prev, fileToDelete.id)));
            } else {
                const updated = applyLawsuitSoftDelete(fileToDelete);
                setFiles((prev) =>
                    persistLawsuitFiles(prev.map((f) => (f.id === fileToDelete.id ? updated : f))),
                );
                void removeAllBridgedEventsForEntity('lawsuit', fileToDelete.id, userId);
            }
            unpinWorkspaceForDeletedFile(fileToDelete);
            void refreshAppAlerts();
        },
        [refreshAppAlerts, setFiles, unpinWorkspaceForDeletedFile, userId],
    );

    const handleRestoreFile = useCallback(
        (fileToRestore: FileData) => {
            const updated: FileData = { ...fileToRestore, status: 'active', deletedAt: undefined };
            setFiles((prev) =>
                persistLawsuitFiles(prev.map((f) => (f.id === fileToRestore.id ? updated : f))),
            );
            setActiveFile(updated);
            void refreshAppAlerts();
        },
        [refreshAppAlerts, setActiveFile, setFiles],
    );

    return {
        moveLawsuitToTrash,
        restoreLawsuitFromTrash,
        archiveLawsuit,
        restoreArchivedLawsuit,
        permanentlyDeleteLawsuits,
        handleDeleteFile,
        handleRestoreFile,
    };
}

import { useCallback } from 'react';
import type { Dispatch, SetStateAction } from 'react';
import type { SecretaryAlert } from '@/app/services/SecretaryOrchestrator';
import { resolveAlertNavigation } from '@/app/services/alertNavigation';
import { parseWorkspaceRoute } from '@/app/workspace/workspaceRoutes';
import { SmartToast } from '@/app/components/ui/SmartToast';
import type { FileData } from '@/app/components/lawyer/LawyerShared';
import type { ExecutionFile } from '@/app/components/lawyer/LawyerDashboardParts/types';
import type { LawyerArchiveOverlay } from '@/app/hooks/useLawyerExecutionFiles';
import type { LawyerDashboardTab } from '@/app/hooks/lawyerDashboard/lawyerDashboardNav';
import type { OpenCriminalCaseOptions } from '@/app/hooks/lawyerDashboard/lawyerDashboardNav';
import {
    coerceActiveFileTarget,
    coerceExecutionFilePreserveId,
    isFileData,
    isRecord,
} from '@/app/components/lawyer/LawyerDashboardParts/utils';
import { openExecutionDossierWithContract } from '@/app/runtime/executionOpenContract';
import { openLawsuitDossierWithContract } from '@/app/runtime/lawsuitOpenContract';
import { isRealSignedIn } from '@/app/services/auth/shellAuth';

import { getQuantumPendingSnapshot } from '@/app/utils/quantumTasksMetrics';

import type { OpenNotepadOptions } from '@/app/hooks/lawyerDashboard/useLawyerDashboardRepository';

function prefetchArchivePortalIntent() {
    void import('@/app/utils/lazyComponentsIntent')
        .then((m) => m.prefetchArchivePortal())
        .catch(() => undefined);
}

function warmExecutionWorkspaceIntent() {
    void import('@/app/utils/lazyComponentsIntent')
        .then((m) => m.warmExecutionWorkspace())
        .catch(() => undefined);
}

export type UseLawyerDashboardNavigationParams = {
    userId: string | null;
    files: FileData[];
    executionFiles: ExecutionFile[];
    setActiveTab: Dispatch<SetStateAction<LawyerDashboardTab>>;
    setShowCommunity: Dispatch<SetStateAction<boolean>>;
    setCommunityDeepLink: Dispatch<
        SetStateAction<{ postId?: string; openComments?: boolean } | null>
    >;
    setArchiveType: Dispatch<SetStateAction<LawyerArchiveOverlay>>;
    setActiveFile: Dispatch<SetStateAction<FileData | ExecutionFile | null>>;
    setShowNotifications: Dispatch<SetStateAction<boolean>>;
    openNotepad: (opts?: OpenNotepadOptions) => void;
    setTransactionsFocusId: Dispatch<SetStateAction<string | undefined>>;
    openUrgentInLawsuitsWorkspace: (caseId?: string) => void;
    openVaultModal: (opts?: { scanner?: boolean }) => void;
    openTransactionsHub: (focusId?: string) => void;
    openCommunityTab: () => void;
    openFieldTasksSheet: () => void;
    openScheduleTab: (opts?: { date?: string; eventId?: string }) => void;
    openCriminalCase: (caseId: string, options?: OpenCriminalCaseOptions) => void;
    openTasksManager: (focusTaskId?: string) => void;
};

export function useLawyerDashboardNavigation({
    userId,
    files,
    executionFiles,
    setActiveTab,
    setShowCommunity,
    setCommunityDeepLink,
    setArchiveType,
    setActiveFile,
    setShowNotifications,
    openNotepad,
    setTransactionsFocusId,
    openUrgentInLawsuitsWorkspace,
    openVaultModal,
    openTransactionsHub,
    openCommunityTab,
    openFieldTasksSheet,
    openScheduleTab,
    openCriminalCase,
    openTasksManager,
}: UseLawyerDashboardNavigationParams) {
    const handleNotificationRouting = useCallback(
        (path: string, payload: Record<string, unknown> | null) => {
            if (path === 'schedule') {
                openScheduleTab();
                return;
            }
            if (path === 'case_details') {
                const caseId = payload && typeof payload.caseId === 'string' ? payload.caseId : null;
                if (caseId) {
                    if (!isRealSignedIn(userId)) return;
                    const lawsuitTarget = files.find((f) => String(f.id) === caseId);
                    const executionTarget = executionFiles.find((f) => String(f.id) === caseId);
                    if (executionTarget) {
                        openExecutionDossierWithContract(() => {
                            setActiveFile(coerceExecutionFilePreserveId(executionTarget));
                        });
                        SmartToast.info(`جاري فتح القضية...`);
                    } else if (lawsuitTarget) {
                        openLawsuitDossierWithContract(() => {
                            setActiveFile(coerceActiveFileTarget(lawsuitTarget));
                        });
                        SmartToast.info(`جاري فتح القضية...`);
                    }
                } else {
                    setArchiveType('all');
                }
            } else if (path === 'community') {
                setShowCommunity(true);
                if (payload && typeof payload.postId === 'string') {
                    setCommunityDeepLink({ postId: payload.postId, openComments: false });
                }
            } else if (path === 'scan_document') {
                openVaultModal({ scanner: true });
            } else if (path === 'vault') {
                openVaultModal();
            }
        },
        [
            executionFiles,
            files,
            openVaultModal,
            setActiveFile,
            setActiveTab,
            setArchiveType,
            setCommunityDeepLink,
            setShowCommunity,
            userId,
        ],
    );

    const openSecretaryAlert = useCallback(
        (a: SecretaryAlert) => {
            void import('@/app/services/appAlertPushSync')
                .then((m) => m.markAlertSeenForPush(a.id))
                .catch(() => undefined);
            setShowNotifications(false);
            const nav = resolveAlertNavigation(a, {
                lawsuitFiles: files,
                fieldTasks: getQuantumPendingSnapshot(),
            });

            switch (nav.kind) {
                case 'tab':
                    if (nav.tab === 'community') {
                        openCommunityTab();
                    } else if (nav.tab === 'schedule') {
                        openScheduleTab();
                    } else {
                        setShowCommunity(false);
                        setActiveTab(nav.tab);
                    }
                    return;
                case 'notepad':
                    openNotepad({
                        mode: 'list',
                        focusNoteId:
                            nav.noteId ?? (a.entityId ? String(a.entityId) : undefined),
                    });
                    return;
                case 'client_requests':
                    setArchiveType('client_requests');
                    setActiveTab('home');
                    return;
                case 'transactions': {
                    const txId = nav.entityId ?? a.entityId;
                    if (txId) {
                        const txFile = files.find(
                            (file) => String(file.id) === String(txId) && file.type === 'transaction',
                        );
                        if (txFile && isFileData(txFile) && isRealSignedIn(userId)) {
                            openLawsuitDossierWithContract(() => setActiveFile(txFile));
                            return;
                        }
                        setTransactionsFocusId(String(txId));
                    }
                    openTransactionsHub();
                    return;
                }
                case 'threading_tx':
                    setActiveTab('home');
                    openTransactionsHub(nav.entityId);
                    return;
                case 'urgent_dashboard': {
                    const id = nav.entityId ?? (a.entityId != null ? String(a.entityId) : undefined);
                    openUrgentInLawsuitsWorkspace(id);
                    return;
                }
                case 'open_lawsuit': {
                    if (!isRealSignedIn(userId)) return;
                    const f = files.find((file) => String(file.id) === nav.entityId);
                    if (f && isFileData(f)) {
                        openLawsuitDossierWithContract(() => setActiveFile(f));
                        return;
                    }
                    SmartToast.info('لم يُعثر على إضبارة الدعوى — ربما نُقلت للأرشيف أو السلة');
                    return;
                }
                case 'open_execution': {
                    if (!isRealSignedIn(userId)) return;
                    const ex = executionFiles.find((file) => String(file.id ?? '') === nav.entityId);
                    if (ex) {
                        openExecutionDossierWithContract(() => {
                            setActiveFile(coerceExecutionFilePreserveId(ex));
                        });
                        return;
                    }
                    SmartToast.info('لم يُعثر على إضبارة التنفيذ');
                    return;
                }
                case 'open_criminal':
                    openCriminalCase(nav.entityId);
                    return;
                case 'open_field_tasks':
                    setActiveTab('home');
                    openFieldTasksSheet();
                    return;
                default:
                    return;
            }
        },
        [
            executionFiles,
            files,
            openCommunityTab,
            openCriminalCase,
            openFieldTasksSheet,
            openScheduleTab,
            openTransactionsHub,
            setActiveFile,
            setActiveTab,
            setArchiveType,
            openNotepad,
            setShowCommunity,
            setShowNotifications,
            setTransactionsFocusId,
            openUrgentInLawsuitsWorkspace,
            userId,
        ],
    );

    const navigateWorkspaceRoute = useCallback(
        (routePath: string) => {
            if (routePath === 'workspace:schedule:calendar') {
                openScheduleTab();
                return;
            }
            const parsed = parseWorkspaceRoute(routePath);
            if (!parsed) return;
            switch (parsed.type) {
                case 'hub': {
                    const section = parsed.id as 'lawsuit' | 'execution' | 'transaction';
                    if (section === 'transaction') {
                        openTransactionsHub();
                        return;
                    }
                    if (section === 'execution' || section === 'lawsuit') {
                        prefetchArchivePortalIntent();
                        if (section === 'execution') warmExecutionWorkspaceIntent();
                        setArchiveType(section);
                    }
                    return;
                }
                case 'lawsuit': {
                    if (!isRealSignedIn(userId)) return;
                    const f = files.find((file) => String(file.id) === parsed.id);
                    if (f && isFileData(f)) {
                        openLawsuitDossierWithContract(() => setActiveFile(f));
                        return;
                    }
                    SmartToast.info('لم يُعثر على إضبارة الدعوى');
                    return;
                }
                case 'execution': {
                    if (!isRealSignedIn(userId)) return;
                    const ex = executionFiles.find((file) => String(file.id ?? '') === parsed.id);
                    if (ex) {
                        openExecutionDossierWithContract(() => {
                            setActiveFile(coerceExecutionFilePreserveId(ex));
                        });
                        return;
                    }
                    SmartToast.info('لم يُعثر على إضبارة التنفيذ');
                    return;
                }
                case 'criminal':
                    openCriminalCase(parsed.id);
                    return;
                case 'urgent':
                    openUrgentInLawsuitsWorkspace(parsed.id);
                    return;
                case 'transaction': {
                    if (!isRealSignedIn(userId)) return;
                    const f = files.find((file) => String(file.id) === parsed.id);
                    if (f && isFileData(f)) {
                        openLawsuitDossierWithContract(() => setActiveFile(f));
                        return;
                    }
                    SmartToast.info('لم يُعثر على ملف المعاملة');
                    return;
                }
                case 'threading':
                    openTransactionsHub(parsed.id);
                    return;
                case 'notepad':
                    openNotepad({ mode: 'list', focusNoteId: parsed.id });
                    return;
                case 'task':
                    openTasksManager(parsed.id);
                    return;
                default:
                    return;
            }
        },
        [
            executionFiles,
            files,
            openCriminalCase,
            openScheduleTab,
            openTasksManager,
            openTransactionsHub,
            setActiveFile,
            setActiveTab,
            setArchiveType,
            openNotepad,
            openUrgentInLawsuitsWorkspace,
            userId,
        ],
    );

    return {
        handleNotificationRouting,
        openSecretaryAlert,
        navigateWorkspaceRoute,
    };
}

import { useCallback, useEffect, useRef, useState } from 'react';
import type { Dispatch, SetStateAction } from 'react';
import type { User } from '@supabase/supabase-js';
import { SmartToast } from '@/app/components/ui/SmartToast';
import { debug } from '@/app/utils/debug';
import { STORAGE_KEYS, PERSIST_DEBOUNCE_MS } from '@/app/utils/constants';
import { persistenceRepository } from '@/app/infrastructure/persistence/LocalStorageRepository';
import { useAutoSave } from '@/app/hooks/useAutoSave';
import { notesVault } from '@/app/data/NotesVault';
import {
    bidirectionalMerge,
    NOTES_VAULT_CHANGED,
    linkGlobalToVault,
    vaultIdForGlobal,
    unlinkGlobal,
} from '@/app/services/notesSyncBridge';
import { normalizeNotesList, dashboardNoteToCloudPayload } from '@/app/services/notesCloudAdapter';
import { saveGlobalNotesRaw } from '@/app/utils/globalNotesStorage';
import { invalidateRepositoryFeedCache } from '@/app/services/repository/repositoryFeedWarmCache';
import type { GlobalNote } from '@/app/components/lawyer/LawyerDashboardParts/types';
import type { FileData } from '@/app/components/lawyer/LawyerShared';
import { LAWYER_NOTES_EXTERNAL_UPDATE } from '@/app/services/notes/lawyerNotesExternalUpdateEvent';
import {
    filterDeletedGlobalNotes,
    markGlobalNoteDeleted,
} from '@/app/services/notes/globalNotesTombstones';

async function ensureSecureStoreReady(): Promise<void> {
    const m = await import('@/app/services/SecureStoreService');
    await m.default.ensurePersistedReady();
}

async function readNotesDossierBackup(uid: string): Promise<unknown> {
    const m = await import('@/app/services/dossierPersistence/dossierBackupStore');
    return m.readLatestDossierBackup('notes');
}

async function loadPersistenceRepository() {
    const m = await import('@/app/infrastructure/persistence/LocalStorageRepository');
    return m.persistenceRepository;
}

export type UseLawyerGlobalNotesParams = {
    localAutoSave: boolean;
    backgroundRuntimeEnabled: boolean;
    user: User | null;
    authUserId?: string | null;
    refreshAppAlerts: () => void;
    bumpSearchIndex: () => void;
    setFiles: Dispatch<SetStateAction<FileData[]>>;
    openNormalNewCaseModal: () => void;
    closeNotepad: () => void;
};

export function useLawyerGlobalNotes({
    localAutoSave,
    backgroundRuntimeEnabled,
    user,
    authUserId,
    refreshAppAlerts,
    bumpSearchIndex,
    setFiles,
    openNormalNewCaseModal,
    closeNotepad,
}: UseLawyerGlobalNotesParams) {
    const [globalNotes, setGlobalNotes] = useState<GlobalNote[]>(() => {
        const loaded = persistenceRepository.load<GlobalNote[]>(STORAGE_KEYS.LAWYER_NOTES);
        const normalized = Array.isArray(loaded) ? normalizeNotesList(loaded) : [];
        return filterDeletedGlobalNotes(normalized);
    });
    const bootstrapNotesRef = useRef(globalNotes);
    const [notesHydrated, setNotesHydrated] = useState(!backgroundRuntimeEnabled);
    const [notesBootSettled, setNotesBootSettled] = useState(!backgroundRuntimeEnabled);

    const resolveNotesUserId = useCallback(
        () => user?.id ?? authUserId ?? null,
        [user?.id, authUserId],
    );

    useAutoSave(
        STORAGE_KEYS.LAWYER_NOTES,
        globalNotes,
        PERSIST_DEBOUNCE_MS.HEAVY,
        localAutoSave,
        notesHydrated,
    );

    useEffect(() => {
        if (!backgroundRuntimeEnabled) {
            setNotesHydrated(true);
            setNotesBootSettled(true);
            return;
        }
        setNotesBootSettled(false);
        let cancelled = false;
        const uid = resolveNotesUserId();
        void (async () => {
            await ensureSecureStoreReady();
            const persistenceRepository = await loadPersistenceRepository();
            let loaded = persistenceRepository.load<GlobalNote[]>(STORAGE_KEYS.LAWYER_NOTES);
            if (!loaded?.length) {
                const backup = (await readNotesDossierBackup(uid ?? '')) as {
                    payload?: unknown[];
                } | null;
                if (backup?.payload?.length) {
                    loaded = filterDeletedGlobalNotes(normalizeNotesList(backup.payload), uid);
                    if (loaded.length) {
                        persistenceRepository.save(STORAGE_KEYS.LAWYER_NOTES, loaded);
                    }
                }
            }
            if (cancelled) return;
            const normalizedLoaded = Array.isArray(loaded) ? normalizeNotesList(loaded) : [];
            const filteredLoaded = filterDeletedGlobalNotes(normalizedLoaded, uid);
            setGlobalNotes((prev) =>
                prev === bootstrapNotesRef.current || prev.length === 0 ? filteredLoaded : prev,
            );
            setNotesHydrated(true);
        })();
        return () => {
            cancelled = true;
        };
    }, [backgroundRuntimeEnabled, resolveNotesUserId]);

    const mergeNotesStores = useCallback(
        (rawNotes?: unknown) => {
            const uid = resolveNotesUserId();
            if (!uid) return;
            notesVault.setUserScope(uid);
            setGlobalNotes((prev) => {
                const base = filterDeletedGlobalNotes(
                    rawNotes !== undefined ? normalizeNotesList(rawNotes) : prev,
                    uid,
                );
                const { mergedGlobal, mergedVault } = bidirectionalMerge(uid, base, notesVault.getNotes());
                const filteredGlobal = filterDeletedGlobalNotes(mergedGlobal, uid);
                notesVault.replaceAll(mergedVault);
                return filteredGlobal;
            });
        },
        [resolveNotesUserId],
    );

    useEffect(() => {
        notesVault.setUserScope(resolveNotesUserId());
    }, [resolveNotesUserId]);

    useEffect(() => {
        const uid = resolveNotesUserId();
        if (!backgroundRuntimeEnabled || !uid || !notesHydrated) {
            if (!uid || !backgroundRuntimeEnabled) setNotesBootSettled(true);
            return;
        }
        mergeNotesStores();
        setNotesBootSettled(true);
    }, [backgroundRuntimeEnabled, resolveNotesUserId, mergeNotesStores, notesHydrated]);

    useEffect(() => {
        const onExternalNotes = () => {
            const uid = resolveNotesUserId();
            void loadPersistenceRepository().then((persistenceRepository) => {
                const next = persistenceRepository.load<GlobalNote[]>(STORAGE_KEYS.LAWYER_NOTES) || [];
                setGlobalNotes(filterDeletedGlobalNotes(normalizeNotesList(next), uid));
            });
        };
        window.addEventListener(LAWYER_NOTES_EXTERNAL_UPDATE, onExternalNotes);
        return () => window.removeEventListener(LAWYER_NOTES_EXTERNAL_UPDATE, onExternalNotes);
    }, [resolveNotesUserId]);

    useEffect(() => {
        const onVaultChanged = () => {
            mergeNotesStores();
            void import('@/app/services/globalSearchLoad')
                .then((m) => m.invalidateGlobalSearchExtrasCache(resolveNotesUserId()))
                .catch(() => undefined);
            bumpSearchIndex();
        };
        window.addEventListener(NOTES_VAULT_CHANGED, onVaultChanged);
        return () => window.removeEventListener(NOTES_VAULT_CHANGED, onVaultChanged);
    }, [bumpSearchIndex, mergeNotesStores, resolveNotesUserId]);

    const handleSaveNote = useCallback(
        async (note: GlobalNote) => {
            const uid = resolveNotesUserId();
            const exists = globalNotes.some((n) => String(n.id) === String(note.id));

            let nextNotes: GlobalNote[] = [];
            setGlobalNotes((prev) => {
                const found = prev.find((n) => String(n.id) === String(note.id));
                const enriched: GlobalNote = {
                    ...note,
                    createdAtIso: note.createdAtIso ?? (found ? found.createdAtIso : new Date().toISOString()),
                };
                nextNotes = found
                    ? prev.map((n) => (String(n.id) === String(note.id) ? enriched : n))
                    : [...prev, enriched];
                if (localAutoSave && notesHydrated) {
                    void loadPersistenceRepository().then((persistenceRepository) => {
                        persistenceRepository.save(STORAGE_KEYS.LAWYER_NOTES, nextNotes);
                    });
                }
                saveGlobalNotesRaw(nextNotes);
                return nextNotes;
            });

            invalidateRepositoryFeedCache();

            const bodyPlain = (note.body || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
            if (uid && bodyPlain) {
                const mappedId = vaultIdForGlobal(uid, note.id);
                const vaultId = notesVault.syncFromGlobal(
                    uid,
                    { id: note.id, body: note.body, type: note.type },
                    !exists,
                    mappedId,
                );
                if (vaultId) linkGlobalToVault(uid, note.id, vaultId);
            }

            if (user) {
                try {
                    const { SupabaseService } = await import('@/app/services/SupabaseService');
                    await SupabaseService.saveGlobalNote(
                        dashboardNoteToCloudPayload(note),
                        exists ? { id: String(note.id) } : undefined,
                    );
                } catch (error) {
                    debug.error('[LawyerDashboard] ⚠️ Cloud note save failed:', error);
                }
            }

            void refreshAppAlerts();

            if (note.apptDate || note.reminder_at) {
                SmartToast.success('تم ربط الموعد بالتقويم');
            }

            if (note.linkedFileId && !note.repositoryInboxHidden) {
                setFiles((prevFiles) =>
                    prevFiles.map((f) => {
                        if (f.id !== note.linkedFileId) return f;
                        const newFileNote = {
                            id: Date.now() + Math.random(),
                            text: note.body,
                            meta: note.title,
                            stageCtx: f.currentStage || 'عام',
                            date: new Date().toLocaleDateString('ar-EG'),
                            apptDate: note.apptDate || note.reminder_at,
                            isPinned: note.isPinned,
                        };
                        return { ...f, notes: [newFileNote, ...f.notes] };
                    }),
                );
            }
        },
        [globalNotes, localAutoSave, notesHydrated, refreshAppAlerts, resolveNotesUserId, setFiles, user],
    );

    const handleDeleteNote = useCallback(
        async (id: string | number) => {
            const idStr = String(id);
            const uid = resolveNotesUserId();
            const note = globalNotes.find((n) => String(n.id) === idStr);
            const [{ parseVoiceNoteRef }, { deleteVoiceBlob }] = await Promise.all([
                import('@/app/services/voice/voiceNoteCodec'),
                import('@/app/services/voice/voiceNoteStorage'),
            ]);
            const voiceRef = parseVoiceNoteRef(note?.body);
            if (voiceRef) await deleteVoiceBlob(voiceRef);

            markGlobalNoteDeleted(uid, idStr);

            if (uid) {
                const vaultId = vaultIdForGlobal(uid, idStr);
                if (vaultId) notesVault.deleteNote(vaultId);
                // محاولة إضافية: ملاحظات vault بصيغة g_${id}
                notesVault.deleteNote(`g_${idStr}`);
                unlinkGlobal(uid, idStr);
            }
            setGlobalNotes((prev) => {
                const next = prev.filter((n) => String(n.id) !== idStr);
                if (localAutoSave && notesHydrated) {
                    void loadPersistenceRepository().then((persistenceRepository) => {
                        persistenceRepository.save(STORAGE_KEYS.LAWYER_NOTES, next);
                    });
                }
                saveGlobalNotesRaw(next);
                return next;
            });
            invalidateRepositoryFeedCache();
            void import('@/app/workspace/unpinWorkspaceEntity')
                .then((m) => m.unpinWorkspaceItem(idStr, 'notepad'))
                .catch(() => undefined);

            if (user) {
                try {
                    const { SupabaseService } = await import('@/app/services/SupabaseService');
                    await SupabaseService.deleteGlobalNote(idStr);
                } catch (error) {
                    debug.error('[LawyerDashboard] ⚠️ Cloud note delete failed:', error);
                }
            }
            void refreshAppAlerts();
        },
        [globalNotes, localAutoSave, notesHydrated, refreshAppAlerts, resolveNotesUserId, user],
    );

    const handleConvertNote = useCallback(() => {
        closeNotepad();
        openNormalNewCaseModal();
    }, [closeNotepad, openNormalNewCaseModal]);

    const handleNotepadConvert = useCallback(
        (_note: { text: string }) => {
            handleConvertNote();
        },
        [handleConvertNote],
    );

    return {
        globalNotes,
        setGlobalNotes,
        mergeNotesStores,
        resolveNotesUserId,
        notesBootSettled,
        handleSaveNote,
        handleDeleteNote,
        handleConvertNote,
        handleNotepadConvert,
    };
}

import { createThreadingId } from './ids';

function newTemplateId(): string {
    return createThreadingId('tpl');
}

export type TaskTemplateTask = {
  id: string;
  title: string;
  parentTaskId: string | null;
  deadline: string | null;
};

export type TaskTemplate = {
  id: string;
  name: string;
  createdAt: string;
  tasks: TaskTemplateTask[];
};

const STORAGE_KEY_PREFIX = 'hami:transactions:taskTemplates:v1:';

let memoryFallback: TaskTemplate[] = [];

function safeParseTemplates(raw: string | null): TaskTemplate[] {
  if (!raw) return [];
  try {
    const parsed: unknown = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    return parsed as TaskTemplate[];
  } catch {
    return [];
  }
}

function getStorageKey(userId: string) {
  return `${STORAGE_KEY_PREFIX}${userId}`;
}

function readTemplates(userId: string): TaskTemplate[] {
  if (typeof window === 'undefined' || !window?.localStorage) return memoryFallback;
  return safeParseTemplates(window.localStorage.getItem(getStorageKey(userId)));
}

function writeTemplates(userId: string, templates: TaskTemplate[]) {
  if (typeof window === 'undefined' || !window?.localStorage) {
    memoryFallback = templates;
    return;
  }
  window.localStorage.setItem(getStorageKey(userId), JSON.stringify(templates));
}

export function listTaskTemplates(userId: string): TaskTemplate[] {
  return readTemplates(userId).slice().sort((a, b) => b.createdAt.localeCompare(a.createdAt));
}

export function saveTaskTemplate(
  userId: string,
  input: { name: string; tasks: Omit<TaskTemplateTask, 'id'>[] } | { name: string; tasks: TaskTemplateTask[] },
) {
  const now = new Date().toISOString();
  const tasks = (input as any).tasks.map((t: any) => ({
    id: t.id ?? newTemplateId(),
    title: String(t.title ?? '').trim(),
    parentTaskId: t.parentTaskId ?? null,
    deadline: t.deadline ?? null,
  })) as TaskTemplateTask[];

  const next: TaskTemplate = {
    id: newTemplateId(),
    name: input.name.trim() || 'قالب بدون اسم',
    createdAt: now,
    tasks,
  };

  const templates = readTemplates(userId);
  writeTemplates(userId, [next, ...templates]);
  return next;
}

export function deleteTaskTemplate(userId: string, templateId: string) {
  const templates = readTemplates(userId).filter((t) => t.id !== templateId);
  writeTemplates(userId, templates);
}

