/**
 * الموجة الأخيرة — كل تبويبات محضر المتابعة + جسورها. بعدها لا يبقى أي chunk
 * بارد داخل قسم التنفيذ: فتح المحضر والتنقل بين تبويباته يصبح لحظياً.
 */
function prefetchExecutionFollowupFullWarm(): void {
    void import('@/app/components/lawyer/ExecutionDashboard/executionFollowupTabPrefetch')
        .then((m) => {
            m.prefetchAllExecutionFollowupTabs();
        })
        .catch(() => undefined);
}

/** يبدأ تحميل الـ chunk الرئيسي فقط — بدون منافسة أرشيف التنفيذ */
export function prefetchExecutionDashboardCore(): void {
    if (typeof window === 'undefined') return;
    prefetchDeferredFeatureStyles();
    void loadExecutionDashboardModule().catch(() => {
        executionModulePromise = null;
    });
}

/**
 * تسخين خفيف لمسار Instant (portal + first-paint) — بدون تحميل chunk التنفيذ الكامل.
 * يُستخدم من executionBootHydrator عند الإقلاع.
 */
export function prefetchExecutionDashboardChromeWarm(): void {
    if (typeof window === 'undefined') return;
    prefetchDeferredFeatureStyles();
    prefetchExecutionFirstPaintChunks();
    void import('@/app/components/lawyer/dashboard/ExecutionDashboardBootChrome').catch(() => undefined);
}

/**
 * deferred: بعد فتح قسم التنفيذ — لا يُشغَّل على مسار الفتح المباشر
 * intent: hover على بطاقة/الهَب — chunk رئيسي فوراً، shell عند الخمول
 * urgent: نقرة فتح إضبارة — chunk + shell الحرجة فوراً
 */
export function prefetchExecutionDashboardByMode(mode: ExecutionDashboardPrefetchMode): void {
    if (typeof window === 'undefined') return;

    switch (mode) {
        case 'deferred':
            scheduleIdleWork(() => {
                prefetchExecutionDashboardCore();
                void loadExecutionDashboardModule()
                    .then(() =>
                        scheduleIdleWork(() => {
                            prefetchExecutionShellChunks();
                            // سلسلة أول paint كاملة مع الـ shell — لا تنتظر موجة deep warm
                            prefetchExecutionFirstPaintChunks();
                            // موجة أخيرة idle — تجعل أول فتح فعلي بلا أي تحميل شبكة تقريباً
                            scheduleIdleWork(() => {
                                prefetchExecutionDeepWarmChunks();
                                scheduleIdleWork(() => prefetchExecutionFollowupFullWarm(), 700);
                            }, 600);
                        }, 500),
                    )
                    .catch(() => undefined);
            }, 800);
            break;
        case 'intent':
            // hover/دخول الأرشيف: النقرة تأتي عادة خلال أقل من ثانية —
            // كل ما يلزم لأول paint (core + shell + body + portal) يُحمَّل فوراً.
            prefetchExecutionDashboardCore();
            prefetchExecutionShellChunks();
            prefetchExecutionFirstPaintChunks();
            scheduleIdleWork(() => {
                prefetchExecutionDeepWarmChunks();
                scheduleIdleWork(() => prefetchExecutionFollowupFullWarm(), 600);
            }, 450);
            break;
        case 'urgent':
            // فتح مباشر: كل سلسلة أول paint بالتوازي فوراً — أي جزء مؤجَّل منها
            // كان يتحول لحلقة waterfall بعد النقرة (chrome يظهر والمحتوى ينتظر).
            prefetchExecutionDashboardCore();
            prefetchExecutionShellChunks();
            prefetchExecutionFirstPaintChunks();
            // تسخين عميق سريع بعد أول paint — محضر المتابعة/الجسور كانت تبقى باردة
            // عند الفتح المباشر ويشعر المستخدم بثقل أول نقرة داخل الإضبارة.
            scheduleIdleWork(() => {
                prefetchExecutionDeepWarmChunks();
                scheduleIdleWork(() => prefetchExecutionFollowupFullWarm(), 500);
            }, 250);
            break;
        default:
            break;
    }
}

let cachedExecutionModule: ExecutionDashboardModule | null = null;
let firstPaintReadyPromise: Promise<void> | null = null;
let firstPaintReady = false;

export function getCachedExecutionDashboard(): ExecutionDashboardModule | null {
    return cachedExecutionModule;
}

export function isExecutionDossierFirstPaintReady(): boolean {
    return firstPaintReady;
}

/**
 * ينتظر سلسلة أول paint حتى تكتمل — يُستدعى قبل setActiveFile حتى يصبح
 * أول فتح كالثاني (بلا BootChrome / PhoneBodyLoadingShell).
 */
export function ensureExecutionDossierFirstPaintReady(): Promise<void> {
    if (typeof window === 'undefined') return Promise.resolve();

    if (firstPaintReady) return Promise.resolve();

    if (!firstPaintReadyPromise) {
        firstPaintReadyPromise = (async () => {
            prefetchDeferredFeatureStyles();
            prefetchExecutionFirstPaintChunks();
            prefetchExecutionShellChunks();
            void loadExecutionDashboardModule()
                .then((mod) => {
                    cachedExecutionModule = mod;
                })
                .catch(() => {
                    executionModulePromise = null;
                });

            const [portalLazy, phoneLazy, baseScope, shell] = await Promise.all([
                import('@/app/components/lawyer/dashboard/executionDashboardPortalLazy'),
                import('@/app/components/lawyer/ExecutionDashboard/executionDashboardPhoneBodyLazy'),
                import(
                    '@/app/components/lawyer/ExecutionDashboard/hooks/executionDashboardCore/executionDashboardBaseScopeCache'
                ),
                import('@/app/components/lawyer/ExecutionDashboard/executionDashboardLazyShell'),
            ]);

            await Promise.all([
                portalLazy.LazyExecutionDashboardPortal.preload().catch(() => undefined),
                phoneLazy.LazyExecutionDashboardPhoneBody.preload().catch(() => undefined),
                baseScope.loadAndCacheExecutionDashboardBaseScopeBuilder().then(
                    () => undefined,
                    () => undefined,
                ),
                loadExecutionDashboardModule().then(
                    (mod) => {
                        cachedExecutionModule = mod;
                    },
                    () => undefined,
                ),
            ]);

            // ثبّت Resolved داخل Portal's LazyExecutionDashboard (نفس وحدة loadExecutionDashboardModule)
            await import('@/app/components/lawyer/dashboard/ExecutionDashboardPortal')
                .then((m) => m.prefetchExecutionDashboardComponent())
                .catch(() => undefined);

            firstPaintReady = true;
        })().catch(() => {
            firstPaintReadyPromise = null;
        });
    }

    return firstPaintReadyPromise ?? Promise.resolve();
}

export function primeExecutionDossierSurface(): void {
    if (typeof window === 'undefined') return;
    prefetchExecutionDashboardByMode('urgent');
    void ensureExecutionDossierFirstPaintReady();
}

/** كشف/إخفاء مركز الإعدادات فوراً في الـ DOM — مستقل عن إطار React */

const HOST_SELECTOR = '[data-testid="hami-settings-overlay-host"]';
const ROOT_SELECTOR = '[data-settings-root]';
const BRIDGE_ID = 'hami-settings-instant-bridge';
const CHROME = '#0B1021';
const INTERACT_CLASS = 'hami-settings-overlay-layer--interact';
const CLOSE_GUARD_ATTR = 'data-settings-close-guard';

/**
 * احتياطي قصير لحارس زر X إن لم يأتِ click إيماءة الفتح.
 * التسليح الأساسي فور pointerup+click — لا تأخير اصطناعي معتاد.
 */
export const SETTINGS_INTERACT_ARM_MS = 64;

let forceVisible = false;
/** ساعة كشف الطبقة في الـ DOM — قبل التزام React بـ open=true */
let revealedAtMs: number | null = null;
let prevThemeColor: string | null = null;
let interactArmCleanup: (() => void) | null = null;
/** يمنع إعادة فتح الإعدادات بنقرة إغلاق الشبحية (pointerdown يغلق → click يصيب الترس). */
let reopenSuppressedUntil = 0;
let reopenSuppressCleanup: (() => void) | null = null;
/**
 * حد أقصى لكبح إعادة الفتح — الضغطة المتبقية على الترس تُبتلع ثم تُرفع الكبح؛
 * المهلة احتياط إن لم يصل حدث ترس (كان 280ms فيجمّد التبديل السريع).
 */
export const SETTINGS_REOPEN_SUPPRESS_MS = 90;

const SETTINGS_GEAR_TRIGGER_SELECTOR = '[data-testid="header-settings-trigger"]';
let instantCloseHandler: (() => void) | null = null;

export function isSettingsForceVisible(): boolean {
    return forceVisible;
}

export function clearSettingsForceVisible(): void {
    forceVisible = false;
}

/** لحظة كشف الطبقة (DOM) — لساعة مهلة الإغلاق دون انتظار إطار React */
export function getSettingsShellRevealedAt(): number | null {
    return revealedAtMs;
}

function clearReopenSuppressListeners(): void {
    if (!reopenSuppressCleanup) return;
    reopenSuppressCleanup();
    reopenSuppressCleanup = null;
}

/**
 * كبح إعادة الفتح الشبحي بعد إغلاق حقيقي —
 * يبتلع pointerdown/click المتبقي على ترس الهيدر ثم يرفع الكبح؛ مهلة ≤90ms احتياط.
 */
export function suppressSettingsReopen(ms: number = SETTINGS_REOPEN_SUPPRESS_MS): void {
    const now = typeof performance !== 'undefined' ? performance.now() : Date.now();
    const duration = Math.max(0, ms);
    reopenSuppressedUntil = now + duration;
    clearReopenSuppressListeners();

    if (typeof window === 'undefined' || duration <= 0) return;

    const clear = () => {
        reopenSuppressedUntil = 0;
        clearReopenSuppressListeners();
    };

    const swallowGearGhost = (event: Event) => {
        const target = event.target;
        if (!(target instanceof Element)) return;
        if (!target.closest(SETTINGS_GEAR_TRIGGER_SELECTOR)) return;
        event.preventDefault();
        event.stopPropagation();
        if (typeof event.stopImmediatePropagation === 'function') {
            event.stopImmediatePropagation();
        }
        clear();
    };

    window.addEventListener('pointerdown', swallowGearGhost, true);
    window.addEventListener('click', swallowGearGhost, true);
    const fallbackTimer = window.setTimeout(clear, duration);

    reopenSuppressCleanup = () => {
        window.removeEventListener('pointerdown', swallowGearGhost, true);
        window.removeEventListener('click', swallowGearGhost, true);
        window.clearTimeout(fallbackTimer);
    };
}

export function isSettingsReopenSuppressed(): boolean {
    const now = typeof performance !== 'undefined' ? performance.now() : Date.now();
    return now < reopenSuppressedUntil;
}

export function clearSettingsReopenSuppress(): void {
    reopenSuppressedUntil = 0;
    clearReopenSuppressListeners();
}

/** يُسجَّل من useLawyerDashboardSettings — إغلاق فوري من DOM إن لزم */
export function registerSettingsInstantCloseHandler(handler: (() => void) | null): void {
    instantCloseHandler = handler;
}

export function isSettingsCloseGuarded(): boolean {
    if (typeof document === 'undefined') return false;
    return document.documentElement.hasAttribute(CLOSE_GUARD_ATTR);
}

function setCloseGuard(active: boolean): void {
    if (typeof document === 'undefined') return;
    if (active) document.documentElement.setAttribute(CLOSE_GUARD_ATTR, '1');
    else document.documentElement.removeAttribute(CLOSE_GUARD_ATTR);
}

export function hasSettingsOverlayHost(): boolean {
    if (typeof document === 'undefined') return false;
    return Boolean(document.querySelector(HOST_SELECTOR));
}

function resolveLayer(): HTMLElement | null {
    if (typeof document === 'undefined') return null;
    const host = document.querySelector(HOST_SELECTOR);
    if (host instanceof HTMLElement) return host;
    const bridge = document.getElementById(BRIDGE_ID);
    if (bridge instanceof HTMLElement) return bridge;
    const root = document.querySelector(ROOT_SELECTOR);
    return root instanceof HTMLElement ? root : null;
}

function applyThemeChrome(active: boolean): void {
    if (typeof document === 'undefined') return;
    let meta = document.querySelector('meta[name="theme-color"]');
    if (active) {
        if (!meta) {
            meta = document.createElement('meta');
            meta.setAttribute('name', 'theme-color');
            document.head.appendChild(meta);
        }
        if (prevThemeColor === null) {
            prevThemeColor = meta.getAttribute('content');
        }
        meta.setAttribute('content', CHROME);
        document.documentElement.style.backgroundColor = CHROME;
        document.body.style.backgroundColor = CHROME;
        return;
    }
    if (meta && prevThemeColor != null) {
        meta.setAttribute('content', prevThemeColor);
    }
    prevThemeColor = null;
    document.documentElement.style.backgroundColor = '';
    document.body.style.backgroundColor = '';
}

function clearInteractArmSchedule(): void {
    if (!interactArmCleanup) return;
    interactArmCleanup();
    interactArmCleanup = null;
}

export function isSettingsOverlayInteractionArmed(root?: HTMLElement | null): boolean {
    if (isSettingsCloseGuarded()) return false;
    const el = root ?? resolveLayer();
    return Boolean(el?.classList.contains(INTERACT_CLASS));
}

/** يسمح بالإغلاق بعد انتهاء إيماءة الفتح */
export function armSettingsOverlayInteraction(root?: HTMLElement | null): void {
    clearInteractArmSchedule();
    setCloseGuard(false);
    const el = root ?? resolveLayer();
    if (!el) return;
    el.classList.add(INTERACT_CLASS);
    el.style.setProperty('pointer-events', 'auto');
}

/** يمنع التفاعل (عند الإخفاء فقط — الطبقة الظاهرة تبقى قابلة للمس) */
export function disarmSettingsOverlayInteraction(root?: HTMLElement | null): void {
    clearInteractArmSchedule();
    setCloseGuard(false);
    const el = root ?? resolveLayer();
    if (!el) return;
    el.classList.remove(INTERACT_CLASS);
    if (!el.classList.contains('hami-settings-overlay-layer--visible')) {
        el.style.setProperty('pointer-events', 'none');
    }
}

/**
 * حارس إغلاق على زر X فقط (CSS) حتى ينتهي click إيماءة فتح الترس —
 * Host/Shell يعيدان الاستدعاء: لا تُعاد الجدولة.
 */
export function scheduleSettingsOverlayInteractionArm(root?: HTMLElement | null): void {
    const el = root ?? resolveLayer();
    if (!el) return;

    if (el.classList.contains(INTERACT_CLASS) && !isSettingsCloseGuarded()) return;
    if (interactArmCleanup) return;

    el.classList.remove(INTERACT_CLASS);
    el.style.setProperty('pointer-events', 'auto');
    setCloseGuard(true);

    if (typeof window === 'undefined') {
        armSettingsOverlayInteraction(el);
        return;
    }

    let settled = false;

    const cleanupListeners = () => {
        if (typeof window === 'undefined') return;
        window.removeEventListener('pointerup', onPointerEnd, true);
        window.removeEventListener('pointercancel', onPointerEnd, true);
        window.removeEventListener('click', swallowGhostClick, true);
        window.clearTimeout(fallbackTimer);
    };

    const armNow = () => {
        if (settled) return;
        settled = true;
        cleanupListeners();
        interactArmCleanup = null;
        armSettingsOverlayInteraction(el);
    };

    const swallowGhostClick = (event: Event) => {
        const target = event.target;
        if (
            target instanceof Element &&
            target.closest('[data-testid="settings-shell-close"]')
        ) {
            event.preventDefault();
            event.stopPropagation();
            if (typeof event.stopImmediatePropagation === 'function') {
                event.stopImmediatePropagation();
            }
        }
        armNow();
    };

    const onPointerEnd = () => {
        window.removeEventListener('pointerup', onPointerEnd, true);
        window.removeEventListener('pointercancel', onPointerEnd, true);
        window.addEventListener('click', swallowGhostClick, true);
    };

    window.addEventListener('pointerup', onPointerEnd, true);
    window.addEventListener('pointercancel', onPointerEnd, true);
    const fallbackTimer = window.setTimeout(armNow, SETTINGS_INTERACT_ARM_MS);

    interactArmCleanup = () => {
        settled = true;
        cleanupListeners();
        setCloseGuard(false);
        interactArmCleanup = null;
    };
}

function applyLayerVisible(root: HTMLElement, visible: boolean): void {
    if (visible) {
        root.style.setProperty('visibility', 'visible');
        root.style.setProperty('pointer-events', 'auto');
        root.style.setProperty('opacity', '1');
        root.style.setProperty('background-color', CHROME);
        root.classList.add('hami-settings-overlay-layer--visible');
        root.classList.remove(INTERACT_CLASS);
        root.setAttribute('data-open', 'true');
        root.removeAttribute('aria-hidden');
        root.removeAttribute('inert');
        revealedAtMs =
            typeof performance !== 'undefined' ? performance.now() : Date.now();
        applyThemeChrome(true);
    } else {
        clearInteractArmSchedule();
        setCloseGuard(false);
        root.style.setProperty('visibility', 'hidden');
        root.style.setProperty('pointer-events', 'none');
        root.style.setProperty('opacity', '0');
        root.classList.remove('hami-settings-overlay-layer--visible');
        root.classList.remove(INTERACT_CLASS);
        root.setAttribute('data-open', 'false');
        root.setAttribute('aria-hidden', 'true');
        root.setAttribute('inert', '');
        revealedAtMs = null;
        applyThemeChrome(false);
    }
}

/** إزالة جسر طلاء قديم إن وُجد (لم نعد نزرعه) */
export function removeSettingsInstantBridge(): void {
    if (typeof document === 'undefined') return;
    document.getElementById(BRIDGE_ID)?.remove();
}

/**
 * طلاء فوري: يكشف Host الحقيقي فقط — بلا جسر هيكل ملوّن.
 * إن لم يوجد Host يعيد false؛ المستدعي يركّب عبر flushSync ثم يعيد المحاولة.
 */
export function paintSettingsInstantChrome(): boolean {
    if (typeof document === 'undefined') return false;
    removeSettingsInstantBridge();

    const existingHost = document.querySelector(HOST_SELECTOR);
    if (!(existingHost instanceof HTMLElement)) return false;

    forceVisible = true;
    applyLayerVisible(existingHost, true);
    scheduleSettingsOverlayInteractionArm(existingHost);
    return true;
}

/** كشف طبقة الإعدادات الدافئة فوراً (قبل أي setState ثقيل) */
export function revealSettingsWarmShell(): boolean {
    return paintSettingsInstantChrome();
}

export type ConcealSettingsWarmShellOptions = {
    /**
     * كبح إعادة الفتح بعد إغلاق مستخدم حقيقي فقط.
     * الافتراضي false — وإلا priming (تركيب host مغلق) يبتلع click فتح الترس في نفس الإيماءة.
     */
    suppressReopen?: boolean;
};

/** إخفاء فوري للطبقة الدافئة (بدون كبح فتح افتراضياً) */
export function concealSettingsWarmShell(
    options: ConcealSettingsWarmShellOptions = {},
): void {
    forceVisible = false;
    if (options.suppressReopen) {
        suppressSettingsReopen();
    }
    const root = resolveLayer();
    if (root) applyLayerVisible(root, false);
    else {
        clearInteractArmSchedule();
        setCloseGuard(false);
        revealedAtMs = null;
        applyThemeChrome(false);
    }
    removeSettingsInstantBridge();
}

import { getOrCreateDeviceId } from '@/app/security/deviceId';
import { getBffCryptoWrapCredential } from '@/app/utils/bffCryptoSession';

const __DEV__ = import.meta.env.DEV;
const _log = (...a: unknown[]) => {
  if (__DEV__) console.warn(...a);
};
const _warn = (...a: unknown[]) => {
  if (__DEV__) console.warn(...a);
};
const _err = (...a: unknown[]) => {
  if (__DEV__) console.error(...a);
};

const SESSION_KEY_STORAGE_KEY = 'hami-crypto-session-key';
const DEVICE_KEY_STORAGE_KEY = 'hami-crypto-device-wrapped-key';
const KEY_SALT = 'hami-crypto-key-salt-v2';
const DEVICE_WRAP_PREFIX = 'hami-crypto-device:';
const CRYPTO_DB_NAME = 'hami-crypto-keystore';
const CRYPTO_DB_VERSION = 1;
const CRYPTO_KEY_STORE = 'crypto_keys';
const MASTER_KEY_RECORD_ID = 'master-key-v3';

async function getWrapCredential(): Promise<string | null> {
  try {
    const bffCredential = getBffCryptoWrapCredential();
    if (bffCredential) return bffCredential;

    // ديناميكي — يمنع سحب vendor-supabase (~200KB) إلى مسار الإقلاع عبر SecureStore
    const { supabase } = await import('@/app/lib/supabase-client');
    const { data } = await supabase.auth.getSession();
    return data.session?.access_token?.trim() ?? null;
  } catch {
    return null;
  }
}

function normalizeExplicitCredential(credential: string | undefined): string | null {
  const normalized = credential?.trim() ?? '';
  return normalized || null;
}

async function deriveWrappingKey(credential: string): Promise<CryptoKey> {
  const wrapInput = credential.startsWith('bff:')
    ? credential
    : `hami-crypto-wrap:${credential}`;
  const keyMaterial = await crypto.subtle.importKey(
    'raw',
    new TextEncoder().encode(wrapInput),
    { name: 'PBKDF2' },
    false,
    ['deriveKey']
  );
  return crypto.subtle.deriveKey(
    {
      name: 'PBKDF2',
      salt: new TextEncoder().encode(KEY_SALT),
      iterations: 600000,
      hash: 'SHA-256',
    },
    keyMaterial,
    { name: 'AES-KW', length: 256 },
    false,
    ['wrapKey', 'unwrapKey']
  );
}

function toBase64Url(data: ArrayBuffer): string {
  const bytes = new Uint8Array(data);
  let binary = '';
  const chunkSize = 0x8000;
  for (let i = 0; i < bytes.length; i += chunkSize) {
    binary += String.fromCharCode(...bytes.subarray(i, i + chunkSize));
  }
  return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/g, '');
}

function fromBase64Url(data: string): ArrayBuffer {
  const base64 = data.replace(/-/g, '+').replace(/_/g, '/');
  const padLen = (4 - (base64.length % 4)) % 4;
  const padded = base64 + '='.repeat(padLen);
  const binary = atob(padded);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return bytes.buffer;
}

export class CryptoService {
  private static masterKey: CryptoKey | null = null;
  private static isInitialized = false;
  private static sessionWrapCredential: string | null = null;

  private static openCryptoDatabase(): Promise<IDBDatabase | null> {
    if (typeof indexedDB === 'undefined') return Promise.resolve(null);
    return new Promise((resolve) => {
      const req = indexedDB.open(CRYPTO_DB_NAME, CRYPTO_DB_VERSION);
      req.onupgradeneeded = () => {
        const db = req.result;
        if (!db.objectStoreNames.contains(CRYPTO_KEY_STORE)) {
          db.createObjectStore(CRYPTO_KEY_STORE, { keyPath: 'id' });
        }
      };
      req.onsuccess = () => resolve(req.result);
      req.onerror = () => resolve(null);
      req.onblocked = () => resolve(null);
    });
  }

  private static async tryRestoreKeyFromPersistentStore(): Promise<boolean> {
    const db = await this.openCryptoDatabase();
    if (!db) return false;
    return new Promise((resolve) => {
      try {
        const tx = db.transaction(CRYPTO_KEY_STORE, 'readonly');
        const req = tx.objectStore(CRYPTO_KEY_STORE).get(MASTER_KEY_RECORD_ID);
        req.onsuccess = () => {
          const record = req.result as { key?: unknown } | undefined;
          if (record?.key instanceof CryptoKey) {
            this.masterKey = record.key;
            this.isInitialized = true;
            resolve(true);
            return;
          }
          resolve(false);
        };
        req.onerror = () => resolve(false);
        tx.oncomplete = () => db.close();
        tx.onerror = () => db.close();
        tx.onabort = () => db.close();
      } catch {
        db.close();
        resolve(false);
      }
    });
  }

  private static async persistKeyToPersistentStore(): Promise<void> {
    if (!this.masterKey) return;
    const db = await this.openCryptoDatabase();
    if (!db) return;
    await new Promise<void>((resolve) => {
      try {
        const tx = db.transaction(CRYPTO_KEY_STORE, 'readwrite');
        tx.objectStore(CRYPTO_KEY_STORE).put({
          id: MASTER_KEY_RECORD_ID,
          key: this.masterKey,
          v: 3,
        });
        tx.oncomplete = () => {
          db.close();
          resolve();
        };
        tx.onerror = () => {
          db.close();
          resolve();
        };
        tx.onabort = () => {
          db.close();
          resolve();
        };
      } catch {
        db.close();
        resolve();
      }
    });
  }

  static setMasterKey(key: CryptoKey): void {
    this.masterKey = key;
    this.isInitialized = true;
  }

  static async generateMasterKey(): Promise<CryptoKey> {
    const key = await crypto.subtle.generateKey(
      { name: 'AES-GCM', length: 256 },
      false,
      ['encrypt', 'decrypt'],
    );
    this.masterKey = key;
    this.isInitialized = true;
    return key;
  }

  static async initialize(userCredential?: string): Promise<void> {
    if (this.isInitialized && this.masterKey) return;

    this.sessionWrapCredential = normalizeExplicitCredential(userCredential);

    const restoredPersistent = await this.tryRestoreKeyFromPersistentStore();
    if (restoredPersistent) return;

    const restoredSession = await this.tryRestoreKeyFromSession();
    if (restoredSession) {
      await this.persistKeyToPersistentStore();
      return;
    }

    const restoredLegacyDevice = await this.tryRestoreLegacyDeviceKey();
    if (restoredLegacyDevice) {
      await this.persistKeyToPersistentStore();
      this.purgeLegacyDeviceWrappedKey();
      return;
    }

    await this.generateMasterKey();
    await this.persistKeyToPersistentStore();
  }

  private static purgeLegacyDeviceWrappedKey(): void {
    if (typeof localStorage === 'undefined') return;
    try {
      localStorage.removeItem(DEVICE_KEY_STORAGE_KEY);
    } catch {
      /* ignore */
    }
  }

  private static async tryRestoreLegacyDeviceKey(): Promise<boolean> {
    if (typeof window === 'undefined') return false;
    try {
      const deviceId = getOrCreateDeviceId();
      if (!deviceId) return false;

      const stored = localStorage.getItem(DEVICE_KEY_STORAGE_KEY);
      if (!stored) return false;

      let parsed: { wrapped?: string };
      try {
        parsed = JSON.parse(stored) as { wrapped?: string };
      } catch {
        this.purgeLegacyDeviceWrappedKey();
        return false;
      }

      if (!parsed.wrapped) {
        this.purgeLegacyDeviceWrappedKey();
        return false;
      }

      const wrappingKey = await deriveWrappingKey(`${DEVICE_WRAP_PREFIX}${deviceId}`);
      const wrappedKeyBuffer = fromBase64Url(parsed.wrapped);
      const unwrapped = await crypto.subtle.unwrapKey(
        'raw',
        wrappedKeyBuffer,
        wrappingKey,
        { name: 'AES-KW' },
        { name: 'AES-GCM', length: 256 },
        false,
        ['encrypt', 'decrypt'],
      );

      this.masterKey = unwrapped;
      this.isInitialized = true;
      return true;
    } catch (error) {
      _warn('[CryptoService] Legacy device key restore failed:', error);
      this.purgeLegacyDeviceWrappedKey();
      return false;
    }
  }

  private static async tryRestoreKeyFromSession(): Promise<boolean> {
    try {
      const credential = this.sessionWrapCredential ?? (await getWrapCredential());
      if (!credential) return false;

      const sessionData = sessionStorage.getItem(SESSION_KEY_STORAGE_KEY);
      if (!sessionData) return false;

      let parsed: { wrapped: string };
      try {
        parsed = JSON.parse(sessionData);
      } catch {
        sessionStorage.removeItem(SESSION_KEY_STORAGE_KEY);
        return false;
      }

      if (!parsed.wrapped) {
        sessionStorage.removeItem(SESSION_KEY_STORAGE_KEY);
        return false;
      }

      const wrappingKey = await deriveWrappingKey(credential);
      const wrappedKeyBuffer = fromBase64Url(parsed.wrapped);

      const unwrapped = await crypto.subtle.unwrapKey(
        'raw',
        wrappedKeyBuffer,
        wrappingKey,
        { name: 'AES-KW' },
        { name: 'AES-GCM', length: 256 },
        false,
        ['encrypt', 'decrypt']
      );

      this.masterKey = unwrapped;
      this.isInitialized = true;
      return true;
    } catch (error) {
      _warn('[CryptoService] Session key restore failed, will generate a new key:', error);
      sessionStorage.removeItem(SESSION_KEY_STORAGE_KEY);
      return false;
    }
  }

  private static async persistKeyToSession(): Promise<void> {
    try {
      if (!this.masterKey) return;
      if (!this.masterKey.extractable) return;
      const credential = this.sessionWrapCredential ?? (await getWrapCredential());
      if (!credential) return;

      const wrappingKey = await deriveWrappingKey(credential);
      const wrapped = await crypto.subtle.wrapKey(
        'raw',
        this.masterKey,
        wrappingKey,
        { name: 'AES-KW' }
      );

      sessionStorage.setItem(SESSION_KEY_STORAGE_KEY, JSON.stringify({
        wrapped: toBase64Url(wrapped),
        v: 2,
      }));
    } catch (error) {
      _warn('[CryptoService] Session key persist failed:', error);
    }
  }

  static async encryptData(plainText: string): Promise<string> {
    if (!this.masterKey) {
      throw new Error('CryptoService not initialized. Call initialize() first.');
    }
    const encoder = new TextEncoder();
    const data = encoder.encode(plainText);
    const iv = crypto.getRandomValues(new Uint8Array(12));
    const ciphertext = await crypto.subtle.encrypt({ name: 'AES-GCM', iv }, this.masterKey, data);
    const ivB64 = this.arrayBufferToBase64(iv.buffer);
    const cipherB64 = this.arrayBufferToBase64(ciphertext);
    return `${ivB64}:${cipherB64}`;
  }

  static async decryptData(encryptedData: string): Promise<string> {
    if (!this.masterKey) {
      throw new Error('CryptoService not initialized. Call initialize() first.');
    }
    const trimmed = encryptedData.trim();
    if (!trimmed) return '';

    if (!this.isValidEncryptedData(trimmed)) {
      throw new Error('[CryptoService] Data does not appear to be encrypted or is corrupted');
    }

    if (trimmed.includes(':')) {
      const [ivB64, cipherB64] = trimmed.split(':', 2);
      if (!ivB64 || !cipherB64) throw new Error('[CryptoService] Tampered data: invalid IV/ciphertext format');
      const ivBuf = this.base64ToArrayBuffer(ivB64);
      const cipherBuf = this.base64ToArrayBuffer(cipherB64);
      const decrypted = await crypto.subtle.decrypt({ name: 'AES-GCM', iv: new Uint8Array(ivBuf) }, this.masterKey, cipherBuf);
      return new TextDecoder().decode(decrypted);
    }

    const combined = this.base64ToArrayBuffer(trimmed);
    const combinedArray = new Uint8Array(combined);
    const iv = combinedArray.slice(0, 12);
    const cipher = combinedArray.slice(12);
    const decrypted = await crypto.subtle.decrypt({ name: 'AES-GCM', iv }, this.masterKey, cipher);
    return new TextDecoder().decode(decrypted);
  }

  static async generateDataSignature(data: string): Promise<string> {
    const encoder = new TextEncoder();
    const hashBuffer = await crypto.subtle.digest('SHA-256', encoder.encode(data));
    return this.arrayBufferToHex(hashBuffer);
  }

  static async encrypt(plaintext: string): Promise<string> {
    return await this.encryptData(plaintext);
  }

  static async decrypt(ciphertext: string): Promise<string> {
    return await this.decryptData(ciphertext);
  }

  static async generateSignature(data: Record<string, unknown>): Promise<string> {
    const cleanedEntries = Object.entries(data).filter(([, v]) => v !== undefined && v !== null && v !== '');
    const criticalFields = cleanedEntries
      .sort(([a], [b]) => a.localeCompare(b))
      .map(([k, v]) => `${k}:${typeof v === 'string' ? v : JSON.stringify(v)}`)
      .join('|');
    return await this.generateDataSignature(criticalFields);
  }

  static async verifySignature(
    data: Record<string, unknown>,
    expectedSignature: string
  ): Promise<boolean> {
    try {
      const currentSignature = await this.generateSignature(data);
      return currentSignature === expectedSignature;
    } catch {
      return false;
    }
  }

  static async encryptObject(obj: Record<string, unknown>): Promise<{
    encrypted: Record<string, unknown>;
    signature: string;
  }> {
    const encrypted: Record<string, unknown> = {};
    for (const [key, value] of Object.entries(obj)) {
      if (typeof value === 'string' && value.trim()) {
        encrypted[key] = await this.encryptData(value);
      } else {
        encrypted[key] = value;
      }
    }
    const signature = await this.generateSignature(obj);
    return { encrypted, signature };
  }

  static async decryptObject(
    encryptedObj: Record<string, unknown>,
    expectedSignature?: string
  ): Promise<{
    decrypted: Record<string, unknown>;
    isIntegrityValid: boolean;
    needsReEncryption?: boolean;
  }> {
    if (!encryptedObj || typeof encryptedObj !== 'object') {
      _warn('[CryptoService] Invalid input - expected object, got:', typeof encryptedObj);
      return {
        decrypted: {},
        isIntegrityValid: false,
        needsReEncryption: false
      };
    }

    const decrypted: Record<string, unknown> = {};
    for (const [key, value] of Object.entries(encryptedObj)) {
      if (typeof value !== 'string') {
        decrypted[key] = value;
        continue;
      }
      const trimmed = value.trim();
      if (!trimmed) {
        decrypted[key] = value;
        continue;
      }
      if (trimmed.includes(':')) {
        try {
          decrypted[key] = await this.decryptData(trimmed);
        } catch (error) {
          _warn('[CryptoService] Field decrypt failed:', key, error);
          decrypted[key] = '[DECRYPT_FAILED]';
        }
        continue;
      }
      if (/^[A-Za-z0-9+/]+={0,2}$/.test(trimmed) && trimmed.length >= 24) {
        try {
          decrypted[key] = await this.decryptData(trimmed);
        } catch {
          _warn('[CryptoService] Field decrypt failed (base64 but not encrypted):', key);
          decrypted[key] = value;
        }
        continue;
      }
      decrypted[key] = value;
    }

    let isIntegrityValid = true;
    let needsReEncryption = false;

    if (expectedSignature) {
      isIntegrityValid = await this.verifySignature(decrypted, expectedSignature);
      if (!isIntegrityValid) {
        needsReEncryption = true;
      }
    }

    return { decrypted, isIntegrityValid, needsReEncryption };
  }

  static async reEncryptObject(
    oldEncryptedObj: Record<string, unknown>,
    oldSignature: string
  ): Promise<{
    encrypted: Record<string, unknown>;
    signature: string;
  } | null> {
    try {
      const { decrypted } = await this.decryptObject(oldEncryptedObj, oldSignature);
      return await this.encryptObject(decrypted);
    } catch (error) {
      _err('[CryptoService] Re-encryption failed:', error);
      return null;
    }
  }

  static destroy(): void {
    try {
      sessionStorage.removeItem(SESSION_KEY_STORAGE_KEY);
    } catch {
      /* ignore */
    }
    this.masterKey = null;
    this.isInitialized = false;
    this.sessionWrapCredential = null;
  }

  private static arrayBufferToBase64(buffer: ArrayBuffer): string {
    const bytes = new Uint8Array(buffer);
    const chunkSize = 0x8000;
    let binary = '';
    for (let i = 0; i < bytes.length; i += chunkSize) {
      const chunk = bytes.subarray(i, i + chunkSize);
      binary += String.fromCharCode(...chunk);
    }
    return btoa(binary);
  }

  private static base64ToArrayBuffer(base64: string): ArrayBuffer {
    const binary = atob(base64);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) {
      bytes[i] = binary.charCodeAt(i);
    }
    return bytes.buffer;
  }

  private static arrayBufferToHex(buffer: ArrayBuffer): string {
    return Array.from(new Uint8Array(buffer))
      .map(b => b.toString(16).padStart(2, '0'))
      .join('');
  }

  private static isValidEncryptedData(data: string): boolean {
    try {
      const base64Regex = /^[A-Za-z0-9+/=]+(:[A-Za-z0-9+/=]+)?$/;
      if (!base64Regex.test(data)) return false;
      if (data.includes(':')) {
        const parts = data.split(':');
        if (parts.length !== 2) return false;
        return parts[0].length > 0 && parts[1].length > 0;
      }
      return data.length > 16;
    } catch {
      return false;
    }
  }
}

/**
 * Rate Limiting Service
 * حماية من هجمات DDoS والطلبات المفرطة
 * @version 2.0.0 — with IndexedDB persistence
 */

const DB_NAME = 'HamiRateLimitDB';
const DB_VERSION = 1;
const STORE_NAME = 'rateLimitEntries';

const _warn = (...a: unknown[]) => { if (import.meta.env.DEV) console.warn(...a); };
const _log = (...a: unknown[]) => { if (import.meta.env.DEV) console.log(...a); };

interface RateLimitConfig {
  maxRequests: number;
  windowMs: number;
  blockDurationMs?: number;
}

interface RateLimitEntry {
  count: number;
  resetTime: number;
  blocked: boolean;
  blockUntil?: number;
}

interface PersistedEntry {
  key: string;
  entry: RateLimitEntry;
  updatedAt: number;
}

function openDB(): Promise<IDBDatabase | null> {
  if (typeof indexedDB === 'undefined') return Promise.resolve(null);
  return new Promise((resolve) => {
    try {
      const request = indexedDB.open(DB_NAME, DB_VERSION);
      request.onerror = () => resolve(null);
      request.onsuccess = () => resolve(request.result);
      request.onupgradeneeded = () => {
        const db = request.result;
        if (!db.objectStoreNames.contains(STORE_NAME)) {
          db.createObjectStore(STORE_NAME, { keyPath: 'key' });
        }
      };
    } catch {
      resolve(null);
    }
  });
}

async function persistToDB(key: string, entry: RateLimitEntry): Promise<void> {
  const db = await openDB();
  if (!db) return;
  try {
    const tx = db.transaction(STORE_NAME, 'readwrite');
    const store = tx.objectStore(STORE_NAME);
    store.put({ key, entry, updatedAt: Date.now() } satisfies PersistedEntry);
    tx.commit();
  } catch {
    /* best effort */
  } finally {
    db.close();
  }
}

async function bulkLoadFromDB(): Promise<Map<string, RateLimitEntry>> {
  const map = new Map<string, RateLimitEntry>();
  const db = await openDB();
  if (!db) return map;
  try {
    const tx = db.transaction(STORE_NAME, 'readonly');
    const store = tx.objectStore(STORE_NAME);
    const all = await new Promise<PersistedEntry[]>((resolve, reject) => {
      const req = store.getAll();
      req.onsuccess = () => resolve(req.result as PersistedEntry[]);
      req.onerror = () => reject(req.error);
    });
    const now = Date.now();
    for (const item of all) {
      if (item.entry.resetTime > now) {
        map.set(item.key, item.entry);
      }
    }
  } catch {
    /* best effort */
  } finally {
    db.close();
  }
  return map;
}

async function removeFromDB(key: string): Promise<void> {
  const db = await openDB();
  if (!db) return;
  try {
    const tx = db.transaction(STORE_NAME, 'readwrite');
    const store = tx.objectStore(STORE_NAME);
    store.delete(key);
    tx.commit();
  } catch {
    /* best effort */
  } finally {
    db.close();
  }
}

async function clearAllFromDB(): Promise<void> {
  const db = await openDB();
  if (!db) return;
  try {
    const tx = db.transaction(STORE_NAME, 'readwrite');
    const store = tx.objectStore(STORE_NAME);
    store.clear();
    tx.commit();
  } catch {
    /* best effort */
  } finally {
    db.close();
  }
}

class RateLimitService {
  private limits: Map<string, RateLimitEntry> = new Map();
  private configs: Map<string, RateLimitConfig> = new Map();
  private persisted = false;

  async initialize(): Promise<void> {
    if (this.persisted) return;
    try {
      const loaded = await bulkLoadFromDB();
      if (loaded.size > 0) {
        this.limits = loaded;
        _log(`[RateLimit] Loaded ${loaded.size} persisted entries`);
      }
      this.persisted = true;
    } catch {
      this.persisted = true;
    }
  }

  configure(operation: string, config: RateLimitConfig): void {
    this.configs.set(operation, config);
  }

  check(operation: string, identifier: string): boolean {
    const config = this.configs.get(operation);
    if (!config) return true;

    const key = `${operation}:${identifier}`;
    const now = Date.now();
    let entry = this.limits.get(key);

    if (entry?.blocked && entry.blockUntil && now < entry.blockUntil) {
      return false;
    }

    if (!entry || now > entry.resetTime) {
      entry = {
        count: 0,
        resetTime: now + config.windowMs,
        blocked: false,
      };
      this.limits.set(key, entry);
      void persistToDB(key, entry);
    }

    entry.count++;

    if (entry.count > config.maxRequests) {
      entry.blocked = true;
      entry.blockUntil = now + (config.blockDurationMs || config.windowMs * 2);
      _warn(`[RateLimit] Blocked: ${key} (${entry.count} requests)`);
      void persistToDB(key, entry);
      return false;
    }

    void persistToDB(key, entry);
    return true;
  }

  reset(operation: string, identifier: string): void {
    const key = `${operation}:${identifier}`;
    this.limits.delete(key);
    void removeFromDB(key);
  }

  getStatus(operation: string, identifier: string): {
    allowed: boolean;
    remaining: number;
    resetTime: number;
  } | null {
    const config = this.configs.get(operation);
    if (!config) return null;

    const key = `${operation}:${identifier}`;
    const entry = this.limits.get(key);

    if (!entry) {
      return {
        allowed: true,
        remaining: config.maxRequests,
        resetTime: Date.now() + config.windowMs,
      };
    }

    return {
      allowed: !entry.blocked,
      remaining: Math.max(0, config.maxRequests - entry.count),
      resetTime: entry.resetTime,
    };
  }

  async cleanup(): Promise<void> {
    const now = Date.now();
    const keysToDelete: string[] = [];
    for (const [key, entry] of this.limits.entries()) {
      if (now > entry.resetTime && (!entry.blocked || (entry.blockUntil && now > entry.blockUntil))) {
        this.limits.delete(key);
        keysToDelete.push(key);
      }
    }
    if (keysToDelete.length > 0) {
      const db = await openDB();
      if (db) {
        try {
          const tx = db.transaction(STORE_NAME, 'readwrite');
          const store = tx.objectStore(STORE_NAME);
          for (const k of keysToDelete) store.delete(k);
          tx.commit();
        } catch {
          /* best effort */
        } finally {
          db.close();
        }
      }
    }
  }

  async clearAllPersisted(): Promise<void> {
    this.limits.clear();
    await clearAllFromDB();
  }
}

