    static async togglePostSubscription(postId: string, requesterId?: string | null): Promise<boolean> {
        const userId = await getSessionUserId(requesterId);
        if (!userId) throw new Error('يجب تسجيل الدخول');

        const wasSubscribed = await ForumPostFollowRepository.isSubscribed(userId, postId);
        let subscribed: boolean;
        if (wasSubscribed) {
            await ForumPostFollowRepository.unsubscribe(userId, postId);
            subscribed = false;
        } else {
            await ForumPostFollowRepository.subscribe(userId, postId);
            subscribed = true;
        }

        void postJson<ApiOk<{ subscribed: boolean }>>('/api/forum/post-follow', {
            postId,
            action: 'toggle',
        }).catch(() => undefined);

        return subscribed;
    }

    static async listForumNotifications(requesterId?: string | null): Promise<{
        notifications: ForumNotification[];
        unreadCount: number;
    }> {
        const userId = await getSessionUserId(requesterId);
        if (!userId) return { notifications: [], unreadCount: 0 };

        const [blobLocal] = await Promise.all([NotificationDB.getNotifications(userId)]);
        const repoLocal = peekLocalNotifications(userId)
            .filter((n) => deriveNotificationCategory(n) === 'forum')
            .map((n) => mapModelToForumNotification(n, userId))
            .filter((n): n is ForumNotification => n !== null);
        const local = mergeForumNotificationsById(blobLocal, repoLocal);

        if (!(await canUseRemoteForumSession())) {
            return {
                notifications: local,
                unreadCount: local.filter((n) => !n.read).length,
            };
        }

        try {
            const res = await SecureAPIClient.fetchSecure<{
                ok: boolean;
                notifications: import('@/app/services/cloud/lawyerCommunityTypes').ForumNotification[];
                unreadCount: number;
            }>('/api/forum/notifications', { method: 'GET' });
            const notifications = Array.isArray(res.notifications) ? res.notifications : local;
            const unreadCount =
                typeof res.unreadCount === 'number'
                    ? res.unreadCount
                    : notifications.filter((n) => !n.read).length;

            if (typeof window !== 'undefined') {
                syncForumNotificationsToAppStore(userId, notifications);
                emitForumUnreadCount(unreadCount, { refresh: true });
            }

            return { notifications, unreadCount };
        } catch {
            const unreadCount = local.filter((n) => !n.read).length;
            if (typeof window !== 'undefined') {
                emitForumUnreadCount(unreadCount, { refresh: true });
            }
            return {
                notifications: local,
                unreadCount,
            };
        }
    }

    static async markForumNotificationRead(notificationId: string, requesterId?: string | null): Promise<void> {
        const userId = await getSessionUserId(requesterId);
        if (!userId) return;

        await persistForumNotificationRead(userId, notificationId);

        if (typeof window !== 'undefined') {
            const { syncForumReadToShell } = await import(
                '@/app/services/notifications/notificationReadSync'
            );
            await syncForumReadToShell(userId, notificationId);
            const remaining = await countForumUnread(userId);
            emitForumUnreadCount(remaining);
        }
    }

    static async markAllForumNotificationsRead(requesterId?: string | null): Promise<void> {
        const userId = await getSessionUserId(requesterId);
        if (!userId) return;

        await persistForumMarkAllRead(userId);

        if (typeof window !== 'undefined') {
            const { syncForumMarkAllReadToShell } = await import(
                '@/app/services/notifications/notificationReadSync'
            );
            await syncForumMarkAllReadToShell(userId);
            emitForumUnreadCount(0);
        }
    }

    static async dismissForumNotification(notificationId: string, requesterId?: string | null): Promise<void> {
        const userId = await getSessionUserId(requesterId);
        if (!userId) return;

        await persistForumNotificationDismiss(userId, notificationId);

        if (typeof window !== 'undefined') {
            const remaining = await countForumUnread(userId);
            emitForumUnreadCount(remaining, { refresh: true });
        }
    }
}

import SecureStoreService from '@/app/services/SecureStoreService';
import { lawyerCloudKv as kv, uuidv4 } from '@/app/services/cloud/lawyerCloudKv';

const LAWYER_LOCAL_PREFIX = 'hami:lawyerdb:';

function isRecord(value: unknown): value is Record<string, unknown> {
    return Boolean(value) && typeof value === 'object';
}

export const LawyerDB = {
    async saveUserProfile(userId: string, data: Record<string, unknown>) {
        try {
            await kv.set(`user:${userId}:profile`, data);
        } catch {
            const key = `${LAWYER_LOCAL_PREFIX}${userId}:profile`;
            await SecureStoreService.setItem(key, JSON.stringify(data));
        }
    },

    async getUserProfile(userId: string) {
        try {
            return await kv.get(`user:${userId}:profile`);
        } catch {
            const key = `${LAWYER_LOCAL_PREFIX}${userId}:profile`;
            const raw = await SecureStoreService.getItem(key);
            return raw ? JSON.parse(raw) : null;
        }
    },

    async saveCase(userId: string, caseData: Record<string, unknown>) {
        const providedId = typeof caseData.id === 'string' ? caseData.id : undefined;
        const id = providedId ?? uuidv4();
        const key = `user:${userId}:cases:${id}`;
        try {
            await kv.set(key, { ...caseData, id, updatedAt: new Date().toISOString() });
        } catch {
            const existing = await this.getCases(userId);
            const updated = [
                ...(Array.isArray(existing) ? existing : []).filter((c: any) => c.id !== id),
                { ...caseData, id, updatedAt: new Date().toISOString() },
            ];
            await SecureStoreService.setItem(`${LAWYER_LOCAL_PREFIX}${userId}:cases`, JSON.stringify(updated));
        }
        return id;
    },

    async getCases(userId: string) {
        try {
            const cases = await kv.getByPrefix(`user:${userId}:cases:`);
            return cases || [];
        } catch {
            const raw = await SecureStoreService.getItem(`${LAWYER_LOCAL_PREFIX}${userId}:cases`);
            return raw ? JSON.parse(raw) : [];
        }
    },

    async saveNote(userId: string, noteData: Record<string, unknown>) {
        const providedId = typeof noteData.id === 'string' ? noteData.id : undefined;
        const id = providedId ?? uuidv4();
        const key = `user:${userId}:notes:${id}`;
        try {
            await kv.set(key, { ...noteData, id, createdAt: new Date().toISOString() });
        } catch {
            const existing = await this.getNotes(userId);
            const updated = [
                ...(Array.isArray(existing) ? existing : []).filter((n: any) => n.id !== id),
                { ...noteData, id, createdAt: new Date().toISOString() },
            ];
            await SecureStoreService.setItem(`${LAWYER_LOCAL_PREFIX}${userId}:notes`, JSON.stringify(updated));
        }
        return id;
    },

    async getNotes(userId: string) {
        try {
            const notes = await kv.getByPrefix(`user:${userId}:notes:`);
            return notes || [];
        } catch {
            const raw = await SecureStoreService.getItem(`${LAWYER_LOCAL_PREFIX}${userId}:notes`);
            return raw ? JSON.parse(raw) : [];
        }
    },

    async saveDeadline(userId: string, deadlineData: Record<string, unknown>) {
        const providedId = typeof deadlineData.id === 'string' ? deadlineData.id : undefined;
        const id = providedId ?? uuidv4();
        const key = `user:${userId}:deadlines:${id}`;
        try {
            await kv.set(key, { ...deadlineData, id, status: 'pending' });
        } catch {
            const existing = await this.getDeadlines(userId);
            const updated = [
                ...(Array.isArray(existing) ? existing : []).filter((d: any) => d.id !== id),
                { ...deadlineData, id, status: 'pending' },
            ];
            await SecureStoreService.setItem(`${LAWYER_LOCAL_PREFIX}${userId}:deadlines`, JSON.stringify(updated));
        }
        return id;
    },

    async checkUpcomingDeadlines(userId: string) {
        const deadlines = await this.getDeadlines(userId);
        const list = Array.isArray(deadlines) ? deadlines : [];
        const tomorrow = new Date();
        tomorrow.setDate(tomorrow.getDate() + 1);
        tomorrow.setHours(0, 0, 0, 0);

        return list.filter((d) => {
            if (!isRecord(d) || typeof d.date !== 'string') return false;
            const date = new Date(d.date);
            const t = date.getTime();
            return t >= tomorrow.getTime() && t < tomorrow.getTime() + 86400000;
        });
    },

    async getDeadlines(userId: string) {
        try {
            return (await kv.getByPrefix(`user:${userId}:deadlines:`)) || [];
        } catch {
            const raw = await SecureStoreService.getItem(`${LAWYER_LOCAL_PREFIX}${userId}:deadlines`);
            return raw ? JSON.parse(raw) : [];
        }
    },
};

import type { NotificationModel } from '@/app/infrastructure/NotificationRepository';
import { deriveNotificationCategory } from '@/app/infrastructure/NotificationRepository';
import {
    mapForumNotificationToModel,
    mapModelToForumNotification,
} from '@/app/services/notifications/forumNotificationMapper';
import { capMergedNotificationLists, mergeNotificationRecord } from '@/app/services/notifications/notificationMerge';
import type { ForumNotification } from '@/app/services/forum/forumTypes';

export const NOTIFICATION_BLOB_KEY_PREFIX = 'notifications_';

export function notificationBlobKey(userId: string): string {
    return `${NOTIFICATION_BLOB_KEY_PREFIX}${userId}`;
}

export function parseNotificationBlob(raw: unknown): NotificationModel[] {
    return Array.isArray(raw) ? (raw as NotificationModel[]) : [];
}

export function extractForumNotificationsFromModels(
    models: NotificationModel[],
    userId: string,
): ForumNotification[] {
    return models
        .map((model) => mapModelToForumNotification(model, userId))
        .filter((n): n is ForumNotification => n != null)
        .sort((a, b) => Date.parse(b.createdAt) - Date.parse(a.createdAt));
}

export function upsertForumIntoModels(
    models: NotificationModel[],
    forumNotif: ForumNotification,
): NotificationModel[] {
    const incoming = mapForumNotificationToModel(forumNotif);
    const existing = models.find((n) => n.id === incoming.id);
    if (!existing) {
        return capMergedNotificationLists(models, [incoming]);
    }
    return models.map((n) => (n.id === incoming.id ? mergeNotificationRecord(n, incoming) : n));
}

export function patchForumInModels(
    models: NotificationModel[],
    userId: string,
    notificationId: string,
    patch: Partial<Pick<ForumNotification, 'title' | 'message' | 'read' | 'createdAt' | 'activityCount' | 'dedupeKey'>>,
): NotificationModel[] {
    const forum = extractForumNotificationsFromModels(models, userId).find((n) => n.id === notificationId);
    if (!forum) return models;

    const updatedForum: ForumNotification = {
        ...forum,
        ...patch,
        read: patch.read ?? forum.read,
    };

    return upsertForumIntoModels(
        models.filter((n) => n.id !== notificationId),
        updatedForum,
    );
}

export function markForumReadInModels(
    models: NotificationModel[],
    userId: string,
    notificationId: string,
): NotificationModel[] {
    return patchForumInModels(models, userId, notificationId, { read: true });
}

export function markAllForumReadInModels(models: NotificationModel[], userId: string): NotificationModel[] {
    return models.map((n) =>
        deriveNotificationCategory(n) === 'forum' ? { ...n, isRead: true } : n,
    );
}

export function dismissForumNotificationInModels(
    models: NotificationModel[],
    userId: string,
    notificationId: string,
): NotificationModel[] {
    return models.filter((n) => {
        if (n.id !== notificationId) return true;
        const forum = mapModelToForumNotification(n, userId);
        return forum == null;
    });
}

export function mergeLegacyForumIntoModels(
    models: NotificationModel[],
    legacyForum: ForumNotification[],
): NotificationModel[] {
    let next = models;
    for (const forumNotif of legacyForum) {
        next = upsertForumIntoModels(next, forumNotif);
    }
    return next;
}

export function isForumModel(n: NotificationModel): boolean {
    return deriveNotificationCategory(n) === 'forum';
}

