import type { BackgroundPresetId } from './backgroundPresets';

/** كل عناصر الواجهة القابلة للنقل بين المناطق */
export const HOME_WIDGET_IDS = [
    'alerts',
    'hubExecution',
    'hubLawsuit',
    'hubTransaction',
    'forum',
    'dockRepository',
    'dockNotepad',
    'dockCalendar',
    'dockVault',
    'dockTasks',
    'dockQuickNote',
] as const;

export type HomeWidgetId = (typeof HOME_WIDGET_IDS)[number];

export type HomeWidgetZone = 'main' | 'dock';

export interface HomeWidgetPlacement {
    zone: HomeWidgetZone;
    order: number;
}

export type HomeWidgetPlacements = Record<HomeWidgetId, HomeWidgetPlacement>;

/** دُمجت في المستودع الذكي — تبقى في placements للترحيل فقط ولا تُعرض على السطح */
export const REPOSITORY_LEGACY_WIDGET_IDS = ['dockNotepad', 'dockVault'] as const satisfies readonly HomeWidgetId[];

export type RepositoryLegacyWidgetId = (typeof REPOSITORY_LEGACY_WIDGET_IDS)[number];

export function isRepositoryLegacyWidget(id: HomeWidgetId): id is RepositoryLegacyWidgetId {
    return (REPOSITORY_LEGACY_WIDGET_IDS as readonly HomeWidgetId[]).includes(id);
}

export function filterDisplayHomeWidgets(
    ids: HomeWidgetId[],
    _layoutEditMode: boolean,
): HomeWidgetId[] {
    return ids.filter((id) => !isRepositoryLegacyWidget(id));
}

export function buildDefaultPlacements(): HomeWidgetPlacements {
    return {
        alerts: { zone: 'main', order: 0 },
        hubExecution: { zone: 'main', order: 1 },
        hubLawsuit: { zone: 'main', order: 2 },
        hubTransaction: { zone: 'main', order: 3 },
        forum: { zone: 'main', order: 4 },
        dockRepository: { zone: 'dock', order: 0 },
        dockNotepad: { zone: 'dock', order: 98 },
        dockCalendar: { zone: 'dock', order: 1 },
        dockVault: { zone: 'dock', order: 99 },
        dockTasks: { zone: 'dock', order: 2 },
        dockQuickNote: { zone: 'dock', order: 3 },
    };
}

export function isHomeWidgetId(id: string): id is HomeWidgetId {
    return (HOME_WIDGET_IDS as readonly string[]).includes(id);
}

/** عناصر الدوك — لا تُحسب في ترتيب أيقونات الشريط */
export const DOCK_SHELL_WIDGET_IDS: HomeWidgetId[] = ['dockQuickNote'];

export function isDockShellOrderWidget(id: HomeWidgetId): boolean {
    return !DOCK_SHELL_WIDGET_IDS.includes(id) && !isRepositoryLegacyWidget(id);
}

/** عناصر الدوك الأصلية — أيقونة + تسمية فقط */
export function isDockCompactWidget(id: HomeWidgetId): boolean {
    return (
        id === 'dockRepository' ||
        id === 'dockNotepad' ||
        id === 'dockCalendar' ||
        id === 'dockVault' ||
        id === 'dockTasks' ||
        id === 'dockQuickNote'
    );
}

export function getWidgetZone(
    placements: HomeWidgetPlacements,
    widgetId: HomeWidgetId,
): HomeWidgetZone {
    return placements[widgetId]?.zone ?? 'main';
}

export function getWidgetsInZone(
    placements: HomeWidgetPlacements,
    zone: HomeWidgetZone,
): HomeWidgetId[] {
    return HOME_WIDGET_IDS.filter((id) => placements[id]?.zone === zone).sort(
        (a, b) => (placements[a]?.order ?? 0) - (placements[b]?.order ?? 0),
    );
}

/** إعادة ترقيم order داخل منطقة */
function reindexZone(placements: HomeWidgetPlacements, zone: HomeWidgetZone): HomeWidgetPlacements {
    const ids = getWidgetsInZone(placements, zone);
    const next = { ...placements };
    ids.forEach((id, index) => {
        next[id] = { zone, order: index };
    });
    return next;
}

/** نقل عنصر إلى منطقة أخرى مع موضع إدراج */
export function transferWidget(
    placements: HomeWidgetPlacements,
    widgetId: HomeWidgetId,
    targetZone: HomeWidgetZone,
    insertIndex: number,
): HomeWidgetPlacements {
    const sourceZone = placements[widgetId]?.zone ?? 'main';
    let next = { ...placements };

    const sourceIds = getWidgetsInZone(next, sourceZone).filter((id) => id !== widgetId);
    sourceIds.forEach((id, i) => {
        next[id] = { zone: sourceZone, order: i };
    });

    const targetIds = getWidgetsInZone(next, targetZone).filter((id) => id !== widgetId);
    const clamped = Math.max(0, Math.min(insertIndex, targetIds.length));
    targetIds.splice(clamped, 0, widgetId);
    targetIds.forEach((id, i) => {
        next[id] = { zone: targetZone, order: i };
    });

    next[widgetId] = { zone: targetZone, order: clamped };
    next = reindexZone(next, sourceZone);
    next = reindexZone(next, targetZone);
    return next;
}

export function reorderWidgetInZone(
    placements: HomeWidgetPlacements,
    widgetId: HomeWidgetId,
    newIndex: number,
): HomeWidgetPlacements {
    const zone = placements[widgetId]?.zone ?? 'main';
    const ids = getWidgetsInZone(placements, zone);
    const from = ids.indexOf(widgetId);
    if (from < 0) return placements;
    const nextIds = [...ids];
    nextIds.splice(from, 1);
    const clamped = Math.max(0, Math.min(newIndex, nextIds.length));
    nextIds.splice(clamped, 0, widgetId);
    let next = { ...placements };
    nextIds.forEach((id, i) => {
        next[id] = { zone, order: i };
    });
    return next;
}

/** حساب موضع الإدراج من إحداثيات المؤشر */
export function computeInsertIndex(
    pointer: number,
    bounds: Array<{ id: HomeWidgetId; start: number; end: number }>,
    axis: 'x' | 'y',
): number {
    if (bounds.length === 0) return 0;
    for (let i = 0; i < bounds.length; i++) {
        const mid = (bounds[i].start + bounds[i].end) / 2;
        if (pointer < mid) return i;
    }
    return bounds.length;
}

export function migrateLegacyOrdersToPlacements(raw: {
    scrollOrder?: unknown;
    hubTileOrder?: unknown;
    dockItemOrder?: unknown;
    placements?: unknown;
}): HomeWidgetPlacements {
    if (raw.placements && typeof raw.placements === 'object') {
        const base = buildDefaultPlacements();
        const obj = raw.placements as Record<string, HomeWidgetPlacement>;
        for (const id of HOME_WIDGET_IDS) {
            const p = obj[id];
            if (p && (p.zone === 'main' || p.zone === 'dock') && typeof p.order === 'number') {
                base[id] = { zone: p.zone, order: p.order };
            }
        }
        return consolidateLegacyRepositoryDock(reindexZone(reindexZone(base, 'main'), 'dock'));
    }

    const base = buildDefaultPlacements();
    const mainOrder: string[] = [];
    const scroll = Array.isArray(raw.scrollOrder) ? raw.scrollOrder : [];
    for (const id of scroll) {
        if (id === 'hub') {
            const hubTiles = Array.isArray(raw.hubTileOrder)
                ? raw.hubTileOrder
                : ['hubExecution', 'hubLawsuit', 'hubTransaction'];
            for (const t of hubTiles) if (typeof t === 'string') mainOrder.push(t);
        } else if (typeof id === 'string' && id !== 'notepad' && id !== 'homeTitle') {
            mainOrder.push(id);
        }
    }
    if (mainOrder.length === 0) {
        mainOrder.push('alerts', 'hubExecution', 'hubLawsuit', 'hubTransaction', 'forum');
    }
    mainOrder.filter((id) => id !== 'homeTitle').forEach((id, i) => {
        if (isHomeWidgetId(id)) base[id] = { zone: 'main', order: i };
    });

    const dockOrder = Array.isArray(raw.dockItemOrder)
        ? raw.dockItemOrder
        : ['dockRepository', 'dockCalendar', 'dockTasks', 'dockQuickNote'];
    dockOrder.forEach((id, i) => {
        if (isHomeWidgetId(id as string)) base[id as HomeWidgetId] = { zone: 'dock', order: i };
    });

    return consolidateLegacyRepositoryDock(reindexZone(reindexZone(base, 'main'), 'dock'));
}

function stashRepositoryLegacyWidgets(placements: HomeWidgetPlacements): {
    placements: HomeWidgetPlacements;
    changed: boolean;
} {
    const next = { ...placements };
    let changed = false;
    for (const id of REPOSITORY_LEGACY_WIDGET_IDS) {
        const zone = next[id]?.zone;
        if (zone !== 'main' && zone !== 'dock') continue;
        next[id] = { zone: 'dock', order: 98 + REPOSITORY_LEGACY_WIDGET_IDS.indexOf(id) };
        changed = true;
    }
    return { placements: next, changed };
}

/** دمج أيقونتي المفكرة والمخزن القديمتين في المستودع الذكي */
export function consolidateLegacyRepositoryDock(
    placements: HomeWidgetPlacements,
): HomeWidgetPlacements {
    const dockIds = getWidgetsInZone(placements, 'dock');
    const mainIds = getWidgetsInZone(placements, 'main');
    const hasLegacyOnSurface =
        dockIds.some(isRepositoryLegacyWidget) || mainIds.some(isRepositoryLegacyWidget);

    if (dockIds.includes('dockRepository')) {
        if (!hasLegacyOnSurface) return placements;
        const stashed = stashRepositoryLegacyWidgets(placements);
        return stashed.changed
            ? reindexZone(reindexZone(stashed.placements, 'main'), 'dock')
            : placements;
    }

    const hasLegacy = dockIds.includes('dockNotepad') || dockIds.includes('dockVault');
    if (!hasLegacy) return placements;

    const next = { ...placements };
    const legacyOrder = Math.min(
        dockIds.includes('dockNotepad') ? placements.dockNotepad?.order ?? 0 : 99,
        dockIds.includes('dockVault') ? placements.dockVault?.order ?? 0 : 99,
    );
    next.dockRepository = { zone: 'dock', order: legacyOrder };
    const stashed = stashRepositoryLegacyWidgets(next);
    return reindexZone(reindexZone(stashed.placements, 'main'), 'dock');
}

export const DOCK_ONLY_WIDGETS: HomeWidgetId[] = [
    'dockRepository',
    'dockNotepad',
    'dockCalendar',
    'dockVault',
    'dockTasks',
    'dockQuickNote',
];

export function defaultMainSpan(widgetId: HomeWidgetId): 1 | 2 {
    if (widgetId === 'alerts' || widgetId === 'forum') return 2;
    if (widgetId === 'hubExecution') return 2;
    return 1;
}

export type { BackgroundPresetId };

const DB_NAME = 'hami-vault-blobs';

const DB_VERSION = 1;

const STORE = 'files';

const IDB_OPEN_TIMEOUT_MS = 12_000;

const IDB_READ_TIMEOUT_MS = 10_000;

const IDB_OPEN_RETRY_MS = 400;

const IDB_WRITE_TIMEOUT_MIN_MS = 12_000;

const IDB_WRITE_TIMEOUT_MAX_MS = 120_000;



type VaultBlobRow = {

    key: string;

    authorId: string;

    docId: string;

    mimeType: string;

    size: number;

    blob: Blob;

    updatedAt: string;

};



function rowKey(authorId: string, docId: string): string {

    return `${authorId.trim()}:${docId.trim()}`;

}



export function buildVaultIdbPath(userId: string, docId: string): string {

    return `idb:vault:${userId.trim()}:${docId.trim()}`;

}



export function isVaultIdbStoragePath(path: string | undefined | null): boolean {

    return (path || '').startsWith('idb:vault:');

}



export function parseVaultIdbPath(path: string): { userId: string; docId: string } | null {

    if (!isVaultIdbStoragePath(path)) return null;

    const parts = path.split(':');

    if (parts.length < 4) return null;

    const userId = parts[2]?.trim();

    const docId = parts.slice(3).join(':').trim();

    if (!userId || !docId) return null;

    return { userId, docId };

}



const testBlobStore = new Map<string, VaultBlobRow>();

const runtimeBlobStore = new Map<string, VaultBlobRow>();

const hotBlobCache = new Map<string, Blob>();



let blobWriteChain: Promise<void> = Promise.resolve();



function useMemoryStore(): boolean {

    return import.meta.env.MODE === 'test' || import.meta.env.VITEST === true;

}



let cachedDb: IDBDatabase | null = null;

let openDbPromise: Promise<IDBDatabase | null> | null = null;



function resolveWriteTimeoutMs(blobSize: number): number {

    const perMbMs = 8_000;

    const estimated = Math.ceil(blobSize / (1024 * 1024)) * perMbMs;

    return Math.min(IDB_WRITE_TIMEOUT_MAX_MS, Math.max(IDB_WRITE_TIMEOUT_MIN_MS, estimated));

}



function openDbFresh(): Promise<IDBDatabase | null> {

    if (useMemoryStore()) return Promise.resolve(null);

    if (typeof indexedDB === 'undefined') return Promise.resolve(null);

    return new Promise((resolve) => {

        let settled = false;

        const finish = (db: IDBDatabase | null) => {

            if (settled) return;

            settled = true;

            clearTimeout(timer);

            resolve(db);

        };

        const timer = setTimeout(() => finish(null), IDB_OPEN_TIMEOUT_MS);

        try {

            const request = indexedDB.open(DB_NAME, DB_VERSION);

            request.onerror = () => finish(null);

            request.onsuccess = () => finish(request.result);

            request.onupgradeneeded = () => {

                const db = request.result;

                if (!db.objectStoreNames.contains(STORE)) {

                    db.createObjectStore(STORE, { keyPath: 'key' });

                }

            };

        } catch {

            finish(null);

        }

    });

}



function getDb(): Promise<IDBDatabase | null> {

    if (useMemoryStore()) return Promise.resolve(null);

    if (cachedDb) return Promise.resolve(cachedDb);

    if (!openDbPromise) {

        openDbPromise = openDbFresh()

            .then(async (db) => {

                if (!db) {

                    await new Promise((r) => setTimeout(r, IDB_OPEN_RETRY_MS));

                    db = await openDbFresh();

                }

                if (db) {

                    cachedDb = db;

                    db.onversionchange = () => {

                        cachedDb = null;

                        openDbPromise = null;

                        db.close();

                    };

                } else {

                    openDbPromise = null;

                }

                return db;

            })

            .catch(() => {

                openDbPromise = null;

                return null;

            });

    }

    return openDbPromise;

}



/** تسخين اتصال IDB — يُستدعى عند فتح المستودع أو اختيار ملف */

export function prefetchVaultBlobStore(): void {

    if (typeof window === 'undefined') return;

    void getDb();

}



/** يجعل الملف متاحاً فوراً للمعاينة قبل اكتمال كتابة IDB */

export function primeVaultBlobCache(authorId: string, docId: string, blob: Blob): void {

    hotBlobCache.set(rowKey(authorId, docId), blob);

}

/** قراءة متزامنة من الذاكرة — للمعاينة الفورية */
export function peekVaultBlob(authorId: string, docId: string): Blob | null {
    const key = rowKey(authorId, docId);
    const hot = hotBlobCache.get(key);
    if (hot) return hot;
    return runtimeBlobStore.get(key)?.blob ?? null;
}



function persistRuntimeBlobRow(row: VaultBlobRow): void {

    runtimeBlobStore.set(row.key, row);

}



function writeVaultBlobRowToIdb(row: VaultBlobRow, db: IDBDatabase): Promise<void> {

    const writeTimeoutMs = resolveWriteTimeoutMs(row.size);

    return new Promise<void>((resolve, reject) => {

        let settled = false;

        const finish = (error?: Error | null) => {

            if (settled) return;

            settled = true;

            clearTimeout(timer);

            if (error) reject(error);

            else resolve();

        };

        const timer = setTimeout(() => finish(new Error('vault blob write timeout')), writeTimeoutMs);

        const tx = db.transaction(STORE, 'readwrite');

        tx.oncomplete = () => finish();

        tx.onerror = () => finish(tx.error ?? new Error('vault blob write failed'));

        tx.onabort = () => finish(tx.error ?? new Error('vault blob write aborted'));

        tx.objectStore(STORE).put(row);

    });

}



function writeVaultBlobRow(row: VaultBlobRow): Promise<void> {

    if (useMemoryStore()) {

        testBlobStore.set(row.key, row);

        return Promise.resolve();

    }



    return getDb()

        .then((db) => {

            if (!db) {

                persistRuntimeBlobRow(row);

                return;

            }

            return writeVaultBlobRowToIdb(row, db).catch(() => {

                persistRuntimeBlobRow(row);

            });

        })

        .catch(() => {

            persistRuntimeBlobRow(row);

        });

}



export function putVaultBlob(

    authorId: string,

    docId: string,

    blob: Blob,

    mimeType: string,

): Promise<void> {

    const key = rowKey(authorId, docId);

    const row: VaultBlobRow = {

        key,

        authorId: authorId.trim(),

        docId: docId.trim(),

        mimeType: mimeType || blob.type || 'application/octet-stream',

        size: blob.size,

        blob,

        updatedAt: new Date().toISOString(),

    };



    primeVaultBlobCache(authorId, docId, blob);



    const writePromise = writeVaultBlobRow(row);

    blobWriteChain = blobWriteChain.then(() => writePromise).catch(() => undefined);

    return writePromise;

}



export function waitForVaultBlobWrites(): Promise<void> {

    return blobWriteChain;

}



export async function getVaultBlob(authorId: string, docId: string): Promise<Blob | null> {

    const key = rowKey(authorId, docId);

    const hot = hotBlobCache.get(key);

    if (hot) return hot;



    const runtime = runtimeBlobStore.get(key);

    if (runtime) return runtime.blob;



    if (useMemoryStore()) {

        return testBlobStore.get(key)?.blob ?? null;

    }



    const db = await getDb();

    if (!db) return null;

    return Promise.race<Blob | null>([
        new Promise((resolve) => {
            const tx = db.transaction(STORE, 'readonly');
            const req = tx.objectStore(STORE).get(key);
            req.onsuccess = () => {
                const row = req.result as VaultBlobRow | undefined;
                resolve(row?.blob ?? null);
            };
            req.onerror = () => resolve(null);
        }),
        new Promise((resolve) => {
            window.setTimeout(() => resolve(null), IDB_READ_TIMEOUT_MS);
        }),
    ]);
}



export async function getVaultBlobObjectUrl(
    authorId: string,
    docId: string,
    options?: { mimeType?: string | null },
): Promise<string | null> {

    const blob = await getVaultBlob(authorId, docId);

    if (!blob) return null;

    const hinted = (options?.mimeType || '').toLowerCase();
    if (hinted === 'application/pdf' && blob.type !== 'application/pdf') {
        return URL.createObjectURL(new Blob([blob], { type: 'application/pdf' }));
    }

    return URL.createObjectURL(blob);

}



export async function deleteVaultBlob(authorId: string, docId: string): Promise<void> {

    const key = rowKey(authorId, docId);

    hotBlobCache.delete(key);

    runtimeBlobStore.delete(key);

    if (useMemoryStore()) {

        testBlobStore.delete(key);

        return;

    }



    const db = await getDb();

    if (!db) return;



    await new Promise<void>((resolve) => {

        const tx = db.transaction(STORE, 'readwrite');

        tx.oncomplete = () => resolve();

        tx.onerror = () => resolve();

        tx.objectStore(STORE).delete(key);

    });

}



export async function deleteVaultBlobByPath(storagePath: string | undefined | null): Promise<void> {

    const parsed = parseVaultIdbPath(storagePath || '');

    if (!parsed) return;

    await deleteVaultBlob(parsed.userId, parsed.docId);

}



export async function clearAllVaultBlobs(): Promise<void> {

    hotBlobCache.clear();

    runtimeBlobStore.clear();

    if (useMemoryStore()) {

        testBlobStore.clear();

        return;

    }



    const db = await getDb();

    if (!db) return;



    await new Promise<void>((resolve) => {

        const tx = db.transaction(STORE, 'readwrite');

        tx.oncomplete = () => resolve();

        tx.onerror = () => resolve();

        tx.objectStore(STORE).clear();

    });

}



export function clearVaultBlobTestStore(): void {

    testBlobStore.clear();

}



export function resetVaultBlobStoreForTests(): void {

    cachedDb = null;

    openDbPromise = null;

    testBlobStore.clear();

    runtimeBlobStore.clear();

    hotBlobCache.clear();

    blobWriteChain = Promise.resolve();

}



