    employee_summons_assignments_by_debtor?: Record<string, EmployeeSummonsAssignmentState>;

    /**
     * تبليغ بالنشر (جريدتان) — لكل مدين عند تعدد الخصوم؛ المفتاح يطابق مفاتيح مساحة عمل المدين.
