    it('non-primary debtor does not inherit legacy root dates', () => {
        const file = baseFile({
            debtorNotificationDate: '2026-03-01',
            activeNoticeState: 'forced_attendance',
        });
        const s = getDebtorNoticeStateForKey(file, extraKey, primaryKey);
