    appealRequestOrigin?: 'creditor_side' | 'debtor_side' | 'executor_side';
    /** عنوان صف مركز القرارات (افتراضي: طلب تنفيذي خاص) */
    decisionTitle?: string;
    /** حمولة منظمة لطلبات خاصة (مثل التوحيد) */
    payloadJson?: string;
}): string | null {
