// @ts-nocheck
import { lazy, type ComponentType, type LazyExoticComponent } from 'react';
import { resetLawyerDashboardModuleCache } from '@/app/runtime/lawyerDashboardLoader';

export type LazyComponent = ComponentType<Record<string, unknown>>;

const LAZY_IMPORT_TIMEOUT_MS = 18_000;

function isDynamicImportFetchError(error: unknown): boolean {
    const msg = error instanceof Error ? error.message : String(error);
    return (
        /Failed to fetch dynamically imported module/i.test(msg) ||
        /Importing a module script failed/i.test(msg) ||
        /error loading dynamically imported module/i.test(msg)
    );
}

function toLoadError(error: unknown): Error {
    const generic = 'فشل في تحميل المكون. تأكد من الاتصال ثم أعد المحاولة.';
    const cause =
        error instanceof Error
            ? error.message
            : typeof error === 'string'
              ? error
              : '';
    const message =
        import.meta.env.DEV && cause && !cause.includes(generic)
            ? `${generic} (${cause})`
            : generic;
    if (error instanceof Error && import.meta.env.DEV) {
        const wrapped = new Error(message);
        wrapped.stack = error.stack;
        wrapped.cause = error;
        return wrapped;
    }
    if (error instanceof Error && !isDynamicImportFetchError(error)) return error;
    return new Error(message);
}

async function loadLazyModule(
    componentImport: () => Promise<{ default: LazyComponent }>,
    retriesLeft: number,
    attempt = 0,
): Promise<{ default: LazyComponent }> {
    try {
        return await componentImport();
    } catch (error) {
        if (retriesLeft > 0) {
            if (isDynamicImportFetchError(error)) {
                resetLawyerDashboardModuleCache();
            }
            const delayMs = Math.min(200 * 2 ** attempt, 2_000);
            await new Promise((resolve) => setTimeout(resolve, delayMs));
            return loadLazyModule(componentImport, retriesLeft - 1, attempt + 1);
        }
        throw toLoadError(error);
    }
}

function importWithTimeout(
    componentImport: () => Promise<{ default: LazyComponent }>,
    retries: number,
): Promise<{ default: LazyComponent }> {
    return new Promise<{ default: LazyComponent }>((resolve, reject) => {
        let settled = false;
        const timeoutId = window.setTimeout(() => {
            if (settled) return;
            settled = true;
            reject(new Error('انتهت مهلة تحميل المكون. تحقق من الاتصال ثم أعد المحاولة.'));
        }, LAZY_IMPORT_TIMEOUT_MS);

        const finish = (fn: () => void) => {
            if (settled) return;
            settled = true;
            window.clearTimeout(timeoutId);
            fn();
        };

        const attemptImport = (retriesLeft: number) => {
            componentImport()
                .then((mod) => finish(() => resolve(mod)))
                .catch((error: unknown) => {
                    if (retriesLeft === 0) {
                        finish(() => reject(toLoadError(error)));
                        return;
                    }
                    if (isDynamicImportFetchError(error)) {
                        resetLawyerDashboardModuleCache();
                    }
                    window.setTimeout(() => attemptImport(retriesLeft - 1), 1000);
                });
        };

        attemptImport(retries);
    });
}

/** إعادة محاولة عند فشل dynamic import — بدون إعادة تحميل الصفحة (تُدار عبر GlobalErrorBoundary). */
export function lazyWithRetry(
    componentImport: () => Promise<{ default: LazyComponent }>,
    retries: number = 3,
): LazyExoticComponent<LazyComponent> {
    if (import.meta.env.DEV) {
        return lazy(() => loadLazyModule(componentImport, 4));
    }
    return lazy(() => importWithTimeout(componentImport, retries));
}

/**
 * Lazy واعٍ بالتحميل المسبق — React.lazy يعلّق (Suspense) عند أول تركيب حتى لو
 * كانت الوحدة محمّلة، فيومض الهيكل إطاراً كاملاً. هنا: إذا اكتمل preload
 * نرسم المكوّن الحقيقي مباشرة في نفس الـ commit — صفر تعليق، صفر وميض.
 */
import React from 'react';
import { lazyWithRetry, type LazyComponent } from '@/app/utils/lazy/lazyWithRetry';

type ModuleWithDefault<P> = { default: React.ComponentType<P> };

export type PreloadableLazyComponent<P> = React.FC<P> & {
    /** يحمّل الوحدة ويثبّتها للرسم المباشر — آمن للاستدعاء المتكرر */
    preload: () => Promise<void>;
    /** هل اكتمل التحميل وثُبّت المكوّن؟ */
    isPreloaded: () => boolean;
};

export function createPreloadableLazyComponent<P extends Record<string, any>>(
    importer: () => Promise<ModuleWithDefault<P>>,
): PreloadableLazyComponent<P> {
    let Resolved: React.ComponentType<P> | null = null;
    let modulePromise: Promise<ModuleWithDefault<P>> | null = null;

    const load = (): Promise<ModuleWithDefault<P>> => {
        if (!modulePromise) {
            modulePromise = importer()
                .then((mod) => {
                    Resolved = mod.default;
                    return mod;
                })
                .catch((err: unknown) => {
                    // فشل الشبكة لا يثبّت وعداً ميتاً — المحاولة التالية تعيد الاستيراد
                    modulePromise = null;
                    throw err;
                });
        }
        return modulePromise;
    };

    // مسار التعليق (البارد) يمر عبر lazyWithRetry — إعادة محاولة عند فشل الشبكة
    const Lazy = lazyWithRetry(
        load as unknown as () => Promise<{ default: LazyComponent }>,
    ) as unknown as React.ComponentType<P>;

    function PreloadableLazy(props: P) {
        // إن اكتمل preload (أثناء الأرشيف/الإقلاع) ارسم المباشر فوراً —
        // useState كان يُثبّت Lazy إلى الأبد حتى بعد اكتمال التحميل لنفس الـ instance.
        if (Resolved) {
            return <Resolved {...props} />;
        }
        return <Lazy {...props} />;
    }

    const out = PreloadableLazy as PreloadableLazyComponent<P>;
    out.preload = () =>
        load().then(
            () => undefined,
            () => undefined,
        );
    out.isPreloaded = () => Resolved != null;
    return out;
}

/**
 * Smart logger — verbose in development only when opt-in console is enabled.
 * Errors always surface. Enable: hamiVerboseConsole(true) then reload.
 */

import { isVerboseConsoleEnabled } from '@/app/utils/consoleHygiene';

const isDevelopment = import.meta.env.DEV;
const isTest =
    import.meta.env.MODE === 'test' ||
    (typeof process !== 'undefined' && process.env.NODE_ENV === 'test');

function allowVerbose(): boolean {
    return isDevelopment && !isTest && isVerboseConsoleEnabled();
}

export const logger = {
    /**
     * Log general information
     */
    log: (...args: unknown[]) => {
        if (allowVerbose()) {
            console.log(...args);
        }
    },

    /**
     * Log warnings
     */
    warn: (...args: unknown[]) => {
        if (allowVerbose()) {
            console.warn(...args);
        }
    },

    /**
     * Log errors (kept in production for monitoring)
     */
    error: (...args: unknown[]) => {
        console.error(...args);
        // في الإنتاج، يمكن إرسال الأخطاء لخدمة monitoring
        if (!isDevelopment) {
            // TODO: Send to error monitoring service (Sentry, etc.)
        }
    },

    /**
     * Log debug information (development only)
     */
    debug: (...args: unknown[]) => {
        if (allowVerbose()) {
            console.debug(...args);
        }
    },

    /**
     * Group logs together
     */
    group: (label: string, ...args: unknown[]) => {
        if (allowVerbose()) {
            console.group(label);
            args.forEach(arg => console.log(arg));
            console.groupEnd();
        }
    },

    /**
     * Log with timestamp
     */
    timestamped: (message: string, ...args: unknown[]) => {
        if (allowVerbose()) {
            const timestamp = new Date().toISOString();
            console.log(`[${timestamp}] ${message}`, ...args);
        }
    },

    /**
     * Performance logging
     */
    performance: (label: string, callback: () => void) => {
        if (allowVerbose()) {
            const start = performance.now();
            callback();
            const end = performance.now();
            console.log(`⏱️ ${label}: ${(end - start).toFixed(2)}ms`);
        } else {
            callback();
        }
    },

    /**
     * Conditional logging based on condition
     */
    logIf: (condition: boolean, ...args: unknown[]) => {
        if (allowVerbose() && condition) {
            console.log(...args);
        }
    },

    /**
     * Log with color (development only)
     */
    colored: (color: string, message: string, ...args: unknown[]) => {
        if (allowVerbose()) {
            console.log(`%c${message}`, `color: ${color}`, ...args);
        }
    },

    /**
     * Success log (green)
     */
    success: (message: string, ...args: unknown[]) => {
        if (allowVerbose()) {
            console.log(`%c✅ ${message}`, 'color: #22c55e', ...args);
        }
    },

    /**
     * Info log (blue)
     */
    info: (message: string, ...args: unknown[]) => {
        if (allowVerbose()) {
            console.log(`%cℹ️ ${message}`, 'color: #3b82f6', ...args);
        }
    },

    /**
     * Table logging for arrays/objects
     */
    table: (data: unknown) => {
        if (allowVerbose()) {
            console.table(data);
        }
    },
};

/**
 * Performance measurement decorator
 */
export function measurePerformance(_target: unknown, propertyKey: string, descriptor: PropertyDescriptor) {
    const originalMethod = descriptor.value;
    
    descriptor.value = function (...args: unknown[]) {
        if (allowVerbose()) {
            const start = performance.now();
            const result = originalMethod.apply(this, args);
            const end = performance.now();
            logger.info(`${propertyKey} executed in ${(end - start).toFixed(2)}ms`);
            return result;
        }
        return originalMethod.apply(this, args);
    };
    
    return descriptor;
}

/**
 * Component render logger
 */
export const logRender = (componentName: string, props?: unknown) => {
    if (allowVerbose()) {
        logger.group(`🔄 ${componentName} rendered`, props);
    }
};

