export type PartyDeathCaseRecord = NonNullable<ExecutionFile['party_death_case']>;

/** مسار وفاة/ورثة طرف واحد — لا يخلط بين الدائن والمدين */
export function getPartyDeathCaseForRole(
    file: ExecutionFile | null | undefined,
    role: 'creditor' | 'debtor'
): PartyDeathCaseRecord | null | undefined {
    const scoped =
        role === 'creditor' ? file?.creditor_party_death_case : file?.debtor_party_death_case;
    if (scoped) return scoped;
    const legacy = file?.party_death_case;
    if (legacy?.deceased_party === role) return legacy;
    return null;
}

export function isPartyDeathCaseForRole(
    file: ExecutionFile | null | undefined,
    role: 'creditor' | 'debtor'
): boolean {
    return getPartyDeathCaseForRole(file, role) != null;
}

/** دمج حفظ — يحدّث مسار الطرف المحدد دون المساس بمسار الطرف الآخر */
export function buildScopedPartyDeathPersistPatch(
    base: ExecutionFile | null | undefined,
    role: 'creditor' | 'debtor',
    nextCase: PartyDeathCaseRecord
): Pick<ExecutionFile, 'creditor_party_death_case' | 'debtor_party_death_case'> {
    const creditorCase =
        role === 'creditor' ? nextCase : (getPartyDeathCaseForRole(base, 'creditor') ?? null);
    const debtorCase = role === 'debtor' ? nextCase : (getPartyDeathCaseForRole(base, 'debtor') ?? null);
    return {
        creditor_party_death_case: creditorCase,
        debtor_party_death_case: debtorCase,
    };
}

/**
 * ═══════════════════════════════════════════════════════════════════════════
 * ⚡ Performance Monitor - Real-time Performance Tracking
 * ═══════════════════════════════════════════════════════════════════════════
 * 
 * Monitors and tracks application performance metrics
 * مراقبة وتتبع مقاييس أداء التطبيق
 * 
 * @version 1.0.0
 * @author Hami Legal System - Performance Suite
 */

// ═══════════════════════════════════════════════════════════════════════════
// TYPES
// ═══════════════════════════════════════════════════════════════════════════

interface PerformanceMetric {
    name: string;
    duration: number;
    timestamp: number;
    metadata?: Record<string, unknown>;
}

interface PerformanceReport {
    metrics: PerformanceMetric[];
    averages: Record<string, number>;
    slowest: PerformanceMetric[];
    fastest: PerformanceMetric[];
}

// ═══════════════════════════════════════════════════════════════════════════
// PERFORMANCE MONITOR CLASS
// ═══════════════════════════════════════════════════════════════════════════

class PerformanceMonitorClass {
    private metrics: PerformanceMetric[] = [];
    private readonly maxMetrics = 1000;
    private marks: Map<string, number> = new Map();

    /**
     * Start measuring a performance metric
     */
    start(name: string): void {
        this.marks.set(name, performance.now());
    }

    /**
     * End measuring and record the metric
     */
    end(name: string, metadata?: Record<string, unknown>): number {
        const startTime = this.marks.get(name);
        if (!startTime) {
            return 0;
        }

        const duration = performance.now() - startTime;
        
        this.metrics.push({
            name,
            duration,
            timestamp: Date.now(),
            metadata
        });

        // Cleanup old metrics if we exceed max
        if (this.metrics.length > this.maxMetrics) {
            this.metrics = this.metrics.slice(-this.maxMetrics);
        }

        this.marks.delete(name);
        return duration;
    }

    /**
     * Measure a synchronous function
     */
    measure<T>(name: string, fn: () => T, metadata?: Record<string, unknown>): T {
        this.start(name);
        try {
            const result = fn();
            return result;
        } finally {
            this.end(name, metadata);
        }
    }

    /**
     * Measure an async function
     */
    async measureAsync<T>(
        name: string, 
        fn: () => Promise<T>,
        metadata?: Record<string, unknown>
    ): Promise<T> {
        this.start(name);
        try {
            const result = await fn();
            return result;
        } finally {
            this.end(name, metadata);
        }
    }

    /**
     * Get metrics for a specific name
     */
    getMetrics(name?: string): PerformanceMetric[] {
        if (!name) return [...this.metrics];
        return this.metrics.filter(m => m.name === name);
    }

    /**
     * Get average duration for a metric
     */
    getAverage(name: string): number {
        const metrics = this.getMetrics(name);
        if (metrics.length === 0) return 0;
        
        const sum = metrics.reduce((acc, m) => acc + m.duration, 0);
        return sum / metrics.length;
    }

    /**
     * Get performance report
     */
    getReport(): PerformanceReport {
        // Calculate averages
        const averages: Record<string, number> = {};
        const metricNames = new Set(this.metrics.map(m => m.name));
        
        metricNames.forEach(name => {
            averages[name] = this.getAverage(name);
        });

        // Get slowest and fastest
        const sorted = [...this.metrics].sort((a, b) => b.duration - a.duration);
        const slowest = sorted.slice(0, 10);
        const fastest = sorted.slice(-10).reverse();

        return {
            metrics: [...this.metrics],
            averages,
            slowest,
            fastest
        };
    }

    /**
     * Clear all metrics
     */
    clear(): void {
        this.metrics = [];
        this.marks.clear();
    }

    /**
     * Log performance report to console
     */
    logReport(): void {
        const report = this.getReport();
        if (report.metrics.length === 0) return;

        console.group('📊 Performance Report');
        console.log('Total Metrics:', report.metrics.length);

        console.group('⚡ Averages');
        Object.entries(report.averages).forEach(([name, avg]) => {
            console.log(`${name}: ${avg.toFixed(2)}ms`);
        });
        console.groupEnd();

        if (report.slowest.length > 0) {
            console.group('🐌 Slowest Operations');
            report.slowest.forEach((m, i) => {
                console.log(`${i + 1}. ${m.name}: ${m.duration.toFixed(2)}ms`);
            });
            console.groupEnd();
        }

        if (report.fastest.length > 0) {
            console.group('🚀 Fastest Operations');
            report.fastest.forEach((m, i) => {
                console.log(`${i + 1}. ${m.name}: ${m.duration.toFixed(2)}ms`);
            });
            console.groupEnd();
        }

        console.groupEnd();
    }

    /**
     * Get performance score (0-100)
     */
    getScore(): number {
        const report = this.getReport();
        const averages = Object.values(report.averages);
        
        if (averages.length === 0) return 100;
        
        const avgDuration = averages.reduce((a, b) => a + b, 0) / averages.length;
        
        // Score based on average duration
        // < 50ms = 100, > 500ms = 0
        if (avgDuration < 50) return 100;
        if (avgDuration > 500) return 0;
        
        return Math.round(100 - ((avgDuration - 50) / 450) * 100);
    }
}

