import type { Debtor, ExecutionFile } from '@/app/types/execution';
import { isDebtorRowEmployee } from '@/app/stores';

/** مهنة المدين لمصفوفة الحجز */
export type SeizureDebtorJob = 'employee' | 'kasib';

/** نوع المدين لمصفوفة الحجز */
export type SeizureDebtorType = 'natural_person' | 'government';

export type SeizureMatrixRuleId =
    | 'rule_0_government'
    | 'rule_1_zero'
    | 'rule_2_soft'
    | 'rule_3_tier1'
    | 'rule_4_tier2'
    | 'rule_5_full';

export type SeizureMatrixButtonKey = 'salary' | 'movable' | 'third_party' | 'property';

export type SeizureMatrixButtons = Record<SeizureMatrixButtonKey, boolean>;

export interface SeizureMatrixInput {
    /** الرصيد المتبقي بذمة المدين — حصراً من المركز المالي */
    remainingBalanceIqd: number;
    debtorJob: SeizureDebtorJob;
    debtorType: SeizureDebtorType;
    /** بعد موافقة المحامي في الحالة الأولى (1–2 مليون) */
    lawyerSoftOptIn?: boolean;
}

export interface SeizureProgressiveDisclosure {
    showAdditionalExpand: boolean;
    additionalButtons: SeizureMatrixButtonKey[];
    showMaximumExpand: boolean;
    maximumButtons: SeizureMatrixButtonKey[];
}

export interface SeizureMatrixResult {
    ruleId: SeizureMatrixRuleId;
    remainingBalanceIqd: number;
    hideSeizureTab: boolean;
    requiresSoftActivationModal: boolean;
    showTabContentButtons: boolean;
    allSeizureDisabled: boolean;
    buttons: SeizureMatrixButtons;
    progressiveDisclosure: SeizureProgressiveDisclosure;
}

const TIER_SOFT_MAX = 2_000_000;
const TIER1_MAX = 5_000_000;
const TIER2_MAX = 15_000_000;

const ALL_BUTTONS_OFF: SeizureMatrixButtons = {
    salary: false,
    movable: false,
    third_party: false,
    property: false,
};

function withButtons(partial: Partial<SeizureMatrixButtons>): SeizureMatrixButtons {
    return { ...ALL_BUTTONS_OFF, ...partial };
}

function rule2OptInButtons(job: SeizureDebtorJob): SeizureMatrixButtons {
    if (job === 'employee') return withButtons({ salary: true });
    return withButtons({ movable: true });
}

function tierBaseButtons(job: SeizureDebtorJob): SeizureMatrixButtons {
    if (job === 'employee') return withButtons({ salary: true, movable: true });
    return withButtons({ movable: true });
}

export function resolveSeizureButtonLadder(job: SeizureDebtorJob): SeizureMatrixButtonKey[] {
    if (job === 'employee') return ['salary', 'movable', 'third_party', 'property'];
    return ['movable', 'third_party', 'property'];
}

/** تقسيم الخيارات المخفية إلى كشف تدريجي: إضافية ثم قصوى */
export function computeSeizureProgressiveDisclosure(
    recommended: SeizureMatrixButtons,
    job: SeizureDebtorJob
): SeizureProgressiveDisclosure {
    const ladder = resolveSeizureButtonLadder(job);
    const hidden = ladder.filter((key) => !recommended[key]);
    if (hidden.length === 0) {
        return {
            showAdditionalExpand: false,
            additionalButtons: [],
            showMaximumExpand: false,
            maximumButtons: [],
        };
    }
    if (hidden.length === 1) {
        return {
            showAdditionalExpand: true,
            additionalButtons: hidden,
            showMaximumExpand: false,
            maximumButtons: [],
        };
    }
    return {
        showAdditionalExpand: true,
        additionalButtons: [hidden[0]],
        showMaximumExpand: true,
        maximumButtons: hidden.slice(1),
    };
}

function finalizeMatrixResult(
    partial: Omit<SeizureMatrixResult, 'progressiveDisclosure'>,
    job: SeizureDebtorJob
): SeizureMatrixResult {
    return {
        ...partial,
        progressiveDisclosure: computeSeizureProgressiveDisclosure(partial.buttons, job),
    };
}

export function computeSeizureMatrix(input: SeizureMatrixInput): SeizureMatrixResult {
    const remaining = Math.max(0, Math.round(Number(input.remainingBalanceIqd) || 0));

    if (input.debtorType === 'government') {
        return finalizeMatrixResult(
            {
                ruleId: 'rule_0_government',
                remainingBalanceIqd: remaining,
                hideSeizureTab: true,
                requiresSoftActivationModal: false,
                showTabContentButtons: false,
                allSeizureDisabled: true,
                buttons: ALL_BUTTONS_OFF,
            },
            input.debtorJob
        );
    }

    if (remaining === 0) {
        return finalizeMatrixResult(
            {
                ruleId: 'rule_1_zero',
                remainingBalanceIqd: 0,
                hideSeizureTab: true,
                requiresSoftActivationModal: false,
                showTabContentButtons: false,
                allSeizureDisabled: true,
                buttons: ALL_BUTTONS_OFF,
            },
            input.debtorJob
        );
    }

    if (remaining <= TIER_SOFT_MAX) {
        return finalizeMatrixResult(
            {
                ruleId: 'rule_2_soft',
                remainingBalanceIqd: remaining,
                hideSeizureTab: false,
                requiresSoftActivationModal: false,
                showTabContentButtons: true,
                allSeizureDisabled: false,
                buttons: rule2OptInButtons(input.debtorJob),
            },
            input.debtorJob
        );
    }

    if (remaining <= TIER1_MAX) {
        return finalizeMatrixResult(
            {
                ruleId: 'rule_3_tier1',
                remainingBalanceIqd: remaining,
                hideSeizureTab: false,
                requiresSoftActivationModal: false,
                showTabContentButtons: true,
                allSeizureDisabled: false,
                buttons: tierBaseButtons(input.debtorJob),
            },
            input.debtorJob
        );
    }

    if (remaining <= TIER2_MAX) {
        return finalizeMatrixResult(
            {
                ruleId: 'rule_4_tier2',
                remainingBalanceIqd: remaining,
                hideSeizureTab: false,
                requiresSoftActivationModal: false,
                showTabContentButtons: true,
                allSeizureDisabled: false,
                buttons: withButtons({
                    ...tierBaseButtons(input.debtorJob),
                    third_party: true,
                }),
            },
            input.debtorJob
        );
    }

    return finalizeMatrixResult(
        {
            ruleId: 'rule_5_full',
            remainingBalanceIqd: remaining,
            hideSeizureTab: false,
            requiresSoftActivationModal: false,
            showTabContentButtons: true,
            allSeizureDisabled: false,
            buttons: withButtons({
                ...tierBaseButtons(input.debtorJob),
                third_party: true,
                property: true,
            }),
        },
        input.debtorJob
    );
}

const GOVERNMENT_ENTITY_MARKERS =
    /دائرة\s*حكومية|جهة\s*حكومية|وزارة|محافظة|بلدية|مؤسسة\s*حكومية|هيئة\s*حكومية/i;

export function resolveSeizureDebtorType(
    debtor: Debtor | undefined,
    executionData?: ExecutionFile | Record<string, unknown> | null
): SeizureDebtorType {
    const ed = executionData as Record<string, unknown> | null | undefined;
    const explicit = String(
        ed?.debtor_entity_type ?? (debtor as { entityType?: string } | undefined)?.entityType ?? ''
    ).trim();
    if (
        explicit === 'government' ||
        explicit === 'حكومي' ||
        explicit === 'دائرة حكومية' ||
        explicit === 'جهة حكومية'
    ) {
        return 'government';
    }
    const occ = String(debtor?.occupation ?? '').trim();
    if (GOVERNMENT_ENTITY_MARKERS.test(occ)) return 'government';
    const name = String(debtor?.name ?? debtor?.fullName ?? '').trim();
    if (GOVERNMENT_ENTITY_MARKERS.test(name)) return 'government';
    return 'natural_person';
}

export function resolveSeizureDebtorJob(
    debtor: Debtor | undefined,
    activeDebtorIsEmployee?: boolean
): SeizureDebtorJob {
    if (activeDebtorIsEmployee || isDebtorRowEmployee(debtor)) return 'employee';
    const occ = String(debtor?.occupation ?? '').toLowerCase();
    if (occ === 'موظف' || occ.includes('موظف')) return 'employee';
    return 'kasib';
}

export function resolveSeizureMatrixFromExecution(args: {
    remainingBalanceIqd: number;
    executionData?: ExecutionFile | null;
    activeDebtor?: Debtor;
    activeDebtorIsEmployee?: boolean;
}): SeizureMatrixResult {
    const debtor =
        args.activeDebtor ??
        (Array.isArray(args.executionData?.debtors) ? args.executionData?.debtors[0] : undefined);
    return computeSeizureMatrix({
        remainingBalanceIqd: args.remainingBalanceIqd,
        debtorJob: resolveSeizureDebtorJob(debtor, args.activeDebtorIsEmployee),
        debtorType: resolveSeizureDebtorType(debtor, args.executionData),
        lawyerSoftOptIn: Boolean(
            (args.executionData as Record<string, unknown> | null | undefined)?.seizure_matrix_soft_opt_in
        ),
    });
}

// @ts-nocheck
import {
    readExecutorDecisionsFromActiveNamespace,
    writeExecutorDecisionsArray,
} from '@/app/utils/executionDecisionsNamespace';
import {
    dispatchDomainIsolationBlocked,
    gateExecutorRequestPersist,
    readExecutionDataForDomainGate,
} from '@/app/utils/executionDomainIsolation';
import { resolveDecisionsStorageExecutionId } from '@/app/components/lawyer/DecisionsAndAppealsEngine/engine/resolveDecisionsStorageExecutionId';

export const DECISIONS_RELOAD_EVENT = 'hami-decisions-reload';

function dispatchDecisionsReload(): void {
    try {
        window.dispatchEvent(new CustomEvent(DECISIONS_RELOAD_EVENT));
    } catch {
        /* ignore */
    }
}

function executorDecisionRowHubDefaults(): { status: 'pending'; appealPhase: null } {
    return { status: 'pending', appealPhase: null };
}

function newExecutorDecisionId(prefix: string): string {
    const c = (globalThis as any).crypto as { randomUUID?: () => string } | undefined;
    const uuid = c?.randomUUID?.();
    if (uuid) return `${prefix}_${uuid}`;
    return `${prefix}_${Date.now()}_${Math.random().toString(16).slice(2)}`;
}

function assertSpecialFollowupDomainGate(executionId: string | undefined): boolean {
    const gate = gateExecutorRequestPersist(executionId, 'special_followup');
    if (!gate.allowed) {
        dispatchDomainIsolationBlocked(gate.reasonAr || 'الطلب غير مسموح في هذا المسار', 'special_followup');
        return false;
    }
    return true;
}

function readActiveSpecialFollowupDecisions(executionId: string | undefined): Record<string, unknown>[] {
    return readExecutorDecisionsFromActiveNamespace(
        executionId,
        readExecutionDataForDomainGate(executionId),
    );
}

function persistSpecialFollowupDecisions(
    executionId: string | undefined,
    rows: Record<string, unknown>[],
): void {
    const data = readExecutionDataForDomainGate(executionId);
    const persistId = resolveDecisionsStorageExecutionId(executionId, data);
    writeExecutorDecisionsArray(persistId !== 'default' ? persistId : executionId, rows, data);
    dispatchDecisionsReload();
}

export function appendSpecialFollowupRequest(input: {
    executionId: string | undefined;
    requestDate: string;
    content: string;
    appealRequestOrigin?: 'creditor_side' | 'debtor_side' | 'executor_side';
    decisionTitle?: string;
    payloadJson?: string;
}): string | null {
    if (!assertSpecialFollowupDomainGate(input.executionId)) {
        return null;
    }

    const trimmed = String(input.content || '').trim();
    const body = `بتاريخ ${input.requestDate}:\n\n${trimmed}`;
    const rowId = newExecutorDecisionId('special_followup');

    try {
        const rows = readActiveSpecialFollowupDecisions(input.executionId);
        const resolvedTitle = String(input.decisionTitle || '').trim() || 'طلب تنفيذي خاص';
        const payloadJson = String(input.payloadJson || '').trim();
        const dupPending = rows.some((row) => {
            const pending =
                (row as any).executorOutcome === 'pending' || (row as any).executorOutcome === undefined;
            if (!pending) return false;
            if (String((row as any).requestKind || '') !== 'special_followup') return false;
            return (
                String((row as any).title || '').trim() === resolvedTitle &&
                String((row as any).body || '').trim() === body &&
                String((row as any).payloadJson || '').trim() === payloadJson
            );
        });
        if (dupPending) {
            dispatchDecisionsReload();
            return null;
        }

        rows.unshift({
            id: rowId,
            title: resolvedTitle,
            body,
            date: input.requestDate,
            appealStatus: 'pending' as const,
            executorOutcome: 'pending' as const,
            requestKind: 'special_followup' as const,
            ...(payloadJson ? { payloadJson } : {}),
            ...(input.appealRequestOrigin ? { appealRequestOrigin: input.appealRequestOrigin } : {}),
            ...executorDecisionRowHubDefaults(),
        });

        persistSpecialFollowupDecisions(input.executionId, rows);
        return rowId;
    } catch {
        return null;
    }
}

/**
 * Storage Cache Layer
 * طبقة تخزين مؤقت لتحسين أداء LocalStorage (بدون تأثير على التصميم)
 */
import SecureStoreService from '@/app/services/SecureStoreService';
import {
  applyExecutionDossierBlobSet,
  isExecutionDossierMainBlobKey,
  readExecutionDossierBlob,
  registerExecutionBlobCacheTouch,
} from '@/app/utils/executionDossierBlobPersistence';
import { executionDossierIdFromStorageKey } from '@/app/utils/executionStorageKeys';

function readExecutionDossierCacheValue(key: string): Record<string, unknown> | null {
  if (!isExecutionDossierMainBlobKey(key)) return null;
  const dossierId = executionDossierIdFromStorageKey(key);
  if (!dossierId) return null;
  const blob = readExecutionDossierBlob(dossierId);
  return blob && typeof blob === 'object' ? blob : null;
}

function executionDossierValueExistsInStorage(key: string): boolean {
  return readExecutionDossierCacheValue(key) != null;
}

interface CacheEntry {
  value: any;
  timestamp: number;
}

class StorageCacheClass {
  private cache: Map<string, CacheEntry> = new Map();
  private readonly TTL = 5 * 60 * 1000; // 5 دقائق
  private isEnabled: boolean = true;

  /**
   * تفعيل/تعطيل الـ Cache
   */
  setEnabled(enabled: boolean): void {
    this.isEnabled = enabled;
    if (!enabled) {
      this.cache.clear();
    }
  }

  /**
   * قراءة من الـ Cache أو LocalStorage
   */
  get(key: string): any | null {
    if (!this.isEnabled) {
      return this.readFromLocalStorage(key);
    }

    const cached = this.cache.get(key);

    if (cached) {
      if (Date.now() - cached.timestamp > this.TTL) {
        this.cache.delete(key);
        return this.get(key);
      }
      // إن حُذف المفتاح من SecureStore مباشرةً — لا نُرجع قيمة قديمة من الذاكرة
      try {
        const stillExists = isExecutionDossierMainBlobKey(key)
          ? executionDossierValueExistsInStorage(key)
          : SecureStoreService.getItemSync(key) !== null;
        if (!stillExists) {
          this.cache.delete(key);
          return null;
        }
      } catch {
        this.cache.delete(key);
        return null;
      }
      return cached.value;
    }

    const value = this.readFromLocalStorage(key);
    if (value !== null) {
      this.cache.set(key, {
        value,
        timestamp: Date.now(),
      });
    }
    return value;
  }

  /**
   * تحديث الذاكرة المؤقتة فقط — بعد كتابة SecureStore مباشرة
   */
  touchCacheEntry(key: string, value: any): void {
    if (!this.isEnabled) return;
    this.cache.set(key, {
      value,
      timestamp: Date.now(),
    });
  }

  /**
   * الكتابة إلى الـ Cache و LocalStorage
   */
  set(key: string, value: any): void {
    if (applyExecutionDossierBlobSet(key, value, (k, v) => this.touchCacheEntry(k, v))) {
      return;
    }
    // الكتابة إلى localStorage
    try {
      SecureStoreService.setItemSync(key, JSON.stringify(value));
    } catch (e) {
      console.error('[StorageCache] فشل الحفظ في localStorage:', e);
      return;
    }

    // الكتابة إلى الـ Cache
    if (this.isEnabled) {
      this.cache.set(key, {
        value,
        timestamp: Date.now()
      });
    }
  }

  /**
   * حذف من الـ Cache و LocalStorage
   */
  remove(key: string): void {
    this.cache.delete(key);
    try {
      SecureStoreService.deleteItemSync(key);
    } catch (e) {
      console.error('[StorageCache] فشل الحذف من localStorage:', e);
    }
  }

  /**
   * إلغاء صلاحية key معين من الـ Cache فقط
   */
  invalidate(key: string): void {
    this.cache.delete(key);
  }

  /**
   * مسح الـ Cache بالكامل (بدون تأثير على localStorage)
   */
  clear(): void {
    this.cache.clear();
  }

  /**
   * مسح الـ Cache و LocalStorage
   */
  clearAll(): void {
    this.cache.clear();
    try {
      const appKeyPrefixes = ['hami_', 'hami:', 'lawyer_', 'execution_', 'lawsuit_', 'client_', 'notes_', 'cache_'];
      const keys = SecureStoreService.listKeysSync();
      keys.forEach((k) => {
        if (appKeyPrefixes.some((p) => k.startsWith(p))) {
          SecureStoreService.deleteItemSync(k);
        }
      });
    } catch (e) {
      console.error('[StorageCache] فشل مسح localStorage:', e);
    }
  }

  /**
   * الحصول على حجم الـ Cache
   */
  getCacheSize(): number {
    return this.cache.size;
  }

  /**
   * الحصول على إحصائيات الـ Cache
   */
  getStats(): {
    cacheSize: number;
    oldestEntry: number | null;
    newestEntry: number | null;
  } {
    let oldestTimestamp: number | null = null;
    let newestTimestamp: number | null = null;

    this.cache.forEach((entry) => {
      if (oldestTimestamp === null || entry.timestamp < oldestTimestamp) {
        oldestTimestamp = entry.timestamp;
      }
      if (newestTimestamp === null || entry.timestamp > newestTimestamp) {
        newestTimestamp = entry.timestamp;
      }
    });

    return {
      cacheSize: this.cache.size,
      oldestEntry: oldestTimestamp,
      newestEntry: newestTimestamp
    };
  }

  /**
   * قراءة من LocalStorage مع معالجة الأخطاء
   */
  private readFromLocalStorage(key: string): any | null {
    try {
      const dossierBlob = readExecutionDossierCacheValue(key);
      if (dossierBlob) return dossierBlob;

      const value = SecureStoreService.getItemSync(key);
      if (value === null) return null;

      try {
        return JSON.parse(value);
      } catch {
        // إذا لم يكن JSON، أرجع النص كما هو
        return value;
      }
    } catch (e) {
      console.error('[StorageCache] فشل القراءة من localStorage:', e);
      return null;
    }
  }

  /**
   * تنظيف الـ entries القديمة
   */
  cleanup(): number {
    const now = Date.now();
    let removed = 0;

    this.cache.forEach((entry, key) => {
      if (now - entry.timestamp > this.TTL) {
        this.cache.delete(key);
        removed++;
      }
    });

    if (removed > 0 && import.meta.env.DEV) {
      console.log(`🧹 [StorageCache] تم تنظيف ${removed} إدخال قديم`);
    }

    return removed;
  }
}

// Singleton Instance
export const storageCache = new StorageCacheClass();

registerExecutionBlobCacheTouch((key, value) => storageCache.touchCacheEntry(key, value));

if (typeof window !== 'undefined') {
  const w = window as unknown as {
    __hamiStorageCacheCleanupInterval?: number;
  };
  if (w.__hamiStorageCacheCleanupInterval) {
